export const SYSTEM_RECIPES = [
  {"name": "Classic Buttermilk Biscuits", "category": "Baking", "description": "Tall and flaky hand-cut biscuits made with cold butter and tangy buttermilk for perfect layers.", "servings": 9, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 1/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"3/4 tsp\", \"name\": \"table salt\"}, {\"qty\": \"2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"9 tbsp\", \"name\": \"cold unsalted butter cut into small chunks\"}, {\"qty\": \"3/4 cup\", \"name\": \"cold buttermilk\"}]", "instructions": "1. Heat oven to 400°F and line a baking sheet with parchment paper. 2. Whisk flour, baking powder, baking soda, salt, and sugar together in a large bowl. 3. Work cold butter into dry ingredients with fingertips or pastry blender until mixture resembles coarse meal with pea-sized chunks. 4. Add buttermilk and stir until large craggy clumps form; knead briefly until dough just holds together. 5. Transfer dough to floured counter and pat to 3/4-inch thickness. 6. Cut rounds with a 2-inch cutter pressing straight down without twisting; re-roll scraps once. 7. Place biscuits 2 inches apart on prepared sheet and bake 12 to 15 minutes until golden brown on top. 8. Cool slightly and serve warm.", "tags": "flaky, quick, breakfast", "source": "https://smittenkitchen.com/2013/03/my-favorite-buttermilk-biscuits/", "nutritionData": "{\"calories\": 353, \"protein\": 3.0, \"carbs\": 25.0, \"fat\": 27.0}"},
  {"name": "Classic Scones", "category": "Baking", "description": "Tender wedge-shaped scones with a crisp exterior and soft crumb ready in under an hour.", "servings": 12, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"8 tbsp\", \"name\": \"cold unsalted butter cut into pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tbsp\", \"name\": \"milk for brushing\"}, {\"qty\": \"1 tbsp\", \"name\": \"coarse sparkling sugar\"}]", "instructions": "1. Preheat oven to 425°F with rack in upper third; line a baking sheet with parchment. 2. Whisk together flour, sugar, baking powder, baking soda, and salt in a large bowl. 3. Work butter into dry ingredients with fingertips until mixture is unevenly crumbly with some pea-sized pieces remaining. 4. Whisk sour cream, egg, and vanilla together; add to flour mixture and stir until dough comes together. 5. Turn dough onto a lightly floured surface and press gently into a 1-inch-thick round. 6. Cut into 6 wedges with a bench scraper; place on prepared sheet with space between them. 7. Brush tops with milk and sprinkle with coarse sugar; freeze pan 15 minutes. 8. Bake 18 to 23 minutes until light golden brown; cool briefly and serve warm.", "tags": "make-ahead, breakfast, freezer-friendly", "source": "https://www.kingarthurbaking.com/recipes/scones-recipe", "nutritionData": "{\"calories\": 194, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 10.0}"},
  {"name": "Ham and Cheddar Savory Scones", "category": "Baking", "description": "Savory scones loaded with sharp cheddar and ham with a hint of garlic and fresh chive.", "servings": 8, "prepTime": 20, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"chopped fresh chives\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"8 tbsp\", \"name\": \"frozen unsalted butter\"}, {\"qty\": \"2/3 cup\", \"name\": \"cold buttermilk\"}, {\"qty\": \"1\", \"name\": \"large egg separated\"}, {\"qty\": \"3/4 cup\", \"name\": \"finely chopped ham\"}]", "instructions": "1. Whisk flour, sugar, baking powder, garlic powder, salt, and pepper in a large bowl; stir in chives and cheddar. 2. Grate frozen butter with a box grater into flour mixture; toss to coat. 3. Whisk 2/3 cup buttermilk and egg yolk together; pour over flour mixture and add ham then mix until dough clumps together. 4. Turn onto a floured surface and press into an 8-inch disc; cut into 8 wedges. 5. Whisk egg white with 1 tbsp buttermilk; brush tops of scones. 6. Refrigerate scones on a lined baking sheet for at least 15 minutes. 7. Preheat oven to 400°F; bake scones 22 to 25 minutes until golden brown around edges. 8. Cool for a few minutes on baking sheet before serving warm.", "tags": "savory, make-ahead, breakfast", "source": "https://sallysbakingaddiction.com/ham-cheese-scones/", "nutritionData": "{\"calories\": 441, \"protein\": 10.0, \"carbs\": 26.0, \"fat\": 33.0}"},
  {"name": "Big and Bubbly Focaccia", "category": "Baking", "description": "Crispy-edged oven focaccia with an open crumb dimpled with olive oil and flaky salt.", "servings": 9, "prepTime": 30, "cookTime": 18, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"warm water\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil divided\"}, {\"qty\": \"1 tsp\", \"name\": \"flaky sea salt\"}]", "instructions": "1. Whisk together flour, salt, sugar, and yeast in a large bowl; add water and 2 tbsp olive oil and stir until no dry patches remain. 2. Cover bowl and set aside for 15 minutes; perform a bowl fold by lifting and pressing dough inward around the bowl then flip dough smooth side up. 3. Repeat bowl fold 3 more times at 15-minute intervals; cover and let dough rise at room temperature 1 hour until nearly doubled. 4. Spray a 9-inch square pan with nonstick spray; add 1 tbsp olive oil and tilt to coat. 5. Transfer dough to pan flipping it to coat in oil; cover and let rise at warm room temperature 1 to 1.5 hours until marshmallowy. 6. Preheat oven to 475°F with racks in upper and lower thirds. 7. Oil fingers and dimple dough thoroughly from edge to edge; drizzle remaining olive oil over surface and sprinkle with flaky salt. 8. Bake on lower rack 15 to 18 minutes until golden; lift out with parchment and return to oven directly on rack 5 to 7 more minutes to crisp sides.", "tags": "yeasted, savory, shareable", "source": "https://www.kingarthurbaking.com/recipes/big-and-bubbly-focaccia-recipe", "nutritionData": "{\"calories\": 245, \"protein\": 6.0, \"carbs\": 43.0, \"fat\": 5.0}"},
  {"name": "Overnight Cinnamon Rolls", "category": "Baking", "description": "Pillowy enriched dough rolls with cinnamon sugar filling and cream cheese frosting made ahead overnight.", "servings": 12, "prepTime": 45, "cookTime": 25, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"1/3 cup\", \"name\": \"light brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk warmed to 110\\u00b0F\"}, {\"qty\": \"3\", \"name\": \"large eggs room temperature\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter very soft for filling\"}, {\"qty\": \"2/3 cup\", \"name\": \"light brown sugar for filling\"}, {\"qty\": \"2 tbsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"powdered sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"whole milk for frosting\"}]", "instructions": "1. Combine flour, yeast, brown sugar, and salt in stand mixer bowl; pour in warm milk and add eggs. 2. Mix with dough hook until dough forms then add softened butter gradually and knead 8 minutes until smooth and slightly tacky. 3. Cover bowl and let rest 15 minutes; punch down and roll dough into a 14x18-inch rectangle. 4. Spread very soft butter over dough leaving a 1/2-inch border; mix brown sugar and cinnamon then sprinkle evenly over butter. 5. Roll up tightly from the long side; cut into 12 equal rolls and place in a greased 9x13-inch or round pan. 6. Cover with plastic wrap and refrigerate overnight 8 to 12 hours. 7. Remove from fridge and let rolls come to room temperature and proof for 1 to 1.5 hours until puffed. 8. Preheat oven to 350°F; bake 22 to 25 minutes until golden. 9. Beat cream cheese with powdered sugar and milk until smooth; spread over warm rolls.", "tags": "make-ahead, yeasted, indulgent", "source": "https://www.halfbakedharvest.com/overnight-cinnamon-rolls/", "nutritionData": "{\"calories\": 439, \"protein\": 7.0, \"carbs\": 65.0, \"fat\": 17.0}"},
  {"name": "Homemade Soft Pretzels", "category": "Baking", "description": "Chewy hand-shaped pretzels with a deeply golden crust from a baking soda bath.", "servings": 8, "prepTime": 30, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"3 3/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"9 cups\", \"name\": \"water for bath\"}, {\"qty\": \"1/2 cup\", \"name\": \"baking soda for bath\"}, {\"qty\": \"1\", \"name\": \"large egg beaten\"}, {\"qty\": \"\", \"name\": \"coarse pretzel salt for topping\"}]", "instructions": "1. Whisk yeast and sugar into warm water; cover and let sit 1 minute until foamy. 2. Whisk in melted butter and salt; add 3 cups flour and mix with a wooden spoon or dough hook until combined. 3. Add remaining 3/4 cup flour until dough is slightly tacky and pulls away from sides; knead 5 minutes until smooth. 4. Cover and let dough rest 10 to 30 minutes. 5. Preheat oven to 400°F; line 2 baking sheets with parchment. 6. Divide dough into 8 pieces about 75g each; roll each into a 20-to-22-inch rope and form into pretzel shape. 7. Bring baking soda and 9 cups water to a boil; drop pretzels in one at a time for 20 to 30 seconds then lift out and place on baking sheet. 8. Brush with beaten egg and sprinkle with coarse salt; bake 12 to 15 minutes until deep golden brown.", "tags": "yeasted, snack, make-ahead", "source": "https://sallysbakingaddiction.com/easy-homemade-soft-pretzels/", "nutritionData": "{\"calories\": 274, \"protein\": 7.0, \"carbs\": 45.0, \"fat\": 7.0}"},
  {"name": "Blueberry Muffins", "category": "Baking", "description": "Domed bakery-style blueberry muffins with a crunchy turbinado sugar top and yogurt-enriched crumb.", "servings": 9, "prepTime": 15, "cookTime": 28, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1\", \"name\": \"lemon zest finely grated\"}, {\"qty\": \"1 cup\", \"name\": \"plain whole milk yogurt\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"fresh blueberries\"}, {\"qty\": \"3 tbsp\", \"name\": \"turbinado sugar\"}]", "instructions": "1. Heat oven to 375°F; line a muffin tin with 9 paper liners and spray with nonstick spray. 2. Melt butter in a large bowl; whisk in granulated sugar, lemon zest, yogurt, and egg until smooth. 3. Whisk in baking powder, baking soda, and salt until fully combined. 4. Fold in flour and blueberries gently; batter will be very thick like cookie dough. 5. Divide batter between prepared cups filling nearly to top. 6. Sprinkle each muffin with 1 tsp turbinado sugar. 7. Bake 25 to 30 minutes until tops are golden and a tester inserted in center comes out clean. 8. Cool in pan for 10 minutes then transfer to a rack.", "tags": "quick, breakfast, fruit", "source": "https://smittenkitchen.com/2010/08/perfect-blueberry-muffins/", "nutritionData": "{\"calories\": 309, \"protein\": 5.0, \"carbs\": 47.0, \"fat\": 12.0}"},
  {"name": "Morning Glory Muffins", "category": "Baking", "description": "Hearty muffins packed with carrots and apple and coconut for a nourishing portable breakfast.", "servings": 12, "prepTime": 20, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"packed brown sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"raisins soaked in hot water\"}, {\"qty\": \"2 cups\", \"name\": \"peeled shredded carrots\"}, {\"qty\": \"1\", \"name\": \"large apple peeled and grated\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsweetened shredded coconut\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped walnuts\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 cup\", \"name\": \"orange juice\"}]", "instructions": "1. Preheat oven to 375°F; line a 12-cup muffin tin with papers and grease insides. 2. Cover raisins with hot water in a small bowl and set aside to soak. 3. Whisk together flour, brown sugar, baking soda, cinnamon, ginger, and salt in a large bowl. 4. Stir in carrots, apple, coconut, and walnuts. 5. Beat eggs, oil, vanilla, and orange juice together in a separate bowl. 6. Add wet ingredients to dry ingredients and stir until evenly moistened. 7. Drain raisins and fold in; divide batter among muffin cups filling nearly to the top. 8. Bake 25 to 28 minutes until nicely domed and a tester comes out clean; cool 5 minutes in pan then transfer to a rack.", "tags": "breakfast, make-ahead, wholesome", "source": "https://www.kingarthurbaking.com/recipes/morning-glory-muffins-recipe", "nutritionData": "{\"calories\": 330, \"protein\": 5.0, \"carbs\": 44.0, \"fat\": 16.0}"},
  {"name": "Maple Corn Muffins", "category": "Baking", "description": "Lightly sweet corn muffins made with real maple syrup and a tender golden crumb.", "servings": 12, "prepTime": 10, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"fine cornmeal\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/3 cup\", \"name\": \"pure maple syrup\"}, {\"qty\": \"1 tsp\", \"name\": \"maple extract\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}]", "instructions": "1. Preheat oven to 400°F; lightly grease a 12-cup standard muffin pan or line with papers. 2. Whisk together flour, cornmeal, baking powder, baking soda, and salt in a medium bowl. 3. Whisk together milk, maple syrup, maple extract, and egg in another bowl. 4. Pour liquid all at once into flour mixture and stir quickly and gently until just combined. 5. Once barely combined, stir in melted butter. 6. Scoop batter into prepared pan filling cups about 2/3 full. 7. Bake 15 to 18 minutes until a toothpick in a center muffin comes out clean and tops spring back lightly. 8. Remove from oven and transfer to a rack; serve warm or at room temperature.", "tags": "quick, savory-sweet, breakfast", "source": "https://www.kingarthurbaking.com/recipes/maple-corn-muffins-recipe", "nutritionData": "{\"calories\": 151, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 5.0}"},
  {"name": "Classic Banana Bread", "category": "Baking", "description": "Classic one-bowl banana bread with walnuts and warm spice that bakes up moist and tender.", "servings": 10, "prepTime": 20, "cookTime": 70, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"mashed very ripe bananas about 3 large\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped walnuts\"}]", "instructions": "1. Preheat oven to 325°F; lightly grease a 9x5-inch loaf pan. 2. In a large bowl stir together butter, sugar, vanilla, cinnamon, nutmeg, baking soda, baking powder, and salt vigorously for 2 to 3 minutes until smooth. 3. Add mashed bananas, honey, and eggs and stir until combined; some lumps are fine. 4. Add flour and walnuts and stir just until smooth. 5. Spoon batter into prepared pan and smooth top; let rest at room temperature for 10 minutes. 6. Bake for 45 minutes then loosely tent with foil to prevent over-browning. 7. Bake an additional 25 minutes until a toothpick inserted in center comes out with just a few moist crumbs. 8. Cool in pan for 10 minutes then turn out onto a rack to cool completely before slicing.", "tags": "quick-bread, make-ahead, freezer-friendly", "source": "https://www.kingarthurbaking.com/recipes/banana-bread-recipe", "nutritionData": "{\"calories\": 294, \"protein\": 5.0, \"carbs\": 39.0, \"fat\": 14.0}"},
  {"name": "Pumpkin Chocolate Chip Bread", "category": "Baking", "description": "Deeply spiced pumpkin loaf studded with chocolate chips and baked to a moist dense crumb.", "servings": 10, "prepTime": 15, "cookTime": 65, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 3/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"canned pumpkin puree\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"orange juice\"}, {\"qty\": \"2/3 cup\", \"name\": \"semi-sweet chocolate chips\"}]", "instructions": "1. Position oven rack in lower third and preheat to 350°F; grease a 9x5-inch metal loaf pan. 2. Whisk flour, baking soda, cinnamon, nutmeg, cloves, ginger, and salt in a large bowl. 3. Whisk eggs, granulated sugar, and brown sugar together in a medium bowl until combined. 4. Whisk in pumpkin, oil, and orange juice. 5. Pour wet ingredients into dry and mix gently with a rubber spatula until just combined with a few lumps. 6. Fold in chocolate chips then pour into prepared pan. 7. Bake 60 to 65 minutes covering loosely with foil halfway through; bread is done when a toothpick in center comes out clean. 8. Cool completely in pan on a wire rack before slicing and serving.", "tags": "quick-bread, seasonal, make-ahead", "source": "https://sallysbakingaddiction.com/pumpkin-chocolate-chip-bread/", "nutritionData": "{\"calories\": 354, \"protein\": 4.0, \"carbs\": 52.0, \"fat\": 15.0}"},
  {"name": "Simple Zucchini Bread", "category": "Baking", "description": "Warmly spiced zucchini loaf with a crunchy brown sugar top and consistently moist tender crumb.", "servings": 10, "prepTime": 20, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"2 cups\", \"name\": \"shredded unpeeled zucchini\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped walnuts\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar for topping\"}]", "instructions": "1. Preheat oven to 350°F; lightly grease an 8.5x4.5-inch loaf pan. 2. Beat together brown sugar, apple juice, oil, eggs, and vanilla in a medium bowl until smooth. 3. Whisk baking powder, baking soda, salt, and cinnamon into flour then add to wet ingredients stirring gently until smooth. 4. Gently pat shredded zucchini dry with paper towels then stir in zucchini and walnuts. 5. Scoop batter into prepared pan smoothing top; sprinkle with 1 tbsp brown sugar. 6. Bake 55 to 65 minutes until a toothpick in center comes out clean. 7. Cool in pan for 10 minutes then turn out onto a rack. 8. For best results do not slice until completely cool; store wrapped at room temperature.", "tags": "quick-bread, vegetable, make-ahead", "source": "https://www.kingarthurbaking.com/recipes/simple-zucchini-bread-recipe", "nutritionData": "{\"calories\": 292, \"protein\": 4.0, \"carbs\": 35.0, \"fat\": 16.0}"},
  {"name": "Honey Butter Cheddar Biscuits", "category": "Baking", "description": "Flaky layered cheddar biscuits baked in a skillet and finished with a warm honey garlic butter glaze.", "servings": 9, "prepTime": 20, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"8 tbsp\", \"name\": \"cold salted butter grated\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 tsp\", \"name\": \"honey\"}, {\"qty\": \"4 tbsp\", \"name\": \"salted butter for honey butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey for honey butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chopped parsley\"}, {\"qty\": \"1 pinch\", \"name\": \"sea salt for finishing\"}]", "instructions": "1. Preheat oven to 425°F; rub a 10-inch cast iron skillet with butter. 2. Combine flour, baking powder, garlic powder, and salt in a bowl; mix in grated butter and cheddar with hands until combined. 3. Pour in milk and honey and mix until just combined. 4. Turn dough onto a floured surface and pat into a 1-inch-thick rectangle; fold one side in like a letter then fold other side over; repeat fold once more. 5. Cut into 3-inch rounds with a biscuit cutter; re-roll scraps and cut more. 6. Arrange biscuits in prepared skillet and brush tops with milk. 7. Bake 20 to 22 minutes until golden brown. 8. Melt 4 tbsp butter with honey and parsley; spoon over warm biscuits and sprinkle with sea salt.", "tags": "savory, quick, crowd-pleaser", "source": "https://www.halfbakedharvest.com/cheddar-biscuits/", "nutritionData": "{\"calories\": 318, \"protein\": 7.0, \"carbs\": 24.0, \"fat\": 22.0}"},
  {"name": "Fruit Galette", "category": "Baking", "description": "Rustic free-form tart with a buttery yogurt pastry crust and a jammy seasonal fruit filling.", "servings": 6, "prepTime": 30, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"8 tbsp\", \"name\": \"cold unsalted butter cut into pieces\"}, {\"qty\": \"1/4 cup\", \"name\": \"plain yogurt or sour cream\"}, {\"qty\": \"3 tbsp\", \"name\": \"cold water\"}, {\"qty\": \"3 1/2 cups\", \"name\": \"seasonal fruit berries or stone fruit sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar for filling\"}, {\"qty\": \"1 tbsp\", \"name\": \"tapioca starch\"}, {\"qty\": \"1 pinch\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"juice of half a lemon\"}, {\"qty\": \"1\", \"name\": \"large egg beaten with 1 tsp water\"}, {\"qty\": \"2 tbsp\", \"name\": \"turbinado sugar\"}]", "instructions": "1. Combine flour, salt, and sugar in a large bowl; cut in cold butter with a pastry blender until pieces resemble small peas. 2. Stir in yogurt and 3 tbsp cold water until large clumps form; add last tbsp water if needed. 3. Bring dough together into a flat disc on parchment; wrap and chill in fridge 1 to 2 hours until firm. 4. Combine fruit, sugar, tapioca starch, salt, and lemon juice in a bowl and toss. 5. Heat oven to 400°F; roll dough on floured counter into a 14-inch round and transfer on parchment to a baking sheet. 6. Spoon filling into center leaving a 2 to 3 inch border; fold border over fruit pleating as needed. 7. Brush crust with egg wash and sprinkle turbinado sugar over crust and fruit. 8. Bake 30 to 35 minutes until golden all over and fruit is bubbling; cool at least 20 minutes before serving.", "tags": "rustic, seasonal, make-ahead", "source": "https://smittenkitchen.com/2020/05/any-kind-of-fruit-galette/", "nutritionData": "{\"calories\": 363, \"protein\": 5.0, \"carbs\": 47.0, \"fat\": 18.0}"},
  {"name": "Zucchini Ricotta Galette", "category": "Baking", "description": "Savory free-form tart with a creamy ricotta base topped with thinly sliced zucchini and fresh basil.", "servings": 6, "prepTime": 40, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"8 tbsp\", \"name\": \"cold unsalted butter cut into cubes\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"cold water\"}, {\"qty\": \"1\", \"name\": \"large zucchini sliced 1/4-inch thick\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk ricotta\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"1\", \"name\": \"large egg yolk\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh basil thinly sliced\"}]", "instructions": "1. Whisk flour and salt in a large bowl; cut in cold butter until mixture resembles coarse meal. 2. Whisk sour cream, lemon juice, and water together; stir into flour mixture until large lumps form. 3. Gather into a disc wrap in parchment and chill 1 to 2 hours. 4. Spread zucchini slices on paper towels; salt and let drain 30 minutes then blot dry. 5. Whisk olive oil and garlic; mix ricotta, Parmesan, mozzarella, and 1 tsp garlic oil; season with salt and pepper. 6. Heat oven to 400°F; roll dough on floured surface into a 12-inch round and transfer to parchment-lined baking sheet. 7. Spread ricotta mixture over dough leaving a 2-inch border; shingle zucchini in concentric circles; drizzle remaining garlic oil over top. 8. Fold border over filling pleating edges; brush crust with egg yolk glaze; bake 30 to 40 minutes until golden. 9. Sprinkle with basil; let stand 5 minutes then slide onto serving plate.", "tags": "savory, vegetarian, rustic", "source": "https://smittenkitchen.com/2010/06/zucchini-and-ricotta-galette/", "nutritionData": "{\"calories\": 353, \"protein\": 7.0, \"carbs\": 23.0, \"fat\": 26.0}"},
  {"name": "Homemade Croissants", "category": "Baking", "description": "Buttery laminated pastry croissants with dozens of flaky layers shaped and baked golden over two days.", "servings": 16, "prepTime": 120, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"whole milk warmed to 110\\u00b0F\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2 cups\", \"name\": \"unsalted butter cold for lamination\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour for butter layer\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tbsp\", \"name\": \"whole milk for egg wash\"}]", "instructions": "1. Combine flour, sugar, salt, and yeast in stand mixer bowl with dough hook; add softened butter then slowly pour in warm milk and knead on medium 3 minutes until smooth. 2. Shape dough into a rectangle; wrap and refrigerate at least 1 hour or overnight. 3. Beat cold butter with 2 tbsp flour until smooth; flatten into an 8x5-inch rectangle between parchment; chill 30 minutes. 4. Roll dough into a 10x20-inch rectangle; place butter block in center and fold dough over enclosing it completely. 5. Roll into a large rectangle; fold into thirds like a letter (1st turn); wrap and refrigerate 30 minutes. 6. Repeat rolling and folding 2 more times with 30-minute rests between; refrigerate 4 hours or overnight. 7. Roll dough into an 8x20-inch rectangle; cut into 16 triangles and roll each from wide end to point; curve ends inward. 8. Place on lined baking sheets; let proof at room temperature 1 hour then refrigerate 1 hour. 9. Preheat oven to 400°F; brush croissants with egg wash; bake 20 minutes until deep golden brown.", "tags": "laminated, yeasted, weekend-project", "source": "https://sallysbakingaddiction.com/homemade-croissants/", "nutritionData": "{\"calories\": 378, \"protein\": 5.0, \"carbs\": 29.0, \"fat\": 27.0}"},
  {"name": "Homemade Bagels", "category": "Baking", "description": "Dense chewy New York-style bagels boiled in a honey water bath and baked until dark golden.", "servings": 8, "prepTime": 30, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"plus 2 tbsp warm water\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1 tbsp\", \"name\": \"barley malt syrup or sugar\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"quarts water for water bath\"}, {\"qty\": \"1 tbsp\", \"name\": \"barley malt syrup or honey for water bath\"}, {\"qty\": \"1\", \"name\": \"large egg beaten for egg wash\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds or poppy seeds for topping\"}]", "instructions": "1. Whisk warm water, yeast, and barley malt syrup together in stand mixer bowl; let sit 5 minutes until foamy. 2. Add flour and salt; beat with dough hook on medium speed 2 minutes until stiff dough forms; knead 6 to 7 minutes. 3. Place dough in a greased bowl; cover and let rise 1.5 to 2 hours until doubled. 4. Punch down dough and divide into 8 equal pieces; shape each into a ball then poke a hole through center and stretch to 1.5-to-2-inch diameter. 5. Let shaped bagels rest 5 to 10 minutes; preheat oven to 425°F and line 2 baking sheets. 6. Bring 2 quarts water with barley malt syrup to a boil; drop 2 to 3 bagels at a time and boil 1 minute per side. 7. Lift out with a slotted spatula; brush with egg wash and dip tops in seeds. 8. Bake 20 to 25 minutes rotating pans halfway until bagels are dark golden brown; cool on sheets 20 minutes.", "tags": "yeasted, breakfast, make-ahead", "source": "https://sallysbakingaddiction.com/homemade-bagels/", "nutritionData": "{\"calories\": 194, \"protein\": 5.0, \"carbs\": 39.0, \"fat\": 1.0}"},
  {"name": "English Muffins", "category": "Baking", "description": "Griddle-cooked yeasted muffins with signature nooks and crannies perfect for toasting.", "servings": 6, "prepTime": 30, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"bread flour for preferment\"}, {\"qty\": \"1/2 tsp\", \"name\": \"instant yeast for preferment\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk for preferment\"}, {\"qty\": \"1/4 cup\", \"name\": \"water for preferment\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"\", \"name\": \"cornmeal for dusting\"}]", "instructions": "1. Make preferment by whisking together bread flour, yeast, milk, and water until smooth; cover and rest at room temperature 1 to 4 hours until bubbly. 2. Add flour, salt, sugar, and butter to preferment and mix by hand into a soft sticky dough. 3. Perform bowl folds reaching under dough and stretching up and over; flip smooth side up and round; cover and rest 1 hour. 4. Perform another bowl fold; cover and rest 1 more hour until very puffy. 5. Turn dough onto a cornmeal-dusted surface; gently deflate and pat into a 1/2-inch-thick circle. 6. Cut into 3.5-inch rounds with a cutter; gather scraps and cut again to yield 6 muffins; dust tops with cornmeal and let rest 20 to 30 minutes until puffy. 7. Heat a cast iron skillet over medium-low; cook muffins undisturbed 10 to 15 minutes per side until bottoms are lightly browned and sides look matte. 8. Cool completely then fork-split before toasting and serving with butter.", "tags": "yeasted, breakfast, make-ahead", "source": "https://www.kingarthurbaking.com/recipes/english-muffins-recipe", "nutritionData": "{\"calories\": 340, \"protein\": 8.0, \"carbs\": 59.0, \"fat\": 8.0}"},
  {"name": "Popovers", "category": "Baking", "description": "Dramatic hollow egg-based rolls with a crisp golden shell and airy steam-puffed interior.", "servings": 6, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened for serving\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey or maple syrup for serving\"}]", "instructions": "1. Preheat oven to 450°F with rack on a lower shelf; grease all 12 cups and surrounding surface of a standard muffin tin. 2. Whisk eggs, milk, and salt together until smooth and evenly yellow with no streaks. 3. Add flour all at once and beat with a wire whisk until frothy and mostly smooth; stir in melted butter. 4. Let batter rest 15 minutes; whisk briefly again to recombine any lumps. 5. Pour batter into greased muffin cups filling 2/3 to 3/4 full; place pan on lower oven rack. 6. Bake at 450°F for 20 minutes without opening the oven door. 7. Reduce heat to 350°F and bake an additional 10 to 15 minutes until deep golden brown. 8. Pierce top of each popover with a knife tip to release steam; remove from pan and serve immediately.", "tags": "quick, impressive, breakfast", "source": "https://www.kingarthurbaking.com/recipes/popovers-recipe", "nutritionData": "{\"calories\": 197, \"protein\": 6.0, \"carbs\": 21.0, \"fat\": 10.0}"},
  {"name": "Pita Bread", "category": "Baking", "description": "Soft golden pita rounds that puff dramatically in a hot oven to create a perfect pocket.", "servings": 8, "prepTime": 20, "cookTime": 5, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}]", "instructions": "1. Dissolve yeast and sugar in 1 cup warm water; let sit 5 to 10 minutes until foamy. 2. Combine flour and salt in a large bowl; add yeast mixture and olive oil and stir until a shaggy dough forms. 3. Knead on a floured surface for 8 to 10 minutes until smooth and elastic; add water 1 tbsp at a time if dough is too stiff. 4. Place dough in a greased bowl; cover and let rise 1 to 1.5 hours at warm room temperature until doubled. 5. Punch down dough and divide into 8 equal pieces; roll each into a smooth ball then flatten into a 6-inch round about 1/4-inch thick. 6. Let rounds rest on a floured surface for 20 minutes covered with a towel. 7. Preheat oven to 500°F with a baking stone or inverted baking sheet on the middle rack for at least 30 minutes. 8. Bake pita rounds in batches for 3 to 5 minutes until puffed and just lightly colored; wrap in a towel to keep soft.", "tags": "yeasted, savory, make-ahead", "source": "https://www.kingarthurbaking.com/recipes/golden-pita-bread-recipe", "nutritionData": "{\"calories\": 188, \"protein\": 5.0, \"carbs\": 36.0, \"fat\": 2.0}"},
  {"name": "Oatmeal Raisin Cookies", "category": "Baking", "description": "Classic chewy oatmeal cookies with golden raisins and a hint of cinnamon and nutmeg.", "servings": 50, "prepTime": 15, "cookTime": 13, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"16 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"packed brown sugar\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3 cups\", \"name\": \"old-fashioned rolled oats\"}, {\"qty\": \"1 cup\", \"name\": \"golden raisins\"}]", "instructions": "1. Preheat oven to 350°F; line two baking sheets with parchment. 2. Beat butter, granulated sugar, brown sugar, vanilla, cinnamon, nutmeg, salt, and vinegar until fairly smooth. 3. Beat in egg until smooth. 4. Add baking soda and flour and beat until well incorporated. 5. Stir in oats and raisins until evenly combined. 6. Drop rounded tablespoons of dough onto prepared baking sheets leaving 2 inches between cookies. 7. Bake 12 to 14 minutes rotating pans halfway through until light golden brown with slightly darker edges. 8. Sprinkle lightly with salt immediately from oven; cool on pan then transfer to a rack.", "tags": "classic, make-ahead, freezer-friendly", "source": "https://www.kingarthurbaking.com/recipes/oatmeal-cookies-recipe", "nutritionData": "{\"calories\": 108, \"protein\": 2.0, \"carbs\": 16.0, \"fat\": 4.0}"},
  {"name": "Soft Dinner Rolls", "category": "Baking", "description": "Pillowy pull-apart yeasted dinner rolls brushed with honey butter and baked until golden.", "servings": 12, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"2 tsp\", \"name\": \"honey\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1\", \"name\": \"large egg yolk\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"3 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted for brushing\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey for brushing\"}]", "instructions": "1. Whisk 1/4 cup warm milk, yeast, and 1 tsp honey in stand mixer bowl; cover and let sit 5 to 10 minutes until foamy. 2. Add remaining honey, egg, egg yolk, 4 tbsp melted butter, 3 cups flour, salt, and 3/4 cup warm milk; mix with dough hook on low 1 minute then add remaining 1/2 cup flour. 3. Mix on low 1 minute then increase to medium-low and knead 8 minutes until soft and slightly tacky dough forms. 4. Shape into a ball in a greased bowl; cover and let rise 1 to 1.5 hours at warm room temperature until doubled. 5. Punch down dough and divide into 12 equal pieces; shape each into a smooth ball. 6. Arrange balls in a greased 9x13-inch baking dish; cover and let rise 45 minutes until puffed and touching. 7. Preheat oven to 350°F; bake rolls 18 to 22 minutes until tops are golden brown. 8. Stir 2 tbsp melted butter with 1 tbsp honey and brush over warm rolls; serve immediately.", "tags": "yeasted, holiday, crowd-pleaser", "source": "https://sallysbakingaddiction.com/soft-dinner-rolls/", "nutritionData": "{\"calories\": 215, \"protein\": 5.0, \"carbs\": 31.0, \"fat\": 7.0}"},
  {"name": "Shortbread Cookies", "category": "Baking", "description": "Crisp buttery shortbread with a melt-in-the-mouth texture from a simple four-ingredient dough.", "servings": 24, "prepTime": 15, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"16 tbsp\", \"name\": \"cold unsalted butter cubed\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"coarse sugar for sprinkling\"}]", "instructions": "1. Preheat oven to 325°F; line two baking sheets with parchment. 2. Whisk flour, powdered sugar, and salt together in a food processor; add cold butter and vanilla. 3. Pulse until dough just comes together into a ball that holds when squeezed. 4. Turn dough onto a lightly floured surface; roll to 1/4-inch thickness. 5. Cut into rectangles or rounds with a cookie cutter or knife; place on prepared baking sheets 1 inch apart. 6. Sprinkle with coarse sugar and refrigerate for 15 minutes. 7. Bake 16 to 18 minutes until edges are just barely golden; centers should look pale. 8. Cool completely on baking sheets before transferring; cookies firm up as they cool.", "tags": "classic, make-ahead, holiday", "source": "Classic", "nutritionData": "{\"calories\": 116, \"protein\": 1.0, \"carbs\": 11.0, \"fat\": 8.0}"},
  {"name": "Flaky All-Butter Pie Crust", "category": "Baking", "description": "Shatteringly crisp pie crust made by smashing cold butter flat into flour for incredible flaky layers.", "servings": 2, "prepTime": 20, "cookTime": 0, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 1/3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"cold unsalted butter cubed\"}, {\"qty\": \"1/4 cup\", \"name\": \"cold water\"}, {\"qty\": \"2 tbsp\", \"name\": \"cold vodka or additional water\"}, {\"qty\": \"1\", \"name\": \"large egg beaten with 1 tsp water for egg wash\"}]", "instructions": "1. Whisk flour, sugar, and salt together in a medium bowl. 2. Toss cold butter cubes into flour mixture to coat; using fingertips smash each cube flat without rubbing or cutting. 3. Stir in cold water until dough comes together into a shaggy ball; dough temperature should be 65 to 70°F. 4. On a generously floured surface roll dough into a roughly 10x15-inch rectangle. 5. Fold the 10-inch sides to the center then close like a book; fold in half again bringing short sides together to create a thick block. 6. Divide in half with a bench scraper; flatten each half into a disc. 7. Wrap each disc in plastic wrap and refrigerate at least 1 hour or up to 3 days before rolling. 8. Roll out as needed on a floured surface to 1/8-inch thickness; fit into pie plate and crimp edges before filling and baking.", "tags": "make-ahead, classic, technique", "source": "Classic", "nutritionData": "{\"calories\": 1405, \"protein\": 19.0, \"carbs\": 117.0, \"fat\": 96.0}"},
  {"name": "Quiche Lorraine", "category": "Baking", "description": "Classic French custard quiche with caramelized leeks, ham, and Gruyere in a buttery pastry shell.", "servings": 8, "prepTime": 45, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"cornstarch\"}, {\"qty\": \"8 tbsp\", \"name\": \"cold unsalted butter cut into small pieces\"}, {\"qty\": \"1\", \"name\": \"large egg for pastry\"}, {\"qty\": \"4\", \"name\": \"leeks white and pale green parts thinly sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 oz\", \"name\": \"sliced ham finely chopped\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Gruyere cheese\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"sour cream\"}, {\"qty\": \"3\", \"name\": \"large eggs for filling\"}, {\"qty\": \"1 pinch\", \"name\": \"nutmeg\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Combine flour, cornstarch, and 1/4 tsp salt in a bowl; cut butter in until very tiny bits form then mix in 1 egg until dough forms. 2. On a floured surface roll dough into a 12-inch circle; fit into a 9-inch pie plate crimp edges and refrigerate 30 minutes. 3. Saute leeks in olive oil over low heat 30 to 40 minutes until caramelized; remove from heat and cool. 4. Preheat oven to 350°F. 5. Mix heavy cream and sour cream together; whisk in 3 eggs and season with nutmeg, salt, and pepper. 6. Spread leek mixture evenly over pastry shell; scatter ham then cheese over leeks. 7. Pour custard over filling; bake in upper third of oven 25 to 30 minutes until puffed and golden. 8. Remove from oven; cool on rack for 10 minutes before slicing and serving warm or at room temperature.", "tags": "savory, classic, make-ahead", "source": "https://smittenkitchen.com/2009/10/quiche-lorraine/", "nutritionData": "{\"calories\": 487, \"protein\": 14.0, \"carbs\": 23.0, \"fat\": 38.0}"},
  {"name": "Chocolate Chip Cookies", "category": "Baking", "description": "Brown butter chocolate chip cookies with crisp edges and a thick chewy center.", "servings": 24, "prepTime": 20, "cookTime": 14, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 1/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"packed dark brown sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 cups\", \"name\": \"chopped bittersweet chocolate or chips\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for finishing\"}]", "instructions": "1. Brown butter in a large saucepan over medium heat until golden and nutty-smelling; remove from heat and let cool until solidified but not hard about 1 hour in fridge. 2. Preheat oven to 375°F; line baking sheets with parchment. 3. Whisk flour, baking soda, and salt together in a medium bowl. 4. Beat cooled brown butter with granulated and brown sugars in stand mixer until fluffy; add eggs one at a time then beat in vanilla. 5. Add flour mixture and mix on low until just combined; fold in chocolate. 6. Scoop rounded tablespoons of dough onto prepared baking sheets leaving 2 inches between. 7. Bake 12 to 14 minutes until golden around edges but still slightly soft in centers. 8. Sprinkle with flaky salt immediately; cool on baking sheet 5 minutes then transfer to rack.", "tags": "classic, crowd-pleaser, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 231, \"protein\": 2.0, \"carbs\": 30.0, \"fat\": 12.0}"},
  {"name": "Soft Sandwich Bread", "category": "Baking", "description": "Tender everyday sandwich loaf with a fine crumb from enriched dough and a glossy golden crust.", "servings": 12, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter melted for brushing\"}]", "instructions": "1. Whisk warm milk, yeast, and honey in stand mixer bowl; let sit 5 minutes until foamy. 2. Add flour, salt, softened butter, and egg; knead with dough hook on medium speed for 8 minutes until smooth and slightly tacky. 3. Shape into a ball in a greased bowl; cover and let rise at warm room temperature 1 to 1.5 hours until doubled. 4. Punch down dough and shape into a log; press into a greased 9x5-inch loaf pan. 5. Cover and let rise 45 to 60 minutes until dough crowns 1 inch above pan rim. 6. Preheat oven to 350°F; brush top of loaf gently with melted butter. 7. Bake 28 to 32 minutes until golden brown and loaf sounds hollow when tapped; internal temperature should read 190°F. 8. Turn out onto a wire rack and cool completely before slicing.", "tags": "yeasted, classic, everyday", "source": "Classic", "nutritionData": "{\"calories\": 168, \"protein\": 4.0, \"carbs\": 28.0, \"fat\": 4.0}"},
  {"name": "Classic Cornbread", "category": "Baking", "description": "Moist golden cornbread with a tender crumb baked in a cast iron skillet until lightly crisp at edges.", "servings": 9, "prepTime": 10, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"yellow cornmeal\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1\", \"name\": \"large egg\"}]", "instructions": "1. Preheat oven to 375°F; lightly grease a 9-inch square pan or cast iron skillet. 2. Whisk together flour, cornmeal, sugar, baking powder, baking soda, and salt in a medium bowl. 3. Whisk together milk, melted butter, vegetable oil, and egg in another bowl. 4. Pour liquid ingredients all at once into dry ingredients and stir quickly and gently just until combined; do not overmix. 5. Spread batter into prepared pan. 6. Bake 20 to 25 minutes until edges begin to pull away from pan and a toothpick inserted in center comes out clean. 7. Remove from oven and cool on a rack for 5 minutes. 8. Cut into squares and serve warm; store leftovers wrapped at room temperature.", "tags": "quick, savory-sweet, classic", "source": "https://www.kingarthurbaking.com/recipes/cornbread-recipe", "nutritionData": "{\"calories\": 212, \"protein\": 4.0, \"carbs\": 26.0, \"fat\": 10.0}"},
  {"name": "Chocolate Chunk Coconut Banana Bread", "category": "Baking", "description": "Moist banana bread made with coconut oil and honey and loaded with dark chocolate chunks throughout.", "servings": 10, "prepTime": 15, "cookTime": 55, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"medium very ripe bananas mashed about 1 1/4 cups\"}, {\"qty\": \"1/4 cup\", \"name\": \"melted coconut oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"honey\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"semi-sweet or dark chocolate chunks\"}]", "instructions": "1. Preheat oven to 350°F; grease a 9x5-inch loaf pan. 2. In a large bowl stir together mashed bananas, coconut oil, honey, eggs, and vanilla until combined. 3. Add flour, baking soda, cinnamon, and salt and mix until just combined; do not overmix. 4. Fold in chocolate chunks. 5. Pour batter into prepared pan. 6. Bake 50 to 60 minutes until center is just set and a toothpick inserted in the middle comes out clean. 7. Remove from oven and let cool in pan for at least 30 minutes before cutting. 8. Serve warm with a smear of butter or drizzle of honey.", "tags": "quick-bread, dairy-free, make-ahead", "source": "https://www.halfbakedharvest.com/chocolate-chunk-coconut-banana-bread/", "nutritionData": "{\"calories\": 280, \"protein\": 4.0, \"carbs\": 43.0, \"fat\": 12.0}"},
  {"name": "Cream Biscuits", "category": "Baking", "description": "Ultra-simple heavy cream biscuits with just four ingredients that bake up golden and tender in minutes.", "servings": 10, "prepTime": 10, "cookTime": 14, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted for dipping\"}]", "instructions": "1. Preheat oven to 425°F; line a baking sheet with parchment paper. 2. Sift flour, baking powder, salt, and sugar into a large bowl. 3. Fold in 1 1/4 cups heavy cream until dough is soft and just holds together; add remaining cream 1 tbsp at a time if dough is too dry. 4. Turn dough onto a floured surface and press to a thickness of about 3/4 inch. 5. Cut rounds with a 2.5-inch round cutter; gather scraps gently and cut more rounds. 6. Melt butter in a small dish; dip the top of each round in melted butter then place butter side up on prepared baking sheet. 7. Bake 12 to 15 minutes until golden brown. 8. Serve immediately or flash freeze unbaked rounds for future baking.", "tags": "quick, 4-ingredient, breakfast", "source": "https://smittenkitchen.com/2009/12/cream-biscuits/", "nutritionData": "{\"calories\": 248, \"protein\": 4.0, \"carbs\": 21.0, \"fat\": 17.0}"},
  {"name": "Classic White Sandwich Bread", "category": "Bread Machine", "description": "Soft and fluffy white sandwich bread baked to golden perfection in the bread machine on the Basic cycle.", "servings": 16, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3 1/4 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add water and oil to the bread machine pan. 2. Add salt and sugar. 3. Spoon in the bread flour on top covering the liquid completely. 4. Make a small well in the flour and add the yeast making sure it does not touch the salt. 5. Insert pan into machine and select Basic/White cycle for a 1.5 lb loaf with medium crust. 6. When cycle is complete remove pan with oven mitts and shake loaf out onto a wire rack. 7. Cool at least 30 minutes before slicing.", "tags": "bread machine, sandwich bread, white bread, classic", "source": "https://www.kingarthurbaking.com/recipes/easy-bread-machine-bread-recipe", "nutritionData": "{\"calories\": 114, \"protein\": 3.0, \"carbs\": 21.0, \"fat\": 2.0}"},
  {"name": "100% Whole Wheat Bread", "category": "Bread Machine", "description": "Hearty whole wheat loaf made entirely with whole wheat flour on the Whole Wheat cycle.", "servings": 16, "prepTime": 10, "cookTime": 210, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"vital wheat gluten\"}, {\"qty\": \"3 cups\", \"name\": \"whole wheat flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water honey and butter to the bread machine pan. 2. Add salt and vital wheat gluten. 3. Spoon whole wheat flour on top of the liquids. 4. Make a small well in the flour and add the yeast keeping it away from the salt. 5. Select the Whole Wheat cycle for a 1.5 lb loaf with medium crust and press Start. 6. Check dough after 10 minutes of kneading and add water or flour 1 tbsp at a time if needed. 7. When baking cycle completes remove loaf and cool on a wire rack for 1 hour before slicing.", "tags": "bread machine, whole wheat, healthy, high-fiber", "source": "https://www.kingarthurbaking.com/recipes/100-whole-wheat-bread-for-the-bread-machine-recipe", "nutritionData": "{\"calories\": 102, \"protein\": 4.0, \"carbs\": 19.0, \"fat\": 2.0}"},
  {"name": "Bread Machine Sourdough Bread", "category": "Bread Machine", "description": "Tangy sourdough-style bread using active starter made on the French Bread cycle for a long slow rise.", "servings": 16, "prepTime": 15, "cookTime": 240, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"active sourdough starter\"}, {\"qty\": \"1/2 cup\", \"name\": \"warm water\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add sourdough starter and warm water to the bread machine pan. 2. Add salt and sugar on top of the liquid. 3. Spoon bread flour over the liquids covering them completely. 4. Make a small indent in the flour and add yeast. 5. Select the French Bread cycle or a similar long-rising cycle on your machine and press Start. 6. Check dough consistency after 10 minutes of kneading and adjust with water or flour as needed. 7. Remove loaf when cycle finishes and cool completely on a wire rack before slicing.", "tags": "bread machine, sourdough, French cycle, tangy", "source": "https://www.kingarthurbaking.com/recipes/bread-machine-sourdough-bread-recipe", "nutritionData": "{\"calories\": 104, \"protein\": 3.0, \"carbs\": 22.0, \"fat\": 0.0}"},
  {"name": "French Bread", "category": "Bread Machine", "description": "Crusty classic French bread made in the bread machine using the Basic cycle with a crackly crust.", "servings": 12, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"2\", \"name\": \"egg whites\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Beat egg whites with a whisk for 2 to 3 minutes until frothy and bubbly. 2. Pour beaten egg whites and water into the bread machine pan. 3. Add flour on top covering the liquid completely. 4. Make a small well in flour and add sugar and salt on one side and yeast on the opposite side. 5. Select Basic White cycle with medium crust and press Start. 6. Watch the first few minutes of kneading; add 1 tbsp water if dough is dry or 1 tbsp flour if too wet. 7. Allow machine to complete cycle then remove loaf and cool on a wire rack at least 30 minutes before slicing.", "tags": "bread machine, French bread, crusty, classic", "source": "https://adamantkitchen.com/bread-machine-french-bread/", "nutritionData": "{\"calories\": 120, \"protein\": 4.0, \"carbs\": 25.0, \"fat\": 0.0}"},
  {"name": "Honey Oat Bread", "category": "Bread Machine", "description": "Lightly sweet honey oat bread made with old-fashioned rolled oats on the Basic cycle.", "servings": 14, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"1/4 cup\", \"name\": \"milk\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"3/4 cup\", \"name\": \"old-fashioned rolled oats\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water milk honey and butter to the bread machine pan. 2. Add salt then spoon flour on top of the liquid ingredients. 3. Add rolled oats on top of the flour. 4. Make a small well in the flour mixture and add yeast keeping it away from salt. 5. Select Basic White cycle for a 1.5 lb loaf with medium crust and press Start. 6. Check dough ball after 5 minutes of kneading and add water or flour as needed. 7. When cycle is complete remove loaf and cool on a wire rack before slicing.", "tags": "bread machine, honey oat, oatmeal, soft", "source": "https://adamantkitchen.com/bread-machine-honey-oat-bread/", "nutritionData": "{\"calories\": 131, \"protein\": 3.0, \"carbs\": 24.0, \"fat\": 2.0}"},
  {"name": "Cinnamon Raisin Bread", "category": "Bread Machine", "description": "Sweet cinnamon-scented bread studded with plump raisins perfect for breakfast toast.", "servings": 14, "prepTime": 15, "cookTime": 200, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"warm milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"1 cup\", \"name\": \"raisins\"}]", "instructions": "1. Add warm milk water butter eggs and vanilla to the bread machine pan. 2. Spoon flour on top of the liquid ingredients. 3. Add sugar cinnamon and salt and make a small well for the yeast in the flour keeping salt and yeast separated. 4. Select Basic or Sweet cycle for a 1.5 lb loaf and press Start. 5. Add raisins when the machine beeps during the mix-in phase or about 5 minutes before the end of the second kneading cycle. 6. When cycle is complete remove pan with oven mitts and turn loaf out onto a wire rack. 7. Cool completely before slicing for best texture.", "tags": "bread machine, cinnamon raisin, sweet, breakfast", "source": "https://www.kingarthurbaking.com/recipes/cinnamon-raisin-bread-recipe", "nutritionData": "{\"calories\": 175, \"protein\": 4.0, \"carbs\": 33.0, \"fat\": 3.0}"},
  {"name": "Rye Bread with Caraway", "category": "Bread Machine", "description": "Earthy caraway rye bread with a hearty crumb made on the Basic or Rye cycle in the bread machine.", "servings": 14, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"molasses\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"dark rye flour\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"caraway seeds\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"instant yeast\"}]", "instructions": "1. Add water olive oil and molasses to the bread machine pan. 2. Add salt then spoon rye flour and all-purpose flour on top. 3. Sprinkle caraway seeds over the flour. 4. Make a small well in the flour and add yeast. 5. Select the Rye Bread setting or Whole Wheat setting for a 1.5 lb loaf and press Start. 6. Allow machine to complete all cycles. 7. Remove loaf from pan and cool on a wire rack for at least 30 minutes before slicing.", "tags": "bread machine, rye, caraway, hearty", "source": "https://littlesunnykitchen.com/bread-machine-rye-bread-recipe/", "nutritionData": "{\"calories\": 128, \"protein\": 3.0, \"carbs\": 24.0, \"fat\": 2.0}"},
  {"name": "Multigrain Seeded Loaf", "category": "Bread Machine", "description": "Nutty multigrain bread packed with seeds and whole grains baked on the Whole Wheat cycle.", "servings": 14, "prepTime": 15, "cookTime": 210, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 cup\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"2 tbsp\", \"name\": \"flaxseed\"}, {\"qty\": \"2 tbsp\", \"name\": \"sunflower seeds\"}, {\"qty\": \"2 tbsp\", \"name\": \"millet\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water olive oil and honey to the bread machine pan. 2. Add salt then spoon bread flour and whole wheat flour on top. 3. Add oats flaxseed sunflower seeds and millet on top of the flour. 4. Make a small well in the flour and add yeast. 5. Select Whole Wheat cycle for a 1.5 lb loaf with medium crust and press Start. 6. After 10 minutes of kneading check dough consistency and add water or flour 1 tbsp at a time as needed. 7. Cool loaf completely on a wire rack before slicing.", "tags": "bread machine, multigrain, seeded, whole grain", "source": "Classic", "nutritionData": "{\"calories\": 137, \"protein\": 4.0, \"carbs\": 23.0, \"fat\": 4.0}"},
  {"name": "Italian Herb and Olive Oil Bread", "category": "Bread Machine", "description": "Fragrant Italian herb bread made with olive oil rosemary and garlic on the Basic cycle.", "servings": 14, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/8 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water and olive oil to the bread machine pan. 2. Add salt garlic powder and dried herbs. 3. Spoon bread flour on top then add sugar. 4. Make a small well in the flour and add yeast keeping it away from the salt. 5. Select Basic/White cycle for a 1.5 lb loaf with medium crust and press Start. 6. Check dough ball after 5 minutes of kneading and adjust hydration if needed. 7. Remove baked loaf and cool on a wire rack at least 30 minutes before slicing.", "tags": "bread machine, Italian herb, olive oil, savory", "source": "Classic", "nutritionData": "{\"calories\": 117, \"protein\": 3.0, \"carbs\": 21.0, \"fat\": 2.0}"},
  {"name": "Pumpernickel Dark Rye Bread", "category": "Bread Machine", "description": "Rich dark pumpernickel bread with molasses and cocoa powder made on the Basic cycle.", "servings": 14, "prepTime": 10, "cookTime": 180, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"4 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 cup\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1 cup\", \"name\": \"dark rye flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"instant coffee\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water and oil to the bread machine pan. 2. Add salt and brown sugar. 3. Spoon bread flour whole wheat flour and dark rye flour on top. 4. Add cocoa powder and instant coffee over the flour. 5. Make a small well in the flour and add yeast. 6. Select Basic cycle for a 1.5 lb loaf with medium crust and press Start. 7. Once baking cycle is complete remove loaf from pan and cool completely on a wire rack before slicing.", "tags": "bread machine, pumpernickel, dark rye, molasses", "source": "https://culinaryshades.com/bread-machine-pumpernickel-bread/", "nutritionData": "{\"calories\": 134, \"protein\": 4.0, \"carbs\": 27.0, \"fat\": 2.0}"},
  {"name": "Gluten-Free White Bread", "category": "Bread Machine", "description": "Light and fluffy gluten-free white bread made with gluten-free bread flour on the Gluten-Free cycle.", "servings": 12, "prepTime": 10, "cookTime": 130, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water about 110\\u00b0F\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"gluten-free bread flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"butter melted\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"instant yeast\"}]", "instructions": "1. Add warm water melted butter eggs and apple cider vinegar to the bread machine pan. 2. Whisk together gluten-free flour sugar salt and yeast in a bowl. 3. Add the dry ingredient mixture on top of the liquid ingredients without stirring. 4. Select Gluten-Free cycle or Basic cycle with dark crust setting and press Start. 5. Allow machine to complete the full cycle without opening the lid. 6. Remove pan with oven mitts and turn loaf out onto a wire rack. 7. Cool completely before slicing for best texture and structure.", "tags": "bread machine, gluten-free, white bread, easy", "source": "https://www.seasonalcravings.com/gluten-free-white-bread-machine-bread/", "nutritionData": "{\"calories\": 162, \"protein\": 3.0, \"carbs\": 25.0, \"fat\": 6.0}"},
  {"name": "Banana Bread", "category": "Bread Machine", "description": "Moist and tender banana bread made with ripe bananas using the bread machine on the Quick Bread cycle.", "servings": 10, "prepTime": 10, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"ripe bananas mashed\"}, {\"qty\": \"1/3 cup\", \"name\": \"butter melted\"}, {\"qty\": \"3/4 cup\", \"name\": \"sugar\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}]", "instructions": "1. Mash ripe bananas well in a bowl and set aside. 2. Add melted butter sugar eggs and vanilla to the bread machine pan first. 3. Add mashed bananas and stir lightly to combine with the wet ingredients. 4. Spoon flour on top then add baking soda baking powder salt and cinnamon. 5. Select the Quick Bread or Cake cycle on your machine and press Start. 6. When cycle is complete check center with a toothpick; it should come out clean. 7. Remove bread from pan and cool on a wire rack before slicing.", "tags": "bread machine, banana bread, quick bread, no-yeast", "source": "https://breaddad.com/bread-machine-banana-bread/", "nutritionData": "{\"calories\": 223, \"protein\": 4.0, \"carbs\": 36.0, \"fat\": 7.0}"},
  {"name": "Beer Bread", "category": "Bread Machine", "description": "Savory yeast beer bread made with amber ale and whole wheat flour on the Basic cycle.", "servings": 12, "prepTime": 10, "cookTime": 180, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"amber ale room temperature\"}, {\"qty\": \"1/4 cup\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tsp\", \"name\": \"instant yeast\"}]", "instructions": "1. Pour beer into the bread machine pan followed by sugar and oil. 2. Spoon bread flour and whole wheat flour on top of the liquid ingredients. 3. Sprinkle salt around the edges of the flour and make a small well in the center for the yeast. 4. Select Basic or White Bread cycle with medium or dark crust and press Start. 5. Check dough ball after 5 minutes of kneading and add flour if batter is too wet. 6. When cycle is complete promptly remove loaf from pan. 7. Cool on a wire rack for at least 30 minutes before slicing.", "tags": "bread machine, beer bread, savory, amber ale", "source": "https://jennifercooks.com/bread-machine-beer-bread/", "nutritionData": "{\"calories\": 179, \"protein\": 4.0, \"carbs\": 35.0, \"fat\": 2.0}"},
  {"name": "Focaccia Dough", "category": "Bread Machine", "description": "Pillowy olive oil focaccia with rosemary and sea salt using the bread machine Dough cycle.", "servings": 12, "prepTime": 15, "cookTime": 115, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"1/3 cup\", \"name\": \"onion finely chopped\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 1/2 tsp\", \"name\": \"yeast\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil for topping\"}, {\"qty\": \"1 1/2 tbsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"\", \"name\": \"coarse sea salt for sprinkling\"}]", "instructions": "1. Add water and onion to the bread machine pan. 2. Spoon flour on top then add sugar making two small wells in the flour for salt and yeast separately. 3. Select Dough cycle and press Start. 4. When dough cycle is complete generously brush a baking sheet with olive oil and turn dough out onto it. 5. Use oiled fingers to press dough out to about 1 inch thick. 6. Cover with plastic wrap and let rise 40 minutes until doubled. 7. Preheat oven to 425°F. Dimple dough with fingers drizzle with olive oil sprinkle with rosemary and sea salt then bake 20-25 minutes until golden brown.", "tags": "bread machine, focaccia, dough cycle, Italian", "source": "https://www.sidewalkshoes.com/focaccia/", "nutritionData": "{\"calories\": 150, \"protein\": 3.0, \"carbs\": 25.0, \"fat\": 4.0}"},
  {"name": "Pizza Dough", "category": "Bread Machine", "description": "Classic chewy pizza crust made in the bread machine on the Dough cycle ready to top and bake.", "servings": 12, "prepTime": 10, "cookTime": 90, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water 105-110\\u00b0F\"}, {\"qty\": \"2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"active dry yeast\"}]", "instructions": "1. Add warm water to the bread machine pan. 2. Add olive oil then spoon flour on top covering the liquid. 3. Add sugar and salt making a small well in the flour for the yeast keeping it away from the salt. 4. Select Dough cycle and press Start. 5. After cycle is complete turn dough out onto a lightly floured surface. 6. Divide into portions and roll out to desired thickness. 7. Top with sauce and toppings and bake at 400-425°F for 18-25 minutes until cheese is bubbly and crust is golden.", "tags": "bread machine, pizza dough, dough cycle, Italian", "source": "https://www.allrecipes.com/recipe/7189/pizza-crust-for-bread-machine/", "nutritionData": "{\"calories\": 100, \"protein\": 2.0, \"carbs\": 17.0, \"fat\": 3.0}"},
  {"name": "Soft Pretzel Dough", "category": "Bread Machine", "description": "Chewy homemade soft pretzels made using the bread machine Dough cycle then boiled and baked.", "servings": 8, "prepTime": 20, "cookTime": 105, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water room temperature\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter cut into pieces\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"6 cups\", \"name\": \"water for boiling\"}, {\"qty\": \"1/4 cup\", \"name\": \"baking soda\"}, {\"qty\": \"1\", \"name\": \"egg for egg wash\"}, {\"qty\": \"2 tbsp\", \"name\": \"coarse sea salt for topping\"}]", "instructions": "1. Add water butter sugar and salt to the bread machine pan. 2. Spoon flour on top and make a small well for the yeast. 3. Select Dough cycle and press Start. Allow 1.5 hours. 4. Remove dough and chill wrapped in plastic wrap in refrigerator for 30 minutes. 5. Divide dough into 8 pieces and roll each into an 18-20 inch rope. Form into pretzel shapes. 6. Bring 6 cups water and baking soda to a rapid boil. Boil pretzels for 30 seconds per side then transfer to a parchment-lined baking sheet. 7. Brush with egg wash sprinkle with coarse salt and bake at 425°F for 12-15 minutes until golden brown.", "tags": "bread machine, soft pretzels, dough cycle, snack", "source": "https://www.artandthekitchen.com/bread-machine-pretzels/", "nutritionData": "{\"calories\": 193, \"protein\": 5.0, \"carbs\": 37.0, \"fat\": 2.0}"},
  {"name": "Hamburger Buns", "category": "Bread Machine", "description": "Soft golden hamburger buns made with the bread machine Dough cycle then shaped and baked.", "servings": 8, "prepTime": 20, "cookTime": 105, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/8 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"1\", \"name\": \"egg for egg wash\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds for topping\"}]", "instructions": "1. Add egg milk water butter sugar and salt to the bread machine pan in order listed. 2. Spoon flour on top and make a small well for the yeast. 3. Select Dough cycle and press Start. 4. When cycle is complete transfer dough to a floured surface and divide into 8 equal pieces. 5. Shape each piece into a ball and place on a parchment-lined baking sheet flattening each to about 1/2 inch thick. 6. Cover and let rise in a warm place until doubled about 30-35 minutes. 7. Brush with egg wash sprinkle with sesame seeds and bake at 400°F for 10-12 minutes until golden brown. Cool on wire rack.", "tags": "bread machine, hamburger buns, dough cycle, buns", "source": "https://pudgefactor.com/homemade-hamburger-buns-bread-machine/", "nutritionData": "{\"calories\": 207, \"protein\": 6.0, \"carbs\": 32.0, \"fat\": 6.0}"},
  {"name": "Challah Bread", "category": "Bread Machine", "description": "Rich golden egg bread with honey and olive oil made on the Basic cycle in the bread machine.", "servings": 16, "prepTime": 15, "cookTime": 195, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1\", \"name\": \"egg yolk\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"4 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"1\", \"name\": \"egg white for topping\"}, {\"qty\": \"1 tsp\", \"name\": \"poppy seeds for topping\"}]", "instructions": "1. Add water eggs egg yolk honey and olive oil to the bread machine pan. 2. Spoon flour on top covering the liquid ingredients. 3. Create a small well in the flour and nestle the salt on one side and yeast on the other. 4. Select Basic cycle with medium crust setting for a 2 lb loaf and press Start. 5. Optional: during the final rise just before baking open lid and brush top with egg white and sprinkle poppy seeds. 6. Allow cycle to complete fully. 7. Remove loaf from pan and cool completely on a wire rack before slicing.", "tags": "bread machine, challah, egg bread, Jewish", "source": "https://adamantkitchen.com/bread-machine-challah/", "nutritionData": "{\"calories\": 169, \"protein\": 4.0, \"carbs\": 26.0, \"fat\": 5.0}"},
  {"name": "Honey Whole Wheat Bread", "category": "Bread Machine", "description": "Sweet whole wheat honey bread with a soft tender crumb made on the Basic or Whole Wheat cycle.", "servings": 14, "prepTime": 10, "cookTime": 195, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"milk\"}, {\"qty\": \"3 tbsp\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"honey\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 cup\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}]", "instructions": "1. Warm milk to 80°F. Add milk water oil honey and egg to the bread machine pan. 2. Spoon bread flour and whole wheat flour on top of the liquid ingredients. 3. Add salt and make a small well for the yeast in the flour. 4. Select Basic cycle with medium crust for a 1.5 lb loaf and press Start. 5. Check dough consistency after 5 minutes of kneading; it should be a soft tacky ball. Adjust with water or flour 1 tbsp at a time if needed. 6. When cycle is complete remove bread and cool on a wire rack. 7. Store wrapped at room temperature for up to 4 days.", "tags": "bread machine, whole wheat, honey, soft", "source": "https://redstaryeast.com/recipes/bread-machine-whole-wheat-honey-bread/", "nutritionData": "{\"calories\": 142, \"protein\": 4.0, \"carbs\": 25.0, \"fat\": 3.0}"},
  {"name": "Oatmeal Bread", "category": "Bread Machine", "description": "Moist hearty oatmeal bread with a tender crumb baked on the Basic cycle for perfect everyday slices.", "servings": 14, "prepTime": 10, "cookTime": 185, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"old-fashioned rolled oats\"}, {\"qty\": \"2 1/4 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water and butter to the bread machine pan. 2. Add brown sugar honey and salt. 3. Spoon rolled oats into pan then cover with bread flour. 4. Make a small well in the flour and add yeast keeping it away from the salt. 5. Select Basic/White cycle for a 1.5 lb loaf with medium crust and press Start. 6. After about 10 minutes of kneading check dough; adjust with water or flour 1 tbsp at a time if needed. 7. Remove loaf when done and cool on a wire rack at least 30 minutes before slicing.", "tags": "bread machine, oatmeal bread, soft, hearty", "source": "Classic", "nutritionData": "{\"calories\": 113, \"protein\": 3.0, \"carbs\": 22.0, \"fat\": 2.0}"},
  {"name": "Brioche Bread", "category": "Bread Machine", "description": "Rich buttery brioche with a tender golden crumb made in the bread machine on the Sweet cycle.", "servings": 12, "prepTime": 20, "cookTime": 210, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"3\", \"name\": \"large eggs at room temperature\"}, {\"qty\": \"8 tbsp\", \"name\": \"unsalted butter softened and cut into pieces\"}, {\"qty\": \"2 3/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"dry milk powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"instant yeast\"}]", "instructions": "1. Add warm water and eggs to the bread machine pan. 2. Distribute pieces of softened butter evenly over the liquid. 3. Spoon flour on top then add dry milk powder and sugar. 4. Make a well in the flour adding salt on one side and yeast on the other. 5. Select Sweet or Basic cycle for a 1.5 lb loaf and press Start. 6. Check dough after 10 minutes; the dough should be soft and slightly sticky. Add flour 1 tbsp at a time if too wet. 7. Cool loaf on a wire rack for at least 1 hour before slicing for best texture.", "tags": "bread machine, brioche, rich, butter", "source": "Classic", "nutritionData": "{\"calories\": 213, \"protein\": 5.0, \"carbs\": 26.0, \"fat\": 10.0}"},
  {"name": "Rosemary Garlic Focaccia Dough", "category": "Bread Machine", "description": "Aromatic rosemary and roasted garlic focaccia made via the Dough cycle then dimpled and baked in olive oil.", "servings": 10, "prepTime": 20, "cookTime": 110, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil plus more for pan\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh or dried rosemary\"}, {\"qty\": \"4 cloves\", \"name\": \"roasted garlic mashed\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"1/4 tsp\", \"name\": \"flaky sea salt for topping\"}]", "instructions": "1. Add warm water and 2 tbsp olive oil to the bread machine pan. 2. Add roasted garlic then spoon flour on top. 3. Add sugar and salt in small wells in the flour and add yeast separately. 4. Select Dough cycle and press Start. 5. Once dough cycle is complete oil an 18x13 inch baking pan generously. Turn dough out and stretch it into the pan. 6. Cover and let rise 30 minutes. Dimple dough with fingertips drizzle with remaining olive oil and scatter rosemary and flaky salt on top. 7. Bake at 425°F for 20-25 minutes until light golden brown. Serve warm.", "tags": "bread machine, focaccia, rosemary garlic, dough cycle", "source": "Classic", "nutritionData": "{\"calories\": 181, \"protein\": 4.0, \"carbs\": 30.0, \"fat\": 5.0}"},
  {"name": "Multigrain Honey Bread", "category": "Bread Machine", "description": "Hearty bread made with multiple flours rolled oats and millet sweetened with honey on the Whole Wheat cycle.", "servings": 14, "prepTime": 10, "cookTime": 215, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 cups\", \"name\": \"whole wheat flour\"}, {\"qty\": \"3/4 cup\", \"name\": \"bread flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"2 tbsp\", \"name\": \"millet or cracked wheat\"}, {\"qty\": \"1 tbsp\", \"name\": \"flaxseed meal\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water oil and honey to the bread machine pan. 2. Add salt then layer in whole wheat flour and bread flour. 3. Add rolled oats millet and flaxseed meal on top. 4. Make a small well in the grain mixture and add yeast. 5. Select Whole Wheat cycle for a 1.5 lb loaf and press Start. 6. After kneading begins check consistency and add water or flour 1 tbsp at a time if needed. 7. Remove baked loaf and cool on a rack at least 30 minutes before slicing.", "tags": "bread machine, multigrain, whole grain, honey", "source": "Classic", "nutritionData": "{\"calories\": 137, \"protein\": 4.0, \"carbs\": 25.0, \"fat\": 3.0}"},
  {"name": "Sweet Potato Bread", "category": "Bread Machine", "description": "Soft golden bread with mashed sweet potato and warm spices baked on the Basic cycle.", "servings": 14, "prepTime": 15, "cookTime": 190, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"1/2 cup\", \"name\": \"mashed sweet potato cooled\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water mashed sweet potato butter and honey to the bread machine pan. 2. Add salt cinnamon and nutmeg. 3. Spoon bread flour on top covering the liquid. 4. Make a small well in the flour and add yeast keeping it away from salt. 5. Select Basic cycle for a 1.5 lb loaf with medium crust and press Start. 6. Check dough after 10 minutes of kneading; sweet potato adds moisture so add flour 1 tbsp at a time if dough is too sticky. 7. Cool loaf on a wire rack before slicing.", "tags": "bread machine, sweet potato, spiced, soft", "source": "Classic", "nutritionData": "{\"calories\": 124, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 2.0}"},
  {"name": "Anadama Bread", "category": "Bread Machine", "description": "Old-fashioned New England cornmeal and molasses bread with a chewy crumb made on the Basic cycle.", "servings": 14, "prepTime": 10, "cookTime": 190, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"1/3 cup\", \"name\": \"cornmeal\"}, {\"qty\": \"2 tbsp\", \"name\": \"molasses\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 3/4 cups\", \"name\": \"bread flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water cornmeal molasses and butter to the bread machine pan. 2. Add salt then spoon bread flour on top. 3. Make a small well in the flour and add yeast. 4. Select Basic/White cycle for a 1.5 lb loaf with medium crust and press Start. 5. After 10 minutes of kneading check dough; it should be a soft ball. Add flour 1 tbsp at a time if too sticky. 6. Allow machine to complete all cycles. 7. Remove loaf and cool on a wire rack for at least 30 minutes before slicing.", "tags": "bread machine, anadama, cornmeal, molasses", "source": "Classic", "nutritionData": "{\"calories\": 116, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 1.0}"},
  {"name": "Cheddar Jalapeño Bread", "category": "Bread Machine", "description": "Bold and cheesy bread with jalapeño heat baked on the Basic cycle for a crowd-pleasing savory loaf.", "servings": 14, "prepTime": 15, "cookTime": 185, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1os seeded and diced\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water and oil to the bread machine pan. 2. Add sugar and salt then spoon flour on top. 3. Make a small well in the flour and add yeast. 4. Select Basic/White cycle and press Start. 5. Add shredded cheddar and diced jalapeños when the machine beeps for mix-ins or about 5 minutes before the end of the kneading cycle. 6. Allow machine to complete baking cycle. 7. Remove loaf and cool completely on a wire rack before slicing.", "tags": "bread machine, cheddar jalapeño, savory, cheesy", "source": "Classic", "nutritionData": "{\"calories\": 142, \"protein\": 5.0, \"carbs\": 21.0, \"fat\": 4.0}"},
  {"name": "Honey Butter White Bread", "category": "Bread Machine", "description": "Ultra-soft enriched white bread with butter and honey for a pillowy rich everyday loaf on the Basic cycle.", "servings": 16, "prepTime": 10, "cookTime": 195, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Warm milk to 110°F and add to bread machine pan with butter and honey. 2. Add egg to the pan. 3. Spoon flour on top of the liquid ingredients. 4. Add salt and make a small well in the flour for the yeast. 5. Select Basic cycle for a 1.5 lb loaf with light or medium crust and press Start. 6. Check dough consistency after 5 minutes of kneading. Dough should be soft and smooth; adjust with flour or water as needed. 7. Remove loaf when done and cool on a wire rack before slicing.", "tags": "bread machine, white bread, enriched, soft", "source": "Classic", "nutritionData": "{\"calories\": 130, \"protein\": 3.0, \"carbs\": 22.0, \"fat\": 3.0}"},
  {"name": "Pretzel Dough Rolls", "category": "Bread Machine", "description": "Chewy homemade pretzel rolls shaped from bread machine dough and baked with a baking soda bath.", "servings": 10, "prepTime": 25, "cookTime": 105, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"8 cups\", \"name\": \"water for water bath\"}, {\"qty\": \"1/3 cup\", \"name\": \"baking soda\"}, {\"qty\": \"1\", \"name\": \"egg beaten for egg wash\"}, {\"qty\": \"\", \"name\": \"coarse salt for topping\"}]", "instructions": "1. Add warm water butter salt and brown sugar to the bread machine pan. 2. Spoon flour on top and add yeast in a small well in the flour. 3. Select Dough cycle and press Start. 4. Once dough cycle is complete divide dough into 10 equal pieces and shape each into a smooth ball then flatten slightly to 3 inches across. 5. Place on a parchment-lined baking sheet cover and rest 15 minutes. 6. Bring 8 cups water and baking soda to a boil. Boil rolls 30 seconds per side then return to baking sheet. 7. Brush with egg wash cut a cross on top of each roll sprinkle with coarse salt and bake at 400°F for 20-22 minutes until deep golden brown.", "tags": "bread machine, pretzel rolls, dough cycle, snack", "source": "https://www.kingarthurbaking.com/recipes/pretzel-buns-recipe", "nutritionData": "{\"calories\": 165, \"protein\": 4.0, \"carbs\": 30.0, \"fat\": 3.0}"},
  {"name": "Sun-Dried Tomato Herb Bread", "category": "Bread Machine", "description": "Mediterranean-inspired sun-dried tomato bread with basil and garlic made on the Basic cycle.", "servings": 14, "prepTime": 15, "cookTime": 185, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil from sun-dried tomato jar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"3 cups\", \"name\": \"bread flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"sun-dried tomatoes chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}]", "instructions": "1. Add warm water and olive oil to the bread machine pan. 2. Add salt and sugar then spoon flour on top. 3. Add dried basil oregano and garlic powder and make a small well in the flour for the yeast. 4. Select Basic cycle for a 1.5 lb loaf and press Start. 5. Add chopped sun-dried tomatoes when the machine beeps for mix-ins or about 5 minutes before the end of the kneading cycle. 6. Allow machine to complete full baking cycle. 7. Remove loaf cool on a wire rack for 30 minutes and slice.", "tags": "bread machine, sun-dried tomato, herb, Mediterranean", "source": "Classic", "nutritionData": "{\"calories\": 126, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 2.0}"},
  {"name": "Cinnamon Swirl Bread", "category": "Bread Machine", "description": "Soft white bread swirled with cinnamon sugar filling made on the Dough cycle then shaped and baked.", "servings": 14, "prepTime": 25, "cookTime": 135, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"warm milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"warm water\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"bread machine yeast\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar for filling\"}, {\"qty\": \"2 tsp\", \"name\": \"cinnamon for filling\"}, {\"qty\": \"1 tbsp\", \"name\": \"melted butter for filling\"}]", "instructions": "1. Add warm milk water butter sugar and salt to the bread machine pan. 2. Spoon flour on top and add yeast in a small well in the flour. 3. Select Dough cycle and press Start. 4. When cycle is complete turn dough out onto a lightly floured surface and roll into a 9x18 inch rectangle. 5. Brush with melted butter and sprinkle evenly with cinnamon-sugar filling leaving a 1 inch border on one short end. 6. Roll tightly from the filled end into a log and pinch seam to seal. Place seam-side down in a greased 9x5 inch loaf pan. 7. Cover and let rise until domed 1 inch over pan rim about 1 hour. Bake at 350°F for 35-40 minutes until golden and internal temperature reaches 190°F. Cool completely before slicing.", "tags": "bread machine, cinnamon swirl, dough cycle, sweet", "source": "Classic", "nutritionData": "{\"calories\": 144, \"protein\": 3.0, \"carbs\": 25.0, \"fat\": 3.0}"},
  {"name": "Soft Chocolate Chip Cookies", "category": "Desserts", "description": "Thick and chewy chocolate chip cookies with crisp edges and gooey centers.", "servings": 24, "prepTime": 15, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"3/4 cup\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"semi-sweet chocolate chips\"}]", "instructions": "1. Beat butter and sugars on medium speed until creamy, about 2 minutes. 2. Beat in egg and vanilla; scrape bowl. 3. Whisk flour, cornstarch, baking soda, and salt; add to wet ingredients on low speed until combined. 4. Fold in chocolate chips. Cover dough and chill at least 1 hour. 5. Preheat oven to 350°F and line baking sheets with parchment. Roll dough into 1.5-tablespoon balls and place 3 inches apart. 6. Bake 11-12 minutes until barely golden around edges. Cool on baking sheet 5 minutes before transferring.", "tags": "cookies, chocolate, make-ahead", "source": "https://sallysbakingaddiction.com/chocolate-chip-cookies/", "nutritionData": "{\"calories\": 148, \"protein\": 2.0, \"carbs\": 21.0, \"fat\": 7.0}"},
  {"name": "King Arthur Fudge Brownies", "category": "Desserts", "description": "Dense and fudgy scratch brownies with a shiny crackle top and deep chocolate flavor.", "servings": 24, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 1/4 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"Dutch-process cocoa powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"espresso powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"semi-sweet chocolate chips\"}]", "instructions": "1. Preheat oven to 350°F and line a 9x13-inch pan with parchment. 2. Whisk eggs, cocoa, salt, baking powder, espresso powder, and vanilla in a large bowl until smooth. 3. Melt butter in a saucepan; stir in sugar and heat to 110-120°F but not bubbling. 4. Add hot butter-sugar to egg-cocoa mixture and stir until smooth. Stir in flour and chocolate chips. 5. Cool batter 20 minutes then spread into pan. Bake 28-32 minutes until edges are set and a toothpick shows moist crumbs. 6. Cool completely on a rack before cutting.", "tags": "chocolate, fudgy, crowd-pleaser", "source": "https://www.kingarthurbaking.com/recipes/fudge-brownies-recipe", "nutritionData": "{\"calories\": 229, \"protein\": 3.0, \"carbs\": 35.0, \"fat\": 11.0}"},
  {"name": "Classic New York Cheesecake", "category": "Desserts", "description": "Silky cream cheese cheesecake on a buttery graham cracker crust baked in a water bath.", "servings": 12, "prepTime": 30, "cookTime": 70, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"graham cracker crumbs\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"32 oz\", \"name\": \"full-fat cream cheese softened\"}, {\"qty\": \"1 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"full-fat sour cream\"}, {\"qty\": \"1 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}]", "instructions": "1. Preheat oven to 350°F. Mix crumbs, 1/3 cup sugar, and butter; press into a 9-inch springform pan. Bake crust 8 minutes; cool. 2. Beat cream cheese and 1 cup sugar until completely smooth, about 2 minutes. 3. Add sour cream, lemon juice, and vanilla; beat until combined. Add eggs one at a time, beating just until combined. 4. Pour batter over crust. Wrap pan in heavy-duty foil; place in a roasting pan with 1 inch of boiling water. 5. Bake 55-70 minutes until edges set and center jiggles slightly. Turn off oven; leave door ajar 1 hour. 6. Cool on rack; refrigerate at least 4 hours before slicing.", "tags": "cheesecake, make-ahead, special-occasion", "source": "https://sallysbakingaddiction.com/classic-cheesecake/", "nutritionData": "{\"calories\": 513, \"protein\": 7.0, \"carbs\": 32.0, \"fat\": 40.0}"},
  {"name": "Smitten Kitchen Apple Pie", "category": "Desserts", "description": "Flaky double-crust apple pie with tender spiced filling and a golden pastry shell.", "servings": 8, "prepTime": 45, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"cold unsalted butter cut into cubes\"}, {\"qty\": \"6 tbsp\", \"name\": \"ice water\"}, {\"qty\": \"3 lbs\", \"name\": \"mixed baking apples peeled and sliced\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1\", \"name\": \"large egg beaten with 1 tbsp water\"}]", "instructions": "1. Pulse flour, salt, and sugar in a food processor. Add cold butter; pulse until pea-sized. Drizzle in ice water 1 tbsp at a time until dough comes together. Divide, flatten, wrap, and refrigerate 1 hour. 2. Preheat oven to 375°F. Toss apples with sugar, cornstarch, cinnamon, nutmeg, and lemon juice. 3. Roll out one disc to a 12-inch circle and fit into a 9-inch pie plate. Add filling. Roll out second disc; lay over filling. Trim, fold, and crimp edges. Cut vents. Brush with egg wash. 4. Place on a baking sheet; bake 20 minutes. Reduce to 350°F and bake 40-50 minutes more until crust is golden and juices bubble. 5. Cool on a wire rack at least 2 hours before slicing.", "tags": "pie, fall, make-ahead", "source": "https://smittenkitchen.com/2018/10/even-more-perfect-apple-pie/", "nutritionData": "{\"calories\": 529, \"protein\": 5.0, \"carbs\": 76.0, \"fat\": 24.0}"},
  {"name": "Maple Pecan Pie", "category": "Desserts", "description": "Rich and buttery pecan pie made with pure maple syrup for a deep caramel flavor.", "servings": 8, "prepTime": 25, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"unbaked 9-inch pie crust\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"pecan halves\"}, {\"qty\": \"5 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/2 cup\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"pure maple syrup\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for sprinkling\"}]", "instructions": "1. Preheat oven to 350°F. Blind-bake chilled pie crust with pie weights 15 minutes; remove weights. 2. Spread pecans evenly inside warm crust. Set aside. 3. Whisk melted butter, brown sugar, and flour together. Whisk in vanilla, salt, eggs, and maple syrup until combined. 4. Pour filling evenly over pecans. Shield crust edges with foil. 5. Bake 40-50 minutes until top is lightly browned. Sprinkle with flaky sea salt immediately. 6. Cool completely on a wire rack before slicing; filling sets as it cools.", "tags": "pie, holiday, fall", "source": "https://sallysbakingaddiction.com/my-favorite-pecan-pie-recipe/", "nutritionData": "{\"calories\": 537, \"protein\": 10.0, \"carbs\": 58.0, \"fat\": 31.0}"},
  {"name": "Classic Key Lime Pie", "category": "Desserts", "description": "Tangy and creamy key lime pie with a crisp graham cracker crust and silky custard filling.", "servings": 8, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"graham cracker crumbs\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime zest\"}, {\"qty\": \"4\", \"name\": \"large egg yolks\"}, {\"qty\": \"14 oz\", \"name\": \"sweetened condensed milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"powdered sugar\"}]", "instructions": "1. Preheat oven to 325°F. Mix crumbs, sugar, and butter; press into a 9-inch pie pan. Bake 15 minutes; cool. 2. Whisk lime zest and egg yolks at high speed 4 minutes until lightened. 3. Stir in condensed milk; beat at high speed 3 minutes. Add lime juice and stir just to combine. 4. Pour into crust and bake 25 minutes until set around edges but wobbly in center. 5. Cool to room temperature then refrigerate at least 3 hours. 6. Whip cream with powdered sugar to medium peaks. Serve each slice with whipped cream.", "tags": "pie, citrus, summer", "source": "https://www.kingarthurbaking.com/recipes/classic-key-lime-pie-recipe", "nutritionData": "{\"calories\": 432, \"protein\": 4.0, \"carbs\": 42.0, \"fat\": 27.0}"},
  {"name": "Smitten Kitchen Lemon Bars", "category": "Desserts", "description": "Buttery shortbread crust under a bright and tangy lemon curd filling dusted with powdered sugar.", "servings": 16, "prepTime": 20, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"unsalted butter at room temperature\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/8 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"6\", \"name\": \"extra-large eggs at room temperature\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated lemon zest\"}, {\"qty\": \"1 cup\", \"name\": \"freshly squeezed lemon juice\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"confectioners sugar for dusting\"}]", "instructions": "1. Preheat oven to 350°F and grease a 9x13-inch baking pan. 2. Cream butter and 1/2 cup sugar until light. Mix in 2 cups flour and salt until just combined. Press into pan building up 1/2-inch edges. Refrigerate 15 minutes. 3. Bake crust 15-20 minutes until very lightly browned. Cool; leave oven on. 4. Whisk eggs, 2 1/2 cups sugar, lemon zest, lemon juice, and 1 cup flour. Pour over crust. 5. Bake 30-35 minutes until filling is set. Cool to room temperature. 6. Cut into rectangles and dust generously with confectioners sugar before serving.", "tags": "bars, lemon, citrus", "source": "https://smittenkitchen.com/2008/01/lemon-bars/", "nutritionData": "{\"calories\": 366, \"protein\": 5.0, \"carbs\": 57.0, \"fat\": 14.0}"},
  {"name": "Chocolate Lava Cakes", "category": "Desserts", "description": "Individual molten chocolate cakes with a gooey flowing center for an elegant dinner-party dessert.", "servings": 4, "prepTime": 15, "cookTime": 14, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6 oz\", \"name\": \"semi-sweet chocolate chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"confectioners sugar\"}, {\"qty\": \"1/8 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2\", \"name\": \"large egg yolks\"}]", "instructions": "1. Spray four 6-oz ramekins with nonstick spray and dust with cocoa powder. Preheat oven to 425°F. 2. Microwave butter and chocolate in 10-second increments until smooth. 3. Whisk flour, confectioners sugar, and salt in a small bowl. Whisk eggs and yolks in another bowl. 4. Pour flour mixture and eggs into chocolate mixture; stir with a spatula until smooth and slightly thick. 5. Divide batter among ramekins on a baking sheet. Bake 12-14 minutes until sides are firm but tops are still soft. 6. Cool 1 minute then cover each with an inverted plate; flip and let release 10 seconds. Remove ramekin. Serve immediately with ice cream.", "tags": "chocolate, elegant, dinner-party", "source": "https://sallysbakingaddiction.com/chocolate-lava-cakes/", "nutritionData": "{\"calories\": 467, \"protein\": 6.0, \"carbs\": 42.0, \"fat\": 34.0}"},
  {"name": "Classic Tiramisu", "category": "Desserts", "description": "Luxurious layers of espresso-soaked ladyfingers and mascarpone cream dusted with cocoa.", "servings": 8, "prepTime": 30, "cookTime": 0, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar divided\"}, {\"qty\": \"3/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 cup\", \"name\": \"mascarpone cheese at room temperature\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"strong espresso cooled\"}, {\"qty\": \"2 tbsp\", \"name\": \"dark rum\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"24\", \"name\": \"ladyfinger cookies\"}, {\"qty\": \"1 oz\", \"name\": \"dark chocolate shaved for garnish\"}]", "instructions": "1. Beat egg yolks and 1/4 cup sugar until pale yellow and tripled in volume, about 4 minutes. Set aside. 2. Whip cream and remaining 1/4 cup sugar to soft peaks. Add mascarpone; whip to medium peaks. 3. Gently fold mascarpone mixture into sweetened yolks until combined. 4. Combine espresso and rum in a shallow bowl. Dust bottom of an 8x8-inch pan with 1 tbsp cocoa. 5. Quickly dip each ladyfinger in espresso mixture; arrange in a single layer in the pan. Cover with half the cream. 6. Repeat with remaining ladyfingers and cream. Dust top with remaining cocoa. Cover and refrigerate at least 4 hours. Garnish with shaved chocolate.", "tags": "no-bake, make-ahead, Italian", "source": "Classic", "nutritionData": "{\"calories\": 390, \"protein\": 4.0, \"carbs\": 27.0, \"fat\": 25.0}"},
  {"name": "Strawberry Cream Pretzel Tart", "category": "Desserts", "description": "Honey-cream tart in a pretzel-gingersnap crust swirled with jam and topped with fresh berries.", "servings": 8, "prepTime": 20, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"mini salted pretzels\"}, {\"qty\": \"15\", \"name\": \"gingersnap cookies\"}, {\"qty\": \"6 tbsp\", \"name\": \"salted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"3 1/2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"1/3 cup\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1/3 cup\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"strawberry jam\"}, {\"qty\": \"2 cups\", \"name\": \"mixed fresh berries\"}]", "instructions": "1. Preheat oven to 350°F. Pulse pretzels and gingersnaps until fine crumbs. Add melted butter and 2 tbsp honey; pulse until mixture holds together. Press into a 9-inch tart pan with removable bottom. Bake 8 minutes; cool. 2. Combine cream, 1/3 cup honey, and lemon zest in a large pot over high heat. Bring to a boil; boil 5 minutes. Remove from heat; whisk in lemon juice and vanilla. Cool 10 minutes. 3. Pour lemon cream into crust. Dollop jam over cream and gently swirl with a knife. 4. Cover and chill 1.5-2 hours until set. 5. Before serving remove tart from pan and top with fresh berries. Slice and serve immediately.", "tags": "no-bake, summer, fruit", "source": "https://www.halfbakedharvest.com/strawberry-cream-pretzel-tart/", "nutritionData": "{\"calories\": 708, \"protein\": 5.0, \"carbs\": 65.0, \"fat\": 48.0}"},
  {"name": "Vanilla Panna Cotta", "category": "Desserts", "description": "Silky and wobbly Italian set cream perfumed with vanilla and served with fresh berry coulis.", "servings": 6, "prepTime": 10, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 1/4 tsp\", \"name\": \"unflavored powdered gelatin\"}, {\"qty\": \"3 tbsp\", \"name\": \"cold water\"}, {\"qty\": \"2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"1/2\", \"name\": \"vanilla bean scraped\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"1 cup\", \"name\": \"fresh raspberries\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon juice\"}]", "instructions": "1. Sprinkle gelatin over cold water; let sit 5 minutes to bloom. 2. Combine cream, milk, and sugar in a saucepan over medium heat; stir until sugar dissolves and mixture just steams. Do not boil. 3. Remove from heat. Stir in bloomed gelatin, vanilla extract, vanilla bean seeds, and salt until dissolved. 4. Pour into six lightly oiled 6-oz ramekins. Refrigerate uncovered at least 4 hours or overnight. 5. Make coulis: simmer raspberries, sugar, and lemon juice 5 minutes. Press through a sieve; cool. 6. Run a thin knife around edge of each panna cotta and invert onto plates. Spoon berry coulis over top.", "tags": "Italian, elegant, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 365, \"protein\": 5.0, \"carbs\": 22.0, \"fat\": 30.0}"},
  {"name": "Old-School Chocolate Mousse", "category": "Desserts", "description": "Light yet intensely rich chocolate mousse made with whipped egg whites for an airy texture.", "servings": 6, "prepTime": 25, "cookTime": 5, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6 oz\", \"name\": \"semi-sweet chocolate finely chopped\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"5\", \"name\": \"large eggs separated\"}, {\"qty\": \"4 tbsp\", \"name\": \"granulated sugar divided\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cream of tartar\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"pure vanilla extract\"}]", "instructions": "1. Melt chocolate and butter in a double boiler until smooth. Cool to lukewarm. 2. Whisk egg yolks and 2 tbsp sugar until pale. Stir into melted chocolate. 3. Beat egg whites with cream of tartar and salt to soft peaks. Gradually add remaining 2 tbsp sugar; beat to medium-stiff peaks. 4. Whip heavy cream and vanilla to soft peaks. 5. Fold one-third of egg whites into chocolate to lighten; fold in remaining whites. Fold in whipped cream. 6. Spoon into cups; refrigerate at least 2 hours. Serve with additional whipped cream and chocolate shavings.", "tags": "chocolate, elegant, make-ahead", "source": "https://smittenkitchen.com/2009/10/silky-decadent-old-school-chocolate-mousse/", "nutritionData": "{\"calories\": 285, \"protein\": 7.0, \"carbs\": 23.0, \"fat\": 21.0}"},
  {"name": "Magic Cookie Bars", "category": "Desserts", "description": "Seven-layer bars with a graham cracker base and layers of chocolate chips, nuts, coconut, and condensed milk.", "servings": 16, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"graham cracker crumbs\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"14 oz\", \"name\": \"sweetened condensed milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"3/4 cup\", \"name\": \"semi-sweet chocolate chips divided\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped walnuts\"}, {\"qty\": \"1/2 cup\", \"name\": \"dried cranberries\"}, {\"qty\": \"1 cup\", \"name\": \"sweetened shredded coconut\"}]", "instructions": "1. Preheat oven to 350°F. Line an 8-inch square pan with a parchment sling and grease sides. 2. Mix graham cracker crumbs and melted butter; press firmly into bottom of pan. 3. Whisk condensed milk with cocoa powder until smooth; pour over crust. 4. Sprinkle 1/2 cup chocolate chips, then walnuts, cranberries, and coconut over the top. 5. Bake 25-30 minutes until coconut is lightly toasted. 6. Melt remaining chocolate chips and drizzle over bars. Cool 90 minutes at room temperature then refrigerate 30 minutes before slicing.", "tags": "bars, no-mixer, easy", "source": "https://www.kingarthurbaking.com/recipes/chocolate-magic-cookie-bars-recipe", "nutritionData": "{\"calories\": 222, \"protein\": 2.0, \"carbs\": 27.0, \"fat\": 13.0}"},
  {"name": "Classic Blondies", "category": "Desserts", "description": "Chewy brown sugar bars packed with vanilla and chocolate chips finished with flaky sea salt.", "servings": 16, "prepTime": 15, "cookTime": 32, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"14 tbsp\", \"name\": \"unsalted butter melted and slightly cooled\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"1\", \"name\": \"large egg plus 1 egg yolk\"}, {\"qty\": \"1 tbsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"semi-sweet chocolate chips\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for topping\"}]", "instructions": "1. Preheat oven to 350°F. Line a 9-inch square pan with parchment leaving overhang on the sides. 2. Whisk flour, baking powder, and salt in a large bowl. 3. Whisk melted butter and brown sugar until combined. Whisk in egg, egg yolk, and vanilla. 4. Pour wet into dry; stir until combined. Fold in chocolate chips. Spread into pan; sprinkle with flaky sea salt. 5. Bake 30-34 minutes until golden brown with only a few moist crumbs on a toothpick. 6. Cool completely in pan about 1 hour before lifting out and cutting.", "tags": "bars, chocolate, easy", "source": "https://sallysbakingaddiction.com/candy-bar-blondies/", "nutritionData": "{\"calories\": 255, \"protein\": 3.0, \"carbs\": 36.0, \"fat\": 13.0}"},
  {"name": "Apple Cranberry Crisp", "category": "Desserts", "description": "Tender spiced apples and tart cranberries baked under a buttery oat-almond streusel topping.", "servings": 8, "prepTime": 20, "cookTime": 50, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"apples peeled cored and sliced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh or frozen cranberries\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"packed brown sugar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"cold unsalted butter cubed\"}, {\"qty\": \"1/3 cup\", \"name\": \"sliced almonds\"}]", "instructions": "1. Preheat oven to 350°F and grease a 9x13-inch baking dish. 2. Toss apples and cranberries with granulated sugar, cornstarch, cinnamon, nutmeg, and lemon juice; spread in dish. 3. Make streusel: combine oats, flour, brown sugar, and salt. Cut in cold butter until crumbly. Stir in almonds. 4. Sprinkle streusel evenly over fruit. 5. Bake 45-55 minutes until topping is golden and juices bubble. Tent with foil if streusel browns too quickly. 6. Cool 15 minutes and serve warm with vanilla ice cream.", "tags": "fall, fruit, easy", "source": "https://smittenkitchen.com/2007/12/apple-cranberry-crisp/", "nutritionData": "{\"calories\": 334, \"protein\": 4.0, \"carbs\": 58.0, \"fat\": 12.0}"},
  {"name": "Blueberry Peach Cobbler", "category": "Desserts", "description": "Juicy summer fruit baked under a tender drop-biscuit topping that comes out golden and flaky.", "servings": 8, "prepTime": 20, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"fresh blueberries\"}, {\"qty\": \"3 cups\", \"name\": \"sliced fresh peaches\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"cold unsalted butter\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"coarse sugar for topping\"}]", "instructions": "1. Preheat oven to 375°F and grease a 9x13-inch baking dish. 2. Toss blueberries and peaches with 1/2 cup sugar, cornstarch, and lemon juice; spread in dish. 3. Make biscuit topping: whisk flour, 2 tbsp sugar, baking powder, and salt. Cut in cold butter until crumbly. Stir in milk just until a shaggy dough forms. 4. Drop spoonfuls of dough over fruit leaving some fruit exposed. Sprinkle with coarse sugar. 5. Bake 40-45 minutes until biscuit topping is golden and fruit is bubbling. 6. Cool 10 minutes; serve warm with vanilla ice cream.", "tags": "summer, fruit, easy", "source": "https://www.kingarthurbaking.com/recipes/blueberry-peach-cobbler-recipe", "nutritionData": "{\"calories\": 301, \"protein\": 4.0, \"carbs\": 51.0, \"fat\": 10.0}"},
  {"name": "Homemade Chocolate Eclairs", "category": "Desserts", "description": "Classic French eclairs filled with silky pastry cream and dipped in a rich chocolate glaze.", "servings": 12, "prepTime": 45, "cookTime": 30, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4\", \"name\": \"large eggs beaten\"}, {\"qty\": \"4\", \"name\": \"large egg yolks\"}, {\"qty\": \"3 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk for pastry cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"4 oz\", \"name\": \"semi-sweet chocolate\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}]", "instructions": "1. Make pastry cream: whisk yolks and cornstarch. Heat 2 cups milk and 1/2 cup sugar to simmer; slowly whisk into yolks. Return to pan; cook over medium heat until thick and bubbling. Remove; stir in 1 tbsp butter and vanilla. Press plastic wrap on surface; refrigerate 3 hours. 2. Make choux: combine butter, water, milk, salt, and sugar; bring to simmer. Add flour; stir vigorously until dough forms a ball. Cool 5 minutes then beat in eggs gradually until dough is smooth and shiny. 3. Preheat oven to 400°F. Pipe 4-inch logs onto parchment-lined sheets. Bake 20 minutes; reduce to 350°F and bake 10-15 more minutes until golden. Cool completely. 4. Make glaze: heat cream until steaming; pour over chopped chocolate. Stir until smooth. 5. Pierce base of each eclair; pipe with pastry cream. Dip tops in chocolate glaze. 6. Refrigerate until ready to serve.", "tags": "French, pastry, special-occasion", "source": "https://sallysbakingaddiction.com/homemade-eclairs/", "nutritionData": "{\"calories\": 286, \"protein\": 6.0, \"carbs\": 26.0, \"fat\": 18.0}"},
  {"name": "Smitten Kitchen Birthday Cake", "category": "Desserts", "description": "Classic moist vanilla butter cake layered with rich sour cream chocolate frosting.", "servings": 12, "prepTime": 30, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"cake flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 sticks\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"15 oz\", \"name\": \"semisweet chocolate chopped\"}, {\"qty\": \"2 1/4 cups\", \"name\": \"sour cream at room temperature\"}, {\"qty\": \"1/4 cup\", \"name\": \"light corn syrup\"}, {\"qty\": \"3/4 tsp\", \"name\": \"vanilla extract for frosting\"}]", "instructions": "1. Preheat oven to 350°F. Butter two 9-inch round pans and line with parchment. Sift flour, baking powder, baking soda, and salt. 2. Beat butter and sugar until pale and fluffy. Beat in vanilla; add eggs one at a time. 3. Alternately beat in flour mixture and buttermilk in three additions each, beginning and ending with flour. 4. Divide batter between pans; bake 35-40 minutes until a toothpick comes out clean. Cool in pans 10 minutes then on racks completely. 5. Make frosting: melt chocolate in a double boiler; cool to tepid. Whisk sour cream, 1/4 cup corn syrup, and vanilla. Stir in chocolate until uniform. Chill until spreadable, about 30 minutes. 6. Place one layer on plate; spread with frosting. Top with second layer; frost top and sides. Refrigerate 30 minutes before slicing.", "tags": "cake, birthday, chocolate", "source": "https://smittenkitchen.com/2009/07/best-birthday-cake/", "nutritionData": "{\"calories\": 682, \"protein\": 10.0, \"carbs\": 93.0, \"fat\": 32.0}"},
  {"name": "Classic Creme Brulee", "category": "Desserts", "description": "Perfectly silky vanilla custard with a crackling caramelized sugar crust baked in a water bath.", "servings": 6, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"1\", \"name\": \"vanilla bean split and scraped\"}, {\"qty\": \"5\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"granulated sugar for brulee topping\"}]", "instructions": "1. Preheat oven to 325°F. Heat cream with vanilla bean pod and seeds until just simmering. Remove; steep 15 minutes. Discard pod. 2. Whisk egg yolks, 1/2 cup sugar, and salt until pale. Slowly whisk in warm cream to temper. Strain through a fine sieve. 3. Divide among six 6-oz ramekins. Place in a roasting pan; add boiling water to come halfway up ramekins. 4. Bake 40-45 minutes until just set around edges but wobbly in center. 5. Remove from water bath; cool to room temperature. Cover and refrigerate at least 4 hours or up to 2 days. 6. Just before serving sprinkle 1 tbsp sugar over each custard. Torch until deep amber and crackly. Serve immediately.", "tags": "French, elegant, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 427, \"protein\": 4.0, \"carbs\": 32.0, \"fat\": 32.0}"},
  {"name": "Carrot Cake with Cream Cheese Frosting", "category": "Desserts", "description": "Supremely moist one-layer carrot cake packed with warm spices and tangy cream cheese frosting.", "servings": 10, "prepTime": 20, "cookTime": 38, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"packed light brown sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"2 tsp\", \"name\": \"pure vanilla extract\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 cups\", \"name\": \"finely shredded carrots\"}, {\"qty\": \"3/4 cup\", \"name\": \"chopped pecans\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2 cups\", \"name\": \"confectioners sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"heavy cream\"}]", "instructions": "1. Preheat oven to 350°F; spray a 9-inch springform pan with nonstick spray. 2. Beat brown sugar, oil, and yogurt until combined. Add eggs one at a time; mix in vanilla. 3. Whisk flour, baking soda, cinnamon, nutmeg, and salt; fold into wet ingredients until just combined. Fold in carrots and pecans. 4. Pour into pan; bake 32-38 minutes until a toothpick comes out clean. Cool completely. 5. Make frosting: beat cream cheese and butter until smooth, 2 minutes. Add confectioners sugar; beat until thick. Add cream and beat 2 more minutes. 6. Spread frosting over cooled cake. Refrigerate 30 minutes before slicing.", "tags": "cake, spring, make-ahead", "source": "https://sallysbakingaddiction.com/my-favorite-carrot-cake-recipe/", "nutritionData": "{\"calories\": 664, \"protein\": 8.0, \"carbs\": 68.0, \"fat\": 41.0}"},
  {"name": "Yeast-Raised Doughnuts", "category": "Desserts", "description": "Pillowy golden yeast doughnuts fried to perfection and glazed with classic vanilla icing.", "servings": 12, "prepTime": 30, "cookTime": 12, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"2 cups\", \"name\": \"powdered sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"whole milk for glaze\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract for glaze\"}]", "instructions": "1. Whisk flour, sugar, yeast, and salt. Add warm milk, melted butter, egg, and vanilla; mix until a soft dough forms. 2. Knead 6-8 minutes until smooth. Place in greased bowl; cover and let rise 1.5-2 hours until doubled. 3. Punch down dough; roll to 1/4-inch thickness on a floured surface. Cut with a 2.5-inch round cutter; let rise on parchment 30-60 minutes until doubled. 4. Heat oil in a heavy pan to 350°F. Fry doughnuts 2-3 at a time until golden brown, about 1 minute per side. Drain on paper towels. 5. Make glaze: whisk powdered sugar, milk, and vanilla until smooth. 6. Dip warm doughnuts in glaze and set on a wire rack 15 minutes until glaze is set.", "tags": "doughnuts, weekend-baking, fried", "source": "https://www.kingarthurbaking.com/recipes/yeast-raised-doughnuts-recipe", "nutritionData": "{\"calories\": 289, \"protein\": 4.0, \"carbs\": 49.0, \"fat\": 8.0}"},
  {"name": "Chocolate Budino", "category": "Desserts", "description": "Silky Italian chocolate pudding made rich with egg yolks and topped with lightly whipped cream.", "servings": 6, "prepTime": 15, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"5\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"8 oz\", \"name\": \"semi-sweet chocolate finely chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 pinches\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tsp\", \"name\": \"bourbon optional\"}, {\"qty\": \"1/2 cup\", \"name\": \"additional heavy cream for serving\"}, {\"qty\": \"1 tbsp\", \"name\": \"powdered sugar\"}]", "instructions": "1. Whisk egg yolks and sugar in the bottom of a medium saucepan. Slowly drizzle in 2 cups cream while whisking. 2. Warm over medium-low heat, stirring frequently, until thick enough to coat a spoon. Do not simmer. 3. Place chopped chocolate in a bowl; set a fine-mesh sieve over it. Pour hot egg mixture through the sieve onto chocolate. 4. Stir until chocolate melts. Add butter, salt, vanilla, and bourbon if using; stir until smooth. 5. Divide among small cups; refrigerate until cold and set, about 2 hours. 6. Just before serving whip remaining 1/2 cup cream with powdered sugar to very soft peaks. Spoon gently over each budino.", "tags": "Italian, pudding, make-ahead", "source": "https://smittenkitchen.com/2019/06/chocolate-budino/", "nutritionData": "{\"calories\": 551, \"protein\": 6.0, \"carbs\": 34.0, \"fat\": 46.0}"},
  {"name": "No-Bake Berry Cheesecake", "category": "Desserts", "description": "Luscious no-bake cream cheese filling in a graham cracker crust swirled with fresh raspberries.", "servings": 8, "prepTime": 30, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/4 cups\", \"name\": \"graham cracker crumbs\"}, {\"qty\": \"6 tbsp\", \"name\": \"salted butter melted\"}, {\"qty\": \"16 oz\", \"name\": \"cream cheese at room temperature\"}, {\"qty\": \"1/3 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"3 tsp\", \"name\": \"vanilla extract divided\"}, {\"qty\": \"2 cups\", \"name\": \"heavy cream divided\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"fresh raspberries\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"fresh blueberries\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tsp\", \"name\": \"cornstarch\"}]", "instructions": "1. Mix crumbs and melted butter; press into an 8-9 inch springform pan. Freeze 15 minutes. 2. Beat cream cheese, powdered sugar, and 2 tsp vanilla until smooth. Add 1 cup cream; whip until soft peaks form. 3. Mash 1/2 cup raspberries into a sauce; swirl into cream cheese filling. Pour into crust. Refrigerate at least 8 hours. 4. Make berry sauce: simmer 1 cup raspberries with lemon juice and 1 tbsp honey 2-3 minutes. Stir in cornstarch dissolved in 2 tbsp water; boil 1 minute. Strain; cool completely. 5. Whip remaining 1 cup cream with remaining 1 tsp vanilla and 2 tbsp honey to soft peaks. 6. Remove from pan. Spoon berry sauce on top; pile with fresh berries and dollop with whipped cream.", "tags": "no-bake, summer, make-ahead", "source": "https://www.halfbakedharvest.com/no-bake-eton-mess-berry-cheesecake/", "nutritionData": "{\"calories\": 576, \"protein\": 6.0, \"carbs\": 28.0, \"fat\": 50.0}"},
  {"name": "Banana Pudding with Vanilla Wafers", "category": "Desserts", "description": "Creamy vanilla custard layered with ripe bananas and vanilla wafers for a Southern-style dessert.", "servings": 8, "prepTime": 30, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"3\", \"name\": \"large eggs plus 2 yolks\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla bean paste\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"4\", \"name\": \"ripe bananas sliced\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream for topping\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"\", \"name\": \"vanilla wafer cookies for layering\"}]", "instructions": "1. Whisk sugar, cornstarch, and salt in a saucepan. Add eggs and yolks one at a time whisking smooth. Whisk in vanilla bean paste then gradually pour in milk and then cream. 2. Bring to a simmer over medium heat, whisking constantly until thickened and bubbling; cook 1 minute more. Stir in butter and vanilla. Cool 5 minutes. 3. Lay vanilla wafers in the bottom of a 9x9-inch dish. Slice bananas over wafers. 4. Pour warm custard through a sieve over bananas. Press plastic wrap on custard surface; chill 1-2 hours until set. 5. Whip 1 cup cream with 1 tbsp sugar to soft peaks. Dollop over chilled pudding. 6. Garnish with crumbled wafers and sliced banana. Serve within a few hours.", "tags": "pudding, Southern, comfort-food", "source": "https://smittenkitchen.com/2016/01/banana-puddings-with-vanilla-bean-wafers/", "nutritionData": "{\"calories\": 463, \"protein\": 7.0, \"carbs\": 48.0, \"fat\": 28.0}"},
  {"name": "Blueberry Crisp", "category": "Desserts", "description": "Bubbling blueberry filling under a crispy oat-brown sugar topping ready in under an hour.", "servings": 8, "prepTime": 15, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6 cups\", \"name\": \"fresh blueberries\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"3/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2/3 cup\", \"name\": \"packed brown sugar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"cold unsalted butter cut into small pieces\"}]", "instructions": "1. Preheat oven to 375°F; grease a 9-inch square baking dish. 2. Toss blueberries with granulated sugar, cornstarch, lemon juice, and zest; spread in dish. 3. Make topping: combine oats, flour, brown sugar, cinnamon, and salt. Cut in cold butter until crumbly with pea-sized clumps. 4. Spread topping evenly over blueberries. 5. Bake 40-45 minutes until topping is golden and fruit is bubbling vigorously. 6. Cool at least 15 minutes before serving; best warm with vanilla ice cream.", "tags": "summer, fruit, easy", "source": "https://www.kingarthurbaking.com/recipes/blueberry-crisp-recipe", "nutritionData": "{\"calories\": 320, \"protein\": 4.0, \"carbs\": 56.0, \"fat\": 10.0}"},
  {"name": "Sticky Toffee Pudding", "category": "Desserts", "description": "Warm date sponge cake drenched in a luscious butterscotch toffee sauce for the ultimate comfort dessert.", "servings": 8, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"Medjool dates pitted and chopped\"}, {\"qty\": \"1 cup\", \"name\": \"boiling water\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3/4 cup\", \"name\": \"packed dark brown sugar\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"packed dark brown sugar for sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter for sauce\"}, {\"qty\": \"\", \"name\": \"pinch of salt for sauce\"}]", "instructions": "1. Preheat oven to 350°F; grease a 9x9-inch pan. Place chopped dates in a bowl; pour boiling water over them and stir in baking soda. Soak 10 minutes then mash slightly. 2. Whisk flour, baking powder, and salt. Beat butter and 3/4 cup brown sugar until fluffy; beat in eggs one at a time then vanilla. 3. Fold in flour mixture alternately with date mixture until just combined. Pour into pan. 4. Bake 25-30 minutes until a toothpick comes out clean. 5. Make toffee sauce: combine 1 cup brown sugar, cream, 4 tbsp butter, and a pinch of salt in a saucepan over medium heat. Stir until melted and combined; boil gently 2 minutes. 6. Poke warm cake all over with a skewer; pour half the sauce over cake. Absorb 5 minutes then slice. Serve warm drizzled with remaining sauce.", "tags": "British, pudding, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 542, \"protein\": 5.0, \"carbs\": 86.0, \"fat\": 21.0}"},
  {"name": "Vanilla Bean Ice Cream", "category": "Desserts", "description": "Custard-based homemade vanilla ice cream with a rich egg yolk base and intense vanilla flavor.", "servings": 8, "prepTime": 20, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"1\", \"name\": \"vanilla bean split and scraped\"}, {\"qty\": \"6\", \"name\": \"large egg yolks\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"pure vanilla extract\"}]", "instructions": "1. Combine milk, cream, vanilla bean pod and seeds in a saucepan; bring just to a simmer. Remove from heat; steep 15 minutes. Discard pod. 2. Whisk egg yolks, sugar, and salt until pale and slightly thick. 3. Slowly ladle warm cream into yolks while whisking to temper; return mixture to saucepan. 4. Cook over medium-low heat, stirring constantly, until custard coats the back of a spoon at 170-175°F. Do not boil. 5. Strain through a sieve into a clean bowl; stir in vanilla. Chill over an ice bath then refrigerate at least 4 hours. 6. Churn in an ice cream maker 20-25 minutes. Transfer to a container and freeze at least 2 hours until firm.", "tags": "ice cream, frozen, summer", "source": "Classic", "nutritionData": "{\"calories\": 352, \"protein\": 6.0, \"carbs\": 23.0, \"fat\": 27.0}"},
  {"name": "Half Baked Harvest Chocolate Lava Cakes", "category": "Desserts", "description": "Rich molten chocolate cakes with a flowing dark chocolate center served with vanilla ice cream.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 oz\", \"name\": \"semisweet chocolate chopped\"}, {\"qty\": \"8 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4\", \"name\": \"squares dark chocolate for center\"}, {\"qty\": \"\", \"name\": \"cocoa powder for dusting\"}, {\"qty\": \"\", \"name\": \"powdered sugar for serving\"}]", "instructions": "1. Preheat oven to 450°F. Grease four 6-oz ramekins and dust with cocoa powder; place on a baking sheet. 2. Melt butter and semisweet chocolate in microwave in 15-second increments until smooth. 3. Beat eggs, egg yolks, sugar, and vanilla on high speed 10 minutes until pale and fluffy. 4. Fold chocolate-butter into egg mixture; fold in flour until just combined. 5. Divide batter among ramekins. Press one dark chocolate square into center of each. 6. Bake 10-15 minutes until tops and sides are set but centers remain very soft. Rest 5 minutes; invert onto plates or serve in ramekins. Dust with powdered sugar; serve immediately with vanilla ice cream.", "tags": "chocolate, elegant, dinner-party", "source": "https://www.halfbakedharvest.com/chocolate-lava-cakes/", "nutritionData": "{\"calories\": 450, \"protein\": 6.0, \"carbs\": 36.0, \"fat\": 34.0}"},
  {"name": "Banana Cream Pie", "category": "Desserts", "description": "Custardy banana cream pie layered with ripe bananas in a vanilla wafer crust topped with whipped cream.", "servings": 8, "prepTime": 30, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"vanilla wafer crumbs\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"5 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"large eggs plus 2 yolks\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla bean paste\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"3\", \"name\": \"ripe bananas sliced\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream for topping\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}]", "instructions": "1. Preheat oven to 350°F. Mix wafer crumbs, 1/4 tsp salt, and melted butter; press into a 9-inch pie dish. Bake 9-10 minutes until lightly browned. Cool in refrigerator. 2. Whisk sugar, cornstarch, and remaining salt in a saucepan. Whisk in eggs and yolks one at a time; whisk in vanilla bean paste then gradually pour in milk and then cream. 3. Bring to a simmer over medium heat, whisking constantly until thickened and bubbling; cook 1 minute. Stir in butter and vanilla. Cool 5 minutes. 4. Slice bananas into the cooled crust. Strain warm custard through a sieve over bananas; press plastic wrap on surface and chill 1-2 hours. 5. Whip 1 cup cream with 1 tbsp sugar to soft peaks; spread over chilled custard. 6. Decorate with sliced banana; slice into wedges and serve within a few hours.", "tags": "pie, banana, custard", "source": "https://smittenkitchen.com/2022/03/banana-cream-pie/", "nutritionData": "{\"calories\": 535, \"protein\": 6.0, \"carbs\": 49.0, \"fat\": 36.0}"},
  {"name": "Pecan Pie Bars with Brown Butter Crust", "category": "Desserts", "description": "Brown-butter shortbread bars topped with a maple-pecan caramel filling baked into irresistible squares.", "servings": 24, "prepTime": 30, "cookTime": 43, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"unsalted butter cut into pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/2 cup\", \"name\": \"pure maple syrup\"}, {\"qty\": \"1/2 cup\", \"name\": \"packed dark brown sugar\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter for topping\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"3 cups\", \"name\": \"chopped pecans\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for sprinkling\"}]", "instructions": "1. Preheat oven to 350°F; line a 9x13-inch pan with parchment leaving overhang. 2. Brown 1 cup butter in a light-colored skillet over medium heat 5-8 minutes until golden and nutty. Pour into a bowl; cool 10 minutes. 3. Stir sugar, water, vanilla, and salt into brown butter. Mix in flour and cornstarch until no dry flour remains. Press evenly into pan; bake 15 minutes until lightly browned. 4. In the same skillet combine maple syrup, brown sugar, 6 tbsp butter, and cream; stir until butter melts. Cool 5 minutes; whisk in beaten eggs then fold in pecans. Pour over warm crust; sprinkle with flaky sea salt. 5. Bake 25-28 minutes until a toothpick comes out mostly clean. Tent with foil if browning too quickly. 6. Cool completely before lifting out and cutting into squares.", "tags": "bars, pecan, holiday", "source": "https://sallysbakingaddiction.com/brown-butter-pecan-pie-bars/", "nutritionData": "{\"calories\": 272, \"protein\": 4.0, \"carbs\": 24.0, \"fat\": 19.0}"},
  {"name": "Peanut Butter Overnight Oats", "category": "Healthy Breakfast", "description": "Creamy overnight oats with peanut butter and chia seeds for a filling make-ahead breakfast.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"gluten-free rolled oats\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"natural peanut butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"3/4 tbsp\", \"name\": \"chia seeds\"}, {\"qty\": \"1/2\", \"name\": \"banana sliced for topping\"}, {\"qty\": \"1 tbsp\", \"name\": \"granola for topping\"}]", "instructions": "1. Add almond milk, chia seeds, peanut butter, and maple syrup to a mason jar and stir to combine. 2. Add oats and stir a few more times, pressing down to ensure all oats are submerged. 3. Cover and refrigerate overnight or at least 6 hours. 4. Top with sliced banana and granola before serving. 5. Enjoy cold or microwave for 45-60 seconds if preferred warm.", "tags": "make-ahead, high-fiber, vegan", "source": "https://minimalistbaker.com/peanut-butter-overnight-oats/", "nutritionData": "{\"calories\": 576, \"protein\": 19.0, \"carbs\": 74.0, \"fat\": 26.0}"},
  {"name": "Mixed Berry Smoothie Bowl", "category": "Healthy Breakfast", "description": "A thick soft-serve smoothie base of berries and banana topped with crunchy seeds and coconut.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"frozen mixed berries\"}, {\"qty\": \"1\", \"name\": \"small ripe banana sliced and frozen\"}, {\"qty\": \"2 tbsp\", \"name\": \"light coconut milk\"}, {\"qty\": \"1\", \"name\": \"scoop vanilla protein powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"chia seeds\"}, {\"qty\": \"1 tbsp\", \"name\": \"hemp seeds\"}, {\"qty\": \"1 tbsp\", \"name\": \"shredded unsweetened coconut\"}, {\"qty\": \"1/4 cup\", \"name\": \"granola\"}]", "instructions": "1. Add frozen berries and banana to a blender and blend on low until broken into small bits. 2. Add coconut milk and protein powder and blend on low scraping down sides until thick soft-serve consistency forms. 3. Scoop into a bowl and top with chia seeds, hemp seeds, coconut, and granola. 4. Serve immediately.", "tags": "high-protein, vegan, quick", "source": "https://minimalistbaker.com/favorite-smoothie-bowl-5-minutes/", "nutritionData": "{\"calories\": 601, \"protein\": 36.0, \"carbs\": 74.0, \"fat\": 22.0}"},
  {"name": "Classic Avocado Toast", "category": "Healthy Breakfast", "description": "Simple whole-grain toast topped with mashed ripe avocado and flaky sea salt for a satisfying breakfast.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 slice\", \"name\": \"thick whole-grain bread\"}, {\"qty\": \"1/2\", \"name\": \"ripe avocado\"}, {\"qty\": \"1/8 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 pinch\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 pinch\", \"name\": \"flaky sea salt\"}]", "instructions": "1. Toast the bread until golden and firm. 2. Halve the avocado, remove pit, and scoop flesh into a bowl. 3. Add lemon juice and kosher salt and mash with a fork to desired consistency. 4. Spread avocado over the toast. 5. Finish with flaky sea salt and red pepper flakes. 6. Serve immediately.", "tags": "quick, vegan, no-cook", "source": "https://cookieandkate.com/avocado-toast-recipe/", "nutritionData": "{\"calories\": 210, \"protein\": 6.0, \"carbs\": 22.0, \"fat\": 13.0}"},
  {"name": "Basic Chia Seed Pudding", "category": "Healthy Breakfast", "description": "A silky chia pudding that sets overnight for a no-cook high-fiber breakfast with fresh toppings.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"chia seeds\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"1/2 tsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh blueberries\"}, {\"qty\": \"1 tbsp\", \"name\": \"chopped walnuts\"}]", "instructions": "1. Combine almond milk, chia seeds, maple syrup, and cinnamon in a lidded jar. 2. Seal and shake vigorously to combine. 3. Chill for 2 hours then stir well to break up clumps. 4. Cover and refrigerate 8 hours or overnight until set. 5. Top with blueberries and walnuts before serving.", "tags": "make-ahead, high-fiber, vegan", "source": "https://www.loveandlemons.com/chia-seed-pudding/", "nutritionData": "{\"calories\": 255, \"protein\": 6.0, \"carbs\": 29.0, \"fat\": 14.0}"},
  {"name": "Shakshuka with Feta", "category": "Healthy Breakfast", "description": "Eggs poached in a spiced tomato and red pepper sauce topped with crumbled feta cheese.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large yellow onion chopped\"}, {\"qty\": \"1\", \"name\": \"large red bell pepper chopped\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"28 oz\", \"name\": \"can crushed fire-roasted tomatoes\"}, {\"qty\": \"5\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled feta\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fine sea salt\"}]", "instructions": "1. Preheat oven to 375 degrees F. Warm olive oil in a large oven-safe skillet over medium heat. 2. Add onion, bell pepper, and salt; cook stirring often until softened about 5 minutes. 3. Add garlic, tomato paste, cumin, paprika, and red pepper flakes; cook stirring 1-2 minutes until fragrant. 4. Pour in crushed tomatoes and parsley; simmer 5 minutes. 5. Make wells with a spoon and crack one egg into each well; spoon a bit of sauce over the whites. 6. Transfer skillet to oven and bake 8-12 minutes until whites are set and yolks are still soft. 7. Top with crumbled feta and additional parsley; serve with crusty bread.", "tags": "gluten-free, high-protein, vegetarian", "source": "https://cookieandkate.com/foolproof-shakshuka-recipe/", "nutritionData": "{\"calories\": 267, \"protein\": 13.0, \"carbs\": 17.0, \"fat\": 17.0}"},
  {"name": "Freezer Breakfast Burritos", "category": "Healthy Breakfast", "description": "Hearty scrambled egg and veggie burritos made in bulk and frozen for quick weekday breakfasts.", "servings": 8, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"large eggs\"}, {\"qty\": \"8\", \"name\": \"burrito-size flour tortillas\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter divided\"}, {\"qty\": \"1 lb\", \"name\": \"cooked ham diced\"}, {\"qty\": \"8 oz\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"2 pinches\", \"name\": \"salt and pepper\"}]", "instructions": "1. Saute onion and bell pepper in 1/2 tbsp butter over medium heat until softened about 5 minutes; transfer to a bowl. 2. Cook ham in another 1/2 tbsp butter until browned about 5 minutes; transfer to a separate bowl. 3. Whisk eggs; melt remaining butter in skillet over medium heat; pour in eggs and scramble until just set but still moist. 4. Lay out tortillas and distribute eggs, peppers and onions, ham, and cheese evenly. 5. Fold bottom of each tortilla up, tuck in sides, and roll up tightly. 6. Wrap each burrito in parchment paper and freeze. 7. To reheat thaw overnight in fridge and microwave 1-2 minutes or air fry at 350 degrees F for 6-10 minutes.", "tags": "make-ahead, meal-prep, high-protein", "source": "https://www.budgetbytes.com/freezer-breakfast-burritos/", "nutritionData": "{\"calories\": 391, \"protein\": 27.0, \"carbs\": 15.0, \"fat\": 24.0}"},
  {"name": "Blueberry Baked Oatmeal", "category": "Healthy Breakfast", "description": "A warm wholesome baked oatmeal casserole packed with blueberries and pecans for a crowd-friendly breakfast.", "servings": 9, "prepTime": 10, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"old-fashioned rolled oats\"}, {\"qty\": \"2/3 cup\", \"name\": \"roughly chopped pecans\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"milk of choice\"}, {\"qty\": \"1/3 cup\", \"name\": \"maple syrup\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"melted coconut oil divided\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"12 oz\", \"name\": \"fresh or frozen blueberries divided\"}]", "instructions": "1. Preheat oven to 375 degrees F and grease a 9-inch square baking dish. 2. Toast pecans on a rimmed baking sheet 4-5 minutes until fragrant. 3. Whisk oats, pecans, cinnamon, baking powder, salt, and nutmeg in a bowl. 4. Whisk milk, maple syrup, eggs, half the oil, and vanilla in a smaller bowl. 5. Spread 2/3 of the blueberries in the baking dish, cover with dry oat mixture, then drizzle wet ingredients over. 6. Wiggle pan so milk seeps through; scatter remaining blueberries on top. 7. Bake 42-45 minutes until golden. Drizzle remaining oil over top before serving.", "tags": "make-ahead, vegetarian, high-fiber", "source": "https://cookieandkate.com/baked-oatmeal-recipe/", "nutritionData": "{\"calories\": 234, \"protein\": 7.0, \"carbs\": 22.0, \"fat\": 14.0}"},
  {"name": "Asparagus and Goat Cheese Frittata", "category": "Healthy Breakfast", "description": "A golden broiled frittata with shaved asparagus ribbons and creamy goat cheese.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"asparagus cleaned\"}, {\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 oz\", \"name\": \"soft goat cheese crumbled\"}, {\"qty\": \"\", \"name\": \"fresh black pepper to taste\"}]", "instructions": "1. Shave asparagus into ribbons using a vegetable peeler discarding tough ends. 2. Preheat broiler with a rack 6 inches from the heat. 3. Beat eggs with milk, salt, and pepper; stir in scallions and gently fold in asparagus ribbons. 4. Heat olive oil in a 12-inch oven-safe skillet over medium heat until fully hot. 5. Pour in egg mixture and crumble goat cheese over the top. 6. Cook on medium-low until edges are set and bottom is lightly browned, about 5 minutes. 7. Transfer to broiler and cook 1-3 minutes until top is golden and eggs are just set. 8. Let cool slightly then slice into wedges and serve.", "tags": "gluten-free, high-protein, vegetarian", "source": "https://smittenkitchen.com/2016/04/shaved-asparagus-frittata/", "nutritionData": "{\"calories\": 303, \"protein\": 18.0, \"carbs\": 5.0, \"fat\": 24.0}"},
  {"name": "Loaded Veggie Egg Muffins", "category": "Healthy Breakfast", "description": "Portable baked egg cups loaded with spinach and bell pepper for easy high-protein meal prep.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"9\", \"name\": \"large eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"thawed frozen spinach drained\"}, {\"qty\": \"3 tbsp\", \"name\": \"diced tomatoes\"}, {\"qty\": \"3 tbsp\", \"name\": \"diced onion\"}, {\"qty\": \"3 tbsp\", \"name\": \"diced bell pepper\"}, {\"qty\": \"3\", \"name\": \"strips cooked bacon chopped\"}, {\"qty\": \"2 oz\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Preheat oven to 350 degrees F and generously spray a 12-cup muffin tin with olive oil spray. 2. Whisk eggs in a large bowl and season with salt and pepper. 3. Mix in spinach, tomatoes, onion, bell pepper, and bacon. 4. Pour egg mixture evenly into muffin cups filling about 3/4 full. 5. Top each cup with shredded cheddar. 6. Place tin on a baking sheet and bake 20-25 minutes until set. 7. Cool 5-10 minutes before removing from tin.", "tags": "meal-prep, gluten-free, high-protein", "source": "https://www.skinnytaste.com/loaded-baked-omelet-muffins/", "nutritionData": "{\"calories\": 185, \"protein\": 13.0, \"carbs\": 2.0, \"fat\": 13.0}"},
  {"name": "PBJ Acai Bowl", "category": "Healthy Breakfast", "description": "A thick acai and banana smoothie base with peanut butter finished with fresh fruit and hemp seeds.", "servings": 2, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"packets frozen unsweetened acai\"}, {\"qty\": \"1 1/2\", \"name\": \"ripe bananas sliced and frozen\"}, {\"qty\": \"3 tbsp\", \"name\": \"peanut butter powder\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"1 cup\", \"name\": \"fresh spinach optional\"}, {\"qty\": \"1/2\", \"name\": \"banana sliced for topping\"}, {\"qty\": \"2 tbsp\", \"name\": \"shredded unsweetened coconut\"}, {\"qty\": \"2 tbsp\", \"name\": \"hemp seeds\"}, {\"qty\": \"1/4 cup\", \"name\": \"mixed berries\"}]", "instructions": "1. Add frozen acai, frozen banana, peanut butter powder, and almond milk to a high-speed blender. 2. Add spinach if using. 3. Blend on low using a blender wand to push fruit down, scraping sides as needed, until thick and smooth. 4. Add only as much milk as needed to achieve a thick smoothie consistency. 5. Divide between two bowls and top with sliced banana, coconut, hemp seeds, and berries. 6. Serve immediately.", "tags": "vegan, high-protein, gluten-free", "source": "https://minimalistbaker.com/pbj-acai-bowls/", "nutritionData": "{\"calories\": 286, \"protein\": 10.0, \"carbs\": 27.0, \"fat\": 16.0}"},
  {"name": "Super Green Smoothie Bowl", "category": "Healthy Breakfast", "description": "A nutrient-dense green smoothie bowl packed with spinach and kale topped with granola and seeds.", "servings": 2, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4\", \"name\": \"ripe avocado\"}, {\"qty\": \"2\", \"name\": \"medium ripe bananas frozen\"}, {\"qty\": \"1 cup\", \"name\": \"mixed frozen berries\"}, {\"qty\": \"2\", \"name\": \"large handfuls fresh spinach\"}, {\"qty\": \"1\", \"name\": \"small handful kale stems removed\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"flaxseed meal\"}, {\"qty\": \"2 tbsp\", \"name\": \"almond butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"granola\"}, {\"qty\": \"2 tbsp\", \"name\": \"hemp seeds\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh berries for topping\"}]", "instructions": "1. Add avocado, frozen bananas, frozen berries, spinach, kale, almond milk, flaxseed meal, and almond butter to a blender. 2. Blend until creamy and smooth adding more milk as needed to thin. 3. Taste and adjust sweetness with a ripe banana or a drizzle of maple syrup if needed. 4. Divide between two bowls and top with granola, hemp seeds, and fresh berries. 5. Serve immediately.", "tags": "vegan, high-fiber, gluten-free", "source": "https://minimalistbaker.com/super-green-smoothie-bowl/", "nutritionData": "{\"calories\": 510, \"protein\": 14.0, \"carbs\": 61.0, \"fat\": 28.0}"},
  {"name": "Whole Wheat Banana Bread Pancakes", "category": "Healthy Breakfast", "description": "Fluffy whole wheat pancakes made with mashed bananas and a touch of cinnamon for natural sweetness.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"whole wheat pastry flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"3\", \"name\": \"large ripe bananas mashed\"}, {\"qty\": \"2/3 cup\", \"name\": \"milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil melted\"}, {\"qty\": \"\", \"name\": \"maple syrup for serving\"}]", "instructions": "1. Whisk flour, baking powder, brown sugar, and salt in a large bowl. 2. Mash bananas in a medium bowl and add milk, vanilla, egg, and melted coconut oil; whisk to combine. 3. Fold wet ingredients into dry ingredients, stirring until a smooth batter forms; do not overmix. Let batter rest 5 minutes. 4. Heat a skillet or griddle over medium heat and lightly grease with coconut oil or spray. 5. Pour about 1/3 cup batter per pancake. Cook until bubbles form on surface about 2-3 minutes. 6. Flip and cook another 1-2 minutes until golden. 7. Serve hot with maple syrup.", "tags": "vegetarian, high-fiber, whole-grain", "source": "https://www.halfbakedharvest.com/whole-wheat-chocolate-chip-banana-bread-pancakes-with-a-vanilla-coconut-glaze/", "nutritionData": "{\"calories\": 448, \"protein\": 12.0, \"carbs\": 81.0, \"fat\": 11.0}"},
  {"name": "Egg White and Veggie Omelet", "category": "Healthy Breakfast", "description": "A high-protein omelet made with egg whites and fresh vegetables folded with melted cheddar.", "servings": 1, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"egg whites\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh spinach chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"red bell pepper chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"red onion chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Lightly beat the whole egg and egg whites with a fork in a bowl; add vegetables, salt, and pepper and mix well. 2. Heat a 9-inch nonstick skillet over medium-low heat; spray with oil. 3. Pour in egg mixture and let sit to start cooking. 4. Gently lift cooked edges with a spatula to allow uncooked egg to flow to the sides. 5. Once eggs are mostly set, scatter cheese along the center. 6. Let cheese melt briefly then fold both sides toward the center. 7. Slide onto a plate and serve immediately.", "tags": "high-protein, gluten-free, quick", "source": "https://www.skinnytaste.com/high-protein-omelet/", "nutritionData": "{\"calories\": 369, \"protein\": 30.0, \"carbs\": 6.0, \"fat\": 25.0}"},
  {"name": "Egg White Muffins with Turkey Bacon", "category": "Healthy Breakfast", "description": "Protein-packed egg white cups lined with turkey bacon and filled with colorful vegetables and cheese.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"carton egg whites\"}, {\"qty\": \"1/2 cup\", \"name\": \"2% cottage cheese\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"seasoning salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped shallots\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped scallions\"}, {\"qty\": \"1\", \"name\": \"medium red bell pepper chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped steamed broccoli\"}, {\"qty\": \"6 slices\", \"name\": \"uncured turkey bacon cut in half\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded sharp cheddar\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Preheat oven to 350 degrees F and generously spray a 12-cup muffin tin with olive oil spray. 2. Saute shallots, scallions, and bell pepper in olive oil over medium-low heat 5-6 minutes until tender. 3. Add broccoli and cook 1 more minute. 4. Whisk egg whites, cottage cheese, garlic powder, and seasoning salt in a large bowl; add cooked vegetables and stir to combine. 5. Line each muffin cup with a half slice of turkey bacon around the edges. 6. Pour in egg mixture about 1/3 cup per cup. Top with cheddar. 7. Bake 25 minutes in the center of the oven until set.", "tags": "meal-prep, high-protein, gluten-free", "source": "https://www.skinnytaste.com/egg-white-muffins/", "nutritionData": "{\"calories\": 138, \"protein\": 15.0, \"carbs\": 5.0, \"fat\": 7.0}"},
  {"name": "Golden Milk Overnight Oats", "category": "Healthy Breakfast", "description": "Anti-inflammatory turmeric-spiced overnight oats with coconut milk and almond butter.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"light coconut milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"chia seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ginger\"}, {\"qty\": \"2 tbsp\", \"name\": \"almond butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1/2 cup\", \"name\": \"gluten-free rolled oats\"}, {\"qty\": \"1/2\", \"name\": \"banana sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut flakes\"}]", "instructions": "1. Combine coconut milk, chia seeds, turmeric, cinnamon, ginger, almond butter, and maple syrup in a jar; stir until spices are incorporated. 2. Add rolled oats and stir to combine pressing down to ensure oats are submerged. 3. Cover and refrigerate overnight or at least 6 hours. 4. In the morning top with sliced banana and coconut flakes. 5. Enjoy cold or gently warmed.", "tags": "make-ahead, vegan, anti-inflammatory", "source": "https://minimalistbaker.com/golden-milk-overnight-oats/", "nutritionData": "{\"calories\": 667, \"protein\": 17.0, \"carbs\": 68.0, \"fat\": 39.0}"},
  {"name": "Greek Yogurt Parfait", "category": "Healthy Breakfast", "description": "Layered Greek yogurt with fresh berries and honey-sweetened granola for a quick high-protein breakfast.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1/2 cup\", \"name\": \"mixed berries\"}, {\"qty\": \"1/4 cup\", \"name\": \"granola\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"chia seeds\"}, {\"qty\": \"1/4 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Mix Greek yogurt with vanilla extract. 2. Spoon half the yogurt into a glass or bowl. 3. Add half the berries and a sprinkle of granola. 4. Repeat layers with remaining yogurt and berries. 5. Drizzle with honey and top with remaining granola and chia seeds. 6. Serve immediately or refrigerate up to 1 day.", "tags": "high-protein, quick, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 581, \"protein\": 29.0, \"carbs\": 65.0, \"fat\": 25.0}"},
  {"name": "Savory Breakfast Quinoa Bowl", "category": "Healthy Breakfast", "description": "A hearty bowl of cooked quinoa topped with soft-boiled eggs and sauteed spinach with avocado and feta.", "servings": 2, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"cooked quinoa\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"6\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/2\", \"name\": \"ripe avocado sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"crumbled feta cheese\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"red pepper flakes to taste\"}]", "instructions": "1. Bring a small pot of water to a gentle simmer; lower eggs in and cook 7 minutes for jammy yolks. Transfer to ice water to cool then peel and halve. 2. Heat olive oil in a small skillet over medium heat; add garlic and cook 30 seconds. 3. Add spinach and tomatoes; cook stirring until spinach wilts about 2-3 minutes. 4. Divide quinoa between bowls. Top with sauteed spinach and tomatoes, avocado slices, and halved eggs. 5. Crumble feta over top and season with salt, pepper, and red pepper flakes. 6. Serve immediately.", "tags": "gluten-free, high-protein, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 380, \"protein\": 16.0, \"carbs\": 35.0, \"fat\": 21.0}"},
  {"name": "Brussels Sprout and Bacon Frittata", "category": "Healthy Breakfast", "description": "A rich broiled frittata with crispy bacon and tender brussels sprouts with melted Gruyere cheese.", "servings": 6, "prepTime": 10, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"bacon diced\"}, {\"qty\": \"2\", \"name\": \"small shallots halved and thinly sliced\"}, {\"qty\": \"3/4 lb\", \"name\": \"brussels sprouts halved and sliced 1/4 inch thick\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper to taste\"}, {\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Gruyere cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"snipped chives divided\"}]", "instructions": "1. Preheat broiler with rack 6 inches from heat. 2. Cook bacon in a 10-inch oven-safe skillet over medium-high heat until almost crisp about 5 minutes. 3. Add shallots and cook until softened about 3 minutes. 4. Add brussels sprouts, season with salt and pepper, and cook tossing until crisp-tender and lightly browned about 5 minutes. 5. Beat eggs with milk, salt, and pepper in a bowl; stir in cheese and half the chives. 6. Pour egg mixture into skillet; cook over moderate heat stirring gently until eggs start to set then cook until bottom is lightly browned about 5 more minutes. 7. Transfer to broiler and cook until top is deep golden and eggs are just set about 5 minutes. 8. Scatter remaining chives over top and slice into 6 wedges to serve.", "tags": "gluten-free, high-protein, meal-prep", "source": "https://smittenkitchen.com/2020/12/brussels-sprout-and-bacon-frittata/", "nutritionData": "{\"calories\": 412, \"protein\": 30.0, \"carbs\": 7.0, \"fat\": 29.0}"},
  {"name": "Sweet Potato and Black Bean Grain Bowl", "category": "Healthy Breakfast", "description": "A nourishing bowl of roasted sweet potatoes and black beans over bulgur with green tahini sauce.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"dry bulgur\"}, {\"qty\": \"2 cups\", \"name\": \"cubed sweet potatoes\"}, {\"qty\": \"1 cup\", \"name\": \"canned black beans rinsed\"}, {\"qty\": \"1\", \"name\": \"ripe avocado sliced\"}, {\"qty\": \"1\", \"name\": \"jalapeno thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"pepitas\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"3 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 clove\", \"name\": \"garlic\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}]", "instructions": "1. Toast dry bulgur in a saucepan over medium heat 2-3 minutes; add 2 cups water, bring to a boil, cover, and simmer 12 minutes; rest 5 minutes then fluff. 2. Preheat oven to 400 degrees F; toss sweet potato cubes with olive oil, salt, and pepper on a baking sheet; roast 30 minutes until tender. 3. Blend cilantro, tahini, lemon juice, garlic, and water until smooth to make the green tahini sauce; season with salt. 4. Rinse and drain black beans. Slice avocado and jalapeno. 5. Divide bulgur among four bowls; top with sweet potatoes, black beans, avocado, and jalapeno. 6. Sprinkle pepitas over each bowl and drizzle generously with green tahini sauce.", "tags": "vegan, high-fiber, meal-prep", "source": "https://www.budgetbytes.com/sweet-potato-grain-bowls-green-tahini-sauce/", "nutritionData": "{\"calories\": 356, \"protein\": 12.0, \"carbs\": 41.0, \"fat\": 18.0}"},
  {"name": "Cottage Cheese Breakfast Bowl", "category": "Healthy Breakfast", "description": "A protein-rich cottage cheese bowl with blueberries and almonds finished with a drizzle of honey.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"2% cottage cheese\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh blueberries\"}, {\"qty\": \"2 tbsp\", \"name\": \"sliced almonds\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}]", "instructions": "1. Stir vanilla extract into cottage cheese. 2. Transfer to a bowl and top with blueberries and almonds. 3. Drizzle honey over top and dust with cinnamon. 4. Serve immediately or refrigerate up to 2 days.", "tags": "high-protein, quick, gluten-free", "source": "https://www.budgetbytes.com/cottage-cheese-breakfast-bowls-6-ways/", "nutritionData": "{\"calories\": 219, \"protein\": 14.0, \"carbs\": 36.0, \"fat\": 3.0}"},
  {"name": "Chocolate Overnight Oats", "category": "Healthy Breakfast", "description": "Rich cocoa overnight oats with almond butter that taste indulgent but fuel your morning with fiber.", "servings": 1, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"\", \"name\": \"1-2 tbsp almond butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"\", \"name\": \"1-2 tsp chia seeds\"}, {\"qty\": \"1/4 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"2 tbsp\", \"name\": \"cocoa powder\"}, {\"qty\": \"1 pinch\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"raspberries for topping\"}]", "instructions": "1. Add almond milk, almond butter, maple syrup, chia seeds, and vanilla to a mason jar; stir to combine. 2. Add oats, cocoa powder, and salt; mix well until cocoa powder is fully incorporated. 3. Press down with a spoon to ensure all oats are submerged. 4. Seal and refrigerate overnight or at least 6 hours. 5. In the morning stir and top with fresh raspberries. 6. Enjoy cold or microwave briefly to warm.", "tags": "make-ahead, vegan, high-fiber", "source": "https://minimalistbaker.com/chocolate-overnight-oats/", "nutritionData": "{\"calories\": 470, \"protein\": 16.0, \"carbs\": 60.0, \"fat\": 20.0}"},
  {"name": "Homemade Maple Pecan Granola", "category": "Healthy Breakfast", "description": "Crunchy oven-baked oat and pecan granola sweetened with maple syrup for healthy parfaits and bowls.", "servings": 16, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"old-fashioned rolled oats\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"raw pecans and pepitas mixed\"}, {\"qty\": \"1 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 cup\", \"name\": \"melted coconut oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"maple syrup\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2/3 cup\", \"name\": \"dried cranberries\"}]", "instructions": "1. Preheat oven to 350 degrees F and line a large rimmed baking sheet with parchment paper. 2. Combine oats, nuts and seeds, salt, and cinnamon in a large bowl and stir to blend. 3. Add coconut oil, maple syrup, and vanilla; mix well until every oat is coated. 4. Spread onto prepared pan in an even layer. 5. Bake 21-24 minutes stirring halfway until lightly golden. 6. Let cool completely undisturbed for at least 45 minutes. 7. Stir in dried cranberries; break into clusters and store in an airtight container.", "tags": "vegan, make-ahead, high-fiber", "source": "https://cookieandkate.com/healthy-granola-recipe/", "nutritionData": "{\"calories\": 157, \"protein\": 4.0, \"carbs\": 17.0, \"fat\": 9.0}"},
  {"name": "Spinach and Feta Scrambled Eggs", "category": "Healthy Breakfast", "description": "Fluffy scrambled eggs folded with wilted spinach and tangy feta for a fast protein-packed breakfast.", "servings": 2, "prepTime": 5, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"fresh baby spinach\"}, {\"qty\": \"1/4 cup\", \"name\": \"crumbled feta cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Whisk eggs and milk together in a bowl; season with salt and pepper. 2. Melt butter in a nonstick skillet over medium-low heat; add garlic and cook 30 seconds. 3. Add spinach and cook until just wilted about 1 minute. 4. Pour in egg mixture and let sit briefly then gently fold and pull eggs toward center to form soft curds. 5. Remove from heat while still slightly underdone. 6. Fold in crumbled feta and serve immediately on toast or alone.", "tags": "quick, high-protein, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 251, \"protein\": 15.0, \"carbs\": 3.0, \"fat\": 19.0}"},
  {"name": "Avocado Egg Toast with Everything Bagel Seasoning", "category": "Healthy Breakfast", "description": "Toasted whole-grain bread topped with mashed avocado and a fried egg finished with everything bagel seasoning.", "servings": 1, "prepTime": 5, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 slice\", \"name\": \"whole-grain bread\"}, {\"qty\": \"1/2\", \"name\": \"ripe avocado\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"everything bagel seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"pinch red pepper flakes\"}]", "instructions": "1. Toast bread until golden and firm. 2. Mash avocado in a small bowl with lemon juice, salt, and pepper. 3. Heat olive oil in a small nonstick skillet over medium heat; crack egg in and cook until whites are set and yolk is runny about 3 minutes. 4. Spread mashed avocado on toast. 5. Place fried egg on top and sprinkle with everything bagel seasoning and red pepper flakes. 6. Serve immediately.", "tags": "high-protein, quick, whole-grain", "source": "Classic", "nutritionData": "{\"calories\": 322, \"protein\": 12.0, \"carbs\": 22.0, \"fat\": 22.0}"},
  {"name": "Banana Oat Pancakes", "category": "Healthy Breakfast", "description": "Light gluten-free pancakes blended from rolled oats and ripe banana with no flour needed.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"rolled oats\"}, {\"qty\": \"1\", \"name\": \"ripe banana\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1\", \"name\": \"egg white\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"coconut oil or butter for cooking\"}]", "instructions": "1. Add all ingredients to a blender in order: almond milk, eggs, egg white, banana, maple syrup, vanilla, oats, baking powder, and salt. 2. Blend until completely smooth. 3. Let batter rest 5 minutes while heating a skillet over medium heat. 4. Grease skillet lightly with coconut oil and pour batter into rounds. 5. Cook 2-3 minutes until bubbles form on surface; flip and cook 1-2 minutes more until golden. 6. Serve with maple syrup and fresh fruit.", "tags": "gluten-free, high-fiber, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 230, \"protein\": 9.0, \"carbs\": 33.0, \"fat\": 7.0}"},
  {"name": "Mango Coconut Chia Pudding", "category": "Healthy Breakfast", "description": "Tropical chia pudding made with coconut milk and topped with fresh mango for a vibrant no-cook breakfast.", "servings": 2, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"chia seeds\"}, {\"qty\": \"1 cup\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1/4 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"fresh mango diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"toasted coconut flakes\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}]", "instructions": "1. Whisk chia seeds, coconut milk, maple syrup, and vanilla in a jar or bowl. 2. Refrigerate 2 hours then stir well to break up clumps. 3. Return to fridge and chill overnight until thick and set. 4. Toss diced mango with lime juice. 5. Spoon chia pudding into bowls and top with mango and toasted coconut flakes. 6. Serve chilled.", "tags": "vegan, make-ahead, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 532, \"protein\": 11.0, \"carbs\": 45.0, \"fat\": 37.0}"},
  {"name": "Turkey Sausage and Sweet Potato Hash", "category": "Healthy Breakfast", "description": "A hearty skillet hash of roasted sweet potatoes and turkey sausage topped with fried eggs.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium sweet potatoes peeled and diced\"}, {\"qty\": \"12 oz\", \"name\": \"turkey breakfast sausage casings removed\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion diced\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Heat 1 tbsp olive oil in a large cast-iron skillet over medium-high heat. 2. Add sweet potato cubes, season with paprika, garlic powder, salt, and pepper; cook turning occasionally until tender and caramelized about 12 minutes. 3. Push potatoes to the side; add remaining oil and cook turkey sausage breaking it up until browned about 5 minutes. 4. Add bell pepper and onion; cook until softened about 4 minutes. 5. Mix everything together and make 4 wells; crack an egg into each well. 6. Cover and cook until egg whites are set about 4-5 minutes. 7. Garnish with parsley and serve.", "tags": "gluten-free, high-protein, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 462, \"protein\": 19.0, \"carbs\": 20.0, \"fat\": 34.0}"},
  {"name": "Spinach and Mushroom Breakfast Burrito", "category": "Healthy Breakfast", "description": "A protein-rich whole-grain wrap filled with scrambled eggs and sauteed mushrooms with fresh salsa.", "servings": 2, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2\", \"name\": \"whole-wheat flour tortillas\"}, {\"qty\": \"1 cup\", \"name\": \"baby bella mushrooms sliced\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded Monterey jack cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"salsa\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Heat olive oil in a nonstick skillet over medium heat; add mushrooms and cook until browned about 4 minutes. 2. Add spinach and cumin; cook stirring until spinach wilts about 2 minutes. Transfer to a bowl. 3. Whisk eggs with salt and pepper; pour into the same skillet over medium-low heat and scramble gently until just set. 4. Warm tortillas briefly in a dry pan or microwave. 5. Divide eggs, mushroom mixture, and cheese between tortillas. 6. Top each with salsa then fold up the bottom, tuck in the sides, and roll to close. 7. Serve immediately.", "tags": "high-protein, whole-grain, quick", "source": "Classic", "nutritionData": "{\"calories\": 492, \"protein\": 23.0, \"carbs\": 52.0, \"fat\": 20.0}"},
  {"name": "Strawberry Almond Butter Yogurt Parfait", "category": "Healthy Breakfast", "description": "Creamy Greek yogurt layered with fresh strawberries and granola with an almond butter drizzle.", "servings": 2, "prepTime": 8, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1 cup\", \"name\": \"fresh strawberries sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"granola\"}, {\"qty\": \"2 tbsp\", \"name\": \"almond butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Stir vanilla and cinnamon into Greek yogurt. 2. Warm almond butter in a microwave 15-20 seconds until drizzleable. 3. Spoon half the yogurt into two glasses or bowls. 4. Layer half the strawberries and granola over the yogurt. 5. Repeat with remaining yogurt, strawberries, and granola. 6. Drizzle honey and almond butter over the top. 7. Serve immediately.", "tags": "high-protein, quick, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 492, \"protein\": 23.0, \"carbs\": 49.0, \"fat\": 24.0}"},
  {"name": "Kale and White Bean Breakfast Bowl", "category": "Healthy Breakfast", "description": "A savory bowl of sauteed kale and cannellini beans over farro with a poached egg and lemon.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"cooked farro\"}, {\"qty\": \"1 can\", \"name\": \"cannellini beans rinsed and drained\"}, {\"qty\": \"4 cups\", \"name\": \"lacinato kale stems removed and chopped\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"shaved Parmesan\"}]", "instructions": "1. Warm farro if needed and divide between two bowls. 2. Heat 1 tbsp olive oil over medium heat; add garlic and red pepper flakes and cook 30 seconds. 3. Add kale and beans; cook tossing until kale wilts and beans are warmed through about 5 minutes. Season with salt and pepper. 4. Bring a shallow pot of water to a gentle simmer; add a splash of vinegar. Crack eggs into separate cups and slide into water; poach 3-4 minutes until whites are set. 5. Top each farro bowl with kale-bean mixture and a poached egg. 6. Drizzle with remaining olive oil and lemon juice; top with shaved Parmesan.", "tags": "high-fiber, high-protein, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 559, \"protein\": 28.0, \"carbs\": 62.0, \"fat\": 22.0}"},
  {"name": "Sheet Pan Greek Chicken and Vegetables", "category": "Healthy Dinner", "description": "Lemon-garlic marinated chicken breast roasted with bell peppers and tomatoes topped with feta and olives.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1\", \"name\": \"pint grape tomatoes\"}, {\"qty\": \"2\", \"name\": \"bell peppers chopped\"}, {\"qty\": \"1\", \"name\": \"small red onion chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"lemon juiced and zested\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"kalamata olives halved\"}, {\"qty\": \"2 oz\", \"name\": \"crumbled feta\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Preheat oven to 400°F. Whisk together olive oil, lemon juice, garlic, oregano, salt, and pepper; reserve lemon zest. 2. Toss tomatoes, bell peppers, and onion on a large baking sheet with half the marinade; roast 10 minutes. 3. Pound chicken breasts to even 3/4-inch thickness and cut each in half; toss with remaining marinade. 4. Push vegetables to the sides of the sheet pan and add chicken to the center. 5. Bake 20–25 minutes until chicken reaches 165°F; broil 5 minutes for extra browning. 6. Top with olives, feta, lemon zest, and fresh parsley before serving.", "tags": "high-protein, sheet-pan, mediterranean", "source": "https://www.budgetbytes.com/sheet-pan-greek-chicken-and-vegetables/", "nutritionData": "{\"calories\": 512, \"protein\": 57.0, \"carbs\": 12.0, \"fat\": 26.0}"},
  {"name": "Slow Cooker Chicken Taco Bowls", "category": "Healthy Dinner", "description": "Tender shredded chicken slow-cooked with salsa and black beans served over rice.", "servings": 6, "prepTime": 10, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"16 oz\", \"name\": \"jar chunky salsa\"}, {\"qty\": \"15 oz\", \"name\": \"can black beans drained\"}, {\"qty\": \"1/2 lb\", \"name\": \"frozen corn\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"6 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}]", "instructions": "1. Place chicken breasts in the bottom of a 6-quart slow cooker. 2. Add black beans, salsa, corn, water, garlic, chili powder, cumin, oregano, cayenne, and pepper; stir briefly. 3. Cook on low for 8 hours or high for 4 hours. 4. Cook rice according to package directions; time to finish with slow cooker. 5. Shred chicken using two forks; stir to combine with the cooking liquid. Taste and add salt if needed. 6. Build bowls with 1 cup rice, 1 cup chicken mixture, shredded cheese, and sliced green onions.", "tags": "high-protein, slow-cooker, meal-prep", "source": "https://www.budgetbytes.com/taco-chicken-bowls/", "nutritionData": "{\"calories\": 742, \"protein\": 58.0, \"carbs\": 84.0, \"fat\": 18.0}"},
  {"name": "Chicken Stir Fry with Broccoli and Peppers", "category": "Healthy Dinner", "description": "Quick weeknight stir-fry with tender chicken and crisp vegetables in a savory sesame-ginger sauce.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"boneless skinless chicken breasts cut into 1/2-inch pieces\"}, {\"qty\": \"3/4 lb\", \"name\": \"broccoli florets\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"small yellow onion sliced\"}, {\"qty\": \"2\", \"name\": \"carrots sliced\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"3 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"1/3 cup\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tsp\", \"name\": \"sriracha\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/3 cup\", \"name\": \"water\"}]", "instructions": "1. Whisk together soy sauce, brown sugar, sesame oil, garlic, ginger, sriracha, cornstarch, and water; set aside. 2. Heat large wok or skillet over medium-high; add 2 tbsp oil. Add chicken; cook until browned, about 5–7 minutes. Remove to a plate. 3. Add remaining oil; add carrots and broccoli. Cook and stir 1 minute until broccoli turns bright green. 4. Add bell pepper and onion; cook and stir 1–2 minutes more. 5. Return chicken to skillet; pour sauce over everything and stir. 6. Simmer 1–2 minutes until sauce thickens and turns glossy. Top with green onions and serve over rice.", "tags": "high-protein, stir-fry, quick", "source": "https://www.budgetbytes.com/chicken-stir-fry/", "nutritionData": "{\"calories\": 355, \"protein\": 28.0, \"carbs\": 26.0, \"fat\": 16.0}"},
  {"name": "Turkey Meatballs with Marinara", "category": "Healthy Dinner", "description": "Baked lean turkey meatballs seasoned with Italian herbs and served over your favorite sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce for serving\"}]", "instructions": "1. Preheat oven to 400°F; line a baking sheet with parchment paper. 2. Combine breadcrumbs, Parmesan, Italian seasoning, garlic powder, onion powder, salt, and pepper in a bowl. 3. In a large bowl, combine ground turkey and egg; add breadcrumb mixture. Mix with hands until just combined; do not overmix. 4. Divide and shape into 16 meatballs (about 2 tbsp each). Place on prepared baking sheet. 5. Bake 20 minutes until cooked through and internal temperature reaches 165°F. 6. Warm marinara sauce and serve meatballs over pasta or zucchini noodles.", "tags": "lean-protein, baked, meal-prep", "source": "https://www.budgetbytes.com/turkey-meatballs/", "nutritionData": "{\"calories\": 367, \"protein\": 32.0, \"carbs\": 26.0, \"fat\": 15.0}"},
  {"name": "One Pot Chicken and Rice", "category": "Healthy Dinner", "description": "Seasoned chicken thighs seared then simmered over fluffy rice in one skillet for a complete meal.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"1 cup\", \"name\": \"long-grain white rice uncooked\"}, {\"qty\": \"1.75 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Mix paprika, oregano, thyme, garlic powder, onion powder, salt, and pepper; coat both sides of chicken. 2. Heat 1 tbsp oil in deep skillet over medium; sear chicken 5 minutes per side until browned. Remove to a plate. 3. Add remaining oil and onion; sauté 5 minutes until softened, scraping up browned bits. 4. Add rice; sauté 1–2 minutes until lightly toasted. 5. Add broth; stir. Return chicken on top of rice. Cover, bring to boil, then reduce to low; simmer 20 minutes without lifting lid. 6. Turn off heat; rest 5 minutes. Fluff rice and garnish with parsley.", "tags": "one-pot, high-protein, weeknight", "source": "https://www.budgetbytes.com/one-pot-chicken-and-rice/", "nutritionData": "{\"calories\": 544, \"protein\": 39.0, \"carbs\": 44.0, \"fat\": 22.0}"},
  {"name": "Sheet Pan Lemon Balsamic Chicken and Potatoes", "category": "Healthy Dinner", "description": "Balsamic-marinated chicken and baby potatoes roasted together with briny olives and a creamy feta sauce.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"boneless skinless chicken breasts or thighs\"}, {\"qty\": \"1 lb\", \"name\": \"baby potatoes halved\"}, {\"qty\": \"4 tbsp\", \"name\": \"plus 1/3 cup olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh oregano chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic chopped\"}, {\"qty\": \"1\", \"name\": \"shallot chopped\"}, {\"qty\": \"1/4 tsp\", \"name\": \"chili flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 cup\", \"name\": \"mixed fresh herbs dill or basil\"}, {\"qty\": \"1 cup\", \"name\": \"green olives torn\"}, {\"qty\": \"1 cup\", \"name\": \"tzatziki sauce\"}, {\"qty\": \"6 oz\", \"name\": \"feta cheese crumbled\"}]", "instructions": "1. Preheat oven to 425°F. Toss potatoes with 2 tbsp olive oil on a large sheet pan; season with salt and pepper. 2. In a bowl, combine 2 tbsp olive oil, balsamic, Dijon, oregano, paprika, garlic, shallot, salt, pepper, and chili flakes; add chicken and toss. 3. Nestle chicken among potatoes on the sheet pan. 4. Bake 25–30 minutes until chicken is cooked through to 165°F. 5. Mix remaining 1/3 cup olive oil with lemon juice, herbs, and olives. Mix tzatziki with crumbled feta. 6. Spoon herby olive mixture over chicken; serve with tzatziki-feta sauce.", "tags": "sheet-pan, mediterranean, high-protein", "source": "https://www.halfbakedharvest.com/lemon-balsamic-chicken-and-potatoes/", "nutritionData": "{\"calories\": 646, \"protein\": 54.0, \"carbs\": 20.0, \"fat\": 38.0}"},
  {"name": "Sheet Pan Chicken Tzatziki with Sweet Potatoes", "category": "Healthy Dinner", "description": "Spiced chicken and roasted sweet potatoes served bowl-style with tzatziki and honey garlic tahini.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breasts or thighs cubed\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3\", \"name\": \"small sweet potatoes sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"tahini\"}, {\"qty\": \"1 clove\", \"name\": \"garlic grated\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tsp\", \"name\": \"honey\"}, {\"qty\": \"1 cup\", \"name\": \"tzatziki sauce\"}, {\"qty\": \"2 oz\", \"name\": \"crumbled feta\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}]", "instructions": "1. Preheat oven to 450°F; rub a baking sheet with oil. 2. Toss chicken with paprika, oregano, garlic powder, onion powder, turmeric, salt, pepper, and 2 tbsp olive oil on one side of sheet pan. 3. Add sweet potatoes to the other side; toss with remaining oil, salt, and pepper. 4. Bake 15–20 minutes until chicken is cooked through; toss and cook 5 more minutes until crisp. 5. Make tahini sauce by whisking tahini, garlic, lemon juice, honey, and 1/4 cup water until smooth; season with salt. 6. Serve chicken and sweet potatoes over rice with tzatziki, tahini sauce, feta, and sesame seeds.", "tags": "sheet-pan, high-protein, mediterranean", "source": "https://www.halfbakedharvest.com/sheet-pan-chicken-tzatziki/", "nutritionData": "{\"calories\": 860, \"protein\": 82.0, \"carbs\": 30.0, \"fat\": 45.0}"},
  {"name": "One Pan Lemon Pepper Yogurt Chicken and Rice", "category": "Healthy Dinner", "description": "Greek yogurt marinated chicken baked over fluffy basmati rice and broccoli all in one pan.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"bone-in or boneless chicken thighs or breasts\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1/3 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon zest\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic chopped\"}, {\"qty\": \"1.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1.75 cups\", \"name\": \"dry basmati rice\"}, {\"qty\": \"2 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"2 cups\", \"name\": \"roughly chopped broccoli\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}]", "instructions": "1. Toss chicken with olive oil, yogurt, lemon zest, garlic, pepper, oregano, thyme, paprika, onion powder, and salt. Marinate 30 minutes if time allows. 2. Preheat oven to 400°F. 3. Pour rice and broccoli into a 9×13-inch baking dish; add water and dot with butter. 4. Arrange marinated chicken over the rice and broccoli. 5. Bake 30–40 minutes until rice is fluffy and chicken reaches 165°F. If rice seems dry, add 1/3 cup water and bake 10 more minutes. 6. Serve topped with fresh basil or thyme.", "tags": "one-pan, high-protein, meal-prep", "source": "https://www.halfbakedharvest.com/lemon-pepper-yogurt-chicken/", "nutritionData": "{\"calories\": 923, \"protein\": 69.0, \"carbs\": 74.0, \"fat\": 36.0}"},
  {"name": "One Skillet Greek Lemon Chicken and Rice", "category": "Healthy Dinner", "description": "Seared chicken thighs finished in the oven over toasted orzo and rice with olives and feta.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry orzo\"}, {\"qty\": \"1 cup\", \"name\": \"jasmine rice\"}, {\"qty\": \"2\", \"name\": \"shallots chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"lemon sliced\"}, {\"qty\": \"3 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"1 cup\", \"name\": \"green olives\"}, {\"qty\": \"4 oz\", \"name\": \"crumbled feta\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil\"}]", "instructions": "1. Preheat oven to 425°F. In a large oven-safe skillet, combine 1 tbsp olive oil, chicken, oregano, paprika, cayenne, 1 tbsp thyme, salt, and pepper; toss to coat. 2. Set skillet over high heat; sear chicken 3–5 minutes per side until golden. Remove from skillet. 3. Add butter, orzo, rice, shallots, garlic, and remaining thyme; cook until toasted, about 3 minutes. Add butter and lemon slices; let butter brown. 4. Pour in broth; stir in spinach. Season with salt and pepper; bring to a boil. Return chicken to skillet. 5. Cover; reduce heat to lowest setting; cook 10 minutes. Bake uncovered 10–15 minutes until chicken is cooked through. 6. Top with feta, olives, lemon juice, basil, and a drizzle of olive oil; serve.", "tags": "one-skillet, mediterranean, high-protein", "source": "https://www.halfbakedharvest.com/lemon-chicken-and-rice/", "nutritionData": "{\"calories\": 745, \"protein\": 44.0, \"carbs\": 33.0, \"fat\": 48.0}"},
  {"name": "Pork Tenderloin with Herb Seasoning", "category": "Healthy Dinner", "description": "Herb-crusted pork tenderloin seared golden then finished in the oven to juicy perfection.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"pork tenderloins (1 lb each)\"}, {\"qty\": \"1.5 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"granulated garlic\"}, {\"qty\": \"2 tsp\", \"name\": \"herbes de Provence\"}, {\"qty\": \"4 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"white wine or chicken stock\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme chopped\"}]", "instructions": "1. Preheat oven to 400°F. Trim silver skin from each tenderloin; pat dry. 2. Mix salt, pepper, granulated garlic, and herbes de Provence; rub evenly over pork. 3. Heat oil in a large oven-proof skillet over medium-high until shimmering. Add tenderloins; cook undisturbed 5 minutes until golden. Flip and cook 3 more minutes. 4. Add wine or stock; cook 1 minute. Transfer pan to oven. 5. Bake 15–19 minutes until internal temperature reaches 145°F. 6. Transfer to cutting board; rest 5–10 minutes before slicing. Serve with pan juices.", "tags": "lean-protein, oven-roasted, quick", "source": "https://www.allrecipes.com/the-best-easy-pork-tenderloin-recipe-7485158", "nutritionData": "{\"calories\": 376, \"protein\": 60.0, \"carbs\": 2.0, \"fat\": 13.0}"},
  {"name": "Mediterranean Turkey Meatball Sheet Pan Dinner", "category": "Healthy Dinner", "description": "Herb-packed turkey meatballs baked alongside lemon-dressed peppers and zucchini on one pan.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"2/3 cup\", \"name\": \"plain breadcrumbs\"}, {\"qty\": \"1/3 cup\", \"name\": \"shallot finely chopped\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"each fresh rosemary oregano dill and mint chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2\", \"name\": \"lemon juiced and zested\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper sliced\"}, {\"qty\": \"1/2\", \"name\": \"red onion sliced\"}, {\"qty\": \"1\", \"name\": \"zucchini sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled feta\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped tomatoes\"}]", "instructions": "1. Preheat oven to 400°F; line a baking sheet with parchment. 2. Mix together parsley, rosemary, oregano, dill, mint, salt, and pepper; reserve 2 tbsp for vegetables. 3. Add breadcrumbs, shallot, garlic, and lemon zest to herb bowl; whisk egg with 1 tbsp oil and add. Add ground turkey; mix until just combined. 4. Shape into 18 meatballs; arrange on sheet pan; spray lightly with oil. Bake 15 minutes. 5. Toss bell peppers, onion, and zucchini with lemon juice, reserved herbs, and 1 tbsp oil; scatter around meatballs. 6. Return to oven 15 more minutes until vegetables are tender and meatballs reach 165°F. Top with feta and tomatoes.", "tags": "sheet-pan, lean-protein, mediterranean", "source": "https://www.allrecipes.com/mediterranean-turkey-meatball-sheet-pan-dinner-recipe-7562426", "nutritionData": "{\"calories\": 438, \"protein\": 33.0, \"carbs\": 24.0, \"fat\": 24.0}"},
  {"name": "Sheet Pan Honey Buffalo Chicken with Broccoli", "category": "Healthy Dinner", "description": "Crispy baked chicken tossed in a sweet-hot buffalo sauce alongside perfectly roasted broccoli.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"chicken breasts or thighs cubed\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cups\", \"name\": \"broccoli florets\"}, {\"qty\": \"1/2 cup\", \"name\": \"hot sauce\"}, {\"qty\": \"6 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"seasoned salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"honey\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}, {\"qty\": \"\", \"name\": \"ranch or blue cheese dressing for serving\"}]", "instructions": "1. Preheat oven to 450°F; line a baking sheet with parchment. 2. Toss chicken with paprika, onion powder, garlic powder, salt, and pepper. Add flour; toss again. Add 2 tbsp oil; toss to coat. 3. Arrange chicken on one side of the pan; toss broccoli with remaining oil on the other side. 4. Bake 15–20 minutes until chicken is cooked through. 5. Meanwhile melt hot sauce, butter, seasoned salt, and cayenne in a saucepan. Remove from heat and stir in honey. 6. Remove broccoli from pan; pour buffalo sauce over chicken and toss. Bake 5 more minutes. Serve with green onions and ranch dressing.", "tags": "sheet-pan, high-protein, spicy", "source": "https://www.halfbakedharvest.com/honey-buffalo-chicken/", "nutritionData": "{\"calories\": 781, \"protein\": 74.0, \"carbs\": 32.0, \"fat\": 39.0}"},
  {"name": "Greek Lemon Chicken and Potatoes", "category": "Healthy Dinner", "description": "Classic roasted chicken thighs and potatoes bathed in lemon olive oil and oregano for a robust one-pan dinner.", "servings": 4, "prepTime": 15, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"skin-on bone-in chicken thighs\"}, {\"qty\": \"3\", \"name\": \"russet potatoes peeled and quartered\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"Greek olive oil\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 pinch\", \"name\": \"cayenne\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth divided\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh oregano for garnish\"}]", "instructions": "1. Preheat oven to 425°F; lightly oil a large roasting pan. 2. Combine lemon juice, olive oil, garlic, dried oregano, salt, rosemary, pepper, and cayenne in a large bowl. Add chicken and potatoes; toss to coat. 3. Place chicken skin-side up in the roasting pan; tuck potatoes around chicken; drizzle with 2/3 cup broth. Spoon any remaining marinade over top. 4. Bake 20 minutes; toss chicken and potatoes. Place chicken skin-side up again; bake another 25 minutes until browned and 165°F at the bone. 5. Transfer chicken to platter. Toss potatoes with pan juices; broil 3 minutes until crisped. 6. Deglaze pan with remaining 1/3 cup broth; strain pan juices over chicken and potatoes. Garnish with fresh oregano.", "tags": "sheet-pan, high-protein, mediterranean", "source": "https://www.allrecipes.com/recipe/242352/greek-lemon-chicken-and-potatoes/", "nutritionData": "{\"calories\": 1321, \"protein\": 122.0, \"carbs\": 28.0, \"fat\": 78.0}"},
  {"name": "BBQ Chicken Burrito Bowls", "category": "Healthy Dinner", "description": "Smoky BBQ chicken over rice with black beans corn and avocado makes a colorful and satisfying bowl.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"cooked chicken breast shredded\"}, {\"qty\": \"1/2 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"4 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"15 oz\", \"name\": \"can black beans drained and rinsed\"}, {\"qty\": \"1 cup\", \"name\": \"frozen corn thawed\"}, {\"qty\": \"1\", \"name\": \"small zucchini diced\"}, {\"qty\": \"4 oz\", \"name\": \"pepper jack cheese shredded\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"1\", \"name\": \"small avocado pitted and sliced\"}]", "instructions": "1. Shred or chop chicken breast and toss with 2–3 tbsp BBQ sauce until well coated. 2. Drain and rinse black beans. Dice zucchini into 1/4-inch cubes. Shred cheese, slice green onions, and slice avocado. 3. Prepare 4 cups cooked rice if not already ready. 4. Build each bowl: place 1 cup rice in the bottom. 5. Divide chicken, beans, corn, zucchini, cheese, green onions, and avocado evenly among the four bowls. 6. Drizzle 1 tbsp BBQ sauce over each bowl and serve immediately or refrigerate for meal prep.", "tags": "high-protein, meal-prep, quick", "source": "https://www.budgetbytes.com/bbq-chicken-burrito-bowls/", "nutritionData": "{\"calories\": 675, \"protein\": 36.0, \"carbs\": 98.0, \"fat\": 16.0}"},
  {"name": "Sweet and Spicy Chicken Bowl", "category": "Healthy Dinner", "description": "Honey-spiced chicken with pineapple and black beans over brown rice in a vibrant weeknight bowl.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"boneless skinless chicken breast (3/4 lb) cubed\"}, {\"qty\": \"1 cup\", \"name\": \"uncooked brown rice\"}, {\"qty\": \"1.75 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"mild chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/2 tsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"8 oz\", \"name\": \"can pineapple tidbits drained\"}, {\"qty\": \"15 oz\", \"name\": \"can black beans rinsed\"}, {\"qty\": \"1\", \"name\": \"ripe avocado sliced\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"1/4\", \"name\": \"bunch fresh cilantro\"}]", "instructions": "1. Cook rice in chicken broth: bring to boil, cover, simmer 25 minutes on low; rest 10 minutes off heat then fluff. 2. Mix chili powder, cumin, paprika, garlic powder, cayenne, salt, olive oil, honey, and apple cider vinegar in a bowl. 3. Add cubed chicken to spice mix; toss until coated. Set aside. 4. Prepare toppings: drain pineapple and chop smaller, rinse beans, slice green onions, cube avocado, chop cilantro. 5. Heat non-stick skillet over medium; cook chicken 5–7 minutes until cooked through and slightly caramelized. 6. Build bowls with 3/4 cup rice, then chicken, beans, pineapple, avocado, green onions, and cilantro.", "tags": "high-protein, bowl, weeknight", "source": "https://www.budgetbytes.com/sweet-n-spicy-chicken-bowls/", "nutritionData": "{\"calories\": 617, \"protein\": 50.0, \"carbs\": 71.0, \"fat\": 15.0}"},
  {"name": "Baked Chicken Breasts and Vegetables", "category": "Healthy Dinner", "description": "Simple Italian-seasoned chicken breasts baked alongside carrots celery and bell peppers for an easy one-pan dinner.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless skinless chicken breast halves\"}, {\"qty\": \"8\", \"name\": \"carrots sliced into rounds\"}, {\"qty\": \"8\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"8\", \"name\": \"green onions chopped\"}, {\"qty\": \"4\", \"name\": \"green bell peppers sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh flat-leaf parsley chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 375°F. 2. Arrange chicken breasts in the center of a large baking sheet. 3. Spread carrots, celery, green onion, and bell peppers around the chicken. 4. Drizzle olive oil over chicken and vegetables evenly. 5. Season everything with Italian seasoning, chili powder, lemon pepper, salt, and black pepper. 6. Bake 30 minutes until chicken is no longer pink and an instant-read thermometer reads 165°F. Sprinkle with fresh parsley before serving.", "tags": "sheet-pan, lean-protein, quick", "source": "https://www.allrecipes.com/recipe/236110/baked-chicken-breasts-and-vegetables/", "nutritionData": "{\"calories\": 606, \"protein\": 51.0, \"carbs\": 26.0, \"fat\": 34.0}"},
  {"name": "Turkey Stuffed Bell Peppers", "category": "Healthy Dinner", "description": "Colorful bell peppers filled with seasoned ground turkey and rice baked until tender and topped with melted cheese.", "servings": 6, "prepTime": 20, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"bell peppers halved horizontally\"}, {\"qty\": \"2 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 cup\", \"name\": \"marinara sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"long-grain white rice uncooked\"}, {\"qty\": \"3/4 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1.25 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Preheat oven to 350°F. Cut peppers in half horizontally; remove seeds. Brush with 1 tbsp oil; season inside with salt and pepper; bake 20 minutes to soften. 2. Heat remaining oil in a large skillet over medium; brown ground turkey. 3. Add onion and garlic; sauté until onion is translucent. 4. Add uncooked rice, marinara, Italian seasoning, garlic powder, 1 tsp salt, and chicken broth; stir; cover and bring to a boil. Reduce heat; simmer 20 minutes without lifting lid. Rest 5 minutes. 5. Fluff and stir filling; spoon into pepper halves. Top each with mozzarella; cover loosely with foil and bake 15 minutes. 6. Remove foil; broil 2–3 minutes until cheese is golden. Garnish with parsley.", "tags": "lean-protein, baked, family-friendly", "source": "https://www.budgetbytes.com/stuffed-bell-peppers/", "nutritionData": "{\"calories\": 344, \"protein\": 24.0, \"carbs\": 25.0, \"fat\": 16.0}"},
  {"name": "Slow Cooker White Bean Chicken Chili", "category": "Healthy Dinner", "description": "Hearty and creamy white bean chili with tender pulled chicken and green chiles slow-cooked for deep flavor.", "servings": 6, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"2 cans\", \"name\": \"(15 oz each) white cannellini beans drained\"}, {\"qty\": \"4 oz\", \"name\": \"can diced green chiles\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1 cup\", \"name\": \"frozen corn\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"\", \"name\": \"sour cream and shredded cheese for serving\"}]", "instructions": "1. Add chicken breasts to the bottom of a slow cooker. 2. Add beans, green chiles, onion, garlic, broth, cumin, oregano, chili powder, and salt; stir. 3. Cook on low 6–8 hours or high 3–4 hours until chicken is very tender. 4. Remove chicken; shred with two forks. 5. Stir cream cheese and corn into the slow cooker; return shredded chicken. Cook 15 more minutes on high until cream cheese is fully incorporated and corn is warmed. 6. Add lime juice and cilantro; taste and adjust seasoning. Serve with sour cream and shredded cheese.", "tags": "slow-cooker", "source": "Classic", "nutritionData": "{\"calories\": 541, \"protein\": 51.0, \"carbs\": 48.0, \"fat\": 16.0}"},
  {"name": "Grilled Chicken Thighs with Chimichurri", "category": "Healthy Dinner", "description": "Juicy grilled chicken thighs finished with a bright herb-packed chimichurri sauce for a summer dinner.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 cup\", \"name\": \"fresh flat-leaf parsley packed\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/3 cup\", \"name\": \"olive oil for chimichurri\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt for chimichurri\"}]", "instructions": "1. Pat chicken dry and coat with olive oil; season all over with salt, pepper, paprika, and garlic powder. Let sit 15 minutes at room temperature. 2. Preheat grill to medium-high heat (400–450°F); clean and oil grates. 3. Grill chicken skin-side down 5–7 minutes until skin is crispy. Flip and grill 10–12 minutes more until internal temperature reaches 165°F. Rest 5 minutes. 4. Make chimichurri: pulse parsley, cilantro, garlic, red wine vinegar, red pepper flakes, and salt in a food processor; slowly drizzle in olive oil until combined but still textured. 5. Serve chicken thighs topped generously with chimichurri.", "tags": "grilled, high-protein, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 865, \"protein\": 78.0, \"carbs\": 2.0, \"fat\": 58.0}"},
  {"name": "Sheet Pan Sausage and Vegetables", "category": "Healthy Dinner", "description": "Sliced turkey sausage and a rainbow of vegetables roasted together on one pan with smoky seasonings.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"links turkey or chicken sausage sliced\"}, {\"qty\": \"2 cups\", \"name\": \"broccoli florets\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"yellow bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"red onion sliced\"}, {\"qty\": \"2 cups\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Preheat oven to 425°F. Line a large baking sheet with parchment paper. 2. Slice sausages into 1/2-inch rounds. Slice bell peppers and onion. 3. Spread sausage, broccoli, peppers, onion, and cherry tomatoes on the baking sheet in a single layer. 4. Drizzle with olive oil; sprinkle with garlic powder, Italian seasoning, paprika, salt, and pepper. Toss to coat. 5. Roast 20–25 minutes until vegetables are tender and slightly caramelized. Stir halfway through. 6. Garnish with fresh basil and serve immediately as-is or over rice or pasta.", "tags": "sheet-pan, one-pan, quick", "source": "Classic", "nutritionData": "{\"calories\": 305, \"protein\": 18.0, \"carbs\": 16.0, \"fat\": 20.0}"},
  {"name": "Ground Turkey and Zucchini Skillet", "category": "Healthy Dinner", "description": "A fast and satisfying skillet meal of seasoned ground turkey with zucchini and tomatoes over rice.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"2\", \"name\": \"medium zucchini diced\"}, {\"qty\": \"1 can\", \"name\": \"(14.5 oz) diced tomatoes\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"cooked brown rice\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil\"}]", "instructions": "1. Heat olive oil in a large skillet over medium-high heat. Add onion; sauté 3 minutes until softened. 2. Add garlic; cook 1 minute. Add ground turkey; cook 5–7 minutes, breaking up with spoon, until no longer pink. 3. Add Italian seasoning, cumin, paprika, salt, and pepper; stir. 4. Add diced tomatoes (with juices) and zucchini; stir to combine. 5. Reduce heat to medium; simmer 8–10 minutes until zucchini is tender and flavors meld. 6. Taste and adjust seasoning. Serve over brown rice and top with fresh basil.", "tags": "lean-protein, quick, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 369, \"protein\": 29.0, \"carbs\": 30.0, \"fat\": 15.0}"},
  {"name": "Slow Cooker Chicken and Sweet Potato Stew", "category": "Healthy Dinner", "description": "Warming stew of tender chicken thighs and sweet potatoes in a lightly spiced tomato broth.", "servings": 4, "prepTime": 15, "cookTime": 360, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"2\", \"name\": \"large sweet potatoes peeled and cubed\"}, {\"qty\": \"1 can\", \"name\": \"(14.5 oz) diced tomatoes\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1.5 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) chickpeas drained\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro\"}]", "instructions": "1. Place chicken thighs in the bottom of a slow cooker. 2. Add sweet potatoes, onion, garlic, diced tomatoes, and chicken broth. 3. Sprinkle cumin, paprika, cinnamon, salt, and pepper over the top; stir gently. 4. Cook on low 6 hours or high 3 hours until chicken is cooked through and sweet potatoes are tender. 5. Shred chicken using two forks; return to pot. Add chickpeas and stir. 6. Cook on high 15 more minutes to warm chickpeas. Serve in bowls garnished with fresh cilantro.", "tags": "slow-cooker, high-protein, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 484, \"protein\": 48.0, \"carbs\": 27.0, \"fat\": 19.0}"},
  {"name": "Baked Lemon Herb Chicken Thighs", "category": "Healthy Dinner", "description": "Aromatic lemon and herb marinated chicken thighs baked until golden with a beautiful pan sauce.", "servings": 4, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon zest\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"lemon slices for garnish\"}]", "instructions": "1. Combine olive oil, lemon juice, lemon zest, garlic, rosemary, thyme, oregano, salt, and pepper in a bowl. Add chicken; toss to coat. Marinate 15 minutes minimum. 2. Preheat oven to 425°F. 3. Heat an oven-proof skillet over medium-high. Sear chicken thighs skin-side down 3–4 minutes until golden; flip and sear 2 more minutes. 4. Add chicken broth to skillet. Transfer to oven; bake 20–25 minutes until internal temperature reaches 165°F. 5. Remove chicken; set skillet over medium heat. Whisk butter into pan juices until glossy. 6. Serve chicken with pan sauce drizzled over top and lemon slices alongside.", "tags": "high-protein, baked, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 561, \"protein\": 52.0, \"carbs\": 2.0, \"fat\": 38.0}"},
  {"name": "Turkey and Quinoa Stuffed Portobello Mushrooms", "category": "Healthy Dinner", "description": "Hearty portobello caps filled with seasoned ground turkey and quinoa then baked with Parmesan.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large portobello mushroom caps stems removed\"}, {\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"1/2 cup\", \"name\": \"quinoa cooked\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 can\", \"name\": \"(14.5 oz) diced tomatoes drained\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded Parmesan\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}]", "instructions": "1. Preheat oven to 400°F. Place mushroom caps gill-side up on a baking sheet; brush with olive oil; season with salt and pepper. Pre-bake 10 minutes. 2. Cook quinoa per package directions if not already prepared. 3. Heat olive oil in a skillet; sauté onion 3 minutes; add garlic and cook 1 minute. 4. Add ground turkey; cook 6–8 minutes until cooked through; break into crumbles. Season with Italian seasoning, paprika, salt, and pepper. 5. Stir in drained tomatoes and cooked quinoa. Remove from heat. 6. Spoon turkey-quinoa filling into mushroom caps; top with Parmesan. Bake 15 minutes until cheese melts. Garnish with parsley.", "tags": "lean-protein, gluten-free, baked", "source": "Classic", "nutritionData": "{\"calories\": 345, \"protein\": 35.0, \"carbs\": 12.0, \"fat\": 18.0}"},
  {"name": "Chicken Fajita Sheet Pan Bake", "category": "Healthy Dinner", "description": "Colorful sheet pan chicken fajitas with smoky sliced chicken and charred peppers ready in under 30 minutes.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts sliced into strips\"}, {\"qty\": \"3\", \"name\": \"bell peppers (assorted colors) sliced\"}, {\"qty\": \"1\", \"name\": \"large red onion sliced\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"8\", \"name\": \"small flour tortillas warmed\"}, {\"qty\": \"\", \"name\": \"salsa avocado and sour cream for serving\"}]", "instructions": "1. Preheat oven to 425°F. Line a large baking sheet with parchment. 2. Mix chili powder, cumin, paprika, garlic powder, onion powder, salt, and pepper; toss with chicken strips, peppers, and onion in a bowl. Drizzle with olive oil; toss again. 3. Spread evenly in a single layer on the baking sheet; do not crowd. 4. Bake 20–22 minutes until chicken is cooked through and vegetables are slightly charred at the edges. 5. Squeeze lime juice over everything. 6. Serve in warm tortillas topped with salsa, sliced avocado, and sour cream.", "tags": "sheet-pan, high-protein, quick", "source": "Classic", "nutritionData": "{\"calories\": 724, \"protein\": 63.0, \"carbs\": 57.0, \"fat\": 26.0}"},
  {"name": "Chicken and Vegetable Soup", "category": "Healthy Dinner", "description": "Nourishing homemade chicken soup loaded with vegetables and herbs for a comforting weeknight dinner.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"3\", \"name\": \"medium carrots sliced\"}, {\"qty\": \"3\", \"name\": \"stalks celery sliced\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2\", \"name\": \"medium potatoes peeled and cubed\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"6 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Sauté onion, carrots, and celery 5 minutes until softened. 2. Add garlic; cook 1 minute. 3. Add chicken breasts, broth, potatoes, thyme, parsley, bay leaf, salt, and pepper. Bring to a boil. 4. Reduce heat; simmer 20 minutes until chicken is cooked through and potatoes are tender. 5. Remove chicken and shred with two forks; return to pot. Add frozen peas. 6. Cook 5 more minutes until peas are heated through. Remove bay leaf; taste and adjust seasoning. Serve hot.", "tags": "one-pot, high-protein, comforting", "source": "Classic", "nutritionData": "{\"calories\": 321, \"protein\": 41.0, \"carbs\": 21.0, \"fat\": 7.0}"},
  {"name": "Pork and Vegetable Fried Rice", "category": "Healthy Dinner", "description": "Lean pork tenderloin with colorful vegetables tossed in a light soy-sesame sauce for a quick healthy fried rice.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"pork tenderloin cut into small pieces\"}, {\"qty\": \"3 cups\", \"name\": \"cooked and cooled brown rice\"}, {\"qty\": \"2\", \"name\": \"eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas and carrots\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ginger powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"cooking oil\"}]", "instructions": "1. Season pork pieces with salt and pepper. Heat 1 tbsp oil in large wok or skillet over high heat; cook pork 4–5 minutes until cooked through; remove to plate. 2. Add 1 tbsp oil; scramble beaten eggs until just set; push to side. 3. Add remaining oil; stir-fry garlic, peas and carrots, and bell pepper 2–3 minutes. 4. Add cold rice; stir-fry 3–4 minutes, pressing against pan to allow crisping. 5. Return pork to wok with vegetables and rice. Add soy sauce, oyster sauce, sesame oil, and ginger; toss everything together. 6. Cook 2 more minutes; taste and adjust seasoning. Top with green onions and serve.", "tags": "lean-protein, stir-fry, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 498, \"protein\": 38.0, \"carbs\": 42.0, \"fat\": 19.0}"},
  {"name": "Baked Turkey Breast with Roasted Root Vegetables", "category": "Healthy Dinner", "description": "Herb-seasoned turkey breast roasted alongside colorful root vegetables for an easy celebratory dinner.", "servings": 6, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"boneless turkey breast\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3\", \"name\": \"medium carrots peeled and cut into chunks\"}, {\"qty\": \"2\", \"name\": \"parsnips peeled and cut into chunks\"}, {\"qty\": \"2\", \"name\": \"medium beets peeled and cubed\"}, {\"qty\": \"1\", \"name\": \"red onion quartered\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}]", "instructions": "1. Preheat oven to 350°F. Combine 2 tbsp olive oil, rosemary, thyme, garlic, salt, and pepper; rub all over turkey breast. 2. Toss carrots, parsnips, beets, and onion with remaining 1 tbsp olive oil; season with salt and pepper. 3. Spread vegetables in a large roasting pan; pour in chicken broth. 4. Set turkey breast on top of vegetables. 5. Roast 75–90 minutes until turkey reaches 165°F internal temperature, basting with pan juices every 30 minutes. 6. Let turkey rest 10 minutes before slicing. Serve with roasted vegetables and pan juices.", "tags": "lean-protein, baked, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 386, \"protein\": 59.0, \"carbs\": 16.0, \"fat\": 9.0}"},
  {"name": "Cauliflower Chicken Casserole", "category": "Healthy Dinner", "description": "Creamy and comforting chicken casserole with roasted cauliflower and a lightened-up cheese sauce.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts cubed\"}, {\"qty\": \"1\", \"name\": \"large head cauliflower cut into florets\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded sharp cheddar\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}]", "instructions": "1. Preheat oven to 400°F. Toss cauliflower with 1 tbsp olive oil; season with salt and pepper; roast on a baking sheet 15–20 minutes until golden. 2. Meanwhile heat remaining oil in oven-proof skillet; cook chicken pieces 5–6 minutes until browned. Season with garlic powder, paprika, thyme, salt, and pepper. 3. Add garlic; cook 1 minute. Pour in broth; bring to simmer. 4. Stir in Greek yogurt until smooth. Add roasted cauliflower; toss to combine. 5. Sprinkle cheddar and mozzarella on top. 6. Bake uncovered 15–20 minutes until cheese is bubbly and golden. Garnish with chives and serve.", "tags": "high-protein, casserole, baked", "source": "Classic", "nutritionData": "{\"calories\": 519, \"protein\": 66.0, \"carbs\": 11.0, \"fat\": 22.0}"},
  {"name": "Ginger Sesame Ground Turkey Bowls", "category": "Healthy Dinner", "description": "Savory ground turkey seasoned with ginger and sesame served over brown rice with crisp cucumber.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"3 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"hoisin sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"3 cups\", \"name\": \"cooked brown rice\"}, {\"qty\": \"1\", \"name\": \"cucumber diced\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"1 tbsp\", \"name\": \"sriracha optional\"}, {\"qty\": \"\", \"name\": \"shredded carrots for topping\"}]", "instructions": "1. Whisk soy sauce, hoisin, rice vinegar, sesame oil, ginger, garlic, cornstarch, and water in a small bowl; set sauce aside. 2. Heat a large skillet over medium-high heat. Add ground turkey; cook 6–8 minutes breaking into crumbles until no longer pink. 3. Pour sauce over turkey; stir well and cook 2–3 minutes until sauce thickens and glazes the meat. 4. Prepare rice and toppings. 5. Build bowls with a base of brown rice. 6. Top with glazed turkey, cucumber, shredded carrots, green onions, and sesame seeds. Drizzle with sriracha if desired.", "tags": "lean-protein, quick, asian-inspired", "source": "Classic", "nutritionData": "{\"calories\": 458, \"protein\": 32.0, \"carbs\": 44.0, \"fat\": 18.0}"},
  {"name": "Quinoa Chickpea Salad", "category": "Healthy Lunch", "description": "Bright lemony quinoa salad with chickpeas, cucumber, bell pepper, and fresh parsley tossed in a zesty dressing.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas rinsed and drained\"}, {\"qty\": \"1\", \"name\": \"medium cucumber seeded and chopped\"}, {\"qty\": \"1\", \"name\": \"medium red bell pepper chopped\"}, {\"qty\": \"3/4 cup\", \"name\": \"chopped red onion\"}, {\"qty\": \"1 cup\", \"name\": \"finely chopped flat-leaf parsley\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper to taste\"}]", "instructions": "1. Combine rinsed quinoa and water in a saucepan and bring to a boil over medium-high heat. 2. Reduce heat to a gentle simmer and cook uncovered until quinoa absorbs all water about 15 minutes. 3. Remove from heat cover and let rest 5 minutes then fluff with a fork and cool. 4. In a large bowl combine chickpeas cucumber bell pepper onion and parsley. 5. In a small bowl whisk together olive oil lemon juice vinegar garlic and salt. 6. Once quinoa is mostly cool add to the bowl and drizzle dressing over top. 7. Toss thoroughly season with black pepper and rest 5-10 minutes before serving.", "tags": "high-protein, meal-prep, vegetarian", "source": "https://cookieandkate.com/best-quinoa-salad-recipe/", "nutritionData": "{\"calories\": 417, \"protein\": 14.0, \"carbs\": 52.0, \"fat\": 17.0}"},
  {"name": "Greek Chicken Wraps", "category": "Healthy Lunch", "description": "Juicy marinated grilled chicken thighs tucked into flatbreads with hummus, cucumber, tomato, and a creamy dill yogurt sauce.", "servings": 4, "prepTime": 40, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1 tsp\", \"name\": \"dried dill\"}, {\"qty\": \"1 cup\", \"name\": \"grape tomatoes halved\"}, {\"qty\": \"1\", \"name\": \"medium cucumber diced\"}, {\"qty\": \"1/4\", \"name\": \"small red onion thinly sliced\"}, {\"qty\": \"4\", \"name\": \"flatbreads or large pitas\"}, {\"qty\": \"1/4 cup\", \"name\": \"hummus\"}]", "instructions": "1. Combine olive oil lemon juice garlic oregano salt and pepper in a zip bag and add chicken thighs to marinate at least 30 minutes. 2. Stir together Greek yogurt dried dill a squeeze of lemon juice and a pinch of salt to make the sauce and set aside. 3. Soak sliced red onion in ice water 5-10 minutes then drain to mellow the flavor. 4. Cook marinated chicken in a skillet over medium heat 5-7 minutes per side until browned and cooked through. 5. Rest chicken 5 minutes then slice. 6. Smear each flatbread with hummus then pile on sliced chicken tomatoes cucumber and onion. 7. Add dollops of dill yogurt sauce wrap tightly and serve.", "tags": "high-protein, meal-prep, mediterranean", "source": "https://www.budgetbytes.com/greek-chicken-wraps/", "nutritionData": "{\"calories\": 678, \"protein\": 48.0, \"carbs\": 28.0, \"fat\": 34.0}"},
  {"name": "Crunchy Thai Peanut Quinoa Salad", "category": "Healthy Lunch", "description": "Shredded purple cabbage, carrots, and snap peas tossed with quinoa in a vibrant sesame peanut dressing.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"water\"}, {\"qty\": \"2 cups\", \"name\": \"shredded purple cabbage\"}, {\"qty\": \"1 cup\", \"name\": \"grated carrot\"}, {\"qty\": \"1 cup\", \"name\": \"thinly sliced snow peas\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped cilantro\"}, {\"qty\": \"1/4 cup\", \"name\": \"sliced green onion\"}, {\"qty\": \"1/4 cup\", \"name\": \"roasted salted peanuts chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"smooth peanut butter\"}, {\"qty\": \"3 tbsp\", \"name\": \"reduced-sodium soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"1/2\", \"name\": \"lime juiced\"}, {\"qty\": \"\", \"name\": \"pinch of red pepper flakes\"}]", "instructions": "1. Rinse quinoa and combine with water in a pot over medium heat. Bring to a gentle boil then simmer 10-15 minutes until water is absorbed. 2. Cover and let rest 5 minutes then fluff and set aside to cool. 3. Whisk together peanut butter and soy sauce until smooth adding a splash of water if too thick. 4. Whisk in maple syrup sesame oil lime juice and red pepper flakes. 5. In a large bowl combine cooled quinoa cabbage carrot snow peas cilantro and green onion. 6. Pour peanut sauce over salad and toss until everything is coated. 7. Taste and adjust seasoning then divide into bowls and garnish with chopped peanuts.", "tags": "vegan, make-ahead, high-fiber", "source": "https://cookieandkate.com/thai-peanut-quinoa-salad-recipe/", "nutritionData": "{\"calories\": 359, \"protein\": 14.0, \"carbs\": 41.0, \"fat\": 17.0}"},
  {"name": "Chicken Lettuce Wraps", "category": "Healthy Lunch", "description": "Savory ground chicken stir-fried with hoisin sauce, water chestnuts, and bell pepper served in crisp iceberg lettuce cups.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground chicken\"}, {\"qty\": \"1 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1 can\", \"name\": \"8 oz water chestnuts drained and diced\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped roasted peanuts\"}, {\"qty\": \"1/4 cup\", \"name\": \"hoisin sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh grated ginger\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"8\", \"name\": \"large iceberg lettuce leaves\"}]", "instructions": "1. In a small bowl stir together hoisin sauce soy sauce rice vinegar sesame oil ginger and garlic to make the sauce. 2. Heat oil in a large skillet over medium heat and add ground chicken breaking it up as it cooks until browned. 3. Add diced bell pepper and water chestnuts to the skillet and saute 2 minutes. 4. Pour sauce into skillet and stir well cooking another 2 minutes. 5. Remove from heat and top with sliced green onions and chopped peanuts. 6. Spoon about 1/3 cup chicken filling into each lettuce cup and serve immediately.", "tags": "low-carb, high-protein, quick", "source": "https://www.budgetbytes.com/chicken-lettuce-wraps/", "nutritionData": "{\"calories\": 349, \"protein\": 25.0, \"carbs\": 16.0, \"fat\": 20.0}"},
  {"name": "Everyday Lentil Soup", "category": "Healthy Lunch", "description": "Hearty one-pot lentil soup with carrots, celery, kale, and fresh herbs ready in about 35 minutes.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2\", \"name\": \"small shallots diced\"}, {\"qty\": \"4\", \"name\": \"large carrots thinly sliced\"}, {\"qty\": \"4\", \"name\": \"stalks celery thinly sliced\"}, {\"qty\": \"3 cups\", \"name\": \"baby potatoes roughly chopped\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"green or brown lentils rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"chopped kale\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary or thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"fresh parsley for serving\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat and add garlic shallots carrots and celery. 2. Season with salt and pepper and saute 4-5 minutes until slightly tender. 3. Add potatoes stir and cook 2 minutes more. 4. Pour in vegetable broth and add rosemary or thyme then increase heat to medium-high and bring to a rolling simmer. 5. Add lentils stir and once simmering again reduce heat to low. Simmer uncovered 15-20 minutes until lentils and potatoes are tender. 6. Stir in chopped kale cover and cook 3-4 minutes to wilt. 7. Taste and adjust seasoning then serve garnished with fresh parsley.", "tags": "vegan, high-fiber, meal-prep", "source": "https://minimalistbaker.com/1-pot-everyday-lentil-soup/", "nutritionData": "{\"calories\": 397, \"protein\": 17.0, \"carbs\": 63.0, \"fat\": 7.0}"},
  {"name": "Herbed Quinoa Chickpea Salad", "category": "Healthy Lunch", "description": "Fluffy quinoa with chickpeas, spinach, fresh herbs, and feta tossed in a creamy lemon-tahini dressing.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas rinsed and drained\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"chopped baby spinach\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped flat-leaf parsley\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped cilantro\"}, {\"qty\": \"1/3 cup\", \"name\": \"chopped green onion\"}, {\"qty\": \"1/3 cup\", \"name\": \"crumbled feta\"}, {\"qty\": \"1/3 cup\", \"name\": \"toasted pepitas\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sea salt\"}]", "instructions": "1. Cook quinoa in water by bringing to a boil then simmering 15 minutes until water is absorbed. Remove from heat cover and rest 5 minutes then fluff. 2. Toast pepitas in a dry skillet over medium heat stirring frequently about 5 minutes until fragrant. 3. Whisk together olive oil lemon juice tahini garlic salt and pepper to make the dressing. 4. Combine cooked quinoa chickpeas spinach parsley cilantro green onion feta and pepitas in a large bowl. 5. Drizzle all the dressing over the salad and toss to combine. 6. Serve immediately or refrigerate up to 3 days.", "tags": "vegetarian, high-protein, make-ahead", "source": "https://cookieandkate.com/herbed-quinoa-chickpea-salad-recipe/", "nutritionData": "{\"calories\": 576, \"protein\": 20.0, \"carbs\": 57.0, \"fat\": 30.0}"},
  {"name": "Golden Curry Lentil Soup", "category": "Healthy Lunch", "description": "Fragrant one-pot red lentil soup simmered with carrots, ginger, coconut milk, and warm curry spices.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"1/4 cup\", \"name\": \"thinly sliced shallot\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"minced ginger\"}, {\"qty\": \"1\", \"name\": \"small serrano pepper seeded and minced\"}, {\"qty\": \"2 cups\", \"name\": \"thinly sliced carrots\"}, {\"qty\": \"3 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"3/4 cup\", \"name\": \"canned light coconut milk\"}, {\"qty\": \"1 cup\", \"name\": \"red lentils rinsed\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"1 tbsp\", \"name\": \"curry powder\"}, {\"qty\": \"\", \"name\": \"sea salt to taste\"}, {\"qty\": \"\", \"name\": \"fresh cilantro and lime for serving\"}]", "instructions": "1. Heat a large pot over medium heat and add water and shallot. Saute 3 minutes stirring frequently until softened. 2. Add garlic ginger and serrano and saute 2-3 minutes more. 3. Add carrots and a pinch of salt and stir cooking 1-2 minutes. 4. Pour in vegetable broth and coconut milk and increase heat to medium-high to bring to a low boil. 5. Add lentils coconut aminos and curry powder and stir. Reduce heat to a gentle simmer and cook uncovered 12-16 minutes until carrots and lentils are tender. 6. Taste and adjust seasoning then divide into bowls and garnish with cilantro and lime juice.", "tags": "vegan, gluten-free, high-fiber", "source": "https://minimalistbaker.com/1-pot-golden-curry-lentil-soup/", "nutritionData": "{\"calories\": 253, \"protein\": 13.0, \"carbs\": 38.0, \"fat\": 4.0}"},
  {"name": "Sushi Bowl with Sriracha Mayo", "category": "Healthy Lunch", "description": "Seasoned sushi rice topped with imitation crab, avocado, cucumber, carrots, nori, and a drizzle of sriracha mayo.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"short grain white rice\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"8 oz\", \"name\": \"imitation crab shredded\"}, {\"qty\": \"1\", \"name\": \"carrot julienned\"}, {\"qty\": \"1\", \"name\": \"cucumber sliced into matchsticks\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1\", \"name\": \"pack nori snacks crumbled\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"4 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"2 tbsp\", \"name\": \"sriracha\"}]", "instructions": "1. Rinse rice and combine with 2 cups water in a pot. Bring to boil then reduce to low and simmer covered 15 minutes. Turn off heat and rest covered 10 minutes then fluff. 2. Stir together rice vinegar sugar and salt until dissolved and fold into cooked rice. 3. Whisk together mayonnaise and sriracha to make spicy mayo. 4. Prepare toppings: shred crab julienne carrot slice cucumber and avocado. 5. Divide seasoned rice among four bowls. 6. Top each bowl with crab carrot cucumber avocado nori pieces and sesame seeds. 7. Drizzle with sriracha mayo and serve.", "tags": "pescatarian, make-ahead, grain-bowl", "source": "https://www.budgetbytes.com/sushi-bowls-sriracha-mayo/", "nutritionData": "{\"calories\": 591, \"protein\": 13.0, \"carbs\": 89.0, \"fat\": 20.0}"},
  {"name": "Shawarma Sheet Pan Chicken Bowl", "category": "Healthy Lunch", "description": "Spiced chicken thighs roasted on a sheet pan with chickpeas and vegetables served over grains with tzatziki or tahini.", "servings": 4, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"boneless skinless chicken thighs cut into 1-inch pieces\"}, {\"qty\": \"1\", \"name\": \"small red onion cut into pieces\"}, {\"qty\": \"1\", \"name\": \"red bell pepper cut into pieces\"}, {\"qty\": \"2\", \"name\": \"carrots cut into 1/4-inch pieces\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas rinsed and drained\"}, {\"qty\": \"1 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"3/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"cooked farro or brown rice\"}, {\"qty\": \"\", \"name\": \"tzatziki or tahini for serving\"}]", "instructions": "1. Preheat oven to 425 degrees F. 2. Add chicken veggies and chickpeas to a large mixing bowl and drizzle with olive oil. 3. Season with all spices and salt and toss to evenly combine. 4. Transfer mixture onto a rimmed baking sheet in an even layer. 5. Roast 30-35 minutes until chicken is cooked through and vegetables are tender. 6. Broil the last 2 minutes for extra char if desired. 7. Serve over farro or brown rice with tzatziki or tahini sauce on the side.", "tags": "high-protein, gluten-free, meal-prep", "source": "https://www.skinnytaste.com/chicken-shawarma-sheet-pan-dinner/", "nutritionData": "{\"calories\": 660, \"protein\": 55.0, \"carbs\": 51.0, \"fat\": 23.0}"},
  {"name": "Turkey Taco Lettuce Wraps", "category": "Healthy Lunch", "description": "Lean ground turkey seasoned with Mexican spices and served in crisp iceberg lettuce cups for a low-carb protein-packed lunch.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.3 lbs\", \"name\": \"99% lean ground turkey\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"oregano\"}, {\"qty\": \"1/2\", \"name\": \"small onion minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"bell pepper minced\"}, {\"qty\": \"3/4 cup\", \"name\": \"water\"}, {\"qty\": \"1 can\", \"name\": \"4 oz tomato sauce\"}, {\"qty\": \"8\", \"name\": \"large iceberg lettuce leaves\"}, {\"qty\": \"\", \"name\": \"optional toppings shredded cheese salsa avocado\"}]", "instructions": "1. Heat a large skillet over medium heat and add ground turkey onion and bell pepper. Cook breaking up meat until browned about 5-7 minutes. 2. Drain excess fat if needed. 3. Add garlic powder cumin salt chili powder paprika and oregano and stir to coat. 4. Pour in water and tomato sauce and stir to combine. 5. Simmer uncovered 5 minutes until sauce reduces and thickens. 6. Spoon filling into lettuce leaves and serve with optional toppings like cheese salsa or avocado.", "tags": "low-carb, gluten-free, high-protein", "source": "https://www.skinnytaste.com/turkey-taco-lettuce-wraps-3-pts/", "nutritionData": "{\"calories\": 179, \"protein\": 36.0, \"carbs\": 2.0, \"fat\": 2.0}"},
  {"name": "Roasted Sweet Potato Buddha Bowl", "category": "Healthy Lunch", "description": "Nourishing bowl of roasted sweet potato, chickpeas, greens, quinoa, avocado, and tahini dressing for a filling plant-based meal.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium sweet potatoes diced\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas rinsed and drained\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"2 cups\", \"name\": \"cooked quinoa\"}, {\"qty\": \"4 cups\", \"name\": \"mixed greens or kale\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded red cabbage\"}, {\"qty\": \"3 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"water to thin\"}]", "instructions": "1. Preheat oven to 400 degrees F. Toss sweet potatoes with 1 tbsp olive oil paprika cumin salt and pepper and spread on one half of a baking sheet. 2. Toss chickpeas with remaining oil salt and pepper and spread on the other half. 3. Roast 25-30 minutes tossing halfway until sweet potatoes are tender and chickpeas are crispy. 4. Whisk tahini lemon juice garlic and water together until smooth and pourable. 5. Divide quinoa among four bowls and top with greens. 6. Add roasted sweet potato chickpeas avocado and red cabbage to each bowl. 7. Drizzle generously with tahini dressing and serve.", "tags": "vegan, gluten-free, high-fiber", "source": "https://cookieandkate.com/buddha-bowl-recipe/", "nutritionData": "{\"calories\": 548, \"protein\": 16.0, \"carbs\": 70.0, \"fat\": 24.0}"},
  {"name": "Honey Lime Chili Chicken Bowl", "category": "Healthy Lunch", "description": "Sheet-pan chili-lime chicken with roasted peppers and onions served over rice with avocado and a honey-lime vinaigrette.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"boneless chicken breasts or thighs\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"honey\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"2\", \"name\": \"bell peppers sliced\"}, {\"qty\": \"1\", \"name\": \"yellow onion sliced\"}, {\"qty\": \"\", \"name\": \"salt and chili flakes to taste\"}, {\"qty\": \"3 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"salsa verde\"}, {\"qty\": \"1/4 cup\", \"name\": \"lime juice\"}]", "instructions": "1. Preheat oven to 425 degrees F. 2. On a baking sheet toss chicken with olive oil honey garlic chili powder cumin salt and chili flakes. 3. Add bell peppers and onion with a drizzle of olive oil and a pinch of salt and arrange everything evenly on the pan. 4. Bake 20-25 minutes until chicken is cooked and peppers begin to char. 5. Whisk together salsa verde lime juice and a drizzle of olive oil and honey for the vinaigrette. 6. Slice the chicken thinly. 7. Serve chicken and peppers over rice topped with avocado tomatoes cilantro and drizzle of vinaigrette.", "tags": "gluten-free, high-protein, meal-prep", "source": "https://www.halfbakedharvest.com/honey-lime-chili-chicken-bowls/", "nutritionData": "{\"calories\": 672, \"protein\": 59.0, \"carbs\": 55.0, \"fat\": 14.0}"},
  {"name": "Banh Mi Rice Bowl", "category": "Healthy Lunch", "description": "Savory ground chicken over coconut jasmine rice with a fresh herb cucumber salad and spicy mayo for a quick satisfying bowl.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"ground chicken\"}, {\"qty\": \"2\", \"name\": \"shallots chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"tamari\"}, {\"qty\": \"2 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"2\", \"name\": \"Persian cucumbers chopped\"}, {\"qty\": \"1\", \"name\": \"avocado cubed\"}, {\"qty\": \"1 cup\", \"name\": \"mixed fresh herbs cilantro and basil\"}, {\"qty\": \"3 tbsp\", \"name\": \"mixed sesame seeds and peanuts\"}, {\"qty\": \"2 tbsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"3 cups\", \"name\": \"cooked jasmine rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"pickled carrots\"}, {\"qty\": \"\", \"name\": \"spicy mayo for serving\"}]", "instructions": "1. Toss cucumber herbs peanuts sesame seeds sesame oil and lime juice together in a bowl for the salad and season with salt. 2. Combine tamari fish sauce chili paste and maple syrup in a bowl adding 1/3 cup water. 3. Heat oil in a large skillet over medium-high heat and add chicken shallots and garlic. Cook breaking up meat until browned about 5 minutes. 4. Add sauce and cook another 5 minutes until meat is slightly crispy. 5. Add pickled carrots and cook 1 minute more then remove from heat. 6. Spoon meat over rice in bowls and top with the cucumber herb salad. 7. Drizzle with spicy mayo and serve immediately.", "tags": "high-protein, dairy-free, asian-inspired", "source": "https://www.halfbakedharvest.com/banh-mi-rice-bowls/", "nutritionData": "{\"calories\": 727, \"protein\": 42.0, \"carbs\": 56.0, \"fat\": 35.0}"},
  {"name": "California Chicken Avocado Rice Bowl", "category": "Healthy Lunch", "description": "Spice-rubbed grilled chicken with grilled peppers, zucchini, mashed avocado, cherry tomatoes, and feta over rice.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"2\", \"name\": \"bell peppers sliced\"}, {\"qty\": \"2\", \"name\": \"medium zucchini sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"2\", \"name\": \"ripe avocados\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped parsley\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"2 oz\", \"name\": \"crumbled feta\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted walnuts\"}]", "instructions": "1. Rub chicken with garlic powder paprika cumin salt and pepper. 2. Grill chicken over medium-high heat 6-7 minutes per side until cooked through then rest 5 minutes and slice. 3. Toss sliced peppers and zucchini with olive oil salt and pepper and grill alongside the chicken until charred and tender. 4. Mash avocados with lemon juice parsley and a pinch of flaky salt. 5. Divide rice among bowls and top with sliced chicken and grilled vegetables. 6. Add a large dollop of mashed avocado and scatter cherry tomatoes feta and toasted walnuts over each bowl. 7. Serve immediately.", "tags": "gluten-free, high-protein, fresh", "source": "https://www.halfbakedharvest.com/california-chicken-veggie-avocado-and-rice-bowls/", "nutritionData": "{\"calories\": 799, \"protein\": 67.0, \"carbs\": 57.0, \"fat\": 34.0}"},
  {"name": "Chicken Shawarma Sweet Potato Bowl", "category": "Healthy Lunch", "description": "Marinated shawarma-spiced chicken with oven-crisped sweet potato fries, couscous, and garlic tahini yogurt sauce.", "servings": 4, "prepTime": 40, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"chicken thighs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"2\", \"name\": \"large sweet potatoes cut into fries\"}, {\"qty\": \"2 cups\", \"name\": \"cooked couscous or quinoa\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 cups\", \"name\": \"mixed greens\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}]", "instructions": "1. Whisk olive oil with all spices salt and pepper and toss with chicken thighs to coat. Marinate at least 30 minutes. 2. Preheat oven to 400 degrees F. Spread chicken on one sheet pan and sweet potato fries on another drizzled with oil and salt. 3. Roast chicken 25-30 minutes until cooked through and sweet potatoes 30-35 minutes until crispy. 4. Stir together Greek yogurt tahini garlic and lemon juice for the sauce thinning with water if needed. 5. Cook couscous or quinoa according to package directions. 6. Assemble bowls with couscous greens chicken and sweet potato fries. 7. Add sliced avocado and drizzle generously with garlic tahini yogurt sauce.", "tags": "high-protein, meal-prep, mediterranean", "source": "https://www.halfbakedharvest.com/meal-prep-chicken-shawarma-sweet-potato-fry-bowls/", "nutritionData": "{\"calories\": 795, \"protein\": 56.0, \"carbs\": 53.0, \"fat\": 34.0}"},
  {"name": "Smashed Chickpea Salad Sandwich", "category": "Healthy Lunch", "description": "Lightly smashed chickpeas with lemon, olives, red onion, and parsley piled on toasted whole grain bread with tahini dressing.", "servings": 2, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 can\", \"name\": \"15 oz chickpeas drained and rinsed\"}, {\"qty\": \"2 tbsp\", \"name\": \"pitted black olives sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"finely chopped red onion\"}, {\"qty\": \"1 tbsp\", \"name\": \"chopped fresh parsley\"}, {\"qty\": \"\", \"name\": \"zest and juice of half a lemon\"}, {\"qty\": \"2 pinches\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"a few grinds black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 slices\", \"name\": \"whole grain bread toasted\"}, {\"qty\": \"2 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"handful arugula or watercress\"}, {\"qty\": \"\", \"name\": \"optional sliced roasted red pepper\"}]", "instructions": "1. Combine chickpeas olives red onion parsley lemon zest and juice salt and pepper in a bowl. 2. Lightly smash the mixture with the back of a fork to a coarse chunky texture not a puree. 3. Stir in olive oil and taste to adjust seasoning. 4. Whisk tahini with minced garlic lemon juice and a splash of water until spreadable. 5. Spread tahini on toasted bread slices. 6. Top with arugula then pile on the smashed chickpea mixture. 7. Add roasted red pepper if using close the sandwich slice and serve.", "tags": "vegan, quick, high-fiber", "source": "https://smittenkitchen.com/2009/01/smashed-chickpea-salad/", "nutritionData": "{\"calories\": 690, \"protein\": 25.0, \"carbs\": 82.0, \"fat\": 31.0}"},
  {"name": "Mediterranean Quinoa Roasted Veg Bowl", "category": "Healthy Lunch", "description": "Roasted eggplant, zucchini, and squash tossed with quinoa, cherry tomatoes, fresh herbs, and crumbled feta.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium eggplant diced\"}, {\"qty\": \"2\", \"name\": \"medium zucchini diced\"}, {\"qty\": \"1\", \"name\": \"yellow squash diced\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"1 cup\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"halved grape tomatoes\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh mint leaves\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted almonds or pine nuts\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled feta\"}]", "instructions": "1. Preheat oven to 425 degrees F with racks in upper and lower thirds. Line two rimmed baking sheets with parchment. 2. Divide eggplant zucchini and squash between the pans drizzle each with 1 tbsp olive oil and season with salt and pepper. 3. Roast 25-30 minutes until softened and browning at the edges. Set aside to cool. 4. Cook quinoa in water simmering 15 minutes until absorbed then rest covered 5 minutes and fluff. 5. Toast almonds in a small dry skillet over medium heat 4-8 minutes until golden. 6. In a large bowl whisk lemon juice and garlic then slowly whisk in remaining olive oil. 7. Add quinoa tomatoes basil mint roasted vegetables and nuts and stir gently. Stir in feta season to taste and serve.", "tags": "vegetarian, make-ahead, mediterranean", "source": "https://cookieandkate.com/mediterranean-quinoa-salad-recipe/", "nutritionData": "{\"calories\": 369, \"protein\": 11.0, \"carbs\": 30.0, \"fat\": 24.0}"},
  {"name": "Spicy Tuna Guacamole Bowl", "category": "Healthy Lunch", "description": "Seasoned canned tuna over rice with guacamole, edamame, cucumber, carrots, and sriracha for an easy poke-style lunch.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"5 oz chunk light tuna in water drained\"}, {\"qty\": \"3 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"1 cup\", \"name\": \"frozen shelled edamame cooked\"}, {\"qty\": \"1\", \"name\": \"medium cucumber diced\"}, {\"qty\": \"1\", \"name\": \"medium carrot shredded\"}, {\"qty\": \"8 oz\", \"name\": \"guacamole\"}, {\"qty\": \"1/4\", \"name\": \"bunch cilantro chopped\"}, {\"qty\": \"4 tbsp\", \"name\": \"sriracha hot sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"rice vinegar\"}]", "instructions": "1. Cook edamame according to package directions and let cool. 2. Dice cucumber and shred carrot. 3. Stir soy sauce sesame oil and rice vinegar into drained tuna. 4. Divide cooked rice among four bowls about 3/4 cup each. 5. Top each bowl with 1/4 cup edamame half a can of seasoned tuna 2 tbsp guacamole cucumber shredded carrot and cilantro. 6. Drizzle 1 tbsp sriracha over each bowl and sprinkle with sesame seeds. 7. Serve immediately or refrigerate components separately up to four days.", "tags": "gluten-free, high-protein, quick", "source": "https://www.budgetbytes.com/spicy-tuna-guacamole-bowls/", "nutritionData": "{\"calories\": 435, \"protein\": 26.0, \"carbs\": 53.0, \"fat\": 12.0}"},
  {"name": "Tuna Salad Wrap", "category": "Healthy Lunch", "description": "Classic tuna salad with celery, walnuts, and lemon wrapped in a whole grain tortilla with romaine and sliced tomato.", "servings": 3, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 can\", \"name\": \"12 oz chunk light tuna in water drained\"}, {\"qty\": \"1/2 cup\", \"name\": \"celery finely diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"walnuts chopped\"}, {\"qty\": \"1\", \"name\": \"green onion sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1/8 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/8 tsp\", \"name\": \"salt\"}, {\"qty\": \"1\", \"name\": \"Roma tomato thinly sliced\"}, {\"qty\": \"6\", \"name\": \"romaine lettuce leaves\"}, {\"qty\": \"3\", \"name\": \"large whole grain flour tortillas\"}]", "instructions": "1. Drain canned tuna well and flake into a bowl. 2. Add celery walnuts green onion mayonnaise lemon juice pepper and salt and stir to combine. 3. Slice tomato thinly and tear romaine into smaller pieces. 4. Warm each tortilla in the microwave 5-10 seconds so it stays pliable. 5. Layer romaine then tomato slices then one-third of the tuna salad on each tortilla. 6. Roll up tightly tucking in the sides as you go and place seam-side down. 7. Slice each wrap in half and serve.", "tags": "high-protein, quick, no-cook", "source": "https://www.budgetbytes.com/tuna-wrap/", "nutritionData": "{\"calories\": 434, \"protein\": 30.0, \"carbs\": 24.0, \"fat\": 23.0}"},
  {"name": "Lighter Turkey Club Sandwich", "category": "Healthy Lunch", "description": "Lean turkey breast with crisp bacon, lettuce, and tomato on whole grain bread for a high-protein satisfying lunch.", "servings": 1, "prepTime": 5, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 slices\", \"name\": \"center-cut bacon\"}, {\"qty\": \"2 slices\", \"name\": \"whole grain bread\"}, {\"qty\": \"1 tbsp\", \"name\": \"light mayonnaise\"}, {\"qty\": \"2 slices\", \"name\": \"iceberg lettuce\"}, {\"qty\": \"3 oz\", \"name\": \"thin-sliced turkey breast\"}, {\"qty\": \"2 slices\", \"name\": \"ripe tomato\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cook bacon in a skillet until crisp then drain on paper towels. 2. Toast bread slices until golden. 3. Spread light mayo on both pieces of toast. 4. Layer one slice of lettuce on the bottom bread then add turkey and tomato slices. 5. Season tomato with salt and pepper. 6. Top with bacon and the second slice of lettuce then close the sandwich. 7. Slice diagonally and serve immediately.", "tags": "high-protein, quick, classic-sandwich", "source": "https://www.skinnytaste.com/turkey-club/", "nutritionData": "{\"calories\": 412, \"protein\": 32.0, \"carbs\": 34.0, \"fat\": 16.0}"},
  {"name": "Roasted Mushroom Herbed Quinoa Bowl", "category": "Healthy Lunch", "description": "Savory roasted baby bella mushrooms over herbed quinoa with Parmesan, green onions, lemon, and toasted pepitas.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"baby bella mushrooms halved or quartered\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil plus more for drizzling\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fine salt\"}, {\"qty\": \"1 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped fresh parsley\"}, {\"qty\": \"1/4 cup\", \"name\": \"sliced green onions\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"toasted pepitas\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}]", "instructions": "1. Preheat oven to 425 degrees F and line a rimmed baking sheet with parchment. 2. Toss mushrooms with olive oil and salt and spread on the baking sheet. Roast 15-18 minutes tossing halfway until tender and condensed. 3. Meanwhile combine rinsed quinoa and water in a saucepan and bring to a boil. Reduce heat and simmer 15-20 minutes until water is absorbed. 4. Remove from heat cover and rest 5 minutes then fluff with a fork. 5. Stir in Parmesan most of the parsley green onions garlic salt and olive oil. 6. Add lemon juice and black pepper to taste. 7. Pour quinoa into bowls and top with roasted mushrooms their juices pepitas and remaining parsley.", "tags": "vegetarian, gluten-free, high-protein", "source": "https://cookieandkate.com/roasted-mushrooms-with-herbed-quinoa/", "nutritionData": "{\"calories\": 320, \"protein\": 15.0, \"carbs\": 34.0, \"fat\": 14.0}"},
  {"name": "Vegan Nicoise Salad", "category": "Healthy Lunch", "description": "A plant-based twist on the French classic with chickpeas, green beans, tender potatoes, olives, and a bright mustard dressing.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"baby potatoes halved\"}, {\"qty\": \"1 cup\", \"name\": \"green beans trimmed\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas rinsed and drained\"}, {\"qty\": \"4 cups\", \"name\": \"butter lettuce or mixed greens\"}, {\"qty\": \"1/2 cup\", \"name\": \"kalamata olives\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"sunflower seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 tsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1/4 tsp\", \"name\": \"dried dill\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}]", "instructions": "1. Boil potatoes in salted water 10-12 minutes until tender then drain and slice. 2. Blanch green beans in boiling water 2-4 minutes until bright green then plunge into ice water and drain. 3. Stir together chickpeas with a pinch of salt mustard maple syrup dill and sunflower seeds. 4. Whisk olive oil vinegar salt and pepper together to make the dressing. 5. Divide lettuce between two plates and top with chickpeas green beans potatoes and olives. 6. Add cherry tomatoes then drizzle with dressing and serve.", "tags": "vegan, gluten-free, high-fiber", "source": "https://minimalistbaker.com/vegan-nicoise-salad/", "nutritionData": "{\"calories\": 706, \"protein\": 22.0, \"carbs\": 81.0, \"fat\": 35.0}"},
  {"name": "Sesame Chicken Rice Bowl", "category": "Healthy Lunch", "description": "Crispy golden sesame-glazed chicken breast served over steamed rice with a sticky savory-sweet sesame sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"boneless chicken breast cubed\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"2 tbsp\", \"name\": \"arrowroot or cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil divided\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"\", \"name\": \"sliced green onions for serving\"}]", "instructions": "1. Toss cubed chicken with salt pepper ginger and arrowroot until evenly coated. 2. Heat 1 tbsp avocado oil in a large skillet over medium-high heat and cook chicken in batches until golden brown 5-6 minutes per batch. Set aside. 3. Mix soy sauce sugar tomato paste rice vinegar sesame oil sesame seeds and ginger together in a bowl. 4. Whisk 1 tbsp cornstarch with 2 tbsp water to make a slurry. 5. Add remaining sesame oil to the pan with red pepper flakes and garlic and cook 30 seconds until fragrant. 6. Add half the sauce cook 1 minute then return chicken and pour in remaining sauce and slurry. Cook 2 more minutes. 7. Serve over rice garnished with sesame seeds and green onions.", "tags": "high-protein, gluten-free option, asian-inspired", "source": "https://www.skinnytaste.com/sesame-chicken/", "nutritionData": "{\"calories\": 606, \"protein\": 58.0, \"carbs\": 48.0, \"fat\": 18.0}"},
  {"name": "Salmon Lentil Salad", "category": "Healthy Lunch", "description": "Flaky seared salmon over tender green lentils with mixed greens, cucumber, and a bright lemon scallion dressing.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"salmon fillets 5-6 oz each\"}, {\"qty\": \"1 cup\", \"name\": \"green lentils rinsed\"}, {\"qty\": \"3 cups\", \"name\": \"water or broth\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"1\", \"name\": \"cucumber diced\"}, {\"qty\": \"3 cups\", \"name\": \"mixed greens or arugula\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"\", \"name\": \"fresh dill or parsley for serving\"}]", "instructions": "1. Simmer lentils in water or broth with a pinch of salt for 18-20 minutes until tender. Drain and cool slightly. 2. Whisk together olive oil lemon juice Dijon mustard garlic salt and pepper to make the dressing. 3. Season salmon fillets with salt and pepper. 4. Heat a skillet over medium-high heat with a drizzle of oil and cook salmon skin-side down 4-5 minutes then flip and cook another 2-3 minutes until just cooked through. 5. Toss warm lentils with half the dressing scallions and cucumber. 6. Spread greens on two plates and top with dressed lentils. 7. Flake salmon over the top drizzle with remaining dressing and garnish with fresh dill or parsley.", "tags": "high-protein, gluten-free, omega-3", "source": "Classic", "nutritionData": "{\"calories\": 920, \"protein\": 61.0, \"carbs\": 65.0, \"fat\": 43.0}"},
  {"name": "Mason Jar Greek Salad", "category": "Healthy Lunch", "description": "Layered mason jar salad with lemon-oregano dressing, chickpeas, cucumber, tomatoes, feta, and crisp romaine that stays fresh for days.", "servings": 2, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2\", \"name\": \"English cucumber chopped\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/4 cup\", \"name\": \"kalamata olives\"}, {\"qty\": \"1/4\", \"name\": \"small red onion thinly sliced\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas drained and rinsed\"}, {\"qty\": \"2 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"2 cups\", \"name\": \"romaine lettuce chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}]", "instructions": "1. Whisk together olive oil lemon juice red wine vinegar oregano salt and pepper to make the dressing. 2. Divide dressing between two large mason jars. 3. Layer chickpeas on top of the dressing. 4. Add red onion cucumber olives and cherry tomatoes. 5. Add crumbled feta next. 6. Top with chopped romaine last so it stays crisp. 7. Seal jars and refrigerate up to 3 days. Shake to combine before eating.", "tags": "vegetarian, make-ahead, meal-prep", "source": "https://smittenkitchen.com/2013/05/greek-salad-with-lemon-and-oregano/", "nutritionData": "{\"calories\": 526, \"protein\": 20.0, \"carbs\": 52.0, \"fat\": 27.0}"},
  {"name": "Teriyaki Chicken Meatball Bowl", "category": "Healthy Lunch", "description": "Baked ground chicken meatballs glazed in glossy teriyaki sauce served over jasmine rice with steamed broccoli.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground chicken\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"1/4 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"grated ginger\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2\", \"name\": \"sliced green onions\"}, {\"qty\": \"1/4 cup\", \"name\": \"soy sauce for sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced for sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"grated ginger for sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 cups\", \"name\": \"cooked jasmine rice\"}, {\"qty\": \"2 cups\", \"name\": \"broccoli florets steamed\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. Preheat oven to 400 degrees F and line a baking sheet with parchment. 2. Mix ground chicken egg panko garlic ginger soy sauce and green onions until combined then shape into 16 meatballs. 3. Bake meatballs 20 minutes until golden and cooked through. 4. Combine soy sauce brown sugar garlic ginger water and cornstarch in a small saucepan. Cook over medium heat stirring until sauce simmers and thickens. 5. Toss cooked meatballs in teriyaki sauce to coat. 6. Cook rice according to package and steam broccoli until tender. 7. Divide rice and broccoli among four bowls and top with four meatballs and extra sauce. Garnish with sesame seeds and green onion.", "tags": "high-protein, meal-prep, asian-inspired", "source": "https://www.budgetbytes.com/teriyaki-meatball-bowls/", "nutritionData": "{\"calories\": 383, \"protein\": 29.0, \"carbs\": 42.0, \"fat\": 10.0}"},
  {"name": "Southwest Black Bean Quinoa Bowl", "category": "Healthy Lunch", "description": "Hearty bowl of quinoa with black beans, corn, avocado, roasted peppers, and a cumin-lime dressing for a meatless lunch.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 can\", \"name\": \"15 oz black beans rinsed and drained\"}, {\"qty\": \"1 cup\", \"name\": \"frozen corn thawed\"}, {\"qty\": \"1\", \"name\": \"red bell pepper roasted and diced\"}, {\"qty\": \"1\", \"name\": \"avocado diced\"}, {\"qty\": \"1/4 cup\", \"name\": \"red onion finely diced\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped fresh cilantro\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cook quinoa in vegetable broth by bringing to a boil then simmering 15 minutes until absorbed. Fluff and cool. 2. Whisk together olive oil lime juice cumin chili powder garlic powder salt and pepper for the dressing. 3. In a large bowl combine cooled quinoa black beans corn roasted pepper red onion and cilantro. 4. Pour dressing over the bowl and toss well to combine. 5. Gently fold in diced avocado at the end. 6. Taste and adjust seasoning then divide into bowls. 7. Serve at room temperature or chilled.", "tags": "vegan, gluten-free, high-fiber", "source": "Classic", "nutritionData": "{\"calories\": 517, \"protein\": 17.0, \"carbs\": 67.0, \"fat\": 21.0}"},
  {"name": "Shrimp and Avocado Grain Bowl", "category": "Healthy Lunch", "description": "Sauteed garlicky shrimp over farro with arugula, avocado, cucumber, and a bright lemon herb dressing.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"farro cooked according to package\"}, {\"qty\": \"4 cups\", \"name\": \"arugula\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1\", \"name\": \"cucumber sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil for dressing\"}]", "instructions": "1. Cook farro according to package directions until tender about 20 minutes then drain and cool slightly. 2. Whisk together 3 tbsp olive oil lemon juice Dijon mustard parsley salt and pepper for the dressing. 3. Season shrimp with garlic paprika salt and pepper. 4. Heat 2 tbsp olive oil in a skillet over medium-high heat and cook shrimp 2-3 minutes per side until pink and curled. 5. Divide farro among four bowls and top with arugula. 6. Arrange shrimp avocado cucumber and cherry tomatoes over each bowl. 7. Drizzle generously with lemon herb dressing and serve.", "tags": "high-protein, gluten-free option, omega-3", "source": "Classic", "nutritionData": "{\"calories\": 601, \"protein\": 38.0, \"carbs\": 56.0, \"fat\": 26.0}"},
  {"name": "White Bean and Kale Soup", "category": "Healthy Lunch", "description": "Comforting Tuscan-style soup with cannellini beans, kale, tomatoes, and rosemary for a fiber-rich satisfying lunch.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 can\", \"name\": \"14 oz diced tomatoes\"}, {\"qty\": \"2 cans\", \"name\": \"15 oz cannellini beans rinsed and drained\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable or chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"chopped kale\"}, {\"qty\": \"1 sprig\", \"name\": \"fresh rosemary\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"\", \"name\": \"Parmesan rind optional\"}, {\"qty\": \"\", \"name\": \"whole grain bread for serving\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat and saute onion 5 minutes until softened. 2. Add garlic and red pepper flakes and cook 1 minute until fragrant. 3. Stir in diced tomatoes with their juices and cook 3 minutes. 4. Add cannellini beans broth rosemary and Parmesan rind if using. Bring to a simmer. 5. Simmer uncovered 15 minutes to meld flavors. Discard rosemary sprig and Parmesan rind. 6. Stir in kale and cook 3-4 minutes until wilted. 7. Add lemon juice and adjust seasoning with salt and pepper. Serve with whole grain bread.", "tags": "vegan option, high-fiber, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 373, \"protein\": 19.0, \"carbs\": 56.0, \"fat\": 8.0}"},
  {"name": "Edamame Brown Rice Power Bowl", "category": "Healthy Lunch", "description": "Wholesome bowl of brown rice with edamame, shredded carrots, cucumber, avocado, nori, and a ginger sesame dressing.", "servings": 4, "prepTime": 10, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"brown rice uncooked\"}, {\"qty\": \"2 cups\", \"name\": \"shelled edamame cooked\"}, {\"qty\": \"2\", \"name\": \"large carrots shredded\"}, {\"qty\": \"2\", \"name\": \"cucumbers sliced\"}, {\"qty\": \"2\", \"name\": \"avocados sliced\"}, {\"qty\": \"4 sheets\", \"name\": \"nori torn into pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce or tamari\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"grated fresh ginger\"}, {\"qty\": \"1 tsp\", \"name\": \"honey or maple syrup\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}]", "instructions": "1. Cook brown rice according to package directions about 40-45 minutes then fluff and cool slightly. 2. Cook edamame per package instructions and drain. 3. Whisk together soy sauce rice vinegar sesame oil ginger honey and garlic to make the dressing. 4. Divide brown rice among four bowls. 5. Top each bowl with edamame shredded carrot cucumber and avocado. 6. Scatter nori pieces and sesame seeds over each bowl. 7. Drizzle with ginger sesame dressing and serve.", "tags": "vegan, gluten-free option, high-fiber", "source": "Classic", "nutritionData": "{\"calories\": 639, \"protein\": 20.0, \"carbs\": 83.0, \"fat\": 28.0}"},
  {"name": "Keto Breakfast Casserole", "category": "Keto", "description": "Hearty baked egg casserole with sausage, cheddar, and broccoli for an easy make-ahead keto breakfast.", "servings": 8, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"breakfast sausage\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 cups\", \"name\": \"broccoli florets\"}, {\"qty\": \"12\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 375°F and grease a 9x13-inch casserole dish. 2. In a skillet over medium-high heat, cook minced garlic for 1 minute, then add sausage and cook until browned, breaking it apart with a spatula. 3. Blanch broccoli in boiling water for 5 minutes until crisp-tender, then drain and pat dry. 4. In a large bowl, whisk together eggs, heavy cream, half the cheddar, parsley, salt, and pepper. 5. Spread sausage and broccoli evenly in the casserole dish, then pour egg mixture over the top. 6. Sprinkle remaining cheddar on top and bake for 30 minutes until eggs are set and cheese is golden.", "tags": "keto, make-ahead, high-protein, gluten-free", "source": "https://www.wholesomeyum.com/recipes/low-carb-breakfast-casserole-with-sausage-cheese-gluten-free/", "nutritionData": "{\"calories\": 459, \"protein\": 27.0, \"carbs\": 4.0, \"fat\": 37.0}"},
  {"name": "Almond Flour Pancakes", "category": "Keto", "description": "Fluffy low-carb pancakes made with almond flour that are naturally gluten-free and ready in minutes.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"blanched almond flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"powdered erythritol\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter melted\"}, {\"qty\": \"\", \"name\": \"butter or coconut oil for cooking\"}]", "instructions": "1. In a large bowl, whisk together almond flour, erythritol, baking powder, and salt. 2. In a separate bowl, whisk eggs, almond milk, vanilla, and melted butter. 3. Add wet ingredients to dry and stir until a smooth batter forms. 4. Heat a lightly oiled skillet over medium heat and pour 1/4 cup batter per pancake. 5. Cook for 2–3 minutes until bubbles form at the edges and the surface looks mostly set, then flip. 6. Cook 1–2 minutes more until golden brown. Serve with sugar-free syrup and butter.", "tags": "keto, gluten-free, low-carb, breakfast", "source": "https://www.wholesomeyum.com/keto-almond-flour-pancakes-recipe/", "nutritionData": "{\"calories\": 402, \"protein\": 16.0, \"carbs\": 5.0, \"fat\": 35.0}"},
  {"name": "Basic Chaffle", "category": "Keto", "description": "Crispy cheese and egg waffles made in a mini waffle iron — zero flour and under 1g net carbs each.", "servings": 2, "prepTime": 2, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded mozzarella cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"almond flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}]", "instructions": "1. Preheat a mini waffle maker for 5 minutes until hot. 2. In a small bowl, whisk together the egg, mozzarella, almond flour, baking powder, and salt until combined. 3. Pour half the batter into the center of the waffle maker and close the lid. 4. Cook for 3–4 minutes until steam stops and the chaffle is golden and crispy. 5. Carefully remove and allow to cool on a rack for 1–2 minutes to crisp up further. 6. Repeat with remaining batter. Serve with butter, sugar-free syrup, or savory toppings.", "tags": "keto, gluten-free, quick, low-carb", "source": "https://www.wholesomeyum.com/keto-chaffles-recipe/", "nutritionData": "{\"calories\": 137, \"protein\": 10.0, \"carbs\": 1.0, \"fat\": 9.0}"},
  {"name": "Fathead Pizza", "category": "Keto", "description": "Classic keto pizza with a chewy mozzarella and almond flour fathead dough topped with marinara and pepperoni.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"2 oz\", \"name\": \"cream cheese\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3/4 cup\", \"name\": \"blanched almond flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/4 cup\", \"name\": \"low-carb pizza sauce\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella for topping\"}, {\"qty\": \"2 oz\", \"name\": \"sliced pepperoni\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F and line a baking sheet with parchment paper. 2. Combine 1 1/2 cups mozzarella and cream cheese in a microwave-safe bowl; microwave 90 seconds, stirring halfway, until melted. 3. Stir in the egg and almond flour until a dough forms, then add garlic powder, oregano, salt, and pepper. 4. Turn dough onto the parchment-lined pan and press or roll into a 10-inch round. 5. Poke dough all over with a fork and bake for 8–10 minutes until golden and set. 6. Spread pizza sauce over the crust, top with mozzarella and pepperoni, and bake 5–8 more minutes until cheese is bubbly.", "tags": "keto, low-carb, grain-free, dinner", "source": "https://www.ketoconnect.net/keto-pizza/", "nutritionData": "{\"calories\": 447, \"protein\": 25.0, \"carbs\": 5.0, \"fat\": 34.0}"},
  {"name": "Keto Bread Loaf", "category": "Keto", "description": "A light and airy almond flour bread with only 1g net carb per slice that toasts beautifully.", "servings": 20, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"blanched almond flour\"}, {\"qty\": \"6\", \"name\": \"large eggs separated\"}, {\"qty\": \"1/4 cup\", \"name\": \"butter melted\"}, {\"qty\": \"3 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cream of tartar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"pink Himalayan salt\"}, {\"qty\": \"6\", \"name\": \"drops liquid stevia optional\"}]", "instructions": "1. Preheat oven to 375°F and line an 8x4-inch loaf pan with parchment paper. 2. Beat egg whites with cream of tartar using a hand mixer until soft peaks form; set aside. 3. In a food processor, combine egg yolks, almond flour, baking powder, salt, melted butter, and stevia; mix until a thick dough forms. 4. Add one-third of the egg whites to the food processor and pulse to combine, then pour batter into a large bowl. 5. Gently fold in remaining egg whites in two additions, being careful not to deflate them. 6. Pour batter into prepared loaf pan and bake for 30 minutes until golden and a toothpick comes out clean. Allow to cool completely before slicing.", "tags": "keto, gluten-free, grain-free, make-ahead", "source": "https://www.ketoconnect.net/best-keto-bread/", "nutritionData": "{\"calories\": 84, \"protein\": 3.0, \"carbs\": 1.0, \"fat\": 7.0}"},
  {"name": "Lettuce-Wrapped Beef Tacos", "category": "Keto", "description": "Juicy seasoned ground beef served in crisp butter lettuce cups with all the classic taco toppings.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground beef 80/20\"}, {\"qty\": \"1 tbsp\", \"name\": \"taco seasoning no-sugar\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"salsa no-sugar-added\"}, {\"qty\": \"8\", \"name\": \"large butter lettuce leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"1\", \"name\": \"lime cut into wedges\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. In a large skillet over medium-high heat, cook ground beef, breaking it apart, until browned and no longer pink, about 8 minutes. 2. Drain excess fat, then add garlic, taco seasoning, and salsa; stir to combine and simmer for 3 minutes. 3. Season with salt and pepper to taste. 4. Lay lettuce leaves on a serving platter to serve as taco shells. 5. Spoon seasoned beef into each lettuce cup. 6. Top with shredded cheddar, avocado, sour cream, and cilantro; serve with lime wedges.", "tags": "keto, gluten-free, dairy-free-option, quick", "source": "Classic", "nutritionData": "{\"calories\": 678, \"protein\": 25.0, \"carbs\": 7.0, \"fat\": 62.0}"},
  {"name": "Chicken Cauliflower Rice Burrito Bowl", "category": "Keto", "description": "Shredded salsa chicken over seasoned cauliflower rice with avocado, sour cream, and cheese.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"boneless chicken breasts\"}, {\"qty\": \"1 cup\", \"name\": \"salsa no-sugar-added\"}, {\"qty\": \"1\", \"name\": \"head cauliflower riced\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tsp\", \"name\": \"taco seasoning\"}, {\"qty\": \"1\", \"name\": \"avocado diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded Mexican cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Place chicken breasts in a skillet, pour salsa over them, season with salt, and cook covered over medium heat for 18–20 minutes until cooked through. 2. Shred chicken with two forks and return to the pan; simmer for 5 minutes to absorb flavors. 3. Rice the cauliflower using a food processor or grater. 4. In a separate skillet, melt butter over medium-high heat and sauté cauliflower rice with taco seasoning for 5–7 minutes until tender; season with salt. 5. Divide cauliflower rice into bowls and top with shredded chicken. 6. Add diced avocado, shredded cheese, sour cream, and cilantro; serve immediately.", "tags": "keto, gluten-free, high-protein, meal-prep", "source": "https://www.dietdoctor.com/recipes/low-carb-chicken-burrito-bowl-with-cauliflower-rice", "nutritionData": "{\"calories\": 543, \"protein\": 62.0, \"carbs\": 13.0, \"fat\": 25.0}"},
  {"name": "Zoodle Carbonara", "category": "Keto", "description": "Creamy bacon and egg carbonara sauce tossed with zucchini noodles for a classic pasta experience without the carbs.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 3/4 lbs\", \"name\": \"zucchini spiralized into zoodles\"}, {\"qty\": \"11 oz\", \"name\": \"bacon or pancetta diced\"}, {\"qty\": \"1 cup\", \"name\": \"heavy whipping cream\"}, {\"qty\": \"4\", \"name\": \"egg yolks\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Parmesan cheese\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Spiralize zucchini into noodles; pat dry with paper towels and set aside. 2. Fry bacon in a large skillet over medium heat until crispy; set aside the pan with drippings to cool slightly. 3. In a saucepan, bring heavy cream to a boil then reduce heat and simmer until reduced by one quarter; remove from heat and let cool slightly. 4. In a bowl, combine egg yolks, cooked bacon with fat, and Parmesan; stir into the warm cream, stirring constantly to prevent curdling. 5. Return saucepan to medium-low heat and add zoodles; toss for 1–2 minutes until warmed through and coated. 6. Season with salt and pepper, divide into bowls, and top with extra Parmesan and parsley.", "tags": "keto, gluten-free, low-carb, dinner", "source": "https://www.dietdoctor.com/recipes/keto-carbonara-with-zoodles", "nutritionData": "{\"calories\": 709, \"protein\": 33.0, \"carbs\": 9.0, \"fat\": 61.0}"},
  {"name": "Avocado Alfredo Zoodles with Chicken", "category": "Keto", "description": "Creamy avocado Alfredo sauce over zucchini noodles topped with pan-seared seasoned chicken thighs.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/3 lbs\", \"name\": \"boneless chicken thighs\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"2\", \"name\": \"ripe avocados\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy whipping cream\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Parmesan cheese\"}, {\"qty\": \"1\", \"name\": \"garlic clove\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 1/2 lbs\", \"name\": \"zucchini spiralized\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Season chicken thighs with thyme, garlic powder, salt, and pepper. 2. Heat 2 tbsp olive oil in a skillet over medium heat and cook chicken for 6 minutes per side until cooked through; set aside to rest. 3. Blend avocados, heavy cream, Parmesan, garlic, parsley, and lemon juice until smooth using an immersion blender or food processor. 4. Transfer sauce to a saucepan and bring to a simmer over medium heat; season with salt and pepper. 5. Toss zoodles in the sauce until fully coated and warmed through, about 2 minutes. 6. Slice chicken and serve over the zoodle Alfredo; garnish with extra Parmesan and parsley.", "tags": "keto, gluten-free, high-fat, dinner", "source": "https://www.dietdoctor.com/recipes/keto-avocado-alfredo-sauce-with-zoodles-and-chicken", "nutritionData": "{\"calories\": 769, \"protein\": 53.0, \"carbs\": 14.0, \"fat\": 57.0}"},
  {"name": "Keto Butter Burgers", "category": "Keto", "description": "Juicy beef and jalapeño patties wrapped in lettuce with avocado, cheese, and a pat of butter on top.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"80/20 ground beef\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o finely chopped\"}, {\"qty\": \"1/4\", \"name\": \"small yellow onion finely chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4 slices\", \"name\": \"cheddar cheese\"}, {\"qty\": \"1\", \"name\": \"tomato sliced\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"8\", \"name\": \"large romaine or butter lettuce leaves\"}, {\"qty\": \"4 tsp\", \"name\": \"butter\"}, {\"qty\": \"\", \"name\": \"mustard and sugar-free ketchup for serving\"}]", "instructions": "1. Preheat a grill or cast iron skillet over medium-high heat. 2. In a bowl, combine ground beef, jalapeño, onion, salt, and pepper; mix with hands and form into 4 patties. 3. Grill or pan-fry patties for 5–7 minutes per side to desired doneness; add cheese in the last minute of cooking. 4. Let burgers rest for 5 minutes while you prep the lettuce wraps. 5. Lay 2 lettuce leaves on each plate to form a wrap. 6. Place each patty on the lettuce, top with a pat of butter, avocado, tomato slices, and condiments; wrap the lettuce around and serve.", "tags": "keto, gluten-free, high-protein, low-carb", "source": "https://www.dietdoctor.com/recipes/keto-butter-burgers", "nutritionData": "{\"calories\": 892, \"protein\": 37.0, \"carbs\": 5.0, \"fat\": 81.0}"},
  {"name": "Chicken Bacon Ranch Casserole", "category": "Keto", "description": "Creamy ranch-seasoned chicken and crispy bacon baked with two cheeses and broccoli for a satisfying keto dinner.", "servings": 6, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"cooked shredded chicken breast\"}, {\"qty\": \"8 slices\", \"name\": \"bacon cooked and crumbled\"}, {\"qty\": \"3 cups\", \"name\": \"broccoli florets steamed\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"ranch dressing\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1 cup\", \"name\": \"shredded cheddar\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}]", "instructions": "1. Preheat oven to 375°F. 2. Steam broccoli for 5 minutes until crisp-tender; drain and pat dry. 3. In a large bowl, combine shredded chicken, crumbled bacon, broccoli, garlic, ranch dressing, and half of each cheese; season with salt and pepper. 4. Transfer mixture to a greased 9x13-inch baking dish. 5. Top with remaining mozzarella and cheddar cheeses. 6. Bake for 15 minutes until hot and bubbly and cheese is melted; garnish with chives and serve.", "tags": "keto, gluten-free, make-ahead, high-protein", "source": "https://www.wholesomeyum.com/recipes/chicken-bacon-ranch-casserole-recipe-easy-low-carb/", "nutritionData": "{\"calories\": 578, \"protein\": 62.0, \"carbs\": 5.0, \"fat\": 32.0}"},
  {"name": "Cheesy Chicken Zucchini Casserole", "category": "Keto", "description": "Seared chicken with sautéed zucchini and mushrooms in a rich cream cheese sauce baked until golden.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"chicken breast cut into pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cups\", \"name\": \"zucchini diced\"}, {\"qty\": \"8 oz\", \"name\": \"mushrooms sliced\"}, {\"qty\": \"1/2\", \"name\": \"small onion diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"6 oz\", \"name\": \"shredded mozzarella divided\"}, {\"qty\": \"2 tbsp\", \"name\": \"sour cream\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F. Pat chicken dry and season with salt and pepper. 2. Heat 1 tbsp oil in a skillet over medium-high; sear chicken pieces until cooked through, then transfer to a large bowl. 3. Add remaining oil; sauté mushrooms and onion for 8 minutes until soft; add zucchini and cook 8–10 more minutes until tender. Transfer to the bowl with chicken. 4. Add cream and broth to the skillet; scrape up browned bits and simmer 5 minutes until slightly thickened; stir in 3 oz cheese. 5. Remove from heat; stir in sour cream. Pour sauce over chicken and vegetables; mix to combine. Transfer to a baking dish. 6. Sprinkle remaining cheese on top; bake 10 minutes until melted, then broil 2 minutes until golden.", "tags": "keto, gluten-free, low-carb, casserole", "source": "https://www.wholesomeyum.com/chicken-zucchini-casserole/", "nutritionData": "{\"calories\": 621, \"protein\": 67.0, \"carbs\": 10.0, \"fat\": 33.0}"},
  {"name": "Keto Egg Muffin Cups", "category": "Keto", "description": "Portable baked egg cups loaded with veggies, bacon, and cheddar — perfect for meal-prep breakfasts.", "servings": 12, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1 cup\", \"name\": \"broccoli florets finely chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"cauliflower finely chopped\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 slices\", \"name\": \"bacon cooked and crumbled\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F and line a 12-cup muffin tin with parchment liners. 2. Toss broccoli, cauliflower, red pepper, and garlic with olive oil; spread on a baking sheet and roast for 15 minutes until edges are browned. 3. Distribute roasted vegetables and crumbled bacon evenly among the muffin cups. 4. In a bowl, whisk together eggs, heavy cream, salt, pepper, and cheddar cheese. 5. Pour egg mixture over the vegetables in each muffin cup, filling about three-quarters full. 6. Bake for 15–20 minutes until eggs are set. Cool 5 minutes before removing; refrigerate up to 5 days.", "tags": "keto, meal-prep, gluten-free, make-ahead", "source": "https://www.wholesomeyum.com/egg-muffins/", "nutritionData": "{\"calories\": 124, \"protein\": 7.0, \"carbs\": 1.0, \"fat\": 10.0}"},
  {"name": "Steak and Eggs", "category": "Keto", "description": "A hearty classic keto breakfast of pan-seared ribeye steak served alongside crispy-edged fried eggs.", "servings": 2, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"ribeye steaks 6 oz each\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"\", \"name\": \"fresh parsley chopped for garnish\"}]", "instructions": "1. Pat steaks dry with paper towels; season both sides generously with salt and pepper. 2. Heat 1 tbsp avocado oil in a cast iron skillet over medium-high heat until shimmering. 3. Cook steaks, flipping every 60–90 seconds, for about 6 minutes total for medium-rare; transfer to a cutting board and rest 5 minutes. 4. Heat remaining oil in a medium nonstick skillet over low heat. 5. Crack 2 eggs per serving into the pan; season with salt and pepper; cover and cook on low until whites are set but yolks are still runny, about 4 minutes. 6. Slice steaks against the grain and serve alongside fried eggs; garnish with parsley.", "tags": "keto, high-protein, gluten-free, breakfast", "source": "https://www.wholesomeyum.com/steak-and-eggs/", "nutritionData": "{\"calories\": 755, \"protein\": 52.0, \"carbs\": 1.0, \"fat\": 59.0}"},
  {"name": "Keto Salmon with Honey Garlic Glaze", "category": "Keto", "description": "Broiled salmon fillets with a sweet-savory keto honey and coconut aminos glaze ready in 25 minutes.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets 6 oz each\"}, {\"qty\": \"2 tbsp\", \"name\": \"keto honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"sliced green onions for garnish\"}]", "instructions": "1. Preheat oven broiler to 500°F with rack 6 inches from heat. 2. Pat salmon fillets dry; season both sides with salt and pepper. 3. In a large bowl, whisk together keto honey, coconut aminos, olive oil, paprika, garlic powder, and ginger. 4. Add salmon to bowl and turn to coat; marinate for at least 10 minutes. 5. Place salmon in a baking dish, brush any remaining glaze over top. 6. Broil for 10–12 minutes until salmon flakes easily with a fork; garnish with green onions and serve.", "tags": "keto, gluten-free, high-protein, dairy-free", "source": "https://www.wholesomeyum.com/keto-salmon/", "nutritionData": "{\"calories\": 390, \"protein\": 34.0, \"carbs\": 2.0, \"fat\": 25.0}"},
  {"name": "Parmesan Crusted Salmon", "category": "Keto", "description": "Flaky baked salmon enveloped in a golden, herby Parmesan crust and ready in under 30 minutes.", "servings": 6, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"salmon fillet whole\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3/4 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"dried dill\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter melted\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F and line a baking sheet with parchment paper. 2. Place salmon on prepared sheet; pat dry and drizzle with olive oil and lemon juice; season both sides with salt and pepper. 3. In a small bowl, mix Parmesan, parsley, dill, and garlic powder; stir in melted butter until crumbly. 4. Crumble Parmesan mixture evenly over salmon and press lightly to adhere. 5. Bake for 15–17 minutes until fish flakes easily with a fork and the topping is golden brown. 6. Optional: broil for 1–2 minutes for a crispier crust; serve immediately.", "tags": "keto, gluten-free, high-protein, quick", "source": "https://www.wholesomeyum.com/parmesan-crusted-salmon/", "nutritionData": "{\"calories\": 460, \"protein\": 35.0, \"carbs\": 0.0, \"fat\": 34.0}"},
  {"name": "Creamy Tuscan Salmon", "category": "Keto", "description": "Pan-seared salmon fillets in a rich Parmesan cream sauce with sun-dried tomatoes and wilted spinach.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets 6 oz each\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"sun-dried tomatoes chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 oz\", \"name\": \"baby spinach\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Pat salmon dry; season both sides with salt and pepper. 2. Heat oil in a large skillet over medium-high; sear salmon skin-side down for 5–6 minutes; flip and cook 1–2 minutes to medium; transfer to a plate. 3. Wipe out pan; sauté garlic and sun-dried tomatoes over medium heat for 1–2 minutes until fragrant. 4. Add broth and cream; bring to a boil then simmer 5 minutes until slightly thickened. 5. Stir in spinach over low heat until just wilted; stir in Parmesan until sauce is smooth and creamy. 6. Return salmon to pan; spoon sauce over fillets; heat through and garnish with parsley before serving.", "tags": "keto, gluten-free, high-fat, dinner", "source": "https://www.wholesomeyum.com/tuscan-salmon/", "nutritionData": "{\"calories\": 655, \"protein\": 41.0, \"carbs\": 5.0, \"fat\": 51.0}"},
  {"name": "Keto Blueberry Muffins", "category": "Keto", "description": "Ultra-moist almond flour blueberry muffins with only 3g net carbs each and a fluffy bakery-style texture.", "servings": 12, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 1/2 cups\", \"name\": \"blanched almond flour\"}, {\"qty\": \"1/3 cup\", \"name\": \"powdered erythritol sweetener\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/3 cup\", \"name\": \"butter melted\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"3\", \"name\": \"large eggs room temperature\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"fresh blueberries\"}]", "instructions": "1. Preheat oven to 350°F and line a 12-cup muffin pan with parchment liners. 2. In a large bowl, whisk together almond flour, erythritol, baking powder, and salt to combine. 3. Stir in melted butter, almond milk, eggs, and vanilla extract until a thick batter forms. 4. Gently fold in blueberries, being careful not to smash them. 5. Divide batter evenly among the 12 muffin cups and bake for 20–25 minutes until tops are golden and a toothpick inserted in the center comes out clean. 6. Cool in pan for 10 minutes, then transfer to a wire rack; store in the refrigerator for up to 1 week.", "tags": "keto, gluten-free, low-carb, make-ahead", "source": "https://www.wholesomeyum.com/recipes/keto-low-carb-paleo-blueberry-muffins-recipe-almond-flour/", "nutritionData": "{\"calories\": 187, \"protein\": 6.0, \"carbs\": 4.0, \"fat\": 16.0}"},
  {"name": "Chocolate Keto Fat Bombs", "category": "Keto", "description": "Rich chocolate macadamia nut fat bombs that taste like decadent truffles with only 1g net carb each.", "servings": 20, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"macadamia nuts salted\"}, {\"qty\": \"2 tbsp\", \"name\": \"MCT oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"1/4 cup\", \"name\": \"powdered erythritol\"}, {\"qty\": \"\", \"name\": \"crushed macadamia nuts for topping\"}]", "instructions": "1. Line a 24-cup mini muffin pan with parchment liners. 2. Pulse macadamia nuts in a food processor, starting and stopping, until broken down into small pieces. 3. Add MCT oil, melted coconut oil, and vanilla; continue to process until a nut butter forms. 4. Add cocoa powder and sweetener 2 tablespoons at a time, pureeing after each addition until smooth. 5. Spoon batter into mini muffin liners, filling to the top; sprinkle crushed macadamia nuts on top. 6. Freeze for at least 30 minutes until solid; store in the refrigerator for up to 2 weeks.", "tags": "keto, no-bake, dessert, low-carb", "source": "https://www.wholesomeyum.com/keto-fat-bomb-recipe-chocolate-fat-bombs/", "nutritionData": "{\"calories\": 123, \"protein\": 1.0, \"carbs\": 1.0, \"fat\": 13.0}"},
  {"name": "No-Bake Keto Cheesecake", "category": "Keto", "description": "Creamy no-bake cheesecake with an almond flour crust and a cloud-like cream cheese filling that sets in the fridge.", "servings": 12, "prepTime": 20, "cookTime": 0, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"blanched almond flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"powdered erythritol for crust\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"5 tbsp\", \"name\": \"butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract for crust\"}, {\"qty\": \"24 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1 cup\", \"name\": \"powdered erythritol for filling\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract for filling\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 oz\", \"name\": \"sugar-free chocolate for drizzle\"}]", "instructions": "1. In a bowl, combine almond flour, 3 tbsp erythritol, and salt; stir in melted butter and 1 tsp vanilla until crumbly but cohesive. 2. Press crust into the bottom of a parchment-lined 9-inch springform pan; refrigerate while making the filling. 3. Beat cream cheese and 1 cup powdered erythritol with a hand mixer until smooth; beat in sour cream, lemon juice, and vanilla. 4. In a separate bowl, whip heavy cream to stiff peaks; gently fold into the cream cheese mixture. 5. Pour filling over the crust and smooth the top; cover and refrigerate at least 4 hours or overnight. 6. Melt sugar-free chocolate and drizzle over the set cheesecake before slicing and serving.", "tags": "keto, no-bake, dessert, gluten-free", "source": "https://www.wholesomeyum.com/no-bake-keto-cheesecake/", "nutritionData": "{\"calories\": 413, \"protein\": 8.0, \"carbs\": 5.0, \"fat\": 41.0}"},
  {"name": "Keto Chocolate Mousse", "category": "Keto", "description": "Silky rich chocolate mousse made with mascarpone and whipped cream — just 4 ingredients and no baking required.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"mascarpone cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy whipping cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"25\", \"name\": \"drops liquid stevia\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Add heavy whipping cream to a medium bowl and beat with a hand mixer to soft peaks; set aside. 2. Microwave mascarpone for 20 seconds to soften; beat with a hand mixer until smooth. 3. Sift cocoa powder over the mascarpone; add liquid stevia and vanilla; beat until fully combined and smooth. 4. Gently fold the whipped cream into the mascarpone mixture until uniform and fluffy. 5. Divide mousse into 4 serving glasses or bowls. 6. Refrigerate for 1–2 hours until chilled and set; serve with optional sugar-free whipped cream on top.", "tags": "keto, no-bake, dessert, low-carb", "source": "https://www.ketoconnect.net/low-carb-chocolate-mousse/", "nutritionData": "{\"calories\": 351, \"protein\": 4.0, \"carbs\": 4.0, \"fat\": 36.0}"},
  {"name": "Keto Avocado Chocolate Pudding", "category": "Keto", "description": "A five-ingredient blended avocado chocolate pudding that delivers rich flavor in under five minutes.", "servings": 2, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium ripe avocado pitted and peeled\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"10\", \"name\": \"drops liquid stevia\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 tsp\", \"name\": \"pink Himalayan salt\"}]", "instructions": "1. Remove the pit from the avocado and scoop the flesh into a mixing bowl. 2. Add cocoa powder, liquid stevia, vanilla extract, and salt. 3. Mash with a fork until a smooth pudding texture forms; for an extra-smooth result, use a hand mixer or small blender. 4. Taste and adjust sweetness by adding more stevia if desired. 5. Transfer to two small serving bowls. 6. Serve immediately or refrigerate up to 2 hours; top with crushed nuts or sugar-free whipped cream if desired.", "tags": "keto, vegan, no-bake, dessert", "source": "https://www.ketoconnect.net/chocolate-avocado-pudding/", "nutritionData": "{\"calories\": 145, \"protein\": 4.0, \"carbs\": 8.0, \"fat\": 13.0}"},
  {"name": "Keto Cheesecake Bites", "category": "Keto", "description": "Mini baked cheesecake cups with a raspberry swirl and cream cheese frosting — just 2g net carbs each.", "servings": 24, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"fresh raspberries\"}, {\"qty\": \"1 tbsp\", \"name\": \"powdered erythritol for sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"water\"}, {\"qty\": \"16 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1/2 cup\", \"name\": \"powdered erythritol for filling\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"\", \"name\": \"sugar-free whipped cream for topping\"}, {\"qty\": \"24\", \"name\": \"fresh raspberries for garnish\"}]", "instructions": "1. Preheat oven to 350°F and line a 24-cup mini muffin pan with parchment liners. 2. In a small saucepan, combine raspberries, 1 tbsp erythritol, and water; heat over low until berries soften, smash, and sauce thickens; set aside to cool. 3. Beat cream cheese and 1/2 cup erythritol with a hand mixer at low-medium speed until fluffy. 4. Beat in egg, then lemon juice and vanilla at low speed to avoid air bubbles. 5. Spoon filling into liners; add 1/2 tsp raspberry sauce to each and swirl with a toothpick. 6. Bake 10–15 minutes until puffed but still jiggly; cool at room temperature then refrigerate at least 1 hour until firm; top with whipped cream and a fresh raspberry.", "tags": "keto, gluten-free, dessert, make-ahead", "source": "https://www.wholesomeyum.com/low-carb-keto-cheesecake-bites-recipe/", "nutritionData": "{\"calories\": 69, \"protein\": 1.0, \"carbs\": 1.0, \"fat\": 7.0}"},
  {"name": "Keto Bacon and Cheese Omelette", "category": "Keto", "description": "A classic fluffy three-egg omelette filled with crispy bacon and sharp cheddar for a satisfying low-carb breakfast.", "servings": 1, "prepTime": 5, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"heavy cream\"}, {\"qty\": \"2 slices\", \"name\": \"bacon cooked and crumbled\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}]", "instructions": "1. Crack eggs into a bowl, add heavy cream, salt, and pepper; whisk until smooth and slightly frothy. 2. Heat butter in an 8-inch nonstick skillet over medium-low heat until foamy. 3. Pour in egg mixture and cook, gently pushing cooked edges toward the center while tilting the pan, for 3–4 minutes until eggs are mostly set but slightly wet on top. 4. Sprinkle crumbled bacon and cheddar over one half of the omelette. 5. Fold the omelette in half over the filling and cook 1 more minute until cheese melts. 6. Slide onto a plate, garnish with chives, and serve immediately.", "tags": "keto, gluten-free, quick, breakfast", "source": "Classic", "nutritionData": "{\"calories\": 564, \"protein\": 32.0, \"carbs\": 2.0, \"fat\": 47.0}"},
  {"name": "Keto Avocado Bacon Chicken Bunless Burger", "category": "Keto", "description": "Juicy chicken patties wrapped in lettuce with crispy bacon, avocado, and caramelized onion rings.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground chicken\"}, {\"qty\": \"2\", \"name\": \"scallions finely chopped\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"8 slices\", \"name\": \"bacon\"}, {\"qty\": \"1\", \"name\": \"small onion sliced into rings\"}, {\"qty\": \"2\", \"name\": \"avocados sliced\"}, {\"qty\": \"8\", \"name\": \"large romaine lettuce leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"cooking oil\"}]", "instructions": "1. In a bowl, combine ground chicken, scallions, garlic, egg, salt, and pepper; mix until combined. 2. Divide into 4 portions and shape into patties. 3. In a skillet over medium heat, fry bacon and onion rings until bacon is crispy and onions are softened; remove and set aside. 4. In the same skillet with bacon drippings, fry chicken patties over medium-high heat for 4–5 minutes per side until golden and cooked to 165°F. 5. Lay two lettuce leaves on each plate as the bun base. 6. Stack each lettuce wrap with a chicken patty, bacon, avocado slices, and caramelized onion rings; fold and serve.", "tags": "keto, gluten-free, dairy-free, high-protein", "source": "https://www.dietdoctor.com/recipes/avocado-bacon-and-chicken-bun-less-burger", "nutritionData": "{\"calories\": 486, \"protein\": 32.0, \"carbs\": 9.0, \"fat\": 37.0}"},
  {"name": "Cauliflower Fried Rice", "category": "Keto", "description": "Savory cauliflower rice stir-fried with eggs, bacon, sesame oil, and low-sodium soy sauce for a grain-free takeout fix.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large head cauliflower riced\"}, {\"qty\": \"4 slices\", \"name\": \"bacon diced\"}, {\"qty\": \"3\", \"name\": \"large eggs beaten\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1/4 cup\", \"name\": \"coconut aminos\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas and carrots thawed\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Rice cauliflower using a food processor or grater; set aside. 2. Cook diced bacon in a large skillet or wok over medium-high heat until crispy; remove and set aside, leaving 1 tbsp drippings in the pan. 3. Add garlic and ginger to the pan; stir-fry 30 seconds until fragrant. 4. Add cauliflower rice; stir-fry for 5–6 minutes until tender and slightly golden. 5. Push rice to the side; scramble beaten eggs in the clear space until set, then mix into the rice. 6. Stir in bacon, peas and carrots, coconut aminos, and sesame oil; season with salt and pepper; top with green onions.", "tags": "keto, gluten-free, low-carb, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 206, \"protein\": 12.0, \"carbs\": 14.0, \"fat\": 9.0}"},
  {"name": "Low-Carb Curry Chicken with Cauliflower Rice", "category": "Keto", "description": "Coconut cream curry chicken with tender vegetables served over golden buttered cauliflower rice.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"boneless chicken thighs cubed\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter or coconut oil\"}, {\"qty\": \"1\", \"name\": \"small onion finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1\", \"name\": \"red chili pepper chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"red curry paste\"}, {\"qty\": \"1 cup\", \"name\": \"broccoli florets\"}, {\"qty\": \"1/2 cup\", \"name\": \"green beans trimmed\"}, {\"qty\": \"1 can\", \"name\": \"14 oz coconut cream solid part only\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"1\", \"name\": \"head cauliflower riced\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter for rice\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}]", "instructions": "1. Melt butter in a large pan over medium heat; sauté onion, ginger, and chili for 5 minutes until fragrant. 2. Add curry paste and chicken; fry for 8–10 minutes until chicken is lightly browned. 3. Add broccoli and green beans; pour in solid coconut cream; season with salt and pepper. 4. Simmer covered for 15 minutes until chicken is cooked through. 5. Meanwhile, grate cauliflower and sauté in a skillet with 1 tbsp butter over medium heat for 5–8 minutes; add turmeric and salt. 6. Serve curry over cauliflower rice.", "tags": "keto, gluten-free, dairy-free, dinner", "source": "https://www.dietdoctor.com/recipes/low-carb-curry-chicken", "nutritionData": "{\"calories\": 612, \"protein\": 49.0, \"carbs\": 10.0, \"fat\": 40.0}"},
  {"name": "Keto Pesto Chicken Zoodle Salad", "category": "Keto", "description": "Shredded poached chicken thighs tossed with pesto zoodles, cherry tomatoes, and creamy feta cheese.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/3 lbs\", \"name\": \"boneless chicken thighs\"}, {\"qty\": \"1/3 cup\", \"name\": \"sugar-free green pesto\"}, {\"qty\": \"5 oz\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"4 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"12 oz\", \"name\": \"zucchini spiralized into zoodles\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Place chicken thighs in a pot, cover with cold water, and bring to a boil; reduce heat and simmer for 15 minutes until cooked through. 2. Remove chicken and shred using two forks; set aside. 3. Spiralize zucchini and place zoodles in a large mixing bowl. 4. Pour pesto over zoodles and toss with tongs until fully coated. 5. Add shredded chicken, cherry tomatoes, and feta to the zoodles; gently toss until evenly combined. 6. Drizzle with olive oil, season with salt and pepper, and serve at room temperature or chilled.", "tags": "keto, gluten-free, high-protein, meal-prep", "source": "https://www.dietdoctor.com/recipes/keto-chicken-pesto-zoodle-salad", "nutritionData": "{\"calories\": 594, \"protein\": 46.0, \"carbs\": 6.0, \"fat\": 42.0}"},
  {"name": "Keto Chimichurri Chicken with Zoodles", "category": "Keto", "description": "Herby chimichurri-sauced pan-seared chicken breasts served over tender spiralized zucchini noodles.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"chicken breasts 8 oz each\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2\", \"name\": \"lemon juice and zest\"}, {\"qty\": \"1/2\", \"name\": \"yellow bell pepper finely chopped\"}, {\"qty\": \"1\", \"name\": \"green chili finely chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"olive oil for sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1\", \"name\": \"garlic clove minced\"}, {\"qty\": \"1 lb\", \"name\": \"zucchini spiralized\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"olive oil for zoodles\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Slice chicken breasts horizontally into thin cutlets; season both sides with salt and pepper. 2. Heat oil in a large skillet over medium-high; cook chicken 4 minutes per side until golden and cooked through; set aside. 3. In a tall beaker, combine lemon juice, lemon zest, bell pepper, chili, 1/3 cup olive oil, parsley, garlic, salt, and pepper; blend with an immersion blender to desired consistency for the chimichurri. 4. Boil salted water and blanch zoodles for 60 seconds; drain well; drizzle with 1/2 tbsp olive oil, salt, and pepper. 5. Divide zoodles between two plates and top with sliced chicken. 6. Spoon chimichurri generously over chicken and zoodles; serve immediately.", "tags": "keto, gluten-free, dairy-free, quick", "source": "https://www.dietdoctor.com/recipes/chimichurri-chicken-with-zoodles", "nutritionData": "{\"calories\": 805, \"protein\": 73.0, \"carbs\": 10.0, \"fat\": 52.0}"},
  {"name": "Cream Cheese Keto Pancakes", "category": "Keto", "description": "Ultra-simple two-ingredient cream cheese pancakes that are light and delicate with virtually zero carbs.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon optional\"}, {\"qty\": \"\", \"name\": \"butter or coconut oil for cooking\"}, {\"qty\": \"\", \"name\": \"sugar-free syrup and butter for serving\"}]", "instructions": "1. Combine cream cheese, eggs, vanilla, and cinnamon in a blender or food processor; blend until completely smooth. 2. Heat a lightly oiled small skillet over medium heat. 3. Pour 1/4 cup batter into the pan and swirl gently to spread into a thin round. 4. Cook for 1–2 minutes until bubbles form at the edges and the surface looks set; carefully flip. 5. Cook 1 minute on the second side until lightly golden; transfer to a warm plate. 6. Repeat with remaining batter; serve with butter and sugar-free syrup.", "tags": "keto, gluten-free, quick, breakfast", "source": "https://www.wholesomeyum.com/cream-cheese-pancakes/", "nutritionData": "{\"calories\": 168, \"protein\": 8.0, \"carbs\": 2.0, \"fat\": 15.0}"},
  {"name": "Baked Mac and Cheese", "category": "Kid-Friendly", "description": "Rich and creamy macaroni baked with a buttery panko topping until golden and bubbling.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"elbow macaroni\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Italian cheese blend\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"additional cheddar for topping\"}]", "instructions": "1. Preheat oven to 375°F. In a medium saucepot combine broth, cream, garlic powder, smoked paprika, and salt; bring to a boil then simmer 7 minutes. 2. Remove sauce from heat and whisk in combined cheeses a handful at a time until smooth. 3. Boil macaroni 7 minutes until just tender; drain. Stir macaroni into cheese sauce. 4. Toast panko in butter in a small skillet 3 minutes; cool. 5. Pour half the mac into a greased 8x8-inch dish, sprinkle reserved cheese, top with remaining mac. 6. Mix toasted panko with additional cheddar and scatter over top. 7. Bake 20 minutes until bubbling and topping is golden brown. Rest 5 minutes before serving.", "tags": "kid-friendly, comfort food, make-ahead", "source": "https://www.budgetbytes.com/baked-mac-and-cheese/", "nutritionData": "{\"calories\": 484, \"protein\": 17.0, \"carbs\": 33.0, \"fat\": 31.0}"},
  {"name": "Baked Chicken Nuggets", "category": "Kid-Friendly", "description": "Crispy cornflake-crusted chicken nuggets baked golden in the oven without any frying.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts cut into 1-inch chunks\"}, {\"qty\": \"1 tbsp\", \"name\": \"ranch seasoning mix\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"buttermilk\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1.5 cups\", \"name\": \"cornflake crumbs\"}, {\"qty\": \"1/3 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"3 tbsp\", \"name\": \"canola oil\"}]", "instructions": "1. Preheat oven to 425°F. Place a wire rack on a foil-lined baking sheet and coat with nonstick spray. 2. Toss chicken with ranch seasoning, salt, and pepper; let sit 30 minutes. 3. Set up three bowls: flour, whisked buttermilk and egg, and cornflake crumbs mixed with Parmesan and oil. 4. Dredge each piece in flour, dip in buttermilk mixture, then press into cornflake mixture. 5. Arrange on rack in a single layer and coat with nonstick spray. 6. Bake 13 to 15 minutes until crisp and cooked through. Serve immediately with ketchup or honey mustard.", "tags": "kid-friendly, baked, freezer-friendly", "source": "https://damndelicious.net/2022/06/03/baked-chicken-nuggets/", "nutritionData": "{\"calories\": 609, \"protein\": 64.0, \"carbs\": 35.0, \"fat\": 22.0}"},
  {"name": "Honey Dijon Chicken Tenders", "category": "Kid-Friendly", "description": "Panko-crusted chicken strips coated in a sweet honey mustard glaze and baked until crispy.", "servings": 4, "prepTime": 10, "cookTime": 28, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"boneless skinless chicken breasts sliced into strips\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter melted\"}, {\"qty\": \"1/4 cup\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}]", "instructions": "1. Preheat oven to 400°F. Line a baking sheet with foil or a silicone mat. 2. In a large bowl combine panko, garlic powder, paprika, salt, and pepper; set aside. 3. In a small bowl whisk together melted butter, Dijon mustard, and honey. 4. Working in batches, dip chicken strips in the honey-mustard mixture then dredge in panko, pressing to coat. 5. Arrange on prepared baking sheet. 6. Bake 25 to 30 minutes until golden brown and crispy. Serve immediately with extra honey mustard for dipping.", "tags": "kid-friendly, baked, quick", "source": "https://damndelicious.net/2011/10/17/honey-dijon-chicken-tenders/", "nutritionData": "{\"calories\": 291, \"protein\": 28.0, \"carbs\": 14.0, \"fat\": 13.0}"},
  {"name": "Mini Chicken Quesadillas", "category": "Kid-Friendly", "description": "Bite-sized flour tortilla quesadillas stuffed with rotisserie chicken, salsa, and melted cheese.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"shredded rotisserie chicken\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded Mexican blend cheese\"}, {\"qty\": \"1/3 cup\", \"name\": \"restaurant-style salsa\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped fresh cilantro\"}, {\"qty\": \"1 cup\", \"name\": \"refried beans\"}, {\"qty\": \"16\", \"name\": \"small street taco flour tortillas\"}, {\"qty\": \"3 tbsp\", \"name\": \"canola oil\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 200°F to keep finished batches warm. 2. In a bowl combine chicken, cheese, salsa, and cilantro; season with salt and pepper. 3. Spread refried beans on half of each tortilla then top with chicken mixture and fold to seal. 4. Heat 1 tbsp oil in a cast iron skillet over medium-low heat. 5. Cook quesadillas in batches 1 to 2 minutes per side until golden brown. Keep warm in oven. 6. Repeat with remaining oil and quesadillas. Serve with guacamole, pico de gallo, and sour cream.", "tags": "kid-friendly, quick, finger food", "source": "https://damndelicious.net/2022/07/22/mini-chicken-quesadillas/", "nutritionData": "{\"calories\": 712, \"protein\": 38.0, \"carbs\": 67.0, \"fat\": 34.0}"},
  {"name": "Pepperoni Pizza Bites", "category": "Kid-Friendly", "description": "Fluffy yogurt-dough pizza cups filled with marinara, mozzarella, and turkey pepperoni.", "servings": 4, "prepTime": 20, "cookTime": 18, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"non-fat Greek yogurt\"}, {\"qty\": \"2/3 cup\", \"name\": \"marinara or pizza sauce\"}, {\"qty\": \"1 cup\", \"name\": \"shredded part-skim mozzarella\"}, {\"qty\": \"1 oz\", \"name\": \"turkey pepperoni chopped\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Preheat oven to 375°F and spray two 12-cup mini muffin tins with oil. 2. Whisk together flour, baking powder, and salt. Add yogurt and mix until combined; dough will look crumbly. 3. Knead on a floured surface about 15 turns until tacky but not sticky. Divide into 16 equal balls. 4. Press each ball into the bottom of a muffin cup allowing it to go up the side slightly. 5. Bake 15 minutes, remove and press centers down to create a well. 6. Fill each well with 2 tsp sauce, 1 tbsp cheese, and a sprinkle of pepperoni. Bake 3 more minutes until cheese melts. 7. Cool 2 minutes then carefully remove bites with a small knife or spatula.", "tags": "kid-friendly, finger food, fun shapes", "source": "https://www.skinnytaste.com/pepperoni-pizza-bites/", "nutritionData": "{\"calories\": 314, \"protein\": 17.0, \"carbs\": 32.0, \"fat\": 12.0}"},
  {"name": "Pigs in a Blanket", "category": "Kid-Friendly", "description": "Cocktail sausages wrapped in buttery crescent roll dough and baked golden in minutes.", "servings": 8, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"refrigerated crescent rolls 8 oz each\"}, {\"qty\": \"48\", \"name\": \"cocktail smoked sausages\"}, {\"qty\": \"1\", \"name\": \"egg beaten (optional for egg wash)\"}]", "instructions": "1. Preheat oven to 375°F. Line baking sheets with parchment paper. 2. Unroll crescent roll dough and separate into triangles. Cut each triangle lengthwise into 3 narrow strips to yield 48 pieces. 3. Place one cocktail sausage at the wide end of each dough strip and roll up toward the narrow end. 4. Place seam-side down on prepared baking sheets. 5. Brush with egg wash if desired for extra browning. 6. Bake 12 to 15 minutes until crescent dough is golden brown. Serve warm with ketchup, mustard, or honey mustard.", "tags": "kid-friendly, party food, finger food", "source": "https://www.eatingonadime.com/pigs-in-a-blanket-how-to-make-pigs-in-a-blanket/", "nutritionData": "{\"calories\": 460, \"protein\": 15.0, \"carbs\": 28.0, \"fat\": 32.0}"},
  {"name": "Baked Chicken Parmesan", "category": "Kid-Friendly", "description": "Crispy breadcrumb-coated chicken topped with marinara and melted mozzarella over spaghetti.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breasts cut in half crosswise\"}, {\"qty\": \"3/4 cup\", \"name\": \"Italian breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded mozzarella cheese\"}, {\"qty\": \"1 cup\", \"name\": \"marinara sauce\"}, {\"qty\": \"1 lb\", \"name\": \"spaghetti\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 450°F. Line a baking sheet with parchment paper. Cook spaghetti according to package instructions; drain. 2. Combine breadcrumbs and Parmesan in a shallow bowl. 3. Brush each chicken piece with melted butter then dredge in breadcrumb mixture pressing to coat. 4. Place on baking sheet and bake 20 minutes. Gently flip and bake 5 more minutes until golden. 5. Spoon 1 tbsp marinara onto each piece and sprinkle with mozzarella. Bake 5 minutes until cheese melts. 6. Serve immediately over spaghetti with additional marinara on the side.", "tags": "kid-friendly, comfort food, Italian", "source": "https://damndelicious.net/2012/10/29/baked-chicken-parmesan/", "nutritionData": "{\"calories\": 822, \"protein\": 59.0, \"carbs\": 100.0, \"fat\": 19.0}"},
  {"name": "Cheesy Broccoli Rice", "category": "Kid-Friendly", "description": "Fluffy white rice folded with chopped broccoli, sharp cheddar, and Parmesan into a simple side.", "servings": 6, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"long grain white rice\"}, {\"qty\": \"3 cups\", \"name\": \"water\"}, {\"qty\": \"1 lb\", \"name\": \"frozen broccoli florets thawed\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}]", "instructions": "1. Combine rice and water in a large pot. Bring to a boil, reduce to low, cover, and simmer 15 minutes. Turn off heat and rest covered 5 minutes. 2. Chop thawed broccoli florets into small pieces. 3. Fluff rice with a fork. Stir in butter, salt, garlic powder, and pepper until butter melts. 4. Fold in chopped broccoli; the cooler broccoli will slightly lower the rice temperature. 5. Add Parmesan and cheddar and fold to combine. Cheese should soften but not fully melt. 6. Taste and adjust salt and butter. Serve immediately.", "tags": "kid-friendly, vegetarian, quick", "source": "https://www.budgetbytes.com/easy-cheesy-broccoli-rice/", "nutritionData": "{\"calories\": 407, \"protein\": 14.0, \"carbs\": 60.0, \"fat\": 12.0}"},
  {"name": "Homemade Fish Sticks", "category": "Kid-Friendly", "description": "Panko-breaded tilapia strips pan-fried to a crispy golden finish kids love with ketchup.", "servings": 4, "prepTime": 15, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"tilapia fillets\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"seasoning salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1 tsp\", \"name\": \"additional seasoning salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"canola or vegetable oil\"}]", "instructions": "1. Pat fish dry and cut into sticks about 3 inches long and 1/2 inch wide. 2. Set up three bowls: flour mixed with 1 tsp seasoning salt, whisked eggs, panko mixed with 1 tsp seasoning salt. 3. Bread each stick by dipping in flour, then egg, then pressing into panko. 4. Heat oil in a small skillet over medium heat until a pinch of panko sizzles on contact. 5. Fry fish sticks in batches 2 to 4 minutes per side until golden brown; do not crowd the pan. 6. Transfer to a paper-towel-lined plate to drain. Serve warm with ketchup or tartar sauce.", "tags": "kid-friendly, seafood, quick", "source": "https://www.budgetbytes.com/tilapia-fish-sticks/", "nutritionData": "{\"calories\": 371, \"protein\": 29.0, \"carbs\": 21.0, \"fat\": 19.0}"},
  {"name": "Sloppy Joe Crescent Cups", "category": "Kid-Friendly", "description": "Savory ground beef sloppy joe filling baked in crescent roll cups and topped with cheddar.", "servings": 8, "prepTime": 15, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"lean ground beef\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped onion\"}, {\"qty\": \"1 cup\", \"name\": \"sloppy joe sauce from a 15 oz can\"}, {\"qty\": \"1 can\", \"name\": \"refrigerated crescent rolls 8 oz\"}, {\"qty\": \"1 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"\", \"name\": \"cooking spray\"}]", "instructions": "1. Preheat oven to 375°F. Spray 8 regular muffin cups with cooking spray. 2. Cook ground beef and onion in a skillet over medium-high heat 5 to 7 minutes until no longer pink; drain fat. Stir in sloppy joe sauce and heat through; cool slightly. 3. Unroll crescent rolls and press seams together. Cut into 8 squares. 4. Press one square into the bottom and up the sides of each muffin cup. 5. Divide beef mixture evenly among cups (about 1/4 cup each). Top each with shredded cheddar. 6. Bake 14 to 18 minutes until dough is deep golden brown and filling is hot. Cool 5 minutes then remove with a metal spatula.", "tags": "kid-friendly, fun shapes, comfort food", "source": "https://familyaroundthetable.com/sloppy-joe-cups/", "nutritionData": "{\"calories\": 314, \"protein\": 20.0, \"carbs\": 17.0, \"fat\": 19.0}"},
  {"name": "Mini Meatballs in Marinara", "category": "Kid-Friendly", "description": "Tender bite-sized beef meatballs baked and simmered in marinara sauce for easy kid dinners.", "servings": 4, "prepTime": 15, "cookTime": 13, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1/4 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce\"}]", "instructions": "1. Preheat oven to 375°F and line a rimmed baking sheet with parchment paper. 2. Soak panko in milk for 2 minutes until absorbed to form a panade. 3. Gently combine ground beef, panade, egg, salt, garlic powder, onion powder, pepper, and Parmesan; do not overmix. 4. Roll into tablespoon-sized balls and arrange on baking sheet. 5. Bake 10 to 13 minutes until cooked through to 165°F. 6. Warm marinara sauce in a saucepan and add cooked meatballs; simmer 5 minutes. Serve over pasta or with crusty bread.", "tags": "kid-friendly, make-ahead, freezer-friendly", "source": "https://mamaknowsnutrition.com/recipes/mini-meatballs-recipe-for-the-whole-family/", "nutritionData": "{\"calories\": 408, \"protein\": 35.0, \"carbs\": 18.0, \"fat\": 25.0}"},
  {"name": "Creamy Chicken and Cheesy Rice Skillet", "category": "Kid-Friendly", "description": "One-pan chicken and rice simmered in broth with peas and carrots then broiled with melted cheddar.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2/3 lb\", \"name\": \"boneless skinless chicken breast diced\"}, {\"qty\": \"1 cup\", \"name\": \"long grain white rice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"3 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1/2 lb\", \"name\": \"frozen peas and carrots\"}, {\"qty\": \"1/3 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"4 oz\", \"name\": \"shredded cheddar cheese\"}]", "instructions": "1. Sauté diced onion in butter in a deep oven-safe skillet over medium heat until soft. 2. Add diced chicken and cook 3 minutes until opaque on outside. 3. Stir in rice, thyme, salt, pepper, and broth. Bring to a boil over medium-high heat. 4. Reduce to low, cover, and simmer 15 minutes stirring occasionally. 5. Stir in frozen vegetables; cover and cook 5 more minutes. Add cream and stir to combine. 6. Top with shredded cheddar and broil in oven 3 to 5 minutes until cheese is melted and bubbly. Serve hot.", "tags": "kid-friendly, one-pan, comfort food", "source": "https://www.budgetbytes.com/creamy-chicken-and-rice-skillet/", "nutritionData": "{\"calories\": 568, \"protein\": 37.0, \"carbs\": 46.0, \"fat\": 25.0}"},
  {"name": "Pancake Mini Muffins", "category": "Kid-Friendly", "description": "Fluffy bite-sized pancake muffins baked in a mini tin and served with warm maple syrup for dipping.", "servings": 6, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2.5 cups\", \"name\": \"milk\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter melted\"}, {\"qty\": \"1/2 cup\", \"name\": \"blueberries or mini chocolate chips optional\"}, {\"qty\": \"\", \"name\": \"warm maple syrup for serving\"}]", "instructions": "1. Preheat oven to 425°F. Generously spray a 24-cup mini muffin tin with baking spray. 2. Sift together flour, baking powder, sugar, and salt. 3. Stir together milk and eggs, then whisk in vanilla. Combine wet and dry ingredients, then stir in melted butter. 4. Fill each muffin cup 2/3 full with batter. 5. Drop 2 to 3 blueberries or a pinch of chocolate chips into each cup if desired. 6. Bake 8 to 9 minutes until tops are golden brown. Let cool 2 minutes in pan then turn out. Serve warm with maple syrup for dipping.", "tags": "kid-friendly, breakfast, fun shapes", "source": "https://www.thepioneerwoman.com/food-cooking/recipes/a11683/pancake-mini-muffins/", "nutritionData": "{\"calories\": 340, \"protein\": 8.0, \"carbs\": 39.0, \"fat\": 17.0}"},
  {"name": "Sneaky Veggie Pasta Sauce", "category": "Kid-Friendly", "description": "A silky tomato pasta sauce blended with five hidden vegetables that kids will never detect.", "servings": 8, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium onion chopped\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"carrot peeled and chopped\"}, {\"qty\": \"1\", \"name\": \"bell pepper chopped\"}, {\"qty\": \"1\", \"name\": \"zucchini peeled and chopped\"}, {\"qty\": \"1\", \"name\": \"medium roasted sweet potato peeled and cubed\"}, {\"qty\": \"1.5 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1 can\", \"name\": \"6 oz tomato paste\"}, {\"qty\": \"1 can\", \"name\": \"28 oz diced tomatoes with juice\"}, {\"qty\": \"1\", \"name\": \"carton 32 oz chicken or vegetable broth\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Heat olive oil in a large Dutch oven over medium heat. Add onion and sauté 3 minutes until fragrant. 2. Add garlic, carrot, bell pepper, zucchini, and sweet potato. Cook stirring occasionally 5 to 10 minutes. 3. Stir in Italian seasoning, tomato paste, diced tomatoes, and broth. Bring to a gentle simmer then turn off heat. 4. Carefully transfer sauce in two batches to a blender and purée until smooth. 5. Return puréed sauce to pot and simmer on low 5 minutes. Season with salt and pepper. 6. Toss with cooked pasta or use as pizza sauce. Freeze leftovers in airtight containers for up to 3 months.", "tags": "kid-friendly, sneaky veggies, make-ahead", "source": "https://www.caligirlcooking.com/hidden-veggie-pasta-sauce/", "nutritionData": "{\"calories\": 109, \"protein\": 4.0, \"carbs\": 17.0, \"fat\": 4.0}"},
  {"name": "Zucchini Pasta with Creamy Sauce", "category": "Kid-Friendly", "description": "Roasted zucchini blended into a silky Parmesan sauce tossed with pasta for a sneaky-veggie dinner.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium onion cut into 1/2-inch pieces\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"24 oz\", \"name\": \"zucchini sliced 1/4 inch thick\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"freshly grated Parmesan\"}, {\"qty\": \"1 lb\", \"name\": \"pasta such as cavatappi or fusilli\"}]", "instructions": "1. Toss zucchini with garlic, onion, olive oil, salt, and pepper. Spread on a sheet pan and roast at 425°F for 25 minutes until tender and browned, tossing halfway. 2. Meanwhile bring a large pot of salted water to a boil and cook pasta al dente per package directions. Reserve 1 cup pasta water before draining. 3. Transfer roasted vegetables to a blender. Add Parmesan and broth and purée until smooth. 4. Return drained pasta to pot and pour zucchini sauce over top. Toss to coat, adding reserved pasta water as needed to loosen the sauce. 5. Top with fresh black pepper and extra Parmesan. Serve immediately.", "tags": "kid-friendly, sneaky veggies, vegetarian", "source": "https://www.skinnytaste.com/pasta-with-creamy-zucchini-sauce/", "nutritionData": "{\"calories\": 578, \"protein\": 22.0, \"carbs\": 94.0, \"fat\": 13.0}"},
  {"name": "Cheesy Pasta Bake", "category": "Kid-Friendly", "description": "Hearty penne baked with a meat sauce, ricotta, and three cheeses until bubbling and golden.", "servings": 8, "prepTime": 20, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"penne pasta\"}, {\"qty\": \"1 lb\", \"name\": \"ground beef or turkey\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped onion\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"1 can\", \"name\": \"8 oz tomato sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 cups\", \"name\": \"ricotta cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded Parmesan\"}, {\"qty\": \"3 cups\", \"name\": \"shredded mozzarella\"}]", "instructions": "1. Preheat oven to 375°F and grease a 9x13-inch baking dish. Cook pasta al dente; drain. 2. Brown ground meat with onion, salt, and pepper in a skillet; drain fat. 3. Add crushed tomatoes, tomato sauce, basil, oregano, and garlic powder. Simmer 5 minutes. 4. Remove from heat and stir in cooked pasta to coat evenly. 5. In a small bowl stir together ricotta and Parmesan. 6. Spread half the noodle mixture in the baking dish. Dollop ricotta mixture over top and spread. Sprinkle with half the mozzarella. Layer remaining noodles and top with remaining mozzarella. 7. Bake 30 to 35 minutes until bubbling. Rest 10 minutes before serving.", "tags": "kid-friendly, make-ahead, comfort food", "source": "https://www.melskitchencafe.com/easy-cheesy-pasta-bake/", "nutritionData": "{\"calories\": 647, \"protein\": 42.0, \"carbs\": 54.0, \"fat\": 28.0}"},
  {"name": "Tater Tot Casserole", "category": "Kid-Friendly", "description": "Classic ground beef casserole topped with crispy tater tots and melted cheddar cheese.", "servings": 6, "prepTime": 10, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small onion finely chopped\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2 cans\", \"name\": \"10.5 oz each condensed cream of mushroom soup\"}, {\"qty\": \"1.25 cups\", \"name\": \"milk\"}, {\"qty\": \"32 oz\", \"name\": \"frozen tater tots\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese\"}]", "instructions": "1. Preheat oven to 350°F. Spray a 9x13-inch baking dish with nonstick spray. 2. Brown ground beef and onion in a large skillet over medium heat until no longer pink; drain fat. Season with salt and pepper. 3. Transfer meat mixture to prepared baking dish. Top with frozen tater tots in an even layer. 4. Whisk together cream of mushroom soup and milk in a bowl; pour evenly over the tater tots. 5. Sprinkle shredded cheddar cheese on top. 6. Bake uncovered 40 minutes until tater tots are golden and filling is bubbling. Serve hot.", "tags": "kid-friendly, comfort food, casserole", "source": "Classic", "nutritionData": "{\"calories\": 810, \"protein\": 45.0, \"carbs\": 50.0, \"fat\": 50.0}"},
  {"name": "Classic Sloppy Joes", "category": "Kid-Friendly", "description": "Sweet and tangy ground beef filling piled high on soft hamburger buns for a messy classic.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1/2\", \"name\": \"medium onion finely chopped\"}, {\"qty\": \"1\", \"name\": \"small green bell pepper finely chopped\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3/4 cup\", \"name\": \"ketchup\"}, {\"qty\": \"1/4 cup\", \"name\": \"tomato paste\"}, {\"qty\": \"2.5 tbsp\", \"name\": \"dark brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"yellow mustard\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"4\", \"name\": \"hamburger buns\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Brown ground beef with onion, bell pepper, and garlic in a large skillet over medium-high heat, breaking into small pieces; drain fat. 2. Stir in ketchup, tomato paste, brown sugar, mustard, and Worcestershire sauce. 3. Add water and stir to combine. Season with salt and pepper. 4. Cook over medium-high heat 7 to 8 minutes stirring often until sauce thickens. 5. Spoon generously onto hamburger buns and serve immediately with plenty of napkins.", "tags": "kid-friendly, comfort food, quick", "source": "Classic", "nutritionData": "{\"calories\": 416, \"protein\": 32.0, \"carbs\": 31.0, \"fat\": 19.0}"},
  {"name": "Stovetop Mac and Cheese", "category": "Kid-Friendly", "description": "One-pot creamy macaroni and cheese made with a simple milk-cooked pasta method and sharp cheddar.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"dry elbow macaroni\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"additional milk if needed\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/4 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}]", "instructions": "1. Combine dry macaroni and 2 cups milk in a medium pot with a lid. Bring to a boil over medium-high heat stirring occasionally. 2. Reduce heat to low and simmer stirring often until pasta is tender and has absorbed most of the milk, about 10 minutes. Replace lid quickly after each stir. 3. Season with salt, pepper, paprika, and Dijon mustard. If mixture looks dry, add the remaining milk. 4. Turn off heat and stir in shredded cheddar until melted and creamy. 5. Serve immediately.", "tags": "kid-friendly, one-pot, quick", "source": "https://www.budgetbytes.com/miracle-mac-n-cheese/", "nutritionData": "{\"calories\": 571, \"protein\": 25.0, \"carbs\": 82.0, \"fat\": 15.0}"},
  {"name": "Pizza Sausage Rolls", "category": "Kid-Friendly", "description": "Bagel-dough rolls stuffed with pizza sauce, mozzarella, and Italian sausage baked golden and sliced.", "servings": 4, "prepTime": 20, "cookTime": 28, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour plus more for dusting\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"non-fat Greek yogurt\"}, {\"qty\": \"2\", \"name\": \"raw chicken Italian sausage links halved lengthwise\"}, {\"qty\": \"4 slices\", \"name\": \"provolone or mozzarella cheese\"}, {\"qty\": \"8 tsp\", \"name\": \"pizza sauce\"}, {\"qty\": \"1\", \"name\": \"egg white beaten\"}, {\"qty\": \"\", \"name\": \"sesame seeds optional\"}]", "instructions": "1. Preheat oven to 400°F. Line a baking sheet with parchment paper and spray with oil. 2. Whisk flour, baking powder, and salt. Add yogurt and mix until combined. Knead on floured surface 15 turns until tacky but not sticky. 3. Divide dough into 4 equal balls. Roll each into a 5.5-inch circle about 1/4 inch thick. 4. Spread 2 tsp pizza sauce down the center of each circle leaving a 1/2-inch border. Top with 1 cheese slice then 1/2 sausage link. 5. Bring sides of dough up and wrap around sausage; press seams to seal. Place seam-side down on baking sheet. 6. Brush with egg wash and top with sesame seeds if using. Bake 25 to 30 minutes until golden. 7. Cool 5 minutes then slice each roll into 6 pieces and serve.", "tags": "kid-friendly, fun shapes, Italian", "source": "https://www.skinnytaste.com/pizza-sausage-rolls/", "nutritionData": "{\"calories\": 337, \"protein\": 25.0, \"carbs\": 36.0, \"fat\": 10.0}"},
  {"name": "Hidden Veggie Mini Meatballs", "category": "Kid-Friendly", "description": "Baked beef meatballs with carrots, onion, and parsley blended right in for extra nutrition.", "servings": 4, "prepTime": 15, "cookTime": 24, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 cup\", \"name\": \"carrots roughly chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"parsley leaves\"}, {\"qty\": \"1\", \"name\": \"small onion peeled and halved\"}, {\"qty\": \"1/2 cup\", \"name\": \"Italian breadcrumbs\"}, {\"qty\": \"1 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"milk\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"marinara sauce for serving\"}]", "instructions": "1. Preheat oven to 375°F and line a rimmed baking sheet with foil; coat with nonstick spray. 2. Add carrots, parsley, and onion to a food processor and grind well, scraping down sides as needed. 3. Add remaining ingredients and pulse to combine into a smooth mixture. 4. Portion into 2-tablespoon-size meatballs and place on baking sheet. 5. Bake 22 to 25 minutes until cooked through. 6. Simmer in warm marinara sauce for 5 minutes if desired. Serve over pasta or with bread.", "tags": "kid-friendly, sneaky veggies, freezer-friendly", "source": "https://www.yummytoddlerfood.com/hidden-veggie-toddler-meatballs/", "nutritionData": "{\"calories\": 442, \"protein\": 38.0, \"carbs\": 17.0, \"fat\": 26.0}"},
  {"name": "Sheet Pan Chicken Parmesan", "category": "Kid-Friendly", "description": "Easy sheet-pan chicken cutlets breaded and baked with burst cherry tomatoes and fresh mozzarella.", "servings": 4, "prepTime": 15, "cookTime": 23, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"mixed cherry or grape tomatoes\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4\", \"name\": \"chicken cutlets\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"6 oz\", \"name\": \"fresh mozzarella sliced\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}]", "instructions": "1. Preheat oven to 400°F and lightly oil a baking sheet. 2. Toss tomatoes with garlic, oregano, olive oil, salt, and pepper in a bowl; set aside. 3. Season chicken with salt and pepper. Dredge in flour, dip in beaten eggs, then press into panko to coat. 4. Place chicken on baking sheet and coat with nonstick spray. Bake 8 minutes. 5. Scatter tomato mixture around chicken and bake 15 more minutes until chicken is cooked through and tomatoes have burst. 6. Top chicken with mozzarella during the last 10 minutes of cooking. Garnish with fresh basil and serve immediately.", "tags": "kid-friendly, sheet pan, Italian", "source": "https://damndelicious.net/2022/05/20/sheet-pan-chicken-parmesan/", "nutritionData": "{\"calories\": 314, \"protein\": 16.0, \"carbs\": 27.0, \"fat\": 14.0}"},
  {"name": "Cheesy Ground Beef Rice Casserole", "category": "Kid-Friendly", "description": "Ground beef and white rice baked together with cream soup and topped with bubbly cheddar cheese.", "servings": 6, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"1 cup\", \"name\": \"long grain white rice uncooked\"}, {\"qty\": \"1 can\", \"name\": \"10.5 oz condensed cream of mushroom soup\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded cheddar cheese\"}]", "instructions": "1. Preheat oven to 350°F and grease a 9x13-inch baking dish. 2. Brown ground beef with onion in a skillet over medium heat; drain fat. Season with garlic powder, salt, and pepper. 3. Whisk together cream of mushroom soup and beef broth in a bowl until smooth. 4. Spread uncooked rice evenly in the baking dish. Top with browned beef mixture. Pour soup-broth mixture evenly over top. 5. Cover tightly with foil and bake 35 minutes until rice is tender. 6. Uncover, sprinkle with cheddar, and bake uncovered 5 more minutes until cheese is melted and bubbly. Serve hot.", "tags": "kid-friendly, casserole, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 474, \"protein\": 31.0, \"carbs\": 34.0, \"fat\": 24.0}"},
  {"name": "Butter Noodles with Parmesan", "category": "Kid-Friendly", "description": "Simple egg noodles tossed in butter and showered with Parmesan for the ultimate kid-approved pasta.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"egg noodles or spaghetti\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"freshly grated Parmesan cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley optional\"}]", "instructions": "1. Cook pasta in a large pot of well-salted boiling water per package directions until al dente. Reserve 1/2 cup pasta water before draining. 2. Drain pasta and return to the pot over low heat. 3. Add butter and toss until melted and pasta is coated. 4. Sprinkle in garlic powder and Parmesan and toss to combine; add a splash of reserved pasta water if needed to loosen. 5. Season with salt and pepper to taste. 6. Serve immediately garnished with extra Parmesan and parsley if desired.", "tags": "kid-friendly, quick, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 468, \"protein\": 16.0, \"carbs\": 64.0, \"fat\": 16.0}"},
  {"name": "Homemade Chicken Tenders with Ranch", "category": "Kid-Friendly", "description": "Whole wheat breadcrumb-coated baked chicken strips served with a cool Greek yogurt ranch dip.", "servings": 4, "prepTime": 15, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast cut into 1-inch strips\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"whole wheat breadcrumbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1/2 cup\", \"name\": \"Greek yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder for ranch\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder for ranch\"}]", "instructions": "1. In a small bowl stir together Greek yogurt, mayonnaise, 1/2 tsp garlic powder, 1/2 tsp onion powder, salt, and pepper for the ranch; refrigerate. 2. Preheat oven to 450°F. Place a wire rack on a baking sheet and coat with cooking spray. 3. Season chicken strips with salt and pepper. Set up flour, beaten eggs, and breadcrumbs mixed with garlic and onion powder in three bowls. 4. Dredge strips in flour, dip in egg, then press in breadcrumbs to coat. Place on rack and spray with cooking spray. 5. Bake 8 minutes, flip each strip and spray again. Bake 8 to 10 more minutes until crisp and golden. 6. Serve immediately with Greek yogurt ranch.", "tags": "kid-friendly, baked, dippable", "source": "https://damndelicious.net/2013/05/21/chicken-tenders-with-greek-yogurt-ranch/", "nutritionData": "{\"calories\": 456, \"protein\": 46.0, \"carbs\": 32.0, \"fat\": 14.0}"},
  {"name": "Mini Pepperoni Flatbread Pizzas", "category": "Kid-Friendly", "description": "English muffin pizzas topped with marinara, mozzarella, and pepperoni ready in under 20 minutes.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"English muffins split in half\"}, {\"qty\": \"1 cup\", \"name\": \"marinara or pizza sauce\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded mozzarella cheese\"}, {\"qty\": \"2 oz\", \"name\": \"mini pepperoni slices\"}, {\"qty\": \"1/4 tsp\", \"name\": \"dried oregano\"}]", "instructions": "1. Preheat oven to 400°F. Arrange English muffin halves cut-side up on a baking sheet. 2. Spread about 2 tbsp marinara sauce on each muffin half. 3. Top each with shredded mozzarella, dividing evenly. 4. Scatter mini pepperoni over the cheese. Sprinkle with oregano. 5. Bake 8 to 10 minutes until cheese is melted and bubbly and muffin edges are toasted. 6. Cool 2 minutes before serving so cheese does not burn little mouths.", "tags": "kid-friendly, quick, pizza night", "source": "Classic", "nutritionData": "{\"calories\": 348, \"protein\": 18.0, \"carbs\": 34.0, \"fat\": 15.0}"},
  {"name": "BBQ Mini Meatball Lunchbox Bites", "category": "Kid-Friendly", "description": "Juicy pan-cooked mini meatballs coated in smoky BBQ sauce for lunchboxes or after-school snacking.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"1 cup\", \"name\": \"barbecue sauce\"}]", "instructions": "1. Combine ground beef with garlic powder, onion powder, salt, and pepper in a large bowl; mix gently. 2. Using a small cookie scoop or hands roll mixture into mini meatballs roughly 1 inch in diameter. 3. Heat a large skillet over medium heat and cook meatballs in batches turning occasionally 8 to 10 minutes until cooked through and no longer pink inside. 4. Drain excess fat from skillet. Return meatballs to pan and add barbecue sauce. 5. Stir to coat all meatballs in sauce and heat through over low heat 2 minutes. 6. Serve warm or pack into lunchboxes once cooled.", "tags": "kid-friendly, lunchbox, finger food", "source": "https://familyaroundthetable.com/lunchbox-mini-bbq-meatballs/", "nutritionData": "{\"calories\": 483, \"protein\": 44.0, \"carbs\": 14.0, \"fat\": 29.0}"},
  {"name": "Scrambled Egg Breakfast Quesadillas", "category": "Kid-Friendly", "description": "Fluffy scrambled eggs with cheddar and mild salsa folded inside a golden flour tortilla.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"milk\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"4\", \"name\": \"large flour tortillas\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"mild salsa\"}, {\"qty\": \"\", \"name\": \"sour cream for serving\"}]", "instructions": "1. Whisk eggs with milk, salt, and pepper until blended. 2. Melt butter in a nonstick skillet over medium-low heat and scramble eggs gently until just set; remove from heat. 3. Warm a clean skillet or griddle over medium heat. 4. Lay one tortilla flat and sprinkle half with cheese; top with scrambled eggs and a spoonful of salsa then fold over. 5. Cook quesadilla 2 to 3 minutes per side until golden brown and cheese is melted. Repeat with remaining tortillas. 6. Slice into wedges and serve with sour cream.", "tags": "kid-friendly, breakfast, quick", "source": "Classic", "nutritionData": "{\"calories\": 451, \"protein\": 24.0, \"carbs\": 24.0, \"fat\": 29.0}"},
  {"name": "Pull-Apart Garlic Cheese Bread Bites", "category": "Kid-Friendly", "description": "Soft pull-apart rolls brushed with garlic butter and loaded with gooey mozzarella inside.", "servings": 6, "prepTime": 15, "cookTime": 18, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 can\", \"name\": \"refrigerated biscuit dough 8-count\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"marinara sauce for dipping\"}]", "instructions": "1. Preheat oven to 375°F. Grease a 9-inch round baking dish or cast iron skillet. 2. Mix melted butter with garlic and parsley in a small bowl. 3. Cut each biscuit round into quarters. Toss biscuit pieces with garlic butter, mozzarella, and Parmesan until evenly coated. 4. Arrange coated pieces in the prepared dish in a single somewhat crowded layer. 5. Bake 15 to 18 minutes until dough is cooked through and tops are golden brown. 6. Serve warm straight from the dish with marinara sauce for dipping.", "tags": "kid-friendly, cheesy, fun shapes", "source": "Classic", "nutritionData": "{\"calories\": 282, \"protein\": 9.0, \"carbs\": 24.0, \"fat\": 18.0}"},
  {"name": "Simple Stovetop Chicken Quesadillas", "category": "Kid-Friendly", "description": "Quick skillet quesadillas filled with seasoned chicken and melted Monterey Jack cheese.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"cooked shredded rotisserie chicken\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Monterey Jack cheese\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded cheddar\"}, {\"qty\": \"4\", \"name\": \"medium flour tortillas\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salsa and sour cream for serving\"}]", "instructions": "1. Toss shredded chicken with chili powder, garlic powder, and salt in a bowl. 2. Heat a large skillet over medium heat with a small drizzle of olive oil. 3. Lay one tortilla flat and sprinkle cheese over half the tortilla. Top with seasoned chicken and more cheese then fold tortilla in half. 4. Cook quesadilla 3 to 4 minutes until golden on the bottom. Flip and cook 2 minutes more. 5. Repeat with remaining tortillas. 6. Cut each quesadilla into 3 wedges and serve with salsa and sour cream.", "tags": "kid-friendly, quick, weeknight", "source": "https://www.wellplated.com/chicken-quesadilla/", "nutritionData": "{\"calories\": 479, \"protein\": 38.0, \"carbs\": 23.0, \"fat\": 25.0}"},
  {"name": "Spaghetti Carbonara", "category": "Pasta", "description": "Rich Roman pasta with eggs, guanciale, and pecorino forming a silky cream-free sauce.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried spaghetti\"}, {\"qty\": \"3 oz\", \"name\": \"guanciale or pancetta diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil divided\"}, {\"qty\": \"2\", \"name\": \"whole large eggs\"}, {\"qty\": \"6\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmigiano-Reggiano\"}, {\"qty\": \"1 tsp\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}]", "instructions": "1. Bring a large pot of salted water to a boil and cook spaghetti until al dente. 2. Cook guanciale with 2 tbsp olive oil over medium heat until fat renders and meat is crisp about 7 minutes. 3. Whisk eggs yolks Pecorino Parmigiano and pepper together in a large heatproof metal bowl. 4. Transfer pasta to skillet with guanciale using tongs leaving pasta water in pot. 5. Add remaining 1 tbsp olive oil and let pasta cool slightly then scrape pasta and pork into egg mixture. 6. Add 1/2 cup pasta water to bowl stir well then set bowl over pot of simmering water. 7. Stir constantly with tongs until sauce thickens to a creamy silky consistency. 8. Season with salt divide into bowls and top with extra cheese and pepper.", "tags": "roman-style, weeknight, pork", "source": "https://www.seriouseats.com/pasta-carbonara-sauce-recipe", "nutritionData": "{\"calories\": 824, \"protein\": 29.0, \"carbs\": 89.0, \"fat\": 38.0}"},
  {"name": "Cacio e Pepe", "category": "Pasta", "description": "Three-ingredient Roman pasta coated in a glossy sauce of pecorino and toasted black pepper.", "servings": 2, "prepTime": 5, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"spaghetti or tonnarelli\"}, {\"qty\": \"2 oz\", \"name\": \"Pecorino Romano finely grated\"}, {\"qty\": \"1 oz\", \"name\": \"Parmigiano-Reggiano finely grated\"}, {\"qty\": \"1 tsp\", \"name\": \"whole black peppercorns toasted and coarsely ground\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}]", "instructions": "1. Bring a medium pot of lightly salted water to a boil and cook pasta reserving 1 cup starchy water before draining. 2. Toast peppercorns in a dry skillet over medium heat until fragrant then coarsely grind. 3. Add 1/2 cup pasta water and butter to a large skillet over medium heat and stir to combine. 4. Add cooked pasta and toss vigorously until water emulsifies with butter. 5. Remove from heat and add both cheeses tossing rapidly with tongs. 6. Add pasta water a splash at a time until sauce is glossy and clings to noodles. 7. Plate immediately and finish with extra pepper and cheese.", "tags": "roman-style, vegetarian, minimalist", "source": "Classic", "nutritionData": "{\"calories\": 722, \"protein\": 32.0, \"carbs\": 91.0, \"fat\": 25.0}"},
  {"name": "Bucatini Allamatriciana", "category": "Pasta", "description": "Bucatini tossed in a spicy tomato sauce with guanciale and Pecorino Romano.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"bucatini\"}, {\"qty\": \"6 oz\", \"name\": \"guanciale sliced into strips\"}, {\"qty\": \"1 can\", \"name\": \"28 oz whole San Marzano tomatoes crushed\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook guanciale in olive oil over medium heat until fat renders and edges crisp about 8 minutes. 2. Add red pepper flakes and cook 30 seconds then deglaze with white wine and simmer until evaporated. 3. Add crushed tomatoes season with salt and simmer 15 minutes until sauce thickens. 4. Cook bucatini in a large pot of salted water until al dente reserving 1 cup pasta water. 5. Add drained pasta to sauce and toss over medium heat adding pasta water as needed. 6. Remove from heat stir in half the pecorino and plate. 7. Top with remaining pecorino and a grind of black pepper.", "tags": "roman-style, spicy, pork", "source": "https://www.seriouseats.com/recipes/2016/03/bucatini-pasta-amatriciana-recipe.html", "nutritionData": "{\"calories\": 837, \"protein\": 26.0, \"carbs\": 96.0, \"fat\": 38.0}"},
  {"name": "Simple Essential Bolognese", "category": "Pasta", "description": "A slow-simmered meat ragu from Smitten Kitchen that develops deep flavor over several hours.", "servings": 6, "prepTime": 20, "cookTime": 200, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground beef\"}, {\"qty\": \"4 oz\", \"name\": \"pancetta optional\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"2\", \"name\": \"carrots\"}, {\"qty\": \"3\", \"name\": \"celery stalks\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"pinch freshly grated nutmeg\"}, {\"qty\": \"\", \"name\": \"kosher salt and pepper\"}, {\"qty\": \"1 lb\", \"name\": \"tagliatelle or pappardelle\"}, {\"qty\": \"\", \"name\": \"Parmigiano-Reggiano for serving\"}]", "instructions": "1. Pulse onion carrot celery and garlic in a food processor until finely chopped. 2. If using pancetta cook in a large Dutch oven until crisp then add vegetables and cook until browned about 10 minutes. 3. Add ground beef and cook until deeply browned about 10 minutes. 4. Add milk and cook until absorbed then add wine and cook until evaporated. 5. Stir in tomato paste bay leaf and nutmeg then add 2 cups water and bring to a simmer. 6. Cook uncovered on lowest heat for 3 hours adding water as needed. 7. Boil pasta until 1 to 2 minutes shy of done then toss with ragu and reserved pasta water. 8. Serve in wide bowls with Parmigiano.", "tags": "slow-cook, make-ahead, weekend", "source": "https://smittenkitchen.com/2020/05/simple-essential-bolognese/", "nutritionData": "{\"calories\": 582, \"protein\": 37.0, \"carbs\": 61.0, \"fat\": 20.0}"},
  {"name": "Classic Fettuccine Alfredo", "category": "Pasta", "description": "Silky buttery fettuccine made without cream using only butter Parmesan and starchy pasta water.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fettuccine\"}, {\"qty\": \"1 stick\", \"name\": \"8 tbsp unsalted butter\"}, {\"qty\": \"1 cup\", \"name\": \"finely grated Parmigiano-Reggiano plus more for serving\"}, {\"qty\": \"1 cup\", \"name\": \"pasta cooking water reserved\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}]", "instructions": "1. Cook fettuccine in a large pot of salted boiling water and reserve 2 cups pasta water before draining. 2. Melt butter in a large saucepan over medium heat then add 1 cup pasta water and whisk to combine. 3. Add drained pasta and toss vigorously. 4. Add grated Parmesan in three batches tossing constantly between additions. 5. Add more pasta water a splash at a time until sauce is creamy and glossy. 6. Season with salt and pepper then plate and top with extra cheese.", "tags": "vegetarian, quick, buttery", "source": "https://www.bonappetit.com/recipe/fettuccine-alfredo", "nutritionData": "{\"calories\": 741, \"protein\": 25.0, \"carbs\": 88.0, \"fat\": 32.0}"},
  {"name": "Rigatoni With Easy Vodka Sauce", "category": "Pasta", "description": "Creamy tangy tomato vodka sauce with rigatoni for a pantry-friendly weeknight dinner.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"rigatoni\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"shallot finely chopped\"}, {\"qty\": \"2\", \"name\": \"garlic cloves finely chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"tomato paste\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"vodka\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"finely grated Parmigiano-Reggiano\"}, {\"qty\": \"\", \"name\": \"fresh basil for serving\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}]", "instructions": "1. In a large skillet melt butter over medium heat and sauté shallot and garlic until soft 4 to 5 minutes. 2. Add tomato paste and red pepper flakes and cook stirring until paste darkens about 5 minutes. 3. Add vodka and stir scraping up any browned bits then remove from heat briefly. 4. Cook rigatoni in salted water until al dente reserving 2 cups pasta water. 5. Return sauce to medium heat add cream and 1/4 cup pasta water and stir to combine. 6. Stir in half the Parmesan until melted then add drained pasta. 7. Fold in remaining cheese adding pasta water as needed and season with salt. 8. Serve topped with fresh basil.", "tags": "quick, pantry-friendly, creamy", "source": "https://www.bonappetit.com/recipe/rigatoni-with-easy-vodka-sauce", "nutritionData": "{\"calories\": 689, \"protein\": 22.0, \"carbs\": 95.0, \"fat\": 25.0}"},
  {"name": "Garden Herb Shrimp Scampi Linguine", "category": "Pasta", "description": "Garlicky butter-lemon shrimp scampi with zucchini and fresh herbs over linguine.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried linguine\"}, {\"qty\": \"4 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 lb\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"2\", \"name\": \"small zucchini thinly sliced\"}, {\"qty\": \"1\", \"name\": \"shallot finely chopped\"}, {\"qty\": \"4 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1 pinch\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"\", \"name\": \"zest and juice of 1 lemon\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook linguine in well-salted water until al dente reserving 1 cup pasta water then drain. 2. Heat 2 tbsp olive oil in a large skillet and sear shrimp seasoned with salt and pepper 2 to 3 minutes per side then remove. 3. Add remaining oil to skillet along with zucchini and shallot and cook 5 minutes. 4. Add butter garlic thyme and red pepper flakes and cook until fragrant 1 to 2 minutes. 5. Pour in wine lemon zest and juice and bring to a simmer. 6. Add shrimp back and toss in pasta thinning sauce with pasta water as needed. 7. Remove from heat and stir in parsley and chives. 8. Divide into plates and garnish with fresh herbs.", "tags": "seafood, quick, summer", "source": "https://www.halfbakedharvest.com/garden-herb-shrimp-scampi-linguine/", "nutritionData": "{\"calories\": 768, \"protein\": 43.0, \"carbs\": 87.0, \"fat\": 27.0}"},
  {"name": "Spaghetti Puttanesca", "category": "Pasta", "description": "Bold and briny tomato sauce with anchovies olives capers and garlic over spaghetti.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"spaghetti\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"4\", \"name\": \"anchovy fillets\"}, {\"qty\": \"3 tbsp\", \"name\": \"capers drained\"}, {\"qty\": \"1/2 cup\", \"name\": \"pitted Kalamata olives halved\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"1/4 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"\", \"name\": \"fresh parsley for serving\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}]", "instructions": "1. Heat olive oil in a large skillet over medium heat and cook garlic until golden about 1 minute. 2. Add anchovies capers olives and red pepper flakes and cook 1 to 2 minutes until anchovies dissolve. 3. Stir in crushed tomatoes and oregano season lightly and simmer 10 to 15 minutes. 4. Cook spaghetti in salted water until al dente reserving 1/2 cup pasta water. 5. Add drained pasta to sauce with a splash of pasta water and toss over low heat 1 minute. 6. Plate and garnish with fresh parsley.", "tags": "weeknight, bold-flavors, seafood", "source": "https://www.seriouseats.com/spaghetti-puttanesca-pasta-week-capers-olives-anchovies-recipe", "nutritionData": "{\"calories\": 581, \"protein\": 17.0, \"carbs\": 96.0, \"fat\": 14.0}"},
  {"name": "Simplest Spaghetti al Limone", "category": "Pasta", "description": "Bright uncooked lemon Parmesan sauce over hot spaghetti with fresh basil and olive oil.", "servings": 2, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"dried spaghetti\"}, {\"qty\": \"1\", \"name\": \"lemon zest of half juice of whole\"}, {\"qty\": \"3.5 oz\", \"name\": \"Parmigiano-Reggiano finely grated\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"\", \"name\": \"kosher salt and freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"fresh basil leaves torn\"}]", "instructions": "1. Cook spaghetti in well-salted water until al dente reserving 1 cup pasta water. 2. Grate lemon zest into a large serving bowl and add the lemon juice. 3. Grate Parmesan over the bowl and add olive oil salt and pepper. 4. Whisk together until smooth and combined. 5. Add hot drained spaghetti to the bowl and toss until coated. 6. Add reserved pasta water a tablespoon at a time tossing until glossy and lightly sauced. 7. Stir in basil and finish with a drizzle of olive oil and extra Parmesan.", "tags": "vegetarian, quick, summer", "source": "https://smittenkitchen.com/2019/06/simplest-spaghetti-al-limone/", "nutritionData": "{\"calories\": 842, \"protein\": 35.0, \"carbs\": 91.0, \"fat\": 37.0}"},
  {"name": "Slow Roasted Mushroom Pasta", "category": "Pasta", "description": "Sheet-pan roasted mushrooms and chickpeas over pasta with burrata and balsamic drizzle.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"linguine\"}, {\"qty\": \"1 lb\", \"name\": \"mixed mushrooms cremini and shiitake\"}, {\"qty\": \"1 can\", \"name\": \"15 oz chickpeas drained\"}, {\"qty\": \"6 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"3 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"4\", \"name\": \"garlic cloves smashed\"}, {\"qty\": \"1\", \"name\": \"lemon zested and juiced\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 cups\", \"name\": \"lacinato kale torn\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"8 oz\", \"name\": \"burrata at room temperature\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 425°F. 2. Toss mushrooms and chickpeas with olive oil rosemary garlic lemon zest and salt on a large sheet pan. 3. Roast 30 to 35 minutes tossing once until mushrooms are caramelized and chickpeas are crisp. 4. Cook linguine in salted water until al dente drain and return to pot. 5. Toss pasta with butter balsamic vinegar Parmesan and kale until kale wilts. 6. Fold in roasted mushrooms and chickpeas. 7. Divide into plates top with burrata and drizzle with olive oil.", "tags": "vegetarian, sheet-pan, umami", "source": "https://www.halfbakedharvest.com/slow-roasted-mushroom-pasta/", "nutritionData": "{\"calories\": 909, \"protein\": 35.0, \"carbs\": 87.0, \"fat\": 48.0}"},
  {"name": "My Old-School Baked Ziti", "category": "Pasta", "description": "Classic crowd-pleasing baked ziti with meat sauce mozzarella and dollops of ricotta.", "servings": 8, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ziti\"}, {\"qty\": \"1 lb\", \"name\": \"Italian sausage or ground beef\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"2 cups\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"olive oil\"}]", "instructions": "1. Preheat oven to 400°F. 2. Cook ziti until 2 minutes shy of al dente drain and reserve 1/2 cup pasta water. 3. Brown meat with onion garlic oregano and red pepper flakes in an ovenproof skillet 6 to 8 minutes. 4. Add crushed tomatoes and simmer 5 minutes then stir in spinach until wilted. 5. Stir drained pasta into sauce and thin with pasta water if needed. 6. Pour half pasta mixture into a 9x13 baking dish and top with half the cheeses. 7. Add remaining pasta and finish with remaining mozzarella and Parmesan. 8. Bake 30 minutes until bubbling and golden.", "tags": "baked, crowd-pleasing, make-ahead", "source": "https://smittenkitchen.com/2015/10/my-old-school-baked-ziti/", "nutritionData": "{\"calories\": 596, \"protein\": 30.0, \"carbs\": 51.0, \"fat\": 29.0}"},
  {"name": "Lasagna Bolognese", "category": "Pasta", "description": "Decadent multi-layer lasagna with slow-cooked bolognese bechamel and Parmesan.", "servings": 8, "prepTime": 60, "cookTime": 240, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"For bolognese: 1 lb ground beef\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"2\", \"name\": \"carrots\"}, {\"qty\": \"3\", \"name\": \"celery stalks\"}, {\"qty\": \"1 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"For bechamel: 4 tbsp butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 cups\", \"name\": \"whole milk\"}, {\"qty\": \"\", \"name\": \"pinch nutmeg\"}, {\"qty\": \"\", \"name\": \"For assembly: 1 lb fresh or dry lasagna noodles\"}, {\"qty\": \"2 cups\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"kosher salt and pepper\"}]", "instructions": "1. Make bolognese: cook vegetables until browned add beef brown well add tomato paste wine and milk then simmer 3 to 4 hours adding water as needed. 2. Make bechamel: melt butter whisk in flour cook 1 minute then gradually whisk in milk and simmer until thick about 10 minutes. 3. Cook lasagna noodles or soak dry noodles in hot water 10 minutes. 4. Preheat oven to 400°F. 5. Spread a thin layer of bechamel in a 9x13 pan then layer noodles bolognese bechamel and Parmesan repeating 4 to 5 times. 6. Finish top layer with remaining bechamel and Parmesan. 7. Bake covered 30 minutes then uncover and bake 15 more minutes until golden and bubbling. 8. Rest at least 15 minutes before slicing.", "tags": "weekend-project, make-ahead, indulgent", "source": "https://smittenkitchen.com/2012/02/lasagna-bolognese/", "nutritionData": "{\"calories\": 587, \"protein\": 36.0, \"carbs\": 54.0, \"fat\": 25.0}"},
  {"name": "Perfect Vegetable Lasagna", "category": "Pasta", "description": "Sky-high five-layer vegetable lasagna with fennel mushrooms spinach and creamy ricotta.", "servings": 8, "prepTime": 40, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"lasagna noodles\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"fennel bulb sliced\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"3 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 cups\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"2 tbsp\", \"name\": \"heavy cream\"}, {\"qty\": \"2 cups\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 400°F. 2. Soak noodles in hot water 10 minutes then drain. 3. Cook onion and fennel in olive oil over medium-high heat 8 to 10 minutes until browned. 4. Add mushrooms and cook 5 minutes then stir in spinach until wilted. 5. Make sauce: sauté garlic add tomato paste then crushed tomatoes and simmer 5 minutes. 6. Mix ricotta with heavy cream and season with salt and pepper. 7. Layer sauce noodles ricotta vegetables and cheese repeating 4 times ending with sauce and cheese. 8. Cover with foil and bake 30 minutes then uncover and bake 20 more minutes until golden.", "tags": "vegetarian, baked, make-ahead", "source": "https://smittenkitchen.com/2020/02/perfect-vegetable-lasagna/", "nutritionData": "{\"calories\": 446, \"protein\": 24.0, \"carbs\": 38.0, \"fat\": 21.0}"},
  {"name": "Skillet-Baked Macaroni and Cheese", "category": "Pasta", "description": "No-boil one-skillet mac and cheese with cheddar Gruyere and a golden panko crust.", "servings": 6, "prepTime": 15, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"elbow macaroni\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter plus 2 tbsp for breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 cups\", \"name\": \"whole milk\"}, {\"qty\": \"6 oz\", \"name\": \"sharp white cheddar coarsely grated\"}, {\"qty\": \"4 oz\", \"name\": \"Gruyere coarsely grated\"}, {\"qty\": \"2 oz\", \"name\": \"Pecorino Romano finely grated\"}, {\"qty\": \"1/2 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"\", \"name\": \"pinch freshly grated nutmeg\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 375°F. 2. Melt 2 tbsp butter in a 10-inch ovenproof skillet and toast breadcrumbs until golden then set aside. 3. Soak dry macaroni in hot tap water 10 minutes then drain. 4. Melt remaining 3 tbsp butter in the skillet over medium-high heat whisk in flour then gradually whisk in milk. 5. Cook stirring until thickened 3 to 4 minutes then season with salt pepper cayenne and nutmeg. 6. Add cheeses reserving 2/3 cup and stir until melted. 7. Stir in drained macaroni then top with reserved cheese and toasted breadcrumbs. 8. Bake 30 to 35 minutes until golden and pasta is cooked through.", "tags": "comfort-food, baked, vegetarian", "source": "https://smittenkitchen.com/2024/11/skillet-baked-macaroni-and-cheese/", "nutritionData": "{\"calories\": 555, \"protein\": 27.0, \"carbs\": 46.0, \"fat\": 29.0}"},
  {"name": "Pasta Salad With Roasted Tomatoes", "category": "Pasta", "description": "A vibrant make-ahead pasta salad with slow-roasted tomatoes olives pine nuts and fresh basil.", "servings": 8, "prepTime": 15, "cookTime": 95, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"bite-sized dried pasta\"}, {\"qty\": \"4 cups\", \"name\": \"grape tomatoes halved\"}, {\"qty\": \"\", \"name\": \"olive oil and salt for roasting\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted pine nuts\"}, {\"qty\": \"1/2 cup\", \"name\": \"Kalamata olives halved\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"1\", \"name\": \"garlic clove\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/3 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}]", "instructions": "1. Preheat oven to 300°F and roast tomatoes halved and cut-side-up with oil and salt for 90 minutes until shriveled. 2. Cook pasta until 1 to 2 minutes shy of done then drain and cool in a large bowl. 3. Make dressing: mince garlic with oregano salt and pepper into a paste then whisk with lemon juice vinegar and olive oil. 4. Toss pasta with roasted tomatoes Pecorino pine nuts and olives. 5. Add dressing to taste and adjust seasoning. 6. Finish with torn basil. 7. Serve immediately or refrigerate up to 3 days.", "tags": "make-ahead, vegetarian, picnic", "source": "https://smittenkitchen.com/2015/05/pasta-salad-with-roasted-tomatoes/", "nutritionData": "{\"calories\": 407, \"protein\": 11.0, \"carbs\": 48.0, \"fat\": 19.0}"},
  {"name": "Lemon Butter Cheese Ravioli", "category": "Pasta", "description": "Store-bought cheese ravioli in a browned butter thyme sauce with garlic Parmesan breadcrumbs.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"store-bought cheese ravioli\"}, {\"qty\": \"4 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"1/2 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Toast panko with olive oil garlic and Parmesan in a skillet over medium heat until golden then set aside. 2. Cook ravioli in salted water until al dente according to package directions. 3. Melt butter in a large skillet over medium heat until golden brown about 3 to 4 minutes. 4. Add thyme and stir then pour in wine and lemon juice and simmer 2 minutes. 5. Drain ravioli and add to sauce tossing gently to coat. 6. Plate and top generously with garlic Parmesan breadcrumbs and fresh basil. 7. Finish with a grind of black pepper.", "tags": "quick, weeknight, comfort-food", "source": "https://www.halfbakedharvest.com/lemon-butter-cheese-ravioli/", "nutritionData": "{\"calories\": 500, \"protein\": 16.0, \"carbs\": 45.0, \"fat\": 27.0}"},
  {"name": "One Pot Burrata Lemon Pesto Pasta", "category": "Pasta", "description": "One-pot pasta with basil pesto ricotta and melty burrata for a summery weeknight dinner.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"short pasta\"}, {\"qty\": \"1 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"small shallot chopped\"}, {\"qty\": \"2\", \"name\": \"garlic cloves chopped\"}, {\"qty\": \"\", \"name\": \"pinch red pepper flakes\"}, {\"qty\": \"3/4 cup\", \"name\": \"basil pesto\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"8 oz\", \"name\": \"burrata at room temperature\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil torn\"}, {\"qty\": \"\", \"name\": \"zest and juice of 1 lemon\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook pasta in salted water until al dente reserving 1/2 cup pasta water then drain. 2. In the same pot over medium-high heat cook olive oil shallot garlic thyme and red pepper flakes 1 minute. 3. Add reserved pasta water pasta pesto balsamic and ricotta and stir to combine. 4. Break burrata over pasta and remove from heat stirring gently until melty. 5. Add basil lemon zest and lemon juice then season with salt and pepper. 6. Serve immediately topped with extra basil.", "tags": "vegetarian, one-pot, summer", "source": "https://www.halfbakedharvest.com/burrata-lemon-pesto-pasta/", "nutritionData": "{\"calories\": 798, \"protein\": 31.0, \"carbs\": 91.0, \"fat\": 34.0}"},
  {"name": "Ricotta Gnocchi With Tomato Sauce", "category": "Pasta", "description": "Quick light homemade ricotta gnocchi cooked until pillowy and tossed in simple tomato sauce.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"whole-milk ricotta well-drained\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1\", \"name\": \"egg yolk\"}, {\"qty\": \"1 oz\", \"name\": \"finely grated Pecorino Romano\"}, {\"qty\": \"3.5 oz\", \"name\": \"all-purpose flour plus more for dusting\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"For sauce: 2 tbsp olive oil\"}, {\"qty\": \"3\", \"name\": \"garlic cloves\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"\", \"name\": \"fresh basil\"}, {\"qty\": \"\", \"name\": \"salt\"}]", "instructions": "1. Press ricotta in paper towels to remove moisture until you have about 12 oz. 2. Combine ricotta eggs egg yolk cheese and a pinch of salt then stir in flour until a soft dough forms. 3. On a floured surface divide dough into 4 pieces and roll into 1-inch-thick logs then cut into 1-inch pieces. 4. Boil gnocchi in salted water until they float then cook 20 seconds more and remove with a slotted spoon. 5. Make sauce: sauté garlic in olive oil add tomatoes and simmer 10 minutes. 6. Toss gnocchi in sauce and finish with torn basil and Parmesan.", "tags": "vegetarian, homemade-pasta, comfort-food", "source": "https://www.seriouseats.com/ricotta-gnocchi-homemade-food-lab-recipe", "nutritionData": "{\"calories\": 476, \"protein\": 24.0, \"carbs\": 33.0, \"fat\": 28.0}"},
  {"name": "Orecchiette With Sausage and Broccoli", "category": "Pasta", "description": "Rustic orecchiette with crumbled Italian sausage broccoli garlic and Pecorino Romano.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"orecchiette\"}, {\"qty\": \"5 tbsp\", \"name\": \"extra-virgin olive oil divided\"}, {\"qty\": \"1 lb\", \"name\": \"Italian sausage casings removed\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 lb\", \"name\": \"broccoli florets\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}]", "instructions": "1. Cook orecchiette in salted water until al dente reserving 1/2 cup pasta water then drain. 2. Brown sausage in 1 tbsp olive oil breaking it into pieces 5 to 6 minutes then add garlic and cook 1 minute. 3. Add remaining olive oil broth broccoli and red pepper flakes and cook 3 to 4 minutes until broccoli is tender-crisp. 4. Stir in butter until melted then simmer 2 minutes. 5. Add drained pasta and half the cheese to the pan and toss well. 6. Adjust consistency with pasta water as needed. 7. Serve topped with remaining cheese.", "tags": "weeknight, hearty, Italian", "source": "Classic", "nutritionData": "{\"calories\": 1094, \"protein\": 39.0, \"carbs\": 98.0, \"fat\": 61.0}"},
  {"name": "Pasta Primavera", "category": "Pasta", "description": "Spring-inspired pasta tossed with sautéed seasonal vegetables in a lemony olive oil sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"penne pasta\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1\", \"name\": \"zucchini sliced\"}, {\"qty\": \"1\", \"name\": \"yellow squash sliced\"}, {\"qty\": \"1\", \"name\": \"bunch asparagus cut into 1-inch pieces\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1\", \"name\": \"red onion sliced\"}, {\"qty\": \"4\", \"name\": \"garlic cloves sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas thawed\"}, {\"qty\": \"3/4 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil\"}, {\"qty\": \"\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook penne in a large pot of salted water until al dente then drain reserving 1/2 cup pasta water and toss with a drizzle of oil. 2. Heat olive oil in a large skillet and sauté garlic onion zucchini squash asparagus and tomatoes 3 to 4 minutes until just tender. 3. Add drained pasta peas Pecorino and lemon juice to skillet and toss. 4. Splash in pasta water as needed to loosen sauce. 5. Stir in basil and season with red pepper flakes salt and pepper. 6. Serve garnished with extra cheese and basil.", "tags": "vegetarian, spring, colorful", "source": "Classic", "nutritionData": "{\"calories\": 611, \"protein\": 23.0, \"carbs\": 89.0, \"fat\": 18.0}"},
  {"name": "Aglio e Olio", "category": "Pasta", "description": "Classic Roman pasta of spaghetti with garlic slowly toasted in olive oil and red pepper flakes.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"spaghetti\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"6\", \"name\": \"garlic cloves thinly sliced\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh Italian parsley chopped\"}, {\"qty\": \"1 cup\", \"name\": \"finely grated Parmigiano-Reggiano\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook spaghetti in a large pot of salted boiling water until al dente reserving 1 cup pasta water then drain. 2. Combine olive oil and garlic in a cold skillet then cook over medium heat until garlic turns golden and fragrant about 8 to 10 minutes. 3. Add red pepper flakes and cook 30 seconds. 4. Add drained pasta to skillet along with 1/2 cup pasta water and toss vigorously. 5. Remove from heat stir in parsley and half the Parmesan. 6. Add more pasta water if needed to keep it silky. 7. Plate and top with remaining cheese and black pepper.", "tags": "vegetarian, pantry-staple, quick", "source": "Classic", "nutritionData": "{\"calories\": 778, \"protein\": 25.0, \"carbs\": 88.0, \"fat\": 36.0}"},
  {"name": "Gnocchi alla Sorrentina", "category": "Pasta", "description": "Tender potato gnocchi baked in tomato sauce with fresh mozzarella and basil.", "servings": 4, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"russet potatoes\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour plus more for dusting\"}, {\"qty\": \"1\", \"name\": \"egg lightly beaten\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"homemade or store-bought marinara sauce\"}, {\"qty\": \"8 oz\", \"name\": \"fresh mozzarella torn\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmigiano-Reggiano\"}, {\"qty\": \"\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"\", \"name\": \"extra-virgin olive oil\"}]", "instructions": "1. Bake potatoes at 400°F until tender then halve and scoop flesh through a ricer onto a floured surface. 2. Spread riced potato and let steam escape then make a well add egg salt and 3/4 of flour. 3. Mix gently adding remaining flour as needed until a soft non-sticky dough forms. 4. Roll into ropes and cut into 1-inch pieces then press with a fork to shape. 5. Boil gnocchi in salted water until they float then drain. 6. Preheat oven to 400°F. 7. Toss gnocchi with marinara in a baking dish scatter mozzarella and Parmesan on top and bake 15 to 20 minutes until cheese is bubbly.", "tags": "baked, comfort-food, Italian", "source": "Classic", "nutritionData": "{\"calories\": 605, \"protein\": 27.0, \"carbs\": 78.0, \"fat\": 19.0}"},
  {"name": "Cheese Ravioli With Brown Butter and Sage", "category": "Pasta", "description": "Pillowy cheese ravioli tossed in a nutty brown butter sauce with crispy sage leaves.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"store-bought or fresh cheese ravioli\"}, {\"qty\": \"1 stick\", \"name\": \"8 tbsp unsalted butter\"}, {\"qty\": \"15\", \"name\": \"fresh sage leaves\"}, {\"qty\": \"2\", \"name\": \"garlic cloves smashed\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted walnuts\"}, {\"qty\": \"1/2 cup\", \"name\": \"apple cider or dry white wine\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"\", \"name\": \"pinch freshly grated nutmeg\"}, {\"qty\": \"1/3 cup\", \"name\": \"shaved Parmesan or Manchego\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Cook ravioli in salted water 3 to 4 minutes until al dente then drain. 2. Melt butter with garlic walnuts and sage in a large skillet over medium heat. 3. Cook stirring occasionally until butter is golden-brown and sage is crisp 4 to 5 minutes. 4. Remove sage leaves and set aside. 5. Reduce heat add apple cider vinegar and wine and simmer 1 minute. 6. Season with nutmeg salt and pepper. 7. Add drained ravioli to sauce and toss gently. 8. Plate and top with crispy sage and shaved cheese.", "tags": "vegetarian, quick, elegant", "source": "Classic", "nutritionData": "{\"calories\": 581, \"protein\": 16.0, \"carbs\": 37.0, \"fat\": 40.0}"},
  {"name": "Stovetop Mac and Cheese", "category": "Pasta", "description": "Quick creamy stovetop macaroni and cheese with cheddar Gruyere and a touch of cayenne.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"elbow macaroni\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 cups\", \"name\": \"sharp cheddar coarsely grated\"}, {\"qty\": \"1 cup\", \"name\": \"Gruyere coarsely grated\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dry mustard\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"\", \"name\": \"pinch freshly grated nutmeg\"}, {\"qty\": \"\", \"name\": \"kosher salt and white pepper\"}]", "instructions": "1. Cook macaroni in salted water until barely al dente then drain. 2. Melt butter in a large saucepan over medium heat whisk in flour and cook 1 minute. 3. Gradually whisk in milk and cream and cook until sauce thickens 5 to 6 minutes. 4. Remove from heat and stir in both cheeses mustard cayenne and nutmeg until smooth. 5. Season generously with salt and white pepper. 6. Fold in drained macaroni and stir over medium-low heat 1 to 2 minutes until hot and creamy. 7. Serve immediately.", "tags": "comfort-food, quick, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 1143, \"protein\": 42.0, \"carbs\": 101.0, \"fat\": 63.0}"},
  {"name": "Cold Italian Pasta Salad", "category": "Pasta", "description": "A classic deli-style pasta salad with salami olives roasted peppers and zesty Italian dressing.", "servings": 8, "prepTime": 15, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"rotini or fusilli pasta\"}, {\"qty\": \"4 oz\", \"name\": \"salami sliced and quartered\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/2 cup\", \"name\": \"Kalamata olives\"}, {\"qty\": \"1/2 cup\", \"name\": \"jarred roasted red peppers chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"banana pepperoncini sliced\"}, {\"qty\": \"4 oz\", \"name\": \"fresh mozzarella cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1/3 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1\", \"name\": \"garlic clove minced\"}, {\"qty\": \"\", \"name\": \"salt and black pepper\"}]", "instructions": "1. Cook pasta in salted water until al dente then drain and rinse under cold water. 2. Whisk together olive oil red wine vinegar oregano garlic salt and pepper for dressing. 3. Combine cooled pasta with salami tomatoes olives roasted peppers pepperoncini and mozzarella in a large bowl. 4. Pour dressing over and toss well to coat. 5. Add Parmesan and toss again. 6. Taste and adjust seasoning adding more vinegar or salt as needed. 7. Refrigerate at least 30 minutes before serving.", "tags": "make-ahead, crowd-pleasing, picnic", "source": "Classic", "nutritionData": "{\"calories\": 432, \"protein\": 16.0, \"carbs\": 46.0, \"fat\": 20.0}"},
  {"name": "Pasta alla Gricia", "category": "Pasta", "description": "The ancestor of carbonara featuring guanciale toasted pepper and Pecorino without eggs or tomato.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"rigatoni or mezzi rigatoni\"}, {\"qty\": \"8 oz\", \"name\": \"guanciale cut into 1/2-inch batons\"}, {\"qty\": \"1 tsp\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"2 oz\", \"name\": \"Pecorino Romano finely grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt for pasta water\"}]", "instructions": "1. Cook pasta in a medium pot of salted water using less water than usual to concentrate starch. 2. Cook guanciale in a large skillet over medium-low heat until golden and fat renders about 10 minutes. 3. Transfer guanciale to a plate and pour all but 1/4 cup fat into a heatproof cup. 4. Add pepper to hot fat and toast 30 seconds off heat. 5. With 2 minutes left on pasta add 1 1/2 cups pasta water to skillet and bring to a boil to reduce. 6. Transfer pasta with tongs to skillet and toss vigorously over medium heat 3 to 5 minutes until sauce emulsifies. 7. Off heat stir in guanciale and cheese adding pasta water as needed until glossy.", "tags": "roman-style, pork, minimalist", "source": "Classic", "nutritionData": "{\"calories\": 832, \"protein\": 26.0, \"carbs\": 88.0, \"fat\": 40.0}"},
  {"name": "Creamy Mushroom Tagliatelle", "category": "Pasta", "description": "Tagliatelle tossed with caramelized wild mushrooms butter white wine and fresh herbs.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"tagliatelle or fettuccine\"}, {\"qty\": \"1 lb\", \"name\": \"mixed wild mushrooms shiitake cremini oyster\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh sage\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"pasta water\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lemon\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"fresh parsley for serving\"}]", "instructions": "1. Cook tagliatelle in salted water until al dente reserving 1/2 cup pasta water then drain. 2. Melt butter in a large skillet over medium-high heat and add mushrooms in a single layer. 3. Cook undisturbed until golden 4 to 5 minutes then toss and cook 3 more minutes. 4. Add garlic thyme and sage and cook 1 minute. 5. Pour in white wine and simmer until reduced by half. 6. Add cream and pasta water and stir then season with salt and pepper. 7. Add pasta and toss to coat finishing with Parmesan lemon juice and parsley.", "tags": "vegetarian, umami, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 712, \"protein\": 25.0, \"carbs\": 92.0, \"fat\": 28.0}"},
  {"name": "Classic Pesto Genovese With Linguine", "category": "Pasta", "description": "Traditional basil pesto with pine nuts Parmesan and garlic tossed with al dente linguine.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"linguine\"}, {\"qty\": \"2 cups\", \"name\": \"fresh basil leaves packed\"}, {\"qty\": \"1/3 cup\", \"name\": \"toasted pine nuts\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano-Reggiano\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Pecorino Romano\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lemon\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Bring a large pot of salted water to a boil and cook linguine until al dente reserving 1 cup pasta water. 2. In a food processor pulse basil pine nuts and garlic until coarsely chopped. 3. With motor running stream in olive oil until smooth. 4. Transfer to a bowl and stir in both cheeses and lemon juice then season with salt and pepper. 5. Drain pasta and immediately toss with pesto loosening with reserved pasta water until silky. 6. Serve at once with extra Parmesan and a drizzle of oil.", "tags": "vegetarian, quick, summer", "source": "Classic", "nutritionData": "{\"calories\": 826, \"protein\": 24.0, \"carbs\": 89.0, \"fat\": 42.0}"},
  {"name": "Pasta E Fagioli", "category": "Pasta", "description": "Hearty Italian pasta and bean soup with rosemary garlic cannellini beans and ditalini.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"ditalini or small pasta\"}, {\"qty\": \"2 cans\", \"name\": \"15 oz each cannellini beans drained\"}, {\"qty\": \"4 oz\", \"name\": \"pancetta diced\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"1 can\", \"name\": \"14 oz crushed tomatoes\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1\", \"name\": \"Parmesan rind optional\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"Parmesan for serving\"}]", "instructions": "1. Cook pancetta in olive oil in a large pot over medium heat until crisp 5 minutes. 2. Add onion and cook until softened 5 minutes then add garlic rosemary and red pepper flakes and cook 1 minute. 3. Add tomatoes broth Parmesan rind and one can of beans. 4. Mash remaining beans and stir into pot for a thick creamy texture. 5. Simmer 15 minutes then add pasta and cook until just al dente. 6. Remove rosemary and Parmesan rind season with salt and pepper. 7. Ladle into bowls and top with Parmesan and a drizzle of olive oil.", "tags": "soup, hearty, Italian", "source": "Classic", "nutritionData": "{\"calories\": 349, \"protein\": 16.0, \"carbs\": 36.0, \"fat\": 16.0}"},
  {"name": "Spinach Ricotta Stuffed Shells", "category": "Pasta", "description": "Jumbo pasta shells stuffed with herbed spinach ricotta and baked in marinara with mozzarella.", "servings": 6, "prepTime": 25, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"20\", \"name\": \"jumbo pasta shells\"}, {\"qty\": \"2 cups\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach wilted and chopped\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella divided\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Italian seasoning\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 375°F. 2. Cook shells in salted water until al dente then drain and cool. 3. Mix ricotta spinach 1/2 cup mozzarella Parmesan egg garlic Italian seasoning salt and pepper until combined. 4. Spread 1 cup marinara in the bottom of a 9x13 baking dish. 5. Fill each shell with ricotta mixture and arrange snugly in pan. 6. Spoon remaining marinara over shells and top with remaining mozzarella. 7. Cover with foil and bake 25 minutes then uncover and bake 15 more minutes until bubbling. 8. Serve with extra Parmesan.", "tags": "vegetarian, baked, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 415, \"protein\": 23.0, \"carbs\": 38.0, \"fat\": 18.0}"},
  {"name": "Crispy Pan-Seared Salmon", "category": "Seafood", "description": "Golden-skinned salmon fillets seared to perfection with a translucent medium-rare center.", "servings": 2, "prepTime": 5, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"skin-on salmon fillets (6 oz each)\"}, {\"qty\": \"2 tbsp\", \"name\": \"canola oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"lemon cut into wedges\"}]", "instructions": "1. Pat salmon fillets completely dry with paper towels on both sides. 2. Season generously with salt and pepper on both sides. 3. Heat oil in a cast iron skillet over medium-high heat until shimmering. 4. Place fillets skin-side down; press gently with a flexible spatula for 15 seconds to prevent buckling. 5. Reduce heat to medium-low and cook 90% through on skin side about 6 minutes until skin is crisp. 6. Flip fillets and cook flesh side for 15 seconds until center reaches 120°F. 7. Transfer to a paper-towel-lined plate; serve immediately with lemon wedges.", "tags": "crispy-skin, quick, weeknight", "source": "https://www.seriouseats.com/crispy-pan-seared-salmon-fillets-recipe", "nutritionData": "{\"calories\": 460, \"protein\": 35.0, \"carbs\": 0.0, \"fat\": 34.0}"},
  {"name": "Shrimp Scampi", "category": "Seafood", "description": "Classic garlicky shrimp in white wine butter sauce served over linguine or crusty bread.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 lb\", \"name\": \"linguine cooked\"}]", "instructions": "1. Cook linguine in salted boiling water until al dente; drain and reserve 1/2 cup pasta water. 2. Melt butter with olive oil in a large skillet over medium heat. 3. Add garlic and red pepper flakes; sauté 1 minute until fragrant. 4. Add white wine, salt, and pepper; let reduce by half about 2 minutes. 5. Add shrimp and cook 2 to 4 minutes until pink and opaque, flipping once. 6. Stir in lemon juice and parsley. 7. Toss with linguine adding pasta water as needed for a silky sauce. 8. Serve immediately.", "tags": "quick, garlicky, Italian-American", "source": "https://cooking.nytimes.com/recipes/1015178-shrimp-scampi", "nutritionData": "{\"calories\": 670, \"protein\": 48.0, \"carbs\": 74.0, \"fat\": 18.0}"},
  {"name": "Miso-Glazed Black Cod", "category": "Seafood", "description": "Silky black cod marinated in a sweet miso glaze and broiled until caramelized and flaky.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"black cod fillets (6 oz each)\"}, {\"qty\": \"1 cup\", \"name\": \"white miso\"}, {\"qty\": \"2/3 cup\", \"name\": \"sugar\"}, {\"qty\": \"1/3 cup\", \"name\": \"mirin\"}, {\"qty\": \"1/4 cup\", \"name\": \"sake\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}]", "instructions": "1. Whisk miso, sugar, mirin, sake, soy sauce, and sesame oil until sugar dissolves. 2. Pat cod fillets dry and place in a zip-lock bag with the marinade. 3. Marinate in refrigerator at least 8 hours and up to 24 hours. 4. Preheat broiler with rack 6 inches from element. 5. Remove fillets from marinade and wipe off excess; place on an oiled foil-lined baking sheet. 6. Broil 8 to 12 minutes until surface is deeply caramelized and fish flakes easily. 7. Serve immediately with steamed rice.", "tags": "umami, Japanese-inspired, restaurant-style", "source": "https://www.allrecipes.com/recipe/237637/miso-glazed-black-cod/", "nutritionData": "{\"calories\": 420, \"protein\": 34.0, \"carbs\": 38.0, \"fat\": 10.0}"},
  {"name": "Maryland Crab Cakes", "category": "Seafood", "description": "Classic jumbo lump crab cakes with minimal filler and Old Bay seasoning.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"jumbo lump crab meat\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain panko breadcrumbs\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"1.5 tsp\", \"name\": \"fresh parsley minced\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Whisk together egg, mayonnaise, mustard, lemon juice, Old Bay, parsley, salt, and pepper in a large bowl. 2. Add crab meat and panko; gently fold with a spatula being careful not to break up the crab lumps. 3. Portion into 4 to 6 mounds on a buttered baking sheet; do not flatten. 4. Refrigerate uncovered at least 30 minutes to firm up. 5. Preheat oven to 450°F and place a small pat of butter on each cake. 6. Bake 12 to 14 minutes until edges are lightly browned; broil last 2 minutes for color. 7. Serve warm with lemon wedges and tartar sauce.", "tags": "Maryland-style, old-bay, minimal-filler", "source": "https://sallysbakingaddiction.com/maryland-crab-cakes/", "nutritionData": "{\"calories\": 300, \"protein\": 26.0, \"carbs\": 10.0, \"fat\": 15.0}"},
  {"name": "Classic Cioppino", "category": "Seafood", "description": "San Francisco-style tomato and wine seafood stew loaded with clams, mussels, shrimp, and fish.", "servings": 6, "prepTime": 20, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"1 cup\", \"name\": \"fennel thinly sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"\", \"name\": \"pinch red pepper flakes\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"3/4 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1 cup\", \"name\": \"bottled clam juice\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) whole peeled tomatoes\"}, {\"qty\": \"1 lb\", \"name\": \"littleneck clams\"}, {\"qty\": \"1/2 lb\", \"name\": \"mussels cleaned\"}, {\"qty\": \"1/2 lb\", \"name\": \"large shrimp peeled\"}, {\"qty\": \"1/2 lb\", \"name\": \"firm white fish cut into pieces\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley minced\"}]", "instructions": "1. Heat olive oil in a large Dutch oven over medium heat; sauté onion and fennel until soft about 8 minutes. 2. Add garlic, red pepper flakes, and bay leaf; cook 2 to 3 minutes. 3. Stir in tomato paste; season lightly with salt and pepper. 4. Add white wine and clam juice; bring to a simmer and cook 5 minutes. 5. Add canned tomatoes breaking them up; cover and simmer 20 minutes. 6. Add clams and mussels; cover and cook until they just begin to open about 5 minutes. 7. Add shrimp and fish; cover and cook 3 to 5 minutes until opaque. 8. Stir in butter; garnish with parsley; serve with crusty bread.", "tags": "San Francisco, stew, shellfish", "source": "https://coleycooks.com/cioppino/", "nutritionData": "{\"calories\": 330, \"protein\": 32.0, \"carbs\": 10.0, \"fat\": 13.0}"},
  {"name": "Connecticut-Style Lobster Roll", "category": "Seafood", "description": "Buttery warm lobster rolls on toasted split-top brioche buns with lemon and fresh herbs.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"cooked lobster meat\"}, {\"qty\": \"8 tbsp\", \"name\": \"unsalted butter divided\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"lemon zested and juiced\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh dill chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt and pepper to taste\"}, {\"qty\": \"4\", \"name\": \"split-top brioche hot dog buns\"}]", "instructions": "1. Chop lobster meat into large bite-sized pieces. 2. Melt 6 tbsp butter in a skillet over medium-low heat; add garlic, lemon zest, and half the lemon juice. 3. Add lobster meat and gently warm tossing to coat about 2 to 3 minutes; season with salt and pepper. 4. Remove lobster from pan; wipe skillet clean and melt remaining 2 tbsp butter over medium-high heat. 5. Toast brioche buns on cut sides until golden about 2 minutes per side. 6. Fill each bun generously with warm buttery lobster. 7. Drizzle any remaining butter over top; garnish with chives and dill. Serve immediately.", "tags": "New England, summer, indulgent", "source": "https://www.howsweeteats.com/2021/06/buttery-lobster-rolls/", "nutritionData": "{\"calories\": 515, \"protein\": 26.0, \"carbs\": 32.0, \"fat\": 30.0}"},
  {"name": "Baja Fish Tacos", "category": "Seafood", "description": "Crispy beer-battered cod in warm corn tortillas with crunchy slaw and chipotle crema.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"cod fillets cut into strips\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"light beer\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"2 cups\", \"name\": \"green cabbage shredded\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tsp\", \"name\": \"chipotle in adobo minced\"}, {\"qty\": \"12\", \"name\": \"small corn tortillas\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1\", \"name\": \"lime cut into wedges\"}]", "instructions": "1. Whisk flour, beer, baking powder, cumin, paprika, and garlic powder into a smooth batter; season with salt and pepper. 2. Toss shredded cabbage with lime juice and a pinch of salt; set aside 10 minutes. 3. Mix sour cream with minced chipotle; refrigerate until needed. 4. Heat 2 inches of oil in a heavy pot to 375°F. 5. Pat cod strips dry; dip in batter letting excess drip off. 6. Fry in batches until golden and crispy about 3 to 4 minutes; drain on paper towels. 7. Warm tortillas on a hot griddle. 8. Assemble tacos with slaw, fried fish, avocado, and chipotle crema. Serve with lime wedges.", "tags": "Mexican-inspired, crispy, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 550, \"protein\": 40.0, \"carbs\": 55.0, \"fat\": 16.0}"},
  {"name": "Peruvian Ceviche", "category": "Seafood", "description": "Fresh white fish cured in citrus juice with red onion, aji amarillo, and cilantro.", "servings": 4, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"fresh sea bass or flounder cut into 1/2-inch cubes\"}, {\"qty\": \"1 cup\", \"name\": \"fresh lime juice about 10 limes\"}, {\"qty\": \"1/2\", \"name\": \"red onion thinly sliced\"}, {\"qty\": \"2\", \"name\": \"aji amarillo peppers seeded and minced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"avocado diced\"}, {\"qty\": \"1 cup\", \"name\": \"cooked corn kernels\"}, {\"qty\": \"\", \"name\": \"tortilla chips for serving\"}]", "instructions": "1. Combine fish cubes with lime juice and 1 tsp salt in a non-reactive bowl; toss to coat. 2. Cover and refrigerate 15 to 20 minutes until fish is opaque and partially cured. 3. Soak sliced red onion in cold salted water 10 minutes; drain well. 4. Drain most of the lime juice from the fish reserving a few tablespoons. 5. Add onion, aji amarillo, garlic, and cilantro; toss gently. 6. Season with salt and pepper; fold in avocado and corn. 7. Serve immediately with tortilla chips.", "tags": "no-cook, fresh, Peruvian", "source": "Classic", "nutritionData": "{\"calories\": 370, \"protein\": 36.0, \"carbs\": 21.0, \"fat\": 14.0}"},
  {"name": "Seafood Paella", "category": "Seafood", "description": "Saffron-scented bomba rice cooked with shrimp, mussels, and calamari in a wide paella pan.", "servings": 6, "prepTime": 20, "cookTime": 40, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3\", \"name\": \"roma tomatoes finely diced\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron threads\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1/4 cup\", \"name\": \"white wine\"}, {\"qty\": \"2 cups\", \"name\": \"bomba or Arborio rice\"}, {\"qty\": \"5 cups\", \"name\": \"fish stock\"}, {\"qty\": \"1/2 lb\", \"name\": \"large shrimp shell-on\"}, {\"qty\": \"1/2 lb\", \"name\": \"mussels cleaned\"}, {\"qty\": \"8 oz\", \"name\": \"calamari rings\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Heat olive oil in a large paella pan over medium heat. 2. Sauté onion, bell pepper, and garlic until onion is translucent about 5 minutes. 3. Add tomatoes, paprika, saffron, salt, and pepper; cook stirring 5 minutes. 4. Pour in white wine and cook 10 minutes. 5. Add rice; stir 1 minute to coat. 6. Pour stock evenly around the pan; bring to a boil then reduce to medium-low. Do not stir. 7. Cook uncovered 15 to 18 minutes. 8. Nestle shrimp, mussels, and calamari into the rice; scatter peas on top; cook 5 minutes until shellfish open. 9. Remove from heat; cover with foil and rest 10 minutes. 10. Garnish with parsley and lemon wedges; serve from the pan.", "tags": "Spanish, saffron, entertaining", "source": "https://tastesbetterfromscratch.com/paella/", "nutritionData": "{\"calories\": 500, \"protein\": 28.0, \"carbs\": 58.0, \"fat\": 10.0}"},
  {"name": "Pan-Seared Scallops", "category": "Seafood", "description": "Perfectly seared sea scallops with a caramelized golden crust and nutty browned butter sauce.", "servings": 2, "prepTime": 35, "cookTime": 5, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dry sea scallops (10 to 13 scallops)\"}, {\"qty\": \"1 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"flaky sea salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley finely chopped\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Remove abductor muscle from side of each scallop; place on a paper-towel-lined plate and refrigerate 30 minutes to dry thoroughly. 2. Season scallops generously on both sides with kosher salt. 3. Heat a large stainless steel skillet over high heat 3 to 5 minutes until very hot. 4. Add enough neutral oil to coat the bottom; place scallops in single layer with at least 1 inch between each. 5. Cook undisturbed 2 to 3 minutes until a deep golden crust forms and they release easily. 6. Flip scallops; add butter and garlic; cook 1 to 2 minutes while basting with browned butter. 7. Transfer to plates; spoon pan butter over top; finish with flaky salt and parsley. Serve immediately with lemon.", "tags": "restaurant-quality, special-occasion, quick", "source": "https://www.wellseasonedstudio.com/pan-seared-scallops/", "nutritionData": "{\"calories\": 370, \"protein\": 39.0, \"carbs\": 5.0, \"fat\": 21.0}"},
  {"name": "Moules Marinières", "category": "Seafood", "description": "Classic French steamed mussels in a fragrant white wine and shallot broth with crusty bread.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"live mussels cleaned and debearded\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2\", \"name\": \"shallots finely chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh flat-leaf parsley chopped\"}, {\"qty\": \"1 sprig\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"crusty French bread for serving\"}]", "instructions": "1. Scrub mussels under cold running water; remove beards. Discard any open mussels that don't close when tapped. 2. Melt butter in a large pot over medium heat; sauté shallots and garlic until softened about 3 minutes. 3. Add white wine, thyme, and bay leaf; bring to a simmer and cook 2 minutes. 4. Add mussels; cover with a tight-fitting lid and cook over high heat 3 to 5 minutes until all shells open. Shake the pot occasionally. 5. Discard any mussels that remain closed. 6. Stir in heavy cream and parsley; season with salt and pepper. 7. Ladle into bowls with plenty of broth; serve with crusty bread.", "tags": "French-classic, shellfish, quick", "source": "Classic", "nutritionData": "{\"calories\": 350, \"protein\": 15.0, \"carbs\": 9.0, \"fat\": 24.0}"},
  {"name": "Blackened Catfish", "category": "Seafood", "description": "Cajun-spiced catfish fillets seared in a screaming-hot cast iron skillet until charred and aromatic.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"catfish fillets (6 oz each)\"}, {\"qty\": \"1 tbsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}, {\"qty\": \"2 tbsp\", \"name\": \"chopped parsley\"}]", "instructions": "1. Mix paprika, garlic powder, onion powder, thyme, cayenne, white pepper, black pepper, and salt in a small bowl. 2. Heat a heavy cast iron skillet over high heat 8 to 10 minutes until extremely hot and just beginning to smoke. 3. Dip each catfish fillet in melted butter; coat both sides with the spice mixture pressing gently. 4. Working in batches place fillets in the hot pan without crowding; drizzle 1 tsp melted butter over each. 5. Cook until bottom is deeply charred about 2 minutes; flip and add another tsp butter. 6. Cook 1 to 2 minutes more until fish is cooked through. 7. Serve immediately with lemon wedges and parsley.", "tags": "Cajun, Southern, spicy", "source": "Classic", "nutritionData": "{\"calories\": 310, \"protein\": 32.0, \"carbs\": 1.0, \"fat\": 19.0}"},
  {"name": "Low Country Shrimp Boil", "category": "Seafood", "description": "Classic Southern boil with shrimp, andouille sausage, corn, and potatoes in a seasoned broth.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"1 lb\", \"name\": \"andouille sausage cut into 1-inch pieces\"}, {\"qty\": \"4\", \"name\": \"ears corn each cut into 4 pieces\"}, {\"qty\": \"1 lb\", \"name\": \"small red potatoes halved\"}, {\"qty\": \"1\", \"name\": \"medium onion quartered\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"2\", \"name\": \"lemons quartered\"}, {\"qty\": \"1/3 cup\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Fill a large stockpot with water; add lemon quarters, onion, garlic, Old Bay, salt, and pepper; bring to a boil. 2. Add potatoes and cook 10 to 12 minutes until just fork-tender. 3. Add corn and sausage; cook 5 to 6 minutes more. 4. Add shrimp; cook 2 to 3 minutes until pink and opaque. 5. Drain and spread everything onto a large baking sheet. 6. Toss with melted butter; sprinkle extra Old Bay and parsley over top. 7. Serve immediately with lemon wedges and extra melted butter.", "tags": "Southern, communal, Cajun", "source": "https://www.julieseatsandtreats.com/shrimp-boil/", "nutritionData": "{\"calories\": 600, \"protein\": 49.0, \"carbs\": 25.0, \"fat\": 37.0}"},
  {"name": "Linguine alle Vongole", "category": "Seafood", "description": "Traditional Italian pasta with fresh littleneck clams in a garlicky white wine broth.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"linguine\"}, {\"qty\": \"3 lbs\", \"name\": \"littleneck clams scrubbed and cleaned\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic thinly sliced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"3/4 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}]", "instructions": "1. Bring a large pot of lightly salted water to a boil; cook linguine to 1 minute shy of al dente; reserve 1 cup pasta water before draining. 2. Heat olive oil in a large deep skillet over medium-low; add garlic and red pepper flakes; cook until garlic is lightly golden 1 to 2 minutes. 3. Add white wine, lemon juice, and clams; cover and steam over medium-high heat until clams open 5 to 8 minutes. Transfer clams to a bowl as they open; discard any that don't open after 10 minutes. 4. Whisk butter into the simmering clam liquid. 5. Add drained linguine to the pan; toss and cook 2 minutes until al dente adding pasta water as needed. 6. Stir in half the parsley. 7. Return clams to pan; toss gently. Serve with remaining parsley and a drizzle of olive oil.", "tags": "Italian, clams, pasta", "source": "Classic", "nutritionData": "{\"calories\": 770, \"protein\": 26.0, \"carbs\": 90.0, \"fat\": 22.0}"},
  {"name": "Grilled Halibut with Lemon Herb Butter", "category": "Seafood", "description": "Thick halibut fillets grilled over medium heat and finished with a bright lemon herb compound butter.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"halibut fillets (6 to 8 oz each)\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley minced\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}]", "instructions": "1. Preheat grill or grill pan to medium-high and lightly oil the grates. 2. Make compound butter by mashing together butter, garlic, parsley, lemon zest, lemon juice, and thyme; set aside. 3. Brush halibut fillets with olive oil; season all over with salt, pepper, and smoked paprika. 4. Grill halibut 5 to 6 minutes per side until grill marks form and internal temperature reaches 145°F. 5. Transfer to plates; immediately top each fillet with a generous spoonful of compound butter. 6. Serve with grilled asparagus or a simple green salad.", "tags": "grilled, light, healthy", "source": "https://heygrillhey.com/grilled-halibut/", "nutritionData": "{\"calories\": 385, \"protein\": 46.0, \"carbs\": 1.0, \"fat\": 23.0}"},
  {"name": "Seared Ahi Tuna Steaks", "category": "Seafood", "description": "Sesame-crusted sushi-grade tuna seared rare with a soy ginger dipping sauce and sliced avocado.", "servings": 2, "prepTime": 20, "cookTime": 4, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"sushi-grade ahi tuna steaks (8 oz each)\"}, {\"qty\": \"3 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"coarsely ground black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"honey\"}, {\"qty\": \"2\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}]", "instructions": "1. Allow tuna steaks to come to room temperature for 20 minutes; pat dry. 2. Combine soy sauce, rice vinegar, ginger, sesame oil, and honey in a small bowl to make dipping sauce. 3. Mix sesame seeds, salt, and pepper on a plate; press tuna steaks into the mixture on all sides to coat. 4. Heat neutral oil in a cast iron skillet over medium-high heat until very hot. 5. Sear tuna 1 to 2 minutes per side until browned outside but rare in the center (130°F for medium-rare). 6. Rest 2 minutes then slice against the grain into 1/2-inch strips. 7. Serve over avocado with dipping sauce and scallions.", "tags": "Asian-inspired, sesame, sushi-grade", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 52.0, \"carbs\": 12.0, \"fat\": 22.0}"},
  {"name": "Honey Garlic Baked Salmon", "category": "Seafood", "description": "Oven-baked salmon glazed with a sweet and savory honey garlic sauce that caramelizes beautifully.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets (6 oz each)\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Preheat oven to 400°F; line a baking dish with foil and lightly grease. 2. Whisk honey, soy sauce, garlic, rice vinegar, and red pepper flakes together to make the glaze. 3. Place salmon skin-side down in the prepared baking dish; season with black pepper. 4. Spoon the honey garlic glaze over each fillet coating evenly. 5. Bake 12 minutes until salmon flakes easily and the glaze is caramelized. 6. Optionally broil last 2 minutes for extra caramelization. 7. Garnish with parsley; serve with lemon wedges and steamed rice.", "tags": "baked, weeknight, Asian-inspired", "source": "Classic", "nutritionData": "{\"calories\": 445, \"protein\": 34.0, \"carbs\": 17.0, \"fat\": 26.0}"},
  {"name": "New England Clam Chowder", "category": "Seafood", "description": "Creamy classic chowder with tender clams, potatoes, and smoky bacon in a rich cream base.", "servings": 6, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 slices\", \"name\": \"thick-cut bacon chopped\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion diced\"}, {\"qty\": \"3\", \"name\": \"stalks celery diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"clam juice\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1.5 lbs\", \"name\": \"Yukon Gold potatoes peeled and cubed\"}, {\"qty\": \"2 cans\", \"name\": \"(10 oz each) chopped clams\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"kosher salt and white pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"\", \"name\": \"oyster crackers for serving\"}]", "instructions": "1. Cook bacon in a large pot over medium heat until crispy; remove with a slotted spoon and set aside leaving fat in pot. 2. Sauté onion and celery in bacon fat until soft about 5 minutes; add garlic and cook 1 minute. 3. Sprinkle flour over vegetables; cook stirring 2 minutes to make a roux. 4. Gradually whisk in clam juice; bring to a simmer while stirring. 5. Add milk, cream, potatoes, thyme, and bay leaf; simmer over medium-low heat 15 to 20 minutes until potatoes are tender. 6. Drain canned clams; stir clams into chowder during last 3 minutes of cooking. 7. Remove bay leaf; season with salt and white pepper. 8. Serve garnished with bacon and chives with oyster crackers on the side.", "tags": "creamy, comfort-food, New England", "source": "Classic", "nutritionData": "{\"calories\": 395, \"protein\": 19.0, \"carbs\": 31.0, \"fat\": 19.0}"},
  {"name": "Salmon Teriyaki", "category": "Seafood", "description": "Glazed salmon with a classic Japanese teriyaki sauce served with steamed rice and broccoli.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets (6 oz each)\"}, {\"qty\": \"1/4 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"2 tbsp\", \"name\": \"sake\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"\", \"name\": \"steamed rice and broccoli for serving\"}]", "instructions": "1. Whisk soy sauce, mirin, sake, sugar, sesame oil, garlic, and ginger to make teriyaki sauce; reserve half for serving. 2. Pat salmon dry; heat vegetable oil in an oven-safe skillet over medium-high heat. 3. Place salmon skin-side up; sear 3 minutes until golden then flip. 4. Brush generously with teriyaki sauce; transfer pan to a 400°F oven. 5. Roast 6 to 8 minutes brushing once more with sauce until salmon is cooked through. 6. Drizzle with reserved sauce; garnish with scallions and sesame seeds. 7. Serve with steamed rice and broccoli.", "tags": "Japanese-inspired, weeknight, glazed", "source": "Classic", "nutritionData": "{\"calories\": 580, \"protein\": 39.0, \"carbs\": 34.0, \"fat\": 27.0}"},
  {"name": "Sheet Pan Shrimp Boil", "category": "Seafood", "description": "Easy oven version of a classic shrimp boil with parboiled potatoes, corn, and andouille sausage.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"medium shrimp peeled and deveined\"}, {\"qty\": \"1 lb\", \"name\": \"baby Yukon Gold potatoes\"}, {\"qty\": \"3\", \"name\": \"ears corn each cut into 6 pieces\"}, {\"qty\": \"1\", \"name\": \"package (12 oz) andouille sausage sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"1\", \"name\": \"lemon cut into wedges\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F; lightly oil a large rimmed baking sheet. 2. Boil potatoes in salted water 10 to 13 minutes until just tender; add corn during last 5 minutes. Drain well. 3. Whisk melted butter, garlic, and Old Bay together in a bowl. 4. Spread potatoes, corn, shrimp, and sausage in a single layer on the baking sheet; pour butter mixture over and toss to coat. 5. Bake 12 to 15 minutes until shrimp are opaque and corn is tender. 6. Serve immediately from the pan with lemon wedges and parsley.", "tags": "easy, sheet-pan, Southern", "source": "https://damndelicious.net/2017/02/13/sheet-pan-shrimp-boil/", "nutritionData": "{\"calories\": 590, \"protein\": 42.0, \"carbs\": 30.0, \"fat\": 36.0}"},
  {"name": "Garlic Butter Baked Cod", "category": "Seafood", "description": "Flaky cod fillets baked with herb butter and topped with a buttery Ritz cracker crumble.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"cod fillets (6 to 8 oz each)\"}, {\"qty\": \"4 oz\", \"name\": \"butter-flavored crackers crushed (about 1.5 cups)\"}, {\"qty\": \"5 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley minced\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"1\", \"name\": \"lemon juiced\"}, {\"qty\": \"\", \"name\": \"sweet paprika for serving\"}]", "instructions": "1. Preheat oven to 425°F. 2. Crush crackers and combine with 4 tbsp melted butter, chives, parsley, lemon zest, onion powder, and garlic powder; mix until all crumbs are moistened. 3. Place cod fillets in a large oven-safe skillet; drizzle remaining 1 tbsp butter over fish and turn to coat. 4. Season fish with salt and pepper. 5. Mound cracker mixture on top of each fillet pressing lightly to adhere. 6. Roast 10 to 16 minutes depending on thickness until fish flakes easily and juices bubble around edges. 7. Squeeze lemon juice over top; sprinkle with paprika; serve with lemon wedges.", "tags": "baked, quick, family-friendly", "source": "https://cooking.nytimes.com/recipes/1019748-baked-cod-with-buttery-cracker-topping", "nutritionData": "{\"calories\": 410, \"protein\": 38.0, \"carbs\": 15.0, \"fat\": 22.0}"},
  {"name": "Grilled Salmon with Avocado Salsa", "category": "Seafood", "description": "Smoky grilled salmon topped with a bright avocado and mango salsa for a vibrant summer dish.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets (6 oz each)\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"ripe avocados diced\"}, {\"qty\": \"1\", \"name\": \"mango diced\"}, {\"qty\": \"1/4\", \"name\": \"red onion finely diced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o seeded and minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}]", "instructions": "1. Preheat grill or grill pan to medium-high; oil grates well. 2. Brush salmon with olive oil; season all sides with cumin, paprika, garlic powder, salt, and pepper. 3. Grill salmon 4 to 5 minutes per side until grill marks form and fish is cooked through. 4. Gently combine avocado, mango, red onion, jalapeño, cilantro, and lime juice; season with salt. 5. Transfer salmon to plates; top generously with avocado-mango salsa. 6. Serve immediately with rice or a green salad.", "tags": "grilled, summer, tropical", "source": "Classic", "nutritionData": "{\"calories\": 580, \"protein\": 37.0, \"carbs\": 18.0, \"fat\": 43.0}"},
  {"name": "Honey Walnut Shrimp", "category": "Seafood", "description": "Crispy battered shrimp tossed in a creamy honey sauce and topped with candied walnuts.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"1/2 cup\", \"name\": \"walnuts\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"cornstarch\"}, {\"qty\": \"2\", \"name\": \"egg whites\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"2 tbsp\", \"name\": \"sweetened condensed milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"\", \"name\": \"steamed white rice for serving\"}]", "instructions": "1. Bring 1/2 cup water and sugar to a boil; add walnuts and cook 2 minutes; drain and cool on parchment. 2. Whisk egg whites until frothy; toss shrimp in egg whites then in cornstarch to coat. 3. Heat 2 inches of oil to 375°F in a heavy pot. 4. Fry shrimp in batches 2 to 3 minutes until golden and crispy; drain on paper towels. 5. Mix mayonnaise, condensed milk, honey, lemon juice, and sesame oil in a large bowl. 6. Toss fried shrimp in the sauce until evenly coated. 7. Serve immediately over steamed rice topped with candied walnuts.", "tags": "Chinese-American, crispy, sweet", "source": "Classic", "nutritionData": "{\"calories\": 530, \"protein\": 32.0, \"carbs\": 28.0, \"fat\": 33.0}"},
  {"name": "Thai Basil Shrimp Stir-Fry", "category": "Seafood", "description": "Quick and spicy shrimp stir-fry with Thai basil, chilies, and oyster sauce over jasmine rice.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3\", \"name\": \"Thai chilies thinly sliced\"}, {\"qty\": \"1\", \"name\": \"shallot thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 cup\", \"name\": \"fresh Thai basil leaves\"}, {\"qty\": \"1/2\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"\", \"name\": \"steamed jasmine rice for serving\"}]", "instructions": "1. Combine oyster sauce, fish sauce, soy sauce, and sugar in a small bowl; set aside. 2. Heat oil in a wok or large skillet over very high heat until smoking. 3. Add garlic, Thai chilies, and shallot; stir-fry 30 seconds until fragrant. 4. Add shrimp and bell pepper; stir-fry 2 to 3 minutes until shrimp are pink. 5. Pour in sauce; toss everything together and cook 1 minute more. 6. Remove from heat; stir in Thai basil leaves until just wilted. 7. Serve immediately over steamed jasmine rice.", "tags": "Thai, spicy, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 390, \"protein\": 44.0, \"carbs\": 32.0, \"fat\": 8.0}"},
  {"name": "Spicy Tuna Poke Bowl", "category": "Seafood", "description": "Hawaiian-style raw tuna poke with sesame soy dressing served over sushi rice with fresh toppings.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"sushi-grade ahi tuna cut into 3/4-inch cubes\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"Sriracha\"}, {\"qty\": \"1 tsp\", \"name\": \"honey\"}, {\"qty\": \"3\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame seeds\"}, {\"qty\": \"2 cups\", \"name\": \"sushi rice\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice vinegar for rice\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"avocados sliced\"}, {\"qty\": \"1\", \"name\": \"cucumber thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"edamame\"}, {\"qty\": \"\", \"name\": \"pickled ginger for serving\"}]", "instructions": "1. Cook sushi rice per package instructions; fold in rice vinegar, sugar, and salt while warm; fan to room temperature. 2. Whisk soy sauce, sesame oil, rice vinegar, Sriracha, and honey together. 3. Add tuna cubes and scallions; toss to coat; marinate 10 minutes in the refrigerator. 4. Divide sushi rice among four bowls. 5. Top each bowl with marinated tuna, avocado slices, cucumber, and edamame. 6. Garnish with sesame seeds and pickled ginger. Serve immediately.", "tags": "Hawaiian, no-cook, bowl", "source": "Classic", "nutritionData": "{\"calories\": 700, \"protein\": 45.0, \"carbs\": 60.0, \"fat\": 22.0}"},
  {"name": "Smoked Salmon Pasta", "category": "Seafood", "description": "Creamy fettuccine with smoked salmon, capers, and lemon zest — a quick and elegant weeknight dinner.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fettuccine\"}, {\"qty\": \"8 oz\", \"name\": \"smoked salmon torn into pieces\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2\", \"name\": \"shallots finely minced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"capers drained\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh dill\"}, {\"qty\": \"1/4 cup\", \"name\": \"cr\\u00e8me fra\\u00eeche\"}, {\"qty\": \"\", \"name\": \"salt and white pepper to taste\"}]", "instructions": "1. Cook fettuccine in salted boiling water until al dente; reserve 1/2 cup pasta water before draining. 2. Melt butter in a large skillet over medium heat; sauté shallots until soft about 3 minutes; add garlic and cook 1 minute. 3. Pour in heavy cream; simmer until slightly thickened about 3 minutes. 4. Stir in crème fraîche, lemon juice, and lemon zest. 5. Toss drained pasta with the cream sauce adding pasta water as needed. 6. Fold in smoked salmon and capers; remove from heat immediately so salmon stays silky. 7. Garnish with fresh dill and white pepper; serve right away.", "tags": "quick, creamy, elegant", "source": "Classic", "nutritionData": "{\"calories\": 820, \"protein\": 28.0, \"carbs\": 88.0, \"fat\": 38.0}"},
  {"name": "Crispy Coconut Shrimp", "category": "Seafood", "description": "Shrimp coated in toasted coconut and panko, fried until golden and served with a sweet mango dipping sauce.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"large shrimp peeled and deveined tails on\"}, {\"qty\": \"1 cup\", \"name\": \"sweetened shredded coconut\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1\", \"name\": \"ripe mango diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"sweet chili sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}]", "instructions": "1. Make dipping sauce by blending mango, sweet chili sauce, lime juice, and ginger until smooth; refrigerate. 2. Set up breading station: flour with salt and cayenne in one dish, beaten eggs in a second, coconut mixed with panko in a third. 3. Pat shrimp dry; dredge in flour then egg then press firmly into coconut-panko mixture. 4. Heat 2 inches of oil in a heavy pot to 350°F. 5. Fry shrimp in batches 2 to 3 minutes until golden and coconut is toasted; drain on paper towels. 6. Serve immediately with mango dipping sauce.", "tags": "appetizer, tropical, crispy", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 47.0, \"carbs\": 35.0, \"fat\": 22.0}"},
  {"name": "Lobster Bisque", "category": "Seafood", "description": "Velvety rich bisque made with a deep lobster shell stock and chunks of tender lobster meat.", "servings": 4, "prepTime": 30, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"lobster tails or 1 lb cooked lobster meat\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"2\", \"name\": \"carrots diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/4 cup\", \"name\": \"cognac or brandy\"}, {\"qty\": \"1 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"4 cups\", \"name\": \"seafood stock\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"half-and-half\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"kosher salt and white pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}]", "instructions": "1. If using whole lobster tails, cook in boiling salted water 8 minutes; remove meat and reserve shells. 2. Melt butter in a large pot over medium heat; sauté onion, celery, and carrots until soft about 8 minutes. 3. Add garlic and tomato paste; cook 2 minutes more. 4. Add cognac; cook 1 minute until mostly evaporated. 5. Add white wine, lobster shells, stock, paprika, thyme, and bay leaf; simmer 20 minutes. 6. Remove shells and bay leaf; use an immersion blender to purée soup until smooth. 7. Stir in heavy cream and half-and-half; simmer 10 minutes until slightly thickened; season with salt and white pepper. 8. Chop lobster meat into bite-sized pieces; stir into bisque; heat through 2 minutes. Serve garnished with chives.", "tags": "special-occasion, rich, restaurant-quality", "source": "Classic", "nutritionData": "{\"calories\": 555, \"protein\": 25.0, \"carbs\": 8.0, \"fat\": 37.0}"},
  {"name": "Salmon Patties with Dill Aioli", "category": "Seafood", "description": "Pan-fried salmon cakes made from canned wild salmon with a creamy homemade dill aioli.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"(14.75 oz each) wild-caught salmon drained\"}, {\"qty\": \"1/3 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"2 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2\", \"name\": \"scallions finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh dill chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"mayonnaise for aioli\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh dill for aioli\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced for aioli\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice for aioli\"}]", "instructions": "1. Make dill aioli by mixing 1/2 cup mayonnaise with 2 tbsp dill, minced garlic, and 1 tbsp lemon juice; refrigerate. 2. Combine drained salmon, panko, egg, 3 tbsp mayonnaise, mustard, lemon juice, scallions, 1 tbsp dill, and Old Bay; mix gently. 3. Season with salt and pepper; form into 8 patties about 1/2-inch thick. 4. Refrigerate patties 10 minutes to firm up. 5. Heat olive oil in a large skillet over medium-high heat. 6. Cook patties 3 to 4 minutes per side until golden brown and heated through. 7. Serve warm with dill aioli and lemon wedges.", "tags": "budget-friendly, weeknight, canned-salmon", "source": "Classic", "nutritionData": "{\"calories\": 540, \"protein\": 28.0, \"carbs\": 7.0, \"fat\": 43.0}"},
  {"name": "Garlic Steamed Dungeness Crab", "category": "Seafood", "description": "Whole Dungeness crab steamed until bright red and served with warm garlic drawn butter and lemon.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"live or pre-cooked Dungeness crabs (about 2 lbs each)\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"1\", \"name\": \"lemon halved\"}, {\"qty\": \"1 tbsp\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"extra lemon wedges for serving\"}]", "instructions": "1. Fill a large steamer pot with 2 inches of salted water; add a steamer basket and bring to a boil. 2. Place crabs in the steamer basket; sprinkle with Old Bay; cover tightly. 3. Steam live crabs 15 to 20 minutes until bright red and cooked through; steam pre-cooked crabs 8 minutes until heated through. 4. While crabs steam, melt butter in a small saucepan over low heat with garlic; simmer 5 minutes then squeeze in juice from half lemon. 5. Strain garlic from butter and keep warm. 6. Serve crabs immediately with drawn butter, lemon wedges, and a seafood cracker set. 7. Garnish with fresh parsley.", "tags": "West Coast, special-occasion, shellfish", "source": "Classic", "nutritionData": "{\"calories\": 415, \"protein\": 43.0, \"carbs\": 1.0, \"fat\": 26.0}"},
  {"name": "Roasted Brussels Sprouts", "category": "Sides & Vegetables", "description": "Halved Brussels sprouts roasted at high heat until caramelized and crispy on the edges.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"Brussels sprouts, trimmed and halved\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}]", "instructions": "1. Preheat oven to 425°F and line a baking sheet with parchment paper. 2. Trim and halve the Brussels sprouts and place on the baking sheet. 3. Drizzle with olive oil, season with salt and pepper, and toss to coat evenly. 4. Arrange cut-side down in a single layer on the sheet pan. 5. Roast for 20 to 25 minutes until deeply golden on the flat sides. 6. Remove from oven and toss with minced garlic and Parmesan. 7. Squeeze lemon juice over the top and serve immediately.", "tags": "roasted, vegetarian, gluten-free", "source": "https://www.bonappetit.com/recipe/roasted-brussels-sprouts-with-warm-honey-glaze", "nutritionData": "{\"calories\": 154, \"protein\": 5.0, \"carbs\": 11.0, \"fat\": 12.0}"},
  {"name": "Ratatouille", "category": "Sides & Vegetables", "description": "A classic Provencal baked vegetable dish with layered zucchini and eggplant over tomato sauce.", "servings": 6, "prepTime": 25, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium eggplant, thinly sliced\"}, {\"qty\": \"2\", \"name\": \"medium zucchini, thinly sliced\"}, {\"qty\": \"2\", \"name\": \"medium yellow squash, thinly sliced\"}, {\"qty\": \"4\", \"name\": \"roma tomatoes, thinly sliced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper, thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"tomato sauce\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 375°F. 2. Spread tomato sauce evenly in the bottom of a large baking dish and stir in garlic. 3. Slice all vegetables into thin rounds approximately 1/16-inch thick using a mandoline. 4. Arrange vegetables in alternating overlapping rows over the tomato sauce. 5. Drizzle with olive oil and sprinkle with thyme, salt, and pepper. 6. Cover with foil and bake 45 minutes until almost fork-tender. 7. Remove foil, increase oven to 425°F, and bake 15 minutes more until edges are caramelized. 8. Serve warm or at room temperature.", "tags": "vegetarian, vegan, make-ahead", "source": "https://smittenkitchen.com/2007/07/ratatouille-style-ratatouille/", "nutritionData": "{\"calories\": 116, \"protein\": 4.0, \"carbs\": 16.0, \"fat\": 6.0}"},
  {"name": "Crispy Sweet Potato Roast", "category": "Sides & Vegetables", "description": "Thinly sliced sweet potatoes fanned upright in a baking dish and roasted until crisped on top.", "servings": 8, "prepTime": 20, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"5 lbs\", \"name\": \"sweet potatoes, peeled and thinly sliced\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter, melted\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"shallots, peeled and thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}]", "instructions": "1. Preheat oven to 375°F. 2. Melt butter and oil together in a small saucepan. 3. Pour 2 tablespoons of the butter-oil mixture into the bottom of a 2-quart baking dish. 4. Arrange potato slices vertically in the dish and tuck shallot slivers between every few slices. 5. Brush tops with remaining butter-oil mixture and season generously with salt, pepper, and pepper flakes. 6. Cover with foil and bake 45 to 50 minutes until potatoes are tender. 7. Increase heat to 450°F, remove foil, and roast 15 to 20 minutes more until tops are browned and crispy. 8. Serve immediately.", "tags": "vegetarian, holiday, impressive", "source": "https://smittenkitchen.com/2014/11/crispy-sweet-potato-roast/", "nutritionData": "{\"calories\": 333, \"protein\": 5.0, \"carbs\": 58.0, \"fat\": 10.0}"},
  {"name": "Slow-Roasted Sweet Potatoes", "category": "Sides & Vegetables", "description": "Sweet potatoes rubbed with oil and salt and baked low and slow until the flesh is deeply caramelized.", "servings": 4, "prepTime": 5, "cookTime": 150, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"medium sweet potatoes, scrubbed\"}, {\"qty\": \"4 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"salted butter, for serving\"}]", "instructions": "1. Preheat oven to 275°F and line a large baking sheet with foil. 2. Rub each sweet potato with 1 teaspoon olive oil, 1/2 teaspoon salt, and 1/4 teaspoon pepper until well coated. 3. Arrange on the baking sheet and bake until very soft inside and caramelized on the bottom, about 2 1/2 hours. 4. Switch oven to broil and run potatoes under the broiler until lightly charred on top, 5 to 10 minutes. 5. Let cool 10 minutes, then gently crush each potato to expose the flesh. 6. Finish with a pat of butter and serve.", "tags": "vegetarian, gluten-free, make-ahead", "source": "https://smittenkitchen.com/2018/02/slow-roasted-sweet-potatoes/", "nutritionData": "{\"calories\": 263, \"protein\": 3.0, \"carbs\": 40.0, \"fat\": 10.0}"},
  {"name": "Best Ever Green Bean Casserole", "category": "Sides & Vegetables", "description": "A from-scratch green bean casserole with fresh mushrooms and homemade cream sauce.", "servings": 8, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh green beans, trimmed and halved\"}, {\"qty\": \"12 oz\", \"name\": \"cremini mushrooms, sliced\"}, {\"qty\": \"1 cup\", \"name\": \"half-and-half\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 cup\", \"name\": \"crispy fried onions\"}]", "instructions": "1. Preheat oven to 400°F. 2. Blanch green beans in salted boiling water for 5 minutes, then plunge into ice water and drain. 3. Melt butter in a large oven-safe skillet over medium heat and saute mushrooms until golden, about 8 minutes. 4. Add garlic and cook 1 minute. Whisk in flour and cook 1 minute more. 5. Gradually whisk in half-and-half and broth, cooking until thickened, about 3 minutes. 6. Season with salt, pepper, and soy sauce. Stir in green beans. 7. Top with panko and fried onions and bake uncovered 20 minutes until bubbly and golden.", "tags": "comfort food, holiday, make-ahead", "source": "https://www.foodnetwork.com/recipes/alton-brown/best-ever-green-bean-casserole-recipe-1950575", "nutritionData": "{\"calories\": 139, \"protein\": 4.0, \"carbs\": 13.0, \"fat\": 8.0}"},
  {"name": "Gingery Glazed Carrots", "category": "Sides & Vegetables", "description": "Tender carrots coated in a glossy ginger glaze with butter and a touch of soy sauce.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"medium carrots, peeled and cut on diagonal\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger, grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Combine water, butter, ginger, sugar, and soy sauce in a large skillet over medium-high heat. 2. Add carrots and bring to a boil. 3. Cover and cook, stirring occasionally, until carrots are almost tender, about 12 minutes. 4. Stir cornstarch into 1 tablespoon cold water to form a slurry. 5. Uncover carrots and stir in cornstarch slurry, cooking until sauce thickens and glazes the carrots, 2 to 3 minutes. 6. Season with salt and rice vinegar, garnish with parsley, and serve.", "tags": "vegetarian, gluten-free, quick", "source": "https://www.seriouseats.com/gingery-glazed-carrots-recipe", "nutritionData": "{\"calories\": 113, \"protein\": 1.0, \"carbs\": 15.0, \"fat\": 6.0}"},
  {"name": "Creamed Spinach and Wild Rice Casserole", "category": "Sides & Vegetables", "description": "A rich bake of caramelized onions with creamy spinach, wild rice, and melted Gruyere.", "servings": 8, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"cooked wild rice\"}, {\"qty\": \"10 oz\", \"name\": \"fresh spinach\"}, {\"qty\": \"2\", \"name\": \"large sweet onions, thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"poultry seasoning\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese, cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"grated Gruyere cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 375°F and grease a 9x13-inch baking dish. 2. Cook onions in butter over medium-low heat, stirring occasionally, until deeply caramelized, about 30 minutes. 3. Add spinach and cook until wilted. Add garlic, thyme, and poultry seasoning and cook 1 minute more. 4. Stir in cream cheese, heavy cream, and milk until smooth. Season with salt and pepper. 5. Spread wild rice in the baking dish and pour creamed spinach mixture over it, stirring gently. 6. Top with Gruyere and bake 30 minutes until bubbly and golden. Let rest 5 minutes before serving.", "tags": "vegetarian, make-ahead, comfort food", "source": "https://www.halfbakedharvest.com/kale-wild-rice-casserole/", "nutritionData": "{\"calories\": 294, \"protein\": 11.0, \"carbs\": 17.0, \"fat\": 21.0}"},
  {"name": "Crispy Sweet Potatoes with Bourbon Maple Butter", "category": "Sides & Vegetables", "description": "Smashed and twice-roasted sweet potatoes drizzled with a bourbon maple pecan butter.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large sweet potatoes, peeled and cubed\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1 tbsp\", \"name\": \"bourbon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"pecans, roughly chopped\"}]", "instructions": "1. Preheat oven to 425°F and line a baking sheet with parchment paper. 2. Toss sweet potatoes with olive oil, salt, and pepper and spread on the baking sheet. 3. Roast for 20 minutes until soft and beginning to char on the edges. 4. Remove from oven and gently smash each cube slightly with a fork to flatten. 5. Melt butter in a small saucepan and stir in maple syrup, bourbon, and cayenne; cook 1 minute. 6. Toast pecans in a dry skillet over medium heat until fragrant, about 3 minutes. 7. Drizzle bourbon maple butter over the sweet potatoes and return to oven for 10 minutes. 8. Serve topped with toasted pecans.", "tags": "vegetarian, holiday, sweet", "source": "https://www.halfbakedharvest.com/crispy-roasted-sweet-potatoes-bourbon-maple-butter/", "nutritionData": "{\"calories\": 329, \"protein\": 3.0, \"carbs\": 31.0, \"fat\": 21.0}"},
  {"name": "Buttery Mashed Potatoes", "category": "Sides & Vegetables", "description": "Classic creamy mashed potatoes made with Yukon Gold potatoes, butter, and warm cream.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"Yukon Gold potatoes, peeled and quartered\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter, cubed\"}, {\"qty\": \"3/4 cup\", \"name\": \"heavy cream, warmed\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, optional\"}]", "instructions": "1. Place potatoes in a large pot and cover with cold salted water. 2. Bring to a boil over high heat, then reduce to a steady simmer. 3. Cook until potatoes are very tender when pierced with a fork, 15 to 20 minutes. 4. Drain well and return to the pot over low heat for 1 minute to evaporate excess moisture. 5. Pass potatoes through a ricer or mash with a potato masher until smooth. 6. Add butter in pieces and stir until fully melted. 7. Gradually add warm cream and stir until fluffy and smooth. 8. Season with salt and white pepper and serve immediately.", "tags": "vegetarian, comfort food, holiday", "source": "https://www.halfbakedharvest.com/make-ahead-roasted-garlic-mashed-potatoes/", "nutritionData": "{\"calories\": 381, \"protein\": 5.0, \"carbs\": 40.0, \"fat\": 23.0}"},
  {"name": "Scalloped Potatoes au Gratin", "category": "Sides & Vegetables", "description": "Thinly sliced potatoes layered with cream and garlic and topped with melted Gruyere.", "servings": 8, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"Yukon Gold potatoes, very thinly sliced\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"grated Gruyere cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"freshly grated nutmeg\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}]", "instructions": "1. Preheat oven to 375°F and butter a 9x13-inch baking dish. 2. Combine cream, milk, garlic, salt, pepper, and nutmeg in a saucepan and bring just to a simmer. 3. Layer one-third of the potato slices in the dish, slightly overlapping, then pour over one-third of the cream mixture and sprinkle with one-third of the cheeses. 4. Repeat layers twice more, finishing with cheese on top. 5. Cover tightly with foil and bake 35 minutes. 6. Remove foil and bake 20 to 25 minutes more until potatoes are tender and top is golden and bubbly. 7. Let rest 10 minutes before slicing and serving.", "tags": "vegetarian, holiday, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 445, \"protein\": 14.0, \"carbs\": 32.0, \"fat\": 29.0}"},
  {"name": "Roasted Broccoli with Parmesan", "category": "Sides & Vegetables", "description": "Broccoli florets roasted at high heat until charred and tender, finished with Parmesan and lemon.", "servings": 4, "prepTime": 5, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large head broccoli, cut into florets\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"freshly grated Parmesan cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}]", "instructions": "1. Preheat oven to 425°F and line a baking sheet with parchment paper. 2. Cut broccoli into even medium florets and pat dry thoroughly. 3. Toss florets with olive oil, garlic, salt, pepper, and red pepper flakes on the baking sheet. 4. Spread in a single layer with space between florets. 5. Roast for 14 to 18 minutes until edges are golden and stems are crisp-tender. 6. Immediately sprinkle with Parmesan and lemon juice and serve warm.", "tags": "vegetarian, gluten-free, quick", "source": "https://smittenkitchen.com/2015/04/crispy-broccoli-with-lemon-and-garlic/", "nutritionData": "{\"calories\": 157, \"protein\": 5.0, \"carbs\": 11.0, \"fat\": 12.0}"},
  {"name": "Roasted Cauliflower with Garlic", "category": "Sides & Vegetables", "description": "Cauliflower florets tossed in olive oil and roasted until golden brown with caramelized edges.", "servings": 4, "prepTime": 10, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large head cauliflower, cut into florets\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter, melted\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Preheat oven to 425°F and line a large baking sheet with parchment paper. 2. Break cauliflower into even bite-sized florets and add to the baking sheet. 3. Drizzle with olive oil and melted butter, then sprinkle with garlic powder, paprika, salt, and pepper. 4. Toss to coat and spread into a single even layer with flat sides down. 5. Roast for 15 minutes, then flip and roast another 7 minutes until golden and caramelized. 6. Sprinkle with parsley and serve immediately.", "tags": "vegetarian, vegan, gluten-free", "source": "https://smittenkitchen.com/2016/11/roasted-cauliflower-with-pumpkin-seeds-brown-butter-and-lime/", "nutritionData": "{\"calories\": 199, \"protein\": 4.0, \"carbs\": 12.0, \"fat\": 17.0}"},
  {"name": "Roasted Asparagus with Lemon", "category": "Sides & Vegetables", "description": "Fresh asparagus roasted at high heat with olive oil and finished with bright lemon and Parmesan.", "servings": 4, "prepTime": 5, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh asparagus, woody ends trimmed\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"lemon, halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Preheat oven to 425°F and line a rimmed baking sheet with parchment paper. 2. Place trimmed asparagus on the baking sheet and pat dry. 3. Drizzle with olive oil, season with salt and pepper, and toss to coat. 4. Spread in a single layer and place lemon halves cut-side down alongside asparagus. 5. Roast thin asparagus 9 to 12 minutes or thick spears 15 to 20 minutes until fork-tender. 6. Transfer to a serving platter, squeeze roasted lemon over the top, and sprinkle with Parmesan and parsley.", "tags": "vegetarian, gluten-free, quick", "source": "https://www.foodnetwork.com/recipes/ina-garten/roasted-asparagus-recipe-1916355", "nutritionData": "{\"calories\": 96, \"protein\": 3.0, \"carbs\": 5.0, \"fat\": 8.0}"},
  {"name": "Honey Roasted Carrots", "category": "Sides & Vegetables", "description": "Caramelized roasted carrots tossed with honey, garlic, and butter until sticky and golden.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"medium carrots, peeled and cut into 2-inch pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter, melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Preheat oven to 425°F. 2. Toss carrots with olive oil, butter, honey, garlic, salt, and pepper in a large bowl. 3. Spread on a rimmed baking sheet in a single layer. 4. Roast for 15 minutes, then toss carrots in the accumulated glaze and spread out again. 5. Continue roasting 10 minutes more until tender and caramelized on the edges. 6. Transfer to a serving dish, toss in any remaining glaze, and sprinkle with parsley. 7. Serve warm.", "tags": "vegetarian, gluten-free, holiday", "source": "Classic", "nutritionData": "{\"calories\": 193, \"protein\": 1.0, \"carbs\": 20.0, \"fat\": 13.0}"},
  {"name": "Hasselback Potatoes", "category": "Sides & Vegetables", "description": "Accordion-sliced potatoes roasted until crispy on the edges and fluffy inside with garlic herb butter.", "servings": 6, "prepTime": 15, "cookTime": 75, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"medium Yukon Gold potatoes\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter, melted\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary, minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, for serving\"}]", "instructions": "1. Preheat oven to 425°F and line a baking sheet with parchment paper. 2. Place each potato between two chopsticks to act as a cutting guide. 3. Slice each potato crosswise into very thin 1/8-inch slices, stopping when the knife hits the chopsticks so the base stays intact. 4. Place potatoes on the baking sheet, drizzle with olive oil, and season with salt and pepper, working oil between the slices. 5. Roast for 50 minutes. 6. Whisk together melted butter, garlic, rosemary, and thyme. Brush generously over potatoes, getting butter between the slices. 7. Return to oven and roast 25 more minutes until slices are deeply golden and crispy. 8. Sprinkle with parsley and serve immediately.", "tags": "vegetarian, impressive, holiday", "source": "https://www.halfbakedharvest.com/crispy-rosemary-butter-roasted-potatoes/", "nutritionData": "{\"calories\": 268, \"protein\": 3.0, \"carbs\": 26.0, \"fat\": 17.0}"},
  {"name": "Herb Rice Pilaf", "category": "Sides & Vegetables", "description": "Toasted long-grain rice cooked in seasoned broth with onion and fresh herbs until fluffy.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"long-grain white rice\"}, {\"qty\": \"3 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1\", \"name\": \"small onion, finely diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives, chopped\"}]", "instructions": "1. Melt butter with olive oil in a medium saucepan over medium heat. 2. Add onion and saute until translucent, about 4 minutes. Add garlic and cook 1 minute more. 3. Add rice and stir to coat, toasting until lightly golden and fragrant, about 4 minutes. 4. Season with salt and pepper, then pour in warmed broth and bring to a boil. 5. Cover tightly, reduce heat to low, and cook for 15 minutes without lifting the lid. 6. Remove from heat and let rest, covered, for 10 minutes. 7. Fluff with a fork, stir in parsley and chives, and serve.", "tags": "vegetarian, make-ahead, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 131, \"protein\": 3.0, \"carbs\": 16.0, \"fat\": 6.0}"},
  {"name": "Roasted Vegetable Quinoa", "category": "Sides & Vegetables", "description": "Fluffy quinoa tossed with roasted seasonal vegetables and a bright lemon dressing.", "servings": 6, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"quinoa, rinsed\"}, {\"qty\": \"3 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1\", \"name\": \"zucchini, diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper, diced\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes, halved\"}, {\"qty\": \"1 cup\", \"name\": \"canned chickpeas, drained\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil, torn\"}]", "instructions": "1. Preheat oven to 400°F. 2. Toss zucchini, bell pepper, and tomatoes with 2 tablespoons olive oil, salt, and pepper on a baking sheet. Roast 20 minutes until tender. 3. Combine quinoa and broth in a saucepan, bring to a boil, then reduce to a gentle simmer and cook uncovered 15 minutes until liquid is absorbed. 4. Remove from heat, cover, and rest 5 minutes, then fluff with a fork. 5. Whisk together remaining olive oil, lemon juice, lemon zest, and garlic to make a dressing. 6. Combine quinoa, roasted vegetables, and chickpeas in a large bowl. Drizzle with dressing and toss. 7. Stir in fresh basil and serve warm or at room temperature.", "tags": "vegan, gluten-free, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 304, \"protein\": 11.0, \"carbs\": 42.0, \"fat\": 11.0}"},
  {"name": "Lemon Herb Couscous", "category": "Sides & Vegetables", "description": "Fluffy couscous steamed in broth and tossed with fresh herbs, toasted almonds, and bright citrus.", "servings": 6, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"couscous\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"vegetable broth, boiling\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley, chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh mint, chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted slivered almonds\"}, {\"qty\": \"1/4 cup\", \"name\": \"dried currants\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Place couscous in a large heatproof bowl with salt and olive oil. 2. Pour boiling broth over couscous, stir once, and immediately cover tightly with plastic wrap. 3. Let steam for 5 minutes without lifting the cover. 4. Fluff couscous with a fork, breaking up any clumps. 5. Add lemon zest, lemon juice, parsley, mint, almonds, and currants and toss gently. 6. Season with black pepper and additional salt to taste. 7. Serve warm or at room temperature.", "tags": "vegan, quick, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 243, \"protein\": 7.0, \"carbs\": 38.0, \"fat\": 7.0}"},
  {"name": "Sauteed Garlic Mushrooms", "category": "Sides & Vegetables", "description": "Cremini mushrooms sauteed in butter with garlic and fresh thyme until golden and deeply savory.", "servings": 4, "prepTime": 5, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"cremini mushrooms, cleaned and sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Heat olive oil in a large skillet over medium-high heat until shimmering. 2. Add butter, mushrooms, salt, and pepper and cook, stirring occasionally, until mushrooms release their liquid and liquid evaporates, about 8 to 10 minutes. 3. Stir in soy sauce, balsamic vinegar, and garlic and cook, stirring constantly, for 30 to 60 seconds until garlic is fragrant. 4. Remove from heat and stir in fresh thyme and parsley. 5. Taste and adjust seasoning, then serve hot.", "tags": "vegetarian, gluten-free, quick", "source": "https://www.foodnetwork.com/recipes/ina-garten/sauteed-wild-mushrooms-recipe2-1942881", "nutritionData": "{\"calories\": 147, \"protein\": 4.0, \"carbs\": 6.0, \"fat\": 13.0}"},
  {"name": "Creamed Spinach", "category": "Sides & Vegetables", "description": "Rich and velvety creamed spinach made with fresh spinach, cream cheese, and Parmesan.", "servings": 6, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"fresh baby spinach\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"small shallot, minced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese, cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"freshly grated nutmeg\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}]", "instructions": "1. Bring a large pot of salted water to a boil. Add spinach and blanch 1 minute until wilted. 2. Drain and squeeze out excess moisture in small handfuls. Roughly chop and set aside. 3. Melt butter in a large skillet over medium heat. Add shallot and cook until softened, about 3 minutes. Add garlic and cook 1 minute more. 4. Add cream cheese and heavy cream, stirring until cream cheese melts and sauce is smooth. 5. Stir in Parmesan and nutmeg. 6. Add chopped spinach and stir to combine and heat through, 2 to 3 minutes. 7. Season with salt, pepper, and lemon juice. Serve hot.", "tags": "vegetarian, gluten-free, holiday", "source": "Classic", "nutritionData": "{\"calories\": 243, \"protein\": 9.0, \"carbs\": 8.0, \"fat\": 20.0}"},
  {"name": "Classic Coleslaw", "category": "Sides & Vegetables", "description": "Crisp green and red cabbage tossed in a creamy tangy dressing with celery seed and honey.", "servings": 8, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"shredded green cabbage\"}, {\"qty\": \"2 cups\", \"name\": \"shredded red cabbage\"}, {\"qty\": \"2\", \"name\": \"medium carrots, grated\"}, {\"qty\": \"1 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 1/2 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"3/4 tsp\", \"name\": \"celery seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Combine shredded green cabbage, red cabbage, and grated carrots in a large bowl. 2. In a separate bowl, whisk together mayonnaise, vinegar, honey, celery seeds, salt, and pepper until smooth. 3. Pour dressing over the cabbage mixture and toss thoroughly to coat. 4. Cover and refrigerate for at least 30 minutes to allow flavors to meld and cabbage to soften slightly. 5. Toss again just before serving and adjust seasoning as needed.", "tags": "vegetarian, make-ahead, no-cook", "source": "https://smittenkitchen.com/2006/11/not-your-mamas-coleslaw/", "nutritionData": "{\"calories\": 210, \"protein\": 1.0, \"carbs\": 7.0, \"fat\": 20.0}"},
  {"name": "Caprese Salad", "category": "Sides & Vegetables", "description": "A classic Italian salad of ripe heirloom tomatoes, fresh mozzarella, basil, and good olive oil.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large heirloom tomatoes, sliced\"}, {\"qty\": \"8 oz\", \"name\": \"fresh mozzarella, sliced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"balsamic reduction\"}, {\"qty\": \"1/2 tsp\", \"name\": \"flaky sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Slice tomatoes and mozzarella into roughly 1/4-inch thick rounds. 2. On a large serving platter, alternate and overlap slices of tomato, mozzarella, and basil leaves. 3. Drizzle generously with extra-virgin olive oil. 4. Drizzle balsamic reduction over the top. 5. Season with flaky sea salt and black pepper. 6. Serve immediately at room temperature.", "tags": "vegetarian, gluten-free, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 291, \"protein\": 13.0, \"carbs\": 8.0, \"fat\": 24.0}"},
  {"name": "Cucumber Dill Salad", "category": "Sides & Vegetables", "description": "Crisp cucumbers and red onion marinated in a vinegar dressing and finished with fresh dill.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"English cucumbers, very thinly sliced\"}, {\"qty\": \"1/2\", \"name\": \"large red onion, very thinly sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"white wine vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh dill, chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives, chopped\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. In a large bowl, toss together sliced cucumber, onion, vinegar, honey, and salt until well coated. 2. Cover and refrigerate for 20 minutes, allowing the cucumbers to release their water and absorb the dressing. 3. Transfer to a clean serving bowl, leaving excess liquid behind. 4. Sprinkle with fresh dill and chives. 5. Season with black pepper and serve chilled.", "tags": "vegan, gluten-free, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 52, \"protein\": 1.0, \"carbs\": 13.0, \"fat\": 0.0}"},
  {"name": "Grilled Summer Vegetables", "category": "Sides & Vegetables", "description": "Zucchini, bell peppers, and eggplant grilled with a herb-garlic marinade until tender.", "servings": 6, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"zucchini, sliced lengthwise\"}, {\"qty\": \"2\", \"name\": \"red bell peppers, quartered\"}, {\"qty\": \"1\", \"name\": \"small eggplant, sliced into rounds\"}, {\"qty\": \"1\", \"name\": \"red onion, cut into thick rounds\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil, torn\"}]", "instructions": "1. Combine olive oil, balsamic vinegar, garlic, thyme, oregano, salt, and pepper in a small bowl. 2. Toss vegetables in the marinade and let sit for 10 minutes. 3. Preheat a gas or charcoal grill to medium-high heat. 4. Grill vegetables in batches, turning once, until tender with grill marks, about 3 to 4 minutes per side. 5. Transfer to a serving platter as they finish. 6. Drizzle any remaining marinade over the grilled vegetables, scatter fresh basil on top, and serve warm.", "tags": "vegan, gluten-free, summer", "source": "Classic", "nutritionData": "{\"calories\": 114, \"protein\": 2.0, \"carbs\": 12.0, \"fat\": 7.0}"},
  {"name": "Honey Butter Corn on the Cob", "category": "Sides & Vegetables", "description": "Sweet corn boiled in salted water and finished with honey butter and a pinch of smoked paprika.", "servings": 4, "prepTime": 5, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"ears fresh corn, husked\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter, softened\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives, for garnish\"}]", "instructions": "1. Bring a large pot of salted water to a boil. 2. Mix softened butter, honey, and smoked paprika in a small bowl until smooth. 3. Add corn to the boiling water and cook until kernels are bright yellow and crisp-tender, 4 to 5 minutes. 4. Remove corn with tongs and place on a serving platter. 5. Immediately spread each ear with a generous amount of honey butter. 6. Season with salt and pepper, garnish with chives, and serve hot.", "tags": "vegetarian, gluten-free, summer", "source": "https://www.halfbakedharvest.com/mexican-grilled-corn-with-green-chile-honey-butter/", "nutritionData": "{\"calories\": 205, \"protein\": 3.0, \"carbs\": 23.0, \"fat\": 12.0}"},
  {"name": "Buttermilk Cornbread", "category": "Sides & Vegetables", "description": "A moist and golden cornbread baked in a cast iron skillet with a crispy browned butter bottom.", "servings": 9, "prepTime": 10, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"fine yellow cornmeal\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"7 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"buttermilk\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey, for serving\"}]", "instructions": "1. Adjust oven rack to center position and preheat oven to 425°F. 2. Place butter in a 10-inch cast iron skillet and heat in the oven until well browned, 10 to 15 minutes. 3. Pour browned butter into a heatproof bowl, leaving about 1 tablespoon in the skillet. 4. Combine cornmeal, flour, sugar, salt, baking powder, and baking soda in a large bowl. 5. Whisk eggs, sour cream, and buttermilk together in a second bowl, then slowly drizzle in the browned butter while whisking constantly. 6. Fold wet ingredients into dry until just combined. 7. Pour batter into the skillet and smooth the top, then bake until golden and a skewer comes out clean, 20 to 25 minutes. 8. Let cool 10 minutes and serve warm with honey and butter.", "tags": "vegetarian, comfort food, baked", "source": "https://smittenkitchen.com/2021/06/perfect-forever-cornbread/", "nutritionData": "{\"calories\": 361, \"protein\": 5.0, \"carbs\": 32.0, \"fat\": 24.0}"},
  {"name": "Soft Dinner Rolls", "category": "Sides & Vegetables", "description": "Pillowy homemade dinner rolls with a buttery crust, perfect for any occasion.", "servings": 12, "prepTime": 30, "cookTime": 18, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk, warmed\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter, softened\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"melted butter, for brushing\"}, {\"qty\": \"1/4 tsp\", \"name\": \"flaky sea salt, for topping\"}]", "instructions": "1. Combine warm milk, sugar, and yeast in a large bowl and let stand until foamy, about 5 minutes. 2. Add egg, softened butter, and salt and stir to combine. 3. Add flour and mix until a shaggy dough forms, then knead on a lightly floured surface until smooth, about 8 minutes. 4. Place in a greased bowl, cover with plastic wrap, and let rise until doubled, about 1 hour. 5. Punch down dough and divide into 12 equal pieces. Shape each into a smooth ball and arrange in a greased 9x13-inch baking pan. 6. Cover and let rise until puffy, about 45 minutes. Preheat oven to 375°F. 7. Brush rolls with melted butter and sprinkle with flaky salt. Bake 16 to 18 minutes until golden brown. 8. Brush again with melted butter and serve warm.", "tags": "vegetarian, baked, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 210, \"protein\": 5.0, \"carbs\": 31.0, \"fat\": 7.0}"},
  {"name": "Garlic Herb Roasted Baby Potatoes", "category": "Sides & Vegetables", "description": "Crispy-edged baby potatoes tossed with garlic, rosemary, and thyme and roasted until golden.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"baby potatoes, halved\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary, minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, chopped\"}]", "instructions": "1. Preheat oven to 425°F and line a large baking sheet with parchment paper. 2. Toss halved potatoes with olive oil, garlic, rosemary, thyme, salt, and pepper until evenly coated. 3. Spread cut-side down on the baking sheet in a single layer. 4. Roast for 25 to 30 minutes, without stirring, until cut sides are deeply golden and crispy. 5. Remove from oven, immediately sprinkle with Parmesan, and toss gently. 6. Garnish with parsley and serve hot.", "tags": "vegetarian, gluten-free, holiday", "source": "https://www.halfbakedharvest.com/garlic-butter-smashed-potatoes/", "nutritionData": "{\"calories\": 239, \"protein\": 5.0, \"carbs\": 30.0, \"fat\": 11.0}"},
  {"name": "Brown Butter Green Beans with Almonds", "category": "Sides & Vegetables", "description": "Tender-crisp green beans blanched and finished in nutty brown butter with toasted almonds.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh green beans, trimmed\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"slivered almonds\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Bring a large pot of generously salted water to a boil. 2. Blanch green beans until crisp-tender, about 4 minutes. Drain and plunge into ice water to stop cooking, then drain and pat dry. 3. In a large skillet over medium heat, melt butter and cook, swirling often, until foam subsides and butter turns golden brown and nutty, about 3 to 4 minutes. 4. Add almonds and garlic and cook until almonds are lightly toasted, about 1 minute. 5. Add green beans and toss to coat, heating through for 2 minutes. 6. Season with salt and pepper, squeeze lemon juice over the top, and serve immediately.", "tags": "vegetarian, gluten-free, quick", "source": "Classic", "nutritionData": "{\"calories\": 152, \"protein\": 3.0, \"carbs\": 10.0, \"fat\": 12.0}"},
  {"name": "Balsamic Brussels Sprouts with Bacon", "category": "Sides & Vegetables", "description": "Brussels sprouts roasted with crispy bacon and finished with a sweet balsamic glaze.", "servings": 6, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"Brussels sprouts, trimmed and halved\"}, {\"qty\": \"6\", \"name\": \"strips bacon, cut into 1-inch pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}]", "instructions": "1. Preheat oven to 400°F and line a large baking sheet with foil. 2. Spread Brussels sprouts and bacon pieces on the baking sheet. Drizzle with olive oil, season with salt, pepper, and red pepper flakes, and toss to combine. 3. Arrange cut-side down in a single layer. 4. Roast for 20 minutes until sprouts are beginning to brown. 5. Whisk balsamic vinegar and maple syrup together, then drizzle over the pan and toss. 6. Return to oven and roast 8 to 10 minutes more until sprouts are caramelized and bacon is crispy. 7. Serve immediately.", "tags": "gluten-free, holiday, savory", "source": "Classic", "nutritionData": "{\"calories\": 146, \"protein\": 7.0, \"carbs\": 14.0, \"fat\": 8.0}"},
  {"name": "Reverse-Sear Ribeye", "category": "Steak", "description": "Thick ribeye slow-roasted in a low oven then seared in a screaming-hot cast iron for a perfect crust.", "servings": 2, "prepTime": 15, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"1.5-inch thick ribeye steaks\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"3\", \"name\": \"garlic cloves smashed\"}]", "instructions": "1. Season steaks generously with salt and pepper; place on a wire rack set over a baking sheet and refrigerate uncovered at least 1 hour or overnight. 2. Preheat oven to 250°F. Place rack with steaks in oven. 3. Cook until an instant-read thermometer reads 115°F for medium-rare, about 45-60 minutes. 4. Remove steaks from oven. Heat oil in a cast iron skillet over high heat until smoking. 5. Add steaks and sear, pressing down firmly, for 45-60 seconds per side until deeply browned. 6. Add butter, thyme, and garlic; baste steaks for 30 seconds. 7. Serve immediately — no resting needed with reverse sear.", "tags": "reverse-sear, cast-iron, weekend", "source": "https://www.seriouseats.com/reverse-seared-steak-recipe", "nutritionData": "{\"calories\": 1100, \"protein\": 78.0, \"carbs\": 0.0, \"fat\": 84.0}"},
  {"name": "Pan-Seared Filet Mignon", "category": "Steak", "description": "Butter-basted tenderloin medallions with a golden crust and rosy pink center cooked to perfection.", "servings": 2, "prepTime": 10, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"6-oz filet mignon steaks about 1.5 inches thick\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"3 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"garlic cloves smashed\"}, {\"qty\": \"1\", \"name\": \"shallot halved\"}]", "instructions": "1. Remove steaks from fridge 30 minutes before cooking. Pat dry and season all over with salt and pepper. 2. Heat oil in a cast iron skillet over high heat until just smoking. 3. Add steaks and sear without moving for 3 minutes until a deep brown crust forms. 4. Flip steaks; add butter, thyme, garlic, and shallot to the pan. 5. Tilt pan and baste steaks continuously with the foaming butter for 2 minutes. 6. Check temperature — pull at 120°F for medium-rare. 7. Rest steaks on a cutting board for 5 minutes before serving.", "tags": "tender, butter-basted, special-occasion", "source": "https://www.seriouseats.com/butter-basted-pan-seared-steaks-recipe", "nutritionData": "{\"calories\": 570, \"protein\": 44.0, \"carbs\": 0.0, \"fat\": 40.0}"},
  {"name": "Grilled New York Strip", "category": "Steak", "description": "Classic charcoal-grilled strip steaks seasoned simply with salt and finished with garlic compound butter.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"12-oz New York strip steaks 1.25 inches thick\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"4 tbsp\", \"name\": \"softened salted butter\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}]", "instructions": "1. One hour before cooking season steaks generously with salt; let rest at room temperature. 2. Mix butter with garlic, thyme, and Worcestershire; set aside as compound butter. 3. Prepare grill for high direct heat; clean and oil grates. 4. Place steaks on hot grill at 45 degrees; cook 2-3 minutes. Rotate 90 degrees, cook 2 more minutes. 5. Flip steaks and repeat on the second side, cooking to 130°F internal for medium-rare. 6. Transfer to a cutting board and top immediately with compound butter. 7. Rest 8-10 minutes before serving.", "tags": "grilled, charcoal, classic", "source": "https://www.dadcooksdinner.com/grilled-thick-cut-new-york-strip-steaks-sear-and-move-style/", "nutritionData": "{\"calories\": 1000, \"protein\": 88.0, \"carbs\": 2.0, \"fat\": 73.0}"},
  {"name": "Skirt Steak Fajitas", "category": "Steak", "description": "Sizzling marinated skirt steak with charred peppers and onions served in warm flour tortillas.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"outside skirt steak\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"lime juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ancho chile powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tbsp\", \"name\": \"canola oil\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"poblano chile sliced\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion sliced\"}, {\"qty\": \"8\", \"name\": \"warm flour tortillas\"}]", "instructions": "1. Cut skirt steak into 3 equal pieces; combine olive oil, lime juice, soy sauce, salt, chile powder, and cumin in a bowl. Reserve 1/4 cup marinade; pour rest over steak in a bag. Marinate 30 minutes. 2. Sear marinated steaks in canola oil in a hot cast iron skillet 2-3 minutes per side; rest and slice against the grain. 3. In the same skillet cook peppers and onions until softened, 5-6 minutes. 4. Return sliced steak to the skillet with reserved marinade for a final sizzle. 5. Serve immediately in warm tortillas with guacamole, pico de gallo, and sour cream.", "tags": "fajitas, tex-mex, weeknight", "source": "https://www.seriouseats.com/grilled-skirt-steak-fajitas-food-lab-recipe", "nutritionData": "{\"calories\": 840, \"protein\": 52.0, \"carbs\": 47.0, \"fat\": 49.0}"},
  {"name": "Steak au Poivre", "category": "Steak", "description": "Classic French pepper-crusted steak with a rich cognac and cream pan sauce for a restaurant-worthy dinner.", "servings": 2, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"12-oz New York strip steaks\"}, {\"qty\": \"3 tbsp\", \"name\": \"black peppercorns coarsely crushed\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"1/3 cup\", \"name\": \"cognac\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"cold unsalted butter\"}, {\"qty\": \"1\", \"name\": \"medium shallot minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"green peppercorns in brine\"}]", "instructions": "1. Pat steaks dry with paper towels and season with salt. Press crushed peppercorns firmly onto both sides of each steak. 2. Heat oil in a large stainless or cast iron pan over medium-high heat until shimmering. Add steaks; cook 4 minutes per side for medium-rare (120-125°F). Rest on a plate tented with foil. 3. Pour off excess fat from pan; add shallot and a pinch of salt; cook 2 minutes until soft. 4. Remove pan from heat; add cognac. Return to medium-high heat; cook until nearly evaporated, 2 minutes. 5. Add cream; simmer until sauce coats the back of a spoon, 2-3 minutes. Add green peppercorns. 6. Season sauce with salt; whisk in cold butter off heat. 7. Plate steaks and spoon sauce over top.", "tags": "french, pan-sauce, date-night", "source": "https://www.sipandfeast.com/steak-au-poivre/", "nutritionData": "{\"calories\": 1320, \"protein\": 90.0, \"carbs\": 4.0, \"fat\": 98.0}"},
  {"name": "Sous Vide Ribeye", "category": "Steak", "description": "Precisely temperature-controlled ribeye cooked in a water bath for edge-to-edge perfection then flash-seared.", "servings": 2, "prepTime": 15, "cookTime": 120, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"1.5-inch ribeye steaks\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter divided\"}, {\"qty\": \"2 tbsp\", \"name\": \"high-smoke-point oil\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}]", "instructions": "1. Season steaks with salt and pepper. Seal each steak in a separate vacuum or zip-top bag with a rosemary sprig and 1 tbsp butter. 2. Set sous vide circulator to 130°F for medium-rare. Submerge bags and cook for 2 hours. 3. Remove steaks from bags and pat completely dry with paper towels. Discard liquid. 4. Heat oil in a cast iron skillet over the highest heat until smoking. 5. Sear steaks 1 minute per side, pressing down for full contact; also sear the fat cap on the edges. 6. Add garlic and remaining butter for the last 30 seconds; baste quickly. 7. Serve immediately — no resting required.", "tags": "sous-vide, precise, weekend", "source": "https://www.seriouseats.com/food-lab-complete-guide-to-sous-vide-steak", "nutritionData": "{\"calories\": 1100, \"protein\": 78.0, \"carbs\": 0.0, \"fat\": 84.0}"},
  {"name": "Chimichurri Flank Steak", "category": "Steak", "description": "Grilled flank steak sliced against the grain and topped with vibrant garlicky Argentine herb sauce.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"flank steak\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 cup\", \"name\": \"flat-leaf parsley leaves packed\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh oregano leaves\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/4 cup\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra virgin olive oil\"}]", "instructions": "1. Make chimichurri: pulse parsley, oregano, garlic, and red pepper flakes in a food processor until finely chopped. Transfer to a bowl; stir in vinegar, salt, and olive oil. Set aside 1 hour. 2. Pat flank steak dry; season with salt and pepper. Let sit at room temperature 30 minutes. 3. Heat a grill or cast iron skillet to very high heat; oil the grates or pan. 4. Cook steak 4-5 minutes per side for medium-rare (125°F internal). 5. Rest steak on a cutting board for 5-10 minutes. 6. Slice thinly against the grain at a slight diagonal. 7. Plate and spoon chimichurri generously over the top.", "tags": "chimichurri, argentinian, gluten-free", "source": "https://www.recipetineats.com/skirt-steak-with-chimichurri-sauce/", "nutritionData": "{\"calories\": 620, \"protein\": 47.0, \"carbs\": 2.0, \"fat\": 48.0}"},
  {"name": "Korean Bulgogi Beef", "category": "Steak", "description": "Sweet and savory thinly sliced beef marinated in soy sauce and pear then grilled over high heat.", "servings": 4, "prepTime": 30, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"beef ribeye or sirloin thinly sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"Asian pear pureed\"}, {\"qty\": \"1/4 cup\", \"name\": \"onion pureed\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"1\", \"name\": \"green onion chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 pinch\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. In a bowl mix together pear puree, onion puree, garlic, ginger, green onion, soy sauce, brown sugar, and black pepper. 2. Add thinly sliced beef and mix gently, massaging marinade into the meat. Stir in sesame oil last. 3. Cover and refrigerate at least 30 minutes, or overnight for best flavor. 4. Heat a grill pan or skillet over medium-high heat; add cooking oil until shimmering. 5. Add beef in a single layer; cook 3-5 minutes until cooked through and slightly caramelized. 6. Sprinkle with sesame seeds. 7. Serve over steamed rice with kimchi and ssam vegetables.", "tags": "korean, marinated, quick", "source": "https://www.maangchi.com/recipe/bulgogi", "nutritionData": "{\"calories\": 400, \"protein\": 29.0, \"carbs\": 10.0, \"fat\": 27.0}"},
  {"name": "Hanger Steak with Herb Marinade", "category": "Steak", "description": "Deeply flavorful butcher's cut marinated in herbs and garlic then pan-seared to medium-rare perfection.", "servings": 2, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"hanger steak center sinew removed\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3\", \"name\": \"garlic cloves crushed\"}, {\"qty\": \"1\", \"name\": \"shallot sliced\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"1 tbsp\", \"name\": \"flat-leaf parsley chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for finishing\"}]", "instructions": "1. Combine olive oil, garlic, shallot, thyme, rosemary, and parsley in a bowl. Add steak, turning to coat. Marinate 6 hours or overnight in the fridge. 2. Remove steak from marinade; pat dry. Season with salt and pepper. 3. Heat a heavy skillet over medium-high heat until nearly smoking. 4. Sear steak, flipping every 1-2 minutes, until deeply browned and internal temperature reaches 100°F. 5. Add butter and aromatics; baste steak until it reaches 120°F. 6. Transfer to a cutting board and rest 5 minutes. 7. Slice thinly against the grain, finishing with flaky sea salt.", "tags": "hanger-steak, pan-seared, butcher-cut", "source": "https://www.thekitchn.com/hanger-steak-recipe-23716710", "nutritionData": "{\"calories\": 1080, \"protein\": 86.0, \"carbs\": 0.0, \"fat\": 82.0}"},
  {"name": "Tomahawk Steak Reverse Sear", "category": "Steak", "description": "Dramatic bone-in cowboy ribeye slow-cooked then finished on a screaming hot grill for a spectacular crust.", "servings": 2, "prepTime": 20, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"2.5-3 lb tomahawk ribeye steak\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"neutral oil for grill\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"2 sprigs\", \"name\": \"rosemary\"}]", "instructions": "1. Season tomahawk generously with salt, pepper, and garlic powder on all sides. Refrigerate uncovered on a rack overnight. 2. Preheat oven to 225°F; place steak on a wire rack over a sheet pan and insert a probe thermometer. 3. Roast until the internal temperature reaches 100°F, about 60-75 minutes. 4. Preheat a grill or grill pan to the highest possible heat (550°F+). 5. Sear tomahawk on all sides including the fat cap, 2-3 minutes per side, until charred grill marks form and internal temperature reaches 125°F. 6. Rest on a cutting board for 10 minutes. 7. Slice off the bone, then cut against the grain; finish with herb butter.", "tags": "tomahawk, showstopper, reverse-sear", "source": "https://www.billyparisi.com/tomahawk-steak/", "nutritionData": "{\"calories\": 1480, \"protein\": 105.0, \"carbs\": 1.0, \"fat\": 115.0}"},
  {"name": "Steak Frites", "category": "Steak", "description": "Classic brasserie-style pan-seared strip steak alongside double-fried golden crispy French fries.", "servings": 2, "prepTime": 20, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"8-oz New York strip steaks\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 sprigs\", \"name\": \"thyme\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1.5 lbs\", \"name\": \"russet potatoes cut into 1/4-inch fries\"}, {\"qty\": \"4 cups\", \"name\": \"neutral oil for frying\"}, {\"qty\": \"\", \"name\": \"kosher salt for fries\"}]", "instructions": "1. Parboil fries in 300°F oil for 3 minutes; drain and let cool on a sheet pan (can hold several hours). 2. Season steaks with salt and pepper. Heat 1 tbsp oil in a large skillet over high heat until smoking. 3. Add steaks; press down firmly. Cook 2-3 minutes per side until deep brown crust forms. Add butter, thyme, and garlic; baste 1-2 minutes until reaching 120°F. 4. Rest steaks on a cutting board 5 minutes while you finish the fries. 5. Heat frying oil to 350°F; fry potatoes in batches 3-5 minutes until deep golden and crispy. Drain and salt immediately. 6. Slice steaks or serve whole alongside the crispy fries. 7. Top with herb butter and serve at once.", "tags": "french, bistro, comfort-food", "source": "https://www.billyparisi.com/steak-frites-recipe-lemon-herb-butter/", "nutritionData": "{\"calories\": 1150, \"protein\": 65.0, \"carbs\": 58.0, \"fat\": 73.0}"},
  {"name": "Philly Cheesesteak", "category": "Steak", "description": "Thinly shaved ribeye with caramelized onions and melted provolone piled into a toasted hoagie roll.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ribeye steak trimmed and thinly sliced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"large sweet onion diced\"}, {\"qty\": \"8 slices\", \"name\": \"provolone cheese\"}, {\"qty\": \"4\", \"name\": \"hoagie rolls\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1\", \"name\": \"garlic clove pressed\"}, {\"qty\": \"2 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}]", "instructions": "1. Place ribeye in the freezer for 30 minutes; once firm, slice as thinly as possible. 2. Mix butter with pressed garlic; spread onto cut sides of hoagie rolls and toast on a skillet until golden. Set aside. 3. Add 1 tbsp oil to the pan over medium heat; sauté onion until caramelized, about 8-10 minutes. Season with salt; transfer to a bowl. 4. Increase heat to high; add remaining oil. Spread sliced ribeye in a single even layer; let brown 2 minutes undisturbed. 5. Season steak with salt and pepper; flip and stir in caramelized onions. Divide into 4 portions. 6. Lay 2 slices provolone over each portion; cover pan briefly to melt the cheese. 7. Spread mayo on toasted rolls; scoop cheesy steak into each roll with a spatula and serve immediately.", "tags": "sandwich, cheesesteak, comfort-food", "source": "https://natashaskitchen.com/philly-cheesesteak/", "nutritionData": "{\"calories\": 780, \"protein\": 47.0, \"carbs\": 39.0, \"fat\": 47.0}"},
  {"name": "Carne Asada Tacos", "category": "Steak", "description": "Citrus and chile marinated grilled flank steak sliced thin and served in warm corn tortillas with fresh salsa.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"flank steak or skirt steak\"}, {\"qty\": \"1/2 cup\", \"name\": \"cilantro chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"orange juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1\", \"name\": \"jalapeno seeded and minced\"}, {\"qty\": \"2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"12\", \"name\": \"corn tortillas warmed\"}]", "instructions": "1. Whisk together cilantro, olive oil, soy sauce, orange juice, lime juice, garlic, jalapeno, chili powder, cumin, and salt in a bowl. Reserve 1/4 cup; pour rest over steak in a large bag. Marinate 2-4 hours. 2. Preheat outdoor grill to high heat (450-500°F). Remove steak from marinade; pat dry and drizzle with a little olive oil. 3. Grill steak with lid closed 4-6 minutes per side for skirt steak or 7-8 minutes for flank, until 130-135°F internal. 4. Rest steak 5 minutes on a cutting board. 5. Slice thinly against the grain. 6. Serve in warm corn tortillas with pico de gallo and avocado.", "tags": "tacos, mexican, grilled", "source": "https://www.isabeleats.com/carne-asada-recipe/", "nutritionData": "{\"calories\": 750, \"protein\": 68.0, \"carbs\": 39.0, \"fat\": 36.0}"},
  {"name": "Steak and Arugula Salad", "category": "Steak", "description": "Sliced grilled sirloin over peppery arugula with shaved Parmesan and bright lemon vinaigrette.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"top sirloin steak\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"5 oz\", \"name\": \"baby arugula\"}, {\"qty\": \"4 oz\", \"name\": \"Parmesan shaved\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1\", \"name\": \"shallot minced\"}]", "instructions": "1. Pat steak dry and season generously with salt and pepper. Let sit at room temperature 20 minutes. 2. Heat 1 tbsp olive oil in a cast iron skillet over high heat until nearly smoking. 3. Sear steak 4-5 minutes per side for medium-rare. Rest 5-10 minutes then slice thinly. 4. Whisk together lemon juice, mustard, shallot, and olive oil to make vinaigrette; season with salt and pepper. 5. Toss arugula and cherry tomatoes with just enough vinaigrette to lightly coat. 6. Plate salad; arrange sliced steak on top. 7. Scatter shaved Parmesan over the salad and drizzle with remaining vinaigrette.", "tags": "salad, light, high-protein", "source": "Classic", "nutritionData": "{\"calories\": 640, \"protein\": 61.0, \"carbs\": 4.0, \"fat\": 42.0}"},
  {"name": "Flank Steak with Soy-Ginger Marinade", "category": "Steak", "description": "Overnight-marinated flank steak grilled to medium-rare with a deeply savory umami-rich glaze.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"flank steak\"}, {\"qty\": \"1/4 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice wine vinegar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2\", \"name\": \"scallions sliced for garnish\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. Whisk together soy sauce, olive oil, honey, sesame oil, garlic, ginger, rice vinegar, and red pepper flakes. 2. Place flank steak in a resealable bag; pour marinade over it. Marinate at least 4 hours or overnight in the refrigerator. 3. Remove steak from fridge 30 minutes before cooking. 4. Preheat grill to high heat. Remove steak from marinade; discard marinade. 5. Grill 5-6 minutes per side for medium-rare, basting with a little reserved marinade once. 6. Rest steak 10 minutes, then slice thinly against the grain at a diagonal. 7. Garnish with sliced scallions and sesame seeds.", "tags": "marinated, asian-inspired, weeknight", "source": "https://www.allrecipes.com/recipe/18074/marinated-flank-steak/", "nutritionData": "{\"calories\": 525, \"protein\": 47.0, \"carbs\": 11.0, \"fat\": 33.0}"},
  {"name": "Skirt Steak with Salsa Verde", "category": "Steak", "description": "Grilled skirt steak served with bright Italian herb salsa verde packed with capers and anchovies.", "servings": 2, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"skirt steak\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"flat-leaf parsley leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers drained\"}, {\"qty\": \"2\", \"name\": \"anchovy fillets\"}, {\"qty\": \"1\", \"name\": \"garlic clove\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra virgin olive oil\"}]", "instructions": "1. Make salsa verde: pulse parsley, basil, capers, anchovies, and garlic in a food processor until roughly chopped. Add lemon juice; slowly drizzle in olive oil until combined but still textured. Season with salt. 2. Pat skirt steak dry and season with salt and pepper. Let rest at room temperature 20 minutes. 3. Heat 1 tbsp oil in a cast iron skillet or grill over very high heat until smoking. 4. Sear skirt steak 2-3 minutes per side for medium-rare — it cooks fast. 5. Rest steak 5 minutes on a cutting board. 6. Slice thinly against the grain. 7. Plate and spoon salsa verde generously over the sliced steak.", "tags": "skirt-steak, herb-sauce, quick", "source": "Classic", "nutritionData": "{\"calories\": 1060, \"protein\": 60.0, \"carbs\": 2.0, \"fat\": 90.0}"},
  {"name": "Cowboy Ribeye with Herb Butter", "category": "Steak", "description": "Thick bone-in cowboy-cut ribeye grilled over charcoal with a smoky crust and melting compound butter.", "servings": 2, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"2-inch bone-in cowboy ribeye about 2 lbs\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"flat-leaf parsley minced\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"lemon zest from 1/2 lemon\"}]", "instructions": "1. Season ribeye liberally with salt and pepper; let rest at room temperature for 45 minutes. 2. Mix softened butter with chives, parsley, garlic powder, smoked paprika, and lemon zest; shape into a log in plastic wrap and refrigerate. 3. Prepare charcoal grill for two-zone fire; grill grates should be very hot. 4. Sear steak directly over coals 3-4 minutes per side until deeply charred. 5. Move to indirect heat; cook with lid closed until internal temperature reaches 125°F for medium-rare. 6. Rest steak 10 minutes loosely tented with foil. 7. Top with a generous slice of herb butter and serve.", "tags": "bone-in, charcoal, special-occasion", "source": "https://www.billyparisi.com/reverse-sear-steak/", "nutritionData": "{\"calories\": 1340, \"protein\": 94.0, \"carbs\": 1.0, \"fat\": 105.0}"},
  {"name": "Japanese Teppanyaki Sirloin", "category": "Steak", "description": "Tender sirloin seared on a hot iron griddle with garlic butter and soy sauce in Japanese style.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"8-oz sirloin steaks\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"2 cups\", \"name\": \"mixed vegetables zucchini and mushrooms\"}, {\"qty\": \"\", \"name\": \"steamed rice for serving\"}]", "instructions": "1. Pat steaks dry and season with salt and pepper. Slice into 1-inch strips if desired for faster cooking. 2. Heat a flat iron griddle or large heavy skillet over very high heat until smoking. Add oil. 3. Sear steaks or steak strips 2-3 minutes per side until browned. Remove and set aside. 4. Add butter and garlic to the griddle; cook 30 seconds until fragrant. Add vegetables and stir-fry 3-4 minutes until tender-crisp. 5. Whisk together soy sauce, mirin, sesame oil, and sugar; pour over the vegetables and toss. 6. Return steak to the griddle; toss with sauce for 30 seconds. 7. Serve immediately over steamed rice with extra soy sauce on the side.", "tags": "japanese, teppanyaki, quick", "source": "Classic", "nutritionData": "{\"calories\": 1050, \"protein\": 72.0, \"carbs\": 72.0, \"fat\": 53.0}"},
  {"name": "T-Bone Steak on the Grill", "category": "Steak", "description": "Classic grilled T-bone featuring both the strip and tenderloin sides cooked to simultaneous perfection.", "servings": 2, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"T-bone steaks about 1.25 inches thick\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 sprigs\", \"name\": \"rosemary\"}, {\"qty\": \"3\", \"name\": \"garlic cloves smashed\"}]", "instructions": "1. Season T-bone steaks on all sides with salt, pepper, and garlic powder at least 30 minutes before cooking. 2. Prepare grill for high direct heat. Brush grates with oil. 3. Place steaks on grill with the strip side toward the hotter part of the grill. 4. Cook 4-5 minutes per side, rotating 90 degrees once per side for crosshatch grill marks. 5. Check temperature in the strip side — pull at 125°F for medium-rare. 6. In a small saucepan melt butter with rosemary and garlic until fragrant. 7. Rest steaks 5-8 minutes; drizzle with garlic-rosemary butter before serving.", "tags": "t-bone, grilled, classic", "source": "Classic", "nutritionData": "{\"calories\": 920, \"protein\": 76.0, \"carbs\": 1.0, \"fat\": 70.0}"},
  {"name": "Steak Diane", "category": "Steak", "description": "Retro tableside-style seared steak with mushrooms, Worcestershire, brandy, and cream in a classic pan sauce.", "servings": 2, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"6-oz filet mignon or sirloin steaks pounded to 1/2 inch\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"1 cup\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"brandy or cognac\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 cup\", \"name\": \"beef stock\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"flat-leaf parsley chopped\"}]", "instructions": "1. Pound steaks to about 1/2-inch thickness. Season with salt and pepper. 2. Heat butter and oil in a skillet over high heat until foaming; sear steaks 2 minutes per side. Remove and rest. 3. Reduce heat to medium; cook shallots and mushrooms in the same pan 3-4 minutes until golden. 4. Remove pan from heat; add brandy. Return to heat; cook until almost evaporated, 1 minute. 5. Stir in Worcestershire sauce and Dijon mustard; add beef stock and simmer 3-4 minutes. 6. Stir in heavy cream; simmer until sauce thickens, 2-3 minutes. 7. Return steaks to pan; coat in sauce; garnish with parsley and serve immediately.", "tags": "retro, pan-sauce, date-night", "source": "https://www.billyparisi.com/delicious-classic-steak-diane-recipe/", "nutritionData": "{\"calories\": 720, \"protein\": 50.0, \"carbs\": 3.0, \"fat\": 53.0}"},
  {"name": "Porterhouse for Two", "category": "Steak", "description": "Massive bone-in porterhouse shared for two, seared in cast iron then finished in the oven with herbs.", "servings": 2, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"porterhouse steak 2 to 2.5 inches thick about 2 lbs\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4\", \"name\": \"garlic cloves smashed\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}]", "instructions": "1. Season porterhouse generously with salt and pepper on all sides. Let rest at room temperature 45 minutes. 2. Preheat oven to 400°F. Heat oil in a large oven-safe cast iron skillet over high heat until smoking. 3. Sear steak 3-4 minutes per side until deeply browned, also searing the edges. 4. Add butter, garlic, thyme, and rosemary to the pan; baste steak for 1-2 minutes. 5. Transfer pan to oven; roast until an instant-read thermometer in the strip side reads 120°F, about 8-12 minutes. 6. Remove from oven and rest 10 minutes. 7. Cut strip and tenderloin sections off the bone; slice each against the grain and reassemble around the bone to serve.", "tags": "porterhouse, sharing, special-occasion", "source": "Classic", "nutritionData": "{\"calories\": 1080, \"protein\": 93.0, \"carbs\": 0.0, \"fat\": 80.0}"},
  {"name": "Bistro-Style Entrecote", "category": "Steak", "description": "French-style pan-seared boneless ribeye with a classic shallot and red wine reduction finished with butter.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"8-oz boneless ribeye steaks\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1 cup\", \"name\": \"beef stock\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"3 tbsp\", \"name\": \"cold unsalted butter cut into cubes\"}, {\"qty\": \"1 tbsp\", \"name\": \"flat-leaf parsley chopped\"}]", "instructions": "1. Pat steaks dry and season with salt and pepper. Let rest 20 minutes at room temperature. 2. Heat oil in a heavy skillet over high heat until smoking. Sear steaks 3-4 minutes per side for medium-rare. Rest on a plate tented with foil. 3. Reduce heat to medium; add shallots to the pan and cook 2 minutes until softened. 4. Add red wine; scrape up any fond and reduce by half. 5. Add beef stock and thyme; simmer until sauce is reduced by half and slightly syrupy, about 8 minutes. 6. Remove from heat; whisk in cold butter cubes one at a time until glossy. Discard thyme. 7. Plate steaks and spoon red wine sauce over; garnish with parsley.", "tags": "french, red-wine-sauce, bistro", "source": "Classic", "nutritionData": "{\"calories\": 850, \"protein\": 54.0, \"carbs\": 2.0, \"fat\": 64.0}"},
  {"name": "Beef Bulgogi Bowl", "category": "Steak", "description": "Korean BBQ sirloin over steamed rice with pickled cucumbers and sesame — a satisfying weeknight bowl.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"beef sirloin thinly sliced\"}, {\"qty\": \"1/3 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"5\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1/2\", \"name\": \"Asian pear grated\"}, {\"qty\": \"2 tbsp\", \"name\": \"gochujang optional\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 cups\", \"name\": \"steamed rice\"}, {\"qty\": \"1 cup\", \"name\": \"sliced cucumbers\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. Whisk together soy sauce, sesame oil, brown sugar, garlic, ginger, grated pear, and gochujang if using. 2. Toss beef slices in marinade; set aside 15-20 minutes or up to overnight. 3. Heat vegetable oil in a wide skillet over high heat until smoking. 4. Cook beef in batches in a single layer, 2-3 minutes per batch, until caramelized; do not crowd the pan. 5. Toss sliced cucumbers with rice vinegar, sugar, and salt; rest 15 minutes for quick pickles. 6. Serve beef over steamed rice with pickled cucumbers and scallions. 7. Finish with sesame seeds and a drizzle of sesame oil.", "tags": "korean, bowls, weeknight", "source": "https://mykoreankitchen.com/bulgogi-korean-bbq-beef/", "nutritionData": "{\"calories\": 750, \"protein\": 56.0, \"carbs\": 68.0, \"fat\": 27.0}"},
  {"name": "Garlic Butter Steak Bites", "category": "Steak", "description": "Tender cubed sirloin seared in a screaming hot skillet and tossed in a garlic and herb butter sauce.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"sirloin steak cut into 1-inch cubes\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"5\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"flat-leaf parsley chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}]", "instructions": "1. Pat steak cubes dry and season with salt, pepper, and garlic powder. 2. Heat a large heavy skillet over the highest heat until nearly smoking; add oil. 3. Add steak cubes in a single layer, working in batches to avoid crowding; sear 1-2 minutes per side until deep brown crust forms. Transfer to a plate. 4. Reduce heat to medium; add butter and minced garlic; cook 1 minute until fragrant and golden. 5. Add Worcestershire sauce and fresh thyme; stir to combine. 6. Return steak bites to the pan; toss to coat in garlic butter. Cook 30 seconds more. 7. Garnish with parsley and serve immediately with crusty bread or over mashed potatoes.", "tags": "quick, garlic-butter, easy", "source": "https://www.thespruceeats.com/garlic-butter-steak-bites-5176427", "nutritionData": "{\"calories\": 515, \"protein\": 51.0, \"carbs\": 1.0, \"fat\": 35.0}"},
  {"name": "Tri-Tip with Santa Maria Rub", "category": "Steak", "description": "California barbecue classic: roasted tri-tip with a bold garlic-herb dry rub and smoky char.", "servings": 6, "prepTime": 15, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"beef tri-tip roast\"}, {\"qty\": \"2 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}]", "instructions": "1. Mix salt, pepper, garlic powder, onion powder, smoked paprika, oregano, and thyme to make the Santa Maria rub. Coat the tri-tip on all sides; let rest at room temperature 30 minutes or refrigerate up to overnight. 2. Prepare grill for two-zone fire; heat one side to high and leave the other off. 3. Sear tri-tip over direct heat 4-5 minutes per side until charred. 4. Move to indirect heat and cook, lid closed, until internal temperature reaches 130°F for medium-rare, about 25-35 minutes. 5. Rest on a cutting board 10 minutes. 6. Identify the grain direction (which changes across the tri-tip); slice against the grain into thin pieces. 7. Serve with grilled bread and salsa.", "tags": "california, bbq, tri-tip", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 52.0, \"carbs\": 1.0, \"fat\": 25.0}"},
  {"name": "Flank Steak with Red Wine Marinade", "category": "Steak", "description": "Tender marinated flank steak infused with red wine, herbs, and garlic for an elegant weeknight dinner.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"flank steak\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil for searing\"}]", "instructions": "1. Combine red wine, olive oil, balsamic vinegar, garlic, rosemary, thyme, salt, and pepper in a baking dish. Add flank steak; turn to coat. Marinate at least 2 hours or overnight in the refrigerator. 2. Remove steak from marinade; pat very dry with paper towels. Discard marinade. 3. Heat a cast iron skillet or grill pan over very high heat until smoking; add oil. 4. Sear steak 4-6 minutes per side until nicely browned (125°F internal for medium-rare). 5. Transfer to a cutting board; rest 10 minutes. 6. Slice thinly against the grain at a sharp diagonal. 7. Serve with roasted vegetables or a simple green salad.", "tags": "marinated, red-wine, elegant", "source": "Classic", "nutritionData": "{\"calories\": 535, \"protein\": 47.0, \"carbs\": 2.0, \"fat\": 38.0}"},
  {"name": "Pepper-Crusted Sirloin with Blue Cheese Butter", "category": "Steak", "description": "Coarsely crusted sirloin steaks topped with rich and pungent blue cheese compound butter for bold flavor.", "servings": 2, "prepTime": 20, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"8-oz sirloin steaks\"}, {\"qty\": \"2 tbsp\", \"name\": \"coarsely cracked black pepper\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3 oz\", \"name\": \"blue cheese crumbled\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives minced\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1\", \"name\": \"small garlic clove minced\"}]", "instructions": "1. Mix softened butter with blue cheese, chives, Worcestershire sauce, and garlic until well combined. Roll into a log in plastic wrap; refrigerate at least 30 minutes. 2. Pat steaks dry; press cracked pepper firmly onto both sides of each steak. Season with salt. 3. Heat oil in a cast iron skillet over high heat until smoking. 4. Sear steaks 3-4 minutes per side until 120-125°F internal for medium-rare. 5. Rest steaks 5 minutes on a cutting board. 6. Top each steak with a thick slice of blue cheese butter immediately before serving. 7. Let the butter melt over the hot steak and serve with roasted potatoes.", "tags": "blue-cheese, pepper-crust, bold", "source": "Classic", "nutritionData": "{\"calories\": 930, \"protein\": 76.0, \"carbs\": 1.0, \"fat\": 71.0}"},
  {"name": "Teriyaki Flank Steak", "category": "Steak", "description": "Flank steak marinated in homemade teriyaki sauce then grilled and glazed until caramelized and sticky.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"flank steak\"}, {\"qty\": \"1/2 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"mirin\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"sake or dry sherry\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch mixed with 1 tbsp water\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. Combine soy sauce, mirin, brown sugar, sake, garlic, and ginger in a saucepan; bring to a simmer. Stir in cornstarch slurry; cook 2 minutes until thickened. Cool completely. 2. Reserve 1/4 cup teriyaki sauce; pour the rest over the flank steak in a zip-top bag. Marinate 2-4 hours in the refrigerator. 3. Remove steak from marinade; discard marinade. Pat lightly dry. 4. Grill or pan-sear steak over high heat 5-6 minutes per side for medium-rare, brushing with reserved sauce in the last 2 minutes to caramelize. 5. Rest steak 5-10 minutes. 6. Slice thinly against the grain. 7. Serve over steamed rice, garnished with scallions and sesame seeds.", "tags": "teriyaki, japanese-inspired, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 475, \"protein\": 51.0, \"carbs\": 15.0, \"fat\": 24.0}"},
  {"name": "Steak Salad with Shallot Vinaigrette", "category": "Steak", "description": "Seared sirloin over mixed greens with blue cheese, cherry tomatoes, and a tangy shallot vinaigrette.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"sirloin steak\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"6 oz\", \"name\": \"mixed greens\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/2\", \"name\": \"red onion thinly sliced\"}, {\"qty\": \"3 oz\", \"name\": \"blue cheese crumbled\"}, {\"qty\": \"2 tbsp\", \"name\": \"shallot minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra virgin olive oil\"}]", "instructions": "1. Season sirloin with salt and pepper. Heat olive oil in a cast iron skillet over high heat until smoking; sear steak 4-5 minutes per side for medium-rare. Rest 8 minutes then slice thinly. 2. Whisk shallot, red wine vinegar, Dijon, and a pinch of sugar together; slowly whisk in olive oil to emulsify. Season with salt and pepper. 3. In a large bowl toss greens, cherry tomatoes, and red onion with half the vinaigrette. 4. Divide dressed salad among 4 plates. 5. Fan sliced steak over each salad. 6. Crumble blue cheese over the top. 7. Drizzle with remaining vinaigrette and serve immediately.", "tags": "salad, high-protein, light", "source": "https://www.epicurious.com/recipes/food/views/steak-salad-with-shallot-vinaigrette", "nutritionData": "{\"calories\": 715, \"protein\": 55.0, \"carbs\": 3.0, \"fat\": 54.0}"},
  {"name": "Steak with Compound Herb Butter", "category": "Steak", "description": "Simply seasoned grilled strip steak finished with a luxurious garlic and fresh herb compound butter.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"10-oz New York strip steaks\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1 pinch\", \"name\": \"cayenne\"}]", "instructions": "1. Mix softened butter with garlic, parsley, chives, thyme, lemon zest, and cayenne until smooth. Roll into a log in plastic wrap; refrigerate until firm. 2. Season strip steaks generously with salt and pepper on all sides. Let rest 30 minutes at room temperature. 3. Heat oil in a cast iron skillet over high heat until smoking. 4. Sear steaks 3-4 minutes per side without moving until deeply browned. 5. Stand steaks on their fat caps with tongs; render the fat 1-2 minutes until golden. 6. Rest steaks 5 minutes. 7. Top each steak with a generous slice of compound butter and serve as butter melts over the hot steak.", "tags": "classic, compound-butter, simple", "source": "Classic", "nutritionData": "{\"calories\": 1090, \"protein\": 73.0, \"carbs\": 1.0, \"fat\": 89.0}"},
  {"name": "Almond Butter Tofu Stir-Fry", "category": "Vegan", "description": "Baked tofu and crisp vegetables tossed in a spicy-sweet almond butter sauce over rice.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"14 oz\", \"name\": \"extra-firm tofu pressed and cubed\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"tamari\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"3 tbsp\", \"name\": \"almond butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"chili garlic sauce\"}, {\"qty\": \"2 cups\", \"name\": \"green beans trimmed\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"2 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}]", "instructions": "1. Preheat oven to 400°F and line a baking sheet with parchment paper. 2. Toss tofu cubes with 1 tbsp tamari and spread on sheet; bake 25-30 minutes until golden and firm. 3. Whisk together almond butter, remaining tamari, maple syrup, lime juice, sesame oil, and chili garlic sauce to make sauce. 4. Marinate baked tofu in half the sauce for 5 minutes. 5. Heat a skillet over medium-high and sear tofu until caramelized, about 4 minutes; remove and set aside. 6. Add green beans and bell pepper to the same skillet with remaining sauce; cover and cook 4-5 minutes until tender-crisp. 7. Return tofu to the pan and toss everything together; serve over rice and garnish with sesame seeds.", "tags": "vegan, high-protein, gluten-free option", "source": "https://minimalistbaker.com/almond-butter-tofu-stir-fry/", "nutritionData": "{\"calories\": 418, \"protein\": 24.0, \"carbs\": 38.0, \"fat\": 20.0}"},
  {"name": "Easy Vegan Ramen", "category": "Vegan", "description": "Savory mushroom miso broth with ramen noodles crispy tofu and miso-glazed vegetables.", "servings": 4, "prepTime": 15, "cookTime": 75, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic roughly chopped\"}, {\"qty\": \"1\", \"name\": \"3-inch piece ginger peeled and diced\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion coarsely chopped\"}, {\"qty\": \"6 cups\", \"name\": \"vegetable stock\"}, {\"qty\": \"2 tbsp\", \"name\": \"tamari\"}, {\"qty\": \"0.5 oz\", \"name\": \"dehydrated shiitake mushrooms\"}, {\"qty\": \"1 tbsp\", \"name\": \"white miso paste\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"8 oz\", \"name\": \"ramen noodles\"}, {\"qty\": \"10 oz\", \"name\": \"extra-firm tofu cubed\"}, {\"qty\": \"2\", \"name\": \"baby bok choy halved\"}, {\"qty\": \"2\", \"name\": \"stalks green onion chopped\"}]", "instructions": "1. Heat a large pot over medium-high heat; add oil, garlic, ginger, and onion and sauté 5-8 minutes until browned at edges. 2. Add 1 cup broth to deglaze, scraping up browned bits. 3. Add remaining broth, tamari, and dried mushrooms; bring to a simmer, cover, and cook on low for at least 1 hour. 4. Stir in miso paste and sesame oil; taste and adjust seasoning. 5. Pan-fry tofu cubes in a little oil until golden on all sides, about 6 minutes; set aside. 6. Cook ramen noodles according to package directions; drain and divide among bowls. 7. Strain broth and ladle over noodles; top with tofu, bok choy, and green onion.", "tags": "vegan, comforting, umami", "source": "https://minimalistbaker.com/easy-vegan-ramen/", "nutritionData": "{\"calories\": 411, \"protein\": 22.0, \"carbs\": 56.0, \"fat\": 12.0}"},
  {"name": "Spicy Red Lentil Curry", "category": "Vegan", "description": "Fragrant red lentils simmered in coconut milk and red curry paste for a bold weeknight dinner.", "servings": 3, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"coconut oil\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"minced ginger\"}, {\"qty\": \"1/2 cup\", \"name\": \"diced carrots\"}, {\"qty\": \"3 tbsp\", \"name\": \"red curry paste\"}, {\"qty\": \"6 oz\", \"name\": \"tomato paste\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"water\"}, {\"qty\": \"2/3 cup\", \"name\": \"dry red lentils rinsed\"}, {\"qty\": \"1 tbsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground turmeric\"}, {\"qty\": \"1/3 cup\", \"name\": \"light coconut milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Rinse lentils thoroughly and set aside. 2. Heat a large rimmed skillet over medium heat; add coconut oil, garlic, ginger, and carrots and sauté for 2 minutes. 3. Add curry paste and sauté for 2 more minutes stirring frequently. 4. Add tomato paste, broth, and water; stir to combine. 5. Add lentils, coconut sugar, and turmeric; stir and bring to a simmer. 6. Reduce heat to medium-low and simmer uncovered for 20 minutes until lentils are tender, stirring often. 7. Stir in coconut milk, taste and adjust seasoning, and serve garnished with cilantro.", "tags": "vegan, gluten-free, quick", "source": "https://minimalistbaker.com/spicy-red-lentil-curry/", "nutritionData": "{\"calories\": 356, \"protein\": 11.0, \"carbs\": 38.0, \"fat\": 13.0}"},
  {"name": "Easy Grillable Veggie Burgers", "category": "Vegan", "description": "Hearty black bean and walnut patties seasoned with smoked spices and perfect for grilling.", "servings": 5, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"cooked brown rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"raw walnuts\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion diced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"1\", \"name\": \"15-oz can black beans drained and dried\"}, {\"qty\": \"1/4 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"BBQ sauce plus more if needed\"}, {\"qty\": \"5\", \"name\": \"burger buns\"}]", "instructions": "1. Toast walnuts in a skillet over medium heat 5-7 minutes until golden; let cool. 2. Sauté onion in oil with salt and pepper until soft and translucent, 3-4 minutes; set aside. 3. Blend cooled walnuts with chili powder, cumin, paprika, salt, pepper, and coconut sugar in a food processor until a fine meal forms. 4. Mash black beans in a large bowl leaving some whole for texture. 5. Add rice, walnut spice mix, sautéed onion, panko, and BBQ sauce; mix until a moldable dough forms, adding more panko if too wet. 6. Form into 5 patties using a 1/2-cup measure; press to about 3/4-inch thick. 7. Cook on an oiled grill or skillet over medium heat 3-4 minutes per side until well browned; serve on toasted buns.", "tags": "vegan, grillable, make-ahead", "source": "https://minimalistbaker.com/easy-grillable-veggie-burgers/", "nutritionData": "{\"calories\": 392, \"protein\": 11.0, \"carbs\": 51.0, \"fat\": 14.0}"},
  {"name": "Roasted Buddha Bowl", "category": "Vegan", "description": "Roasted broccoli cauliflower and crispy chickpeas drizzled with a creamy cashew-nutritional yeast dressing.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large head broccoli chopped\"}, {\"qty\": \"1\", \"name\": \"large head cauliflower chopped\"}, {\"qty\": \"1\", \"name\": \"15-oz can chickpeas drained and rinsed\"}, {\"qty\": \"1 tbsp\", \"name\": \"plus 1 tsp olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1 cup\", \"name\": \"cooked quinoa\"}, {\"qty\": \"1/2 cup\", \"name\": \"raw cashews soaked 8 hours\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"1\", \"name\": \"large garlic clove\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"nutritional yeast\"}, {\"qty\": \"6 tbsp\", \"name\": \"water\"}]", "instructions": "1. Soak cashews in water overnight or for at least 45 minutes in boiling water; drain. 2. Preheat oven to 400°F and line two large baking sheets with parchment paper. 3. Toss broccoli and cauliflower with 1 tbsp oil, salt, and pepper; spread on one sheet and roast. 4. Pat chickpeas dry, toss with 1 tsp oil and salt, spread on second sheet, and roast both for 25-30 minutes until golden. 5. Blend all dressing ingredients on high until smooth, adding more water to thin as needed. 6. Divide cooked quinoa into bowls; top with roasted vegetables and chickpeas. 7. Drizzle with cashew dressing and season to taste.", "tags": "vegan, gluten-free, meal-prep", "source": "https://ohsheglows.com/roasted-buddha-bowl/", "nutritionData": "{\"calories\": 427, \"protein\": 20.0, \"carbs\": 53.0, \"fat\": 17.0}"},
  {"name": "Homemade Vegetarian Chili", "category": "Vegan", "description": "A thick hearty chili loaded with black beans pinto beans and vegetables with smoky spices.", "servings": 6, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1\", \"name\": \"medium red onion chopped\"}, {\"qty\": \"1\", \"name\": \"large red bell pepper chopped\"}, {\"qty\": \"2\", \"name\": \"medium carrots chopped\"}, {\"qty\": \"2\", \"name\": \"ribs celery chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt divided\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1.5 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"28 oz\", \"name\": \"can diced tomatoes with juices\"}, {\"qty\": \"2\", \"name\": \"15-oz cans black beans rinsed and drained\"}, {\"qty\": \"1\", \"name\": \"15-oz can pinto beans rinsed and drained\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}]", "instructions": "1. Warm olive oil in a large Dutch oven over medium heat; add onion, bell pepper, carrots, celery, and 1/4 tsp salt and cook 7-10 minutes until softened. 2. Add garlic, chili powder, cumin, paprika, and oregano and cook 1 minute until fragrant. 3. Add diced tomatoes with juices, black and pinto beans, broth, and bay leaf; stir and bring to a simmer. 4. Cook uncovered at a gentle simmer for 30 minutes, stirring occasionally. 5. Remove bay leaf and blend 1.5 cups of chili until smooth; return to pot and stir. 6. Stir in cilantro and vinegar to taste; season with remaining salt. 7. Serve with desired garnishes such as avocado, tortilla chips, or cilantro.", "tags": "vegan, gluten-free, freezer-friendly", "source": "https://cookieandkate.com/vegetarian-chili-recipe/", "nutritionData": "{\"calories\": 261, \"protein\": 11.0, \"carbs\": 40.0, \"fat\": 5.0}"},
  {"name": "30-Minute Cashew Alfredo", "category": "Vegan", "description": "Silky cashew-based Alfredo sauce tossed with pasta for a rich and indulgent vegan dinner.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.25 cups\", \"name\": \"raw cashews soaked 20 minutes in hot water\"}, {\"qty\": \"1 tbsp\", \"name\": \"arrowroot starch\"}, {\"qty\": \"3 tbsp\", \"name\": \"nutritional yeast\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic crushed\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegan parmesan\"}, {\"qty\": \"1\", \"name\": \"to 2 cups unsweetened plain almond milk\"}, {\"qty\": \"10 oz\", \"name\": \"pasta of choice\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Soak cashews in very hot water for 20 minutes; drain. 2. Add drained cashews, arrowroot starch, nutritional yeast, garlic, salt, vegan parmesan, and 1 cup almond milk to a high-speed blender; blend until completely smooth. 3. Transfer to a rimmed skillet and cook over medium-low heat for 5 minutes, whisking frequently until thickened and bubbling. 4. Add more almond milk as needed to reach a pourable sauce consistency. 5. Cook pasta according to package directions; drain. 6. Toss pasta with cashew Alfredo sauce until well coated. 7. Serve immediately garnished with parsley and additional vegan parmesan.", "tags": "vegan, quick, nut-based", "source": "Classic", "nutritionData": "{\"calories\": 534, \"protein\": 18.0, \"carbs\": 71.0, \"fat\": 21.0}"},
  {"name": "Easy Vegan Jackfruit Tacos", "category": "Vegan", "description": "Pulled jackfruit seasoned with smoky spices and served in warm tortillas with fresh toppings.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"20-oz cans green jackfruit in water drained rinsed and chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"1\", \"name\": \"yellow onion sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"agave\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lime\"}, {\"qty\": \"2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"8\", \"name\": \"small tortillas\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1/4\", \"name\": \"red onion thinly sliced\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Heat oil in a large skillet over medium-high heat; sauté onion and garlic for 5 minutes until softened. 2. Add chopped jackfruit, broth, agave, lime juice, chili powder, paprika, and salt; stir to combine. 3. Cover and simmer on medium-low heat for 5 minutes until jackfruit softens. 4. Use a potato masher to shred the jackfruit until it has a pulled texture. 5. If mixture is too wet, cook uncovered a few minutes more to reduce liquid. 6. Warm tortillas in a dry skillet or directly over a flame until pliable. 7. Fill tortillas with jackfruit and top with sliced avocado, red onion, and cilantro.", "tags": "vegan, gluten-free option, taco-night", "source": "https://itdoesnttastelikechicken.com/easy-vegan-jackfruit-tacos/", "nutritionData": "{\"calories\": 351, \"protein\": 6.0, \"carbs\": 57.0, \"fat\": 12.0}"},
  {"name": "Vegan Mac and Cheese", "category": "Vegan", "description": "Baked pasta smothered in a creamy cashew and vegetable cheese sauce topped with crispy breadcrumbs.", "servings": 5, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"300 g\", \"name\": \"dry macaroni or rotini\"}, {\"qty\": \"1/2\", \"name\": \"medium potato peeled and chopped\"}, {\"qty\": \"1/2\", \"name\": \"large carrot peeled and chopped\"}, {\"qty\": \"1/2\", \"name\": \"small onion peeled and chopped\"}, {\"qty\": \"1.5 cups\", \"name\": \"raw cashews\"}, {\"qty\": \"1 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"6 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"3 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"nutritional yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"1 slice\", \"name\": \"bread processed to crumbs\"}, {\"qty\": \"\", \"name\": \"paprika for garnish\"}]", "instructions": "1. Preheat oven to 350°F and lightly grease a casserole dish. 2. Boil potato, carrot, and onion in a pot until tender, about 15 minutes; drain and reserve. 3. Process cashews in a food processor until fine crumbs form; add almond milk, garlic, lemon juice, salt, nutritional yeast, pepper, and mustard and blend until smooth. 4. Add cooked vegetables to the food processor and blend the cheese sauce until completely smooth. 5. Cook pasta according to package directions; drain and rinse with cold water. 6. Mix pasta with cheese sauce in a large bowl; scoop into casserole dish and top with breadcrumbs and paprika. 7. Bake at 350°F for 30 minutes; cool 10 minutes before serving.", "tags": "vegan, comfort-food, baked", "source": "https://ohsheglows.com/vegan-mac-n-cheese/", "nutritionData": "{\"calories\": 517, \"protein\": 16.0, \"carbs\": 68.0, \"fat\": 20.0}"},
  {"name": "Creamy Vegan Pink Pasta", "category": "Vegan", "description": "Penne in a luscious tomato-cashew cream sauce with a silky rose-pink hue and fresh basil.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"raw cashews\"}, {\"qty\": \"12 oz\", \"name\": \"penne pasta\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"diced yellow onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"15 oz\", \"name\": \"can crushed tomatoes\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"3/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"nutritional yeast\"}, {\"qty\": \"1 cup\", \"name\": \"water\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Cover cashews with water and soak while you prepare the sauce. 2. Cook pasta in well-salted boiling water to al dente; reserve 1/2 cup pasta water and drain. 3. Heat olive oil in a large skillet over medium heat; sauté onion 4-5 minutes until tender. 4. Add garlic and red pepper flakes and cook 30 seconds until fragrant. 5. Add crushed tomatoes, tomato paste, and salt; simmer covered on low for 10 minutes. 6. Drain cashews and blend with nutritional yeast and 1 cup water until completely smooth; stir into tomato sauce. 7. Add pasta and reserved pasta water until sauce is thick and pourable; garnish with basil.", "tags": "vegan, quick, date-night", "source": "Classic", "nutritionData": "{\"calories\": 571, \"protein\": 18.0, \"carbs\": 82.0, \"fat\": 20.0}"},
  {"name": "Summer Glow Buddha Bowl", "category": "Vegan", "description": "A vibrant quinoa bowl with sautéed summer vegetables spiralized beets and a lemon-Dijon vinaigrette.", "servings": 4, "prepTime": 25, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"uncooked quinoa\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cups\", \"name\": \"fresh green beans trimmed\"}, {\"qty\": \"2 cups\", \"name\": \"snap peas trimmed\"}, {\"qty\": \"2 cups\", \"name\": \"yellow zucchini sliced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"2 cups\", \"name\": \"fresh baby spinach\"}, {\"qty\": \"1\", \"name\": \"large carrot spiralized\"}, {\"qty\": \"1\", \"name\": \"medium beet peeled and spiralized\"}, {\"qty\": \"2\", \"name\": \"large avocados sliced\"}, {\"qty\": \"3/4 cup\", \"name\": \"toasted pepita seeds\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1\", \"name\": \"garlic clove minced\"}, {\"qty\": \"2 tsp\", \"name\": \"maple syrup\"}, {\"qty\": \"7 tbsp\", \"name\": \"extra-virgin olive oil\"}]", "instructions": "1. Cook quinoa in 2.25 cups water: bring to a boil, reduce heat, cover, and simmer 13-16 minutes until absorbed; fluff and season. 2. Shake together vinegar, lemon juice, Dijon, garlic, maple syrup, salt, pepper, and olive oil in a mason jar until emulsified; set aside. 3. Sauté green beans, snap peas, and zucchini in 2 tbsp olive oil over medium-high heat for about 10 minutes until tender-crisp. 4. Stir spinach into the skillet and cook until wilted, 2 minutes; remove from heat. 5. Add cooked quinoa to the skillet and toss to combine; warm through. 6. Portion quinoa-veggie mixture into large shallow bowls. 7. Top with carrot, beet, avocado, and pepitas; drizzle generously with vinaigrette.", "tags": "vegan, gluten-free, grain-bowl", "source": "https://ohsheglows.com/summer-glow-buddha-bowl-news/", "nutritionData": "{\"calories\": 902, \"protein\": 21.0, \"carbs\": 72.0, \"fat\": 61.0}"},
  {"name": "Marinated Peanut Tempeh", "category": "Vegan", "description": "Crispy oven-baked tempeh marinated in a spicy-sweet peanut and tamari sauce.", "servings": 2, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"tempeh\"}, {\"qty\": \"1\", \"name\": \"bird's eye chili minced\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"creamy peanut butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"gluten-free tamari\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"2 cups\", \"name\": \"cooked rice for serving\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Steam tempeh in a skillet with 1 inch of water over medium heat for 10-12 minutes flipping once; rinse, pat dry, and cut into small triangles. 2. Whisk together chili, sesame oil, peanut butter, tamari, lime juice, and maple syrup to make marinade. 3. Add tempeh to marinade and toss to coat; refrigerate at least 2 hours or up to 24 hours. 4. Preheat oven to 375°F and line a baking sheet with parchment paper. 5. Arrange tempeh on baking sheet and bake 22-30 minutes until caramelized and deep golden brown. 6. Brush with any remaining marinade immediately after removing from oven. 7. Serve over rice garnished with cilantro.", "tags": "vegan, gluten-free, high-protein", "source": "https://minimalistbaker.com/marinated-peanut-tempeh-7-ingredients/", "nutritionData": "{\"calories\": 707, \"protein\": 31.0, \"carbs\": 81.0, \"fat\": 31.0}"},
  {"name": "Easy 1-Pot Tikka Masala", "category": "Vegan", "description": "Warming chickpea tikka masala simmered in a spiced tomato-coconut sauce ready in one pot.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"sea salt divided\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"minced ginger\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1\", \"name\": \"green chili minced\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red chili flake\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2\", \"name\": \"15-oz cans diced tomatoes\"}, {\"qty\": \"2\", \"name\": \"15-oz cans chickpeas drained\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"cooked rice for serving\"}]", "instructions": "1. Heat a large pot over medium heat; add oil, onion, cumin, and 1/3 tsp salt and sauté 2-3 minutes. 2. Add garlic, ginger, bell pepper, and green chili; sauté 2-3 minutes more. 3. Add coriander, chili flake, turmeric, and paprika; stir and cook 3 minutes. 4. Add diced tomatoes, chickpeas, garam masala, coconut sugar, and remaining salt; stir to combine. 5. Bring to a rolling simmer, then reduce heat and cook uncovered 15-20 minutes until thick and stew-like. 6. Stir in coconut milk and simmer 5 more minutes; taste and adjust seasoning. 7. Serve over rice garnished with fresh cilantro.", "tags": "vegan, gluten-free, one-pot", "source": "https://minimalistbaker.com/easy-1-pot-tikka-masala/", "nutritionData": "{\"calories\": 483, \"protein\": 16.0, \"carbs\": 72.0, \"fat\": 13.0}"},
  {"name": "Sesame Tempeh Bowls", "category": "Vegan", "description": "Sticky sesame-glazed tempeh over jasmine rice with steamed broccoli for a quick meal-prep bowl.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"8 oz\", \"name\": \"tempeh\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"4 cups\", \"name\": \"cooked jasmine rice\"}, {\"qty\": \"1 lb\", \"name\": \"frozen broccoli florets thawed\"}]", "instructions": "1. Whisk together soy sauce, water, sesame oil, brown sugar, rice vinegar, ginger, garlic, sesame seeds, and cornstarch until smooth; set sauce aside. 2. Cut tempeh into 8 squares then slice each diagonally into thin triangles. 3. Place tempeh in a large skillet with 1/2 cup water; simmer over medium-high heat until all water evaporates, flipping a few times, about 5-8 minutes. 4. Reduce heat to medium and pour in sesame sauce; stir and cook 1-2 minutes until sauce thickens and coats the tempeh. 5. Remove from heat immediately to prevent over-thickening. 6. Divide rice into four bowls; top with sesame tempeh, broccoli, and green onion. 7. Serve warm; great for meal prep stored in the fridge up to 4 days.", "tags": "vegan, meal-prep, high-protein", "source": "https://www.budgetbytes.com/sesame-tempeh-bowls/", "nutritionData": "{\"calories\": 435, \"protein\": 20.0, \"carbs\": 69.0, \"fat\": 11.0}"},
  {"name": "Vegan Lentil Stew", "category": "Vegan", "description": "A hearty one-pot lentil and potato stew with rosemary thyme and Dijon for a comforting meal.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"4\", \"name\": \"medium carrots chopped\"}, {\"qty\": \"4\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"2 lbs\", \"name\": \"potatoes cubed\"}, {\"qty\": \"1 cup\", \"name\": \"brown lentils\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"6 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas\"}]", "instructions": "1. Sauté onion and garlic in olive oil in a large pot over medium heat until softened. 2. Add celery and carrots and continue to cook a few minutes more while stirring. 3. Add potatoes, lentils, rosemary, thyme, Dijon, soy sauce, brown sugar, and vegetable broth; stir to combine. 4. Bring to a boil, then reduce heat, cover, and simmer on low for 30 minutes stirring occasionally. 5. Toward the end of simmering, mash some of the potatoes as you stir to thicken the stew. 6. Stir in frozen peas and cook until heated through. 7. Taste and adjust seasoning with salt if needed; serve hot.", "tags": "vegan, gluten-free option, budget-friendly", "source": "Classic", "nutritionData": "{\"calories\": 332, \"protein\": 14.0, \"carbs\": 57.0, \"fat\": 5.0}"},
  {"name": "1-Pot Black Bean Soup", "category": "Vegan", "description": "Smoky chipotle black bean soup with vegan dark chocolate for depth ready in under 30 minutes.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"diced white onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"15-oz cans black beans slightly drained\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1.5 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"\", \"name\": \"1-2 chipotle peppers in adobo\"}, {\"qty\": \"3 tbsp\", \"name\": \"chopped vegan dark chocolate\"}, {\"qty\": \"\", \"name\": \"lime wedges and avocado for serving\"}]", "instructions": "1. Heat a large pot over medium heat; add oil, onion, and garlic with a pinch each of salt and pepper and sauté 4-5 minutes. 2. Add black beans, broth, cumin, chili powder, coriander, chipotle peppers, and dark chocolate and stir to combine. 3. Bring to a simmer and cook uncovered on low for 15-20 minutes letting flavors develop. 4. Taste and adjust seasoning adding more chipotle for heat or cumin for smokiness. 5. Using an immersion blender, partially blend the soup for a creamier texture while leaving some beans whole. 6. Serve in bowls topped with fresh lime juice, avocado, and cilantro. 7. Store in the fridge up to 5-7 days or freeze up to 1 month.", "tags": "vegan, gluten-free, quick", "source": "https://minimalistbaker.com/easy-1-pot-black-bean-soup/", "nutritionData": "{\"calories\": 341, \"protein\": 11.0, \"carbs\": 43.0, \"fat\": 15.0}"},
  {"name": "Chickpea Shakshuka", "category": "Vegan", "description": "Spiced tomato sauce studded with chickpeas and fragrant warm spices for a satisfying one-pan meal.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"diced white onion\"}, {\"qty\": \"1/2\", \"name\": \"red bell pepper chopped\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"28 oz\", \"name\": \"can crushed tomatoes\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"\", \"name\": \"pinch of cayenne\"}, {\"qty\": \"1\", \"name\": \"15-oz can chickpeas drained\"}, {\"qty\": \"\", \"name\": \"fresh lemon juice and cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"crusty bread for serving\"}]", "instructions": "1. Heat a large rimmed skillet over medium heat; add oil, onion, bell pepper, and garlic and sauté 4-5 minutes until soft. 2. Add crushed tomatoes, tomato paste, coconut sugar, salt, paprika, cumin, chili powder, cinnamon, and cayenne; stir to combine. 3. Bring to a simmer and cook 2-3 minutes stirring frequently. 4. Add chickpeas and stir to incorporate; reduce heat to medium-low. 5. Simmer uncovered for 15-20 minutes until sauce thickens and flavors meld. 6. Taste and adjust seasoning as needed. 7. Serve directly from the skillet garnished with lemon juice and cilantro alongside crusty bread.", "tags": "vegan, gluten-free, one-pan", "source": "https://minimalistbaker.com/1-pot-chickpea-shakshuka/", "nutritionData": "{\"calories\": 345, \"protein\": 14.0, \"carbs\": 54.0, \"fat\": 6.0}"},
  {"name": "Sweet Potato Black Bean Tacos", "category": "Vegan", "description": "Roasted sweet potato and spiced black beans in corn tortillas with a creamy avocado-pepita dip.", "servings": 5, "prepTime": 15, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"sweet potatoes peeled and cut into 1-inch chunks\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"small onion finely chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"2\", \"name\": \"15-oz cans black beans rinsed and drained\"}, {\"qty\": \"1/3 cup\", \"name\": \"water\"}, {\"qty\": \"2\", \"name\": \"avocados pitted\"}, {\"qty\": \"1 cup\", \"name\": \"cilantro leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"pepitas toasted\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o seeded\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"\", \"name\": \"8-10 small corn tortillas\"}]", "instructions": "1. Preheat oven to 425°F; toss sweet potatoes with 2 tbsp olive oil, cayenne, and salt; roast on a parchment-lined sheet 30-40 minutes tossing halfway until caramelized. 2. Sauté onion in 1 tbsp oil with a pinch of salt 5-8 minutes; add cumin and chili powder and cook 30 seconds. 3. Add black beans and water; cover and simmer 5 minutes then mash half the beans; season with lime juice, salt, and pepper. 4. Toast pepitas in a dry skillet 5 minutes until fragrant; set aside a few for garnish. 5. Blend avocados, cilantro, jalapeño, garlic, lime juice, water, and salt until smooth; fold in most of the pepitas. 6. Warm tortillas in a skillet or over a flame. 7. Assemble tacos with black beans, sweet potatoes, and avocado-pepita dip; garnish with reserved pepitas.", "tags": "vegan, gluten-free, taco-night", "source": "https://cookieandkate.com/sweet-potato-black-bean-tacos/", "nutritionData": "{\"calories\": 684, \"protein\": 19.0, \"carbs\": 91.0, \"fat\": 28.0}"},
  {"name": "Blissed-Out Thai Salad with Peanut Tempeh", "category": "Vegan", "description": "A rainbow noodle salad with crunchy vegetables marinated peanut tempeh and a bold peanut dressing.", "servings": 4, "prepTime": 30, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6 oz\", \"name\": \"rice vermicelli noodles\"}, {\"qty\": \"2\", \"name\": \"medium carrots ribboned\"}, {\"qty\": \"2\", \"name\": \"stalks green onion finely chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped cilantro\"}, {\"qty\": \"2 tbsp\", \"name\": \"chopped mint\"}, {\"qty\": \"1 cup\", \"name\": \"baby spinach chopped\"}, {\"qty\": \"1 cup\", \"name\": \"red cabbage thinly sliced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper thinly sliced\"}, {\"qty\": \"8 oz\", \"name\": \"marinated peanut tempeh baked\"}, {\"qty\": \"1/3 cup\", \"name\": \"creamy peanut butter\"}, {\"qty\": \"3 tbsp\", \"name\": \"gluten-free tamari\"}, {\"qty\": \"3 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"1 tsp\", \"name\": \"chili garlic sauce\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"1/4 cup\", \"name\": \"water to thin\"}]", "instructions": "1. Cook rice noodles according to package instructions; rinse, drain, and set aside to cool. 2. Combine noodles, carrots, green onions, cilantro, mint, spinach, cabbage, and bell pepper in a large serving bowl. 3. Whisk together peanut butter, tamari, maple syrup, chili garlic sauce, and lime juice in a small bowl; thin with water until pourable. 4. Taste dressing and adjust seasoning as needed. 5. Add half the tempeh and half the dressing to the salad; toss gently to combine. 6. Top with remaining tempeh and drizzle remaining dressing over the top. 7. Serve immediately or store components separately for make-ahead lunches.", "tags": "vegan, gluten-free, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 510, \"protein\": 18.0, \"carbs\": 71.0, \"fat\": 18.0}"},
  {"name": "Glowing Spiced Lentil Soup", "category": "Vegan", "description": "A golden lentil soup with coconut milk warming spices spinach and a bright squeeze of lime.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"ground turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cardamom\"}, {\"qty\": \"1\", \"name\": \"14-oz can diced tomatoes\"}, {\"qty\": \"1\", \"name\": \"14-oz can full-fat coconut milk\"}, {\"qty\": \"1 cup\", \"name\": \"red lentils rinsed\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"3 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}]", "instructions": "1. Heat oil in a large pot over medium heat; add onion and garlic with a pinch of salt and sauté 4-5 minutes until softened. 2. Stir in turmeric, cumin, cinnamon, and cardamom and cook for 1 minute until fragrant. 3. Add diced tomatoes with juices, entire can of coconut milk, red lentils, broth, salt, and pepper; stir to combine. 4. Bring to a low boil, then reduce heat and simmer uncovered 18-22 minutes until lentils are fluffy and tender. 5. Turn off heat and stir in spinach until wilted. 6. Stir in lime juice to taste and adjust salt and pepper. 7. Ladle into bowls and serve with toasted bread and lime wedges.", "tags": "vegan, gluten-free, quick", "source": "Classic", "nutritionData": "{\"calories\": 456, \"protein\": 15.0, \"carbs\": 37.0, \"fat\": 28.0}"},
  {"name": "Coconut Curry Vegan Ramen", "category": "Vegan", "description": "A rich coconut curry broth with ramen noodles sautéed portobello mushrooms and fresh green onion.", "servings": 4, "prepTime": 15, "cookTime": 75, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2\", \"name\": \"small knobs ginger sliced\"}, {\"qty\": \"10 cloves\", \"name\": \"garlic chopped\"}, {\"qty\": \"2\", \"name\": \"large onions chopped\"}, {\"qty\": \"5 tbsp\", \"name\": \"yellow curry paste\"}, {\"qty\": \"8 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"4 cups\", \"name\": \"light coconut milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"ground turmeric\"}, {\"qty\": \"2 tbsp\", \"name\": \"white miso paste\"}, {\"qty\": \"4\", \"name\": \"portobello mushrooms sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"tamari\"}, {\"qty\": \"1 tsp\", \"name\": \"maple syrup\"}, {\"qty\": \"4\", \"name\": \"to 6 cups cooked ramen noodles\"}, {\"qty\": \"\", \"name\": \"green onion for garnish\"}]", "instructions": "1. Heat a large pot over medium-high; sauté sesame oil, ginger, garlic, and onion 5-8 minutes until browned at edges. 2. Add curry paste and sauté 1-2 minutes stirring frequently. 3. Add broth and coconut milk; deglaze the pan and bring to a simmer. 4. Cover and cook on low for at least 1 hour up to 3 hours for maximum flavor. 5. Just before serving, dissolve miso paste in 1/2 cup hot broth then stir back into pot. 6. Sauté sliced portobello mushrooms in sesame oil with tamari and maple syrup until golden, 5-7 minutes. 7. Divide noodles among bowls, ladle broth over top, and garnish with mushrooms and green onion.", "tags": "vegan, umami, comforting", "source": "https://minimalistbaker.com/coconut-curry-ramen/", "nutritionData": "{\"calories\": 766, \"protein\": 19.0, \"carbs\": 90.0, \"fat\": 37.0}"},
  {"name": "Warming Chickpea Curry", "category": "Vegan", "description": "A vindaloo-inspired chickpea curry with tomatoes bell pepper and warm whole spices over basmati rice.", "servings": 4, "prepTime": 10, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"2\", \"name\": \"whole cloves\"}, {\"qty\": \"2\", \"name\": \"15-oz cans chickpeas drained\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable broth\"}, {\"qty\": \"3/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"coconut sugar\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"\", \"name\": \"cooked basmati rice for serving\"}]", "instructions": "1. Heat oil in a large pot over medium heat; sauté onion 2-3 minutes then add bell pepper and cook 3-4 minutes until softened. 2. Add garlic, ginger, and cumin seeds and sauté 1 minute until fragrant. 3. Add chopped tomatoes and cook 5-7 minutes until they begin to break down. 4. Stir in tomato paste, red pepper flakes, coriander, cinnamon, and cloves and cook 1 minute. 5. Add chickpeas, broth, salt, vinegar, and coconut sugar; bring to a simmer, cover, and cook on low for 20-25 minutes to thicken. 6. Remove lid and simmer 5-10 minutes more until thick and saucy; stir in spinach until wilted. 7. Serve over basmati rice garnished with coconut yogurt and cilantro.", "tags": "vegan, gluten-free, one-pot", "source": "Classic", "nutritionData": "{\"calories\": 399, \"protein\": 16.0, \"carbs\": 67.0, \"fat\": 6.0}"},
  {"name": "Vegan Miso Mushroom Risotto", "category": "Vegan", "description": "Creamy Arborio risotto enriched with miso butter and topped with sautéed golden mushrooms.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1 lb\", \"name\": \"mixed mushrooms cremini shiitake oyster\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced divided\"}, {\"qty\": \"3 sprigs\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"2\", \"name\": \"leeks white and light green parts sliced\"}, {\"qty\": \"1.5 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"5 cups\", \"name\": \"warm vegetable broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegan butter softened\"}, {\"qty\": \"1 tbsp\", \"name\": \"white miso paste\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"vegan parmesan optional\"}]", "instructions": "1. Cream softened vegan butter and miso together in a small bowl with a fork; set aside. 2. Heat 1 tbsp oil in a large frying pan over medium-high; add mushrooms and cook undisturbed 3-4 minutes to develop browning then stir and cook 4-5 minutes more. 3. Add half the garlic and thyme; season with salt and cook 2-3 minutes; stir in miso butter to coat mushrooms; set aside. 4. Heat remaining oil in a Dutch oven over medium; sauté leeks and remaining garlic 2-3 minutes until just softened. 5. Add Arborio rice and stir until grains are coated and slightly toasty, 60-90 seconds; pour in wine and stir until nearly absorbed. 6. Ladle warm broth into rice one cup at a time stirring every 30 seconds and allowing absorption before each addition for about 20 minutes total. 7. Stir in mushrooms to combine; taste for seasoning; garnish with parsley and vegan parmesan.", "tags": "vegan, gluten-free, special-occasion", "source": "Classic", "nutritionData": "{\"calories\": 491, \"protein\": 10.0, \"carbs\": 71.0, \"fat\": 15.0}"},
  {"name": "Easy Tempeh Stir-Fry", "category": "Vegan", "description": "Browned tempeh with crisp bell pepper broccoli and carrots in a rich savory stir-fry sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"tempeh cut into 1-inch cubes\"}, {\"qty\": \"2 tbsp\", \"name\": \"neutral oil divided\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2 cups\", \"name\": \"broccoli florets\"}, {\"qty\": \"2\", \"name\": \"medium carrots thinly sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vegetable bouillon dissolved in 1/2 cup boiling water\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"\", \"name\": \"cooked rice for serving\"}]", "instructions": "1. Whisk together cornstarch, bouillon water, soy sauce, sesame oil, and rice vinegar in a medium bowl until smooth; set sauce aside. 2. Heat 1 tbsp oil in a large high-sided skillet over medium-high; add tempeh in a single layer and cook 3-5 minutes per side without moving until evenly browned; remove and set aside. 3. Add remaining oil to the pan with bell pepper, broccoli, and carrots; stir-fry 5 minutes until tender-crisp. 4. Add garlic and ginger and stir-fry 2-3 minutes until fragrant. 5. Return tempeh to the pan; pour in stir-fry sauce and stir often until sauce thickens, about 5 minutes. 6. Remove from heat and garnish with green onion and sesame seeds. 7. Serve over cooked rice.", "tags": "vegan, high-protein, quick", "source": "https://plantbasedonabudget.com/easy-tempeh-stir-fry/", "nutritionData": "{\"calories\": 390, \"protein\": 16.0, \"carbs\": 45.0, \"fat\": 17.0}"},
  {"name": "Roasted Mushrooms with Herbed Quinoa", "category": "Vegan", "description": "Juicy oven-roasted mushrooms over fluffy quinoa tossed with lemon parsley and pepitas.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"mixed mushrooms quartered or halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fine salt\"}, {\"qty\": \"1 cup\", \"name\": \"quinoa rinsed\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"2\", \"name\": \"green onions chopped\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"pepitas\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"\", \"name\": \"extra olive oil for drizzle\"}]", "instructions": "1. Preheat oven to 425°F and line a large rimmed baking sheet with parchment paper. 2. Toss mushrooms with 2 tbsp olive oil and salt; spread on the baking sheet and roast 15-18 minutes tossing halfway until tender and condensed. 3. Meanwhile combine rinsed quinoa and water in a saucepan; bring to a boil then reduce heat and simmer 15-20 minutes until water is absorbed. 4. Remove quinoa from heat, cover, and let steam for 5 minutes; fluff with a fork. 5. Stir parsley, green onions, garlic, lemon juice, salt, olive oil, and pepper into the quinoa. 6. Pour quinoa into a serving bowl and top with roasted mushrooms and their juices. 7. Scatter pepitas over the top and finish with a light drizzle of olive oil.", "tags": "vegan, gluten-free, light", "source": "https://cookieandkate.com/roasted-mushrooms-with-herbed-quinoa/", "nutritionData": "{\"calories\": 334, \"protein\": 11.0, \"carbs\": 34.0, \"fat\": 17.0}"},
  {"name": "Butternut Squash Mac and Cheese", "category": "Vegan", "description": "Silky butternut squash cheese sauce with miso and nutritional yeast tossed with pasta.", "servings": 4, "prepTime": 15, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"small butternut squash halved\"}, {\"qty\": \"12 oz\", \"name\": \"elbow macaroni or shells\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegan butter\"}, {\"qty\": \"1 cup\", \"name\": \"unsweetened plant milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"arrowroot starch\"}, {\"qty\": \"4 tbsp\", \"name\": \"nutritional yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"white miso paste\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F; brush squash halves with oil, season with salt and pepper, and place cut-side down on a lined baking sheet; roast 35-50 minutes until fork-tender. 2. Let squash cool slightly then scoop out flesh; measure out 1 lightly packed cup for the sauce. 3. Cook pasta according to package directions; drain. 4. Add vegan butter, plant milk, arrowroot starch, nutritional yeast, Dijon, garlic powder, onion powder, lemon juice, miso, salt, and pepper to a blender with the 1 cup of squash; blend on high until smooth. 5. Return drained pasta to the pot over medium heat; pour in all the cheese sauce and stir to coat. 6. Cook until heated through and sauce has thickened, about 3-5 minutes; add more milk if needed. 7. Taste and adjust salt and pepper; chop remaining roasted squash into cubes and stir in.", "tags": "vegan, comfort-food, fall", "source": "Classic", "nutritionData": "{\"calories\": 434, \"protein\": 14.0, \"carbs\": 76.0, \"fat\": 7.0}"},
  {"name": "Chunky Lentil Vegetable Soup", "category": "Vegan", "description": "A budget-friendly lentil and black bean soup with smoky spices and hearty vegetables.", "servings": 6, "prepTime": 10, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"\", \"name\": \"3-4 medium carrots sliced\"}, {\"qty\": \"3\", \"name\": \"ribs celery sliced\"}, {\"qty\": \"1\", \"name\": \"15-oz can black beans drained\"}, {\"qty\": \"1 cup\", \"name\": \"brown lentils\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"1\", \"name\": \"15-oz can diced tomatoes with juices\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}]", "instructions": "1. Mince garlic and dice onion; sauté in olive oil in a large pot over medium heat until onions are tender. 2. Slice celery and carrots; add to pot and sauté about 5 minutes more. 3. Add drained black beans, diced tomatoes with juices, dry lentils, cumin, oregano, smoked paprika, cayenne, and freshly cracked black pepper. 4. Add vegetable broth and stir to combine; increase heat to medium-high and bring to a boil. 5. Once boiling, turn heat to low, place lid on top, and simmer for 30 minutes. 6. Test lentils for tenderness; continue simmering if needed. 7. Taste and add salt as needed; serve hot with crusty bread.", "tags": "vegan, budget-friendly, freezer-friendly", "source": "Classic", "nutritionData": "{\"calories\": 258, \"protein\": 13.0, \"carbs\": 39.0, \"fat\": 5.0}"},
  {"name": "BBQ Jackfruit Sandwiches", "category": "Vegan", "description": "Shredded jackfruit cooked in tangy BBQ sauce served on buns with crisp red cabbage slaw.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2\", \"name\": \"small yellow onion diced\"}, {\"qty\": \"1/2\", \"name\": \"small green bell pepper diced\"}, {\"qty\": \"15 oz\", \"name\": \"can jackfruit drained and shredded\"}, {\"qty\": \"1/4\", \"name\": \"to 1/2 cup vegan BBQ sauce\"}, {\"qty\": \"4\", \"name\": \"burger buns\"}, {\"qty\": \"1 cup\", \"name\": \"shredded red cabbage\"}]", "instructions": "1. Using your fingers or two forks, shred the drained jackfruit and remove any tough pieces. 2. Heat oil in a large pan over medium-high heat; add onion and bell pepper and sauté 3-4 minutes until tender. 3. Add shredded jackfruit and cook for 8-10 minutes, adding BBQ sauce halfway through. 4. Stir and press jackfruit gently to help it absorb the sauce and develop caramelized edges. 5. Taste and add more BBQ sauce if desired. 6. Divide jackfruit mixture evenly among the four bun halves. 7. Top with shredded red cabbage and close the buns; serve immediately.", "tags": "vegan, quick, sandwich", "source": "Classic", "nutritionData": "{\"calories\": 269, \"protein\": 6.0, \"carbs\": 50.0, \"fat\": 3.0}"},
  {"name": "Creamy Vegan Mushroom Stroganoff", "category": "Vegan", "description": "Hearty pasta in a creamy mushroom sauce made with coconut milk tahini and nutritional yeast.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"leeks white and light green parts sliced and rinsed\"}, {\"qty\": \"1 lb\", \"name\": \"mixed mushrooms cremini shiitake oyster sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1 cup\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"tamari\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegan Worcestershire\"}, {\"qty\": \"1/2 cup\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"2 tbsp\", \"name\": \"nutritional yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"12 oz\", \"name\": \"egg-free pasta cooked\"}, {\"qty\": \"\", \"name\": \"fresh dill for garnish\"}]", "instructions": "1. Heat oil in a large skillet over medium-high; add leeks and mushrooms spreading them out; cook undisturbed until browned, about 5 minutes then stir and cook 4-5 minutes more. 2. Add garlic and thyme; cook 2 minutes stirring frequently. 3. Set aside half the mushroom mixture for topping; keep remaining in pan. 4. Pour in wine and deglaze the pan with a wooden spoon; add broth whisked with flour, tamari, and Worcestershire. 5. Stir in coconut milk, tahini, nutritional yeast, and paprika; simmer 5 minutes until sauce thickens. 6. Add cooked pasta and toss to coat; taste and adjust seasoning. 7. Serve topped with reserved crispy mushrooms and fresh dill.", "tags": "vegan, comfort-food, date-night", "source": "Classic", "nutritionData": "{\"calories\": 603, \"protein\": 17.0, \"carbs\": 87.0, \"fat\": 19.0}"},
  {"name": "Vegan Black Bean Chili", "category": "Vegan", "description": "A smoky one-pot chipotle black bean chili with fire-roasted tomatoes and bell pepper.", "servings": 6, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"large red bell pepper diced\"}, {\"qty\": \"3\", \"name\": \"large cloves garlic minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable broth\"}, {\"qty\": \"1\", \"name\": \"14.5-oz can fire-roasted diced tomatoes\"}, {\"qty\": \"2\", \"name\": \"chipotle peppers in adobo minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"adobo sauce\"}, {\"qty\": \"4\", \"name\": \"15-oz cans black beans drained\"}, {\"qty\": \"\", \"name\": \"avocado and tortilla chips for serving\"}]", "instructions": "1. Heat a large pot over medium heat; add oil, onion, and bell pepper and cook 4-5 minutes until softened. 2. Add garlic, smoked paprika, cumin, and salt; cook 1 minute until fragrant. 3. Add broth, fire-roasted tomatoes, chipotle peppers, adobo sauce, and drained black beans; stir well. 4. Bring to a gentle boil then reduce heat and cook uncovered at a gentle boil for 20-25 minutes stirring occasionally until thickened. 5. Taste and adjust with more salt, adobo sauce for smokiness, or chipotle for heat. 6. For a creamier texture, partially blend with an immersion blender. 7. Serve topped with diced avocado, tortilla chips, and cilantro.", "tags": "vegan, gluten-free, freezer-friendly", "source": "Classic", "nutritionData": "{\"calories\": 448, \"protein\": 15.0, \"carbs\": 61.0, \"fat\": 14.0}"},
  {"name": "Simple Eggplant Parmesan", "category": "Vegetarian", "description": "Roasted eggplant layered with marinara and melted mozzarella for a satisfying Italian classic.", "servings": 4, "prepTime": 40, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"eggplant cut into 1/2-inch slices\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"5 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"small onion finely chopped\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1\", \"name\": \"28-oz can whole tomatoes\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1\", \"name\": \"handful fresh basil leaves\"}, {\"qty\": \"8 oz\", \"name\": \"grated mozzarella\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated parmesan\"}]", "instructions": "1. Salt eggplant slices and let sit 30 minutes then blot dry. 2. Coat a baking sheet with 3 tbsp olive oil and arrange eggplant in one layer; drizzle with 2 more tbsp oil. 3. Roast at 425°F for 20-25 minutes until browned; flip and roast 10 more minutes. Reduce oven to 375°F. 4. Make sauce: sauté onion in 2 tbsp olive oil 8 minutes; add garlic and pepper flakes 1 minute; add crushed tomatoes and oregano; simmer 10 minutes; stir in basil. 5. Spread 1/2 cup sauce in a 1.5-quart baking dish. Layer half the eggplant then more sauce; repeat with remaining eggplant and sauce. 6. Top with mozzarella and parmesan and bake 30 minutes until cheese is melted and bubbling. 7. Rest 15 minutes before serving.", "tags": "Italian, comfort food, baked, cheese", "source": "https://smittenkitchen.com/2023/09/simple-eggplant-parmesan/", "nutritionData": "{\"calories\": 468, \"protein\": 23.0, \"carbs\": 18.0, \"fat\": 32.0}"},
  {"name": "Shakshuka", "category": "Vegetarian", "description": "Eggs poached in a spiced tomato and pepper sauce and finished with crumbled feta.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"small onion chopped\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1o or Fresno chiles thinly sliced\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1\", \"name\": \"28-oz can whole tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"3 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}, {\"qty\": \"\", \"name\": \"pita for serving\"}]", "instructions": "1. Heat olive oil in a deep 12-inch skillet over medium-high. 2. Cook chiles and onion until soft and golden about 6 minutes. 3. Add garlic cumin and paprika; cook 2 more minutes. 4. Add tomatoes (crushed by hand) and their liquid plus 1/2 cup water. 5. Reduce heat to medium and simmer sauce until slightly thickened about 15 minutes; season with salt. 6. Make 6 divots in the sauce and crack an egg into each; cover and cook until yolks are just set about 5 minutes. 7. Baste whites with sauce then sprinkle with feta and parsley; serve with pita.", "tags": "eggs, one-pan, Mediterranean, spicy", "source": "https://smittenkitchen.com/2010/04/shakshuka/", "nutritionData": "{\"calories\": 440, \"protein\": 19.0, \"carbs\": 42.0, \"fat\": 21.0}"},
  {"name": "Potato and Broccolini Frittata", "category": "Vegetarian", "description": "Hearty stovetop-to-broiler frittata packed with tender potatoes and broccolini and finished with parmesan.", "servings": 6, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"Yukon Gold potatoes thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"bunch broccolini trimmed\"}, {\"qty\": \"1\", \"name\": \"small onion thinly sliced\"}, {\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated parmesan divided\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}]", "instructions": "1. Place potatoes and broth in a 12-inch ovenproof skillet; bring to a boil and simmer 10 minutes until tender and broth is absorbed. 2. Add olive oil broccolini and onion; cook over medium heat 1 minute then cover and cook 3-4 minutes until broccolini is tender. 3. Heat broiler. 4. Beat eggs with half the parmesan plus salt and pepper; pour over vegetables. 5. Cover and cook over medium heat until eggs are mostly set about 5 minutes. 6. Sprinkle remaining parmesan over top; broil until golden and eggs are just set throughout about 5 minutes. 7. Cool slightly then slice into wedges.", "tags": "eggs, one-pan, gluten-free, brunch", "source": "https://smittenkitchen.com/2013/10/potato-and-broccolini-frittata/", "nutritionData": "{\"calories\": 274, \"protein\": 14.0, \"carbs\": 23.0, \"fat\": 14.0}"},
  {"name": "Leek and Mushroom Quiche", "category": "Vegetarian", "description": "Classic French-inspired quiche with silky leeks and earthy mushrooms baked in a buttery pastry shell.", "servings": 6, "prepTime": 30, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"9-inch pie crust pre-baked\"}, {\"qty\": \"3\", \"name\": \"leeks white parts only sliced\"}, {\"qty\": \"6\", \"name\": \"large white mushrooms sliced\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"port wine\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1.5 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Swiss cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"pinch of nutmeg\"}]", "instructions": "1. Preheat oven to 375°F. 2. Braise leeks in a covered saucepan with 1/2 cup water 2 tbsp butter and 1 tsp salt for 30 minutes over low heat until very tender; remove to bowl. 3. Melt remaining butter in pan; add mushrooms and port; cover and cook 8 minutes then uncover and boil until liquid evaporates; stir into leeks. 4. Beat eggs milk salt pepper and nutmeg together. 5. Stir leek-mushroom mixture into egg custard. 6. Pour into pre-baked shell; scatter Swiss cheese on top. 7. Bake in upper third of oven 25-30 minutes until puffed and browned; serve warm.", "tags": "quiche, French, brunch, make-ahead", "source": "https://smittenkitchen.com/2007/01/quiche-me-deadly/", "nutritionData": "{\"calories\": 348, \"protein\": 10.0, \"carbs\": 24.0, \"fat\": 21.0}"},
  {"name": "Arugula and Cremini Quiche", "category": "Vegetarian", "description": "Savory quiche with wilted arugula mushrooms and creamy goat cheese in a gluten-free almond meal crust.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"almond meal\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/3 cup\", \"name\": \"olive oil plus more for pan\"}, {\"qty\": \"3 cups\", \"name\": \"baby arugula roughly chopped\"}, {\"qty\": \"1.5 cups\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"1/3 cup\", \"name\": \"whole milk\"}, {\"qty\": \"5 oz\", \"name\": \"goat cheese crumbled\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}]", "instructions": "1. Preheat oven to 400°F; grease a 10-inch cast iron skillet. 2. Mix almond meal garlic thyme salt pepper olive oil and water; press into skillet up the sides. 3. Bake crust 15-20 minutes until golden and firm. 4. Sauté mushrooms in olive oil until tender; add arugula and wilt 30 seconds; transfer to plate to cool. 5. Whisk eggs milk salt and red pepper flakes together; stir in goat cheese and cooled vegetable mixture. 6. Pour into baked crust and bake 30 minutes until center is firm. 7. Cool 5-10 minutes before slicing and serving.", "tags": "gluten-free, quiche, brunch, cheese", "source": "https://cookieandkate.com/arugula-and-cremini-quiche-with-gluten-free-almond-meal-crust/", "nutritionData": "{\"calories\": 370, \"protein\": 20.0, \"carbs\": 10.0, \"fat\": 29.0}"},
  {"name": "Halloumi Fajita Bowls", "category": "Vegetarian", "description": "Roasted peppers and onions topped with baked golden halloumi over cilantro lime rice.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"halloumi cheese sliced into 1-inch pieces\"}, {\"qty\": \"2\", \"name\": \"bell peppers sliced into strips\"}, {\"qty\": \"1\", \"name\": \"red onion sliced into strips\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"1.5 cups\", \"name\": \"long-grain white rice\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 425°F; line two baking sheets with parchment. 2. Toss peppers and onion with 1.5 tbsp olive oil chili powder cumin garlic powder salt and pepper; spread on one sheet and bake 15 minutes. 3. Toss halloumi with remaining olive oil; spread on second sheet and add to oven. 4. After 10 minutes flip halloumi and check peppers; return to oven 5 more minutes until halloumi is golden and peppers are caramelized. 5. Drizzle lime juice over peppers while hot. 6. Cook rice according to package; fluff with fork and stir in cilantro and lime juice. 7. Serve halloumi and peppers over cilantro rice.", "tags": "one-pan, weeknight, gluten-free, Mediterranean", "source": "https://cookieandkate.com/fajita-veggie-halloumi-bowls/", "nutritionData": "{\"calories\": 437, \"protein\": 17.0, \"carbs\": 42.0, \"fat\": 22.0}"},
  {"name": "Chopped Greek Salad", "category": "Vegetarian", "description": "Crisp romaine with feta olives cucumber and tomatoes tossed in a bold Greek vinaigrette.", "servings": 4, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"10 oz\", \"name\": \"chopped romaine lettuce\"}, {\"qty\": \"1\", \"name\": \"pint cherry tomatoes quartered\"}, {\"qty\": \"1\", \"name\": \"medium cucumber seeded and chopped\"}, {\"qty\": \"1\", \"name\": \"orange bell pepper chopped\"}, {\"qty\": \"1/2\", \"name\": \"red onion chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"parsley chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"Kalamata olives halved\"}, {\"qty\": \"6 oz\", \"name\": \"feta cheese cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"red wine vinegar\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"honey\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Combine romaine tomatoes cucumber bell pepper red onion parsley olives and feta in a large bowl. 2. Whisk together olive oil red wine vinegar garlic oregano honey salt and pepper until combined. 3. Taste dressing and adjust acidity and sweetness as needed. 4. Drizzle dressing over salad and toss to combine or store separately if making ahead. 5. Serve immediately for best texture.", "tags": "salad, no-cook, gluten-free, Mediterranean", "source": "https://cookieandkate.com/chopped-greek-salad-recipe/", "nutritionData": "{\"calories\": 321, \"protein\": 9.0, \"carbs\": 16.0, \"fat\": 26.0}"},
  {"name": "Spinach and Ricotta Gnudi", "category": "Vegetarian", "description": "Pillowy ricotta and spinach dumplings pan-browned in sage brown butter for a simple elegant dinner.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"10-oz package frozen chopped spinach thawed\"}, {\"qty\": \"1 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated parmesan plus more to serve\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"pinch of nutmeg\"}, {\"qty\": \"4 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"6\", \"name\": \"fresh sage leaves\"}]", "instructions": "1. Squeeze all excess water from thawed spinach in small fistfuls; finely chop on a cutting board. 2. Combine spinach ricotta egg parmesan nutmeg salt pepper and flour in a bowl; stir to form a thick dough. 3. Scoop into 1.5-tablespoon balls and arrange on a plate. 4. Bring a pot of salted water to a gentle boil; simmer gnudi in batches until they float about 3 minutes; remove with a slotted spoon. 5. Melt butter in a large skillet over medium heat; add sage leaves. 6. Add gnudi in batches and brown on both sides turning gently. 7. Transfer to a serving plate; drizzle with browned butter and finish with extra parmesan and black pepper.", "tags": "Italian, eggs, quick, comfort food", "source": "https://smittenkitchen.com/2025/10/spinach-and-ricotta-gnudi/", "nutritionData": "{\"calories\": 327, \"protein\": 15.0, \"carbs\": 12.0, \"fat\": 24.0}"},
  {"name": "Roasted Tomato Feta Orzo", "category": "Vegetarian", "description": "Burst roasted cherry tomatoes tossed with herbed orzo crumbled feta and toasted nuts.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dry orzo pasta\"}, {\"qty\": \"4 cups\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"\", \"name\": \"3-4 garlic cloves smashed\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"3 tsp\", \"name\": \"honey\"}, {\"qty\": \"7 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/2\", \"name\": \"small shallot grated\"}, {\"qty\": \"8 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil roughly chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"toasted pine nuts\"}, {\"qty\": \"\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 425°F. 2. Combine cherry tomatoes garlic thyme chili powder 1 tsp honey 3 tbsp olive oil salt and pepper in a roasting pan; roast 20-25 minutes until tomatoes burst. 3. Bring a large pot of salted water to boil; cook orzo until al dente and drain. 4. In a large bowl whisk together 4 tbsp olive oil red wine vinegar 2 tsp honey shallot and a pinch of red pepper flakes salt and pepper. 5. Add hot orzo and fresh herbs; toss to combine. 6. Add burst tomatoes with all their juices feta and toasted pine nuts; toss gently. 7. Serve warm or chilled.", "tags": "pasta, Mediterranean, feta, weeknight", "source": "https://www.halfbakedharvest.com/roasted-tomato-basil-and-feta-orzo/", "nutritionData": "{\"calories\": 900, \"protein\": 26.0, \"carbs\": 99.0, \"fat\": 46.0}"},
  {"name": "Winter Squash and Spinach Pasta Bake", "category": "Vegetarian", "description": "Creamy ricotta and fontina pasta bake layered with butternut squash and spinach for a hearty one-dish dinner.", "servings": 8, "prepTime": 25, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"1 cup\", \"name\": \"finely grated parmesan divided\"}, {\"qty\": \"1 cup\", \"name\": \"coarsely grated fontina\"}, {\"qty\": \"1.25 cups\", \"name\": \"water\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"3\", \"name\": \"garlic cloves thinly sliced\"}, {\"qty\": \"5 oz\", \"name\": \"baby spinach roughly chopped\"}, {\"qty\": \"1.25 lb\", \"name\": \"butternut squash peeled and thinly sliced\"}, {\"qty\": \"8 oz\", \"name\": \"dried pasta broken into pieces\"}]", "instructions": "1. Heat oven to 350°F; line a 9-inch springform pan with parchment. 2. Whisk egg and ricotta in a large bowl; stir in half the parmesan fontina water 2 tbsp olive oil salt nutmeg pepper and red pepper flakes. 3. Stir in garlic squash spinach and sage then add dry pasta and stir to coat. 4. Pour into prepared pan pressing into an even layer; sprinkle with remaining parmesan. 5. Cover tightly with foil and bake on a sheet for 1 hour. 6. Remove foil drizzle with remaining 1 tbsp olive oil and return to oven uncovered 30 minutes until top is crisp. 7. Cool 30 minutes before removing springform ring; cut into wedges and serve.", "tags": "pasta, baked, comfort food, make-ahead", "source": "https://smittenkitchen.com/2021/10/winter-squash-and-spinach-pasta-bake/", "nutritionData": "{\"calories\": 359, \"protein\": 17.0, \"carbs\": 32.0, \"fat\": 18.0}"},
  {"name": "Pesto Pasta Genovese", "category": "Vegetarian", "description": "Fresh basil pesto tossed with your favorite pasta and served with white beans cherry tomatoes and bocconcini.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried pasta\"}, {\"qty\": \"2 oz\", \"name\": \"aged parmesan plus more to serve\"}, {\"qty\": \"\", \"name\": \"2-3 garlic cloves\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted pine nuts\"}, {\"qty\": \"4 cups\", \"name\": \"fresh basil leaves packed\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 can\", \"name\": \"white beans drained\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"4 oz\", \"name\": \"fresh bocconcini mozzarella\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}]", "instructions": "1. Bring a large pot of well-salted water to boil and cook pasta until al dente; drain. 2. Make pesto: grind parmesan in food processor until powdery; add garlic and pulse until chopped; add pine nuts and pulse to small pieces. 3. Add salt pepper and basil; run machine until finely chopped then drizzle in olive oil with machine running. 4. Stir in remaining parmesan; taste and season with more salt. 5. Transfer pasta to a large bowl and let cool slightly. 6. Add half the pesto and toss then add more a spoonful at a time until pasta is well coated. 7. Serve with white beans cherry tomatoes and bocconcini alongside with extra parmesan.", "tags": "pasta, quick, Italian, cheese", "source": "https://smittenkitchen.com/2020/07/pasta-with-pesto-genovese/", "nutritionData": "{\"calories\": 1008, \"protein\": 38.0, \"carbs\": 114.0, \"fat\": 45.0}"},
  {"name": "Four Cheese Butternut Squash Rigatoni", "category": "Vegetarian", "description": "Rich butternut squash and ricotta puree with rigatoni baked under a melting gouda and fontina crust.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"butternut squash peeled and cubed\"}, {\"qty\": \"2\", \"name\": \"shallots quartered\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh oregano\"}, {\"qty\": \"\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"1 lb\", \"name\": \"rigatoni\"}, {\"qty\": \"3 cups\", \"name\": \"water\"}, {\"qty\": \"5 oz\", \"name\": \"baby spinach\"}, {\"qty\": \"1/2 cup\", \"name\": \"sun-dried tomatoes chopped\"}, {\"qty\": \"1 cup\", \"name\": \"shredded gouda\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated parmesan\"}, {\"qty\": \"1 cup\", \"name\": \"shredded fontina\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Preheat oven to 425°F; toss squash shallots garlic oregano red pepper flakes oil salt and pepper on a baking sheet and roast 25 minutes until tender. 2. Purée roasted squash with garlic and ricotta in a blender until smooth; season with salt. 3. In a large oven-safe skillet bring 3 cups water to a boil; add rigatoni and cook until just al dente do not drain. 4. Stir in squash purée spinach sun-dried tomatoes gouda and parmesan. 5. Top with fontina; transfer to oven and bake 15-20 minutes until cheese is melted and bubbling. 6. Serve hot directly from the pan.", "tags": "pasta, baked, comfort food, cheese", "source": "https://www.halfbakedharvest.com/baked-4-cheese-butternut-squash-rigatoni/", "nutritionData": "{\"calories\": 612, \"protein\": 30.0, \"carbs\": 79.0, \"fat\": 20.0}"},
  {"name": "Spinach Ricotta Stuffed Shells", "category": "Vegetarian", "description": "Jumbo pasta shells filled with creamy ricotta and spinach baked in marinara with pecorino on top.", "servings": 4, "prepTime": 25, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"18-20 jumbo pasta shells\"}, {\"qty\": \"5 oz\", \"name\": \"fresh spinach\"}, {\"qty\": \"2 cups\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated pecorino cheese plus more\"}, {\"qty\": \"2\", \"name\": \"garlic cloves grated\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"3/4 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce plus more\"}, {\"qty\": \"\", \"name\": \"fresh parsley for serving\"}]", "instructions": "1. Preheat oven to 425°F. 2. Steam spinach 1 minute until wilted; transfer to strainer squeeze dry and chop. 3. Cook shells in salted water 10 minutes until al dente; drain and drizzle with olive oil. 4. Mix spinach with ricotta pecorino garlic oregano lemon zest red pepper flakes salt and pepper. 5. Spread marinara over bottom of a 9x13 baking dish. 6. Fill each shell with ricotta mixture and arrange in dish. 7. Cover with foil and bake 20 minutes; serve with extra marinara and parsley.", "tags": "Italian, pasta, baked, cheese", "source": "https://www.loveandlemons.com/stuffed-shells-recipe/", "nutritionData": "{\"calories\": 520, \"protein\": 26.0, \"carbs\": 55.0, \"fat\": 21.0}"},
  {"name": "Caprese Salad", "category": "Vegetarian", "description": "Heirloom tomatoes fresh mozzarella and fragrant basil drizzled with olive oil and balsamic reduction.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"3-4 medium heirloom tomatoes sliced\"}, {\"qty\": \"8 oz\", \"name\": \"fresh mozzarella sliced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic reduction\"}, {\"qty\": \"\", \"name\": \"flaky sea salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}]", "instructions": "1. Arrange tomato and mozzarella slices alternately on a large platter overlapping slightly. 2. Tuck fresh basil leaves between the slices. 3. Drizzle generously with olive oil and balsamic reduction. 4. Season with flaky sea salt and several grinds of black pepper. 5. Serve immediately at room temperature.", "tags": "no-cook, Italian, salad, gluten-free", "source": "https://www.loveandlemons.com/caprese-salad/", "nutritionData": "{\"calories\": 289, \"protein\": 13.0, \"carbs\": 10.0, \"fat\": 20.0}"},
  {"name": "Palak Paneer", "category": "Vegetarian", "description": "Creamy spiced spinach sauce with tender paneer cubes served over basmati rice or with naan.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"fresh spinach leaves\"}, {\"qty\": \"1 lb\", \"name\": \"paneer cubed\"}, {\"qty\": \"1\", \"name\": \"onion chopped\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"\", \"name\": \"1-inch piece ginger\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"2 tbsp\", \"name\": \"dried fenugreek leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain whole-milk yogurt\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}]", "instructions": "1. Place spinach in a Dutch oven over low heat with 2 tbsp water; cover and cook until wilted 10-12 minutes; transfer to blender with onion ginger and garlic and blend until smooth. 2. Heat 1 tbsp ghee in the same pot; add cinnamon coriander garam masala cumin and cayenne; sauté 30-45 seconds until fragrant. 3. Add spinach purée and dried fenugreek; bring to a boil then reduce and simmer 5 minutes. 4. Remove from heat and whisk in yogurt; return to low heat and simmer. 5. Fold in paneer and simmer 1-2 minutes until paneer is soft; season with salt. 6. Top with remaining 1 tbsp ghee and serve hot with rice or naan.", "tags": "Indian, gluten-free, dairy, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 484, \"protein\": 28.0, \"carbs\": 10.0, \"fat\": 37.0}"},
  {"name": "Mushroom Risotto", "category": "Vegetarian", "description": "Velvety Arborio rice cooked with sautéed mushrooms white wine and finished with butter and parmesan.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"6 cups\", \"name\": \"vegetable stock warm\"}, {\"qty\": \"1 lb\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1\", \"name\": \"onion finely chopped\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"grated parmesan\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"fresh thyme leaves\"}]", "instructions": "1. Heat 1 tbsp oil and half the butter in a large pot over high heat; sauté half the mushrooms until golden about 4 minutes; add half the garlic season with salt and pepper and cook until browned another 1.5 minutes; remove to bowl and repeat with remaining mushrooms. 2. Reduce heat to medium; in the same pot melt remaining butter and cook remaining garlic and onion 2 minutes until translucent. 3. Add wine and simmer rapidly 2 minutes until mostly evaporated. 4. Add rice and stir 1 minute until semi-translucent. 5. Add stock 1.5 cups at a time stirring occasionally until absorbed about 10 minutes total. 6. Stir in cream and remaining butter vigorously to make it creamy then stir in parmesan; season with salt and pepper. 7. Stir through half the mushrooms; serve topped with reserved mushrooms and thyme.", "tags": "Italian, comfort food, gluten-free, cheese", "source": "Classic", "nutritionData": "{\"calories\": 715, \"protein\": 20.0, \"carbs\": 82.0, \"fat\": 32.0}"},
  {"name": "Spanakopita", "category": "Vegetarian", "description": "Traditional Greek spinach and feta pie wrapped in crispy layered phyllo dough.", "servings": 8, "prepTime": 30, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"fresh spinach leaves\"}, {\"qty\": \"1 lb\", \"name\": \"frozen phyllo dough thawed\"}, {\"qty\": \"1 lb\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"4\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"3\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried dill\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"sesame seeds for topping\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}]", "instructions": "1. Place spinach in a large colander; sprinkle with salt and let sit 10 minutes; wring out in a tea towel to remove excess water. 2. In a large bowl combine spinach feta scallions garlic eggs dill and black pepper; mix well. 3. Brush a 9x13 baking dish with olive oil. 4. Layer 8 sheets of phyllo in the dish brushing each with olive oil. 5. Spread filling over phyllo in an even layer. 6. Top with remaining 8 sheets of phyllo brushing each layer with oil; sprinkle sesame seeds on top. 7. Score top with a sharp knife and bake at 375°F for 45 minutes until golden brown; cool before serving.", "tags": "Greek, cheese, eggs, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 16.0, \"carbs\": 41.0, \"fat\": 25.0}"},
  {"name": "Skillet Mac and Cheese", "category": "Vegetarian", "description": "Rich stovetop-to-oven mac and cheese with a three-cheese sauce and golden toasted breadcrumb crust.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"dried elbow macaroni\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded Gruy\\u00e8re\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded fontina\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"\", \"name\": \"pinch nutmeg\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"panko breadcrumbs\"}]", "instructions": "1. Soak dry pasta in a large bowl of hot tap water for 10 minutes then drain. 2. Heat oven to 375°F; melt 2 tbsp butter in a 10-inch ovenproof skillet; add breadcrumbs and toast stirring until light golden; remove to a small bowl. 3. Melt remaining butter in the same skillet over medium-high heat; whisk in flour until smooth; add milk 1/2 cup at a time whisking after each addition. 4. Season with salt cayenne nutmeg and black pepper; cook stirring until simmering and slightly thickened 2-3 minutes. 5. Remove from heat; stir in all but 2/3 cup cheese until melted. 6. Add drained pasta; stir to coat; sprinkle with reserved cheese then top with toasted breadcrumbs. 7. Bake 30 minutes until pasta is cooked through and top is golden.", "tags": "comfort food, pasta, cheese, weeknight", "source": "https://smittenkitchen.com/2024/11/skillet-baked-macaroni-and-cheese/", "nutritionData": "{\"calories\": 630, \"protein\": 27.0, \"carbs\": 57.0, \"fat\": 32.0}"},
  {"name": "Paneer Tikka Masala", "category": "Vegetarian", "description": "Charred marinated paneer in a rich tomato cream sauce seasoned with garam masala and kasuri methi.", "servings": 4, "prepTime": 30, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"paneer cubed\"}, {\"qty\": \"1 cup\", \"name\": \"plain whole-milk yogurt\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger-garlic paste\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"2\", \"name\": \"large onions chopped\"}, {\"qty\": \"4\", \"name\": \"tomatoes chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"cashews\"}, {\"qty\": \"2 tbsp\", \"name\": \"neutral oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"fresh coriander to garnish\"}, {\"qty\": \"\", \"name\": \"naan or rice to serve\"}]", "instructions": "1. Marinate paneer in yogurt red chili powder garam masala ginger-garlic paste turmeric kasuri methi oil lemon juice and salt for 20 minutes. 2. Grill or broil paneer on a baking tray at 430°F for 8-10 minutes turning once until golden. 3. Sauté onions in oil over medium heat until golden; add tomatoes cashews sugar and salt; cook until tomatoes are mushy. 4. Cool and blend to a smooth purée; return to pan with remaining oil and whole spices; cook 2 minutes. 5. Pour in purée and cook covered until thick about 10 minutes until oil surfaces. 6. Stir in cream and grilled paneer; simmer 2 minutes; garnish with coriander. 7. Serve with naan or basmati rice.", "tags": "Indian, comfort food, dairy, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 880, \"protein\": 41.0, \"carbs\": 65.0, \"fat\": 51.0}"},
  {"name": "Baked Ziti with Ricotta", "category": "Vegetarian", "description": "Tube pasta baked in a rich tomato sauce with pools of ricotta mozzarella and parmesan throughout.", "servings": 6, "prepTime": 20, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ziti pasta\"}, {\"qty\": \"2 cups\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce\"}, {\"qty\": \"2 cups\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated parmesan\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Italian seasoning\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"fresh basil to serve\"}, {\"qty\": \"\", \"name\": \"olive oil\"}]", "instructions": "1. Preheat oven to 375°F; boil ziti in well-salted water until 2 minutes shy of al dente; drain reserving 1/2 cup pasta water. 2. Mix ricotta egg Italian seasoning red pepper flakes salt and pepper in a bowl; stir in 1/4 cup each mozzarella and parmesan. 3. Combine hot pasta with marinara; add pasta water if sauce seems thick. 4. Spread a thin layer of pasta in a 9x13 baking dish; dollop half the ricotta mixture over the pasta. 5. Add remaining pasta; dollop remaining ricotta over top. 6. Cover with remaining mozzarella and parmesan; cover dish with foil. 7. Bake covered 20 minutes then uncover and bake 15-20 minutes until cheese is golden and bubbling; rest 10 minutes before serving with basil.", "tags": "Italian, pasta, baked, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 622, \"protein\": 32.0, \"carbs\": 69.0, \"fat\": 22.0}"},
  {"name": "Cheese Blintzes with Sour Cream", "category": "Vegetarian", "description": "Thin crêpes filled with sweetened farmer's cheese and pan-fried to a golden crisp served with sour cream.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted plus more for frying\"}, {\"qty\": \"1 lb\", \"name\": \"farmer's cheese or dry ricotta\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"\", \"name\": \"sour cream and jam to serve\"}]", "instructions": "1. Blend flour milk eggs melted butter and a pinch of salt until smooth; rest batter 30 minutes. 2. Cook 6-inch crêpes in a buttered pan pouring in about 3 tbsp batter per crêpe; cook until edges lift and bottom is light golden; flip 30 seconds; stack on a plate. 3. Beat farmer's cheese cream cheese sugar vanilla lemon zest and salt until smooth. 4. Place 3 tbsp filling near one edge of each crêpe; fold in sides and roll up tightly. 5. Melt butter in a skillet over medium heat; fry blintzes seam-side down until golden about 3 minutes per side. 6. Serve warm with sour cream and fruit jam.", "tags": "Jewish, brunch, eggs, cheese", "source": "Classic", "nutritionData": "{\"calories\": 620, \"protein\": 28.0, \"carbs\": 55.0, \"fat\": 31.0}"},
  {"name": "Margherita Pizza", "category": "Vegetarian", "description": "Hand-stretched pizza dough with San Marzano tomato sauce fresh mozzarella and basil baked at high heat.", "servings": 2, "prepTime": 20, "cookTime": 12, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"ball pizza dough about 12 oz\"}, {\"qty\": \"1/2 cup\", \"name\": \"San Marzano tomatoes crushed\"}, {\"qty\": \"6 oz\", \"name\": \"fresh mozzarella torn\"}, {\"qty\": \"1 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"6\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for finishing\"}]", "instructions": "1. Preheat oven with a pizza stone or cast iron skillet to 550°F for at least 45 minutes. 2. Season crushed tomatoes with salt. 3. On a floured surface stretch dough into a 12-inch round. 4. Spread tomato sauce over dough leaving a 1-inch border; scatter mozzarella over top and drizzle with olive oil. 5. Transfer pizza to hot stone or skillet. 6. Bake until crust is charred in spots and cheese is bubbling about 10-12 minutes. 7. Top with fresh basil and a pinch of flaky sea salt; serve immediately.", "tags": "Italian, pizza, cheese, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 768, \"protein\": 31.0, \"carbs\": 94.0, \"fat\": 25.0}"},
  {"name": "Over-the-Top Mushroom Quiche", "category": "Vegetarian", "description": "Luxurious deep-dish quiche loaded with sautéed mushrooms Gruyère and a rich egg cream custard.", "servings": 8, "prepTime": 60, "cookTime": 105, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"mixed mushrooms oyster cremini button\"}, {\"qty\": \"4\", \"name\": \"shallots minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"cold unsalted butter diced\"}, {\"qty\": \"1/4 cup\", \"name\": \"ice water\"}, {\"qty\": \"3/4 cup\", \"name\": \"grated Gruy\\u00e8re\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2 cups\", \"name\": \"heavy cream\"}, {\"qty\": \"6\", \"name\": \"large eggs lightly beaten\"}, {\"qty\": \"\", \"name\": \"freshly grated nutmeg\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Make pastry: mix 1 cup flour with all salt in a stand mixer; add butter until combined; add remaining flour; add ice water; wrap dough and chill at least 1 hour. 2. Roll dough into a 16-inch round and press into a 9-inch springform; par-bake with weights 30-40 minutes at 375°F then remove weights and bake 10-15 more minutes until richly brown; cool. 3. Sauté mushrooms in oil over high heat until golden; add butter shallots and thyme; cook until tender 12 minutes; cool. 4. Scatter 1/4 cup Gruyère and half the mushrooms in shell; blend half the milk cream and eggs with salt pepper and nutmeg; pour into shell. 5. Add remaining 1/4 cup Gruyère and remaining mushrooms; repeat custard with remaining milk cream and eggs; pour in. 6. Sprinkle top with remaining Gruyère; bake at 375°F for 1.5 hours until just set. 7. Cool slightly; remove springform ring and serve warm.", "tags": "brunch, French, eggs, cheese", "source": "https://smittenkitchen.com/2012/04/over-the-top-mushroom-quiche/", "nutritionData": "{\"calories\": 685, \"protein\": 18.0, \"carbs\": 32.0, \"fat\": 55.0}"},
  {"name": "Shakshuka with Chickpeas and Kale", "category": "Vegetarian", "description": "Hearty one-pan eggs poached in a smoky spiced tomato sauce with chickpeas and wilted kale.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"onion chopped\"}, {\"qty\": \"4\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"harissa or cayenne\"}, {\"qty\": \"1\", \"name\": \"28-oz can crushed tomatoes\"}, {\"qty\": \"1 can\", \"name\": \"chickpeas drained and rinsed\"}, {\"qty\": \"3 cups\", \"name\": \"kale roughly chopped\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"4 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"crusty bread to serve\"}]", "instructions": "1. Heat olive oil in a large deep skillet over medium-high heat; cook onion until softened about 5 minutes. 2. Add garlic cumin paprika and harissa; cook 2 minutes until fragrant. 3. Pour in crushed tomatoes; stir in chickpeas; season with salt and pepper; simmer 10 minutes. 4. Stir in kale and cook until wilted about 3 minutes. 5. Make 6 wells in the sauce and crack an egg into each; cover and cook 6-8 minutes until whites are set but yolks remain runny. 6. Sprinkle with crumbled feta and serve straight from the pan with crusty bread.", "tags": "one-pan, Mediterranean, eggs, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 482, \"protein\": 23.0, \"carbs\": 41.0, \"fat\": 23.0}"},
  {"name": "Butternut Squash and Goat Cheese Tart", "category": "Vegetarian", "description": "Flaky puff pastry topped with creamy goat cheese caramelized butternut squash and fresh thyme.", "servings": 6, "prepTime": 20, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 sheet\", \"name\": \"frozen puff pastry thawed\"}, {\"qty\": \"1.5 lbs\", \"name\": \"butternut squash peeled and thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"5 oz\", \"name\": \"fresh goat cheese softened\"}, {\"qty\": \"2 tbsp\", \"name\": \"heavy cream\"}, {\"qty\": \"1\", \"name\": \"garlic clove minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"arugula to serve\"}]", "instructions": "1. Preheat oven to 400°F; line a baking sheet with parchment. 2. Toss squash slices with olive oil thyme salt and pepper; spread on another baking sheet and roast 20 minutes until just tender. 3. Roll out puff pastry on prepared baking sheet and score a 1-inch border around the edge with a knife; prick inside with a fork. 4. Mix goat cheese cream garlic salt and pepper until smooth; spread over pastry inside the border. 5. Arrange roasted squash over cheese in overlapping layers; drizzle with maple syrup. 6. Bake 20-25 minutes until pastry is golden and puffed. 7. Serve warm topped with fresh arugula.", "tags": "autumn, cheese, elegant, quick", "source": "Classic", "nutritionData": "{\"calories\": 423, \"protein\": 9.0, \"carbs\": 36.0, \"fat\": 28.0}"},
  {"name": "Greek Frittata with Feta and Olives", "category": "Vegetarian", "description": "Mediterranean-style oven frittata with crumbled feta Kalamata olives roasted peppers and herbs.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"5 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"1/2 cup\", \"name\": \"Kalamata olives halved\"}, {\"qty\": \"1\", \"name\": \"roasted red pepper sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh oregano leaves\"}, {\"qty\": \"2\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"fresh dill to finish\"}]", "instructions": "1. Preheat oven to 375°F. 2. Whisk eggs and milk together; season with salt and pepper. 3. Stir in half the feta olives roasted red pepper oregano and scallions. 4. Heat olive oil in a 10-inch oven-proof skillet over medium heat; swirl to coat sides. 5. Pour in egg mixture; cook without stirring until edges begin to set about 3-4 minutes. 6. Scatter remaining feta over the top; transfer to oven and bake 12-15 minutes until center is just set and edges are golden. 7. Finish with fresh dill; slide onto a plate and cut into wedges.", "tags": "Mediterranean, gluten-free, brunch, eggs", "source": "Classic", "nutritionData": "{\"calories\": 227, \"protein\": 12.0, \"carbs\": 3.0, \"fat\": 18.0}"},
  {"name": "Tzatziki with Warm Pita", "category": "Vegetarian", "description": "Thick Greek yogurt sauce with cucumber garlic fresh dill and lemon served with warm grilled pita.", "servings": 4, "prepTime": 15, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"full-fat Greek yogurt\"}, {\"qty\": \"1\", \"name\": \"English cucumber grated\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh dill chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"4\", \"name\": \"pita breads\"}, {\"qty\": \"\", \"name\": \"olive oil for brushing\"}]", "instructions": "1. Grate cucumber and squeeze out all moisture in a clean kitchen towel. 2. In a bowl combine Greek yogurt cucumber garlic dill lemon juice olive oil salt and pepper; stir well. 3. Taste and adjust seasoning; refrigerate at least 15 minutes to meld flavors. 4. Heat a grill pan or skillet over medium-high heat; brush pita with olive oil. 5. Grill pita 1-2 minutes per side until warm and lightly charred. 6. Transfer tzatziki to a serving bowl and drizzle with olive oil. 7. Serve tzatziki alongside warm pita for dipping.", "tags": "Greek, appetizer, no-cook, gluten-free option", "source": "Classic", "nutritionData": "{\"calories\": 298, \"protein\": 18.0, \"carbs\": 41.0, \"fat\": 8.0}"},
  {"name": "Halloumi and Watermelon Salad", "category": "Vegetarian", "description": "Salty grilled halloumi with juicy watermelon cucumber fresh mint and a honey lime dressing.", "servings": 4, "prepTime": 10, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"halloumi cheese sliced 1/2-inch thick\"}, {\"qty\": \"4 cups\", \"name\": \"seedless watermelon cubed\"}, {\"qty\": \"1\", \"name\": \"English cucumber sliced into half-moons\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh mint leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"flaky sea salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}]", "instructions": "1. Heat a grill pan or skillet over medium-high heat; brush halloumi slices with olive oil. 2. Grill halloumi 2-3 minutes per side until golden grill marks form; set aside to cool slightly. 3. Whisk together lime juice honey red pepper flakes and olive oil until combined; season with salt and pepper. 4. Arrange watermelon and cucumber on a large platter. 5. Place grilled halloumi over the salad. 6. Drizzle dressing over everything and scatter fresh mint leaves on top. 7. Finish with flaky sea salt and serve immediately.", "tags": "salad, summer, gluten-free, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 254, \"protein\": 14.0, \"carbs\": 19.0, \"fat\": 14.0}"},
  {"name": "Baked Brie with Honey and Nuts", "category": "Vegetarian", "description": "Whole wheel of Brie baked until molten and topped with toasted walnuts honey and fresh thyme.", "servings": 6, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"8-oz wheel Brie cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1/4 cup\", \"name\": \"walnut halves roughly chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"\", \"name\": \"pinch of flaky sea salt\"}, {\"qty\": \"\", \"name\": \"pinch of red pepper flakes\"}, {\"qty\": \"\", \"name\": \"crackers or sliced baguette to serve\"}]", "instructions": "1. Preheat oven to 350°F. 2. Place Brie on a parchment-lined baking sheet or in a small oven-safe dish; score the top rind with a knife in a crosshatch pattern. 3. Toast walnuts in butter in a small skillet over medium heat 2-3 minutes until fragrant and golden. 4. Arrange toasted walnuts over the Brie and drizzle with honey. 5. Sprinkle with thyme leaves flaky sea salt and red pepper flakes. 6. Bake 12-15 minutes until Brie is molten and soft throughout. 7. Serve immediately with crackers or sliced baguette for spreading.", "tags": "appetizer, cheese, quick, entertaining", "source": "Classic", "nutritionData": "{\"calories\": 265, \"protein\": 10.0, \"carbs\": 17.0, \"fat\": 18.0}"},
  {"name": "Cacio e Pepe", "category": "Vegetarian", "description": "Roman pasta dish with just pecorino romano parmesan and freshly cracked black pepper in a silky sauce.", "servings": 2, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"tonnarelli or spaghetti\"}, {\"qty\": \"2 oz\", \"name\": \"finely grated pecorino romano\"}, {\"qty\": \"1 oz\", \"name\": \"finely grated parmesan\"}, {\"qty\": \"1 tsp\", \"name\": \"freshly cracked black pepper plus more to taste\"}, {\"qty\": \"\", \"name\": \"kosher salt for pasta water\"}, {\"qty\": \"2 tbsp\", \"name\": \"pasta cooking water reserved\"}]", "instructions": "1. Bring a pot of well-salted water to boil; cook pasta until al dente reserving 1/2 cup pasta water. 2. Toast cracked black pepper in a dry large skillet over medium heat until fragrant about 1 minute. 3. Add 2 tbsp pasta water to the skillet and let it reduce. 4. Add drained pasta and toss to coat in the peppery liquid. 5. Remove from heat and add combined cheeses a handful at a time tossing constantly and adding pasta water a splash at a time to create a creamy emulsified sauce. 6. Plate immediately and finish with extra grated pecorino and freshly cracked pepper.", "tags": "Italian, quick, pasta, cheese", "source": "Classic", "nutritionData": "{\"calories\": 590, \"protein\": 30.0, \"carbs\": 86.0, \"fat\": 13.0}"},
  {"name": "Greek Sheet Pan Chicken", "category": "Whole30", "description": "Juicy chicken thighs roasted with potatoes and asparagus in a bright lemon-garlic-oregano marinade.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs cut into 1-inch pieces\"}, {\"qty\": \"0.5 lb\", \"name\": \"small yellow potatoes cut into wedges\"}, {\"qty\": \"1 lb\", \"name\": \"asparagus ends trimmed\"}, {\"qty\": \"0.25 cup\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"0.25 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"lemon cut into wedges\"}, {\"qty\": \"0.25 cup\", \"name\": \"minced fresh parsley\"}]", "instructions": "1. Heat oven to 425°F conventional with rack in upper-middle position and lightly grease a rimmed baking sheet. 2. In a large bowl whisk together olive oil, lemon juice, garlic, salt, oregano, and pepper. 3. Add chicken and potatoes to the bowl and toss to coat; transfer to the prepared baking sheet. 4. Toss asparagus in the bowl to coat with remaining marinade and arrange in a single layer on the sheet alongside lemon wedges. 5. Bake 15 minutes then rotate pan 180° and switch oven to broil. 6. Broil 3 to 5 minutes until chicken is cooked through and vegetables have golden spots. 7. Remove from oven and sprinkle with parsley; squeeze charred lemon over everything before serving.", "tags": "whole30, sheet-pan, gluten-free, meal-prep", "source": "https://nomnompaleo.com/greek-sheet-pan-chicken", "nutritionData": "{\"calories\": 556, \"protein\": 48.0, \"carbs\": 17.0, \"fat\": 33.0}"},
  {"name": "Sheet Pan Italian Chicken", "category": "Whole30", "description": "Tender chicken thighs roasted with green beans, cherry tomatoes, olives, and a balsamic drizzle.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs cut into 1.5-inch cubes\"}, {\"qty\": \"1 lb\", \"name\": \"French green beans\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"0.5 cup\", \"name\": \"Castelvetrano olives pitted\"}, {\"qty\": \"1\", \"name\": \"small red onion cut into wedges\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"aged balsamic vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil or parsley minced\"}]", "instructions": "1. Heat oven to 450°F conventional with rack in the middle position. 2. Spread chicken, green beans, tomatoes, olives, onion, and garlic on a large rimmed baking sheet. 3. Sprinkle with salt and drizzle with olive oil; toss to coat and spread into a single layer. 4. Roast 15 to 25 minutes rotating the tray halfway through until chicken reaches 165°F and green beans are blistered. 5. Drizzle balsamic vinegar over everything; sprinkle fresh herbs and serve immediately.", "tags": "whole30, sheet-pan, gluten-free, quick", "source": "https://nomnompaleo.com/sheet-pan-italian-chicken", "nutritionData": "{\"calories\": 525, \"protein\": 47.0, \"carbs\": 14.0, \"fat\": 31.0}"},
  {"name": "Sheet Pan Cashew Chicken", "category": "Whole30", "description": "Savory chicken and vegetables tossed in a compliant stir-fry sauce with crunchy cashews on one pan.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts cut into bite-sized pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil divided\"}, {\"qty\": \"4 tsp\", \"name\": \"arrowroot powder divided\"}, {\"qty\": \"0.75 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"sliced carrots\"}, {\"qty\": \"1 cup\", \"name\": \"sliced celery\"}, {\"qty\": \"2 cups\", \"name\": \"sugar snap peas strings removed\"}, {\"qty\": \"0.5 cup\", \"name\": \"roasted unsalted cashews\"}, {\"qty\": \"0.5 cup\", \"name\": \"coconut aminos\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2\", \"name\": \"scallions sliced for garnish\"}]", "instructions": "1. Heat oven to 450°F conventional with rack in upper-middle position and lightly grease a large rimmed baking sheet. 2. Toss chicken with 1 tbsp arrowroot, salt, and 1 tbsp oil; transfer to sheet pan. 3. Toss carrots and celery with 1.5 tsp oil; add to pan and arrange in a single layer. 4. Bake 10 minutes until mostly cooked through. 5. Whisk coconut aminos, garlic, ginger, and remaining 1 tsp arrowroot in a small bowl. 6. Remove pan from oven and switch to broiler; add snap peas and cashews, pour sauce over everything, and toss. 7. Broil on high 3 to 5 minutes until sauce thickens and snap peas are tender-crisp. 8. Toss to coat, garnish with scallions, and serve.", "tags": "whole30, sheet-pan, nut-free-option, quick", "source": "https://nomnompaleo.com/sheet-pan-cashew-chicken", "nutritionData": "{\"calories\": 567, \"protein\": 58.0, \"carbs\": 36.0, \"fat\": 20.0}"},
  {"name": "Egg Roll in a Bowl", "category": "Whole30", "description": "A deconstructed egg roll with pork, napa cabbage, and umami-rich coconut aminos in one skillet.", "servings": 6, "prepTime": 20, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ground pork\"}, {\"qty\": \"1\", \"name\": \"small napa cabbage thinly sliced\"}, {\"qty\": \"2\", \"name\": \"medium carrots peeled and finely diced\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"0.25 lb\", \"name\": \"shiitake mushrooms stemmed and sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"ghee or avocado oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"2 tsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"fish sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"3\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}]", "instructions": "1. In a large skillet over medium heat melt ghee and sauté carrots, shallots, and mushrooms with a pinch of salt for 3 to 5 minutes until softened. 2. Add garlic and ginger; stir 30 seconds until fragrant. 3. Add ground pork with a pinch of salt, increase heat to medium-high, and cook about 5 minutes until no longer pink. 4. Transfer pork with a slotted spoon to a plate, leaving liquid in the pan. 5. Add cabbage with a pinch of salt and sauté 3 to 5 minutes until wilted. 6. Return pork to the pan and stir to combine. 7. Season with coconut aminos, rice vinegar, and fish sauce; taste and adjust. 8. Remove from heat, drizzle with sesame oil, and top with scallions. Serve over cauliflower rice.", "tags": "whole30, one-pan, low-carb, make-ahead", "source": "https://nomnompaleo.com/post/135524457693/nom-nom-paleo-app-9", "nutritionData": "{\"calories\": 484, \"protein\": 35.0, \"carbs\": 10.0, \"fat\": 34.0}"},
  {"name": "Spaghetti Squash Bolognese", "category": "Whole30", "description": "Hearty meat sauce with bacon and ground beef served over tender roasted spaghetti squash strands.", "servings": 4, "prepTime": 15, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large spaghetti squash halved and seeded\"}, {\"qty\": \"1 lb\", \"name\": \"grass-fed ground beef\"}, {\"qty\": \"4\", \"name\": \"strips bacon chopped\"}, {\"qty\": \"1\", \"name\": \"medium carrot diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"garlic-infused olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"24 oz\", \"name\": \"compliant marinara sauce (Rao's)\"}, {\"qty\": \"0.25 cup\", \"name\": \"full-fat coconut milk optional\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley or basil for garnish\"}]", "instructions": "1. Preheat oven to 400°F and line a baking sheet with parchment. Brush squash halves with oil, season with salt and pepper, and place cut-side down. 2. Roast squash 20 to 25 minutes until tender when pressed. 3. Meanwhile heat garlic oil in a large skillet over medium-high heat and sauté carrot and celery until tender, about 3 minutes. 4. Add bacon and cook until three-quarters done; drain excess fat if desired. 5. Crumble ground beef into skillet, season with salt, pepper, and oregano, and brown completely. 6. Stir in marinara and coconut milk if using; bring to a boil then simmer 5 to 10 minutes to thicken. 7. Use a fork to scrape squash strands into bowls, top with bolognese, and garnish with parsley.", "tags": "whole30, gluten-free, low-carb, meal-prep", "source": "https://www.paleorunningmomma.com/spaghetti-squash-bolognese-paleo-whole30/", "nutritionData": "{\"calories\": 650, \"protein\": 39.0, \"carbs\": 43.0, \"fat\": 39.0}"},
  {"name": "Paleo Beef Stew", "category": "Whole30", "description": "A rich and warming stew with tender beef chuck, mushrooms, carrots, and potatoes in savory broth.", "servings": 6, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"beef chuck roast cut into 2-inch cubes\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"3\", \"name\": \"carrots cut into chunks\"}, {\"qty\": \"3\", \"name\": \"stalks celery sliced\"}, {\"qty\": \"0.5 lb\", \"name\": \"cremini mushrooms quartered\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 lb\", \"name\": \"small potatoes halved\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}]", "instructions": "1. Pat beef dry and season generously with salt and pepper. 2. Heat oil in a large stock pot over medium heat. Brown beef in batches on all sides, about 2 to 3 minutes per side; remove and set aside. 3. Add mushrooms to the pot and cook until browned, about 3 minutes. Add onions, carrots, and celery; cook 3 to 5 minutes. 4. Add garlic and cook 1 minute until fragrant. 5. Stir in tomato paste, broth, thyme, and bay leaves. Return beef to the pot. 6. Bring to a boil, reduce to a simmer, cover, and cook 40 minutes. 7. Add potatoes and continue simmering uncovered 20 minutes until potatoes and beef are tender. 8. Remove bay leaves, taste for seasoning, and serve hot.", "tags": "whole30, comfort-food, make-ahead, gluten-free", "source": "https://www.paleorunningmomma.com/paleo-beef-stew-whole30-low-carb/", "nutritionData": "{\"calories\": 502, \"protein\": 45.0, \"carbs\": 22.0, \"fat\": 26.0}"},
  {"name": "Quick Beanless Chili", "category": "Whole30", "description": "A fast stovetop ground beef chili loaded with peppers, fire-roasted tomatoes, and bold spices.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"grass-fed ground beef\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"large bell pepper diced\"}, {\"qty\": \"2\", \"name\": \"small jalape\\u00f1os seeded and minced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"28 oz\", \"name\": \"can fire-roasted diced tomatoes\"}, {\"qty\": \"6 oz\", \"name\": \"can tomato paste\"}, {\"qty\": \"16 oz\", \"name\": \"beef broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"0.5 tsp\", \"name\": \"chipotle powder\"}, {\"qty\": \"1 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"\", \"name\": \"sliced avocado and cilantro for garnish\"}]", "instructions": "1. Heat oil in a large stock pot over medium-high heat. Add ground beef with salt and pepper and cook until three-quarters browned. 2. Add onion and bell pepper; cook until beef is fully browned and vegetables soften. 3. Add jalapeños and garlic; cook 1 minute. 4. Add diced tomatoes, tomato paste, broth, and all spices. Stir to combine. 5. Bring to a boil, cover, and reduce to a simmer for 15 to 20 minutes. 6. Serve hot topped with sliced avocado, cilantro, and lime wedges.", "tags": "whole30, one-pot, meal-prep, gluten-free", "source": "https://www.paleorunningmomma.com/quick-stovetop-beanless-chili-paleo-whole30-keto/", "nutritionData": "{\"calories\": 522, \"protein\": 44.0, \"carbs\": 19.0, \"fat\": 32.0}"},
  {"name": "Sausage Tomato Basil Frittata", "category": "Whole30", "description": "A protein-packed oven frittata with Italian sausage, spinach, and sliced tomatoes on top.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"Italian pork sausage casings removed\"}, {\"qty\": \"1 tbsp\", \"name\": \"coconut oil\"}, {\"qty\": \"2\", \"name\": \"large handfuls fresh spinach roughly chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil chopped plus more for garnish\"}, {\"qty\": \"8\", \"name\": \"large eggs whisked\"}, {\"qty\": \"0.5 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"0.25 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"2\", \"name\": \"roma tomatoes thinly sliced\"}, {\"qty\": \"\", \"name\": \"sea salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"pinch crushed red pepper optional\"}]", "instructions": "1. Preheat oven to 375°F. 2. Heat coconut oil in an oven-safe skillet over medium-high heat. Crumble sausage into the pan and cook, breaking up lumps, until browned. 3. Add spinach and stir until wilted; remove from heat. Sprinkle with basil. 4. Whisk eggs with onion powder and salt; pour slowly over sausage mixture in the skillet. 5. Top with sliced tomatoes; season with salt and pepper. 6. Bake 20 to 25 minutes until eggs are set and edges are golden. 7. Garnish with fresh basil and serve warm or at room temperature.", "tags": "whole30, breakfast, high-protein, gluten-free", "source": "https://www.paleorunningmomma.com/sausage-tomato-basil-frittata-paleo-whole30/", "nutritionData": "{\"calories\": 541, \"protein\": 35.0, \"carbs\": 9.0, \"fat\": 41.0}"},
  {"name": "Paleo Skillet Meatballs in Marinara", "category": "Whole30", "description": "Juicy almond-flour meatballs simmered in compliant marinara sauce for a quick weeknight dinner.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"grass-fed ground beef\"}, {\"qty\": \"0.5 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3 tbsp\", \"name\": \"almond flour\"}, {\"qty\": \"0.75 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"0.25 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"0.75 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"\", \"name\": \"pinch crushed red pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"28 oz\", \"name\": \"compliant marinara sauce (Rao's)\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. In a large bowl combine beef, pork, egg, almond flour, and seasonings. Mix gently with hands. 2. Heat oil in a large skillet over medium-high heat. Roll meat into 1.5-inch balls and place in the pan. 3. Brown meatballs on all sides about 2 to 3 minutes per side. 4. Pour marinara over meatballs and bring to a boil. 5. Cover and reduce to a simmer for 5 to 8 minutes until cooked through. 6. Uncover and simmer an additional 10 minutes if a thicker sauce is desired. 7. Garnish with parsley and serve over zucchini noodles or spaghetti squash.", "tags": "whole30, comfort-food, gluten-free, meal-prep", "source": "https://www.paleorunningmomma.com/quick-skillet-meatballs-in-sauce-paleo-whole30/", "nutritionData": "{\"calories\": 648, \"protein\": 49.0, \"carbs\": 21.0, \"fat\": 42.0}"},
  {"name": "Slow Cooker Sweet Potato Chili", "category": "Whole30", "description": "A veggie-loaded slow cooker chili with ground beef, sweet potato, and fire-roasted tomatoes.", "servings": 6, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"large sweet potato peeled and diced into 0.5-inch cubes\"}, {\"qty\": \"1\", \"name\": \"large yellow onion diced\"}, {\"qty\": \"8 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cans\", \"name\": \"(28 oz each) fire-roasted diced tomatoes\"}, {\"qty\": \"1 can\", \"name\": \"(4 oz) diced green chiles\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground cumin\"}, {\"qty\": \"0.5 tsp\", \"name\": \"chipotle powder\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"0.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}]", "instructions": "1. In a skillet over medium-high heat, brown ground beef until cooked through; drain excess fat. 2. Transfer browned beef to a slow cooker. Add sweet potato, onion, garlic, tomatoes, green chiles, tomato paste, spices, salt, pepper, and broth. 3. Stir well to combine, cover, and cook on high for 4 hours or low for 6 to 8 hours until sweet potato is tender. 4. Taste and adjust seasonings. Serve with cilantro, lime, or sliced avocado.", "tags": "whole30, slow-cooker, meal-prep, gluten-free", "source": "https://therealfooddietitians.com/slow-cooker-sweet-potato-chili/", "nutritionData": "{\"calories\": 466, \"protein\": 42.0, \"carbs\": 18.0, \"fat\": 26.0}"},
  {"name": "Whole30 Pot Roast", "category": "Whole30", "description": "Fork-tender Dutch oven pot roast braised with potatoes, carrots, and a savory herb-mustard sauce.", "servings": 6, "prepTime": 20, "cookTime": 240, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"boneless beef chuck roast\"}, {\"qty\": \"2 tbsp\", \"name\": \"arrowroot flour\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"3\", \"name\": \"carrots chopped\"}, {\"qty\": \"3\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"1.5 lbs\", \"name\": \"yellow potatoes quartered\"}]", "instructions": "1. Preheat oven to 275°F. Pat beef dry and season generously with salt and pepper. Dust with arrowroot flour to coat. 2. Heat oil in a Dutch oven over medium-high heat. Sear roast until golden on all sides, about 4 minutes per side. Transfer to a plate. 3. Reduce heat to medium and sauté onions, carrots, celery, and garlic until onions soften, about 4 minutes. 4. Stir in mustard, tomato paste, paprika, bay leaves, and thyme. Add apple cider vinegar and cook until reduced by half. 5. Pour in 0.75 cup broth and stir. Bring to a boil. Nestle roast back in, scatter potatoes around it, and pour in remaining broth. 6. Cover tightly and roast 4 to 5 hours until beef is completely tender. 7. Rest 10 minutes before serving; season to taste.", "tags": "whole30, comfort-food, make-ahead, gluten-free", "source": "https://thedefineddish.com/the-best-whole30-pot-roast/", "nutritionData": "{\"calories\": 715, \"protein\": 65.0, \"carbs\": 31.0, \"fat\": 37.0}"},
  {"name": "Instant Pot Barbacoa Beef", "category": "Whole30", "description": "Boldly spiced shredded beef with chipotle and cumin cooked in the Instant Pot in 90 minutes.", "servings": 6, "prepTime": 15, "cookTime": 100, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"boneless beef chuck roast cut into 5 to 6 pieces\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"white onion thinly sliced\"}, {\"qty\": \"1.5 cups\", \"name\": \"beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"3 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"chipotle chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}]", "instructions": "1. Season beef generously with salt. Set Instant Pot to Sauté and heat oil. Sear meat in batches on all sides about 3 minutes per side; set aside. 2. Add onions to the pot with 1 tbsp more oil and sauté 4 minutes. Hit Cancel. 3. Nestle all beef back into the pot. Whisk together broth, tomato paste, vinegar, chipotle powder, cumin, garlic, and oregano; pour over meat. Add bay leaves. 4. Seal lid, select Manual, and set to 90 minutes. 5. When done, carefully quick-release pressure. Transfer meat to a rimmed pan and shred with two forks. 6. Serve immediately with cauliflower rice, salsa, and guacamole.", "tags": "whole30, instant-pot, make-ahead, high-protein", "source": "https://thedefineddish.com/instant-pot-whole30-barbacoa/", "nutritionData": "{\"calories\": 774, \"protein\": 82.0, \"carbs\": 4.0, \"fat\": 47.0}"},
  {"name": "Whole30 Chicken Lettuce Cups", "category": "Whole30", "description": "Savory ground chicken in a coconut aminos sauce served in crisp butter lettuce cups.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground chicken\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"0.25 tsp\", \"name\": \"crushed red pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tsp\", \"name\": \"arrowroot powder\"}, {\"qty\": \"4 oz\", \"name\": \"water chestnuts diced\"}, {\"qty\": \"4 oz\", \"name\": \"shiitake mushrooms diced\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"1\", \"name\": \"head butter lettuce leaves separated\"}]", "instructions": "1. Heat avocado oil and sesame oil in a large skillet over medium-high heat. Add shallots and bell pepper; sauté 3 minutes. 2. Add garlic and ground chicken, breaking up the meat. Season with salt and pepper; cook through, about 7 minutes. 3. Whisk together coconut aminos, rice vinegar, crushed red pepper, ginger, and arrowroot in a small bowl. 4. Pour sauce into the skillet along with water chestnuts, mushrooms, and green onions. Cook 3 to 5 minutes until mushrooms are tender and sauce thickens. 5. Serve mixture in butter lettuce cups.", "tags": "whole30, quick, low-carb, gluten-free", "source": "https://thedefineddish.com/whole30-chicken-lettuce-cups/", "nutritionData": "{\"calories\": 370, \"protein\": 33.0, \"carbs\": 24.0, \"fat\": 18.0}"},
  {"name": "Blackened Pan-Seared Salmon", "category": "Whole30", "description": "Salmon fillets crusted with smoky blackened seasoning and seared to a crispy golden crust.", "servings": 4, "prepTime": 10, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets 6 oz each\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"0.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"0.5 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"0.5 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"0.25 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.25 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"0.25 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"0.5\", \"name\": \"lemon sliced into wedges\"}]", "instructions": "1. Combine all spices in a small bowl and stir to mix. 2. Evenly divide seasoning mixture among the salmon fillets and rub gently into the flesh side. 3. Heat avocado oil in a nonstick skillet over medium-high heat until hot but not smoking. 4. Place salmon flesh-side down and sear until a deep blackened crust forms, about 3 minutes. 5. Flip to skin side and cook until salmon flakes easily, 2 to 3 more minutes. 6. Serve immediately with lemon wedges.", "tags": "whole30, quick, high-protein, gluten-free", "source": "https://thedefineddish.com/blackened-pan-seared-salmon-with-whole30-tartar-sauce/", "nutritionData": "{\"calories\": 435, \"protein\": 34.0, \"carbs\": 5.0, \"fat\": 29.0}"},
  {"name": "Tex-Mex Sweet Potato Breakfast Hash", "category": "Whole30", "description": "A colorful skillet breakfast hash with sweet potato, bell pepper, mushrooms, and taco-seasoned meat.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium sweet potatoes peeled and diced\"}, {\"qty\": \"1 lb\", \"name\": \"ground beef cooked with taco seasoning\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"4 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"2\", \"name\": \"handfuls fresh spinach\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"avocado oil divided\"}, {\"qty\": \"0.5 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"4\", \"name\": \"eggs optional for topping\"}]", "instructions": "1. Heat 1 tbsp oil in a large cast iron skillet over medium heat. Add sweet potatoes, season with salt and pepper, and sauté 10 to 15 minutes until nearly cooked through. 2. Add remaining 0.5 tbsp oil along with onion, bell pepper, and mushrooms. Sauté 3 minutes until tender. 3. Fold in spinach and cooked taco meat; cook until spinach is wilted and everything is heated through. 4. Season with garlic powder, cumin, salt, and pepper. 5. If desired, create wells and crack in eggs; cover and cook until whites are set. 6. Serve hot directly from the skillet.", "tags": "whole30, breakfast, meal-prep, gluten-free", "source": "https://therealfooddietitians.com/tex-mex-sweet-potato-hash/", "nutritionData": "{\"calories\": 496, \"protein\": 39.0, \"carbs\": 21.0, \"fat\": 30.0}"},
  {"name": "Paleo Shrimp Tacos in Lettuce Cups", "category": "Whole30", "description": "Lime-marinated roasted shrimp in butter lettuce cups drizzled with creamy avocado crema.", "servings": 4, "prepTime": 40, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"peeled and deveined shrimp\"}, {\"qty\": \"0.25 cup\", \"name\": \"avocado oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh oregano minced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"zest of 1 lime\"}, {\"qty\": \"0.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"0.25 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"head butter lettuce leaves\"}, {\"qty\": \"1\", \"name\": \"small white onion finely diced\"}, {\"qty\": \"0.25 cup\", \"name\": \"cilantro minced\"}, {\"qty\": \"1\", \"name\": \"large Hass avocado\"}, {\"qty\": \"0.25 cup\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. Combine oil, oregano, garlic, and lime zest in a bowl. Add shrimp and toss to coat. Refrigerate 30 minutes. 2. Make avocado crema: blend avocado, coconut milk, cilantro, lime juice, and a pinch of salt until smooth. Refrigerate until ready. 3. Preheat oven to 400°F. Season marinated shrimp with salt and pepper and arrange on a parchment-lined baking sheet. 4. Roast 6 to 8 minutes until pink and cooked through. 5. Combine diced onion and remaining cilantro in a small bowl. 6. Arrange shrimp in lettuce leaves, top with onion-cilantro mixture, drizzle with avocado crema, and serve with lime wedges.", "tags": "whole30, quick, gluten-free, seafood", "source": "https://nomnompaleo.com/paleo-shrimp-tacos", "nutritionData": "{\"calories\": 328, \"protein\": 43.0, \"carbs\": 11.0, \"fat\": 13.0}"},
  {"name": "Chicken Cauliflower Fried Rice", "category": "Whole30", "description": "A satisfying grain-free fried rice with diced chicken, scrambled eggs, carrots, and coconut aminos.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs diced\"}, {\"qty\": \"4 cups\", \"name\": \"cauliflower rice\"}, {\"qty\": \"2\", \"name\": \"large eggs whisked\"}, {\"qty\": \"1 tsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 cup\", \"name\": \"sliced carrots\"}, {\"qty\": \"0.5\", \"name\": \"onion sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"avocado oil divided\"}, {\"qty\": \"0.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"white pepper to taste\"}]", "instructions": "1. Season chicken with 0.5 tsp salt and 1 tsp oil; set aside. 2. Heat pan over medium heat and swirl in 2 tsp oil. Pour in egg and fish sauce mixture and scramble gently into soft curds. Transfer to a plate. 3. Wipe skillet; add 2 tsp oil and sauté onion and carrots with a pinch of salt for 3 to 5 minutes. 4. Add chicken and cook stirring until cooked through. Transfer everything to a platter. 5. Add remaining oil to the pan, add garlic, then cauliflower rice. Cook 3 to 4 minutes until tender. 6. Return chicken and veggies to the pan. Add coconut aminos and white pepper; toss well. 7. Remove from heat, drizzle with sesame oil, and top with scallions.", "tags": "whole30, low-carb, quick, gluten-free", "source": "https://nomnompaleo.com/cauliflower-chicken-fried-rice", "nutritionData": "{\"calories\": 583, \"protein\": 50.0, \"carbs\": 20.0, \"fat\": 33.0}"},
  {"name": "Whole30 Beef Stew", "category": "Whole30", "description": "A hearty whole30 beef stew with tender vegetables and a rich broth cooked on the stovetop or Instant Pot.", "servings": 6, "prepTime": 15, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"beef stew meat\"}, {\"qty\": \"1 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"0.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"3\", \"name\": \"carrots sliced\"}, {\"qty\": \"3\", \"name\": \"stalks celery sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 lb\", \"name\": \"baby potatoes halved\"}]", "instructions": "1. Heat oil in a large pot over medium-high heat. Season stew meat with salt and pepper. Add meat and cook 5 minutes until browned. 2. Add all remaining ingredients to the pot and stir to combine. 3. STOVETOP: Bring to a boil, reduce to a simmer, cover, and cook 40 minutes until veggies are tender. INSTANT POT: Select Stew and cook 35 minutes. SLOW COOKER: Cook on low 8 hours or high 4 hours. 4. Optional: blend 1 cup cooked potatoes with 1 cup broth and stir back in for a thicker stew. 5. Remove bay leaves and serve.", "tags": "whole30, one-pot, comfort-food, meal-prep", "source": "https://whole30.com/recipes/whole30-beef-stew/", "nutritionData": "{\"calories\": 474, \"protein\": 44.0, \"carbs\": 21.0, \"fat\": 24.0}"},
  {"name": "Pizza Stuffed Bell Peppers", "category": "Whole30", "description": "Bell peppers stuffed with Italian ground beef and marinara topped with a creamy cashew drizzle.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bell peppers halved and seeded\"}, {\"qty\": \"1 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small yellow onion diced\"}, {\"qty\": \"4 oz\", \"name\": \"cremini mushrooms diced\"}, {\"qty\": \"0.75 cup\", \"name\": \"compliant marinara sauce (Rao's)\"}, {\"qty\": \"2 oz\", \"name\": \"compliant pepperoni chopped optional\"}, {\"qty\": \"0.5 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"0.75 cup\", \"name\": \"raw cashews\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"0.25 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"sea salt\"}]", "instructions": "1. Preheat oven to 375°F. Place pepper halves face-up in a greased baking dish; pour 0.5 cup water into the bottom of the dish. 2. Heat oil in a large skillet over medium-high heat. Sauté onion until translucent then add mushrooms until softened. 3. Crumble beef into the skillet, season with salt, pepper, and oregano, and brown completely. Stir in sauce and pepperoni if using; cook 1 minute. 4. Spoon filling into pepper halves. Bake 20 minutes until peppers are slightly tender. 5. Meanwhile blend cashews, lemon juice, water, garlic powder, and salt until smooth to make the cashew cream. 6. Remove peppers from oven, drizzle with cashew cream, and serve.", "tags": "whole30, make-ahead, gluten-free, comfort-food", "source": "https://www.paleorunningmomma.com/pizza-stuffed-peppers-paleo-whole30/", "nutritionData": "{\"calories\": 662, \"protein\": 42.0, \"carbs\": 29.0, \"fat\": 43.0}"},
  {"name": "Whole30 Beef Tacos in Lettuce Wraps", "category": "Whole30", "description": "Richly seasoned Instant Pot ground beef taco meat served in crisp butter lettuce leaves with avocado.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"white onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o minced\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"coriander\"}, {\"qty\": \"0.5 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"14 oz\", \"name\": \"can crushed tomatoes\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"1\", \"name\": \"head butter lettuce leaves\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Set Instant Pot to Sauté. Add beef and cook 5 minutes breaking up meat until browned. Season with salt and pepper. 2. Add onion, bell pepper, garlic, and jalapeño. Cook stirring until vegetables soften, about 5 minutes. 3. Stir in paprika, chili powder, coriander, and cumin. Add coconut aminos and crushed tomatoes; scrape up any browned bits. 4. Lock lid and select Meat/Stew; cook 10 minutes. Natural release 10 minutes then quick release. 5. Serve meat mixture in lettuce leaves topped with avocado slices and cilantro.", "tags": "whole30, instant-pot, quick, gluten-free", "source": "https://whole30.com/recipes/slow-cooker-3/", "nutritionData": "{\"calories\": 568, \"protein\": 47.0, \"carbs\": 21.0, \"fat\": 35.0}"},
  {"name": "Cracklin Chicken Thighs", "category": "Whole30", "description": "Crispy-skinned chicken thighs cooked low and slow in a cast iron skillet for maximum crunch.", "servings": 4, "prepTime": 5, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"0.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"0.5 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"\", \"name\": \"fresh lemon wedges for serving\"}, {\"qty\": \"\", \"name\": \"fresh thyme or parsley for garnish\"}]", "instructions": "1. Pat chicken thighs completely dry with paper towels. Season all over with salt, pepper, garlic powder, and paprika. 2. Place chicken skin-side down in a cold cast iron skillet. Turn heat to medium-low. 3. Cook undisturbed 25 to 30 minutes until skin is deeply golden and crispy, slowly rendering the fat. 4. Flip chicken and cook 5 to 8 more minutes until cooked through and an instant-read thermometer reads 165°F. 5. Transfer to a plate, rest 5 minutes, and serve with lemon wedges and fresh herbs.", "tags": "whole30, quick, high-protein, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 328, \"protein\": 26.0, \"carbs\": 2.0, \"fat\": 23.0}"},
  {"name": "Zucchini Noodles with Meat Sauce", "category": "Whole30", "description": "Spiralized zucchini noodles topped with a rich ground beef and tomato meat sauce.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"24 oz\", \"name\": \"compliant marinara sauce (Rao's)\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"0.5 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"4\", \"name\": \"medium zucchini spiralized\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Heat a large skillet over medium-high heat. Crumble in ground beef, season with salt and pepper, and cook until browned about 8 minutes. 2. Drain excess fat. Add onion and garlic; cook 3 minutes until softened. 3. Stir in marinara, basil, oregano, and red pepper flakes. Simmer uncovered 15 minutes until sauce thickens. 4. Meanwhile heat olive oil in a separate skillet over medium heat. Add zucchini noodles and toss 2 to 3 minutes until just tender. 5. Season zucchini with salt. Divide into bowls and top with meat sauce and fresh basil.", "tags": "whole30, low-carb, quick, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 610, \"protein\": 50.0, \"carbs\": 24.0, \"fat\": 36.0}"},
  {"name": "Chicken Vegetable Soup", "category": "Whole30", "description": "A comforting classic chicken soup with tender thighs, potatoes, carrots, and herbed broth.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs diced into 1-inch pieces\"}, {\"qty\": \"2 cups\", \"name\": \"carrots diced\"}, {\"qty\": \"1 lb\", \"name\": \"red potatoes quartered\"}, {\"qty\": \"1\", \"name\": \"white onion sliced\"}, {\"qty\": \"5\", \"name\": \"ribs celery diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"minced garlic\"}, {\"qty\": \"5 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"arrowroot flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1.5 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}]", "instructions": "1. Heat olive oil in a large stock pot over medium-high heat. Season chicken with salt and pepper, add to pot, and cook on high heat 6 minutes until browned. Remove and set aside. 2. Add onion, celery, carrot, and garlic to the pot. Cook 4 to 5 minutes until onion softens, scraping up browned bits. 3. Whisk arrowroot with 1 cup broth until dissolved; pour into pot. 4. Add chicken back along with remaining broth, potatoes, parsley, rosemary, and bay leaves. Stir to combine. 5. Bring to a simmer, cover, reduce heat to medium, and cook 30 minutes until potatoes and carrots are soft. 6. Discard bay leaves, taste for seasoning, and serve hot.", "tags": "whole30, one-pot, meal-prep, gluten-free", "source": "https://www.wholekitchensink.com/whole30-chicken-soup/", "nutritionData": "{\"calories\": 392, \"protein\": 33.0, \"carbs\": 24.0, \"fat\": 17.0}"},
  {"name": "Ground Beef and Sweet Potato Skillet", "category": "Whole30", "description": "A hearty one-pan dinner with seasoned ground beef, sweet potato, and spinach ready in 30 minutes.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground beef\"}, {\"qty\": \"2\", \"name\": \"medium sweet potatoes peeled and diced small\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"0.5 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Heat oil in a large skillet over medium-high heat. Add sweet potatoes and cook stirring occasionally 10 to 12 minutes until golden and fork-tender. Remove and set aside. 2. Add ground beef to the skillet and cook breaking it up until browned. Drain excess fat if desired. 3. Add onion and garlic to the beef; cook 3 minutes until softened. 4. Season with smoked paprika, cumin, chili powder, garlic powder, onion powder, salt, and pepper. 5. Return sweet potatoes to the skillet, stir to combine, and cook 2 minutes to heat through. 6. Fold in spinach until wilted. Garnish with parsley and serve.", "tags": "whole30, one-pan, quick, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 550, \"protein\": 46.0, \"carbs\": 21.0, \"fat\": 33.0}"},
  {"name": "Baked Chicken Thighs with Roasted Vegetables", "category": "Whole30", "description": "Juicy oven-baked chicken thighs seasoned with herbs over a colorful medley of roasted vegetables.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"zucchini sliced\"}, {\"qty\": \"1\", \"name\": \"yellow squash sliced\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"1\", \"name\": \"medium red onion cut into wedges\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Italian herbs\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"0.5 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Preheat oven to 425°F. Toss all vegetables with 2 tbsp olive oil, garlic, salt, and pepper; spread on a large rimmed baking sheet. 2. Pat chicken thighs dry and rub with remaining 1 tbsp olive oil, Italian herbs, paprika, salt, and pepper. 3. Nestle chicken thighs among the vegetables skin-side up. 4. Roast 35 to 40 minutes until chicken is golden and reads 165°F and vegetables are caramelized. 5. Rest 5 minutes, garnish with fresh basil, and serve.", "tags": "whole30, sheet-pan, gluten-free, easy", "source": "Classic", "nutritionData": "{\"calories\": 444, \"protein\": 29.0, \"carbs\": 14.0, \"fat\": 31.0}"},
  {"name": "Paleo Shrimp Stir-Fry", "category": "Whole30", "description": "A saucy whole30 shrimp stir-fry with snap peas, carrots, and zucchini in a coconut aminos sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"peeled deveined shrimp\"}, {\"qty\": \"2\", \"name\": \"zucchini sliced into strips\"}, {\"qty\": \"1\", \"name\": \"green bell pepper sliced\"}, {\"qty\": \"1 cup\", \"name\": \"sugar snap peas\"}, {\"qty\": \"1 cup\", \"name\": \"shredded carrots\"}, {\"qty\": \"0.5\", \"name\": \"red onion sliced\"}, {\"qty\": \"0.5 cup\", \"name\": \"green onions chopped\"}, {\"qty\": \"0.33 cup\", \"name\": \"coconut aminos\"}, {\"qty\": \"0.33 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1 tbsp\", \"name\": \"minced garlic\"}, {\"qty\": \"0.5 tbsp\", \"name\": \"minced ginger\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. In a large skillet over medium heat heat 1 tbsp oil. Add garlic and ginger; cook until fragrant. Add shrimp with salt and pepper; cook 4 minutes per side until done. Remove and set aside. 2. Add 1 tbsp oil to the pan and sauté zucchini until fork-tender. Remove and set aside. 3. Add remaining 1 tbsp oil to the pan. Add onion, bell pepper, carrots, and snap peas; stir-fry 6 to 8 minutes until crisp-tender. 4. Whisk coconut aminos and broth together; pour into pan and stir. 5. Return shrimp and zucchini to the pan and cook 2 minutes until heated through and sauce thickens. 6. Garnish with sesame seeds and green onion; serve.", "tags": "whole30, seafood, quick, gluten-free", "source": "https://www.wholekitchensink.com/paleo-shrimp-stir-fry/", "nutritionData": "{\"calories\": 390, \"protein\": 32.0, \"carbs\": 42.0, \"fat\": 12.0}"},
  {"name": "Turkey Stuffed Acorn Squash", "category": "Whole30", "description": "Roasted acorn squash halves filled with seasoned ground turkey and sautéed vegetables.", "servings": 4, "prepTime": 15, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium acorn squash halved and seeded\"}, {\"qty\": \"1 lb\", \"name\": \"ground turkey\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"0.5 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"14 oz\", \"name\": \"can fire-roasted diced tomatoes drained\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Preheat oven to 400°F. Brush squash cut sides with 1 tbsp oil, season with salt and pepper, and place cut-side down on a baking sheet. Roast 25 to 30 minutes until tender. 2. Meanwhile heat remaining oil in a large skillet over medium-high heat. Sauté onion, bell pepper, and celery 4 minutes until softened. 3. Add garlic and cook 1 minute. Add ground turkey and brown breaking it up, about 8 minutes. 4. Season with cumin, paprika, chili powder, salt, and pepper. Stir in drained tomatoes and cook 3 minutes to combine. 5. Flip roasted squash halves cut-side up. Fill each half generously with turkey mixture. 6. Return to oven and bake 10 more minutes. Garnish with cilantro and serve.", "tags": "whole30, gluten-free, make-ahead, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 413, \"protein\": 34.0, \"carbs\": 30.0, \"fat\": 18.0}"},
  {"name": "Whole30 Egg and Veggie Breakfast Casserole", "category": "Whole30", "description": "A make-ahead frittata-style casserole with eggs, sausage, and colorful vegetables perfect for meal prep.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"large eggs\"}, {\"qty\": \"1 lb\", \"name\": \"compliant breakfast sausage\"}, {\"qty\": \"1\", \"name\": \"yellow onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2 cups\", \"name\": \"fresh spinach\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"0.5 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"0.5 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 375°F. Grease a 9x13 baking dish with avocado oil. 2. Heat a large skillet over medium heat. Brown sausage breaking it up until cooked; remove with a slotted spoon and place in baking dish. 3. In the same skillet sauté onion in the remaining fat for 2 minutes. Add garlic and bell pepper; cook 3 minutes. Stir in spinach until wilted. Transfer to baking dish. 4. Whisk eggs with garlic powder, onion powder, oregano, salt, and pepper. Pour over sausage and vegetable mixture. 5. Bake 25 to 30 minutes until eggs are fully set and edges are golden. 6. Cool slightly, slice into portions, and serve. Store leftovers in the fridge up to 5 days.", "tags": "whole30, breakfast, meal-prep, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 400, \"protein\": 26.0, \"carbs\": 8.0, \"fat\": 29.0}"},
  {"name": "Coconut Lime Baked Chicken", "category": "Whole30", "description": "Tender baked chicken thighs marinated in coconut milk, lime, and garlic with a hint of ginger.", "servings": 4, "prepTime": 40, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"0.75 cup\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"lime zest\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"coconut aminos\"}, {\"qty\": \"0.5 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"0.5 tsp\", \"name\": \"cumin\"}, {\"qty\": \"0.25 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"\", \"name\": \"fresh cilantro and lime wedges for serving\"}]", "instructions": "1. In a bowl whisk coconut milk, lime juice, lime zest, garlic, ginger, fish sauce, coconut aminos, turmeric, cumin, and cayenne. 2. Add chicken to the marinade and toss to coat. Refrigerate at least 30 minutes and up to overnight. 3. Preheat oven to 400°F. Transfer chicken and marinade to a baking dish in a single layer. 4. Bake 30 to 35 minutes until chicken reads 165°F and the sauce is bubbling. 5. Broil for 2 to 3 minutes to caramelize the top. 6. Garnish with fresh cilantro and serve with lime wedges and cauliflower rice.", "tags": "whole30, make-ahead, gluten-free, high-protein", "source": "Classic", "nutritionData": "{\"calories\": 496, \"protein\": 46.0, \"carbs\": 10.0, \"fat\": 30.0}"},
  {"name": "Pumpkin Chili", "category": "Whole30", "description": "A cozy ground beef and pork chili enriched with pumpkin puree that adds body and subtle warmth.", "servings": 6, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"grass-fed ground beef\"}, {\"qty\": \"0.5 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"large green bell pepper diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o minced\"}, {\"qty\": \"28 oz\", \"name\": \"can crushed tomatoes\"}, {\"qty\": \"14.5 oz\", \"name\": \"can diced tomatoes\"}, {\"qty\": \"15 oz\", \"name\": \"can pumpkin puree\"}, {\"qty\": \"2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"0.75 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"0.25 tsp\", \"name\": \"chipotle powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1.5 tsp\", \"name\": \"pumpkin spice\"}, {\"qty\": \"0.75 tsp\", \"name\": \"sea salt\"}, {\"qty\": \"0.5 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"\", \"name\": \"cilantro and avocado for garnish\"}]", "instructions": "1. Heat a Dutch oven over medium-high heat and add oil. Add beef and pork, season with salt and pepper, and brown while breaking up the meat. 2. Once two-thirds browned add onion and bell pepper. Cook 2 minutes until beef is fully browned. Do not drain all the fat. 3. Add garlic and jalapeño; stir and cook 1 minute. 4. Lower heat and add crushed tomatoes, diced tomatoes, pumpkin puree, salt, and all spices. Stir to combine well. 5. Raise heat to bring to a boil then lower to a slow simmer. Cover and simmer at least 15 minutes and up to 45 minutes for deeper flavor. 6. Serve topped with cilantro, sliced avocado, and a squeeze of lime.", "tags": "whole30, one-pot, meal-prep, comfort-food", "source": "https://www.paleorunningmomma.com/paleo-pumpkin-chili-whole30/", "nutritionData": "{\"calories\": 424, \"protein\": 32.0, \"carbs\": 20.0, \"fat\": 26.0}"},
  {"name": "Spatchcock Roast Chicken", "category": "Chicken", "description": "Butterflied whole chicken roasted at high heat for ultra-crispy skin and juicy meat in under an hour.", "servings": 4, "prepTime": 15, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken about 4 lbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"lemon halved\"}]", "instructions": "1. Preheat oven to 450°F. Place chicken breast-side down and cut along both sides of backbone with kitchen shears to remove it. 2. Flip chicken breast-side up and press firmly on breastbone to flatten. Pat dry with paper towels. 3. Mix butter, garlic, thyme, rosemary, salt, and pepper. Slide butter mixture under the skin over breasts and thighs. 4. Rub outside of chicken with olive oil and season with salt and pepper. Place on a rimmed baking sheet. 5. Roast at 450°F for 40–45 minutes until thickest part of thigh reads 160°F. Rest 10 minutes before carving. 6. Squeeze lemon over carved chicken before serving.", "tags": "roast chicken, crispy skin, family dinner", "source": "https://www.seriouseats.com/the-food-lab-ultra-crispy-spatchcocked-roast-chicken", "nutritionData": "{\"calories\": 457, \"protein\": 59.0, \"carbs\": 1.0, \"fat\": 23.0}"},
  {"name": "Classic Roast Chicken with Pan Jus", "category": "Chicken", "description": "Timeless whole roast chicken with herb butter and a rich pan sauce made from drippings.", "servings": 4, "prepTime": 20, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken about 4 lbs\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"1\", \"name\": \"lemon zested and halved\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1\", \"name\": \"small onion quartered\"}, {\"qty\": \"2\", \"name\": \"carrots roughly chopped\"}]", "instructions": "1. Preheat oven to 425°F. Pat chicken dry and let sit at room temperature 30 minutes. 2. Mix butter, garlic, thyme, parsley, lemon zest, salt, and pepper. Slide most of the herb butter under the skin. Rub remaining on outside. 3. Stuff cavity with lemon halves and onion. Tie legs with twine. 4. Place carrots and onion in roasting pan. Set chicken on top. Roast 60–70 minutes until thigh reads 165°F. 5. Rest chicken 15 minutes on a cutting board. 6. Deglaze roasting pan with chicken stock, scraping up browned bits. Simmer 3 minutes for pan jus. Serve with carved chicken.", "tags": "classic, roast chicken, Sunday dinner", "source": "Classic", "nutritionData": "{\"calories\": 501, \"protein\": 59.0, \"carbs\": 2.0, \"fat\": 28.0}"},
  {"name": "Buttermilk Fried Chicken", "category": "Chicken", "description": "Crispy-crunchy buttermilk-brined fried chicken with a perfectly seasoned double-dredged coating.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"bone-in skin-on chicken pieces\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"2 tsp\", \"name\": \"hot sauce\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}]", "instructions": "1. Combine buttermilk and hot sauce in a large bowl. Add chicken, cover, and refrigerate at least 4 hours or overnight. 2. Mix flour, garlic powder, onion powder, paprika, cayenne, salt, pepper, and baking powder in a shallow dish. 3. Remove chicken from marinade, letting excess drip off. Dredge in seasoned flour, pressing firmly. Dip back in remaining buttermilk then dredge again in flour. 4. Heat 3 inches of vegetable oil in a Dutch oven to 350°F. 5. Fry chicken in batches, maintaining oil at 325°F, 12–15 minutes for breasts and wings, 14–18 minutes for thighs and legs until deeply golden and 165°F internal. 6. Drain on wire rack and season with salt immediately.", "tags": "fried chicken, Southern, crispy", "source": "Classic", "nutritionData": "{\"calories\": 586, \"protein\": 44.0, \"carbs\": 31.0, \"fat\": 28.0}"},
  {"name": "Nashville Hot Chicken", "category": "Chicken", "description": "Fiery spiced fried chicken slathered in cayenne-laced hot oil and served over white bread with pickles.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"bone-in chicken pieces\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"1/4 cup\", \"name\": \"pickle brine\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"lard or vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"4 slices\", \"name\": \"white bread\"}, {\"qty\": \"\", \"name\": \"Pickle slices for serving\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}]", "instructions": "1. Whisk buttermilk, pickle brine, and egg together. Add chicken, cover, and marinate 2–4 hours in refrigerator. 2. Mix flour and salt in a shallow dish. Remove chicken from marinade and blot dry. Dredge in flour, return to marinade, then dredge again in flour. Rest on rack 15 minutes. 3. Melt butter and lard in a small saucepan. Add cayenne, brown sugar, paprika, and garlic powder. Stir until combined. Keep warm. 4. Heat vegetable oil in a cast iron skillet to 350°F. Fry chicken 10–12 minutes per side until 165°F internal. 5. Transfer to rack. Brush hot sauce all over each piece. 6. Serve chicken on slices of white bread with pickle slices.", "tags": "Nashville hot, fried chicken, spicy", "source": "https://www.allrecipes.com/recipe/254804/chef-johns-nashville-hot-chicken/", "nutritionData": "{\"calories\": 841, \"protein\": 43.0, \"carbs\": 45.0, \"fat\": 51.0}"},
  {"name": "Korean Fried Chicken", "category": "Chicken", "description": "Double-fried chicken wings tossed in a sweet and spicy gochujang glaze with sesame seeds.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chicken wings cut at joint\"}, {\"qty\": \"1/2 cup\", \"name\": \"potato starch\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}, {\"qty\": \"3 tbsp\", \"name\": \"gochujang\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}]", "instructions": "1. Pat wings dry. Toss in mixture of potato starch, flour, salt, and pepper. Rest on a rack for 15 minutes. 2. Heat oil in large pot to 325°F. Fry wings in batches 8–10 minutes until lightly golden but not fully cooked. Drain on rack. 3. Raise oil temperature to 400°F. Fry wings again 2–3 minutes until deep golden and very crispy. 4. Make glaze: combine gochujang, soy sauce, honey, rice vinegar, sesame oil, garlic, and ginger in a small saucepan. Simmer 2 minutes. 5. Toss hot fried wings in glaze until fully coated. 6. Transfer to platter, sprinkle with sesame seeds and green onions. Serve immediately.", "tags": "Korean, fried chicken, wings, spicy-sweet", "source": "Classic", "nutritionData": "{\"calories\": 590, \"protein\": 30.0, \"carbs\": 42.0, \"fat\": 27.0}"},
  {"name": "Chicken Pot Pie", "category": "Chicken", "description": "Creamy chicken and vegetable filling encased in a flaky double-crust pie shell for ultimate comfort.", "servings": 6, "prepTime": 30, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breast diced\"}, {\"qty\": \"2 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"2\", \"name\": \"carrots diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"store-bought pie crusts 9-inch\"}, {\"qty\": \"1\", \"name\": \"egg beaten for egg wash\"}]", "instructions": "1. Preheat oven to 375°F. Cook chicken in simmering broth until done, about 12 minutes. Remove chicken; reserve broth. Shred or dice chicken. 2. Melt butter in large saucepan over medium heat. Sauté onion, carrots, celery, and garlic until softened, 5–6 minutes. 3. Stir in flour; cook 1 minute. Gradually whisk in reserved broth and milk. Simmer until thickened, about 5 minutes. 4. Add peas, cooked chicken, thyme, salt, and pepper. Stir to combine. 5. Fit one pie crust into a 9-inch pie dish. Pour in filling. Top with second crust, crimp edges, and cut vents. Brush with egg wash. 6. Bake 35–40 minutes until crust is golden brown. Rest 10 minutes before serving.", "tags": "pot pie, comfort food, chicken dinner", "source": "Classic", "nutritionData": "{\"calories\": 662, \"protein\": 43.0, \"carbs\": 43.0, \"fat\": 30.0}"},
  {"name": "Chicken Parmesan", "category": "Chicken", "description": "Breaded and pan-fried chicken cutlets topped with marinara and melted mozzarella, baked to perfection.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts about 1.5 lbs\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1.5 cups\", \"name\": \"marinara sauce\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella cheese\"}, {\"qty\": \"\", \"name\": \"Fresh basil for serving\"}]", "instructions": "1. Slice chicken breasts in half horizontally to create 4 thin cutlets. Pound to 1/4-inch thickness. Season with salt and pepper. 2. Set up breading stations: flour in one shallow dish, beaten eggs in a second, panko mixed with Parmesan, garlic powder, and Italian seasoning in a third. 3. Dredge cutlets in flour, then egg, then panko-Parmesan mixture, pressing to adhere. 4. Heat olive oil in an oven-safe skillet over medium-high. Cook cutlets 2–3 minutes per side until golden. 5. Transfer to a baking dish. Spoon marinara over each cutlet. Top with mozzarella. 6. Bake at 400°F for 10–12 minutes until cheese is melted and bubbly. Garnish with fresh basil.", "tags": "Italian, chicken parmesan, weeknight dinner", "source": "https://www.seriouseats.com/chicken-parmesan", "nutritionData": "{\"calories\": 750, \"protein\": 74.0, \"carbs\": 41.0, \"fat\": 30.0}"},
  {"name": "Chicken Marsala", "category": "Chicken", "description": "Tender pan-seared chicken cutlets in a rich Marsala wine and mushroom cream sauce.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts about 1.5 lbs\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour seasoned\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"3\", \"name\": \"shallots minced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3/4 cup\", \"name\": \"dry Marsala wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"\", \"name\": \"Fresh parsley for serving\"}]", "instructions": "1. Slice chicken breasts in half horizontally. Pound to 1/4-inch thickness. Season with salt and pepper, then dredge lightly in flour. 2. Heat olive oil and 1 tbsp butter in a large skillet over medium-high. Cook cutlets 2–3 minutes per side until golden. Remove to a plate. 3. Add remaining butter to skillet. Sauté mushrooms 4–5 minutes until browned. Add shallots and garlic; cook 1 minute. 4. Pour in Marsala wine, scraping up browned bits. Simmer 2 minutes. Add chicken broth; simmer another 2 minutes. 5. Stir in heavy cream and thyme. Simmer until sauce thickens slightly, about 3 minutes. 6. Return chicken to pan and warm through 2 minutes. Serve garnished with parsley.", "tags": "Italian, chicken marsala, mushroom sauce", "source": "https://www.recipetineats.com/chicken-marsala/", "nutritionData": "{\"calories\": 579, \"protein\": 57.0, \"carbs\": 15.0, \"fat\": 27.0}"},
  {"name": "Chicken Piccata", "category": "Chicken", "description": "Thin chicken cutlets in a bright lemon-butter-caper pan sauce that comes together in under 30 minutes.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts about 1.5 lbs\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1\", \"name\": \"large egg beaten\"}, {\"qty\": \"3/4 cup\", \"name\": \"seasoned breadcrumbs\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter divided\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1/3 cup\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers drained\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}]", "instructions": "1. Slice chicken breasts horizontally in half. Place in a zip-lock bag and pound to 1/4-inch thickness. Season with salt and pepper. 2. Dredge cutlets in flour, dip in egg, then press into breadcrumbs to coat. 3. Heat oil in a large skillet over medium-high. Cook cutlets 2–3 minutes per side until golden. Transfer to a baking sheet and keep warm in 350°F oven. 4. Discard excess oil. Add chicken broth and lemon juice to skillet. Bring to a boil, scraping up browned bits. Simmer 2 minutes until slightly reduced. 5. Remove from heat. Swirl in 2 tbsp butter and capers. Taste and season. 6. Plate chicken, spoon sauce over top, and garnish with parsley.", "tags": "Italian, lemon, quick dinner", "source": "https://www.onceuponachef.com/recipes/chicken-piccata.html", "nutritionData": "{\"calories\": 564, \"protein\": 58.0, \"carbs\": 24.0, \"fat\": 24.0}"},
  {"name": "Chicken Cacciatore", "category": "Chicken", "description": "Rustic Italian braised chicken with tomatoes, mushrooms, peppers, and olives in a rich wine sauce.", "servings": 4, "prepTime": 20, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"4\", \"name\": \"chicken drumsticks\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"onion sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"14 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"2\", \"name\": \"rosemary sprigs\"}, {\"qty\": \"1/4 cup\", \"name\": \"pitted black olives\"}]", "instructions": "1. Season chicken with salt and pepper. Heat olive oil in a large heavy pot over high heat. Sear chicken skin-side down 6 minutes until deep golden. Flip and cook 1 minute. Remove to a plate. 2. Reduce heat to medium. Sauté onion and rosemary 3 minutes. Add garlic, anchovies (if using), and cook 1 minute. 3. Add bell pepper and mushrooms; cook 5 minutes. Add tomato paste and cook 2 minutes. 4. Pour in red wine and simmer until reduced by 75%. Add crushed tomatoes, stock, and oregano. Stir to combine. 5. Return chicken skin-side up to pot. Cover and simmer 20 minutes. Remove lid, add olives, and simmer uncovered 10 minutes until sauce thickens. 6. Discard rosemary sprigs. Serve over mashed potatoes or polenta.", "tags": "Italian, braised, comfort food, one pot", "source": "https://www.recipetineats.com/chicken-cacciatore-italian-chicken-stew/", "nutritionData": "{\"calories\": 465, \"protein\": 49.0, \"carbs\": 10.0, \"fat\": 23.0}"},
  {"name": "Butter Chicken", "category": "Chicken", "description": "Tender yogurt-marinated chicken simmered in a velvety spiced tomato-cream sauce.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"tandoori masala\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"14 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"Salt to taste\"}, {\"qty\": \"\", \"name\": \"Fresh cilantro for serving\"}]", "instructions": "1. Mix yogurt, tandoori masala, and lemon juice. Add chicken, coat well. Marinate at least 3 hours or overnight. 2. Heat 1 tbsp ghee in a skillet over high heat. Cook chicken 3–4 minutes per side until charred at edges. Remove and set aside. 3. Heat remaining ghee over medium heat. Sauté onion until golden, 8 minutes. Add garlic and ginger; cook 1 minute. 4. Add chili powder, coriander, and cumin; cook 1 minute. Add crushed tomatoes and simmer 10 minutes. Blend sauce smooth with an immersion blender. 5. Return to heat. Add cream, sugar, and salt. Simmer 5 minutes. Add cooked chicken and heat through. 6. Stir in garam masala. Serve over basmati rice topped with fresh cilantro.", "tags": "Indian, curry, butter chicken, creamy", "source": "https://www.recipetineats.com/butter-chicken/", "nutritionData": "{\"calories\": 585, \"protein\": 49.0, \"carbs\": 12.0, \"fat\": 37.0}"},
  {"name": "Chicken Tikka Masala", "category": "Chicken", "description": "Charred tandoori chicken in a rich, aromatic tomato-cream masala sauce — a global comfort classic.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"garam masala\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee or butter\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"14 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"Salt to taste\"}, {\"qty\": \"\", \"name\": \"Fresh cilantro to serve\"}]", "instructions": "1. Mix yogurt, half the garam masala, 1 tsp cumin, paprika, and turmeric. Add chicken; marinate 3 hours to overnight. 2. Broil marinated chicken on high, 5–6 minutes per side until charred at edges and cooked through. Cut into chunks. 3. Melt ghee in a large pan over medium heat. Sauté onion 8 minutes until golden. Add garlic and ginger; cook 2 minutes. 4. Add remaining spices and cook 1 minute. Add crushed tomatoes; simmer covered 10 minutes. Blend until smooth. 5. Stir in cream and sugar. Simmer 5 minutes. Add chicken chunks and remaining garam masala. 6. Cook 3 minutes until heated through. Serve over basmati rice with cilantro.", "tags": "Indian, tikka masala, curry, creamy", "source": "https://www.recipetineats.com/chicken-tikka-masala/", "nutritionData": "{\"calories\": 648, \"protein\": 49.0, \"carbs\": 15.0, \"fat\": 44.0}"},
  {"name": "Coq au Vin", "category": "Chicken", "description": "Classic French braised chicken with red wine, bacon, pearl onions, and earthy mushrooms.", "servings": 4, "prepTime": 30, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"4\", \"name\": \"chicken drumsticks\"}, {\"qty\": \"1\", \"name\": \"bottle 750ml dry red wine\"}, {\"qty\": \"4 oz\", \"name\": \"thick-cut bacon lardons\"}, {\"qty\": \"1 cup\", \"name\": \"pearl onions peeled\"}, {\"qty\": \"8 oz\", \"name\": \"button mushrooms halved\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"\", \"name\": \"Fresh parsley for serving\"}]", "instructions": "1. Marinate chicken overnight in red wine with thyme, bay leaves, and garlic. Drain; reserve wine. Pat chicken dry. 2. Render bacon lardons in a Dutch oven over medium heat until crisp. Remove. Brown chicken on all sides in bacon fat. Remove. 3. Sauté pearl onions until golden. Remove. Add mushrooms; cook 5 minutes. Remove. Add garlic and tomato paste; cook 1 minute. 4. Add flour; stir 1 minute. Pour in reserved wine (reduced by half) and chicken broth. Bring to a simmer. 5. Return chicken, bacon, and onions to pot. Cover and cook in 325°F oven 45 minutes. 6. Add mushrooms and simmer uncovered 10 minutes to thicken sauce. Serve garnished with parsley.", "tags": "French, braised, red wine, classic", "source": "https://www.recipetineats.com/coq-au-vin/", "nutritionData": "{\"calories\": 626, \"protein\": 57.0, \"carbs\": 11.0, \"fat\": 33.0}"},
  {"name": "Filipino Chicken Adobo", "category": "Chicken", "description": "Chicken braised in soy sauce and vinegar with garlic and bay leaves until the sauce reduces to a sticky glaze.", "servings": 4, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1/3 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/3 cup\", \"name\": \"white vinegar\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced plus 3 cloves for cooking\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"4\", \"name\": \"bay leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"whole black peppercorns\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1.5 cups\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"green onions sliced\"}, {\"qty\": \"\", \"name\": \"Steamed white rice for serving\"}]", "instructions": "1. Combine chicken, soy sauce, vinegar, 3 minced garlic cloves, and bay leaves in a bowl. Marinate at least 20 minutes. 2. Heat oil in a large skillet over high heat. Remove chicken from marinade (reserve marinade); sear 1 minute per side until browned. Remove. 3. Sauté remaining garlic and onion in same pan 1.5 minutes. 4. Add reserved marinade, water, brown sugar, and peppercorns. Bring to a simmer. 5. Add chicken smooth-side down. Simmer uncovered 20–25 minutes, turning at 15 minutes, until sauce reduces to a thick syrupy glaze. 6. Serve over steamed rice, garnished with green onions.", "tags": "Filipino, adobo, braised, weeknight", "source": "https://www.recipetineats.com/filipino-chicken-adobo-flavour-kapow/", "nutritionData": "{\"calories\": 401, \"protein\": 37.0, \"carbs\": 9.0, \"fat\": 22.0}"},
  {"name": "Chicken and Dumplings", "category": "Chicken", "description": "Hearty chicken soup with tender vegetables and fluffy herb-flecked dumplings cooked directly in the broth.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"6 tbsp\", \"name\": \"salted butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh sage chopped\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1 cup\", \"name\": \"celery diced\"}, {\"qty\": \"1 cup\", \"name\": \"carrots diced\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"1.5 cups\", \"name\": \"all-purpose flour for dumplings\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh sage for dumplings\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk for dumplings\"}]", "instructions": "1. In a large pot over medium heat, melt butter. Whisk in 1/3 cup flour and garlic to form a roux; cook 5 minutes. 2. Add thyme, sage, onion, celery, and carrots. Pour in broth and season with salt and pepper. Add chicken breasts whole. Cover and simmer 20 minutes until chicken is cooked through. 3. Remove chicken and shred with two forks. Stir in 2 cups milk. Return shredded chicken to pot. 4. Make dumplings: combine 1.5 cups flour, baking powder, sage, and pepper. Add 3/4 cup milk; mix until just combined. 5. Drop heaping tablespoons of dumpling dough into simmering soup. Cover and cook on low heat 15–20 minutes until dumplings are cooked through and puffy. 6. Ladle into bowls with dumplings and garnish with thyme.", "tags": "comfort food, soup, dumplings, chicken", "source": "https://www.halfbakedharvest.com/crockpot-chicken-and-dumplings/", "nutritionData": "{\"calories\": 547, \"protein\": 43.0, \"carbs\": 41.0, \"fat\": 18.0}"},
  {"name": "Thai Green Curry Chicken", "category": "Chicken", "description": "Fragrant chicken simmered in coconut milk with green curry paste, eggplant, and Thai basil.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.25 lbs\", \"name\": \"boneless skinless chicken thighs sliced\"}, {\"qty\": \"400 ml\", \"name\": \"full-fat coconut milk\"}, {\"qty\": \"4 tbsp\", \"name\": \"Thai green curry paste\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"Japanese eggplants sliced\"}, {\"qty\": \"1.5 cups\", \"name\": \"snow peas\"}, {\"qty\": \"4\", \"name\": \"kaffir lime leaves torn\"}, {\"qty\": \"2 tsp\", \"name\": \"fish sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"Juice of 1/2 lime\"}, {\"qty\": \"16\", \"name\": \"Thai basil leaves\"}, {\"qty\": \"\", \"name\": \"Steamed jasmine rice for serving\"}]", "instructions": "1. Heat oil in a large skillet or wok over medium-high heat. Add green curry paste and cook, stirring, 2–3 minutes until fragrant and dried out. 2. Add chicken broth and coconut milk. Stir to dissolve paste. Add kaffir lime leaves, fish sauce, and sugar. Bring to a simmer. 3. Add sliced chicken thighs; stir and reduce heat to medium. Cook 7 minutes. 4. Add eggplant slices; cook 5 minutes until softened. 5. Taste and adjust seasoning with fish sauce or sugar as needed. 6. Add snow peas and cook 2 minutes. Stir in basil leaves and lime juice. Serve over jasmine rice.", "tags": "Thai, green curry, coconut milk, spicy", "source": "https://www.recipetineats.com/thai-green-curry/", "nutritionData": "{\"calories\": 608, \"protein\": 41.0, \"carbs\": 13.0, \"fat\": 43.0}"},
  {"name": "Jerk Chicken", "category": "Chicken", "description": "Boldly spiced Caribbean chicken marinated in scotch bonnet peppers and allspice, then grilled to charred perfection.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"bone-in skin-on chicken pieces\"}, {\"qty\": \"4\", \"name\": \"scotch bonnet or habanero peppers seeded\"}, {\"qty\": \"1/2 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground allspice\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"4\", \"name\": \"green onions\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}]", "instructions": "1. Blend scotch bonnets, soy sauce, brown sugar, garlic, allspice, thyme, cinnamon, nutmeg, oil, lime juice, green onions, and ginger until smooth. Reserve 3 tbsp for serving. 2. Score chicken pieces deeply. Rub marinade all over and into cuts. Cover and refrigerate at least 4 hours, preferably overnight. 3. Preheat grill to medium (350°F). Clean and lightly oil grates. 4. Grill chicken over medium heat, lid closed, 10–12 minutes per side. Move to indirect heat if flaring. 5. Cook until thickest parts register 165°F and skin is deeply charred in spots. 6. Rest 5 minutes. Serve with reserved jerk sauce, rice and peas, and grilled corn.", "tags": "Jamaican, jerk, grilled, Caribbean", "source": "https://www.recipetineats.com/jamaican-jerk-chicken-drumsticks-with-caribbean-rice-with-beans/", "nutritionData": "{\"calories\": 395, \"protein\": 37.0, \"carbs\": 6.0, \"fat\": 21.0}"},
  {"name": "Chicken Shawarma", "category": "Chicken", "description": "Middle Eastern spiced chicken thighs marinated in warm spices and served in flatbread with creamy yogurt sauce.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1\", \"name\": \"large garlic clove minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground cardamom\"}, {\"qty\": \"1 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"Black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4\", \"name\": \"flatbreads\"}, {\"qty\": \"1 cup\", \"name\": \"Greek yogurt\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic for sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice for sauce\"}, {\"qty\": \"\", \"name\": \"Romaine lettuce sliced\"}, {\"qty\": \"\", \"name\": \"Tomato sliced\"}, {\"qty\": \"\", \"name\": \"Red onion sliced\"}]", "instructions": "1. Combine garlic, coriander, cumin, cardamom, cayenne, paprika, salt, pepper, lemon juice, and olive oil in a zip-lock bag. Add chicken thighs; massage to coat. Marinate 3 hours to overnight. 2. Mix yogurt, garlic, and lemon juice for sauce. Refrigerate. 3. Heat a large skillet or grill pan over high heat. Cook chicken 4–5 minutes per side until nicely charred and cooked through. 4. Rest chicken 3 minutes, then slice thinly on a cutting board. 5. Warm flatbreads briefly in a dry skillet. 6. Spread yogurt sauce on flatbread. Top with chicken slices, lettuce, tomato, and onion. Roll up and serve.", "tags": "Middle Eastern, shawarma, wraps", "source": "https://www.recipetineats.com/chicken-sharwama-middle-eastern/", "nutritionData": "{\"calories\": 723, \"protein\": 57.0, \"carbs\": 42.0, \"fat\": 37.0}"},
  {"name": "Moroccan Chicken Tagine", "category": "Chicken", "description": "Tender braised chicken with chickpeas, dried apricots, and ras el hanout in a warmly spiced North African stew.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"ras el hanout\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"14 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"15 oz\", \"name\": \"canned chickpeas drained\"}, {\"qty\": \"1/2 cup\", \"name\": \"dried apricots halved and soaked\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"\", \"name\": \"Preserved lemon rind chopped\"}, {\"qty\": \"\", \"name\": \"Fresh cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"Couscous for serving\"}]", "instructions": "1. Season chicken thighs with salt. Heat olive oil in a large wide pan over high heat. Sear chicken skin-side down 8–10 minutes until deep golden. Turn and sear flesh side 1 minute. Remove to a plate. 2. Reduce heat to medium. Sauté onion 3 minutes. Add garlic; cook 1 minute. Add ras el hanout, cumin, and turmeric; stir 30 seconds. 3. Add crushed tomatoes, broth, chickpeas, apricots, cinnamon stick, and honey. Stir and bring to a simmer. 4. Place chicken on top skin-side up. Cover and simmer 5 minutes. 5. Remove lid; simmer uncovered 20 minutes until chicken is cooked through and sauce reduces. 6. Stir in preserved lemon. Garnish with cilantro. Serve over couscous.", "tags": "Moroccan, tagine, North African, braised", "source": "https://www.recipetineats.com/chicken-tagine/", "nutritionData": "{\"calories\": 579, \"protein\": 46.0, \"carbs\": 42.0, \"fat\": 25.0}"},
  {"name": "Lemon Herb Roast Chicken Thighs", "category": "Chicken", "description": "Sheet-pan chicken thighs roasted with potatoes, chickpeas, and bright lemon in an oregano-scented marinade.", "servings": 4, "prepTime": 15, "cookTime": 55, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs about 2.25 lbs\"}, {\"qty\": \"2\", \"name\": \"lemons one zested and juiced one thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion halved and thinly sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"15 oz\", \"name\": \"canned chickpeas drained\"}, {\"qty\": \"3/4 lb\", \"name\": \"Yukon Gold potatoes cut into wedges\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"\", \"name\": \"Flat-leaf parsley for garnish\"}]", "instructions": "1. Whisk lemon juice, half the oregano, and 1 tsp salt. Add chicken thighs and toss to coat. Marinate 20 minutes or up to overnight. 2. Preheat oven to 450°F. 3. In a 9×13-inch baking dish, combine lemon slices, olive oil, onion, garlic, remaining oregano, salt, and pepper. Add potato wedges and chickpeas; toss to coat. 4. Place chicken thighs on top of potato mixture, skin-side up. Drizzle skin with a little extra olive oil. 5. Roast 45 minutes until chicken is cooked through and skin is crisp. 6. Transfer chicken to a plate. Return pan to oven 10–15 minutes to further brown potatoes. Serve chicken over potato-chickpea mixture, garnished with parsley.", "tags": "sheet pan, lemon, roasted, easy weeknight", "source": "https://smittenkitchen.com/2024/09/lemon-chicken-with-potatoes-and-chickpeas/", "nutritionData": "{\"calories\": 576, \"protein\": 46.0, \"carbs\": 33.0, \"fat\": 28.0}"},
  {"name": "Vietnamese Chicken Pho", "category": "Chicken", "description": "Crystal-clear aromatic chicken broth with rice noodles, tender poached chicken, and fresh herbs.", "servings": 4, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken about 3.5 lbs\"}, {\"qty\": \"1\", \"name\": \"large onion halved\"}, {\"qty\": \"\", \"name\": \"3-inch piece fresh ginger halved\"}, {\"qty\": \"3\", \"name\": \"star anise\"}, {\"qty\": \"3\", \"name\": \"whole cloves\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"1 tbsp\", \"name\": \"coriander seeds\"}, {\"qty\": \"2 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"Salt to taste\"}, {\"qty\": \"12 oz\", \"name\": \"dried rice noodles flat\"}, {\"qty\": \"2 cups\", \"name\": \"bean sprouts\"}, {\"qty\": \"4\", \"name\": \"green onions sliced\"}, {\"qty\": \"\", \"name\": \"Fresh cilantro\"}, {\"qty\": \"\", \"name\": \"Fresh basil leaves\"}, {\"qty\": \"\", \"name\": \"Lime wedges\"}, {\"qty\": \"\", \"name\": \"Jalape\\u00f1o sliced\"}, {\"qty\": \"\", \"name\": \"Hoisin sauce and sriracha for serving\"}]", "instructions": "1. Char onion and ginger halves cut-side down in a dry skillet over high heat until blackened, about 4 minutes. 2. In a large pot, combine chicken, charred onion and ginger, star anise, cloves, cinnamon stick, and coriander seeds with 8 cups water. Bring to a simmer. 3. Skim foam from surface. Simmer very gently with lid ajar for 1.5 hours. 4. Remove chicken; let cool. Strain broth; return to pot. Season with fish sauce, sugar, and salt. The broth should be slightly salty. 5. Shred chicken meat from carcass; discard skin and bones. Prepare noodles per package directions; drain. 6. Divide noodles into bowls. Top with shredded chicken. Ladle hot broth over. Serve with bean sprouts, herbs, lime, and condiments.", "tags": "Vietnamese, pho, soup, noodles", "source": "https://www.recipetineats.com/vietnamese-chicken-pho-soup-pho-ga/", "nutritionData": "{\"calories\": 523, \"protein\": 44.0, \"carbs\": 68.0, \"fat\": 4.0}"},
  {"name": "Chicken Tortilla Soup", "category": "Chicken", "description": "Smoky, creamy chicken soup loaded with peppers and melted cheddar, topped with crunchy tortilla chips.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"1\", \"name\": \"poblano pepper diced\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1os seeded and diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"2 tbsp\", \"name\": \"taco seasoning\"}, {\"qty\": \"1 cup\", \"name\": \"salsa verde\"}, {\"qty\": \"4 oz\", \"name\": \"canned green chiles\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"\", \"name\": \"Fresh cilantro\"}, {\"qty\": \"\", \"name\": \"Tortilla chips for serving\"}, {\"qty\": \"\", \"name\": \"Avocado and sour cream for topping\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Sauté onion 5 minutes until fragrant. Add poblano, jalapeños, cumin, and taco seasoning. Cook 5 minutes. 2. Add chicken breasts, salsa verde, canned chiles, and broth. Season with salt and pepper. Partially cover and simmer over medium-low 20 minutes until chicken is cooked through. 3. Remove chicken; shred with two forks. 4. Microwave cream cheese 15 seconds to soften. Whisk into soup until smooth. Stir in shredded chicken and cheddar cheese. 5. Simmer 5 minutes until cheese is fully melted. Stir in lime juice and cilantro. 6. Ladle into bowls. Top with tortilla chips, avocado, and sour cream.", "tags": "soup, tortilla, Mexican, quick", "source": "https://www.halfbakedharvest.com/creamy-chicken-tortilla-soup/", "nutritionData": "{\"calories\": 551, \"protein\": 46.0, \"carbs\": 26.0, \"fat\": 28.0}"},
  {"name": "Chicken Enchiladas", "category": "Chicken", "description": "Corn tortillas filled with seasoned shredded chicken, rolled in enchilada sauce, and baked under a blanket of melted cheese.", "servings": 6, "prepTime": 25, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"3 cups\", \"name\": \"enchilada sauce divided\"}, {\"qty\": \"12\", \"name\": \"corn tortillas 6-inch\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded Monterey Jack cheese\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"\", \"name\": \"Sour cream cilantro and lime for serving\"}]", "instructions": "1. Sprinkle chicken with cumin and chili powder. Heat oil in skillet over medium-high; cook chicken 5 minutes per side. Cool and shred with forks. 2. In same skillet, cook onion, bell pepper, and garlic until softened, 6 minutes. Combine with shredded chicken and 1 cup enchilada sauce, 1 cup cheddar, and 1 cup Jack cheese. Season with salt. 3. Preheat oven to 350°F. Spread 1 cup enchilada sauce in bottom of a 9×13 inch baking dish. 4. Warm tortillas one at a time over a gas burner or in a dry skillet. Spoon 1/3 cup filling down center of each tortilla. Roll up and place seam-side down in baking dish. 5. Pour remaining 1 cup enchilada sauce over top. Sprinkle with remaining cheeses. 6. Bake 20–25 minutes until cheese is melted and bubbly. Serve with sour cream, cilantro, and lime.", "tags": "Mexican, enchiladas, baked, cheese", "source": "https://www.thepioneerwoman.com/food-cooking/recipes/a11635/chicken-enchiladas/", "nutritionData": "{\"calories\": 570, \"protein\": 62.0, \"carbs\": 37.0, \"fat\": 20.0}"},
  {"name": "BBQ Chicken Thighs", "category": "Chicken", "description": "Juicy bone-in chicken thighs grilled to perfection and glazed with smoky-sweet BBQ sauce.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large bone-in skin-on chicken thighs about 2 lbs\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce divided\"}]", "instructions": "1. Pat chicken thighs dry. Rub with olive oil then season all over with garlic powder, paprika, onion powder, cayenne, salt, and pepper. 2. Preheat grill to medium-high (400°F). Clean and oil grates. 3. Place thighs skin-side down on grill. Cook 6–8 minutes until skin releases easily and is marked. Flip and cook another 6–8 minutes. 4. Reduce heat to medium or move to indirect heat. Brush thighs generously with BBQ sauce. Cook 2 minutes. Flip, brush again, and cook 2 minutes more. 5. Repeat glazing once more. Cook until thickest part registers 165°F. 6. Rest 5 minutes before serving with extra BBQ sauce on the side.", "tags": "BBQ, grilled, summer, easy", "source": "Classic", "nutritionData": "{\"calories\": 404, \"protein\": 39.0, \"carbs\": 14.0, \"fat\": 20.0}"},
  {"name": "Grilled Lemon Garlic Chicken Thighs", "category": "Chicken", "description": "Boneless chicken thighs marinated in lemon, garlic, and herbs then grilled until golden and juicy.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"Fresh parsley for garnish\"}, {\"qty\": \"\", \"name\": \"Lemon wedges for serving\"}]", "instructions": "1. Whisk garlic, lemon juice, olive oil, oregano, thyme, paprika, salt, and pepper in a bowl. Add chicken thighs and toss to coat. Marinate at least 2 hours or overnight. 2. Preheat grill to medium-high heat (400°F). Oil the grates. 3. Remove chicken from marinade, letting excess drip off. Place thighs on grill. 4. Grill 5–7 minutes per side until cooked through (165°F internal) and nicely charred in spots. 5. Transfer to a plate and rest 3 minutes. 6. Serve garnished with parsley and lemon wedges.", "tags": "grilled, lemon, garlic, easy weeknight", "source": "Classic", "nutritionData": "{\"calories\": 425, \"protein\": 44.0, \"carbs\": 2.0, \"fat\": 26.0}"},
  {"name": "Chicken Florentine", "category": "Chicken", "description": "Pan-seared chicken in a creamy white wine and lemon sauce with wilted spinach and Parmesan.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts about 1.5 lbs\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"minced shallots\"}, {\"qty\": \"3 tbsp\", \"name\": \"dry white wine\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon zest\"}, {\"qty\": \"1/2 cup\", \"name\": \"diced red bell pepper\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 lb\", \"name\": \"fresh baby spinach\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"Grated Parmesan for serving\"}]", "instructions": "1. Slice chicken breasts in half horizontally. Season with salt and pepper. Coat evenly in flour. 2. Heat 2 tbsp oil in a skillet over medium-high. Cook chicken 4–5 minutes per side until golden and just cooked through. Remove to a plate. 3. Add remaining oil and butter to pan. Cook garlic and shallots 1 minute. 4. Add wine and cook until reduced by half. Add lemon zest and bell pepper; cook 2 minutes. Stir in cream; bring to a simmer. 5. Add spinach in batches, stirring until wilted. Season sauce with salt and pepper. 6. Return chicken to pan; simmer 3–4 minutes until heated through. Serve with freshly grated Parmesan.", "tags": "Italian, creamy, spinach, chicken", "source": "https://www.allrecipes.com/chef-john-s-chicken-florentine-recipe-8729485", "nutritionData": "{\"calories\": 695, \"protein\": 62.0, \"carbs\": 16.0, \"fat\": 42.0}"},
  {"name": "Chicken Cordon Bleu", "category": "Chicken", "description": "Rolled chicken breasts stuffed with ham and Swiss cheese, breaded and pan-fried to crispy golden perfection.", "servings": 4, "prepTime": 25, "cookTime": 30, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts\"}, {\"qty\": \"4 slices\", \"name\": \"thin ham\"}, {\"qty\": \"4 slices\", \"name\": \"Swiss cheese\"}, {\"qty\": \"\", \"name\": \"Salt and black pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1.5 cups\", \"name\": \"chicken broth for sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour for sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"2 tbsp\", \"name\": \"heavy cream\"}, {\"qty\": \"\", \"name\": \"Salt and pepper to taste\"}]", "instructions": "1. Slice chicken breasts in half widthwise. Pound each piece to 1/4-inch thickness. Season with salt and pepper. 2. Layer 1 slice ham and 1 slice Swiss cheese on each pounded piece, leaving a border. Roll tightly, folding in the sides. Secure with toothpicks. 3. Set up breading stations: flour, egg whisked with milk, and panko. Dredge each roll in flour, then egg wash, then panko, pressing to coat. 4. Heat oil in a large oven-safe skillet over medium heat. Brown chicken rolls 3–4 minutes on each side until golden all around. 5. Transfer to 375°F oven and bake 15–20 minutes until internal temp reaches 165°F. 6. For Dijon cream sauce: melt butter, whisk in flour, add broth; simmer until thick. Stir in mustard and cream. Remove toothpicks from chicken. Slice and serve with sauce.", "tags": "French, stuffed chicken, elegant dinner", "source": "https://www.recipetineats.com/chicken-cordon-bleu-easy-fancy/", "nutritionData": "{\"calories\": 665, \"protein\": 60.0, \"carbs\": 31.0, \"fat\": 30.0}"},
  {"name": "Chicken Katsu", "category": "Chicken", "description": "Japanese-style panko-breaded chicken cutlets fried until ultra-crispy and served with tonkatsu sauce.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large boneless skinless chicken breasts about 1.5 lbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"2 cups\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"4 cups\", \"name\": \"shredded green cabbage\"}, {\"qty\": \"\", \"name\": \"Lemon wedges\"}, {\"qty\": \"1/4 cup\", \"name\": \"tonkatsu sauce store-bought\"}, {\"qty\": \"\", \"name\": \"Steamed white rice for serving\"}]", "instructions": "1. Slice chicken breasts horizontally to create 4 cutlets. Pound each to 1/4-inch thickness. Season with salt and pepper. 2. Set up three bowls: flour, beaten eggs, and panko. Dredge each cutlet in flour, then egg, then press firmly into panko to adhere on all sides. 3. Fill a large skillet with 1/3 inch of vegetable oil. Heat to 350°F (175°C). 4. Fry cutlets 2 pieces at a time, swirling pan for even browning, 1.5 minutes per side until set. Continue cooking, flipping occasionally, about 3 minutes more until deep golden. 5. Drain on a paper towel-lined rack. Season with salt immediately. 6. Slice katsu into strips. Serve over rice alongside shredded cabbage, lemon wedges, and tonkatsu sauce.", "tags": "Japanese, katsu, panko, crispy", "source": "https://www.allrecipes.com/recipe/72068/chicken-katsu/", "nutritionData": "{\"calories\": 708, \"protein\": 64.0, \"carbs\": 58.0, \"fat\": 22.0}"},
  {"name": "Chicken Karaage", "category": "Chicken", "description": "Double-fried Japanese chicken thigh morsels marinated in ginger and soy, impossibly crispy outside and juicy inside.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skin-on chicken thighs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/8 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1 clove\", \"name\": \"garlic pressed\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sake or dry sherry\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"potato starch or cornstarch\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for deep frying\"}, {\"qty\": \"\", \"name\": \"Lemon wedges\"}, {\"qty\": \"\", \"name\": \"Japanese mayonnaise for serving\"}]", "instructions": "1. Cut chicken thighs into 2-inch pieces. Season with salt and pepper. 2. Combine grated ginger, garlic, soy sauce, sake, and sesame oil in a bowl. Add chicken; toss to coat. Cover and marinate in refrigerator 30 minutes. 3. Heat 3–4 cups vegetable oil in a heavy pot to 325°F (160°C). 4. Dredge each piece of marinated chicken in flour, shake off excess, then dredge in potato starch. 5. First fry: in batches of 3–5 pieces, fry 90 seconds until lightly golden. Transfer to a rack. Raise oil to 350°F. 6. Second fry: return chicken to hot oil in batches for 45 seconds until deep golden and very crispy. Drain on rack. Serve immediately with lemon and Japanese mayo.", "tags": "Japanese, fried chicken, crispy, karaage", "source": "https://www.justonecookbook.com/karaage/", "nutritionData": "{\"calories\": 596, \"protein\": 38.0, \"carbs\": 7.0, \"fat\": 40.0}"},
  {"name": "Chicken Biryani", "category": "Chicken", "description": "Fragrant layered rice dish with spiced marinated chicken, caramelized onions, and saffron-infused basmati rice.", "servings": 6, "prepTime": 30, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"3/4 cup\", \"name\": \"plain yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil for marinade\"}, {\"qty\": \"2 cups\", \"name\": \"basmati rice\"}, {\"qty\": \"2\", \"name\": \"large onions thinly sliced\"}, {\"qty\": \"4 tbsp\", \"name\": \"oil for frying onions\"}, {\"qty\": \"\", \"name\": \"Pinch saffron dissolved in 2 tbsp warm milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh mint\"}]", "instructions": "1. Combine yogurt, tomato paste, garlic, ginger, and all spices. Add chicken; coat well. Marinate 2 hours to overnight. 2. Fry sliced onions in 4 tbsp oil over medium-high heat until deep golden and crisp, 20 minutes. Drain on paper towels. Reserve half for garnish. 3. Par-cook basmati rice in heavily salted boiling water for 5–6 minutes until 70% cooked. Drain. 4. In a heavy pot, place marinated chicken as the base layer. Top with half the caramelized onions, half the herbs, and all of the par-cooked rice. 5. Drizzle saffron milk over rice. Scatter remaining onions and herbs on top. Cover tightly and cook over low heat 35–40 minutes (dum cooking). 6. Serve by scooping deep to get all layers — yellow saffron rice, white rice, curry-stained rice, and chicken together.", "tags": "Indian, biryani, rice, special occasion", "source": "https://www.recipetineats.com/biryani/", "nutritionData": "{\"calories\": 640, \"protein\": 37.0, \"carbs\": 72.0, \"fat\": 21.0}"},
  {"name": "Baked Chicken Nuggets", "category": "Healthy Kids", "description": "Crispy whole grain panko-crusted chicken nuggets baked golden without frying.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole wheat breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Preheat oven to 425F and spray a baking sheet with olive oil spray. 2. Cut chicken into bite-sized pieces. 3. Mix breadcrumbs, panko, Parmesan, garlic powder, paprika, and salt in a bowl. 4. Toss chicken pieces with olive oil to coat. 5. Press chicken into breadcrumb mixture to coat all sides. 6. Arrange on baking sheet and spray tops with olive oil spray. 7. Bake 8-10 minutes, flip, then bake another 4-5 minutes until golden and cooked through.", "tags": "kid-friendly, high-protein, baked", "source": "https://www.skinnytaste.com/healthy-baked-chicken-nuggets/", "nutritionData": "{\"calories\": 260, \"protein\": 32.0, \"carbs\": 12.0, \"fat\": 6.0}"},
  {"name": "Sheet Pan Chicken Nuggets with Veggies", "category": "Healthy Kids", "description": "One-pan baked nuggets alongside colorful roasted vegetables for a balanced meal.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast\"}, {\"qty\": \"1/2 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"broccoli florets\"}, {\"qty\": \"1 cup\", \"name\": \"sliced bell peppers\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 425F and line a large baking sheet with parchment paper. 2. Cut chicken into bite-sized nuggets. 3. Whisk egg in a bowl; mix panko with garlic powder, onion powder, salt in another bowl. 4. Dip chicken in egg then coat in panko mixture; place on one side of baking sheet. 5. Toss broccoli and peppers with olive oil and black pepper; spread on other side of baking sheet. 6. Spray nuggets with cooking spray. 7. Bake 18-20 minutes, flipping nuggets halfway, until chicken is cooked through and veggies are tender-crisp.", "tags": "kid-friendly, sheet-pan, balanced", "source": "Classic", "nutritionData": "{\"calories\": 290, \"protein\": 35.0, \"carbs\": 12.0, \"fat\": 8.0}"},
  {"name": "Turkey Meatballs with Hidden Vegetables", "category": "Healthy Kids", "description": "Tender turkey meatballs packed with grated zucchini, carrot, and spinach in marinara sauce.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"lean ground turkey\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated zucchini (squeezed dry)\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated carrot\"}, {\"qty\": \"1/4 cup\", \"name\": \"finely chopped spinach\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole wheat breadcrumbs\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce\"}]", "instructions": "1. Preheat oven to 375F. 2. Combine turkey, zucchini, carrot, spinach, egg, breadcrumbs, garlic powder, onion powder, salt, and pepper in a bowl; mix until combined. 3. Roll into 1-inch balls and place in a 9x13 baking dish. 4. Pour marinara sauce over meatballs and cover dish with foil. 5. Bake 25-30 minutes until meatballs are cooked through. 6. Serve over whole wheat pasta or zucchini noodles.", "tags": "hidden-veggies, high-protein, kid-friendly", "source": "https://weelicious.com/turkey-pesto-meatballs/", "nutritionData": "{\"calories\": 300, \"protein\": 28.0, \"carbs\": 21.0, \"fat\": 10.0}"},
  {"name": "Whole Wheat Pasta with Hidden Veggie Marinara", "category": "Healthy Kids", "description": "Whole wheat penne with a blended marinara sauce loaded with pureed carrots and spinach.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"whole wheat penne pasta\"}, {\"qty\": \"2 cups\", \"name\": \"marinara sauce\"}, {\"qty\": \"1\", \"name\": \"medium carrot (peeled and chopped)\"}, {\"qty\": \"1 cup\", \"name\": \"fresh spinach\"}, {\"qty\": \"1/2\", \"name\": \"onion (diced)\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}]", "instructions": "1. Cook pasta according to package directions; drain and reserve 1/4 cup pasta water. 2. While pasta cooks, heat olive oil in a saucepan over medium heat and sauté onion and carrot until soft, about 8 minutes. 3. Add garlic and spinach; cook 2 minutes until spinach wilts. 4. Add marinara sauce and simmer 5 minutes. 5. Use an immersion blender to blend sauce until smooth. 6. Toss pasta with veggie marinara, adding pasta water as needed for consistency. 7. Serve topped with Parmesan cheese.", "tags": "hidden-veggies, whole-grain, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 350, \"protein\": 12.0, \"carbs\": 56.0, \"fat\": 7.0}"},
  {"name": "Cauliflower Crust Pizza", "category": "Healthy Kids", "description": "Low-carb pizza with a cheesy cauliflower crust topped with marinara and melted mozzarella.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium head cauliflower (about 4 cups riced)\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded part-skim mozzarella cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/3 cup\", \"name\": \"marinara sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded part-skim mozzarella (for topping)\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Preheat oven to 375F and line two baking sheets with parchment paper; spray with oil. 2. Rice cauliflower in a food processor; microwave in a bowl 5 minutes until tender. 3. Transfer to a clean towel and squeeze out all liquid very well. 4. Mix cauliflower with egg, 3/4 cup mozzarella, Parmesan, oregano, and garlic powder. 5. Press into four thin 7-inch rounds on prepared pans. 6. Bake 15 minutes, flip carefully, and bake 5-7 minutes more until golden. 7. Top each crust with marinara and remaining mozzarella; bake 3-4 minutes until cheese melts.", "tags": "low-carb, gluten-free, kid-friendly", "source": "https://www.skinnytaste.com/spaghetti-squash-crust-pizza/", "nutritionData": "{\"calories\": 180, \"protein\": 14.0, \"carbs\": 8.0, \"fat\": 9.0}"},
  {"name": "Whole Grain Quesadillas with Beans and Cheese", "category": "Healthy Kids", "description": "Crispy whole wheat tortillas filled with black beans, veggies, and melted cheese.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"whole wheat flour tortillas (8 inch)\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) black beans (drained and rinsed)\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"low-fat shredded Mexican cheese blend\"}, {\"qty\": \"1\", \"name\": \"red bell pepper (diced)\"}, {\"qty\": \"1/2\", \"name\": \"onion (diced)\"}, {\"qty\": \"1 cup\", \"name\": \"baby spinach\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"salsa for serving\"}]", "instructions": "1. Heat olive oil in a skillet over medium heat; sauté onion and bell pepper 5 minutes until soft. 2. Add beans, spinach, cumin, and chili powder; cook 2 minutes until spinach wilts. 3. Remove filling from skillet. 4. Place a tortilla in the skillet over medium-high heat; top half with cheese and filling then fold. 5. Cook until golden brown on one side, about 2 minutes, then flip and cook the other side. 6. Repeat with remaining tortillas. 7. Cut into wedges and serve with salsa.", "tags": "high-fiber, vegetarian, kid-friendly", "source": "Classic", "nutritionData": "{\"calories\": 360, \"protein\": 17.0, \"carbs\": 47.0, \"fat\": 12.0}"},
  {"name": "Greek Yogurt Mac and Cheese", "category": "Healthy Kids", "description": "Creamy high-protein mac and cheese made with Greek yogurt and real cheddar for a healthier twist.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"whole wheat elbow macaroni\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"2% milk\"}, {\"qty\": \"1 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Cook macaroni according to package directions; drain. 2. In a saucepan, melt butter over medium heat; whisk in flour and cook 1 minute. 3. Slowly whisk in milk until smooth; cook until slightly thickened, about 3 minutes. 4. Remove from heat; stir in Greek yogurt, cheddar cheese, garlic powder, onion powder, salt, and pepper until melted and smooth. 5. Toss hot pasta with cheese sauce; adjust seasoning. 6. Serve warm immediately.", "tags": "high-protein, kid-favorite, whole-grain", "source": "https://joyfoodsunshine.com/healthy-greek-yogurt-mac-cheese/", "nutritionData": "{\"calories\": 600, \"protein\": 28.0, \"carbs\": 49.0, \"fat\": 30.0}"},
  {"name": "Salmon Teriyaki Bites", "category": "Healthy Kids", "description": "Juicy bite-sized salmon cubes glazed with a simple honey-soy teriyaki sauce.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"salmon fillet (cut into 1-inch cubes)\"}, {\"qty\": \"3 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 clove\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fresh ginger (minced)\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"2\", \"name\": \"scallions (sliced)\"}]", "instructions": "1. Whisk soy sauce, honey, rice vinegar, sesame oil, garlic, and ginger together in a bowl. 2. Add salmon cubes and marinate 15-30 minutes in the refrigerator. 3. Heat a nonstick skillet over medium-high heat; add salmon cubes in a single layer reserving marinade. 4. Cook 2-3 minutes per side until cooked through and caramelized. 5. Pour reserved marinade into a small pan; simmer until thickened, 2-3 minutes. 6. Drizzle sauce over salmon bites; garnish with sesame seeds and scallions. 7. Serve with steamed rice or on toothpicks as finger food.", "tags": "omega-3, high-protein, kid-friendly", "source": "https://www.skinnytaste.com/teriyaki-salmon-bowl-air-fryer-or-oven/", "nutritionData": "{\"calories\": 285, \"protein\": 23.0, \"carbs\": 9.0, \"fat\": 16.0}"},
  {"name": "Mini Whole Wheat Veggie Muffins", "category": "Healthy Kids", "description": "Tender bite-sized whole wheat muffins loaded with grated carrot and zucchini for little hands.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"white whole wheat flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"melted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"maple syrup\"}, {\"qty\": \"1\", \"name\": \"large egg (beaten)\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"grated zucchini (squeezed dry)\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated carrot\"}, {\"qty\": \"1/2 cup\", \"name\": \"raisins\"}]", "instructions": "1. Preheat oven to 350F and spray a mini muffin tin with nonstick spray. 2. Whisk flour, baking soda, cinnamon, and salt in a bowl. 3. In another bowl, stir together butter, maple syrup, egg, and vanilla. 4. Add flour mixture to wet ingredients and stir just until combined. 5. Fold in zucchini, carrot, and raisins. 6. Fill mini muffin cups 3/4 full. 7. Bake 15-20 minutes until a toothpick comes out clean. 8. Cool in pan 5 minutes before removing.", "tags": "whole-grain, hidden-veggies, snack", "source": "https://cupcakesandkalechips.com/healthy-carrot-zucchini-mini-muffins/", "nutritionData": "{\"calories\": 245, \"protein\": 4.0, \"carbs\": 44.0, \"fat\": 7.0}"},
  {"name": "Banana Oat Pancakes", "category": "Healthy Kids", "description": "Fluffy whole wheat and oat pancakes naturally sweetened with ripe bananas and cinnamon.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"very ripe medium bananas\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"rolled oats\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"milk\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter (melted)\"}]", "instructions": "1. Mash bananas until smooth in a large bowl. 2. Add eggs, milk, vanilla, and melted butter to the bananas; stir to combine. 3. Add flour, oats, baking powder, and cinnamon; gently stir until just combined. 4. Heat a nonstick skillet over medium heat; melt a small bit of butter. 5. Pour 1/4 cup batter per pancake; cook 2-3 minutes until bubbles form on surface. 6. Flip and cook another 2 minutes. 7. Serve warm with fresh fruit or maple syrup.", "tags": "whole-grain, naturally-sweet, kid-favorite", "source": "https://www.yummytoddlerfood.com/banana-oatmeal-pancakes/", "nutritionData": "{\"calories\": 415, \"protein\": 15.0, \"carbs\": 59.0, \"fat\": 12.0}"},
  {"name": "Chicken and Veggie Skewers", "category": "Healthy Kids", "description": "Tender grilled chicken cubes and colorful vegetables on skewers kids love to eat.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast (cut into 1-inch cubes)\"}, {\"qty\": \"1\", \"name\": \"red bell pepper (cut into chunks)\"}, {\"qty\": \"1\", \"name\": \"zucchini (sliced)\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"8\", \"name\": \"wooden skewers (soaked in water)\"}]", "instructions": "1. Whisk olive oil, lemon juice, garlic, oregano, salt, and pepper in a bowl. 2. Add chicken cubes and toss to coat; marinate 30 minutes if time allows. 3. Thread chicken, peppers, zucchini, and tomatoes alternately onto skewers. 4. Preheat grill or grill pan over medium-high heat; oil grates lightly. 5. Grill skewers 10-12 minutes, turning every 3-4 minutes, until chicken reaches 165F. 6. Serve immediately.", "tags": "high-protein, grilled, kid-friendly", "source": "https://www.skinnytaste.com/grilled-pesto-chicken-and-tomato-kebabs/", "nutritionData": "{\"calories\": 315, \"protein\": 37.0, \"carbs\": 8.0, \"fat\": 14.0}"},
  {"name": "Whole Grain Pita Pizzas", "category": "Healthy Kids", "description": "Mini whole wheat pita pizzas with marinara and mozzarella ready in under 15 minutes.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"whole wheat pita rounds\"}, {\"qty\": \"1 cup\", \"name\": \"marinara sauce\"}, {\"qty\": \"1 cup\", \"name\": \"shredded part-skim mozzarella cheese\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/3 cup\", \"name\": \"sliced black olives\"}, {\"qty\": \"1/2 cup\", \"name\": \"diced bell peppers\"}]", "instructions": "1. Preheat oven to 400F and line a baking sheet with foil. 2. Mix marinara with garlic powder and Italian seasoning. 3. Spread 1/4 cup sauce on each pita. 4. Top each with 1/4 cup mozzarella, olives, and bell peppers. 5. Bake 10 minutes until cheese is melted and bubbly. 6. Cut into wedges and serve warm.", "tags": "quick, kid-friendly, whole-grain", "source": "https://weelicious.com/pita-pizzas/", "nutritionData": "{\"calories\": 300, \"protein\": 14.0, \"carbs\": 43.0, \"fat\": 8.0}"},
  {"name": "Baked Sweet Potato Fries", "category": "Healthy Kids", "description": "Oven-baked sweet potato sticks seasoned with garlic and paprika for a nutritious side.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"medium sweet potatoes (peeled and cut into 1/4-inch sticks)\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 415F and line a baking sheet with parchment paper. 2. Mix salt, garlic powder, paprika, and pepper in a small bowl. 3. Spread sweet potatoes in a single layer on baking sheet; drizzle with olive oil and sprinkle with seasoning mix. 4. Toss to coat evenly. 5. Bake 15 minutes, flip, then bake another 10-15 minutes until crispy on edges. 6. Serve hot with ketchup or yogurt dip.", "tags": "vitamin-A, kid-favorite, vegan", "source": "https://www.iheartnaptime.net/baked-sweet-potato-fries/", "nutritionData": "{\"calories\": 230, \"protein\": 3.0, \"carbs\": 40.0, \"fat\": 7.0}"},
  {"name": "Veggie-Packed Mini Frittatas", "category": "Healthy Kids", "description": "Bite-sized egg muffins filled with colorful vegetables and melted cheese for easy snacking.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"cottage cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1 cup\", \"name\": \"minced broccoli (or spinach or grated zucchini)\"}, {\"qty\": \"1 tbsp\", \"name\": \"grated onion\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"nonstick spray\"}]", "instructions": "1. Preheat oven to 350F and spray a 12-cup mini muffin tin very well with nonstick spray. 2. Lightly beat eggs in a bowl. 3. Stir in cottage cheese, cheddar, broccoli, grated onion, Parmesan, flour, onion powder, and salt until combined. 4. Spoon mixture into muffin cups, filling to the brim. 5. Bake 18-20 minutes until firm to the touch and golden around the edges. 6. Let cool 5 minutes before loosening edges with a knife. 7. Serve warm or at room temperature.", "tags": "high-protein, finger-food, make-ahead", "source": "https://www.yummytoddlerfood.com/egg-and-cheese-mini-muffins/", "nutritionData": "{\"calories\": 235, \"protein\": 18.0, \"carbs\": 9.0, \"fat\": 13.0}"},
  {"name": "Lentil Bolognese", "category": "Healthy Kids", "description": "Rich meat-free bolognese with green lentils and vegetables over whole wheat pasta.", "servings": 6, "prepTime": 15, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"yellow onion (diced)\"}, {\"qty\": \"2\", \"name\": \"medium carrots (diced)\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms (finely chopped)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 cup\", \"name\": \"green or brown lentils (rinsed)\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) crushed tomatoes\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"12 oz\", \"name\": \"whole wheat spaghetti\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat; sauté onion, carrots, and mushrooms until soft, about 8-10 minutes. 2. Add garlic and tomato paste; stir and cook 5 minutes until paste darkens. 3. Add lentils, crushed tomatoes, broth, Italian seasoning, and salt; stir to combine. 4. Increase heat to medium-high until nearly boiling; reduce to medium-low. 5. Cover and simmer 35-40 minutes until lentils are tender. 6. Meanwhile cook pasta according to package directions; drain. 7. Serve bolognese over pasta topped with Parmesan.", "tags": "plant-based, high-fiber, whole-grain", "source": "https://www.skinnytaste.com/lentil-bolognese/", "nutritionData": "{\"calories\": 485, \"protein\": 23.0, \"carbs\": 84.0, \"fat\": 4.0}"},
  {"name": "Black Bean Brownies", "category": "Healthy Kids", "description": "Fudgy flourless brownies made with black beans and cocoa for a secretly nutritious treat.", "servings": 12, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 can\", \"name\": \"(15 oz) black beans (rinsed and drained)\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"maple syrup\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil (melted)\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsweetened cocoa powder\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/3 cup\", \"name\": \"dark chocolate chips\"}, {\"qty\": \"2 tbsp\", \"name\": \"dark chocolate chips (for topping)\"}]", "instructions": "1. Preheat oven to 350F and line a 12-cup muffin tin with liners; spray inside with nonstick spray. 2. Blend black beans and 1 egg in a food processor until very smooth. 3. Add remaining eggs, maple syrup, coconut oil, and vanilla; process until smooth. 4. Add cocoa powder, baking powder, and salt; process once more until smooth. 5. Fold in 1/3 cup chocolate chips. 6. Divide batter evenly among muffin cups; sprinkle 2 tbsp chocolate chips on top. 7. Bake 25 minutes until a toothpick comes out clean. 8. Cool 10 minutes before removing.", "tags": "gluten-free, naturally-sweet, hidden-veggie", "source": "https://www.ambitiouskitchen.com/gluten-free-flourless-black-bean-brownie-muffins/", "nutritionData": "{\"calories\": 165, \"protein\": 6.0, \"carbs\": 24.0, \"fat\": 6.0}"},
  {"name": "Avocado Egg Toast Fingers", "category": "Healthy Kids", "description": "Fun finger-food toast strips topped with creamy avocado and a fried egg for growing kids.", "servings": 2, "prepTime": 10, "cookTime": 5, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 slices\", \"name\": \"whole grain bread\"}, {\"qty\": \"1\", \"name\": \"ripe avocado\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"nonstick spray\"}]", "instructions": "1. Toast bread slices until golden. 2. Halve avocado, remove pit, and mash flesh with lime juice, garlic powder, salt, and pepper. 3. Spray a small skillet with nonstick spray over medium heat; fry eggs to desired doneness. 4. Spread avocado on toast slices. 5. Cut toast into finger-width strips. 6. Top each serving with a fried egg. 7. Serve immediately.", "tags": "healthy-fats, high-protein, breakfast", "source": "https://pinchmegood.com/kid-friendly-avocado-toast/", "nutritionData": "{\"calories\": 390, \"protein\": 14.0, \"carbs\": 37.0, \"fat\": 22.0}"},
  {"name": "Mini Turkey Burger Sliders on Whole Grain Buns", "category": "Healthy Kids", "description": "Juicy lean ground turkey mini burgers on whole grain slider buns with kid-friendly toppings.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"lean ground turkey (93%)\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole wheat breadcrumbs\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"8\", \"name\": \"whole grain slider buns\"}, {\"qty\": \"4 slices\", \"name\": \"reduced-fat cheddar cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"ketchup\"}, {\"qty\": \"\", \"name\": \"lettuce leaves\"}]", "instructions": "1. Mix ground turkey, breadcrumbs, egg, garlic powder, onion powder, salt, and pepper in a bowl. 2. Form into 8 small patties about 1/2 inch thick. 3. Heat a skillet over medium-high heat; spray with oil. 4. Cook patties 4-5 minutes per side until cooked through (internal temp 165F). 5. Add cheese in last minute of cooking. 6. Serve on slider buns with ketchup and lettuce.", "tags": "high-protein, kid-friendly, whole-grain", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 20.0, \"carbs\": 38.0, \"fat\": 11.0}"},
  {"name": "Chicken and Veggie Cauliflower Fried Rice", "category": "Healthy Kids", "description": "Low-carb cauliflower fried rice with tender chicken, peas, carrots, and scrambled egg.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"small head cauliflower (riced, about 4 cups)\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"onion (diced)\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"2\", \"name\": \"carrots (diced)\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"8 oz\", \"name\": \"cooked chicken breast (diced)\"}, {\"qty\": \"2\", \"name\": \"scallions (sliced)\"}]", "instructions": "1. Rice cauliflower in a food processor; squeeze out excess moisture with a towel. 2. Heat 1 tbsp oil in a large wok or skillet over medium-high heat; sauté onion, garlic, and carrots until tender, about 5 minutes. 3. Add frozen peas and cauliflower rice; cover and cook 5 minutes until slightly tender. 4. Push mixture to the side; add remaining oil and scramble eggs in the center until set. 5. Add chicken and stir everything together. 6. Add soy sauce and sesame oil; toss to combine. 7. Garnish with scallions and serve.", "tags": "low-carb, high-protein, veggie-packed", "source": "https://weelicious.com/asian-style-cauliflower-rice-recipe/", "nutritionData": "{\"calories\": 235, \"protein\": 19.0, \"carbs\": 12.0, \"fat\": 11.0}"},
  {"name": "Healthy Chicken Pot Pie with Whole Grain Crust", "category": "Healthy Kids", "description": "Classic comfort chicken pot pie with a tender whole wheat crust and vegetable-packed filling.", "servings": 6, "prepTime": 30, "cookTime": 55, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"whole wheat pastry flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/3 cup\", \"name\": \"cold unsalted butter (diced)\"}, {\"qty\": \"\", \"name\": \"2-3 tbsp ice water\"}, {\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast (cubed)\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2\", \"name\": \"onion (chopped)\"}, {\"qty\": \"2\", \"name\": \"carrots (sliced)\"}, {\"qty\": \"1 cup\", \"name\": \"diced potatoes\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1/3 cup\", \"name\": \"whole wheat flour\"}, {\"qty\": \"2 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"2% milk\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1\", \"name\": \"egg (for egg wash)\"}]", "instructions": "1. Make crust: mix WW flour and salt; cut in cold butter until pea-sized. Add ice water 1 tbsp at a time until dough comes together. Refrigerate 15 minutes. 2. Preheat oven to 375F. Heat oil in an oven-safe skillet; cook chicken 5 minutes until no longer pink; remove. 3. In same skillet, cook onion and carrots 3 minutes; stir in WW flour to coat. 4. Gradually whisk in broth and milk; add potatoes, peas, thyme, and salt; simmer until thickened, 5 minutes. 5. Stir in chicken; remove from heat. 6. Roll out dough and place over filling; press edges to seal and cut slits for steam. Brush with egg wash. 7. Bake 45-55 minutes until crust is golden.", "tags": "comfort-food, family-meal, whole-grain", "source": "https://www.ambitiouskitchen.com/healthy-chicken-pot-pie/", "nutritionData": "{\"calories\": 385, \"protein\": 29.0, \"carbs\": 34.0, \"fat\": 11.0}"},
  {"name": "Veggie-Loaded Chili", "category": "Healthy Kids", "description": "Mild kid-friendly turkey chili packed with beans, corn, and bell pepper.", "servings": 6, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"lean ground turkey (93%)\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2\", \"name\": \"onion (diced)\"}, {\"qty\": \"1\", \"name\": \"red bell pepper (diced)\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) kidney beans (drained)\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) black beans (drained)\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"1 cup\", \"name\": \"frozen corn\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded cheddar (for topping)\"}]", "instructions": "1. Heat olive oil in a large pot over medium-high heat; brown ground turkey breaking up into pieces, about 5 minutes. 2. Add onion, bell pepper, and garlic; cook 4 minutes until softened. 3. Stir in kidney beans, black beans, diced tomatoes, corn, broth, cumin, chili powder, paprika, and salt. 4. Bring to a boil, reduce heat to medium-low, and simmer 20-25 minutes until flavors meld. 5. Taste and adjust seasoning. 6. Serve in bowls topped with shredded cheddar.", "tags": "high-protein, high-fiber, make-ahead", "source": "https://www.skinnytaste.com/crock-pot-kid-friendly-turkey-chili/", "nutritionData": "{\"calories\": 370, \"protein\": 31.0, \"carbs\": 37.0, \"fat\": 12.0}"},
  {"name": "Greek Yogurt Fruit Dip with Whole Grain Crackers", "category": "Healthy Kids", "description": "Creamy honey-vanilla Greek yogurt dip served with fresh fruit and whole grain crackers.", "servings": 4, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"plain whole milk Greek yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"almond butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 cups\", \"name\": \"assorted sliced fresh fruit (strawberries, apple, grapes)\"}, {\"qty\": \"16\", \"name\": \"whole grain crackers\"}]", "instructions": "1. Add Greek yogurt, almond butter, honey, and vanilla to a medium bowl. 2. Stir together well until smooth and creamy. 3. Chill in refrigerator at least 15 minutes if time allows. 4. Arrange sliced fruit and crackers on a platter. 5. Serve dip alongside fruit and crackers for dipping.", "tags": "no-cook, snack, high-protein", "source": "https://www.yummytoddlerfood.com/yogurt-dip-for-fruit/", "nutritionData": "{\"calories\": 240, \"protein\": 9.0, \"carbs\": 31.0, \"fat\": 9.0}"},
  {"name": "Apple Peanut Butter Sandwiches", "category": "Healthy Kids", "description": "Crisp apple rings sandwiched with creamy natural peanut butter for a fun wholesome snack.", "servings": 2, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium apples\"}, {\"qty\": \"4 tbsp\", \"name\": \"natural peanut butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"granola\"}, {\"qty\": \"1 tsp\", \"name\": \"honey\"}, {\"qty\": \"\", \"name\": \"pinch of cinnamon\"}]", "instructions": "1. Core apples and cut into 1/4-inch rounds. 2. Spread 1 tablespoon peanut butter on half the apple rounds. 3. Sprinkle granola and a pinch of cinnamon on the peanut butter. 4. Drizzle lightly with honey. 5. Top each with another apple round to make sandwiches. 6. Serve immediately.", "tags": "no-cook, snack, naturally-sweet", "source": "Classic", "nutritionData": "{\"calories\": 325, \"protein\": 9.0, \"carbs\": 38.0, \"fat\": 17.0}"},
  {"name": "Quinoa-Stuffed Bell Peppers", "category": "Healthy Kids", "description": "Colorful bell peppers stuffed with seasoned quinoa, black beans, and melted cheese.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large bell peppers (halved and seeded)\"}, {\"qty\": \"1 cup\", \"name\": \"quinoa (rinsed)\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) black beans (drained)\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes (halved)\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen corn\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Mexican cheese blend\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Preheat oven to 425F and place pepper halves on a parchment-lined baking sheet. 2. Drizzle peppers with olive oil and bake 20-25 minutes until tender and slightly blistered. 3. Meanwhile cook quinoa in broth per package directions; fluff with a fork. 4. Mix quinoa with black beans, tomatoes, corn, cumin, chili powder, salt, and lime juice. 5. Stuff roasted pepper halves with quinoa mixture and top with cheese. 6. Bake another 12 minutes until cheese is golden. 7. Garnish with cilantro and serve.", "tags": "vegetarian, high-protein, whole-grain", "source": "https://cookieandkate.com/vegetarian-stuffed-peppers-recipe/", "nutritionData": "{\"calories\": 400, \"protein\": 21.0, \"carbs\": 56.0, \"fat\": 11.0}"},
  {"name": "Healthy Baked Fish Sticks with Whole Grain Breadcrumbs", "category": "Healthy Kids", "description": "Crispy oven-baked cod fish sticks coated in seasoned whole grain panko breadcrumbs.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.25 lb\", \"name\": \"cod fillet\"}, {\"qty\": \"2 cups\", \"name\": \"whole wheat panko breadcrumbs\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"milk\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"nonstick olive oil spray\"}]", "instructions": "1. Preheat oven to 400F; coat a large baking sheet with cooking spray. 2. Toast panko on the baking sheet for 2 minutes; stir and bake 2 more minutes until golden brown. 3. Transfer toasted panko to a bowl; mix in paprika, garlic powder, onion powder, salt, and pepper. 4. Pat cod dry and cut into 1-inch sticks about 3 inches long. 5. Whisk eggs and milk together in a shallow bowl. 6. Dip each fish stick in egg mixture then press into panko to coat; place on baking rack over baking sheet. 7. Spray tops with olive oil spray; bake 15-20 minutes until cooked through and golden.", "tags": "kid-favorite, high-protein, baked", "source": "https://www.ambitiouskitchen.com/homemade-baked-fish-sticks/", "nutritionData": "{\"calories\": 260, \"protein\": 32.0, \"carbs\": 21.0, \"fat\": 5.0}"},
  {"name": "Strawberry Banana Smoothie Bowl", "category": "Healthy Kids", "description": "Thick blended strawberry banana smoothie bowl topped with granola and fresh fruit for kids.", "servings": 2, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"frozen strawberries\"}, {\"qty\": \"1\", \"name\": \"medium banana\"}, {\"qty\": \"1/2 cup\", \"name\": \"vanilla Greek yogurt\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsweetened almond milk\"}, {\"qty\": \"1 tsp\", \"name\": \"honey\"}, {\"qty\": \"1/4 cup\", \"name\": \"granola\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh berries\"}, {\"qty\": \"1 tbsp\", \"name\": \"sliced banana (for topping)\"}]", "instructions": "1. Place frozen strawberries, banana, Greek yogurt, almond milk, and honey in a high-powered blender. 2. Blend until very thick and smooth, using the tamper to help blend. Add almond milk 1 tbsp at a time if needed. 3. Spoon thick smoothie into two bowls. 4. Top each bowl with granola, fresh berries, and banana slices. 5. Serve immediately.", "tags": "no-cook, kid-friendly, antioxidants", "source": "https://www.superhealthykids.com/kid-friendly-breakfast-smoothie-bowls/", "nutritionData": "{\"calories\": 255, \"protein\": 9.0, \"carbs\": 44.0, \"fat\": 5.0}"},
  {"name": "Whole Wheat Banana Bread", "category": "Healthy Kids", "description": "Moist honey-sweetened whole wheat banana bread with cinnamon that kids adore.", "servings": 10, "prepTime": 15, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 3/4 cups\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/3 cup\", \"name\": \"melted coconut oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"honey\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"mashed ripe bananas (about 2.5 bananas)\"}, {\"qty\": \"1/4 cup\", \"name\": \"milk\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Preheat oven to 325F and grease a 9x5 inch loaf pan. 2. In a large bowl, whisk coconut oil and honey together. 3. Beat in eggs, then stir in mashed bananas, milk, and vanilla. 4. Add baking soda, salt, and cinnamon; stir to combine. 5. Fold in flour just until combined (a few lumps are ok). 6. Pour batter into loaf pan and sprinkle lightly with extra cinnamon. 7. Bake 55-60 minutes until a toothpick comes out clean. 8. Cool in pan 10 minutes then transfer to a wire rack.", "tags": "naturally-sweet, whole-grain, snack", "source": "https://cookieandkate.com/healthy-banana-bread-recipe/", "nutritionData": "{\"calories\": 225, \"protein\": 5.0, \"carbs\": 37.0, \"fat\": 7.0}"},
  {"name": "Mini Whole Grain French Toast Sticks", "category": "Healthy Kids", "description": "Golden whole grain bread fingers dipped in a cinnamon egg custard and pan-toasted.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 slices\", \"name\": \"whole grain sandwich bread\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"milk\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tsp\", \"name\": \"butter\"}, {\"qty\": \"\", \"name\": \"maple syrup for serving\"}]", "instructions": "1. Whisk eggs, milk, honey, cinnamon, and vanilla in a shallow bowl. 2. Cut each bread slice into 3 finger-width sticks. 3. Melt butter in a large nonstick skillet over medium heat. 4. Dip bread sticks in egg mixture coating each side well. 5. Cook in batches 1.5-2 minutes per side until golden brown. 6. Add more butter as needed between batches. 7. Serve warm with maple syrup for dipping.", "tags": "kid-favorite, whole-grain, breakfast", "source": "https://weelicious.com/french-toast-on-a-stick/", "nutritionData": "{\"calories\": 265, \"protein\": 11.0, \"carbs\": 31.0, \"fat\": 8.0}"},
  {"name": "Chickpea Pasta with Veggie Sauce", "category": "Healthy Kids", "description": "High-protein chickpea pasta tossed with a blended tomato sauce packed with hidden vegetables.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"chickpea pasta (rotini or penne)\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2\", \"name\": \"onion (diced)\"}, {\"qty\": \"1\", \"name\": \"medium carrot (diced)\"}, {\"qty\": \"1\", \"name\": \"medium zucchini (diced)\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) crushed tomatoes\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Cook chickpea pasta per package directions; drain reserving 1/4 cup pasta water. 2. Heat olive oil in a saucepan over medium heat; sauté onion, carrot, and zucchini until soft, 8 minutes. 3. Add garlic and cook 1 minute. 4. Pour in crushed tomatoes and Italian seasoning; simmer 10 minutes. 5. Blend sauce with an immersion blender until smooth. 6. Toss pasta with sauce, adding pasta water to loosen if needed. 7. Serve topped with Parmesan and fresh basil.", "tags": "high-protein, hidden-veggies, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 315, \"protein\": 18.0, \"carbs\": 47.0, \"fat\": 7.0}"},
  {"name": "Carrot Zucchini Muffins", "category": "Healthy Kids", "description": "Moist mini muffins with grated carrot and zucchini sweetened with maple syrup in a whole wheat base.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"white whole wheat flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"melted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"maple syrup\"}, {\"qty\": \"1\", \"name\": \"large egg (beaten)\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"finely grated zucchini (squeezed dry)\"}, {\"qty\": \"1/2 cup\", \"name\": \"finely grated carrot\"}, {\"qty\": \"1/2 cup\", \"name\": \"raisins\"}]", "instructions": "1. Preheat oven to 350F and spray a mini muffin pan with nonstick spray. 2. Whisk flour, baking soda, cinnamon, and salt in a bowl. 3. In a large bowl, stir together melted butter, maple syrup, egg, and vanilla. 4. Add flour mixture to wet ingredients and stir just until combined. 5. Gently fold in zucchini, carrot, and raisins. 6. Fill mini muffin cups about 3/4 full using a small cookie scoop. 7. Bake 15-20 minutes until a toothpick inserted in the center comes out clean. 8. Cool in pan 5 minutes before removing.", "tags": "whole-grain, hidden-veggies, snack", "source": "https://cupcakesandkalechips.com/healthy-carrot-zucchini-mini-muffins/", "nutritionData": "{\"calories\": 245, \"protein\": 4.0, \"carbs\": 44.0, \"fat\": 7.0}"},
  {"name": "Classic Chicken Noodle Soup", "category": "Soups & Stews", "description": "A comforting, golden chicken broth loaded with tender shredded chicken, egg noodles, and vegetables.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"bone-in chicken thighs\"}, {\"qty\": \"8 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"3\", \"name\": \"large carrots, diced\"}, {\"qty\": \"3\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 cups\", \"name\": \"egg noodles, dry\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion, carrots, and celery and cook until softened, about 6 minutes. Add garlic and cook 1 minute more. 2. Add chicken broth, chicken thighs, bay leaf, thyme, and parsley. Bring to a boil, then reduce heat and simmer for 35 minutes. 3. Remove chicken thighs, shred the meat, and discard bones. Return shredded chicken to the pot. 4. Add egg noodles and cook until tender, about 8 minutes. Remove bay leaf, season with salt and pepper, and serve.", "tags": "comfort food, classic, make-ahead", "source": "https://www.halfbakedharvest.com/creamy-homestyle-chicken-noodle-soup/", "nutritionData": "{\"calories\": 378, \"protein\": 31.0, \"carbs\": 23.0, \"fat\": 17.0}"},
  {"name": "French Onion Soup", "category": "Soups & Stews", "description": "Deeply caramelized onions in a rich beef broth topped with toasted baguette and melted Gruyere cheese.", "servings": 4, "prepTime": 15, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"yellow onions, thinly sliced\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry sherry\"}, {\"qty\": \"6 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"4\", \"name\": \"thick slices baguette\"}, {\"qty\": \"4 oz\", \"name\": \"Gruyere cheese, shredded\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Melt butter with olive oil in a large Dutch oven over medium-high heat. Add onions and sugar, season with salt. Cook, stirring often, until deeply caramelized and golden, about 60 minutes. 2. Add sherry and scrape up any browned bits. Cook until reduced by half, about 2 minutes. 3. Add beef broth, Worcestershire, and thyme. Simmer for 20 minutes. Season with salt and pepper. 4. Ladle soup into oven-safe bowls. Top each with a baguette slice and a generous handful of Gruyere. Broil until cheese is bubbly and golden, 2 to 3 minutes. Serve immediately.", "tags": "French, classic, cozy", "source": "https://www.seriouseats.com/french-onion-soup-recipe", "nutritionData": "{\"calories\": 564, \"protein\": 19.0, \"carbs\": 59.0, \"fat\": 21.0}"},
  {"name": "All-American Beef Stew", "category": "Soups & Stews", "description": "Hearty beef chuck braised with potatoes, carrots, and celery in a deeply savory red wine broth.", "servings": 6, "prepTime": 30, "cookTime": 120, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"beef chuck, cut into 1.5-inch pieces\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3\", \"name\": \"large carrots, cut into chunks\"}, {\"qty\": \"3\", \"name\": \"stalks celery, cut into chunks\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"3\", \"name\": \"medium Yukon gold potatoes, cubed\"}, {\"qty\": \"1 cup\", \"name\": \"red wine\"}, {\"qty\": \"3 cups\", \"name\": \"beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Pat beef dry, season with salt and pepper, and dust with flour. Heat oil in a Dutch oven over high heat. Sear beef in batches until browned on all sides, about 5 minutes per batch. Transfer to a plate. 2. Reduce heat to medium. Add onion, carrots, and celery; cook 5 minutes. Add garlic and tomato paste; cook 1 minute. 3. Add red wine and scrape up browned bits. Simmer 2 minutes. Add broth, Worcestershire, thyme, bay leaves, and seared beef. Bring to a boil. 4. Reduce heat to low, cover, and simmer 1 hour. Add potatoes and cook until tender, about 30 minutes more. Remove bay leaves, season to taste, and serve.", "tags": "hearty, comfort food, weekend cooking", "source": "https://www.seriouseats.com/all-american-beef-stew-recipe", "nutritionData": "{\"calories\": 519, \"protein\": 34.0, \"carbs\": 27.0, \"fat\": 27.0}"},
  {"name": "Tomato Basil Soup", "category": "Soups & Stews", "description": "Velvety roasted tomato soup blended smooth with fresh basil and a swirl of cream.", "servings": 4, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ripe tomatoes, halved\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, quartered\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic, unpeeled\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F. Toss tomatoes, onion, and garlic with 2 tbsp olive oil on a baking sheet. Roast until caramelized, about 25 minutes. Squeeze garlic from skins. 2. Transfer roasted vegetables to a large pot. Add broth and bring to a simmer over medium heat for 10 minutes. 3. Add basil and blend with an immersion blender until smooth. Stir in heavy cream and sugar. Season with salt and pepper. 4. Serve hot with crusty bread or a grilled cheese sandwich.", "tags": "vegetarian, blended, comfort food", "source": "https://smittenkitchen.com/2024/03/weeknight-tomato-soup/", "nutritionData": "{\"calories\": 255, \"protein\": 2.0, \"carbs\": 7.0, \"fat\": 21.0}"},
  {"name": "Chili Con Carne", "category": "Soups & Stews", "description": "Bold and smoky ground beef chili with dried chiles, kidney beans, and deep Tex-Mex spices.", "servings": 6, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"2 cans\", \"name\": \"(15 oz each) kidney beans, drained\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) diced tomatoes\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Heat oil in a large pot over medium-high heat. Add onion and cook until softened, about 5 minutes. Add garlic and cook 1 minute. 2. Add ground beef and cook, breaking it up, until browned. Drain excess fat. 3. Stir in chili powder, cumin, paprika, oregano, and cayenne. Cook for 1 minute. Add tomatoes, broth, and kidney beans. 4. Bring to a boil, then reduce heat and simmer uncovered for 45 minutes, stirring occasionally, until thickened. Season with salt and serve with sour cream, cheddar, and scallions.", "tags": "Tex-Mex, hearty, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 554, \"protein\": 46.0, \"carbs\": 27.0, \"fat\": 31.0}"},
  {"name": "White Chicken Chili", "category": "Soups & Stews", "description": "Creamy and mildly spiced white bean chicken chili with green chiles, cumin, and Monterey Jack.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"2 cans\", \"name\": \"(15 oz each) white cannellini beans, drained\"}, {\"qty\": \"2 cans\", \"name\": \"(4 oz each) diced green chiles\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese, softened\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Heat oil in a large pot over medium heat. Add onion and cook 5 minutes. Add garlic, cumin, oregano, and chili powder; cook 1 minute. 2. Add chicken breasts, broth, beans, and green chiles. Bring to a boil, then simmer 20 minutes until chicken is cooked through. 3. Remove chicken and shred with two forks. Return to pot. 4. Stir in cream cheese and sour cream until melted and smooth. Season with salt and pepper. Serve with lime wedges, cilantro, and tortilla chips.", "tags": "creamy, crowd-pleaser, quick", "source": "Classic", "nutritionData": "{\"calories\": 443, \"protein\": 43.0, \"carbs\": 23.0, \"fat\": 19.0}"},
  {"name": "Classic Minestrone", "category": "Soups & Stews", "description": "A hearty Italian vegetable soup brimming with beans, seasonal vegetables, pasta, and fresh herbs.", "servings": 6, "prepTime": 20, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2\", \"name\": \"large carrots, diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"1\", \"name\": \"zucchini, diced\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) diced tomatoes\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) kidney beans, drained\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"3/4 cup\", \"name\": \"ditalini pasta\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion, carrots, and celery; cook 8 minutes until softened. Add garlic, oregano, and basil; cook 1 minute. 2. Stir in diced tomatoes, broth, water, and kidney beans. Bring to a boil, then simmer covered for 20 minutes. 3. Add zucchini and ditalini pasta. Cook uncovered, stirring occasionally, for 10 minutes until pasta is al dente. 4. Season with salt and pepper. Serve topped with grated Parmesan.", "tags": "vegetarian, Italian, make-ahead", "source": "https://www.recipetineats.com/minestrone-soup/", "nutritionData": "{\"calories\": 232, \"protein\": 8.0, \"carbs\": 34.0, \"fat\": 6.0}"},
  {"name": "Italian Wedding Soup", "category": "Soups & Stews", "description": "Savory chicken broth with tender pork and beef mini-meatballs, orzo pasta, and wilted spinach.", "servings": 6, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1/4 cup\", \"name\": \"breadcrumbs\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"8 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"3/4 cup\", \"name\": \"orzo pasta\"}, {\"qty\": \"4 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"2\", \"name\": \"medium carrots, diced\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Italian seasoning\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Mix ground pork, beef, breadcrumbs, egg, Parmesan, garlic, Italian seasoning, salt, and pepper in a bowl. Roll into 1-inch meatballs and place on a baking sheet. Bake at 375°F for 15 minutes. 2. Heat olive oil in a large pot over medium heat. Add onion and carrots; cook 6 minutes until softened. 3. Pour in chicken broth and bring to a boil. Add orzo and cook for 8 minutes, stirring occasionally. 4. Add meatballs and spinach. Simmer 3 minutes until spinach is wilted. Season with salt and pepper. Serve with extra Parmesan.", "tags": "Italian, hearty, classic", "source": "Classic", "nutritionData": "{\"calories\": 368, \"protein\": 24.0, \"carbs\": 20.0, \"fat\": 18.0}"},
  {"name": "Pasta e Fagioli", "category": "Soups & Stews", "description": "Classic Italian pasta and bean soup with a rich tomato base, rosemary, and a drizzle of olive oil.", "servings": 6, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"2\", \"name\": \"medium carrots, diced\"}, {\"qty\": \"1 can\", \"name\": \"(28 oz) crushed tomatoes\"}, {\"qty\": \"2 cans\", \"name\": \"(15 oz each) cannellini beans, drained\"}, {\"qty\": \"4 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"ditalini pasta\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"salt and red pepper flakes to taste\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion, celery, and carrots; cook 8 minutes until soft. Add garlic and rosemary; cook 1 minute. 2. Add crushed tomatoes, broth, and one can of beans. Mash the other can of beans roughly with a fork and add to pot. Bring to a simmer. 3. Cook covered for 20 minutes. Remove rosemary sprigs. Add ditalini pasta and cook 10 minutes until al dente. 4. Season with salt and red pepper flakes. Ladle into bowls, drizzle with olive oil, and top with Parmesan.", "tags": "Italian, vegetarian, filling", "source": "https://www.seriouseats.com/recipes/2012/01/30-minute-pasta-and-kidney-bean-soup-pasta-e-fagioli-recipe.html", "nutritionData": "{\"calories\": 305, \"protein\": 13.0, \"carbs\": 47.0, \"fat\": 6.0}"},
  {"name": "Tuscan White Bean Soup", "category": "Soups & Stews", "description": "A Ribollita-inspired Tuscan soup with cannellini beans, kale, Italian sausage, and sun-dried tomatoes.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"Italian sausage, removed from casing\"}, {\"qty\": \"2 cans\", \"name\": \"(15 oz each) cannellini beans, drained\"}, {\"qty\": \"3 cups\", \"name\": \"kale, stems removed, roughly chopped\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"3\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"2\", \"name\": \"medium carrots, diced\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1/3 cup\", \"name\": \"sun-dried tomatoes in oil, chopped\"}, {\"qty\": \"3 tbsp\", \"name\": \"sun-dried tomato oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Heat sun-dried tomato oil in a large Dutch oven over medium-high heat. Add sausage and onion; cook, breaking up meat, until browned, about 6 minutes. 2. Add garlic, shallots, carrots, celery, and Italian seasoning. Cook 5 minutes until vegetables begin to soften. 3. Add broth and simmer for 10 minutes. Stir in kale, sun-dried tomatoes, and cannellini beans. Simmer 5 more minutes. 4. Stir in heavy cream and Parmesan. Season with salt and pepper. Serve with crusty bread.", "tags": "Italian, hearty, creamy", "source": "https://www.halfbakedharvest.com/white-bean-lemon-soup/", "nutritionData": "{\"calories\": 478, \"protein\": 18.0, \"carbs\": 25.0, \"fat\": 33.0}"},
  {"name": "Corn Chowder with Bacon", "category": "Soups & Stews", "description": "Thick, creamy corn chowder with smoky bacon, Yukon gold potatoes, and sweet summer corn.", "servings": 6, "prepTime": 20, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"ears fresh corn, kernels cut off (or 4 cups frozen corn)\"}, {\"qty\": \"6\", \"name\": \"strips bacon, chopped\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"3\", \"name\": \"medium Yukon gold potatoes, diced\"}, {\"qty\": \"4 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2\", \"name\": \"green onions, sliced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cook bacon in a large pot over medium heat until crispy. Remove with a slotted spoon and set aside, leaving fat in pot. 2. Add butter, onion, and garlic to pot; cook 5 minutes. Add flour and stir to coat. 3. Pour in broth, milk, potatoes, paprika, and thyme. Bring to a boil, then simmer 15 minutes until potatoes are tender. 4. Add corn and heavy cream. Simmer 5 minutes. Using an immersion blender, partially blend for a creamy but chunky texture. Season with salt and pepper. Serve topped with bacon and green onions.", "tags": "creamy, summer, comfort food", "source": "https://www.recipetineats.com/corn-chowder-with-bacon/", "nutritionData": "{\"calories\": 372, \"protein\": 11.0, \"carbs\": 46.0, \"fat\": 15.0}"},
  {"name": "Broccoli Cheddar Soup", "category": "Soups & Stews", "description": "Velvety cheddar soup with roasted broccoli and a rich, cheesy base that tastes deeply of broccoli.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large head broccoli (about 1.5 lbs), cut into florets\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2 cups\", \"name\": \"sharp cheddar cheese, shredded\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F. Toss half the broccoli florets with 1 tbsp olive oil, salt, and pepper on a baking sheet. Roast 15 minutes until browned. 2. Melt butter in a large pot over medium heat. Add onion and cook 5 minutes. Add garlic and flour; stir 1 minute. Gradually whisk in broth, then milk. 3. Add the remaining raw broccoli to the pot. Simmer 12 minutes until tender. Blend until smooth with immersion blender. 4. Stir in heavy cream and cheddar until melted and smooth. Season with nutmeg, salt, and pepper. Top with roasted broccoli and serve.", "tags": "cheesy, vegetarian, comfort food", "source": "https://www.seriouseats.com/broccoli-cheddar-cheese-soup-food-lab-recipe", "nutritionData": "{\"calories\": 567, \"protein\": 25.0, \"carbs\": 23.0, \"fat\": 40.0}"},
  {"name": "Butternut Squash Soup", "category": "Soups & Stews", "description": "Silky roasted butternut squash soup with warming spices, apple, and a touch of cream.", "servings": 4, "prepTime": 20, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"large butternut squash (about 3 lbs), peeled and cubed\"}, {\"qty\": \"1\", \"name\": \"medium apple, peeled and diced\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 cups\", \"name\": \"vegetable or chicken broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F. Toss squash and apple with 2 tbsp olive oil, salt, and pepper. Roast for 25 minutes until caramelized and tender. 2. Heat remaining olive oil in a large pot. Add onion and cook 5 minutes. Add garlic, cinnamon, nutmeg, and ginger; cook 1 minute. 3. Add broth and roasted squash and apple. Bring to a simmer and cook for 10 minutes. 4. Blend until smooth with an immersion blender. Stir in heavy cream and maple syrup. Season and serve with a swirl of cream and pumpkin seeds.", "tags": "vegetarian, fall, creamy", "source": "Classic", "nutritionData": "{\"calories\": 408, \"protein\": 6.0, \"carbs\": 53.0, \"fat\": 21.0}"},
  {"name": "Split Pea and Ham Soup", "category": "Soups & Stews", "description": "Hearty, thick green split pea soup cooked with a smoky ham hock and aromatic vegetables.", "servings": 8, "prepTime": 15, "cookTime": 75, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried green split peas, rinsed\"}, {\"qty\": \"1\", \"name\": \"smoked ham hock\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"3\", \"name\": \"large carrots, diced\"}, {\"qty\": \"3\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"8 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 cup\", \"name\": \"diced ham\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion, carrots, and celery; cook 6 minutes. Add garlic and thyme; cook 1 minute. 2. Add split peas, ham hock, broth, and bay leaves. Bring to a boil, then reduce heat to a bare simmer. Cover and cook 60 minutes, stirring occasionally, until peas break down completely. 3. Remove ham hock; strip meat from bone and chop. Remove bay leaves. Add chopped ham back to pot along with the diced ham. 4. Season with salt and pepper. Serve hot with crusty bread.", "tags": "hearty, make-ahead, comfort food", "source": "https://www.seriouseats.com/30-minute-pressure-cooker-split-pea-soup-recipe", "nutritionData": "{\"calories\": 280, \"protein\": 22.0, \"carbs\": 39.0, \"fat\": 3.0}"},
  {"name": "Red Lentil Soup", "category": "Soups & Stews", "description": "A warming, spiced red lentil soup with cumin, turmeric, and a bright lemon finish.", "servings": 6, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"red lentils, rinsed\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2\", \"name\": \"medium carrots, diced\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"6 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"ground turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion and carrots; cook 6 minutes. Add garlic, cumin, turmeric, paprika, and cayenne; stir 1 minute until fragrant. 2. Add lentils, diced tomatoes, and broth. Bring to a boil, then reduce heat and simmer uncovered for 20 minutes until lentils are completely soft. 3. Use an immersion blender to partially blend the soup for a creamy yet textured consistency. 4. Stir in lemon juice, season with salt and pepper, and serve drizzled with olive oil.", "tags": "vegan, healthy, quick", "source": "https://www.recipetineats.com/lentil-soup/", "nutritionData": "{\"calories\": 283, \"protein\": 15.0, \"carbs\": 38.0, \"fat\": 8.0}"},
  {"name": "Spiced Black Bean Soup", "category": "Soups & Stews", "description": "Smoky, earthy black bean soup seasoned with cumin and chipotle, finished with lime and cilantro.", "servings": 6, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 cans\", \"name\": \"(15 oz each) black beans, drained\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o, seeded and minced\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1\", \"name\": \"chipotle pepper in adobo, minced\"}, {\"qty\": \"4 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro, chopped\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Heat oil in a large pot over medium heat. Add onion, jalapeño, and a pinch of salt. Cook until softened, about 8 minutes. Add garlic, cumin, paprika, and chipotle; cook 1 minute. 2. Add black beans and broth. Bring to a boil, then simmer for 20 minutes. 3. Transfer about half the soup to a blender and puree until smooth, then return to pot (or use immersion blender partially). 4. Stir in lime juice and cilantro. Season with salt. Serve with sour cream, avocado, and warm tortillas.", "tags": "vegan, Latin-inspired, healthy", "source": "Classic", "nutritionData": "{\"calories\": 210, \"protein\": 11.0, \"carbs\": 30.0, \"fat\": 5.0}"},
  {"name": "Homemade Miso Soup", "category": "Soups & Stews", "description": "Traditional Japanese miso soup with dashi broth, silken tofu, wakame seaweed, and scallions.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"dashi stock (or water with 1 tbsp dashi powder)\"}, {\"qty\": \"3 tbsp\", \"name\": \"white miso paste\"}, {\"qty\": \"6 oz\", \"name\": \"silken tofu, cut into small cubes\"}, {\"qty\": \"2 tbsp\", \"name\": \"dried wakame seaweed\"}, {\"qty\": \"3\", \"name\": \"green onions, thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}]", "instructions": "1. Soak wakame in cold water for 5 minutes, then drain and gently squeeze out excess water. 2. Bring dashi to a gentle simmer in a medium saucepan over medium heat. Do not boil. 3. Place miso paste in a small bowl, ladle some hot dashi over it, and whisk until dissolved. Stir miso mixture back into the pot. 4. Add tofu and wakame; heat gently for 2 minutes. Do not boil after adding miso. Divide into bowls and garnish with green onions and sesame oil.", "tags": "Japanese, vegan, quick", "source": "Classic", "nutritionData": "{\"calories\": 92, \"protein\": 10.0, \"carbs\": 4.0, \"fat\": 5.0}"},
  {"name": "Tonkotsu Ramen Broth", "category": "Soups & Stews", "description": "Rich, cloudy pork bone broth for ramen, served with noodles, chashu pork, and a soft-boiled egg.", "servings": 4, "prepTime": 30, "cookTime": 240, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"pork neck bones\"}, {\"qty\": \"1 lb\", \"name\": \"pork trotters\"}, {\"qty\": \"1 lb\", \"name\": \"pork belly, for chashu\"}, {\"qty\": \"4\", \"name\": \"ramen noodle cakes\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"1 tbsp\", \"name\": \"sake\"}, {\"qty\": \"4\", \"name\": \"green onions, sliced\"}, {\"qty\": \"4 sheets\", \"name\": \"nori\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger, sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}]", "instructions": "1. Blanch pork bones in boiling water for 5 minutes, drain, and rinse. Return to pot, cover with cold water, add ginger and garlic. Boil vigorously for 3 to 4 hours until broth is milky white and rich. 2. Roll pork belly tightly, tie with twine, and braise in soy sauce, mirin, sake, and 1 cup water for 2 hours until tender. Cool and slice into rounds. 3. Soft-boil eggs for 7 minutes, shock in ice water, peel, and marinate in leftover chashu braising liquid for 4 hours. 4. Cook ramen noodles per package. Divide broth into bowls, add noodles, sliced chashu, halved eggs, nori, green onions, sesame seeds, and sesame oil.", "tags": "Japanese, umami, weekend project", "source": "Classic", "nutritionData": "{\"calories\": 1174, \"protein\": 54.0, \"carbs\": 69.0, \"fat\": 64.0}"},
  {"name": "Hot and Sour Soup", "category": "Soups & Stews", "description": "Classic Chinese hot and sour soup with wood ear mushrooms, tofu, bamboo shoots, and silky egg ribbons.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"6 oz\", \"name\": \"firm tofu, cut into thin strips\"}, {\"qty\": \"1 cup\", \"name\": \"shiitake mushrooms, sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"bamboo shoots, julienned\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"cornstarch mixed with 3 tbsp water\"}, {\"qty\": \"2\", \"name\": \"large eggs, beaten\"}, {\"qty\": \"2\", \"name\": \"green onions, sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"rehydrated wood ear mushrooms, sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}]", "instructions": "1. Bring broth to a simmer in a large pot over medium heat. Add soy sauce, sugar, and white pepper. 2. Add shiitake mushrooms, wood ear mushrooms, bamboo shoots, and tofu. Simmer 5 minutes. 3. Stir in cornstarch slurry and cook until broth thickens, about 2 minutes. Reduce heat to low. 4. Add rice vinegar and sesame oil. Slowly pour beaten eggs into soup in a thin stream while stirring gently to form egg ribbons. Serve garnished with green onions.", "tags": "Chinese, spicy-sour, restaurant-style", "source": "https://www.seriouseats.com/hot-and-sour-soup-food-lab", "nutritionData": "{\"calories\": 155, \"protein\": 13.0, \"carbs\": 8.0, \"fat\": 6.0}"},
  {"name": "Tom Yum Goong", "category": "Soups & Stews", "description": "Fragrant Thai hot and sour prawn soup with lemongrass, kaffir lime, galangal, and chili.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"large shrimp, peeled and deveined\"}, {\"qty\": \"5 cups\", \"name\": \"chicken or shrimp broth\"}, {\"qty\": \"2\", \"name\": \"stalks lemongrass, bruised and cut into pieces\"}, {\"qty\": \"4\", \"name\": \"kaffir lime leaves, torn\"}, {\"qty\": \"3 slices\", \"name\": \"galangal or fresh ginger\"}, {\"qty\": \"2\", \"name\": \"Thai chiles, sliced\"}, {\"qty\": \"1 cup\", \"name\": \"oyster mushrooms, torn\"}, {\"qty\": \"3 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"2\", \"name\": \"green onions, chopped\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Bring broth to a boil in a large pot. Add lemongrass, kaffir lime leaves, galangal, and Thai chiles. Simmer 5 minutes to infuse. 2. Add mushrooms and simmer 3 minutes. Add shrimp and cook just until pink, about 2 minutes. 3. Season with fish sauce, lime juice, and sugar. Adjust to your taste — it should be hot, sour, and savory. 4. Ladle into bowls, garnish with green onions and cilantro, and serve with steamed rice.", "tags": "Thai, spicy, seafood", "source": "Classic", "nutritionData": "{\"calories\": 153, \"protein\": 29.0, \"carbs\": 4.0, \"fat\": 0.0}"},
  {"name": "Andalusian Gazpacho", "category": "Soups & Stews", "description": "Chilled Spanish tomato soup blended with cucumber, bell pepper, garlic, and sherry vinegar.", "servings": 6, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ripe tomatoes, cored and roughly chopped\"}, {\"qty\": \"1\", \"name\": \"English cucumber, peeled and seeded\"}, {\"qty\": \"1\", \"name\": \"red bell pepper, cored and seeded\"}, {\"qty\": \"2 slices\", \"name\": \"stale white bread, crusts removed\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/3 cup\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"sherry vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"cold water\"}]", "instructions": "1. Soak bread in cold water for 5 minutes, then squeeze dry. 2. Combine tomatoes, cucumber, bell pepper, bread, and garlic in a blender. Blend until smooth. 3. With the blender running, drizzle in olive oil. Add sherry vinegar, salt, and sugar. Blend until completely smooth and emulsified. 4. Add cold water to adjust consistency. Season to taste, then refrigerate for at least 2 hours until very cold. Serve in chilled bowls with a drizzle of olive oil.", "tags": "vegan, no-cook, Spanish", "source": "Classic", "nutritionData": "{\"calories\": 188, \"protein\": 1.0, \"carbs\": 14.0, \"fat\": 14.0}"},
  {"name": "Vichyssoise", "category": "Soups & Stews", "description": "A classic French cold cream soup made with sautéed leeks and potatoes, served chilled.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large leeks, white and light green parts only, sliced\"}, {\"qty\": \"3\", \"name\": \"medium Yukon gold potatoes, peeled and diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"4 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"fresh chives for garnish\"}]", "instructions": "1. Melt butter in a large pot over medium heat. Add leeks and cook until very soft, about 10 minutes. Do not brown. 2. Add potatoes and broth. Bring to a boil, then simmer covered for 20 minutes until potatoes are completely tender. 3. Blend soup until completely smooth with an immersion blender. Stir in heavy cream and milk. Season with salt and white pepper. 4. Chill in the refrigerator for at least 4 hours or overnight. Serve cold in chilled bowls, garnished with chives.", "tags": "French, cold soup, elegant", "source": "https://smittenkitchen.com/2025/01/potato-leek-soup/", "nutritionData": "{\"calories\": 464, \"protein\": 9.0, \"carbs\": 37.0, \"fat\": 29.0}"},
  {"name": "Creamy Mushroom Soup", "category": "Soups & Stews", "description": "A rich, velvety mushroom soup blended smooth with caramelized cremini and a splash of sherry.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"cremini mushrooms, sliced\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry sherry\"}, {\"qty\": \"4 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lemon\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley, minced\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Melt butter in a large pot over medium-high heat. Add mushrooms in a single layer (in batches) and cook until browned and liquid evaporates, about 12 minutes. Season with salt and pepper. 2. Add onion and cook until softened, 3 minutes. Add garlic and flour; stir 1 minute. 3. Pour in sherry and scrape up browned bits. Add broth, milk, thyme, and bay leaf. Simmer 20 minutes. Remove thyme and bay leaf. 4. Blend until smooth with an immersion blender. Squeeze in lemon juice, season to taste, and serve garnished with parsley.", "tags": "vegetarian, umami, cozy", "source": "https://www.recipetineats.com/mushroom-soup/", "nutritionData": "{\"calories\": 230, \"protein\": 9.0, \"carbs\": 17.0, \"fat\": 11.0}"},
  {"name": "Creamy Wild Rice Chicken Soup", "category": "Soups & Stews", "description": "Cozy, creamy chicken soup with nutty wild rice, roasted mushrooms, carrots, and Parmesan.", "servings": 6, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1.5 cups\", \"name\": \"dry wild rice blend\"}, {\"qty\": \"4\", \"name\": \"large carrots, chopped\"}, {\"qty\": \"3\", \"name\": \"stalks celery, chopped\"}, {\"qty\": \"2\", \"name\": \"shallots, diced\"}, {\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"1 lb\", \"name\": \"mixed mushrooms, torn\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, smashed\"}, {\"qty\": \"2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. In a large pot, combine chicken, wild rice, carrots, celery, shallots, broth, thyme, and season with salt and pepper. Bring to a boil, cover, and simmer for 45 minutes until rice is tender. 2. Meanwhile, roast mushrooms: toss with 3 tbsp butter, garlic, rosemary, and salt on a sheet pan. Roast at 425°F for 25 minutes until golden and crisp. 3. Shred cooked chicken with two forks. Stir cream, Parmesan, and spinach into the soup; cook until wilted. 4. Mash roasted garlic and stir mushrooms into soup. Divide into bowls and serve topped with fresh rosemary.", "tags": "cozy, creamy, make-ahead", "source": "https://www.halfbakedharvest.com/creamy-wild-rice-chicken-soup/", "nutritionData": "{\"calories\": 568, \"protein\": 37.0, \"carbs\": 39.0, \"fat\": 25.0}"},
  {"name": "Cajun Chicken and Andouille Gumbo", "category": "Soups & Stews", "description": "Authentic Louisiana gumbo with a dark chocolate roux, chicken, andouille sausage, and okra.", "servings": 8, "prepTime": 30, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless chicken thighs\"}, {\"qty\": \"1 lb\", \"name\": \"andouille sausage, sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"2\", \"name\": \"green bell peppers, diced\"}, {\"qty\": \"4\", \"name\": \"stalks celery, diced\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"sliced okra\"}, {\"qty\": \"2 tsp\", \"name\": \"Cajun seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"cooked white rice for serving\"}, {\"qty\": \"\", \"name\": \"sliced green onions and hot sauce for serving\"}]", "instructions": "1. Make the roux: heat oil in a large Dutch oven over medium heat. Whisk in flour and cook, stirring constantly, until a deep chocolate brown color, 20 to 25 minutes. Do not burn. 2. Add onion, bell pepper, and celery to the roux. Cook until very soft, about 8 minutes. Add garlic and cook 1 minute. 3. Gradually whisk in chicken broth. Add Cajun seasoning, thyme, bay leaves, sausage, and chicken. Bring to a boil, then simmer for 45 minutes. 4. Remove chicken, shred, and return to pot. Add okra and simmer 10 more minutes. Remove bay leaves. Serve over rice with green onions and hot sauce.", "tags": "Cajun, Southern, hearty", "source": "https://www.seriouseats.com/cajun-gumbo-with-chicken-and-andouille-recipe", "nutritionData": "{\"calories\": 526, \"protein\": 30.0, \"carbs\": 11.0, \"fat\": 38.0}"},
  {"name": "Pork Posole Rojo", "category": "Soups & Stews", "description": "A Mexican pork and hominy stew with a rich dried chile broth and classic garnishes.", "servings": 8, "prepTime": 30, "cookTime": 120, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"pork shoulder, cubed\"}, {\"qty\": \"2 cans\", \"name\": \"(25 oz each) hominy, drained\"}, {\"qty\": \"4\", \"name\": \"dried guajillo chiles, stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"dried ancho chiles, stemmed and seeded\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, halved\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic\"}, {\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"shredded cabbage, radishes, lime, and dried oregano for serving\"}]", "instructions": "1. Toast dried chiles in a dry skillet for 30 seconds per side. Soak in hot water for 15 minutes. Drain and blend with garlic and 1 cup soaking liquid to form a smooth paste. 2. Heat oil in a large pot. Brown pork in batches over high heat. Remove pork and set aside. 3. Add onion and cook until softened, 5 minutes. Add chile paste and cook 3 minutes. Add broth, pork, oregano, and cumin. Bring to a boil, then simmer covered for 1 hour. 4. Add hominy and simmer uncovered for 30 more minutes until pork is very tender. Season with salt. Serve with cabbage, radishes, and lime wedges.", "tags": "Mexican, hearty, weekend cooking", "source": "https://www.seriouseats.com/pork-hominy-soup-recipe", "nutritionData": "{\"calories\": 480, \"protein\": 29.0, \"carbs\": 26.0, \"fat\": 28.0}"},
  {"name": "Kimchi Jjigae", "category": "Soups & Stews", "description": "Bold and fiery Korean kimchi stew with pork belly, silken tofu, and a deeply savory red broth.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"fermented kimchi, roughly chopped\"}, {\"qty\": \"1/2 lb\", \"name\": \"pork belly, cut into bite-sized pieces\"}, {\"qty\": \"1\", \"name\": \"block (14 oz) firm tofu, sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"gochugaru (Korean red pepper flakes)\"}, {\"qty\": \"1 tbsp\", \"name\": \"gochujang (Korean chili paste)\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"3 cups\", \"name\": \"water or pork broth\"}, {\"qty\": \"1\", \"name\": \"small onion, sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2\", \"name\": \"green onions, chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}]", "instructions": "1. In a medium pot, add pork belly, kimchi, onion, and garlic. Cook over medium heat, stirring, for 5 minutes to sauté slightly. 2. Add gochugaru, gochujang, soy sauce, and sugar. Stir to coat everything. 3. Pour in water or broth. Bring to a boil, then reduce heat and simmer for 20 minutes until pork is tender. 4. Gently add tofu and simmer 5 more minutes. Drizzle with sesame oil and garnish with green onions. Serve with steamed white rice.", "tags": "Korean, spicy, fermented", "source": "Classic", "nutritionData": "{\"calories\": 396, \"protein\": 24.0, \"carbs\": 9.0, \"fat\": 31.0}"},
  {"name": "Irish Lamb Stew", "category": "Soups & Stews", "description": "Traditional Irish stew with tender lamb shoulder, waxy potatoes, carrots, and pearl barley.", "servings": 6, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"lamb shoulder, cut into 1.5-inch pieces\"}, {\"qty\": \"1.5 lbs\", \"name\": \"Yukon gold potatoes, quartered\"}, {\"qty\": \"3\", \"name\": \"large carrots, cut into chunks\"}, {\"qty\": \"1\", \"name\": \"large yellow onion, diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"pearl barley\"}, {\"qty\": \"4 cups\", \"name\": \"lamb or chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Season lamb with salt and pepper. Heat oil in a Dutch oven over high heat; sear lamb in batches until browned, about 4 minutes per batch. Transfer to a plate. 2. Reduce heat to medium. Add onion and garlic; cook 5 minutes. 3. Add broth, water, barley, thyme, bay leaves, and seared lamb. Bring to a boil, then cover and simmer for 45 minutes. 4. Add potatoes and carrots. Simmer uncovered for 30 minutes until vegetables are tender and broth has thickened slightly. Remove bay leaves, season, and serve garnished with parsley.", "tags": "Irish, hearty, winter", "source": "Classic", "nutritionData": "{\"calories\": 443, \"protein\": 23.0, \"carbs\": 37.0, \"fat\": 22.0}"},
  {"name": "Beef Bourguignon", "category": "Soups & Stews", "description": "The classic French braised beef stew with red wine, lardons, mushrooms, and pearl onions.", "servings": 6, "prepTime": 40, "cookTime": 180, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"beef chuck, cut into 2-inch cubes\"}, {\"qty\": \"6 oz\", \"name\": \"lardons or thick-cut bacon, diced\"}, {\"qty\": \"1\", \"name\": \"bottle (750 ml) Burgundy red wine\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"2 cups\", \"name\": \"pearl onions, peeled\"}, {\"qty\": \"1 lb\", \"name\": \"cremini mushrooms, quartered\"}, {\"qty\": \"3\", \"name\": \"large carrots, cut into chunks\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1\", \"name\": \"bouquet garni (thyme, bay leaf, parsley)\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Marinate beef in wine with carrots and bouquet garni for 2 hours. Drain and pat beef dry, reserving marinade. 2. Cook lardons in a Dutch oven until crispy; remove. Brown beef in batches in lardon fat. Remove and set aside. Add garlic and tomato paste; cook 1 minute. 3. Sprinkle flour over vegetables in pot; stir. Add reserved marinade, broth, beef, and lardons. Bring to a boil, cover, and braise in 325°F oven for 2.5 hours. 4. In the last 30 minutes, sauté pearl onions and mushrooms in butter until browned; add to stew. Remove bouquet garni, season, and serve with crusty bread or mashed potatoes.", "tags": "French, weekend cooking, elegant", "source": "Classic", "nutritionData": "{\"calories\": 700, \"protein\": 46.0, \"carbs\": 16.0, \"fat\": 39.0}"},
  {"name": "Spiced Pumpkin Soup", "category": "Soups & Stews", "description": "Silky pumpkin soup with coconut milk, ginger, and warming spices for a cozy autumn meal.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"(15 oz each) pure pumpkin puree\"}, {\"qty\": \"1 can\", \"name\": \"(13.5 oz) full-fat coconut milk\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion, diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic, minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger, grated\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lime\"}, {\"qty\": \"\", \"name\": \"salt and white pepper to taste\"}, {\"qty\": \"\", \"name\": \"toasted pepitas for garnish\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat. Add onion and cook 6 minutes until softened. Add garlic and ginger; cook 1 minute. Add cinnamon, nutmeg, and cloves; stir 30 seconds. 2. Stir in pumpkin puree, coconut milk, and broth. Bring to a simmer over medium heat, stirring well. 3. Simmer for 15 minutes, stirring occasionally. Blend until completely smooth if desired. 4. Stir in maple syrup and lime juice. Season with salt and white pepper. Serve garnished with toasted pepitas and a swirl of coconut milk.", "tags": "vegan, fall, creamy", "source": "Classic", "nutritionData": "{\"calories\": 411, \"protein\": 6.0, \"carbs\": 31.0, \"fat\": 31.0}"},
  {"name": "BBQ Pulled Pork", "category": "Slow Cooker", "description": "Tender spice-rubbed pork shoulder slow cooked and tossed in tangy homemade BBQ sauce.", "servings": 8, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"pork shoulder (bone-in)\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 cup\", \"name\": \"apple cider\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"ketchup\"}, {\"qty\": \"1/4 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"Worcestershire sauce\"}]", "instructions": "1. Mix brown sugar, paprika, salt, garlic powder, onion powder, cumin, pepper, and cayenne into a rub. 2. Pat pork shoulder dry and coat all over with the spice rub. 3. Place pork in slow cooker and pour apple cider around it. 4. Cover and cook on LOW for 8-10 hours or HIGH for 5-6 hours until fall-apart tender. 5. Remove pork and shred with two forks, discarding excess fat. 6. Whisk ketchup, vinegar, and Worcestershire into drippings in the slow cooker. 7. Return shredded pork to sauce, stir well, and cook on HIGH for 20 minutes. 8. Serve on buns with coleslaw.", "tags": "slow-cooker, crowd-pleaser, make-ahead, pork", "source": "https://www.recipetineats.com/pulled-pork-with-bbq-sauce/", "nutritionData": "{\"calories\": 370, \"protein\": 34.0, \"carbs\": 12.0, \"fat\": 17.0}"},
  {"name": "White Chicken Chili", "category": "Slow Cooker", "description": "Creamy slow cooker chili with shredded chicken, white beans, salsa verde, and cream cheese.", "servings": 6, "prepTime": 10, "cookTime": 420, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"15 oz\", \"name\": \"canned white navy beans (drained and rinsed)\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1 cup\", \"name\": \"salsa verde\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"4 oz\", \"name\": \"whipped cream cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"shredded Monterey Jack cheese\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro (chopped)\"}, {\"qty\": \"1\", \"name\": \"lime (juiced)\"}]", "instructions": "1. Add chicken breasts, white beans, chicken broth, salsa verde, cumin, oregano, and salt to slow cooker; stir to combine. 2. Cover and cook on LOW for 6-8 hours or HIGH for 3-4 hours until chicken is cooked through. 3. Remove chicken and shred with two forks; return to slow cooker. 4. In a small bowl, temper cream cheese by stirring in a few spoonfuls of hot broth until smooth. 5. Add cream cheese mixture back to slow cooker and whisk until fully incorporated. 6. Stir in lime juice and adjust seasoning. 7. Serve topped with Monterey Jack cheese and fresh cilantro.", "tags": "slow-cooker, creamy, chicken, comfort-food", "source": "https://slowcookergourmet.net/slow-cooker-white-chicken-chili/", "nutritionData": "{\"calories\": 335, \"protein\": 36.0, \"carbs\": 18.0, \"fat\": 13.0}"},
  {"name": "Classic Beef Chili", "category": "Slow Cooker", "description": "Hearty slow cooker chili packed with ground beef, kidney beans, and bold smoky spices.", "servings": 8, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"lean ground beef (85/15)\"}, {\"qty\": \"1\", \"name\": \"medium sweet onion (diced)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1\", \"name\": \"poblano chili (minced)\"}, {\"qty\": \"16 oz\", \"name\": \"canned red kidney beans (drained and rinsed)\"}, {\"qty\": \"16 oz\", \"name\": \"canned black beans (drained and rinsed)\"}, {\"qty\": \"15 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"14.5 oz\", \"name\": \"canned diced tomatoes\"}, {\"qty\": \"2.5 cups\", \"name\": \"beef broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1.5 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"hot sauce\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Brown ground beef in a skillet over medium-high heat, crumbling as it cooks; drain excess fat. 2. Add garlic, onion, and poblano to the skillet and cook 1 minute until fragrant; transfer to slow cooker. 3. Stir in beef broth, kidney beans, black beans, crushed tomatoes, diced tomatoes, chili powder, paprika, oregano, cumin, and hot sauce. 4. Season with salt and pepper. 5. Cover and cook on LOW for 7-8 hours or HIGH for 5-6 hours. 6. Stir before serving; garnish with sour cream and green onions.", "tags": "slow-cooker, hearty, beef, game-day", "source": "https://damndelicious.net/2019/04/03/easy-slow-cooker-chili/", "nutritionData": "{\"calories\": 365, \"protein\": 32.0, \"carbs\": 29.0, \"fat\": 15.0}"},
  {"name": "Mississippi Pot Roast", "category": "Slow Cooker", "description": "Buttery chuck roast slow cooked with ranch seasoning and pepperoncini for tangy, tender perfection.", "servings": 6, "prepTime": 10, "cookTime": 540, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"chuck roast\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"dry ranch seasoning mix\"}, {\"qty\": \"8\", \"name\": \"pepperoncini peppers\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Place chuck roast in the slow cooker and pour in beef broth. 2. Mix cornstarch with 2 tbsp water until smooth; stir into broth. 3. Sprinkle ranch seasoning over the top of the roast. 4. Arrange pepperoncini peppers around the roast and lay butter slices on top. 5. Cover and cook on HIGH for 4-5 hours or LOW for 8-10 hours until internal temp reaches 205°F. 6. Shred beef with two forks or slice and return to juices. 7. Serve over mashed potatoes, rice, or egg noodles with cooking liquid as gravy.", "tags": "slow-cooker, beef, comfort-food, easy", "source": "https://slowcookergourmet.net/slow-cooker-mississippi-pot-roast/", "nutritionData": "{\"calories\": 495, \"protein\": 34.0, \"carbs\": 2.0, \"fat\": 38.0}"},
  {"name": "Slow Cooker Carnitas", "category": "Slow Cooker", "description": "Juicy Mexican pulled pork with orange and lime, broiled crispy for perfect taco filling.", "servings": 8, "prepTime": 20, "cookTime": 600, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3.5 lbs\", \"name\": \"pork shoulder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium white onion (diced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"4 oz\", \"name\": \"canned diced green chilies\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro (roughly chopped)\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh orange juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"\", \"name\": \"corn tortillas (for serving)\"}]", "instructions": "1. Pat pork dry and rub all over with salt, pepper, cumin, chili powder, and oregano; drizzle with olive oil. 2. Place seasoned pork in the slow cooker. 3. Add onion, garlic, green chilies, cilantro, orange juice, and lime juice around and over the pork. 4. Cover and cook on LOW for 10 hours or HIGH for 7 hours until the pork shreds easily. 5. Remove pork to a baking sheet and shred with two forks, reserving cooking liquid. 6. Drizzle a few spoonfuls of cooking liquid over the shredded pork. 7. Broil on high for 3 minutes, toss, and broil 3 more minutes until edges are crispy. 8. Serve in warm corn tortillas with desired toppings.", "tags": "slow-cooker, Mexican, pork, tacos", "source": "https://www.themagicalslowcooker.com/carnitas/", "nutritionData": "{\"calories\": 350, \"protein\": 31.0, \"carbs\": 3.0, \"fat\": 18.0}"},
  {"name": "Barbacoa Beef", "category": "Slow Cooker", "description": "Chipotle-inspired slow cooker beef barbacoa with smoky adobo spices, perfect for tacos and bowls.", "servings": 8, "prepTime": 15, "cookTime": 540, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"boneless chuck roast (cut into large pieces)\"}, {\"qty\": \"\", \"name\": \"2-3 chipotle peppers in adobo sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"beef broth\"}, {\"qty\": \"4 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tsp\", \"name\": \"Mexican oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1/2\", \"name\": \"medium onion (sliced)\"}]", "instructions": "1. In a blender, combine chipotle peppers, apple cider vinegar, garlic, lime juice, beef broth, cumin, oregano, cloves, tomato paste, salt, and pepper; blend until smooth. 2. Place beef pieces and sliced onion in slow cooker; add bay leaves on top. 3. Pour blended sauce over the beef and toss to coat. 4. Cover and cook on LOW for 8-10 hours or HIGH for 4-6 hours until beef is fall-apart tender. 5. Discard bay leaves; shred beef in the slow cooker with two forks. 6. Toss shredded beef in the juices and let sit 10 minutes to absorb flavors. 7. Serve in tacos, burritos, or bowls with rice and beans.", "tags": "slow-cooker, Mexican, beef, spicy", "source": "https://www.themagicalslowcooker.com/copycat-chipotle-barbacoa/", "nutritionData": "{\"calories\": 325, \"protein\": 26.0, \"carbs\": 2.0, \"fat\": 23.0}"},
  {"name": "Slow Cooker Butter Chicken", "category": "Slow Cooker", "description": "Rich Indian butter chicken with aromatic spices, heavy cream, and tender chunks of chicken thighs.", "servings": 6, "prepTime": 15, "cookTime": 240, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs (cut into chunks)\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion (diced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tsp\", \"name\": \"curry powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro (for garnish)\"}, {\"qty\": \"\", \"name\": \"cooked basmati rice (for serving)\"}]", "instructions": "1. In a small bowl, whisk together chicken stock, tomato paste, curry powder, garam masala, turmeric, salt, and pepper. 2. Place chicken thighs, onion, garlic, and ginger into a 4-quart slow cooker; pour stock mixture over top and stir. 3. Cover and cook on LOW for 4 hours or HIGH for 2 hours until chicken is tender. 4. Stir in heavy cream, lime juice, and brown sugar; season with additional salt and pepper if needed. 5. Serve immediately over basmati rice garnished with fresh cilantro.", "tags": "slow-cooker, Indian, chicken, creamy", "source": "https://damndelicious.net/2019/05/03/slow-cooker-indian-butter-chicken/", "nutritionData": "{\"calories\": 320, \"protein\": 30.0, \"carbs\": 3.0, \"fat\": 20.0}"},
  {"name": "Slow Cooker Ropa Vieja", "category": "Slow Cooker", "description": "Cuban shredded flank steak slow cooked in a savory tomato sauce with peppers, olives, and warming spices.", "servings": 6, "prepTime": 20, "cookTime": 540, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"beef flank steak\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"6 oz\", \"name\": \"canned tomato paste\"}, {\"qty\": \"14 oz\", \"name\": \"canned petite diced tomatoes\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1\", \"name\": \"small white onion (diced)\"}, {\"qty\": \"2\", \"name\": \"bell peppers (orange and green, diced)\"}, {\"qty\": \"1 cup\", \"name\": \"Spanish olives\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (peeled)\"}, {\"qty\": \"1.5 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"cooked yellow rice (for serving)\"}]", "instructions": "1. Add beef broth, tomato paste, diced tomatoes, oregano, cumin, turmeric, vinegar, salt, and pepper to the slow cooker and stir to combine. 2. Add flank steak and flip to coat in the sauce. 3. Top with diced onion, bell peppers, olives, and garlic cloves; mix the vegetables together on top of the meat. 4. Cover and cook on LOW for 9 hours or HIGH for 5 hours without lifting the lid. 5. Shred the beef directly in the slow cooker using two forks and stir to combine with the sauce. 6. Serve over yellow rice with fresh cilantro if desired.", "tags": "slow-cooker, Cuban, beef, shredded", "source": "https://www.themagicalslowcooker.com/slow-cooker-ropa-vieja/", "nutritionData": "{\"calories\": 440, \"protein\": 35.0, \"carbs\": 6.0, \"fat\": 30.0}"},
  {"name": "Slow Cooker Beef Stew", "category": "Slow Cooker", "description": "Classic hearty beef stew with tender chuck, potatoes, carrots, and rich savory broth.", "servings": 6, "prepTime": 25, "cookTime": 480, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"beef stew meat (chuck, cut into 1-inch cubes)\"}, {\"qty\": \"3\", \"name\": \"medium potatoes (peeled and diced)\"}, {\"qty\": \"3\", \"name\": \"large carrots (sliced)\"}, {\"qty\": \"1\", \"name\": \"medium onion (diced)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"cooking oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 cup\", \"name\": \"frozen peas\"}]", "instructions": "1. Add potatoes, carrots, and onion to the slow cooker. 2. Combine flour, salt, pepper, onion powder, and thyme in a zip-lock bag; add beef cubes and shake to coat. 3. Heat oil in a skillet over medium-high and brown beef on all sides in batches; transfer to slow cooker. 4. Deglaze the skillet with beef broth, scraping up brown bits; whisk in tomato paste until smooth. 5. Pour broth mixture over the beef and vegetables in the slow cooker; stir. 6. Cover and cook on LOW for 7-8 hours until beef and vegetables are tender. 7. Add frozen peas during the last 15 minutes and stir. 8. Season to taste and serve with crusty bread.", "tags": "slow-cooker, comfort-food, beef, classic", "source": "https://www.themagicalslowcooker.com/slow-cooker-beef-stew/", "nutritionData": "{\"calories\": 390, \"protein\": 26.0, \"carbs\": 23.0, \"fat\": 21.0}"},
  {"name": "French Dip Sandwiches", "category": "Slow Cooker", "description": "Slow-cooked chuck roast piled onto toasted hoagie rolls with provolone and savory au jus for dipping.", "servings": 6, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"beef chuck roast\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"reduced-sodium soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"medium onion (sliced)\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"6\", \"name\": \"hoagie rolls\"}, {\"qty\": \"6 slices\", \"name\": \"provolone cheese\"}]", "instructions": "1. Place butter and onion in the slow cooker and nestle chuck roast on top. 2. Pour in beef broth, soy sauce, and Worcestershire sauce; add garlic and pepper. 3. Cover and cook on LOW for 8 hours or HIGH for 4-5 hours until meat is fork-tender. 4. Remove roast and shred or thinly slice; return meat to slow cooker for 30 minutes. 5. Slice hoagie rolls and toast cut-side up in the oven under broiler. 6. Layer shredded beef and provolone on rolls; broil 2 minutes until cheese melts. 7. Strain cooking liquid into small bowls as au jus for dipping and serve.", "tags": "slow-cooker, sandwiches, beef, game-day", "source": "Classic", "nutritionData": "{\"calories\": 630, \"protein\": 44.0, \"carbs\": 23.0, \"fat\": 38.0}"},
  {"name": "Slow Cooker Chicken Tikka Masala", "category": "Slow Cooker", "description": "Aromatic Indian chicken tikka masala slow cooked in a spiced tomato-yogurt sauce, served over basmati rice.", "servings": 4, "prepTime": 15, "cookTime": 300, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts (cut into bite-size pieces)\"}, {\"qty\": \"1\", \"name\": \"small onion (minced)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (crushed)\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"1.5 cups\", \"name\": \"crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"1% milk\"}, {\"qty\": \"3/4 cup\", \"name\": \"plain whole-milk yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tbsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"fresh cilantro (chopped)\"}, {\"qty\": \"\", \"name\": \"cooked basmati rice (for serving)\"}]", "instructions": "1. Heat olive oil in a large skillet over medium heat; cook onion until golden, about 3 minutes. 2. Add ginger and garlic; cook 1 minute. Add cumin, garam masala, turmeric, chili powder, and salt; cook 2 minutes until fragrant. 3. Stir in crushed tomatoes and milk; transfer mixture to slow cooker. 4. Add chicken pieces and stir to coat in the sauce. 5. Cover and cook on LOW for 4-5 hours or HIGH for 2-3 hours until chicken is cooked through. 6. Temper the yogurt by mixing 1/2 cup of the hot sauce into the yogurt in a bowl, then stir yogurt mixture back into the slow cooker. 7. Serve over basmati rice topped with fresh cilantro.", "tags": "slow-cooker, Indian, chicken, spiced", "source": "https://www.skinnytaste.com/skinny-chicken-tikka-masala/", "nutritionData": "{\"calories\": 295, \"protein\": 45.0, \"carbs\": 7.0, \"fat\": 8.0}"},
  {"name": "Slow Cooker Sesame Chicken", "category": "Slow Cooker", "description": "Sweet and savory crockpot sesame chicken with soy, honey, and ginger sauce served over fluffy rice.", "servings": 4, "prepTime": 10, "cookTime": 240, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1/2 cup\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"5 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"3 tbsp\", \"name\": \"rice wine vinegar\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1.5 tsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1.5 tsp\", \"name\": \"sriracha\"}, {\"qty\": \"2.5 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"5 tbsp\", \"name\": \"water (divided)\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"4\", \"name\": \"scallions (chopped)\"}, {\"qty\": \"\", \"name\": \"cooked rice (for serving)\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}]", "instructions": "1. Place chicken thighs in slow cooker and season with black pepper. 2. Whisk together soy sauce, honey, tomato paste, rice wine vinegar, garlic, ginger, sesame oil, sriracha, and 1 tbsp water in a bowl; pour over chicken. 3. Cover and cook on LOW for 3-4 hours until chicken is cooked through. 4. Remove chicken and shred with two forks; leave sauce in slow cooker. 5. Dissolve cornstarch in remaining 1/4 cup water; stir into the slow cooker sauce. 6. Cover and cook on HIGH for 15-20 minutes until sauce thickens. 7. Return shredded chicken to slow cooker and toss to coat. 8. Serve over rice topped with sesame seeds and chopped scallions.", "tags": "slow-cooker, Asian, chicken, sweet-savory", "source": "https://www.skinnytaste.com/crock-pot-sesame-honey-chicken/", "nutritionData": "{\"calories\": 475, \"protein\": 47.0, \"carbs\": 23.0, \"fat\": 19.0}"},
  {"name": "Thai Peanut Chicken", "category": "Slow Cooker", "description": "Slow-cooked shredded chicken in a creamy Thai peanut coconut sauce with garlic and ginger.", "servings": 4, "prepTime": 15, "cookTime": 300, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 tbsp\", \"name\": \"curry powder\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic (chopped)\"}, {\"qty\": \"1\", \"name\": \"small yellow onion (diced)\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"3 tbsp\", \"name\": \"natural peanut butter\"}, {\"qty\": \"3 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"2 tsp\", \"name\": \"sriracha\"}, {\"qty\": \"1 cup\", \"name\": \"canned coconut milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped roasted peanuts\"}, {\"qty\": \"\", \"name\": \"fresh cilantro and lime wedges for serving\"}, {\"qty\": \"\", \"name\": \"cooked jasmine rice for serving\"}]", "instructions": "1. In a skillet over medium-low heat, cook garlic, onion, and ginger in 1 tsp sesame oil until soft, about 3-4 minutes. 2. Add curry powder and cook 1-2 more minutes; transfer to slow cooker. 3. Add peanut butter, soy sauce, remaining sesame oil, rice vinegar, sriracha, and coconut milk to the slow cooker; whisk to combine. 4. Add chicken and coat well with the sauce. 5. Cover and cook on HIGH for 2-3 hours or LOW for 4-6 hours until chicken is cooked through and tender. 6. Remove chicken, shred with two forks, and return to slow cooker; cook on LOW 15 more minutes. 7. Serve over jasmine rice topped with chopped peanuts, cilantro, and lime wedges.", "tags": "slow-cooker, Thai, peanut, chicken", "source": "https://www.skinnytaste.com/slow-cooker-peanut-chicken/", "nutritionData": "{\"calories\": 420, \"protein\": 44.0, \"carbs\": 5.0, \"fat\": 25.0}"},
  {"name": "Slow Cooker Beef Bourguignon", "category": "Slow Cooker", "description": "French-inspired braised beef with red wine, bacon, mushrooms, and root vegetables in a silky sauce.", "servings": 4, "prepTime": 30, "cookTime": 480, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless beef chuck (cut into 2-inch cubes)\"}, {\"qty\": \"5 slices\", \"name\": \"thick-cut bacon (diced)\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms (sliced)\"}, {\"qty\": \"3\", \"name\": \"large carrots (sliced)\"}, {\"qty\": \"1 lb\", \"name\": \"baby potatoes (halved)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2\", \"name\": \"pearl onions or 1/2 cup diced onion\"}, {\"qty\": \"2 tbsp\", \"name\": \"flour\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley (for garnish)\"}]", "instructions": "1. Cook diced bacon in a large skillet over medium-high until crispy; remove to slow cooker. 2. Season beef cubes with salt and pepper; sear in bacon drippings for 3-4 minutes per side until browned; transfer to slow cooker. 3. Add carrots, potatoes, onions, and garlic to the slow cooker. 4. Whisk together red wine, beef broth, tomato paste, and flour; pour over the slow cooker contents. 5. Add thyme and bay leaf. 6. Cover and cook on LOW for 8-10 hours or HIGH for 6 hours until beef is tender. 7. Stir in mushrooms during the last 30 minutes of cooking. 8. Discard bay leaf; season to taste and garnish with fresh parsley.", "tags": "slow-cooker, French, beef, wine-braised", "source": "https://slowcookergourmet.net/slow-cooker-beef-bourguignon-for-two/", "nutritionData": "{\"calories\": 785, \"protein\": 51.0, \"carbs\": 26.0, \"fat\": 45.0}"},
  {"name": "Slow Cooker Lamb Shanks", "category": "Slow Cooker", "description": "Fall-off-the-bone lamb shanks braised in red wine with aromatics and root vegetables.", "servings": 4, "prepTime": 20, "cookTime": 480, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"lamb shanks (about 3 lbs total)\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium onion (diced)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"2\", \"name\": \"carrots (diced)\"}, {\"qty\": \"2\", \"name\": \"stalks celery (diced)\"}, {\"qty\": \"1 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"14 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"mashed potato or polenta (for serving)\"}]", "instructions": "1. Season lamb shanks generously with salt and pepper. 2. Heat olive oil in a large skillet over high heat; sear shanks in 2 batches until browned all over, about 5 minutes each; transfer to slow cooker. 3. Reduce heat to medium-low in same skillet; sauté onion, garlic, carrot, and celery for 5 minutes until softened. 4. Add red wine to skillet; bring to simmer and scrape up browned bits. 5. Stir in chicken stock, crushed tomatoes, and tomato paste; bring to simmer then pour into slow cooker. 6. Add thyme sprigs and bay leaves. 7. Cover and cook on LOW for 8 hours until lamb is fall-apart tender. 8. Remove shanks; strain and reduce sauce on stovetop if desired. Serve over mashed potatoes.", "tags": "slow-cooker, lamb, wine-braised, dinner-party", "source": "https://www.recipetineats.com/slow-cooked-lamb-shanks-in-red-wine-sauce/", "nutritionData": "{\"calories\": 550, \"protein\": 49.0, \"carbs\": 6.0, \"fat\": 30.0}"},
  {"name": "Slow Cooker BBQ Brisket", "category": "Slow Cooker", "description": "Juicy spice-rubbed beef brisket slow cooked in BBQ sauce, broiled for a caramelized crust.", "servings": 8, "prepTime": 15, "cookTime": 540, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"beef brisket (flat cut)\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}]", "instructions": "1. Mix brown sugar, paprika, garlic powder, onion powder, salt, pepper, and cayenne into a spice rub; coat brisket all over. 2. In the slow cooker, whisk together beef broth, 1/2 cup BBQ sauce, Worcestershire sauce, and soy sauce. 3. Place rubbed brisket into the slow cooker, squeezing in if needed. 4. Cover and cook on LOW for 8-10 hours until very tender. 5. Remove brisket to a foil-lined baking sheet; pour cooking liquid into a saucepan and simmer to thicken. 6. Brush brisket with remaining 1/2 cup BBQ sauce; broil 3-5 minutes until caramelized. 7. Rest 5 minutes then slice against the grain; return to slow cooker with thickened sauce.", "tags": "slow-cooker, BBQ, brisket, beef", "source": "https://www.recipetineats.com/slow-cooker-beef-brisket-with-bbq-sauce/", "nutritionData": "{\"calories\": 365, \"protein\": 26.0, \"carbs\": 14.0, \"fat\": 22.0}"},
  {"name": "Slow Cooker Chicken Cacciatore", "category": "Slow Cooker", "description": "Italian hunter-style chicken with bell peppers, mushrooms, and crushed tomatoes, served over pasta.", "servings": 4, "prepTime": 15, "cookTime": 420, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion (diced)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1\", \"name\": \"medium green bell pepper (diced)\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms (sliced)\"}, {\"qty\": \"28 oz\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley (chopped)\"}, {\"qty\": \"\", \"name\": \"cooked pasta (for serving)\"}]", "instructions": "1. Season chicken thighs with salt and pepper; place in slow cooker. 2. Add onion, garlic, bell pepper, and mushrooms around the chicken. 3. Pour crushed tomatoes and chicken broth over everything; sprinkle with Italian seasoning, oregano, and red pepper flakes. 4. Cover and cook on LOW for 6-8 hours or HIGH for 3-4 hours until chicken is cooked through. 5. Remove chicken and roughly chop or shred; return to slow cooker. 6. Stir in balsamic vinegar; season to taste. 7. Serve over cooked pasta topped with fresh parsley and grated Parmesan.", "tags": "slow-cooker, Italian, chicken, tomato-sauce", "source": "Classic", "nutritionData": "{\"calories\": 410, \"protein\": 47.0, \"carbs\": 11.0, \"fat\": 19.0}"},
  {"name": "Slow Cooker Asian Short Ribs", "category": "Slow Cooker", "description": "Tender beef short ribs braised in a sweet soy-ginger glaze, garnished with sesame seeds and parsley.", "servings": 4, "prepTime": 10, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"beef short ribs\"}, {\"qty\": \"1/2 cup\", \"name\": \"reduced-sodium soy sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"beef broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar (packed)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley (chopped)\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame seeds\"}]", "instructions": "1. In a large bowl, whisk together soy sauce, beef broth, brown sugar, garlic, ginger, sesame oil, and red pepper flakes. 2. Place short ribs into a 6-quart slow cooker and pour sauce over ribs. 3. Cover and cook on LOW for 7-8 hours or HIGH for 3-4 hours until ribs are fall-off-the-bone tender. 4. Remove ribs carefully; whisk cornstarch with 1/4 cup water and stir into the slow cooker. 5. Cover and cook on HIGH for 30 more minutes until sauce thickens. 6. Serve ribs over rice drizzled with thickened sauce, garnished with parsley and sesame seeds.", "tags": "slow-cooker, Asian, beef, short-ribs", "source": "https://damndelicious.net/2016/03/23/slow-cooker-asian-short-ribs/", "nutritionData": "{\"calories\": 750, \"protein\": 30.0, \"carbs\": 5.0, \"fat\": 63.0}"},
  {"name": "Slow Cooker Kalua Pig", "category": "Slow Cooker", "description": "Hawaiian-style smoky shredded pork made with just three ingredients for an authentic luau flavor.", "servings": 10, "prepTime": 10, "cookTime": 600, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"5 lbs\", \"name\": \"pork shoulder (bone-in)\"}, {\"qty\": \"2 tbsp\", \"name\": \"Hawaiian sea salt (or kosher salt)\"}, {\"qty\": \"1 tbsp\", \"name\": \"liquid smoke\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (peeled)\"}, {\"qty\": \"2\", \"name\": \"large banana leaves (optional for lining slow cooker)\"}]", "instructions": "1. Pierce pork shoulder all over with a fork or paring knife. 2. Rub Hawaiian sea salt all over the pork, then drizzle liquid smoke on top and rub in. 3. If using banana leaves, line slow cooker with them; otherwise spray with nonstick spray. 4. Place seasoned pork in slow cooker and scatter garlic cloves around it. 5. Cover and cook on LOW for 10-12 hours without lifting the lid during cooking. 6. When pork is tender, transfer to a plate and shred with two forks, discarding excess fat and bone. 7. Return shredded pork to slow cooker and stir into the accumulated juices. 8. Serve with steamed white rice and Hawaiian macaroni salad.", "tags": "slow-cooker, Hawaiian, pork, simple", "source": "Classic", "nutritionData": "{\"calories\": 355, \"protein\": 36.0, \"carbs\": 0.0, \"fat\": 19.0}"},
  {"name": "Slow Cooker Pulled Chicken", "category": "Slow Cooker", "description": "Easy BBQ pulled chicken with tender shredded chicken breasts smothered in smoky barbecue sauce.", "servings": 6, "prepTime": 10, "cookTime": 360, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"hamburger buns (for serving)\"}, {\"qty\": \"\", \"name\": \"coleslaw (for serving)\"}]", "instructions": "1. Whisk together BBQ sauce, chicken broth, brown sugar, apple cider vinegar, garlic powder, onion powder, smoked paprika, and salt in the slow cooker. 2. Place chicken breasts in the slow cooker and spoon sauce over to coat. 3. Cover and cook on LOW for 6 hours or HIGH for 3-4 hours until chicken is cooked through. 4. Remove chicken and shred with two forks; return to the slow cooker. 5. Stir shredded chicken into the sauce and cook on HIGH for 15 minutes. 6. Pile pulled chicken onto buns and top with creamy coleslaw.", "tags": "slow-cooker, chicken, BBQ, sandwiches", "source": "Classic", "nutritionData": "{\"calories\": 285, \"protein\": 35.0, \"carbs\": 19.0, \"fat\": 4.0}"},
  {"name": "Slow Cooker Honey Garlic Chicken", "category": "Slow Cooker", "description": "Sticky honey garlic glazed chicken thighs slow cooked until tender and served over rice.", "servings": 4, "prepTime": 10, "cookTime": 300, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1/3 cup\", \"name\": \"honey\"}, {\"qty\": \"1/3 cup\", \"name\": \"soy sauce (low sodium)\"}, {\"qty\": \"2 tbsp\", \"name\": \"ketchup\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger (grated)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"2 tbsp\", \"name\": \"onion (minced)\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"3 tbsp\", \"name\": \"cold water\"}, {\"qty\": \"4 cups\", \"name\": \"cooked rice\"}, {\"qty\": \"\", \"name\": \"sesame seeds and scallions for garnish\"}]", "instructions": "1. In the slow cooker, whisk together honey, soy sauce, ketchup, ginger, garlic, minced onion, and red pepper flakes. 2. Remove 1/2 cup of the sauce and reserve in the fridge. 3. Season chicken with salt and pepper; add to slow cooker and toss to coat in sauce. 4. Cover and cook on LOW for 5-6 hours or HIGH for 2.5-3 hours until internal temp reaches 165°F. 5. Remove chicken and tent with foil; whisk cornstarch with cold water and stir into slow cooker on HIGH for 15 minutes until thickened. 6. Add reserved sauce and return chicken; toss to coat. 7. Serve over rice garnished with sesame seeds and sliced scallions.", "tags": "slow-cooker, chicken, honey-garlic, Asian-inspired", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 46.0, \"carbs\": 25.0, \"fat\": 19.0}"},
  {"name": "Slow Cooker Salsa Chicken", "category": "Slow Cooker", "description": "Ultra-easy two-ingredient crockpot salsa chicken perfect for tacos, burritos, or rice bowls.", "servings": 4, "prepTime": 5, "cookTime": 240, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"2 cups\", \"name\": \"salsa\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1.25 oz\", \"name\": \"packet taco seasoning\"}, {\"qty\": \"\", \"name\": \"shredded cheese, sour cream, and cilantro for serving\"}, {\"qty\": \"\", \"name\": \"corn tortillas or cooked rice for serving\"}]", "instructions": "1. Place chicken breasts in the bottom of a 4-6 quart slow cooker. 2. Sprinkle taco seasoning, garlic powder, cumin, salt, and pepper over the chicken. 3. Pour salsa over the top and stir to coat the chicken. 4. Cover and cook on HIGH for 3-4 hours or LOW for 6-7 hours until chicken is cooked through. 5. Remove chicken to a bowl and shred with two forks; return to slow cooker and stir into the salsa. 6. Serve in tortillas or over rice topped with shredded cheese, sour cream, and cilantro.", "tags": "slow-cooker, chicken, Mexican, easy", "source": "https://crockpotladies.com/crockpot-easy-salsa-chicken/", "nutritionData": "{\"calories\": 235, \"protein\": 40.0, \"carbs\": 6.0, \"fat\": 5.0}"},
  {"name": "Slow Cooker Balsamic Chicken", "category": "Slow Cooker", "description": "Tangy balsamic glazed chicken thighs with garlic, herbs, and tomatoes, cooked low and slow.", "servings": 4, "prepTime": 10, "cookTime": 300, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1/3 cup\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"14 oz\", \"name\": \"canned diced tomatoes (drained)\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil (chopped)\"}]", "instructions": "1. Whisk together balsamic vinegar, honey, garlic, olive oil, rosemary, thyme, oregano, salt, and pepper in a bowl. 2. Place chicken thighs in slow cooker and pour balsamic mixture over them; toss to coat. 3. Add drained diced tomatoes around the chicken. 4. Cover and cook on LOW for 5-6 hours or HIGH for 2.5-3 hours until chicken reaches 165°F. 5. Remove chicken; transfer cooking liquid to a small saucepan and simmer 5-10 minutes to reduce into a glaze. 6. Drizzle glaze over chicken and garnish with fresh basil. 7. Serve over mashed potatoes, polenta, or roasted vegetables.", "tags": "slow-cooker, chicken, balsamic, Italian-inspired", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 45.0, \"carbs\": 20.0, \"fat\": 20.0}"},
  {"name": "Classic Slow Cooker Pot Roast", "category": "Slow Cooker", "description": "Traditional Sunday pot roast with fork-tender chuck, carrots, potatoes, and rich savory gravy.", "servings": 8, "prepTime": 20, "cookTime": 540, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"boneless chuck roast\"}, {\"qty\": \"1 lb\", \"name\": \"baby potatoes (halved)\"}, {\"qty\": \"3\", \"name\": \"large carrots (cut into chunks)\"}, {\"qty\": \"1\", \"name\": \"medium onion (sliced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (smashed)\"}, {\"qty\": \"1.5 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch + 2 tbsp water for gravy\"}]", "instructions": "1. Season chuck roast generously on all sides with salt, pepper, garlic powder, and onion powder. 2. Place onion, potatoes, and carrots in the bottom of the slow cooker; add garlic. 3. Set seasoned roast on top of vegetables. 4. Whisk together beef broth, Worcestershire sauce, tomato paste, thyme, and rosemary; pour over the roast. 5. Cover and cook on LOW for 8-10 hours or HIGH for 4-5 hours until roast is fork-tender. 6. Remove roast and vegetables to a serving platter; tent with foil. 7. Whisk cornstarch with water; stir into slow cooker liquid and cook on HIGH 15 minutes until thickened into gravy. 8. Slice or shred roast and serve with vegetables and gravy.", "tags": "slow-cooker, pot-roast, beef, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 370, \"protein\": 27.0, \"carbs\": 12.0, \"fat\": 23.0}"},
  {"name": "Slow Cooker Lentil Soup", "category": "Slow Cooker", "description": "Hearty and nourishing slow cooker lentil soup with spinach, cumin, and a drizzle of olive oil.", "servings": 6, "prepTime": 15, "cookTime": 420, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"green or brown lentils (rinsed)\"}, {\"qty\": \"2\", \"name\": \"large carrots (diced)\"}, {\"qty\": \"2\", \"name\": \"stalks celery (diced)\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion (diced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"14 oz\", \"name\": \"canned diced tomatoes\"}, {\"qty\": \"5 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}]", "instructions": "1. Add lentils, carrots, celery, onion, garlic, diced tomatoes, vegetable broth, cumin, paprika, oregano, cayenne, and salt to the slow cooker; stir to combine. 2. Cover and cook on LOW for 6-8 hours or HIGH for 3-4 hours until lentils are completely tender. 3. About 15 minutes before serving, stir in baby spinach and olive oil; recover and cook until spinach wilts. 4. Stir in fresh lemon juice and adjust seasoning. 5. Optional: Remove 2 cups of soup and blend until smooth, then stir back in for a creamier texture. 6. Serve garnished with fresh herbs and crusty bread.", "tags": "slow-cooker, vegan, lentils, healthy", "source": "https://slowcookergourmet.net/slow-cooker-lentil-soup/", "nutritionData": "{\"calories\": 235, \"protein\": 14.0, \"carbs\": 33.0, \"fat\": 3.0}"},
  {"name": "Slow Cooker Split Pea Soup", "category": "Slow Cooker", "description": "Thick and comforting slow cooker split pea soup with diced ham and tender carrots.", "servings": 8, "prepTime": 15, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"dried split peas (rinsed)\"}, {\"qty\": \"64 oz\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 lb\", \"name\": \"carrots (diced)\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion (diced)\"}, {\"qty\": \"1 lb\", \"name\": \"diced ham\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}]", "instructions": "1. Add split peas, chicken broth, carrots, onion, garlic, ham, thyme, and olive oil to a 5-quart or larger slow cooker. 2. Season with salt and pepper; stir to combine. 3. Cover and cook on LOW for 6-8 hours until peas break down and soup becomes very thick. 4. About 5 hours in, use a potato masher to help break down the peas further. 5. Add water to loosen the soup if it becomes too thick for your liking. 6. Taste and adjust seasoning with additional salt and pepper. 7. Ladle into bowls and serve with crusty bread.", "tags": "slow-cooker, soup, ham, comfort-food", "source": "https://crockpotladies.com/crockpot-split-pea-soup/", "nutritionData": "{\"calories\": 505, \"protein\": 37.0, \"carbs\": 78.0, \"fat\": 6.0}"},
  {"name": "Slow Cooker Ham and Bean Soup", "category": "Slow Cooker", "description": "Classic slow cooker ham and bean soup with a ham bone, tomatoes, and savory herbs.", "servings": 8, "prepTime": 15, "cookTime": 600, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"20 oz\", \"name\": \"15-bean soup mix (seasoning packet discarded)\"}, {\"qty\": \"1\", \"name\": \"ham bone (with meat attached)\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion (diced)\"}, {\"qty\": \"1 clove\", \"name\": \"garlic (minced)\"}, {\"qty\": \"29 oz\", \"name\": \"canned diced tomatoes (undrained)\"}, {\"qty\": \"8 oz\", \"name\": \"tomato sauce\"}, {\"qty\": \"2\", \"name\": \"quarts water\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley (chopped)\"}]", "instructions": "1. Sort and rinse beans; place in slow cooker. 2. Add diced onion, garlic, diced tomatoes, tomato sauce, water, salt, pepper, paprika, and bay leaf; stir to combine. 3. Place ham bone in the center of the slow cooker, pressing down into the beans. 4. Cover and cook on LOW for 10-12 hours until beans are completely tender. 5. One hour before serving, carefully remove ham bone with tongs; pull all meat from the bone and chop. 6. Return chopped ham meat to the slow cooker; discard bone and bay leaf. 7. Stir soup well, adjust seasoning, and garnish with fresh parsley before serving.", "tags": "slow-cooker, soup, ham, beans", "source": "https://crockpotladies.com/crockpot-15-bean-ham-soup/", "nutritionData": "{\"calories\": 330, \"protein\": 24.0, \"carbs\": 51.0, \"fat\": 4.0}"},
  {"name": "Slow Cooker Minestrone", "category": "Slow Cooker", "description": "Classic Italian vegetable minestrone with kidney beans, pasta, and Parmesan in the slow cooker.", "servings": 8, "prepTime": 20, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"28 oz\", \"name\": \"canned diced tomatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"15 oz\", \"name\": \"canned kidney beans (drained and rinsed)\"}, {\"qty\": \"15 oz\", \"name\": \"canned cannellini beans (drained and rinsed)\"}, {\"qty\": \"1 cup\", \"name\": \"carrots (diced)\"}, {\"qty\": \"1 cup\", \"name\": \"celery (diced)\"}, {\"qty\": \"1.5 cups\", \"name\": \"yellow onion (diced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1\", \"name\": \"medium zucchini (diced)\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1.5 cups\", \"name\": \"ditalini pasta\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Add vegetable broth, diced tomatoes, tomato paste, kidney beans, cannellini beans, carrots, celery, onion, garlic, oregano, basil, and bay leaves to slow cooker; stir. 2. Season with salt and pepper. 3. Cover and cook on LOW for 6-8 hours or HIGH for 3-4 hours. 4. Add zucchini and ditalini pasta; turn to HIGH and cook 20-25 more minutes until pasta is tender. 5. Stir in baby spinach and cook 5 more minutes until wilted. 6. Discard bay leaves; adjust seasoning. 7. Serve topped with grated Parmesan and garlic toasted bread.", "tags": "slow-cooker, vegetarian, Italian, soup", "source": "https://crockpotladies.com/crockpot-easy-minestrone/", "nutritionData": "{\"calories\": 255, \"protein\": 13.0, \"carbs\": 41.0, \"fat\": 2.0}"},
  {"name": "Slow Cooker Sweet and Sour Chicken", "category": "Slow Cooker", "description": "Tender crockpot chicken in a tangy pineapple sweet and sour sauce with bell peppers.", "servings": 4, "prepTime": 15, "cookTime": 300, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs (cut into chunks)\"}, {\"qty\": \"20 oz\", \"name\": \"canned pineapple chunks (juice reserved)\"}, {\"qty\": \"1/2 cup\", \"name\": \"ketchup\"}, {\"qty\": \"1/3 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"rice wine vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger powder\"}, {\"qty\": \"1\", \"name\": \"red bell pepper (diced)\"}, {\"qty\": \"1\", \"name\": \"green bell pepper (diced)\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"cold water\"}, {\"qty\": \"\", \"name\": \"cooked white rice for serving\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. In the slow cooker, whisk together reserved pineapple juice, ketchup, brown sugar, rice wine vinegar, soy sauce, garlic powder, and ginger. 2. Add chicken chunks and toss to coat; place pineapple chunks on top. 3. Cover and cook on LOW for 4-5 hours or HIGH for 2-3 hours until chicken is cooked through. 4. Add diced bell peppers in the last 30 minutes of cooking. 5. Dissolve cornstarch in cold water; stir into the slow cooker and cook on HIGH for 15 minutes until sauce thickens. 6. Serve over rice garnished with sesame seeds.", "tags": "slow-cooker, Asian, chicken, sweet-sour", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 34.0, \"carbs\": 26.0, \"fat\": 15.0}"},
  {"name": "Slow Cooker Chili Verde", "category": "Slow Cooker", "description": "New Mexico-style green pork chili with tomatillos, roasted green chiles, and cumin-spiced pork.", "servings": 6, "prepTime": 20, "cookTime": 480, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"boneless pork shoulder (cut into 1-inch chunks)\"}, {\"qty\": \"1 lb\", \"name\": \"tomatillos (husked and quartered)\"}, {\"qty\": \"4 oz\", \"name\": \"canned diced green chiles\"}, {\"qty\": \"2\", \"name\": \"poblano peppers (roasted, peeled, and diced)\"}, {\"qty\": \"1\", \"name\": \"medium white onion (diced)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic (minced)\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro (chopped)\"}, {\"qty\": \"2 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"\", \"name\": \"flour tortillas for serving\"}]", "instructions": "1. Season pork chunks with salt, pepper, cumin, and oregano. 2. Brown pork in a skillet over high heat in batches; transfer to slow cooker. 3. Add tomatillos, diced green chiles, roasted poblanos, onion, garlic, and chicken broth to the slow cooker. 4. Stir to combine and nestle pork into the vegetable mixture. 5. Cover and cook on LOW for 8 hours or HIGH for 4-5 hours until pork is very tender. 6. Use a fork to break apart larger pieces of pork if desired. 7. Stir in fresh cilantro and lime juice; adjust seasoning. 8. Serve with warm flour tortillas, rice, or over baked potatoes.", "tags": "slow-cooker, Mexican, pork, spicy", "source": "Classic", "nutritionData": "{\"calories\": 320, \"protein\": 30.0, \"carbs\": 3.0, \"fat\": 16.0}"},
  {"name": "Greek Salad", "category": "Mediterranean", "description": "A classic Horiatiki salad with tomatoes, cucumber, olives, and creamy feta in olive oil.", "servings": 4, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large ripe tomatoes\"}, {\"qty\": \"1\", \"name\": \"English cucumber\"}, {\"qty\": \"1\", \"name\": \"red onion\"}, {\"qty\": \"1 cup\", \"name\": \"kalamata olives\"}, {\"qty\": \"200g\", \"name\": \"feta cheese\"}, {\"qty\": \"1\", \"name\": \"green bell pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Cut tomatoes into wedges and cucumber into thick half-moons. 2. Thinly slice red onion and green pepper. 3. Combine all vegetables and olives in a large bowl. 4. Place feta block on top or crumble over salad. 5. Drizzle with olive oil, sprinkle oregano, season with salt and pepper, and serve.", "tags": "vegetarian, gluten-free, no-cook, fresh", "source": "https://www.themediterraneandish.com/greek-salad-recipe/", "nutritionData": "{\"calories\": 280, \"protein\": 8.0, \"carbs\": 14.0, \"fat\": 22.0}"},
  {"name": "Chicken Souvlaki", "category": "Mediterranean", "description": "Juicy grilled chicken skewers marinated in lemon, garlic, and oregano, served with pita.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4\", \"name\": \"pita breads\"}, {\"qty\": \"1 cup\", \"name\": \"tzatziki sauce\"}]", "instructions": "1. Cut chicken into 1.5-inch cubes and place in a bowl. 2. Whisk together olive oil, lemon juice, minced garlic, oregano, thyme, salt, and pepper. 3. Pour marinade over chicken, toss to coat, and refrigerate at least 30 minutes. 4. Thread chicken onto metal or soaked wooden skewers. 5. Grill over medium-high heat 12-15 minutes, turning occasionally, until cooked through. 6. Serve in warm pita with tzatziki and fresh vegetables.", "tags": "high-protein, grilled, meal-prep", "source": "https://www.themediterraneandish.com/chicken-souvlaki/", "nutritionData": "{\"calories\": 420, \"protein\": 40.0, \"carbs\": 28.0, \"fat\": 15.0}"},
  {"name": "Lamb Gyros", "category": "Mediterranean", "description": "Seasoned ground lamb cooked on a sheet pan and sliced thin for authentic-style gyros.", "servings": 6, "prepTime": 15, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ground lamb\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tsp\", \"name\": \"dried marjoram\"}, {\"qty\": \"2 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"6\", \"name\": \"pita breads\"}, {\"qty\": \"1 cup\", \"name\": \"tzatziki\"}, {\"qty\": \"2\", \"name\": \"tomatoes\"}, {\"qty\": \"1/2\", \"name\": \"red onion\"}]", "instructions": "1. Preheat oven to 325°F. 2. Pulse onion and garlic in a food processor until finely minced. 3. Combine lamb with onion mixture and all spices, mixing thoroughly for 5 minutes until very smooth. 4. Pack the meat mixture tightly into a loaf pan, pressing out all air bubbles. 5. Bake for 50-60 minutes until internal temperature reaches 165°F. 6. Let rest 5 minutes, then slice very thin. 7. Serve in warm pita with tzatziki, tomatoes, and red onion.", "tags": "high-protein, Greek, weekend-cooking", "source": "https://www.seriouseats.com/homemade-gyro-recipe-with-lamb-and-beef", "nutritionData": "{\"calories\": 510, \"protein\": 36.0, \"carbs\": 30.0, \"fat\": 28.0}"},
  {"name": "Moussaka", "category": "Mediterranean", "description": "Layered Greek casserole of spiced ground lamb, roasted eggplant, and creamy béchamel.", "servings": 8, "prepTime": 40, "cookTime": 75, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large eggplants\"}, {\"qty\": \"1.5 lbs\", \"name\": \"ground lamb\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 cup\", \"name\": \"canned crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"red wine\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"allspice\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2\", \"name\": \"eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Slice eggplant 1/4-inch thick, salt and let drain 30 minutes, then pat dry. 2. Brush eggplant slices with olive oil and roast at 400°F for 20 minutes. 3. Sauté onion and garlic in olive oil until soft; add lamb and brown well. 4. Add wine, crushed tomatoes, cinnamon, and allspice; simmer 20 minutes until thick. 5. Make béchamel: melt butter, whisk in flour, gradually add milk, cook until thick. 6. Remove from heat and stir in eggs and half the Parmesan. 7. Layer eggplant, then meat sauce, then remaining eggplant in a baking dish. 8. Pour béchamel over top, sprinkle remaining Parmesan, and bake at 375°F for 45 minutes until golden.", "tags": "Greek, comfort-food, make-ahead", "source": "https://cooking.nytimes.com/recipes/1014909-moussaka", "nutritionData": "{\"calories\": 490, \"protein\": 28.0, \"carbs\": 22.0, \"fat\": 32.0}"},
  {"name": "Pastitsio", "category": "Mediterranean", "description": "Greek baked pasta with spiced ground beef, tube pasta, and a thick creamy béchamel topping.", "servings": 8, "prepTime": 30, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"tubular pasta (penne or bucatini)\"}, {\"qty\": \"1.5 lbs\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 cup\", \"name\": \"crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"red wine\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"flour\"}, {\"qty\": \"3 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3\", \"name\": \"eggs\"}, {\"qty\": \"1 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cook pasta al dente according to package directions; drain and toss with 1 tbsp olive oil. 2. Sauté onion and garlic, add ground beef, and brown until cooked through. 3. Add wine, tomatoes, cinnamon, nutmeg, salt, and pepper; simmer 20 minutes. 4. Make béchamel: whisk butter and flour, add milk gradually, cook until very thick; beat in eggs off heat. 5. Stir half the Parmesan into the pasta. 6. Spread pasta evenly in a greased 9x13 baking dish. 7. Layer meat sauce over pasta, then pour béchamel on top. 8. Sprinkle remaining Parmesan and bake at 375°F for 45-50 minutes until deep golden.", "tags": "Greek, comfort-food, make-ahead, pasta", "source": "Classic", "nutritionData": "{\"calories\": 560, \"protein\": 34.0, \"carbs\": 45.0, \"fat\": 24.0}"},
  {"name": "Classic Hummus", "category": "Mediterranean", "description": "Silky smooth chickpea hummus blended with tahini, lemon, and garlic, drizzled with olive oil.", "servings": 6, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"chickpeas (15 oz each)\"}, {\"qty\": \"1/3 cup\", \"name\": \"tahini\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"3 tbsp\", \"name\": \"ice water\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"paprika for garnish\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Drain and rinse chickpeas, reserving a few for garnish. 2. Add tahini and lemon juice to food processor and blend 1 minute until creamy. 3. Add garlic, cumin, and salt; blend another minute. 4. Add chickpeas and blend 3-4 minutes, drizzling in ice water for ultra-smooth texture. 5. Taste and adjust salt and lemon. 6. Spread into bowls, drizzle with olive oil, and garnish with paprika, parsley, and reserved chickpeas.", "tags": "vegan, gluten-free, no-cook, snack", "source": "https://www.themediterraneandish.com/easy-hummus-recipe/", "nutritionData": "{\"calories\": 210, \"protein\": 8.0, \"carbs\": 22.0, \"fat\": 11.0}"},
  {"name": "Baba Ganoush", "category": "Mediterranean", "description": "Smoky fire-roasted eggplant dip blended with tahini, garlic, and lemon juice.", "servings": 6, "prepTime": 10, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large eggplants\"}, {\"qty\": \"3 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}, {\"qty\": \"\", \"name\": \"pomegranate seeds for garnish (optional)\"}]", "instructions": "1. Char eggplants directly over a gas flame or under a broiler, turning occasionally, 30-40 minutes until completely collapsed and skin is blackened. 2. Transfer to a colander and let cool and drain for 15 minutes. 3. Peel off charred skin, discard seeds if very large, and squeeze out excess moisture. 4. Roughly chop eggplant flesh and add to food processor with tahini, lemon juice, garlic, cumin, and salt. 5. Pulse until creamy but slightly textured. 6. Transfer to a plate, drizzle with olive oil, garnish with paprika, parsley, and pomegranate seeds.", "tags": "vegan, gluten-free, smoky, mezze", "source": "https://www.seriouseats.com/baba-ganoush-recipe-7484007", "nutritionData": "{\"calories\": 120, \"protein\": 3.0, \"carbs\": 12.0, \"fat\": 8.0}"},
  {"name": "Tabbouleh", "category": "Mediterranean", "description": "Fresh Lebanese herb salad loaded with parsley, mint, bulgur, tomatoes, and bright lemon dressing.", "servings": 6, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"fresh flat-leaf parsley\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh mint\"}, {\"qty\": \"1/2 cup\", \"name\": \"fine bulgur wheat\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes\"}, {\"qty\": \"4\", \"name\": \"green onions\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"allspice\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Soak bulgur in cold water for 10-15 minutes until tender; drain thoroughly and squeeze dry. 2. Finely chop parsley and mint leaves (mostly leaves, few stems). 3. Dice tomatoes small and slice green onions thin. 4. Combine bulgur, parsley, mint, tomatoes, and green onions in a large bowl. 5. Whisk lemon juice, olive oil, allspice, salt, and pepper together. 6. Pour dressing over salad, toss well, and let sit 15 minutes before serving.", "tags": "vegan, Lebanese, fresh, no-cook", "source": "https://www.themediterraneandish.com/tabbouleh-recipe/", "nutritionData": "{\"calories\": 120, \"protein\": 3.0, \"carbs\": 14.0, \"fat\": 7.0}"},
  {"name": "Fattoush Salad", "category": "Mediterranean", "description": "Levantine bread salad with crispy pita chips, seasonal vegetables, and tangy sumac dressing.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"pita breads\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"romaine lettuce hearts\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes\"}, {\"qty\": \"1\", \"name\": \"English cucumber\"}, {\"qty\": \"4\", \"name\": \"radishes\"}, {\"qty\": \"3\", \"name\": \"green onions\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh mint leaves\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"sumac\"}, {\"qty\": \"1 clove\", \"name\": \"garlic\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Tear pita into bite-sized pieces and toss with 1 tbsp olive oil, salt, and half the sumac. 2. Bake pita chips at 375°F for 8-10 minutes until golden and crispy. 3. Whisk remaining olive oil, lemon juice, remaining sumac, minced garlic, salt, and pepper to make dressing. 4. Chop romaine, tomatoes, cucumber, and radishes; slice green onions. 5. Combine vegetables, mint, and parsley in a large bowl. 6. Toss with dressing, then fold in pita chips just before serving.", "tags": "vegetarian, Lebanese, fresh, quick", "source": "https://www.themediterraneandish.com/fattoush-salad-recipe/", "nutritionData": "{\"calories\": 200, \"protein\": 5.0, \"carbs\": 26.0, \"fat\": 9.0}"},
  {"name": "Crispy Falafel", "category": "Mediterranean", "description": "Herb-packed chickpea and fava patties fried until deeply golden and crispy throughout.", "servings": 6, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"dried chickpeas (soaked overnight)\"}, {\"qty\": \"1/2 cup\", \"name\": \"dried fava beans (soaked overnight)\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 cup\", \"name\": \"fresh parsley\"}, {\"qty\": \"1 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"\", \"name\": \"sesame seeds\"}]", "instructions": "1. Drain soaked chickpeas and fava beans thoroughly. 2. Pulse all ingredients (except oil and sesame seeds) in a food processor until a coarse, moist meal forms — do not over-process. 3. Refrigerate mixture 30 minutes, then form into 1.5-inch balls, pressing in sesame seeds. 4. Heat 3 inches of oil to 350°F in a deep pot. 5. Fry falafel in batches for 3-4 minutes until deep golden brown. 6. Drain on paper towels and serve immediately in pita or on a platter with tahini sauce.", "tags": "vegan, Middle Eastern, crispy, street-food", "source": "https://www.seriouseats.com/the-best-falafel-recipe", "nutritionData": "{\"calories\": 290, \"protein\": 13.0, \"carbs\": 34.0, \"fat\": 11.0}"},
  {"name": "Dolmades", "category": "Mediterranean", "description": "Grape leaves stuffed with herbed rice and pine nuts, simmered in olive oil and lemon.", "servings": 8, "prepTime": 45, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"jar grape leaves (about 40 leaves)\"}, {\"qty\": \"1.5 cups\", \"name\": \"long-grain white rice\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/3 cup\", \"name\": \"pine nuts\"}, {\"qty\": \"1/3 cup\", \"name\": \"fresh dill\"}, {\"qty\": \"1/3 cup\", \"name\": \"fresh mint\"}, {\"qty\": \"1/4 cup\", \"name\": \"lemon juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Rinse grape leaves and blanch in boiling water 2 minutes; drain and spread flat. 2. Sauté onion and garlic in 3 tbsp olive oil until soft; add rice and stir 2 minutes. 3. Add pine nuts, dill, mint, allspice, cinnamon, salt, pepper; mix well and let cool. 4. Place a heaping teaspoon of filling on each leaf, fold sides over, and roll tightly. 5. Line a pot bottom with extra grape leaves; arrange stuffed dolmades seam-side down in tight layers. 6. Pour remaining olive oil, lemon juice, and water over dolmades. 7. Weight with a plate, cover, and simmer on low 45 minutes until rice is tender.", "tags": "vegan, Greek, make-ahead, mezze", "source": "Classic", "nutritionData": "{\"calories\": 280, \"protein\": 5.0, \"carbs\": 34.0, \"fat\": 14.0}"},
  {"name": "Kotopoulo Lemonato", "category": "Mediterranean", "description": "Greek braised chicken thighs slowly simmered with lemon, garlic, and olive oil until tender.", "servings": 4, "prepTime": 15, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1/2 cup\", \"name\": \"lemon juice\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1\", \"name\": \"lemon sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"2\", \"name\": \"medium potatoes\"}]", "instructions": "1. Season chicken thighs generously with salt, pepper, and oregano. 2. Heat olive oil in a Dutch oven over medium-high; sear chicken skin-side down 5-6 minutes until golden. 3. Flip and sear 3 minutes more; remove chicken and set aside. 4. Add garlic to pot and sauté 1 minute; deglaze with lemon juice and broth. 5. Add potato wedges, lemon slices, and thyme; nestle chicken back in skin-side up. 6. Cover and simmer on medium-low for 45 minutes until chicken is very tender. 7. Uncover last 10 minutes to reduce sauce slightly; garnish with parsley.", "tags": "Greek, one-pot, comfort-food, gluten-free", "source": "https://www.themediterraneandish.com/greek-lemon-chicken/", "nutritionData": "{\"calories\": 450, \"protein\": 30.0, \"carbs\": 20.0, \"fat\": 28.0}"},
  {"name": "Lebanese Kibbeh", "category": "Mediterranean", "description": "Baked bulgur and ground lamb patties with a spiced meat and pine nut filling.", "servings": 6, "prepTime": 40, "cookTime": 35, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"fine bulgur wheat\"}, {\"qty\": \"1 lb\", \"name\": \"ground lamb (for shell)\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground lamb (for filling)\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"1/3 cup\", \"name\": \"pine nuts\"}, {\"qty\": \"2 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh mint leaves\"}]", "instructions": "1. Soak bulgur in cold water 15 minutes; drain and squeeze very dry. 2. Knead bulgur with 1 lb ground lamb, half the onion (grated), 1 tsp allspice, salt, and pepper until smooth paste forms. 3. For filling: sauté remaining onion in butter until golden, add 1/2 lb lamb, remaining spices, and pine nuts; cook until lamb is done. 4. Grease a baking dish; press half the bulgur-lamb shell into the dish. 5. Spread filling evenly over shell, then top with remaining shell mixture. 6. Score top into diamond shapes, drizzle with olive oil, and bake at 375°F for 35 minutes until golden. 7. Serve with mint and yogurt.", "tags": "Lebanese, lamb, baked, mezze", "source": "Classic", "nutritionData": "{\"calories\": 420, \"protein\": 28.0, \"carbs\": 22.0, \"fat\": 25.0}"},
  {"name": "Moroccan Lamb Tagine", "category": "Mediterranean", "description": "Slow-braised lamb shoulder with warming spices, preserved lemon, and Castelvetrano olives.", "servings": 6, "prepTime": 20, "cookTime": 120, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"bone-in lamb shoulder\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"2\", \"name\": \"preserved lemon quarters\"}, {\"qty\": \"1 cup\", \"name\": \"Castelvetrano olives\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"fresh cilantro\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Season lamb pieces with cumin, coriander, turmeric, ginger, cinnamon, cayenne, and salt. 2. Heat olive oil in a tagine or Dutch oven; sear lamb on all sides until browned, about 10 minutes. 3. Remove lamb; sauté onion until soft, about 5 minutes; add garlic and cook 1 minute. 4. Return lamb to pot, add diced tomatoes and broth, and bring to a simmer. 5. Cover and cook on low heat 1.5-2 hours until lamb is fall-apart tender. 6. In the last 15 minutes, stir in preserved lemon rind and olives. 7. Serve over couscous garnished with fresh cilantro.", "tags": "Moroccan, braised, slow-cook, gluten-free", "source": "https://cooking.nytimes.com/recipes/1014270-lamb-tagine-with-preserved-lemons-and-olives", "nutritionData": "{\"calories\": 480, \"protein\": 32.0, \"carbs\": 10.0, \"fat\": 34.0}"},
  {"name": "Spanish Seafood Paella", "category": "Mediterranean", "description": "Classic Valencian rice dish with saffron, shrimp, mussels, and squid cooked in a wide pan.", "servings": 6, "prepTime": 20, "cookTime": 40, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"Bomba or Arborio rice\"}, {\"qty\": \"1 lb\", \"name\": \"large shrimp (peeled)\"}, {\"qty\": \"1 lb\", \"name\": \"mussels\"}, {\"qty\": \"1/2 lb\", \"name\": \"squid rings\"}, {\"qty\": \"4 cups\", \"name\": \"seafood broth\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2\", \"name\": \"tomatoes\"}, {\"qty\": \"1\", \"name\": \"red bell pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1/2 tsp\", \"name\": \"saffron threads\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"lemon\"}, {\"qty\": \"\", \"name\": \"fresh parsley\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Steep saffron in 1/4 cup warm broth for 10 minutes. 2. Heat olive oil in a wide paella pan; sauté onion and pepper until soft, about 5 minutes. 3. Add garlic and grated tomatoes; cook until sauce thickens, 10 minutes. 4. Add rice and smoked paprika; stir to coat in the sofrito. 5. Pour in hot broth and saffron mixture; arrange seafood evenly over rice. 6. Cook on medium-high without stirring until broth is absorbed, 18-20 minutes. 7. Scatter peas over top, increase heat briefly to form socarrat (crispy bottom), then cover and rest 5 minutes. 8. Garnish with parsley and lemon wedges.", "tags": "Spanish, seafood, saffron, weekend-cooking", "source": "https://www.seriouseats.com/the-best-seafood-paella-recipe", "nutritionData": "{\"calories\": 440, \"protein\": 32.0, \"carbs\": 52.0, \"fat\": 11.0}"},
  {"name": "Andalusian Gazpacho", "category": "Mediterranean", "description": "Chilled Spanish tomato soup blended with cucumber, peppers, garlic, and sherry vinegar.", "servings": 6, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ripe plum tomatoes\"}, {\"qty\": \"1\", \"name\": \"English cucumber\"}, {\"qty\": \"1\", \"name\": \"red bell pepper\"}, {\"qty\": \"1\", \"name\": \"small red onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic\"}, {\"qty\": \"3 tbsp\", \"name\": \"sherry vinegar\"}, {\"qty\": \"4 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 slices\", \"name\": \"stale white bread\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"water as needed\"}, {\"qty\": \"\", \"name\": \"extra-virgin olive oil to serve\"}]", "instructions": "1. Remove crusts from bread and soak in cold water for 5 minutes; squeeze dry. 2. Roughly chop tomatoes, cucumber, pepper, onion, and garlic. 3. Combine all vegetables, bread, garlic, vinegar, olive oil, cumin, salt, and pepper in a blender. 4. Blend on high speed 2-3 minutes until very smooth. 5. Pass through a fine-mesh strainer for silkier texture if desired. 6. Adjust seasoning and thin with cold water if too thick. 7. Refrigerate at least 2 hours until well chilled; serve in bowls with a drizzle of olive oil.", "tags": "Spanish, vegan, no-cook, summer, cold-soup", "source": "https://www.seriouseats.com/best-gazpacho-recipe", "nutritionData": "{\"calories\": 150, \"protein\": 3.0, \"carbs\": 18.0, \"fat\": 8.0}"},
  {"name": "Classic Caprese Salad", "category": "Mediterranean", "description": "Fresh mozzarella and ripe tomatoes layered with basil, olive oil, and aged balsamic glaze.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh mozzarella\"}, {\"qty\": \"4\", \"name\": \"large heirloom tomatoes\"}, {\"qty\": \"1\", \"name\": \"bunch fresh basil\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic glaze\"}, {\"qty\": \"1/2 tsp\", \"name\": \"flaky sea salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Slice mozzarella and tomatoes into 1/4-inch rounds. 2. Arrange alternating slices of tomato and mozzarella on a serving platter. 3. Tuck basil leaves between slices. 4. Drizzle with olive oil and balsamic glaze. 5. Season with flaky salt and black pepper and serve immediately.", "tags": "Italian, vegetarian, no-cook, quick, gluten-free", "source": "https://www.bonappetit.com/recipe/classic-caprese-salad", "nutritionData": "{\"calories\": 300, \"protein\": 18.0, \"carbs\": 8.0, \"fat\": 22.0}"},
  {"name": "Tuscan Panzanella", "category": "Mediterranean", "description": "Rustic Italian bread salad with juicy tomatoes, soaked ciabatta, basil, and red wine vinaigrette.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2\", \"name\": \"loaf ciabatta or sourdough bread\"}, {\"qty\": \"2 lbs\", \"name\": \"ripe tomatoes\"}, {\"qty\": \"1/2\", \"name\": \"red onion\"}, {\"qty\": \"1\", \"name\": \"English cucumber\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"5 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 clove\", \"name\": \"garlic\"}, {\"qty\": \"1 tsp\", \"name\": \"capers\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Tear bread into rough 1.5-inch pieces; toss with 2 tbsp olive oil and bake at 400°F until toasted and golden, about 10 minutes. 2. Cut tomatoes into wedges; season with salt and let sit in a colander 10 minutes to drain juices. 3. Reserve tomato juices for the vinaigrette. 4. Thinly slice red onion; toss with 1 tbsp vinegar and let marinate. 5. Whisk remaining olive oil, remaining vinegar, minced garlic, capers, and tomato juices. 6. Combine bread, tomatoes, onion, sliced cucumber, and basil. 7. Toss with vinaigrette, let sit 15 minutes for bread to absorb, and serve.", "tags": "Italian, vegetarian, bread-salad, summer", "source": "https://www.seriouseats.com/the-best-panzanella-recipe-tuscan-style-bread-salad", "nutritionData": "{\"calories\": 320, \"protein\": 7.0, \"carbs\": 38.0, \"fat\": 16.0}"},
  {"name": "Branzino al Limone", "category": "Mediterranean", "description": "Whole roasted branzino stuffed with lemon and fresh herbs, finished with caper butter.", "servings": 2, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"whole branzino (cleaned and scaled)\"}, {\"qty\": \"2\", \"name\": \"lemons\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Preheat oven to 425°F. Score fish 3 times on each side with a sharp knife. 2. Season fish inside and out with salt and pepper; stuff cavity with lemon slices, rosemary, thyme, and garlic. 3. Rub outside with olive oil. 4. Place in a roasting pan and pour white wine around fish. 5. Roast 18-20 minutes until flesh is opaque and flakes easily. 6. Meanwhile, melt butter in a small pan and cook capers until sizzling. 7. Pour caper butter over roasted branzino and serve with lemon wedges.", "tags": "Italian, seafood, gluten-free, elegant, quick", "source": "https://www.bonappetit.com/recipe/branzino-with-lemon-herb-butter", "nutritionData": "{\"calories\": 380, \"protein\": 42.0, \"carbs\": 5.0, \"fat\": 20.0}"},
  {"name": "Mediterranean Baked Cod", "category": "Mediterranean", "description": "Flaky cod fillets baked in a vibrant tomato, olive, caper, and herb sauce.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"cod fillets\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"kalamata olives\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1\", \"name\": \"small onion\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F. 2. Sauté onion and garlic in olive oil in an oven-safe skillet over medium heat until softened. 3. Add white wine and cook 2 minutes to reduce slightly. 4. Add diced tomatoes, olives, capers, oregano, basil, and red pepper flakes; simmer 5 minutes. 5. Season cod fillets with salt and pepper and nestle into the tomato sauce. 6. Bake uncovered for 15-18 minutes until cod is opaque and flakes easily. 7. Garnish with fresh parsley and serve with crusty bread.", "tags": "seafood, gluten-free, healthy, quick", "source": "https://www.themediterraneandish.com/baked-cod-recipe/", "nutritionData": "{\"calories\": 280, \"protein\": 34.0, \"carbs\": 12.0, \"fat\": 10.0}"},
  {"name": "Lemon Herb Orzo", "category": "Mediterranean", "description": "Creamy one-pot orzo with bright lemon zest, fresh herbs, spinach, and Parmesan.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"orzo pasta\"}, {\"qty\": \"3 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1\", \"name\": \"lemon (zested and juiced)\"}, {\"qty\": \"2 cups\", \"name\": \"baby spinach\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh dill\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Heat olive oil in a medium saucepan over medium heat; sauté garlic 1 minute. 2. Add orzo and toast, stirring, for 2 minutes. 3. Pour in chicken broth and bring to a boil; reduce heat to medium-low and simmer uncovered 10-12 minutes, stirring frequently, until orzo is al dente and broth is mostly absorbed. 4. Stir in butter, lemon zest, lemon juice, and Parmesan. 5. Fold in baby spinach and cook 1 minute until wilted. 6. Remove from heat, stir in dill and parsley, season with salt and pepper, and serve.", "tags": "vegetarian, quick, one-pot, side-dish", "source": "https://www.halfbakedharvest.com/lemon-herb-orzo/", "nutritionData": "{\"calories\": 360, \"protein\": 13.0, \"carbs\": 50.0, \"fat\": 12.0}"},
  {"name": "Lamb Kofta", "category": "Mediterranean", "description": "Spiced Middle Eastern ground lamb skewers grilled over high heat and served with tahini sauce.", "servings": 4, "prepTime": 20, "cookTime": 12, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"ground lamb\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh parsley\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"water\"}, {\"qty\": \"\", \"name\": \"flatbread to serve\"}]", "instructions": "1. Finely grate onion and squeeze out moisture; mince garlic and parsley. 2. Combine lamb, onion, garlic, parsley, and all spices; knead for 2-3 minutes until well mixed and sticky. 3. Refrigerate 30 minutes (optional, helps hold shape). 4. Divide mixture into 8 portions; mold each around a flat metal skewer into a sausage shape. 5. Grill over high heat 10-12 minutes, turning every few minutes, until cooked through and charred. 6. Whisk tahini, lemon juice, and water to make sauce. 7. Serve kofta with tahini sauce and flatbread.", "tags": "Middle Eastern, grilled, high-protein, gluten-free", "source": "https://www.seriouseats.com/ground-lamb-kofta-kebab-recipe", "nutritionData": "{\"calories\": 410, \"protein\": 33.0, \"carbs\": 8.0, \"fat\": 28.0}"},
  {"name": "Sicilian Eggplant Caponata", "category": "Mediterranean", "description": "Sweet and sour Sicilian eggplant stew with tomatoes, olives, capers, and pine nuts.", "servings": 6, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large eggplants\"}, {\"qty\": \"2\", \"name\": \"stalks celery\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) crushed tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"green olives\"}, {\"qty\": \"3 tbsp\", \"name\": \"capers\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"pine nuts\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cut eggplant into 1-inch cubes, salt generously, and let drain in a colander 30 minutes; pat dry. 2. Fry eggplant in hot olive oil in batches until golden on all sides; remove and set aside. 3. In the same pan, sauté onion and celery until softened. 4. Add crushed tomatoes and simmer 10 minutes. 5. Stir in olives, capers, red wine vinegar, and sugar; cook 5 minutes. 6. Return eggplant to pan; season with salt and pepper and simmer 5 more minutes. 7. Toast pine nuts in a dry pan; scatter over caponata with fresh basil. Serve warm or at room temperature.", "tags": "Sicilian, vegan, make-ahead, mezze, sweet-and-sour", "source": "https://cooking.nytimes.com/recipes/1012383-caponata", "nutritionData": "{\"calories\": 200, \"protein\": 4.0, \"carbs\": 20.0, \"fat\": 13.0}"},
  {"name": "Provençal Ratatouille", "category": "Mediterranean", "description": "Classic French Provençal vegetable stew with zucchini, eggplant, peppers, and herbes de Provence.", "servings": 6, "prepTime": 25, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium zucchini\"}, {\"qty\": \"1\", \"name\": \"large eggplant\"}, {\"qty\": \"2\", \"name\": \"bell peppers\"}, {\"qty\": \"4\", \"name\": \"medium tomatoes\"}, {\"qty\": \"1\", \"name\": \"large onion\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"herbes de Provence\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried basil\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Dice all vegetables into 3/4-inch pieces. 2. Heat 2 tbsp olive oil in a large Dutch oven; cook onion and garlic until soft, about 5 minutes. 3. Add eggplant and cook 8 minutes, stirring occasionally. 4. Add bell peppers and cook 5 more minutes. 5. Stir in tomato paste, diced tomatoes, herbes de Provence, and dried basil. 6. Add zucchini, season well with salt and pepper, and cover; simmer on medium-low 25-30 minutes. 7. Uncover and cook 10 more minutes to thicken. Stir in fresh basil and remaining olive oil before serving.", "tags": "French, vegan, gluten-free, make-ahead", "source": "https://cooking.nytimes.com/recipes/1015921-ratatouille", "nutritionData": "{\"calories\": 160, \"protein\": 3.0, \"carbs\": 18.0, \"fat\": 9.0}"},
  {"name": "Harissa Roasted Vegetables", "category": "Mediterranean", "description": "Vibrant North African spiced roasted cauliflower, carrots, and chickpeas with yogurt drizzle.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"head cauliflower\"}, {\"qty\": \"3\", \"name\": \"large carrots\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) chickpeas\"}, {\"qty\": \"3 tbsp\", \"name\": \"harissa paste\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame seeds\"}]", "instructions": "1. Preheat oven to 425°F and line a large sheet pan with parchment. 2. Cut cauliflower into florets and carrots into sticks; drain and rinse chickpeas. 3. Toss all vegetables and chickpeas with harissa, olive oil, cumin, coriander, and salt. 4. Spread in a single layer on the sheet pan; roast 30-35 minutes, turning once, until caramelized and tender. 5. Stir together yogurt and lemon juice to make a drizzle. 6. Transfer vegetables to a platter, drizzle with yogurt, and scatter cilantro and sesame seeds over top.", "tags": "vegetarian, North African, sheet-pan, gluten-free", "source": "https://www.halfbakedharvest.com/harissa-roasted-cauliflower/", "nutritionData": "{\"calories\": 290, \"protein\": 12.0, \"carbs\": 32.0, \"fat\": 13.0}"},
  {"name": "Freekeh Pilaf with Herbs", "category": "Mediterranean", "description": "Smoky whole-grain freekeh cooked pilaf-style with toasted nuts, dried fruit, and warming spices.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"whole freekeh\"}, {\"qty\": \"2 cups\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/3 cup\", \"name\": \"slivered almonds\"}, {\"qty\": \"1/3 cup\", \"name\": \"dried apricots\"}, {\"qty\": \"1 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh mint\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Rinse freekeh under cold water; drain. 2. Toast slivered almonds in a dry pan until golden; set aside. 3. Heat olive oil in a medium saucepan; sauté onion until golden, about 7 minutes. 4. Add garlic and spices; cook 1 minute. 5. Add freekeh and stir to coat in the oil and spices. 6. Pour in broth, season with salt and pepper, bring to a boil. 7. Reduce heat to low, cover, and cook 20-25 minutes until liquid is absorbed. 8. Fluff with a fork; fold in almonds, chopped dried apricots, parsley, and mint.", "tags": "grain, Lebanese, make-ahead, nut-free-adaptable", "source": "Classic", "nutritionData": "{\"calories\": 320, \"protein\": 10.0, \"carbs\": 48.0, \"fat\": 11.0}"},
  {"name": "Mediterranean Stuffed Peppers", "category": "Mediterranean", "description": "Bell peppers filled with herbed rice, ground beef, tomatoes, and feta, baked until tender.", "servings": 4, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large bell peppers\"}, {\"qty\": \"1 lb\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1 cup\", \"name\": \"cooked white rice\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled feta\"}, {\"qty\": \"1\", \"name\": \"medium onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"1/2 cup\", \"name\": \"tomato sauce\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 375°F. Slice tops off peppers and remove seeds and membranes. 2. Sauté onion and garlic in olive oil until soft; add ground beef and brown completely. 3. Drain excess fat; stir in diced tomatoes, cooked rice, oregano, cumin, salt, and pepper. 4. Remove from heat and fold in feta and parsley. 5. Place peppers in a baking dish; fill each generously with the beef and rice mixture. 6. Pour tomato sauce around the base of the peppers and cover with foil. 7. Bake 35 minutes covered, then uncover and bake 10 more minutes until peppers are tender.", "tags": "Greek-inspired, comfort-food, gluten-free, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 30.0, \"carbs\": 32.0, \"fat\": 22.0}"},
  {"name": "Turkish Menemen", "category": "Mediterranean", "description": "Silky Turkish scrambled eggs cooked in a spiced tomato and pepper sauce with fresh herbs.", "servings": 2, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes\"}, {\"qty\": \"2\", \"name\": \"green cubanelle peppers\"}, {\"qty\": \"1\", \"name\": \"small onion\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"Aleppo pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"paprika\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley\"}, {\"qty\": \"\", \"name\": \"crusty bread to serve\"}]", "instructions": "1. Dice onion and peppers; grate or finely chop tomatoes. 2. Heat olive oil in a wide skillet; sauté onion 4 minutes until softened. 3. Add peppers and cook 3 more minutes. 4. Stir in garlic, cumin, Aleppo pepper, and paprika; cook 1 minute. 5. Add tomatoes and cook on medium heat until sauce thickens slightly, 5 minutes. 6. Crack eggs directly into the pan; stir gently with a spatula to create soft folds — do not scramble completely, keep creamy. 7. Remove from heat while still glossy and soft; season with salt and scatter parsley over top. Serve immediately with bread.", "tags": "Turkish, breakfast, vegetarian, quick", "source": "https://cooking.nytimes.com/recipes/1020716-menemen", "nutritionData": "{\"calories\": 310, \"protein\": 16.0, \"carbs\": 14.0, \"fat\": 22.0}"},
  {"name": "Israeli Couscous Salad", "category": "Mediterranean", "description": "Pearl couscous tossed with roasted vegetables, sun-dried tomatoes, olives, and lemon dressing.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"Israeli pearl couscous\"}, {\"qty\": \"1\", \"name\": \"zucchini\"}, {\"qty\": \"1\", \"name\": \"red bell pepper\"}, {\"qty\": \"1 cup\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"sun-dried tomatoes (oil-packed)\"}, {\"qty\": \"1/2 cup\", \"name\": \"Castelvetrano olives\"}, {\"qty\": \"1/3 cup\", \"name\": \"crumbled feta\"}, {\"qty\": \"3 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh basil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Cook pearl couscous in salted boiling water 8-10 minutes until al dente; drain and cool. 2. Halve zucchini and bell pepper; toss with 1 tbsp olive oil and roast at 425°F for 15 minutes until caramelized; dice. 3. Halve cherry tomatoes; slice sun-dried tomatoes and olives. 4. Whisk remaining olive oil, lemon juice, minced garlic, and oregano for dressing. 5. Combine couscous, roasted vegetables, cherry tomatoes, sun-dried tomatoes, and olives in a large bowl. 6. Pour dressing over and toss; fold in feta and fresh basil. 7. Serve warm or at room temperature.", "tags": "Israeli, vegetarian, make-ahead, grain-bowl", "source": "https://www.halfbakedharvest.com/israeli-couscous-salad/", "nutritionData": "{\"calories\": 340, \"protein\": 9.0, \"carbs\": 44.0, \"fat\": 14.0}"},
  {"name": "Spanish Tortilla", "category": "Mediterranean", "description": "Classic Tortilla Española with slowly poached potatoes and onions set in silky golden eggs.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"3\", \"name\": \"medium Yukon gold potatoes\"}, {\"qty\": \"1\", \"name\": \"large yellow onion\"}, {\"qty\": \"1 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Peel and thinly slice potatoes (1/8-inch); halve and slice onion thinly. 2. Heat olive oil in a 10-inch non-stick skillet; add potatoes and onion with salt; cook on medium-low, stirring occasionally, until potatoes are very tender but not browned, about 20 minutes. 3. Drain potatoes and onions in a colander over a bowl, reserving the oil. 4. Beat eggs in a large bowl; fold in the warm potato-onion mixture and season with pepper. 5. Heat 2 tbsp of the reserved oil in the skillet over medium heat; pour in the egg mixture. 6. Cook until edges are set and bottom is golden, 5-7 minutes; cover skillet with a large plate and flip confidently in one motion. 7. Slide tortilla back into pan uncooked-side down and cook 3-4 more minutes until just set. Rest 5 minutes before slicing.", "tags": "Spanish, vegetarian, tapas, gluten-free, make-ahead", "source": "https://www.seriouseats.com/best-spanish-tortilla-de-patatas-recipe", "nutritionData": "{\"calories\": 330, \"protein\": 10.0, \"carbs\": 22.0, \"fat\": 23.0}"},
  {"name": "Carnitas", "category": "Mexican", "description": "Slow-braised pork shoulder confited in lard and citrus until fall-apart tender and crisped in its own fat.", "servings": 8, "prepTime": 20, "cookTime": 240, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 lb\", \"name\": \"pork shoulder cut into 2-inch chunks\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"4\", \"name\": \"garlic cloves smashed\"}, {\"qty\": \"1\", \"name\": \"white onion quartered\"}, {\"qty\": \"1\", \"name\": \"orange halved\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"lard or vegetable oil\"}, {\"qty\": \"\", \"name\": \"corn tortillas for serving\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for serving\"}, {\"qty\": \"\", \"name\": \"diced white onion for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. Season pork chunks generously with salt, pepper, cumin, and oregano. 2. Place pork in a large Dutch oven with lard, garlic, onion, squeezed orange halves (add the juice too), and bay leaves. 3. Cook covered in a 275°F oven for 3 to 3.5 hours until pork is completely tender and shreddable. 4. Remove pork from fat and shred into large chunks. 5. Return shredded pork to a hot cast iron skillet with some of the rendered fat. 6. Cook undisturbed over medium-high heat for 3-4 minutes per side until crispy and caramelized. 7. Serve in warm corn tortillas with cilantro, diced onion, and a squeeze of lime.", "tags": "pork, slow-cooked, tacos, authentic", "source": "https://www.seriouseats.com/no-waste-tacos-de-carnitas-with-salsa-verde-recipe", "nutritionData": "{\"calories\": 520, \"protein\": 38.0, \"carbs\": 14.0, \"fat\": 34.0}"},
  {"name": "Al Pastor Tacos", "category": "Mexican", "description": "Marinated pork spit-style with guajillo chiles, achiote, and pineapple served in small corn tortillas.", "servings": 6, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"boneless pork shoulder thinly sliced\"}, {\"qty\": \"3\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"2 tbsp\", \"name\": \"achiote paste\"}, {\"qty\": \"3\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2\", \"name\": \"white onion\"}, {\"qty\": \"3 tbsp\", \"name\": \"white vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"fresh pineapple chunks\"}, {\"qty\": \"12\", \"name\": \"small corn tortillas\"}, {\"qty\": \"1/2 cup\", \"name\": \"diced white onion\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro leaves\"}, {\"qty\": \"2\", \"name\": \"limes cut into wedges\"}]", "instructions": "1. Toast dried chiles in a dry skillet over medium heat for 30 seconds per side until fragrant, then soak in hot water for 15 minutes. 2. Blend softened chiles with achiote paste, garlic, onion, vinegar, oregano, cumin, and salt until smooth. 3. Coat sliced pork thoroughly in the marinade, cover, and refrigerate for at least 4 hours or overnight. 4. Cook marinated pork in a hot cast iron skillet or grill pan over high heat in batches until charred at the edges, about 3-4 minutes per side. 5. Chop cooked pork into small pieces and toss with caramelized pineapple chunks. 6. Warm tortillas on a comal and fill with pork and pineapple. 7. Top with diced onion, cilantro, and a squeeze of lime.", "tags": "pork, tacos, street food, marinated", "source": "Classic", "nutritionData": "{\"calories\": 420, \"protein\": 32.0, \"carbs\": 28.0, \"fat\": 18.0}"},
  {"name": "Birria de Res", "category": "Mexican", "description": "Rich Jalisco-style beef stew braised in a deep red chile consommé until fall-apart tender.", "servings": 6, "prepTime": 30, "cookTime": 210, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"beef chuck roast cut into 4-inch chunks\"}, {\"qty\": \"12\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"5\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"4\", \"name\": \"arbol chiles stemmed\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion\"}, {\"qty\": \"1\", \"name\": \"Mexican cinnamon stick\"}, {\"qty\": \"3\", \"name\": \"bay leaves\"}, {\"qty\": \"5\", \"name\": \"garlic cloves\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"2 cups\", \"name\": \"beef broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"white vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Season beef chunks with salt and pepper, then sear in olive oil in a Dutch oven over high heat until deeply browned on all sides. 2. Simmer guajillo, ancho, and arbol chiles with tomatoes, onion, cinnamon, and bay leaves in water for 10 minutes until softened. 3. Blend softened chiles and vegetables with beef broth, vinegar, garlic, cumin, oregano, and cloves until smooth. 4. Strain blended sauce through a fine mesh strainer over the seared beef. 5. Bring to a boil, then reduce heat to low, cover, and simmer for 3 to 3.5 hours until beef is completely tender. 6. Remove beef and shred with two forks, then return to the consommé. 7. Serve in bowls garnished with diced onion, cilantro, and lime wedges alongside warm corn tortillas.", "tags": "beef, stew, Jalisco, slow-cooked", "source": "https://www.isabeleats.com/authentic-birria/", "nutritionData": "{\"calories\": 480, \"protein\": 42.0, \"carbs\": 12.0, \"fat\": 28.0}"},
  {"name": "Quesabirria Tacos", "category": "Mexican", "description": "Crispy corn tortillas dipped in birria consommé and filled with shredded beef and melted Oaxaca cheese, served with consommé for dunking.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"cooked shredded birria beef\"}, {\"qty\": \"2 cups\", \"name\": \"birria consomm\\u00e9\"}, {\"qty\": \"12\", \"name\": \"small corn tortillas\"}, {\"qty\": \"2 cups\", \"name\": \"shredded Oaxaca cheese\"}, {\"qty\": \"1/2\", \"name\": \"white onion finely diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro leaves\"}, {\"qty\": \"2\", \"name\": \"limes cut into wedges\"}, {\"qty\": \"1 tbsp\", \"name\": \"birria fat skimmed from consomm\\u00e9\"}, {\"qty\": \"\", \"name\": \"salsa verde or salsa roja for serving\"}]", "instructions": "1. Heat a large non-stick skillet over medium heat and add birria fat. 2. Dip each corn tortilla briefly in the warm consommé to coat, then place in the hot skillet red side down. 3. Immediately sprinkle shredded Oaxaca cheese on one half of the tortilla. 4. Add a generous portion of shredded birria beef on top of the cheese. 5. Fold the tortilla over and cook for 2 minutes per side until golden and crispy. 6. Repeat with remaining tortillas, adding fresh birria fat as needed. 7. Serve immediately with small bowls of hot consommé, diced onion, cilantro, and lime for squeezing.", "tags": "beef, tacos, cheesy, birria", "source": "Classic", "nutritionData": "{\"calories\": 560, \"protein\": 40.0, \"carbs\": 30.0, \"fat\": 30.0}"},
  {"name": "Barbacoa", "category": "Mexican", "description": "Slow-braised beef cheeks or chuck in chile and spice paste, steamed until meltingly tender and deeply flavored.", "servings": 8, "prepTime": 25, "cookTime": 300, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4 lb\", \"name\": \"beef cheeks or chuck roast\"}, {\"qty\": \"4\", \"name\": \"chipotle chiles in adobo sauce\"}, {\"qty\": \"4\", \"name\": \"ancho chiles soaked and seeded\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2\", \"name\": \"white onion\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"3\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"banana leaves or foil for wrapping\"}, {\"qty\": \"\", \"name\": \"corn tortillas for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. Blend chipotle chiles, soaked ancho chiles, garlic, onion, vinegar, cumin, oregano, cloves, salt, and broth into a smooth paste. 2. Score beef and coat thoroughly with the chile paste. 3. Line a large pot or Dutch oven with banana leaves, place seasoned beef inside, add bay leaves, and fold leaves over to enclose. 4. Add 1 cup water to the bottom of the pot, cover tightly, and cook in a 300°F oven for 5 hours until completely tender. 5. Alternatively, cook in a slow cooker on low for 8 hours. 6. Shred the beef and mix with cooking juices. 7. Serve on warm corn tortillas topped with diced onion, cilantro, and fresh lime juice.", "tags": "beef, slow-cooked, tacos, Hidalgo-style", "source": "Classic", "nutritionData": "{\"calories\": 440, \"protein\": 40.0, \"carbs\": 10.0, \"fat\": 26.0}"},
  {"name": "Cochinita Pibil", "category": "Mexican", "description": "Yucatecan slow-roasted pork shoulder marinated in achiote and citrus, wrapped in banana leaves until fall-apart tender.", "servings": 6, "prepTime": 15, "cookTime": 210, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"pork shoulder cut into large chunks\"}, {\"qty\": \"3.5 oz\", \"name\": \"achiote paste\"}, {\"qty\": \"1 cup\", \"name\": \"fresh orange juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1\", \"name\": \"white onion quartered\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"\", \"name\": \"2-3 banana leaves\"}, {\"qty\": \"\", \"name\": \"corn tortillas for serving\"}, {\"qty\": \"\", \"name\": \"pickled red onions for serving\"}, {\"qty\": \"\", \"name\": \"queso fresco for serving\"}, {\"qty\": \"\", \"name\": \"chopped cilantro for serving\"}]", "instructions": "1. Blend achiote paste, orange juice, lime juice, onion, garlic, salt, and cumin until completely smooth. 2. Combine pork and marinade in a large bowl, toss to coat, cover, and refrigerate for at least 6 hours or overnight. 3. Preheat oven to 325°F. 4. Line a Dutch oven with banana leaves so they cover the bottom and hang over the sides. 5. Add marinated pork including all marinade juices, then fold banana leaves over the top. 6. Cover and bake for 3.5 hours until pork is completely fall-apart tender. 7. Shred the pork, mix with 1/3 cup of the cooking liquid, and serve in corn tortillas topped with pickled red onions and queso fresco.", "tags": "pork, Yucatan, slow-roasted, banana-leaves", "source": "https://www.isabeleats.com/cochinita-pibil/", "nutritionData": "{\"calories\": 460, \"protein\": 38.0, \"carbs\": 16.0, \"fat\": 26.0}"},
  {"name": "Tinga de Pollo", "category": "Mexican", "description": "Shredded chicken in a smoky chipotle-tomato sauce, perfect for tacos or tostadas.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"1/2\", \"name\": \"white onion sliced\"}, {\"qty\": \"3\", \"name\": \"chipotle peppers in adobo sauce\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"\", \"name\": \"corn tortillas or tostada shells for serving\"}, {\"qty\": \"\", \"name\": \"cotija cheese for serving\"}, {\"qty\": \"\", \"name\": \"diced avocado for serving\"}]", "instructions": "1. Poach chicken thighs in seasoned water for 15-20 minutes until cooked through, reserve 1 cup broth, then shred. 2. Broil tomatoes and onion on a baking sheet for 10 minutes until charred. 3. Blend charred tomatoes and onion with chipotle peppers, garlic, oregano, cumin, salt, and 1/2 cup reserved broth until smooth. 4. Heat olive oil in a large skillet over medium-high heat and cook the blended tinga sauce for 10 minutes, stirring occasionally. 5. Add shredded chicken and stir to coat evenly in the sauce. 6. Cook for another 10 minutes until sauce thickens and reduces. 7. Serve on warm tortillas or tostadas with cotija cheese, diced avocado, and cilantro.", "tags": "chicken, tacos, chipotle, quick", "source": "https://www.isabeleats.com/chicken-tinga/", "nutritionData": "{\"calories\": 320, \"protein\": 35.0, \"carbs\": 8.0, \"fat\": 16.0}"},
  {"name": "Enchiladas Verdes", "category": "Mexican", "description": "Corn tortillas filled with shredded chicken, smothered in bright roasted tomatillo salsa verde, and baked with melted cheese.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"corn tortillas\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cooked chicken\"}, {\"qty\": \"2 cups\", \"name\": \"shredded Monterey Jack or Mexican blend cheese\"}, {\"qty\": \"1 lb\", \"name\": \"tomatillos husked and rinsed\"}, {\"qty\": \"3\", \"name\": \"jalape\\u00f1o peppers stemmed\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2\", \"name\": \"white onion roughly chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1 tbsp\", \"name\": \"lime juice\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"\", \"name\": \"Mexican crema for serving\"}, {\"qty\": \"\", \"name\": \"thinly sliced red onion for serving\"}, {\"qty\": \"\", \"name\": \"crumbled cotija cheese for serving\"}]", "instructions": "1. Broil tomatillos, jalapeños, and garlic on a baking sheet for 10 minutes flipping halfway until charred. 2. Blend charred vegetables with onion, cilantro, lime juice, and salt until smooth salsa verde forms. 3. Preheat oven to 350°F and pour 1/2 cup salsa verde into a 9x13 baking dish. 4. Warm tortillas in microwave wrapped in damp paper towel for 1 minute until pliable. 5. Spoon about 2 tbsp chicken onto each tortilla, roll tightly, and place seam-side down in the baking dish. 6. Pour remaining salsa verde over enchiladas and top with shredded cheese. 7. Bake for 10-15 minutes until cheese melts and sauce bubbles, then garnish with crema, red onion, and cotija.", "tags": "chicken, enchiladas, tomatillo, baked", "source": "https://www.isabeleats.com/salsa-verde-chicken-enchiladas/", "nutritionData": "{\"calories\": 510, \"protein\": 34.0, \"carbs\": 40.0, \"fat\": 22.0}"},
  {"name": "Enchiladas Rojas", "category": "Mexican", "description": "Rolled corn tortillas filled with shredded beef and drenched in a rich dried-chile red sauce, topped with crema and onion.", "servings": 4, "prepTime": 25, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"corn tortillas\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cooked beef or chicken\"}, {\"qty\": \"4\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"3\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/4\", \"name\": \"white onion\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 cup\", \"name\": \"crumbled queso fresco\"}, {\"qty\": \"1/4\", \"name\": \"white onion thinly sliced\"}, {\"qty\": \"\", \"name\": \"Mexican crema for drizzling\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}]", "instructions": "1. Toast dried chiles briefly in a dry skillet, then soak in hot water for 15 minutes until softened. 2. Blend softened chiles with tomatoes, garlic, onion, oregano, cumin, and broth until smooth, then strain. 3. Heat 1 tbsp oil in a saucepan, add strained chile sauce, and simmer for 10 minutes until slightly thickened. 4. Dip each corn tortilla in the warm red chile sauce and cook briefly in an oiled skillet for 20 seconds per side. 5. Fill each sauced tortilla with shredded meat, roll up, and arrange in a baking dish. 6. Pour remaining sauce over the enchiladas. 7. Serve topped with crumbled queso fresco, sliced onion, drizzle of crema, and cilantro.", "tags": "beef, enchiladas, red-chile, authentic", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 32.0, \"carbs\": 42.0, \"fat\": 20.0}"},
  {"name": "Enchiladas Suizas", "category": "Mexican", "description": "Creamy tomatillo-cream sauce enchiladas stuffed with chicken and blanketed with melted Gruyère or Swiss cheese.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"corn tortillas\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cooked chicken\"}, {\"qty\": \"1 lb\", \"name\": \"tomatillos husked\"}, {\"qty\": \"2\", \"name\": \"serrano chiles\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/4\", \"name\": \"white onion\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1 cup\", \"name\": \"Mexican crema or heavy cream\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Gruy\\u00e8re or Swiss cheese\"}, {\"qty\": \"1 cup\", \"name\": \"shredded mozzarella\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"diced white onion for serving\"}]", "instructions": "1. Simmer tomatillos and serrano chiles in water for 10 minutes until soft, then drain. 2. Blend cooked tomatillos, serranos, garlic, onion, and cilantro until smooth. 3. In a saucepan over medium heat, cook tomatillo sauce for 5 minutes, then stir in Mexican crema and salt. 4. Preheat oven to 375°F and spread 1/2 cup sauce in a baking dish. 5. Briefly fry each tortilla in hot oil for 10 seconds to soften, then fill with chicken and roll tightly. 6. Arrange rolled enchiladas seam-side down, pour remaining creamy sauce over all, and top with Gruyère and mozzarella. 7. Bake for 15-20 minutes until bubbly and golden, then serve immediately.", "tags": "chicken, enchiladas, creamy, cheese", "source": "Classic", "nutritionData": "{\"calories\": 580, \"protein\": 36.0, \"carbs\": 38.0, \"fat\": 30.0}"},
  {"name": "Chicken Mole Poblano", "category": "Mexican", "description": "Roasted chicken smothered in the legendary complex sauce of dried chiles, nuts, spices, and Mexican chocolate from Puebla.", "servings": 6, "prepTime": 45, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"bone-in skin-on chicken pieces\"}, {\"qty\": \"4\", \"name\": \"mulato chiles stemmed and seeded\"}, {\"qty\": \"3\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"pasilla chiles stemmed and seeded\"}, {\"qty\": \"1/4 cup\", \"name\": \"blanched almonds\"}, {\"qty\": \"1/4 cup\", \"name\": \"raw peanuts\"}, {\"qty\": \"2 tbsp\", \"name\": \"raw sesame seeds\"}, {\"qty\": \"1/4 cup\", \"name\": \"raisins\"}, {\"qty\": \"1/2\", \"name\": \"white onion\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"3\", \"name\": \"tomatillos\"}, {\"qty\": \"2\", \"name\": \"corn tortilla pieces\"}, {\"qty\": \"1 slice\", \"name\": \"stale white bread\"}, {\"qty\": \"1\", \"name\": \"Mexican cinnamon stick\"}, {\"qty\": \"3\", \"name\": \"whole cloves\"}, {\"qty\": \"1 tsp\", \"name\": \"black peppercorns\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried marjoram\"}, {\"qty\": \"2 oz\", \"name\": \"Mexican chocolate chopped\"}, {\"qty\": \"3 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"lard or oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}]", "instructions": "1. Toast dried chiles in hot lard for 1-2 minutes per side until fragrant but not burnt, then soak in hot water for 30 minutes. 2. In the same pot fry onion and garlic until golden, then add almonds, peanuts, raisins, and seeds and cook 3 minutes. 3. Add tortilla pieces, bread, tomatoes, tomatillos, and all spices and cook 2-3 more minutes. 4. Add soaked chiles and chicken broth, bring to a boil, then simmer 15 minutes. 5. Let mixture cool, then blend in batches until completely smooth. 6. Fry blended mole in remaining hot lard for 5 minutes, stir in chocolate until melted, season with salt, and simmer 20 minutes. 7. Brown chicken in oil, pour mole over, cover, and braise 45 minutes until chicken is cooked through. Garnish with sesame seeds.", "tags": "chicken, mole, Puebla, complex", "source": "https://patijinich.com/mole_poblano_de_los_angeles/", "nutritionData": "{\"calories\": 590, \"protein\": 38.0, \"carbs\": 22.0, \"fat\": 38.0}"},
  {"name": "Pozole Rojo", "category": "Mexican", "description": "Hearty Mexican hominy soup with tender pork in a rich guajillo-chile broth, topped with fresh garnishes.", "servings": 8, "prepTime": 30, "cookTime": 150, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"pork shoulder cut into 2-inch pieces\"}, {\"qty\": \"1 lb\", \"name\": \"pork ribs\"}, {\"qty\": \"8\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"1\", \"name\": \"white onion halved\"}, {\"qty\": \"6\", \"name\": \"garlic cloves\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1\", \"name\": \"large can (110 oz) hominy drained and rinsed\"}, {\"qty\": \"10 cups\", \"name\": \"water\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"shredded cabbage for serving\"}, {\"qty\": \"\", \"name\": \"thinly sliced radishes for serving\"}, {\"qty\": \"\", \"name\": \"diced white onion for serving\"}, {\"qty\": \"\", \"name\": \"dried oregano for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}, {\"qty\": \"\", \"name\": \"tostadas for serving\"}]", "instructions": "1. Place pork shoulder and ribs in a large stockpot with water, half the onion, 3 garlic cloves, and bay leaves. Bring to a boil, skim foam, then simmer for 1.5 hours. 2. Remove pork and set aside; strain and reserve the broth. 3. Toast dried chiles briefly, then soak in 2 cups hot reserved broth with remaining onion for 20 minutes until softened. 4. Blend soaked chiles, soaking broth, remaining garlic, and oregano until smooth. 5. Return strained broth to the pot, add rinsed hominy, and bring to a simmer. 6. Pour strained chile sauce into the broth, stir, and cook 30 minutes. 7. Shred the cooked pork, add back to the pot, season with salt, and serve in deep bowls with all garnishes on the side.", "tags": "pork, soup, hominy, Guerrero-style", "source": "https://www.mexicoinmykitchen.com/red-pozole-rojo/", "nutritionData": "{\"calories\": 380, \"protein\": 32.0, \"carbs\": 30.0, \"fat\": 14.0}"},
  {"name": "Pozole Verde", "category": "Mexican", "description": "One-pot green pozole with chicken, tomatillos, and pumpkin seeds in a vibrant herbal broth.", "servings": 6, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1 lb\", \"name\": \"tomatillos husked and quartered\"}, {\"qty\": \"1/2 cup\", \"name\": \"raw pumpkin seeds\"}, {\"qty\": \"2\", \"name\": \"poblano peppers stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1o peppers stemmed\"}, {\"qty\": \"1\", \"name\": \"white onion quartered\"}, {\"qty\": \"4\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro leaves and stems\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh epazote or dried\"}, {\"qty\": \"5 cups\", \"name\": \"chicken stock\"}, {\"qty\": \"1 can\", \"name\": \"(25 oz) hominy drained\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"diced avocado for serving\"}, {\"qty\": \"\", \"name\": \"sliced radishes for serving\"}, {\"qty\": \"\", \"name\": \"shredded cabbage for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}, {\"qty\": \"\", \"name\": \"dried oregano for serving\"}]", "instructions": "1. Toast pumpkin seeds in the bottom of a large Dutch oven over medium-high heat until they pop, about 4 minutes, then transfer to a bowl. 2. Add chicken, tomatillos, onion, poblanos, jalapeños, chicken stock, oregano, epazote, and salt to the Dutch oven. Bring to a boil then simmer 40 minutes until chicken is tender. 3. Remove chicken and set aside to cool. Strain broth and transfer solids to a blender. 4. Add toasted pumpkin seeds and cilantro to the blender and blend until completely smooth. 5. Return strained broth to the pot over medium heat, whisk in the green puree, and add hominy. Bring to a simmer. 6. Shred chicken and stir back into the soup. Season with salt. 7. Ladle into bowls and serve with avocado, radishes, cabbage, and lime.", "tags": "chicken, soup, hominy, tomatillo", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 30.0, \"carbs\": 26.0, \"fat\": 12.0}"},
  {"name": "Chiles Rellenos", "category": "Mexican", "description": "Whole roasted poblano chiles stuffed with Oaxaca cheese, dipped in light egg batter, and simmered in tomato broth.", "servings": 4, "prepTime": 30, "cookTime": 40, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large poblano peppers\"}, {\"qty\": \"2 cups\", \"name\": \"shredded Oaxaca or Monterey Jack cheese\"}, {\"qty\": \"4\", \"name\": \"large eggs separated\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"1/4\", \"name\": \"white onion\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1 cup\", \"name\": \"chicken or vegetable broth\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"lard or neutral oil for frying\"}, {\"qty\": \"\", \"name\": \"wooden toothpicks\"}]", "instructions": "1. Blister poblano peppers directly over an open flame or under the broiler on all sides until charred, then place in a bowl, cover with foil, and steam for 10 minutes. 2. Peel off charred skin, make a vertical slit, and carefully remove seeds with a spoon, keeping pepper intact. 3. Stuff each pepper with shredded cheese and seal with a toothpick. Lightly dust in flour and place in freezer for 10 minutes. 4. Beat egg whites to stiff peaks, then fold in yolks one at a time to form a light batter. 5. Heat oil to 325°F. Dip stuffed peppers in egg batter and fry for 3-4 minutes per side until golden. Drain on paper towels. 6. Blend tomatoes, onion, and garlic; cook in 1 tbsp oil for 5 minutes; add broth, bay leaves, oregano, and salt and simmer 10 minutes. 7. Add fried chiles to the tomato broth and simmer gently for 20 minutes before serving.", "tags": "cheese, poblano, fried, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 420, \"protein\": 22.0, \"carbs\": 14.0, \"fat\": 30.0}"},
  {"name": "Tamales de Puerco (Red Chile Pork Tamales)", "category": "Mexican", "description": "Traditional masa-wrapped tamales filled with tender pork in red guajillo-chile sauce, steamed in corn husks.", "servings": 12, "prepTime": 90, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"30\", \"name\": \"dried corn husks\"}, {\"qty\": \"2 lb\", \"name\": \"pork shoulder\"}, {\"qty\": \"5\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"2\", \"name\": \"ancho chiles stemmed and seeded\"}, {\"qty\": \"3\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2\", \"name\": \"white onion\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"4 cups\", \"name\": \"masa harina\"}, {\"qty\": \"1 cup\", \"name\": \"well-packed lard\"}, {\"qty\": \"2.5 cups\", \"name\": \"warm chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt for masa\"}]", "instructions": "1. Soak corn husks in very hot water for 30 minutes until pliable. 2. Simmer pork in salted water with onion and garlic for 1.5 hours until tender, then shred and reserve broth. 3. Toast chiles, soak in hot water for 20 minutes, then blend with garlic, onion, cumin, and 1 cup pork broth until smooth. Strain. 4. Simmer strained chile sauce with shredded pork for 10 minutes. 5. Beat lard until fluffy, then mix in masa harina, baking powder, salt, and warm broth to form a soft spreadable dough. 6. Spread a thin layer of masa on the wide end of each husk, add a spoonful of pork filling, and fold the husk to enclose. Fold up the narrow end. 7. Steam upright in a steamer pot over boiling water for 50-60 minutes until masa pulls cleanly from the husk.", "tags": "pork, tamales, masa, steamed", "source": "https://www.mexicoinmykitchen.com/pork-tamales/", "nutritionData": "{\"calories\": 340, \"protein\": 18.0, \"carbs\": 36.0, \"fat\": 14.0}"},
  {"name": "Tamales de Pollo con Rajas (Chicken and Poblano Tamales)", "category": "Mexican", "description": "Light steamed masa tamales filled with shredded chicken and roasted poblano strips in a tangy salsa verde.", "servings": 12, "prepTime": 90, "cookTime": 60, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"30\", \"name\": \"dried corn husks\"}, {\"qty\": \"1.5 lb\", \"name\": \"boneless chicken thighs poached and shredded\"}, {\"qty\": \"3\", \"name\": \"poblano peppers roasted peeled and cut into strips\"}, {\"qty\": \"1 cup\", \"name\": \"salsa verde\"}, {\"qty\": \"4 cups\", \"name\": \"masa harina\"}, {\"qty\": \"1 cup\", \"name\": \"lard\"}, {\"qty\": \"2.5 cups\", \"name\": \"warm chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"\", \"name\": \"queso fresco for filling\"}]", "instructions": "1. Soak corn husks in hot water for 30 minutes until soft and pliable. 2. Mix shredded chicken with salsa verde and sliced roasted poblano strips; season with salt. 3. Beat lard in a stand mixer until fluffy, about 5 minutes. Gradually add masa harina, baking powder, salt, and warm broth, beating until a soft spreadable dough forms. Test readiness by dropping a small ball of dough in water; it should float. 4. Spread 2-3 tbsp masa dough onto the wide end of a soaked corn husk, leaving a 1-inch border. 5. Spoon chicken and poblano filling down the center. 6. Fold one side of the husk over the filling, then fold the other side over, and fold up the narrow bottom end. 7. Steam tamales upright in a steamer pot for 50-60 minutes, checking water level periodically.", "tags": "chicken, tamales, poblano, green-chile", "source": "Classic", "nutritionData": "{\"calories\": 310, \"protein\": 20.0, \"carbs\": 34.0, \"fat\": 11.0}"},
  {"name": "Chilaquiles Rojos", "category": "Mexican", "description": "Lightly fried tortilla chips simmered in smoky guajillo-tomato salsa roja and topped with eggs, crema, and cotija.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"corn tortillas cut into triangles\"}, {\"qty\": \"3\", \"name\": \"guajillo chiles stemmed and seeded\"}, {\"qty\": \"3\", \"name\": \"Roma tomatoes\"}, {\"qty\": \"1/4\", \"name\": \"white onion\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried Mexican oregano\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"Mexican crema\"}, {\"qty\": \"1/4 cup\", \"name\": \"crumbled cotija cheese\"}, {\"qty\": \"1/4\", \"name\": \"white onion thinly sliced\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}]", "instructions": "1. Toast guajillo chiles in a dry skillet for 30 seconds per side, soak in hot water for 10 minutes, then blend with tomatoes, onion, garlic, oregano, and broth until smooth. Strain. 2. Heat 1 tbsp oil in a large skillet over medium-high heat, add strained sauce, and simmer for 8 minutes until reduced and deep in color. 3. Meanwhile, fry tortilla triangles in remaining oil at 350°F until lightly crispy but not hard, about 2 minutes. Drain. 4. Add fried tortilla chips to the sauce and gently stir to coat. Cook for 2-3 minutes; chips should soften slightly but retain some texture. 5. In a separate pan fry eggs sunny-side up. 6. Divide chilaquiles between plates and top with fried eggs. 7. Drizzle with crema, sprinkle with cotija and sliced onion, and garnish with cilantro.", "tags": "breakfast, tortillas, salsa-roja, quick", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 22.0, \"carbs\": 52.0, \"fat\": 26.0}"},
  {"name": "Chilaquiles Verdes", "category": "Mexican", "description": "Crispy tortilla chips bathed in bright tomatillo-chipotle salsa verde with chorizo and sunny-side up eggs.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"corn tortillas cut into sixths\"}, {\"qty\": \"\", \"name\": \"4-5 tomatillos husked and rinsed\"}, {\"qty\": \"2\", \"name\": \"chipotle chiles in adobo\"}, {\"qty\": \"1/2\", \"name\": \"white onion divided\"}, {\"qty\": \"2\", \"name\": \"garlic cloves\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1\", \"name\": \"chorizo link\"}, {\"qty\": \"\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Roast tomatillos in a 350°F oven for 15-20 minutes until army green in color. 2. Blend roasted tomatillos with chipotle chiles, half the onion, and garlic until smooth. 3. Toss tortilla triangles in a thin layer of olive oil on a sheet pan and bake at 350°F for 13 minutes until lightly golden. 4. Cook chorizo in the oven or a skillet until cooked through. 5. Heat a dollop of oil in a skillet over medium heat, add tomatillo sauce, and cook for a few minutes until bubbly. 6. Fry eggs sunny-side up in a separate pan. 7. Add baked tortilla chips to the sauce, stir quickly to coat, plate immediately with fried eggs, cilantro, and chorizo on the side.", "tags": "breakfast, tomatillo, chipotle, eggs", "source": "https://www.mexicanplease.com/chilaquiles-tomatillo-chipotle-salsa/", "nutritionData": "{\"calories\": 490, \"protein\": 24.0, \"carbs\": 48.0, \"fat\": 24.0}"},
  {"name": "Huevos Rancheros", "category": "Mexican", "description": "Fried corn tortillas topped with refried beans and sunny-side up eggs smothered in a spicy ranch-style tomato salsa.", "servings": 2, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"corn tortillas\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"3\", \"name\": \"Roma tomatoes roughly chopped\"}, {\"qty\": \"1\", \"name\": \"serrano chile roughly chopped\"}, {\"qty\": \"1/4\", \"name\": \"white onion\"}, {\"qty\": \"1\", \"name\": \"garlic clove\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 cup\", \"name\": \"refried pinto beans\"}, {\"qty\": \"1/2 cup\", \"name\": \"cooking oil\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for garnish\"}, {\"qty\": \"\", \"name\": \"queso fresco for serving\"}]", "instructions": "1. Blend tomatoes, serrano, onion, garlic, and thyme with 2 tbsp water until smooth. 2. Heat 1 tbsp oil in a saucepan over medium-high heat, pour in blended sauce, and simmer for 10 minutes until thick and deep red. Season with salt. 3. Heat 1/4 cup oil in a medium skillet over medium heat and fry tortillas one at a time for about 20 seconds per side until just softened. Drain on paper towels. 4. In the same oil, fry eggs sunny-side up until whites are set and yolks remain runny. 5. Spread a generous spoonful of warm refried beans over each tortilla. 6. Place 2 fried tortillas on each plate and gently lay one fried egg on each tortilla. 7. Spoon warm salsa ranchera over the eggs and garnish with cilantro and crumbled queso fresco.", "tags": "breakfast, eggs, salsa, classic", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 22.0, \"carbs\": 36.0, \"fat\": 28.0}"},
  {"name": "Tacos de Camarón (Grilled Shrimp Tacos)", "category": "Mexican", "description": "Juicy chipotle-marinated grilled shrimp in corn tortillas with avocado crema and cabbage slaw.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"2\", \"name\": \"chipotle peppers in adobo sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1\", \"name\": \"ripe avocado\"}, {\"qty\": \"1/2 cup\", \"name\": \"Mexican crema or sour cream\"}, {\"qty\": \"1\", \"name\": \"lime juiced\"}, {\"qty\": \"2 cups\", \"name\": \"shredded green cabbage\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o thinly sliced\"}, {\"qty\": \"12\", \"name\": \"small corn tortillas\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for serving\"}]", "instructions": "1. Blend chipotle peppers, olive oil, garlic, cumin, paprika, and salt into a marinade. Toss shrimp with marinade and let sit for 15 minutes. 2. Make avocado crema by blending avocado, crema, and lime juice until smooth; season with salt. 3. Toss shredded cabbage with a squeeze of lime and a pinch of salt. 4. Grill or cook shrimp in a hot skillet over high heat for 2 minutes per side until pink, opaque, and lightly charred. 5. Warm corn tortillas on a dry comal or skillet. 6. Build tacos with 3-4 shrimp per tortilla. 7. Top with cabbage slaw, a drizzle of avocado crema, sliced jalapeño, and fresh cilantro.", "tags": "shrimp, tacos, grilled, coastal", "source": "Classic", "nutritionData": "{\"calories\": 370, \"protein\": 32.0, \"carbs\": 28.0, \"fat\": 15.0}"},
  {"name": "Tacos de Huevo con Chorizo (Breakfast Tacos)", "category": "Mexican", "description": "Scrambled eggs cooked with spicy Mexican chorizo and potato, served in warm corn tortillas for a hearty Mexican breakfast.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"6 oz\", \"name\": \"Mexican chorizo casing removed\"}, {\"qty\": \"1\", \"name\": \"medium potato diced small\"}, {\"qty\": \"1/4\", \"name\": \"white onion diced\"}, {\"qty\": \"1\", \"name\": \"serrano chile finely diced\"}, {\"qty\": \"1\", \"name\": \"Roma tomato diced\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"8\", \"name\": \"corn tortillas\"}, {\"qty\": \"\", \"name\": \"salsa roja for serving\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. Heat oil in a non-stick skillet over medium-high heat and cook diced potato for 8-10 minutes until golden and tender. Remove and set aside. 2. In the same skillet, cook chorizo over medium heat breaking up with a spoon for 5 minutes until browned and fat is rendered. 3. Add diced onion and serrano and cook for 2 minutes until softened. 4. Crack eggs directly into the pan and scramble together with the chorizo mixture over medium-low heat. 5. Fold in cooked potato and diced tomato and cook just until eggs are set but still slightly moist. 6. Warm tortillas wrapped in a damp towel in the microwave for 1 minute. 7. Fill tortillas with egg and chorizo mixture and serve with salsa roja, cilantro, and lime wedges.", "tags": "breakfast, eggs, chorizo, quick", "source": "Classic", "nutritionData": "{\"calories\": 390, \"protein\": 22.0, \"carbs\": 30.0, \"fat\": 20.0}"},
  {"name": "Tostadas de Tinga", "category": "Mexican", "description": "Crunchy fried tortilla rounds piled with chipotle chicken tinga, refried beans, lettuce, avocado, and cotija cheese.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"tostada shells (store-bought or homemade fried corn tortillas)\"}, {\"qty\": \"2 cups\", \"name\": \"chicken tinga (shredded chicken in chipotle-tomato sauce)\"}, {\"qty\": \"1 cup\", \"name\": \"refried pinto beans\"}, {\"qty\": \"2 cups\", \"name\": \"shredded romaine lettuce\"}, {\"qty\": \"1\", \"name\": \"ripe avocado sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled cotija cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"Mexican crema\"}, {\"qty\": \"\", \"name\": \"salsa verde for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. If making tostada shells from scratch, fry 6-inch corn tortillas in 1/4 inch of oil at 350°F for 1-2 minutes per side until completely crispy. Drain on paper towels. 2. Warm refried beans in a small saucepan over medium heat with a splash of water, stirring until smooth. 3. Warm chicken tinga in a skillet over medium heat until heated through. 4. Spread a generous spoonful of warm refried beans on each tostada shell. 5. Top with a portion of chicken tinga. 6. Layer with shredded lettuce and sliced avocado. 7. Finish with a drizzle of crema, crumbled cotija, salsa verde, and a squeeze of lime.", "tags": "chicken, tostadas, quick, assembly", "source": "Classic", "nutritionData": "{\"calories\": 440, \"protein\": 30.0, \"carbs\": 34.0, \"fat\": 20.0}"},
  {"name": "Sopes", "category": "Mexican", "description": "Thick handmade masa discs with pinched edges, lightly fried and loaded with refried beans, meat, crema, and salsa.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"masa harina\"}, {\"qty\": \"1.25 cups\", \"name\": \"warm water\"}, {\"qty\": \"4 tbsp\", \"name\": \"vegetable oil or lard\"}, {\"qty\": \"1 cup\", \"name\": \"refried beans\"}, {\"qty\": \"1.5 cups\", \"name\": \"cooked shredded beef or chicken\"}, {\"qty\": \"2 cups\", \"name\": \"shredded romaine lettuce\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled queso fresco\"}, {\"qty\": \"1/4 cup\", \"name\": \"white onion finely chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"Mexican crema\"}, {\"qty\": \"\", \"name\": \"salsa of choice for serving\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}]", "instructions": "1. Mix masa harina and warm water until a smooth dough forms, like play dough. Cover with a damp cloth and rest 5 minutes. 2. Divide into 8 equal balls and press each between plastic wrap to form a 4.5-inch round about 1/4-inch thick. 3. Cook on a hot ungreased comal over medium-high heat for 1 minute per side, flip once more for 20 seconds. 4. While still hot, pinch a 1/2-inch rim around the edge of each sope to create a wall for the toppings. 5. Heat oil in a skillet and lightly fry the sopes 30 seconds per side until light golden. 6. Spread warm refried beans over each sope. 7. Top with shredded meat, lettuce, queso fresco, diced onion, crema, and salsa.", "tags": "masa, antojito, street-food, versatile", "source": "https://www.mexicoinmykitchen.com/sopes-recipe/", "nutritionData": "{\"calories\": 450, \"protein\": 26.0, \"carbs\": 44.0, \"fat\": 18.0}"},
  {"name": "Flautas de Pollo", "category": "Mexican", "description": "Tightly rolled corn tortillas filled with spiced chicken and deep-fried until golden and crunchy, served with guacamole and salsa.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"corn tortillas\"}, {\"qty\": \"1.5 lb\", \"name\": \"boneless chicken thighs poached and shredded\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes diced\"}, {\"qty\": \"1/4\", \"name\": \"white onion finely diced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o finely diced\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying (about 2 cups)\"}, {\"qty\": \"2 cups\", \"name\": \"shredded romaine lettuce\"}, {\"qty\": \"1/2 cup\", \"name\": \"guacamole\"}, {\"qty\": \"1/2 cup\", \"name\": \"salsa verde\"}, {\"qty\": \"1/4 cup\", \"name\": \"Mexican crema\"}, {\"qty\": \"1/4 cup\", \"name\": \"crumbled cotija or queso fresco\"}, {\"qty\": \"\", \"name\": \"wooden toothpicks\"}]", "instructions": "1. Mix shredded chicken with diced tomatoes, onion, jalapeño, and salt. Cook in a skillet for 5 minutes to reduce moisture. 2. Warm corn tortillas in a damp paper towel in the microwave for 1-2 minutes until pliable. 3. Place a heaping spoonful of chicken filling on each tortilla, roll tightly, and secure with a toothpick along the seam. 4. Heat vegetable oil to 350°F in a deep skillet. 5. Fry flautas in batches of 3-4, cooking 1.5-2 minutes per side until deeply golden. Drain on paper towels and remove toothpicks. 6. Arrange on a platter over a bed of shredded lettuce. 7. Top with guacamole, salsa verde, a drizzle of crema, and crumbled cotija.", "tags": "chicken, fried, crispy, antojito", "source": "https://www.isabeleats.com/flautas/", "nutritionData": "{\"calories\": 510, \"protein\": 32.0, \"carbs\": 42.0, \"fat\": 22.0}"},
  {"name": "Elote (Mexican Street Corn)", "category": "Mexican", "description": "Grilled corn on the cob slathered in creamy mayo and crema, rolled in cotija cheese and dusted with chili powder.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"ears fresh corn husked\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"2 tbsp\", \"name\": \"Mexican crema or sour cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"finely crumbled cotija cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder or Taj\\u00edn\"}, {\"qty\": \"1\", \"name\": \"lime quartered\"}, {\"qty\": \"\", \"name\": \"fresh cilantro chopped for garnish\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Grill corn directly over medium-high heat, turning every 2-3 minutes for about 12 minutes until cooked and lightly charred in spots. 2. Alternatively, boil corn in salted water for 10 minutes then grill briefly for char. 3. Mix mayonnaise and Mexican crema together in a small bowl. 4. While corn is still hot, brush the creamy mixture all over each ear. 5. Roll or press each corn ear into crumbled cotija cheese to coat generously. 6. Dust with chili powder and a squeeze of fresh lime juice. 7. Garnish with chopped cilantro and serve immediately on a stick or as is.", "tags": "corn, street-food, vegetarian, grilled", "source": "Classic", "nutritionData": "{\"calories\": 260, \"protein\": 7.0, \"carbs\": 28.0, \"fat\": 14.0}"},
  {"name": "Esquites (Mexican Street Corn in a Cup)", "category": "Mexican", "description": "Off-the-cob version of elote featuring sautéed corn kernels in a cup with lime, mayo, chili, and cotija cheese.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"ears corn kernels cut from cob (about 4 cups)\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/4\", \"name\": \"white onion finely diced\"}, {\"qty\": \"1\", \"name\": \"serrano chile finely minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh epazote or cilantro\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"2 tbsp\", \"name\": \"Mexican crema\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled cotija cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder or Taj\\u00edn\"}, {\"qty\": \"2\", \"name\": \"limes cut into wedges\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Melt butter in a large skillet over high heat until slightly browned. 2. Add corn kernels in a single layer and cook undisturbed for 3-4 minutes until kernels begin to char on one side. 3. Add diced onion and serrano and stir, cooking another 2 minutes. 4. Add epazote or cilantro and toss to combine. Season with salt. 5. Divide corn mixture into cups or bowls. 6. Top each serving with a tablespoon of mayo, a drizzle of crema, and a big squeeze of lime. 7. Sprinkle generously with cotija and chili powder and serve immediately.", "tags": "corn, street-food, vegetarian, quick", "source": "Classic", "nutritionData": "{\"calories\": 240, \"protein\": 6.0, \"carbs\": 26.0, \"fat\": 13.0}"},
  {"name": "Salsa Verde", "category": "Mexican", "description": "Bright roasted tomatillo salsa with serrano chile, onion, garlic, and cilantro — the essential Mexican green table sauce.", "servings": 8, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"4-5 medium tomatillos husked and rinsed\"}, {\"qty\": \"1\", \"name\": \"serrano or jalape\\u00f1o pepper\"}, {\"qty\": \"1/2\", \"name\": \"small white onion\"}, {\"qty\": \"1\", \"name\": \"garlic clove peeled\"}, {\"qty\": \"\", \"name\": \"10-12 fresh cilantro sprigs\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Remove stems from tomatillos and place on a baking sheet. 2. Roast tomatillos in a 400°F oven for 15-20 minutes until they start to wrinkle and turn army green in color. 3. Add roasted tomatillos to a blender. 4. Add onion, garlic, cilantro, and 1/4 of the serrano pepper to the blender. 5. Pulse blend and taste for heat level; add more serrano incrementally until the desired spice is reached. 6. Salt to taste. 7. Serve immediately or store in an airtight container in the refrigerator for up to 3 days.", "tags": "sauce, tomatillo, condiment, vegan", "source": "https://www.mexicanplease.com/tomatillo-serrano-sauce-salsa-verde-step-by-step/", "nutritionData": "{\"calories\": 20, \"protein\": 1.0, \"carbs\": 4.0, \"fat\": 0.0}"},
  {"name": "Pico de Gallo", "category": "Mexican", "description": "Fresh uncooked salsa of ripe tomatoes, white onion, jalapeño, lime juice, and cilantro — the classic Mexican fresh salsa.", "servings": 6, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"medium ripe Roma tomatoes seeded and finely diced\"}, {\"qty\": \"1/2\", \"name\": \"white onion finely diced\"}, {\"qty\": \"\", \"name\": \"1-2 jalape\\u00f1o peppers seeded and minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro leaves roughly chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}]", "instructions": "1. Dice tomatoes and place in a fine mesh strainer for 5 minutes to drain excess juice. 2. Finely dice the white onion and mince the jalapeño, adjusting seeds for desired heat level. 3. Combine drained tomatoes, onion, and jalapeño in a medium bowl. 4. Add chopped cilantro and pour in lime juice. 5. Season with salt and stir gently to combine. 6. Let rest for at least 5 minutes to allow flavors to meld. 7. Taste and adjust lime juice and salt as needed before serving.", "tags": "salsa, fresh, vegan, condiment", "source": "Classic", "nutritionData": "{\"calories\": 20, \"protein\": 1.0, \"carbs\": 5.0, \"fat\": 0.0}"},
  {"name": "Guacamole", "category": "Mexican", "description": "Classic hand-mashed avocado dip with lime, jalapeño, white onion, cilantro, and tomato — made to order in a molcajete.", "servings": 4, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"ripe Hass avocados\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4\", \"name\": \"white onion finely minced\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o seeded and minced\"}, {\"qty\": \"1\", \"name\": \"small Roma tomato seeded and diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh cilantro leaves roughly chopped\"}, {\"qty\": \"1\", \"name\": \"small garlic clove minced (optional)\"}]", "instructions": "1. Halve and pit avocados, then scoop flesh into a molcajete or large bowl. 2. Add lime juice and salt and mash with a pestle or fork to your desired texture — chunky is preferred. 3. Fold in minced onion, jalapeño, and garlic if using. 4. Add diced tomato and cilantro and stir gently to combine. 5. Taste and adjust salt and lime juice as needed. 6. If not serving immediately, press plastic wrap directly onto the surface to prevent browning. 7. Serve at room temperature with tortilla chips or alongside tacos.", "tags": "avocado, dip, vegan, condiment", "source": "Classic", "nutritionData": "{\"calories\": 160, \"protein\": 2.0, \"carbs\": 9.0, \"fat\": 15.0}"},
  {"name": "Frijoles Refritos (Refried Beans)", "category": "Mexican", "description": "Authentic pinto beans cooked from scratch and mashed with lard, garlic, and jalapeño into a creamy, deeply savory side dish.", "servings": 6, "prepTime": 10, "cookTime": 120, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried pinto beans rinsed and picked over\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion divided\"}, {\"qty\": \"5\", \"name\": \"garlic cloves divided\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"1 tsp\", \"name\": \"dried Mexican oregano divided\"}, {\"qty\": \"3 tsp\", \"name\": \"kosher salt divided\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil or lard\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o finely diced\"}, {\"qty\": \"\", \"name\": \"water as needed\"}, {\"qty\": \"\", \"name\": \"cotija cheese for serving\"}, {\"qty\": \"\", \"name\": \"lime juice for serving\"}]", "instructions": "1. Combine beans, half the onion, 2 smashed garlic cloves, bay leaf, 1/2 tsp oregano, and 1.5 tsp salt in a large pot with enough water to cover by 3 inches. 2. Bring to a boil, reduce heat to low, cover, and simmer for 1.5-2 hours until beans are completely soft. Reserve cooking liquid and discard bay leaf. 3. Finely dice remaining onion half and 3 garlic cloves. 4. Heat oil or lard in the same pot over medium-high heat and add diced onion, garlic, jalapeño, remaining oregano, and salt. Cook 5 minutes until softened. 5. Add cooked beans and stir for 2 minutes. Add 3/4 cup reserved cooking liquid. 6. Mash beans with a potato masher for chunky texture or use an immersion blender for smooth, adding more liquid as needed. 7. Taste and adjust salt; serve topped with cotija cheese and a squeeze of lime.", "tags": "beans, side-dish, vegetarian, classic", "source": "https://www.isabeleats.com/authentic-mexican-refried-beans/", "nutritionData": "{\"calories\": 220, \"protein\": 11.0, \"carbs\": 34.0, \"fat\": 5.0}"},
  {"name": "Kung Pao Chicken", "category": "Asian", "description": "Sichuan stir-fry with tender chicken, dried chilies, peanuts, and a bold sweet-spicy-tangy sauce.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"boneless skinless chicken thighs cut into 3/4-inch cubes\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Shaoxing wine\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"8\", \"name\": \"dried Sichuan chilies\"}, {\"qty\": \"1 tsp\", \"name\": \"Sichuan peppercorns\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"3\", \"name\": \"stalks scallions cut into 1-inch pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry-roasted peanuts\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"hoisin sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}]", "instructions": "1. Toss chicken with 1 tbsp soy sauce, Shaoxing wine, and cornstarch; marinate 15 minutes. 2. Mix sauce: remaining soy sauce, rice vinegar, hoisin, sugar, and sesame oil in a small bowl. 3. Heat wok over high heat until smoking; add oil and stir-fry chilies and peppercorns 30 seconds. 4. Add chicken and stir-fry 3-4 minutes until cooked through; remove from wok. 5. Add garlic and ginger; stir-fry 30 seconds. 6. Return chicken to wok; pour in sauce and toss to coat. 7. Add scallions and peanuts; toss for 30 seconds and serve over rice.", "tags": "spicy, Chinese, stir-fry, high-protein", "source": "https://www.seriouseats.com/recipes/2014/07/takeout-style-kung-pao-chicken-diced-chicken-peppers-peanuts-recipe.html", "nutritionData": "{\"calories\": 717, \"protein\": 53.0, \"carbs\": 49.0, \"fat\": 33.0}"},
  {"name": "General Tso's Chicken", "category": "Asian", "description": "Crispy fried chicken tossed in a glossy sweet-spicy-savory sauce, a Chinese-American takeout classic.", "servings": 4, "prepTime": 25, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"boneless skinless chicken thighs cut into 2-inch pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"Shaoxing wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"cornstarch\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"3 cups\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"4\", \"name\": \"dried red chilies\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"chicken stock\"}, {\"qty\": \"2 tbsp\", \"name\": \"white vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cornstarch mixed with 1 tbsp water\"}]", "instructions": "1. Marinate chicken with soy sauce, Shaoxing wine, and baking soda for 20 minutes. 2. Mix cornstarch and flour; coat chicken pieces evenly and shake off excess. 3. Heat oil to 350°F and fry chicken in batches 3-4 minutes until golden; drain on paper towels. 4. Combine sauce ingredients: soy sauce, stock, vinegar, sugar, sesame oil in a bowl. 5. In a clean wok heat 1 tbsp oil; fry chilies, garlic, and ginger 30 seconds. 6. Add sauce and bring to simmer; add cornstarch slurry and stir to thicken. 7. Toss fried chicken in sauce and serve immediately with rice.", "tags": "Chinese-American, crispy, takeout, sweet-spicy", "source": "https://www.recipetineats.com/general-tsos-chicken/", "nutritionData": "{\"calories\": 539, \"protein\": 47.0, \"carbs\": 34.0, \"fat\": 22.0}"},
  {"name": "Mapo Tofu", "category": "Asian", "description": "Silky tofu simmered in a fiery Sichuan sauce of doubanjiang, ground pork, and numbing peppercorns.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"14 oz\", \"name\": \"firm tofu cut into 3/4-inch cubes\"}, {\"qty\": \"6 oz\", \"name\": \"ground pork\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"doubanjiang (chili bean paste)\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger minced\"}, {\"qty\": \"1 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"Shaoxing wine\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch mixed with 2 tbsp water\"}, {\"qty\": \"1 tsp\", \"name\": \"ground Sichuan peppercorns\"}, {\"qty\": \"2\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}]", "instructions": "1. Bring salted water to boil; gently simmer tofu cubes 3 minutes and drain. 2. Heat oil in wok over medium-high; add pork and cook until browned, breaking into small pieces. 3. Add doubanjiang and stir-fry 1-2 minutes until darkened and fragrant. 4. Add garlic and ginger; stir-fry 30 seconds. 5. Pour in stock, soy sauce, wine, and sugar; bring to a gentle boil. 6. Slide tofu in carefully; simmer 3-4 minutes to absorb flavors. 7. Stir in cornstarch slurry and cook until sauce thickens. 8. Drizzle with sesame oil, sprinkle Sichuan peppercorn powder and scallions; serve over rice.", "tags": "Sichuan, spicy, tofu, numbing", "source": "Classic", "nutritionData": "{\"calories\": 326, \"protein\": 25.0, \"carbs\": 9.0, \"fat\": 23.0}"},
  {"name": "Char Siu", "category": "Asian", "description": "Cantonese honey-glazed BBQ pork marinated overnight in a fragrant five-spice and hoisin sauce.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"pork shoulder cut into 1-inch thick strips\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic salt\"}, {\"qty\": \"4 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"light soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"hoisin sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Shaoxing wine\"}, {\"qty\": \"1\", \"name\": \"cube red fermented bean curd\"}, {\"qty\": \"1 tsp\", \"name\": \"five spice powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tsp\", \"name\": \"water\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red food coloring optional\"}]", "instructions": "1. Pierce pork strips all over with a fork; combine garlic salt, brown sugar, oyster sauce, soy sauce, hoisin, Shaoxing wine, mashed red bean curd, and five spice into a marinade. 2. Coat pork in marinade and refrigerate overnight or at least 8 hours. 3. Preheat oven to 425°F; line a baking pan with foil and set a rack on top. 4. Lay pork on rack and add 2 tbsp water to pan bottom. 5. Roast 15 minutes; baste with reserved marinade, flip and baste; roast another 15 minutes. 6. Mix honey with 2 tsp water for glaze; baste pork and roast 10 more minutes at 450°F. 7. Rest 5 minutes before slicing; serve with rice or use in fried rice.", "tags": "Chinese, BBQ, pork, make-ahead", "source": "https://www.madewithlau.com/recipes/char-siu-chinese-bbq-pork", "nutritionData": "{\"calories\": 432, \"protein\": 26.0, \"carbs\": 12.0, \"fat\": 31.0}"},
  {"name": "Chinese Potstickers", "category": "Asian", "description": "Pan-fried dumplings with a pork and cabbage filling, crispy on the bottom and tender on top.", "servings": 4, "prepTime": 45, "cookTime": 15, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3/4 cup\", \"name\": \"boiling water\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1 cup\", \"name\": \"napa cabbage finely chopped and salted\"}, {\"qty\": \"2\", \"name\": \"scallions finely chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"water for steaming\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce for dipping\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar for dipping\"}, {\"qty\": \"1 tsp\", \"name\": \"chili oil for dipping\"}]", "instructions": "1. Mix flour with boiling water; knead into smooth dough and rest covered 30 minutes. 2. Salt cabbage, let sit 10 minutes, then squeeze out excess liquid; mix with pork, scallions, soy sauce, sesame oil, ginger, sugar, and white pepper. 3. Roll dough into a log; cut into 24 pieces and roll each into a 3-inch round. 4. Place 1 tsp filling in center; fold and pleat edges to seal. 5. Heat oil in a nonstick skillet over medium-high; arrange dumplings flat-side down and cook 2 minutes until golden. 6. Add 1/2 cup water and cover; steam 6-7 minutes until water evaporates. 7. Uncover and cook another minute until bottoms are crispy; serve with dipping sauce.", "tags": "Chinese, dumplings, pan-fried, pork", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 24.0, \"carbs\": 46.0, \"fat\": 22.0}"},
  {"name": "Yangzhou Fried Rice", "category": "Asian", "description": "Classic Chinese fried rice with shrimp, char siu pork, eggs, and vegetables tossed over high heat.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"day-old cooked jasmine rice\"}, {\"qty\": \"4 oz\", \"name\": \"shrimp peeled and halved\"}, {\"qty\": \"5 oz\", \"name\": \"char siu pork diced\"}, {\"qty\": \"2 oz\", \"name\": \"frozen peas\"}, {\"qty\": \"2 oz\", \"name\": \"carrots diced\"}, {\"qty\": \"3\", \"name\": \"large eggs beaten with pinch of salt\"}, {\"qty\": \"2\", \"name\": \"scallions separated into white and green parts\"}, {\"qty\": \"3 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"light soy sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"white pepper\"}]", "instructions": "1. Blanch carrots and peas 40 seconds; cook shrimp in same water 3 minutes; drain and set aside. 2. Heat wok to high heat until smoking; add 1 tbsp oil. 3. Pour in eggs and immediately add rice; stir-fry vigorously 2-3 minutes until eggs coat the grains. 4. Season with salt and soy sauce; push rice to sides and add char siu to center; cook 1 minute. 5. Mix char siu into rice; add shrimp, peas, and carrots; stir-fry on high 2 minutes. 6. Add remaining oil and scallion greens; toss to combine and serve immediately.", "tags": "Chinese, fried rice, seafood, pork", "source": "https://www.madewithlau.com/recipes/yangzhou-fried-rice", "nutritionData": "{\"calories\": 505, \"protein\": 25.0, \"carbs\": 62.0, \"fat\": 17.0}"},
  {"name": "Dan Dan Noodles", "category": "Asian", "description": "Sichuan spicy noodles topped with seasoned pork mince in a sesame-chili sauce with preserved mustard greens.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"Chinese wheat noodles\"}, {\"qty\": \"6 oz\", \"name\": \"ground pork\"}, {\"qty\": \"2 tbsp\", \"name\": \"hoisin sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"Shaoxing wine\"}, {\"qty\": \"1/4 tsp\", \"name\": \"five spice\"}, {\"qty\": \"4 tbsp\", \"name\": \"sesame paste (tahini)\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1 tsp\", \"name\": \"ground Sichuan peppercorns\"}, {\"qty\": \"2 oz\", \"name\": \"sui mi ya cai (preserved mustard greens)\"}, {\"qty\": \"2\", \"name\": \"scallions chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"roasted peanuts crushed\"}]", "instructions": "1. Make the sauce: whisk together sesame paste, chili oil, soy sauce, rice vinegar, sugar, chicken stock, and Sichuan peppercorn; divide among 4 bowls. 2. Cook pork with hoisin, soy sauce, wine, and five spice until browned; set aside. 3. Warm preserved mustard greens briefly in pan; set aside. 4. Cook noodles per package directions; blanch any greens in last minute and drain. 5. Divide noodles among bowls over the sauce. 6. Top with pork, preserved mustard greens, scallions, and crushed peanuts. 7. Toss everything together before eating.", "tags": "Sichuan, spicy, noodles, pork", "source": "https://www.recipetineats.com/dan-dan-noodles-spicy-sichuan-noodles/", "nutritionData": "{\"calories\": 650, \"protein\": 27.0, \"carbs\": 72.0, \"fat\": 28.0}"},
  {"name": "Pad See Ew", "category": "Asian", "description": "Thai stir-fried wide rice noodles with Chinese broccoli, egg, and a sweet dark soy sauce.", "servings": 2, "prepTime": 15, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"wide fresh rice noodles (chow fun)\"}, {\"qty\": \"4 oz\", \"name\": \"chicken breast thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"2\", \"name\": \"stalks Chinese broccoli cut into 2-inch pieces\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"dark soy sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/8 tsp\", \"name\": \"white pepper\"}]", "instructions": "1. Marinate chicken with soy sauce and sugar 10 minutes. 2. Separate noodles into individual strands; if refrigerated warm briefly in microwave. 3. Mix sauce: oyster sauce, soy sauce, dark soy sauce, and sugar. 4. Heat wok on high until smoking; add oil and fry garlic 15 seconds. 5. Add chicken; stir-fry until just cooked through; push to the side and crack in egg. 6. Scramble egg until 70% set then mix with chicken. 7. Add noodles and sauce; toss to coat and spread noodles out to sear and get wok char. 8. Add Chinese broccoli; toss briefly until stems are tender-crisp; season with white pepper and serve.", "tags": "Thai, noodles, stir-fry, quick", "source": "https://hot-thai-kitchen.com/pad-see-ew-new/", "nutritionData": "{\"calories\": 611, \"protein\": 55.0, \"carbs\": 58.0, \"fat\": 15.0}"},
  {"name": "Pad Krapow Gai", "category": "Asian", "description": "Thai street-food classic of ground chicken stir-fried with holy basil, chilies, and a savory sauce, topped with a fried egg.", "servings": 2, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"10.5 oz\", \"name\": \"ground chicken\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic\"}, {\"qty\": \"3\", \"name\": \"Thai chilies\"}, {\"qty\": \"1/4\", \"name\": \"medium onion diced\"}, {\"qty\": \"1 cup\", \"name\": \"holy basil leaves loosely packed\"}, {\"qty\": \"1 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dark soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"water\"}, {\"qty\": \"1.5 tsp\", \"name\": \"sugar\"}, {\"qty\": \"2\", \"name\": \"eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"\", \"name\": \"jasmine rice for serving\"}]", "instructions": "1. Pound Thai chilies to a paste in mortar; add garlic and pound to a rough paste. 2. Combine oyster sauce, soy sauce, fish sauce, dark soy sauce, water, and sugar; stir until dissolved. 3. Heat 1 tbsp oil in a wok over medium-high; fry chili-garlic paste until garlic is golden, 1-2 minutes. 4. Add onion and cook 30 seconds. 5. Add ground chicken and toss until no longer pink. 6. Pour in sauce; toss until chicken is coated; turn off heat and stir in holy basil to wilt. 7. In separate pan heat 2 tbsp oil; fry eggs with very hot oil until edges are crispy. 8. Serve stir-fry over jasmine rice topped with a fried egg.", "tags": "Thai, quick, spicy, street-food", "source": "https://hot-thai-kitchen.com/pad-kra-pao-anything/", "nutritionData": "{\"calories\": 530, \"protein\": 38.0, \"carbs\": 42.0, \"fat\": 22.0}"},
  {"name": "Thai Red Curry", "category": "Asian", "description": "Creamy coconut milk curry with tender chicken and vegetables in a vibrant Thai red curry paste.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"boneless chicken thighs cut into pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"red curry paste\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) full-fat coconut milk\"}, {\"qty\": \"1 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"1\", \"name\": \"zucchini sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"palm sugar or brown sugar\"}, {\"qty\": \"4\", \"name\": \"kaffir lime leaves torn\"}, {\"qty\": \"1\", \"name\": \"stalk lemongrass bruised\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 cup\", \"name\": \"Thai basil leaves\"}, {\"qty\": \"\", \"name\": \"jasmine rice for serving\"}]", "instructions": "1. Heat oil in a large wok or pot over medium-high; fry curry paste 1-2 minutes until fragrant. 2. Add half the coconut milk and stir to combine; cook 3-4 minutes until oil separates. 3. Add chicken and stir to coat; cook until mostly done, 5-6 minutes. 4. Pour in remaining coconut milk, stock, lemongrass, and kaffir lime leaves. 5. Add fish sauce and sugar; simmer 10 minutes. 6. Add bell pepper and zucchini; simmer 5 more minutes until tender. 7. Stir in Thai basil; taste and adjust seasoning; serve over jasmine rice.", "tags": "Thai, curry, coconut milk, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 545, \"protein\": 38.0, \"carbs\": 26.0, \"fat\": 32.0}"},
  {"name": "Massaman Curry", "category": "Asian", "description": "Rich Thai curry with tender braised beef, potatoes, and peanuts in a warming massaman paste and coconut milk.", "servings": 4, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"beef chuck cut into 2-inch pieces\"}, {\"qty\": \"3 tbsp\", \"name\": \"massaman curry paste\"}, {\"qty\": \"2 cans\", \"name\": \"(14 oz each) full-fat coconut milk\"}, {\"qty\": \"2\", \"name\": \"medium potatoes peeled and cubed\"}, {\"qty\": \"1\", \"name\": \"medium onion cut into wedges\"}, {\"qty\": \"1/3 cup\", \"name\": \"dry-roasted peanuts\"}, {\"qty\": \"2 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"palm sugar or brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"tamarind paste\"}, {\"qty\": \"3\", \"name\": \"kaffir lime leaves\"}, {\"qty\": \"2\", \"name\": \"cardamom pods\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}]", "instructions": "1. Heat 1/4 cup coconut milk in a pot over medium heat; add curry paste and fry 2 minutes until fragrant. 2. Add beef and stir to coat in paste; cook 5 minutes, browning lightly. 3. Add remaining coconut milk, cardamom, cinnamon, bay leaves, and kaffir lime leaves; bring to simmer. 4. Cover and braise on low heat 40 minutes until beef is nearly tender. 5. Add potatoes and onion; cook 15 more minutes until potatoes are cooked through. 6. Stir in fish sauce, palm sugar, tamarind paste, and peanuts. 7. Simmer uncovered 5 minutes; adjust seasoning and serve with jasmine rice.", "tags": "Thai, curry, braised, coconut milk", "source": "Classic", "nutritionData": "{\"calories\": 580, \"protein\": 38.0, \"carbs\": 28.0, \"fat\": 38.0}"},
  {"name": "Goi Cuon", "category": "Asian", "description": "Fresh Vietnamese spring rolls filled with pork belly, shrimp, rice vermicelli, and herbs, served with peanut sauce.", "servings": 4, "prepTime": 40, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"pork belly\"}, {\"qty\": \"1/2 lb\", \"name\": \"medium shrimp peeled and deveined\"}, {\"qty\": \"4 oz\", \"name\": \"rice vermicelli noodles\"}, {\"qty\": \"8\", \"name\": \"rice paper sheets\"}, {\"qty\": \"1\", \"name\": \"head butter lettuce leaves separated\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh mint leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1\", \"name\": \"cucumber julienned\"}, {\"qty\": \"4 tbsp\", \"name\": \"hoisin sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"peanut butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"crushed roasted peanuts\"}]", "instructions": "1. Simmer pork belly in water with salt and onion 25-30 minutes until cooked; cool and slice thin. 2. Boil shrimp in salted water 2 minutes; drain, cool, peel, and halve lengthwise. 3. Cook rice vermicelli per package directions; rinse in cold water and drain. 4. Make peanut sauce: sauté garlic in oil 30 seconds; add hoisin, peanut butter, and water; simmer until thick. 5. Dip rice paper in warm water 4-6 seconds; lay on plate. 6. Layer lettuce, herbs, noodles, and pork belly on bottom third; roll halfway. 7. Place 3 shrimp halves pink-side down; fold in sides and roll tightly. 8. Serve immediately with peanut sauce topped with crushed peanuts.", "tags": "Vietnamese, fresh, no-cook, seafood", "source": "Classic", "nutritionData": "{\"calories\": 415, \"protein\": 26.0, \"carbs\": 38.0, \"fat\": 16.0}"},
  {"name": "Bun Cha", "category": "Asian", "description": "Hanoi-style grilled pork patties and belly served in a light sweet-savory broth with rice noodles and herbs.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1/2 lb\", \"name\": \"pork belly thinly sliced\"}, {\"qty\": \"3\", \"name\": \"shallots minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"8 oz\", \"name\": \"rice vermicelli noodles cooked\"}, {\"qty\": \"3 tbsp\", \"name\": \"fish sauce for broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"sugar for broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1/2 cup\", \"name\": \"hot water\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"Thai chili sliced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh herbs (mint basil cilantro)\"}, {\"qty\": \"1 cup\", \"name\": \"bean sprouts\"}]", "instructions": "1. Mix ground pork with shallots, fish sauce, sugar, pepper, and baking soda; form into 12 patties. 2. Marinate pork belly slices in fish sauce, sugar, and shallots 15 minutes. 3. Make broth: dissolve sugar in hot water; add fish sauce, vinegar, garlic, and chili. 4. Grill or pan-fry pork patties over medium-high heat 3-4 minutes per side until caramelized. 5. Grill pork belly slices 2 minutes per side. 6. Place grilled meats in broth to serve. 7. Serve with rice vermicelli, fresh herbs, and bean sprouts alongside; dip noodles into broth.", "tags": "Vietnamese, grilled, pork, Hanoi", "source": "Classic", "nutritionData": "{\"calories\": 545, \"protein\": 35.0, \"carbs\": 48.0, \"fat\": 22.0}"},
  {"name": "Chicken Teriyaki", "category": "Asian", "description": "Juicy chicken thighs glazed in a homemade teriyaki sauce of soy, mirin, and sake, grilled to perfection.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"boneless skin-on chicken thighs\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"2 tbsp\", \"name\": \"sake\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"\", \"name\": \"steamed Japanese rice for serving\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}, {\"qty\": \"2\", \"name\": \"scallions thinly sliced for garnish\"}]", "instructions": "1. Mix soy sauce, mirin, sake, and sugar in a small bowl to make teriyaki sauce. 2. Pat chicken dry; season lightly with salt and pepper. 3. Heat oil in a skillet over medium-high; lay chicken skin-side down and cook 5-6 minutes until skin is golden. 4. Flip and cook 4-5 more minutes until cooked through. 5. Pour in teriyaki sauce and simmer, turning chicken to glaze, until sauce thickens and coats the chicken, 2-3 minutes. 6. Slice chicken and serve over steamed rice; garnish with scallions and sesame seeds.", "tags": "Japanese, glazed, quick, gluten-free-adaptable", "source": "Classic", "nutritionData": "{\"calories\": 572, \"protein\": 48.0, \"carbs\": 43.0, \"fat\": 21.0}"},
  {"name": "Gyudon", "category": "Asian", "description": "Japanese beef rice bowl with thinly sliced ribeye and onion simmered in a savory-sweet dashi broth.", "servings": 2, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"thinly sliced beef ribeye\"}, {\"qty\": \"1/2\", \"name\": \"medium onion thinly sliced\"}, {\"qty\": \"1/2 cup\", \"name\": \"dashi stock\"}, {\"qty\": \"2 tbsp\", \"name\": \"sake\"}, {\"qty\": \"2 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"2 cups\", \"name\": \"cooked Japanese short-grain rice\"}, {\"qty\": \"1\", \"name\": \"green onion thinly sliced\"}, {\"qty\": \"\", \"name\": \"pickled red ginger (beni shoga) for serving\"}]", "instructions": "1. In a cold frying pan combine dashi, sake, mirin, soy sauce, and sugar; stir to dissolve sugar. 2. Spread onion slices in the broth; separate beef slices and layer on top of onions. 3. Cover and turn heat to medium; bring to a simmer and cook 3-4 minutes. 4. Skim any scum that rises to the surface. 5. Sprinkle green onions on top; cook covered another minute. 6. Divide rice into bowls; drizzle with pan sauce; top with beef and onion mixture. 7. Garnish with pickled red ginger and serve immediately.", "tags": "Japanese, donburi, quick, beef", "source": "https://www.justonecookbook.com/gyudon/", "nutritionData": "{\"calories\": 650, \"protein\": 38.0, \"carbs\": 62.0, \"fat\": 24.0}"},
  {"name": "Katsudon", "category": "Asian", "description": "Japanese pork cutlet rice bowl with a soft egg and onion simmered in a dashi-soy sauce.", "servings": 2, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"pork loin chops (6 oz each) pounded thin\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/2\", \"name\": \"medium onion sliced\"}, {\"qty\": \"3/4 cup\", \"name\": \"dashi stock\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"3 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"3\", \"name\": \"eggs for topping\"}, {\"qty\": \"2 cups\", \"name\": \"cooked Japanese rice\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"\", \"name\": \"salt and white pepper\"}]", "instructions": "1. Season pork with salt and pepper; dredge in flour, dip in beaten egg, then coat in panko. 2. Heat 1 inch of oil to 350°F and fry pork cutlets 3-4 minutes per side until golden; drain and rest before cutting. 3. In a small skillet simmer onion in dashi, soy sauce, mirin, and sugar 3-4 minutes until softened. 4. Slice katsu into strips; lay over the onion mixture. 5. Beat 3 eggs and pour over the cutlet; cover and cook on medium-low until eggs are just set, 1-2 minutes. 6. Slide over a bowl of steamed rice and serve immediately.", "tags": "Japanese, donburi, pork, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 720, \"protein\": 42.0, \"carbs\": 68.0, \"fat\": 28.0}"},
  {"name": "Okonomiyaki", "category": "Asian", "description": "Japanese savory cabbage pancake with pork belly, topped with okonomiyaki sauce, mayo, and bonito flakes.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"green cabbage finely shredded\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"dashi stock\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"4 oz\", \"name\": \"pork belly thinly sliced\"}, {\"qty\": \"2\", \"name\": \"scallions chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"okonomiyaki sauce (or Worcestershire mixed with ketchup)\"}, {\"qty\": \"2 tbsp\", \"name\": \"Japanese mayonnaise\"}, {\"qty\": \"1/4 cup\", \"name\": \"bonito flakes (katsuobushi)\"}, {\"qty\": \"1 tsp\", \"name\": \"aonori seaweed flakes\"}]", "instructions": "1. Whisk flour and dashi until smooth; beat in eggs until combined. 2. Fold in shredded cabbage and scallions to make a thick batter. 3. Heat oil in a nonstick skillet over medium; pour in half the batter and shape into a round pancake. 4. Lay pork belly slices on top; press gently into batter. 5. Cook 4-5 minutes until the underside is set and golden. 6. Flip carefully and cook the pork side 4-5 minutes until cooked through and caramelized. 7. Flip once more; transfer to plate and drizzle with okonomiyaki sauce and mayo; top with bonito flakes and aonori.", "tags": "Japanese, savory pancake, pork, quick", "source": "https://www.justonecookbook.com/okonomiyaki/", "nutritionData": "{\"calories\": 519, \"protein\": 21.0, \"carbs\": 39.0, \"fat\": 30.0}"},
  {"name": "Tonkatsu", "category": "Asian", "description": "Japanese breaded and deep-fried pork cutlet served with tangy tonkatsu sauce and shredded cabbage.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"pork loin chops (6 oz each) pounded to 1/2-inch thickness\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1.5 cups\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 cups\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"\", \"name\": \"salt and white pepper\"}, {\"qty\": \"2 cups\", \"name\": \"green cabbage shredded\"}, {\"qty\": \"4 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"ketchup\"}, {\"qty\": \"1 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"steamed Japanese rice for serving\"}]", "instructions": "1. Mix Worcestershire, ketchup, oyster sauce, soy sauce, and sugar for tonkatsu sauce; set aside. 2. Pat pork dry; make small cuts along fat cap to prevent curling; season with salt and white pepper. 3. Dredge in flour, shake off excess; dip in beaten egg; press into panko on all sides. 4. Heat oil to 340-350°F; fry pork 4-5 minutes per side until deep golden brown and cooked through. 5. Drain on a wire rack 2 minutes then slice into strips. 6. Serve over rice with shredded cabbage; drizzle tonkatsu sauce over cutlet.", "tags": "Japanese, deep-fried, pork, crispy", "source": "https://www.justonecookbook.com/tonkatsu/", "nutritionData": "{\"calories\": 640, \"protein\": 38.0, \"carbs\": 52.0, \"fat\": 28.0}"},
  {"name": "Japanese Curry Rice", "category": "Asian", "description": "Mild and comforting Japanese curry with chicken, potatoes, and carrots in a rich roux-based sauce.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless chicken thighs cut into 1-inch pieces\"}, {\"qty\": \"2\", \"name\": \"medium potatoes peeled and cubed\"}, {\"qty\": \"2\", \"name\": \"medium carrots cut into chunks\"}, {\"qty\": \"1\", \"name\": \"large onion cut into wedges\"}, {\"qty\": \"3.5 cups\", \"name\": \"water or chicken stock\"}, {\"qty\": \"3.5 oz\", \"name\": \"Japanese curry roux (1/2 block such as S&B or Vermont)\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"\", \"name\": \"steamed Japanese rice for serving\"}]", "instructions": "1. Heat oil in a large pot over medium-high; brown chicken in batches and remove. 2. Sauté onions until translucent, about 5 minutes. 3. Return chicken; add carrots and potatoes and stir to coat. 4. Pour in water or stock and bring to a boil; skim off foam. 5. Reduce heat and simmer 20 minutes until vegetables are tender. 6. Remove from heat and break curry roux blocks into the pot; stir until fully dissolved. 7. Return to low heat; add soy sauce and simmer 5 minutes, stirring until sauce thickens. 8. Serve over steamed rice.", "tags": "Japanese, curry, mild, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 545, \"protein\": 37.0, \"carbs\": 61.0, \"fat\": 16.0}"},
  {"name": "Miso-Glazed Eggplant", "category": "Asian", "description": "Silky Japanese eggplant broiled with a sweet miso glaze until caramelized and deeply savory.", "servings": 2, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large Japanese eggplants\"}, {\"qty\": \"2 tbsp\", \"name\": \"white miso (shiro miso)\"}, {\"qty\": \"2 tbsp\", \"name\": \"mirin\"}, {\"qty\": \"1 tbsp\", \"name\": \"sake\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame seeds\"}, {\"qty\": \"1\", \"name\": \"scallion thinly sliced\"}]", "instructions": "1. Preheat broiler to high and line a baking sheet with foil. 2. Halve eggplants lengthwise; score the flesh in a crosshatch pattern and brush with vegetable oil. 3. Broil eggplant cut-side up 8-10 minutes until softened and lightly charred. 4. Mix miso, mirin, sake, and sugar until smooth. 5. Spread miso glaze generously over eggplant cut surfaces. 6. Broil another 3-5 minutes until glaze is caramelized and bubbly. 7. Drizzle with sesame oil; garnish with sesame seeds and scallions; serve immediately.", "tags": "Japanese, vegetarian, vegan-adaptable, quick", "source": "https://www.justonecookbook.com/miso-glazed-eggplant/", "nutritionData": "{\"calories\": 218, \"protein\": 9.0, \"carbs\": 17.0, \"fat\": 12.0}"},
  {"name": "Bibimbap", "category": "Asian", "description": "Korean mixed rice bowl with seasoned vegetables, beef, a fried egg, and gochujang sauce.", "servings": 4, "prepTime": 40, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"cooked short-grain rice\"}, {\"qty\": \"6 oz\", \"name\": \"ground beef\"}, {\"qty\": \"2 cups\", \"name\": \"spinach blanched and seasoned\"}, {\"qty\": \"1 cup\", \"name\": \"bean sprouts blanched and seasoned\"}, {\"qty\": \"1 cup\", \"name\": \"shredded carrots saut\\u00e9ed\"}, {\"qty\": \"1\", \"name\": \"zucchini julienned and saut\\u00e9ed\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"gochujang\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"water\"}, {\"qty\": \"2 tsp\", \"name\": \"sesame seeds\"}]", "instructions": "1. Cook each vegetable (spinach, bean sprouts, carrots, zucchini) separately in oil with a pinch of salt and garlic; season with sesame oil. 2. Cook beef with soy sauce, sesame oil, sugar, and garlic until browned. 3. Mix gochujang sauce: gochujang, sesame oil, sugar, and water. 4. Fry eggs sunny-side up in a nonstick pan. 5. Divide rice into 4 bowls. 6. Arrange vegetables, beef, and a fried egg on top of rice. 7. Drizzle with gochujang sauce and sesame seeds; mix everything together before eating.", "tags": "Korean, rice bowl, balanced, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 554, \"protein\": 26.0, \"carbs\": 70.0, \"fat\": 19.0}"},
  {"name": "Japchae", "category": "Asian", "description": "Korean glass noodle stir-fry with sweet potato noodles, colorful vegetables, beef, and sesame seasoning.", "servings": 4, "prepTime": 50, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"sweet potato starch noodles (dangmyeon) soaked 40 minutes\"}, {\"qty\": \"4 oz\", \"name\": \"beef filet minced sliced thin\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1\", \"name\": \"medium onion sliced\"}, {\"qty\": \"1\", \"name\": \"medium carrot cut into matchsticks\"}, {\"qty\": \"1/2\", \"name\": \"red bell pepper sliced\"}, {\"qty\": \"4 oz\", \"name\": \"spinach blanched and squeezed\"}, {\"qty\": \"4\", \"name\": \"dried shiitake mushrooms soaked and sliced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame seeds\"}, {\"qty\": \"1\", \"name\": \"egg for garnish\"}]", "instructions": "1. Marinate beef with soy sauce, sesame oil, and garlic; cook in pan until done; set aside. 2. Sauté onion, carrot, bell pepper, and mushrooms separately with pinches of salt; set aside. 3. Season spinach with soy sauce and sesame oil. 4. Boil noodles per package directions until chewy; drain and cut with scissors into 5-inch lengths. 5. Toss noodles with 2 tsp sesame oil and 1 tsp soy sauce to prevent sticking. 6. Combine all ingredients in a large bowl with soy sauce, sugar, sesame oil, garlic, and black pepper. 7. Mix well by hand; top with egg garnish strips and sesame seeds; serve warm or at room temperature.", "tags": "Korean, noodles, festive, gluten-free", "source": "https://www.maangchi.com/recipe/japchae", "nutritionData": "{\"calories\": 395, \"protein\": 13.0, \"carbs\": 63.0, \"fat\": 11.0}"},
  {"name": "Kimchijeon", "category": "Asian", "description": "Crispy and tangy Korean kimchi pancake made with well-fermented kimchi and scallions.", "servings": 2, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"well-fermented napa cabbage kimchi chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"kimchi brine\"}, {\"qty\": \"3\", \"name\": \"scallions chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"4 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce for dipping\"}, {\"qty\": \"1 tsp\", \"name\": \"rice vinegar for dipping\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sesame oil for dipping\"}, {\"qty\": \"1/2 tsp\", \"name\": \"gochugaru for dipping\"}]", "instructions": "1. Combine kimchi, kimchi brine, scallions, sugar, flour, and water in a bowl; mix until a batter forms. 2. Heat a 12-inch nonstick skillet over medium heat; add 2 tbsp oil and swirl to coat. 3. Pour in batter and spread into a large circle with the back of a spoon. 4. Cook until bottom is golden brown and crisp, 3-5 minutes. 5. Drizzle remaining 2 tbsp oil around edges; carefully flip the pancake. 6. Cook until other side is golden brown and crisp, 3-5 minutes. 7. Flip once more and cook 1 more minute; slide onto a platter and serve with dipping sauce.", "tags": "Korean, pancake, kimchi, vegetarian", "source": "https://www.maangchi.com/recipe/kimchijeon", "nutritionData": "{\"calories\": 390, \"protein\": 8.0, \"carbs\": 48.0, \"fat\": 18.0}"},
  {"name": "Tteokbokki", "category": "Asian", "description": "Chewy Korean rice cakes simmered in a spicy gochujang-anchovy broth with fish cakes and scallions.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"cylindrical rice cakes (tteok)\"}, {\"qty\": \"4 cups\", \"name\": \"water\"}, {\"qty\": \"7\", \"name\": \"dried anchovies\"}, {\"qty\": \"1\", \"name\": \"piece dried kelp (dasima) 4x4 inches\"}, {\"qty\": \"3 tbsp\", \"name\": \"gochujang\"}, {\"qty\": \"1 tbsp\", \"name\": \"gochugaru (red pepper flakes)\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"2\", \"name\": \"fish cake sheets cut into triangles\"}, {\"qty\": \"3\", \"name\": \"scallions cut into 2-inch pieces\"}, {\"qty\": \"2\", \"name\": \"hard-boiled eggs halved\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}]", "instructions": "1. Boil water with anchovies and kelp over medium-high 15 minutes; remove and discard. 2. Mix gochujang, gochugaru, sugar, and soy sauce in a small bowl. 3. Add rice cakes and fish cakes to the anchovy broth and bring to a boil. 4. Stir in the spicy sauce mixture. 5. Cook stirring gently until rice cakes soften and the sauce thickens and looks shiny, 10-15 minutes; add water if needed. 6. Add scallions and hard-boiled eggs; stir gently and cook 1-2 more minutes. 7. Remove from heat and serve hot.", "tags": "Korean, spicy, rice cakes, street-food", "source": "https://www.maangchi.com/recipe/tteokbokki", "nutritionData": "{\"calories\": 343, \"protein\": 11.0, \"carbs\": 64.0, \"fat\": 5.0}"},
  {"name": "Sweet and Sour Pork", "category": "Asian", "description": "Twice-fried crispy pork tossed with vibrant bell peppers and pineapple in a glossy sweet and sour sauce.", "servings": 4, "prepTime": 25, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"pork shoulder cut into 1-inch pieces\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"light soy sauce\"}, {\"qty\": \"1\", \"name\": \"egg beaten\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"3 cups\", \"name\": \"corn oil for frying\"}, {\"qty\": \"1\", \"name\": \"red bell pepper cut into chunks\"}, {\"qty\": \"1\", \"name\": \"green bell pepper cut into chunks\"}, {\"qty\": \"1/2 cup\", \"name\": \"pineapple chunks\"}, {\"qty\": \"1/3 cup\", \"name\": \"sugar\"}, {\"qty\": \"1/3 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"3 tbsp\", \"name\": \"ketchup\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch mixed with 2 tbsp water\"}]", "instructions": "1. Marinate pork with garlic salt, soy sauce, and beaten egg 20 minutes. 2. Coat pork in flour then cornstarch; fry at 325°F 7-8 minutes until cooked through; drain. 3. Heat oil to 400°F and fry pork again 1-2 minutes for extra crispiness. 4. Make sauce: combine sugar, vinegar, ketchup, soy sauce, oyster sauce, and water in a pan and bring to simmer. 5. Stir-fry bell peppers and pineapple in a clean wok 1-2 minutes. 6. Add sauce and cornstarch slurry; simmer until thickened, 1-2 minutes. 7. Toss in fried pork quickly; serve immediately over rice.", "tags": "Chinese, crispy, sweet-sour, pork", "source": "https://www.madewithlau.com/recipes/sweet-sour-pork", "nutritionData": "{\"calories\": 479, \"protein\": 22.0, \"carbs\": 38.0, \"fat\": 26.0}"},
  {"name": "Pancit Canton", "category": "Asian", "description": "Filipino stir-fried egg noodles with pork, shrimp, and vegetables in a soy-oyster sauce.", "servings": 6, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"Canton egg noodles\"}, {\"qty\": \"1/2 lb\", \"name\": \"pork belly sliced thin\"}, {\"qty\": \"1/2 lb\", \"name\": \"shrimp peeled and deveined\"}, {\"qty\": \"2 cups\", \"name\": \"cabbage shredded\"}, {\"qty\": \"2\", \"name\": \"carrots julienned\"}, {\"qty\": \"1 cup\", \"name\": \"snow peas trimmed\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"medium onion sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"fish sauce\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"calamansi or lemon wedges for serving\"}]", "instructions": "1. Heat oil in a large wok over medium-high; sauté garlic and onion until soft. 2. Add pork and cook until browned; add shrimp and cook 2 minutes until pink. 3. Add carrots and cook 2 minutes; add cabbage and snow peas and stir-fry 2 more minutes. 4. Push vegetables to the side and add chicken broth, soy sauce, oyster sauce, and fish sauce to the center. 5. Add noodles and toss to coat; cook 3-5 minutes until noodles are tender, adding more broth if needed. 6. Mix everything together; season with black pepper. 7. Serve with calamansi or lemon wedges squeezed over top.", "tags": "Filipino, noodles, stir-fry, celebration", "source": "Classic", "nutritionData": "{\"calories\": 515, \"protein\": 32.0, \"carbs\": 48.0, \"fat\": 18.0}"},
  {"name": "Lumpia Shanghai", "category": "Asian", "description": "Crispy Filipino fried spring rolls filled with seasoned ground pork and vegetables, served with sweet chili sauce.", "servings": 6, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1/2 cup\", \"name\": \"carrots finely diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"water chestnuts finely diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"onion minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"20\", \"name\": \"lumpia wrappers (or spring roll wrappers)\"}, {\"qty\": \"3 cups\", \"name\": \"vegetable oil for deep frying\"}, {\"qty\": \"\", \"name\": \"sweet chili sauce for serving\"}]", "instructions": "1. Mix ground pork, carrots, water chestnuts, garlic, onion, soy sauce, sesame oil, and black pepper until combined. 2. Beat egg and set aside. 3. Place 2 tbsp filling along one edge of a lumpia wrapper; roll tightly halfway, fold in sides, and roll completely; seal edge with beaten egg. 4. Heat oil to 350°F in a deep pan. 5. Fry lumpia in batches 3-4 minutes per side until golden brown and crispy; do not crowd the pan. 6. Drain on paper towels. 7. Serve hot with sweet chili sauce.", "tags": "Filipino, deep-fried, pork, party-food", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 18.0, \"carbs\": 22.0, \"fat\": 20.0}"},
  {"name": "Palak Paneer", "category": "Asian", "description": "Indian cottage cheese cubes in a vibrant spinach sauce spiced with garam masala and aromatic spices.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"14 oz\", \"name\": \"paneer cut into 1-inch cubes\"}, {\"qty\": \"1 lb\", \"name\": \"fresh spinach washed\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger grated\"}, {\"qty\": \"1\", \"name\": \"green chili chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"ghee or oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tsp\", \"name\": \"dried fenugreek leaves (kasuri methi)\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Blanch spinach in boiling salted water 2 minutes; drain and blend to a smooth puree. 2. Pan-fry paneer cubes in 1 tbsp ghee until golden on two sides; remove and set aside. 3. In same pan heat remaining ghee; fry cumin seeds until they sputter. 4. Add onion and cook until golden, 8-10 minutes; add garlic, ginger, and green chili; cook 2 minutes. 5. Add tomatoes, turmeric, and cayenne; cook 8-10 minutes until oil separates. 6. Stir in spinach puree; add garam masala and kasuri methi; simmer 5 minutes. 7. Fold in paneer and cream; simmer 3 more minutes; serve with naan or rice.", "tags": "Indian, vegetarian, spinach, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 432, \"protein\": 16.0, \"carbs\": 10.0, \"fat\": 35.0}"},
  {"name": "Dal Makhani", "category": "Asian", "description": "Slow-cooked black lentils and kidney beans in a rich buttery tomato cream sauce, a Punjabi classic.", "servings": 6, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"whole black urad lentils\"}, {\"qty\": \"1/4 cup\", \"name\": \"kidney beans (rajma)\"}, {\"qty\": \"1\", \"name\": \"medium onion finely chopped\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) crushed tomatoes\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger grated\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"cilantro for garnish\"}]", "instructions": "1. Soak lentils and kidney beans overnight; drain and rinse. 2. Pressure cook with 3.5 cups water for 18-20 whistles (or Instant Pot high pressure 30 minutes) until very soft. 3. Heat butter and oil in a pan; fry cumin seeds until they pop. 4. Add onion and cook until light golden, 10 minutes; add garlic and ginger and cook 2 minutes. 5. Add crushed tomatoes, chili powder, and turmeric; cook 10-15 minutes until oil separates. 6. Add cooked lentils and 1 cup water; stir to combine; simmer on low 30-45 minutes stirring every 10 minutes. 7. Stir in cream and garam masala; simmer 5 more minutes; garnish with cilantro and serve with naan.", "tags": "Indian, lentils, slow-cooked, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 380, \"protein\": 18.0, \"carbs\": 44.0, \"fat\": 14.0}"},
  {"name": "Beef Rendang", "category": "Asian", "description": "Malaysian slow-braised beef in a rich coconut and spice paste that reduces until the meat is tender and caramelized.", "servings": 6, "prepTime": 30, "cookTime": 120, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"beef chuck cut into 2-inch cubes\"}, {\"qty\": \"2 cans\", \"name\": \"(14 oz each) coconut milk\"}, {\"qty\": \"4\", \"name\": \"dried red chilies soaked and drained\"}, {\"qty\": \"5\", \"name\": \"shallots peeled\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1\", \"name\": \"inch galangal peeled\"}, {\"qty\": \"1\", \"name\": \"inch ginger peeled\"}, {\"qty\": \"2\", \"name\": \"stalks lemongrass bruised\"}, {\"qty\": \"3\", \"name\": \"kaffir lime leaves torn\"}, {\"qty\": \"1\", \"name\": \"turmeric leaf tied in a knot\"}, {\"qty\": \"1 tbsp\", \"name\": \"palm sugar or brown sugar\"}, {\"qty\": \"1.5 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"toasted shredded coconut (kerisik) optional\"}]", "instructions": "1. Blend chilies, shallots, garlic, galangal, and ginger to a fine paste. 2. Heat oil in a heavy pot over high; sear beef in batches until browned; remove. 3. Reduce heat to medium; fry spice paste 3-4 minutes until darkened and fragrant. 4. Return beef; add coconut milk, lemongrass, kaffir lime leaves, turmeric leaf, sugar, and salt. 5. Bring to a simmer then reduce heat to low; cover and cook 75 minutes until beef is tender. 6. Uncover and increase heat to medium; stir frequently and cook 30-40 minutes until sauce reduces to a thick paste that coats the beef and meat begins to brown. 7. Stir in kerisik if using; taste and adjust seasoning; serve with steamed rice.", "tags": "Malaysian, braised, coconut, slow-cooked", "source": "https://www.recipetineats.com/beef-rendang/", "nutritionData": "{\"calories\": 702, \"protein\": 42.0, \"carbs\": 6.0, \"fat\": 59.0}"},
  {"name": "Matzo Ball Soup", "category": "Jewish", "description": "Classic Ashkenazi chicken broth with fluffy, tender matzo balls simmered to perfection.", "servings": 6, "prepTime": 30, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken (3-4 lbs)\"}, {\"qty\": \"3\", \"name\": \"large carrots peeled and sliced\"}, {\"qty\": \"3\", \"name\": \"stalks celery sliced\"}, {\"qty\": \"1\", \"name\": \"large onion quartered\"}, {\"qty\": \"1\", \"name\": \"bunch fresh dill\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 cup\", \"name\": \"matzo meal\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"schmaltz or vegetable oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}]", "instructions": "1. Place chicken in a large stockpot, cover with 5 quarts water, bring to a boil and skim foam. 2. Add carrots, celery, onion, dill, salt, and pepper; simmer covered for 90 minutes until chicken is cooked through. 3. Strain broth, reserving vegetables and picking chicken meat from bones; discard skin and bones. 4. For matzo balls, whisk eggs with schmaltz in a bowl; stir in matzo meal, baking powder, and salt until combined. 5. Refrigerate matzo ball mixture for 30 minutes to firm up. 6. Bring a large pot of salted water to a boil; with wet hands form mixture into golf-ball-sized balls and drop into boiling water. 7. Reduce heat to a gentle simmer, cover, and cook matzo balls for 30 minutes until puffed and cooked through. 8. Add matzo balls and reserved chicken meat to the warm broth and serve garnished with fresh dill.", "tags": "ashkenazi, passover, shabbat, comfort-food", "source": "https://toriavey.com/perfect-chicken-soup/", "nutritionData": "{\"calories\": 320, \"protein\": 26.0, \"carbs\": 18.0, \"fat\": 14.0}"},
  {"name": "Slow-Braised Brisket", "category": "Jewish", "description": "Tender beef brisket braised low and slow with caramelized onions, garlic, and rich savory sauce.", "servings": 8, "prepTime": 20, "cookTime": 240, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"beef brisket first cut\"}, {\"qty\": \"3\", \"name\": \"large onions sliced\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 cups\", \"name\": \"beef stock\"}, {\"qty\": \"1 cup\", \"name\": \"ketchup\"}, {\"qty\": \"1 cup\", \"name\": \"chili sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"brown sugar\"}]", "instructions": "1. Preheat oven to 350°F. 2. Season brisket generously with paprika, garlic powder, onion powder, salt, and pepper on all sides. 3. Heat oil in a large Dutch oven over medium-high heat; sear brisket 4-5 minutes per side until deeply browned; remove and set aside. 4. Sauté onions in the same pot over medium heat for 15 minutes until caramelized; add garlic and cook 2 minutes more. 5. Whisk together beef stock, ketchup, chili sauce, and brown sugar; pour over onions. 6. Return brisket to pot, spoon sauce over top, cover tightly with foil and lid. 7. Braise in oven for 3 to 3.5 hours until very tender when pierced with a fork. 8. Cool, refrigerate overnight, slice against the grain, and reheat covered in sauce before serving.", "tags": "ashkenazi, passover, rosh-hashanah, shabbat, make-ahead", "source": "https://smittenkitchen.com/2010/04/tangy-spiced-brisket/", "nutritionData": "{\"calories\": 460, \"protein\": 38.0, \"carbs\": 22.0, \"fat\": 22.0}"},
  {"name": "Potato Latkes", "category": "Jewish", "description": "Crispy golden shredded potato pancakes fried until crunchy outside and tender inside for Hanukkah.", "servings": 6, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"russet potatoes peeled\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"3 tbsp\", \"name\": \"matzo meal or all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}, {\"qty\": \"\", \"name\": \"Sour cream and applesauce for serving\"}]", "instructions": "1. Grate potatoes using a food processor or box grater; transfer to a large bowl of cold water for 5 minutes. 2. Grate onion using the same grater and set aside. 3. Drain potatoes in a colander, then wrap in a clean kitchen towel and squeeze firmly to remove as much liquid as possible. 4. In a large bowl, combine dry potatoes, grated onion, beaten eggs, matzo meal, salt, and pepper; stir to combine. 5. Pour oil into a large skillet to a depth of 1/4 inch and heat over medium to 365°F. 6. Working in batches, scoop about 3 tablespoons of mixture per latke, flatten into a disk, and carefully place in hot oil. 7. Fry 2-3 minutes per side until deeply golden and crispy; do not crowd the pan. 8. Drain on a wire rack and serve immediately with sour cream and applesauce.", "tags": "ashkenazi, hanukkah, fried, gluten-free-option", "source": "https://toriavey.com/potato-latkes/", "nutritionData": "{\"calories\": 280, \"protein\": 5.0, \"carbs\": 30.0, \"fat\": 15.0}"},
  {"name": "Sweet Lokshen Kugel", "category": "Jewish", "description": "Creamy baked noodle pudding with eggs, cream cheese, and cinnamon, a beloved Ashkenazi Shabbat side.", "servings": 12, "prepTime": 15, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"wide egg noodles\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"1 lb\", \"name\": \"sour cream\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"8 oz\", \"name\": \"cottage cheese\"}, {\"qty\": \"1 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"raisins\"}, {\"qty\": \"2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar for topping\"}]", "instructions": "1. Preheat oven to 350°F; grease a 9x13 inch baking dish. 2. Cook egg noodles according to package directions until just tender; drain and return to pot. 3. In a blender or food processor, blend eggs, sour cream, cream cheese, cottage cheese, sugar, melted butter, and salt until smooth. 4. Soak raisins in hot water for 5 minutes, then drain. 5. Pour the cream cheese mixture over the noodles and stir to combine; fold in drained raisins. 6. Pour mixture into prepared baking dish. 7. Sprinkle top generously with cinnamon and sugar mixture. 8. Bake for 60 minutes until center is set and noodle tips are golden brown; let rest 15 minutes before slicing.", "tags": "ashkenazi, shabbat, dairy, make-ahead", "source": "https://toriavey.com/sweet-lokshen-kugel/", "nutritionData": "{\"calories\": 420, \"protein\": 10.0, \"carbs\": 48.0, \"fat\": 20.0}"},
  {"name": "Challah", "category": "Jewish", "description": "Beautifully braided, golden egg bread with a glossy crust, the iconic Shabbat and holiday loaf.", "servings": 16, "prepTime": 40, "cookTime": 35, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"1/3 cup\", \"name\": \"honey\"}, {\"qty\": \"1/3 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"large eggs plus 1 egg yolk\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"1\", \"name\": \"egg white for egg wash\"}, {\"qty\": \"\", \"name\": \"Sesame or poppy seeds for topping\"}]", "instructions": "1. Dissolve yeast in warm water with 1 tsp honey; let stand 5 minutes until foamy. 2. Combine flour, salt, remaining honey, oil, and 2 eggs in the bowl of a stand mixer; add yeast mixture and knead with dough hook on medium for 8-10 minutes until smooth and elastic. 3. Place dough in an oiled bowl, cover with plastic wrap, and let rise at room temperature 2 hours until puffy. 4. Gently deflate dough and divide into 6 equal pieces; roll each into a 20-inch rope. 5. Braid into two 3-strand loaves or one 6-strand braid; place on a parchment-lined baking sheet. 6. Cover with greased plastic wrap and let rise 60-90 minutes until very puffy. 7. Preheat oven to 375°F; brush loaves with egg white wash and sprinkle with seeds. 8. Bake 25-30 minutes until deep golden brown and internal temperature reads 190°F; cool on a rack.", "tags": "ashkenazi, shabbat, rosh-hashanah, bread", "source": "https://www.kingarthurbaking.com/recipes/classic-challah-recipe", "nutritionData": "{\"calories\": 195, \"protein\": 5.0, \"carbs\": 29.0, \"fat\": 7.0}"},
  {"name": "Rugelach", "category": "Jewish", "description": "Flaky cream cheese pastry rolled with jam, cinnamon, walnuts, and chocolate into tender crescent cookies.", "servings": 24, "prepTime": 30, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fine sea salt\"}, {\"qty\": \"1/2 lb\", \"name\": \"unsalted butter cold\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese cold\"}, {\"qty\": \"1/2 cup\", \"name\": \"raspberry jam\"}, {\"qty\": \"2/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 1/2 tbsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/3 cup\", \"name\": \"walnuts toasted and finely chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"mini chocolate chips\"}, {\"qty\": \"1\", \"name\": \"egg beaten with 1 tsp water for egg wash\"}]", "instructions": "1. Pulse flour and salt in a food processor; add cream cheese in chunks and process until dispersed; add butter in chunks and pulse until dough clumps together. 2. Divide dough into 4 portions, wrap each in plastic, and refrigerate at least 2 hours or up to 3 days. 3. Preheat oven to 350°F; line baking sheets with parchment. 4. Stir together sugar and cinnamon in a small bowl; combine walnuts and chocolate chips in another. 5. Roll each dough quarter into a 12x8 inch rectangle on a floured surface; spread thinly with 2-3 tbsp jam; sprinkle with 2 tbsp cinnamon-sugar and 4 tbsp nut-chocolate mixture. 6. Roll dough from the 12-inch side into a tight log; freeze 10-15 minutes. 7. Slice logs into 10-12 pieces per log; place on baking sheets. 8. Brush tops with egg wash, sprinkle with remaining cinnamon-sugar, and bake 20-25 minutes until golden brown; cool on racks.", "tags": "ashkenazi, hanukkah, purim, dairy, cookies", "source": "https://smittenkitchen.com/2015/12/unfussy-rugelach/", "nutritionData": "{\"calories\": 185, \"protein\": 3.0, \"carbs\": 16.0, \"fat\": 12.0}"},
  {"name": "Hamantaschen", "category": "Jewish", "description": "Triangular butter cookies filled with jam or poppy seed paste, baked for the Purim holiday.", "servings": 22, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"3 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 tsp\", \"name\": \"orange zest\"}, {\"qty\": \"1 1/3 cups\", \"name\": \"plus 4 tsp all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"fruit jam or prepared poppy seed filling\"}]", "instructions": "1. Cream butter and cream cheese until smooth; add sugar and beat 1 minute; mix in egg, vanilla, orange zest, and salt. 2. Add flour and mix until dough just comes together; it should be slightly sticky. 3. Form dough into a disc, wrap in plastic, and refrigerate at least 1 hour. 4. Preheat oven to 350°F; line baking sheets with parchment. 5. Roll dough on a floured surface to 1/4-inch thick; cut into 2.5-inch circles. 6. Place 1 teaspoon of filling in the center of each circle; fold three sides up and crimp corners firmly into a triangle, leaving filling slightly visible. 7. Place on prepared baking sheets 2 inches apart. 8. Bake 18-20 minutes until the cookies are golden brown; cool on baking sheet for 2 minutes then transfer to a rack.", "tags": "ashkenazi, purim, cookies, dairy", "source": "https://smittenkitchen.com/2008/03/hamantaschen/", "nutritionData": "{\"calories\": 95, \"protein\": 2.0, \"carbs\": 11.0, \"fat\": 5.0}"},
  {"name": "Chocolate Babka", "category": "Jewish", "description": "Buttery, yeasted loaf swirled with rich chocolate filling and brushed with simple syrup for Shabbat.", "servings": 12, "prepTime": 45, "cookTime": 30, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 1/4 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"2 tsp\", \"name\": \"lemon zest\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"warm water\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"10 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter for filling\"}, {\"qty\": \"4 oz\", \"name\": \"semisweet chocolate chopped\"}, {\"qty\": \"1/2 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"cocoa powder\"}, {\"qty\": \"1/4 cup\", \"name\": \"sugar and 1/4 cup water for syrup\"}]", "instructions": "1. Combine flour, sugar, yeast, and zest; add eggs and water, mix with dough hook until it comes together; add salt then softened butter a spoonful at a time. 2. Knead on medium 10 minutes until smooth; refrigerate dough overnight in an oiled bowl covered with plastic. 3. Make filling: melt butter and chocolate together; stir in powdered sugar and cocoa to form a spreadable paste. 4. Butter and parchment two 9x4-inch loaf pans; take half the dough from fridge and roll to a 10x12-inch rectangle. 5. Spread half the chocolate filling over dough leaving a 1/2-inch border; roll tightly into a log; freeze 15 minutes for easier cutting. 6. Cut log in half lengthwise; twist the two halves together with cut sides facing up; place in prepared loaf pan. 7. Repeat with remaining dough; cover loaves and let rise at room temperature 1-1.5 hours. 8. Bake at 375°F for 30 minutes until golden; immediately brush with sugar syrup made by simmering sugar and water together; cool in pan 20 minutes then transfer to a rack.", "tags": "ashkenazi, shabbat, dairy, bread, chocolate", "source": "https://smittenkitchen.com/2014/10/better-chocolate-babka/", "nutritionData": "{\"calories\": 380, \"protein\": 6.0, \"carbs\": 47.0, \"fat\": 19.0}"},
  {"name": "Cholent", "category": "Jewish", "description": "Hearty overnight Shabbat stew of beef, beans, barley, and potatoes slow-cooked for 12 or more hours.", "servings": 8, "prepTime": 20, "cookTime": 720, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"beef brisket or stew meat cut into chunks\"}, {\"qty\": \"2\", \"name\": \"marrow bones\"}, {\"qty\": \"1 cup\", \"name\": \"dried mixed beans soaked overnight\"}, {\"qty\": \"1/2 cup\", \"name\": \"pearl barley\"}, {\"qty\": \"2.5 lbs\", \"name\": \"large red potatoes peeled and halved\"}, {\"qty\": \"2\", \"name\": \"whole onions chopped\"}, {\"qty\": \"3\", \"name\": \"garlic cloves whole\"}, {\"qty\": \"6\", \"name\": \"eggs in shells optional\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1\", \"name\": \"quart low-sodium chicken broth\"}]", "instructions": "1. Layer potatoes on the bottom of a large slow cooker; add onions on top. 2. Place beef chunks in a single layer over the onions; add marrow bones and whole garlic cloves. 3. Rinse beans and barley; sprinkle over the meat; tuck eggs in shells into the meat if using. 4. Whisk together broth, salt, pepper, paprika, turmeric, and cumin; pour over everything. 5. Add water until beans and meat are just covered. 6. Cover and cook on low heat for 16 hours (or overnight in oven at 200°F). 7. Check periodically, adding water if too dry. 8. Peel and slice eggs before serving; dig in and serve from the pot with challah.", "tags": "ashkenazi, shabbat, meat, slow-cooker, make-ahead", "source": "https://toriavey.com/cholent/", "nutritionData": "{\"calories\": 545, \"protein\": 35.0, \"carbs\": 42.0, \"fat\": 22.0}"},
  {"name": "Kasha Varnishkes", "category": "Jewish", "description": "Toasted buckwheat groats tossed with caramelized onions and bow-tie pasta, a classic Ashkenazi comfort dish.", "servings": 6, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3/4 cup\", \"name\": \"kasha buckwheat groats\"}, {\"qty\": \"1\", \"name\": \"large egg beaten\"}, {\"qty\": \"2\", \"name\": \"onions chopped\"}, {\"qty\": \"1/3 cup\", \"name\": \"schmaltz or butter divided\"}, {\"qty\": \"1/2 lb\", \"name\": \"farfalle bow-tie pasta\"}, {\"qty\": \"3 cups\", \"name\": \"boiling water\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped for garnish\"}]", "instructions": "1. Preheat oven to 325°F; mix kasha with beaten egg, 1/4 tsp salt, and a dash of pepper until well coated. 2. Spread kasha mixture in a small oven-safe nonstick skillet and toast in oven 15-20 minutes until dried and fragrant. 3. Meanwhile, heat 2 tbsp schmaltz in a large skillet over medium; caramelize onions 15-20 minutes, stirring often, until golden. 4. Bring 3 cups water to a boil in a medium saucepan; add toasted kasha and 1/4 tsp salt; cover and simmer 15 minutes until water is absorbed and kasha is fluffy. 5. Cook pasta in salted boiling water until al dente; drain. 6. Combine cooked pasta, kasha, and caramelized onions with their oil in a large bowl. 7. Add remaining schmaltz or butter; toss well to combine; season generously with salt and pepper. 8. Serve hot garnished with fresh parsley.", "tags": "ashkenazi, shabbat, meat-or-pareve, classic", "source": "https://toriavey.com/kasha-varnishkes-kasha-and-bows/", "nutritionData": "{\"calories\": 310, \"protein\": 10.0, \"carbs\": 42.0, \"fat\": 11.0}"},
  {"name": "Cheese Blintzes", "category": "Jewish", "description": "Paper-thin crepes filled with sweet ricotta and cream cheese, pan-fried golden for the Shavuot holiday.", "servings": 6, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"lowfat ricotta cheese drained overnight\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1\", \"name\": \"large egg yolk\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}, {\"qty\": \"\", \"name\": \"Sour cream or fruit topping for serving\"}]", "instructions": "1. Blend together eggs, flour, 1/3 cup sugar, milk, water, and vanilla until completely smooth; rest batter 15 minutes. 2. Make filling by mixing ricotta, cream cheese, 1/4 cup sugar, egg yolk, lemon juice, and a pinch of salt with a fork until smooth. 3. Heat an 8-inch nonstick skillet over medium and spray with oil; pour in 1/3 cup batter and tilt to coat pan in a thin, even circle. 4. Cook until edges are dry and bottom is lightly golden, about 60-75 seconds; do not flip; slide blintz onto a plate. 5. Repeat with remaining batter, separating blintzes with parchment paper. 6. Place 3 tbsp filling on the lower part of each blintz; fold bottom edge up, fold in sides, then roll up into a neat package. 7. Heat vegetable oil in a skillet over medium; fry blintzes flap-side down in batches for 1.5-2 minutes per side until evenly browned. 8. Serve warm with sour cream or fruit topping.", "tags": "ashkenazi, shavuot, dairy, breakfast", "source": "https://toriavey.com/shiksa-blintzes/", "nutritionData": "{\"calories\": 390, \"protein\": 14.0, \"carbs\": 34.0, \"fat\": 22.0}"},
  {"name": "Gefilte Fish", "category": "Jewish", "description": "Poached ground fish patties seasoned with onion and matzo meal, the iconic Ashkenazi Passover appetizer.", "servings": 6, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3/4 lb\", \"name\": \"salmon fillets boned and skinned\"}, {\"qty\": \"3/4 lb\", \"name\": \"whitefish or cod boned\"}, {\"qty\": \"1\", \"name\": \"medium onion fine diced\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"matzo meal\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"quart fish stock\"}, {\"qty\": \"1\", \"name\": \"stalk celery sliced\"}, {\"qty\": \"1/2\", \"name\": \"lemon\"}, {\"qty\": \"\", \"name\": \"Prepared horseradish for serving\"}]", "instructions": "1. Bring fish stock with celery, lemon, salt, and pepper to a simmer in a large pot. 2. Sauté onion in oil over medium heat until soft, about 5 minutes; allow to cool. 3. Finely chop salmon and whitefish with a knife or pulse briefly in a food processor; transfer to a bowl. 4. Mix in cooled sautéed onion, eggs, matzo meal, parsley, salt, and pepper until well combined; mixture should hold together when formed. 5. With wet hands, form 2-3 tablespoons of fish mixture into smooth oval patties. 6. Gently lower fish balls into simmering stock in a single layer; do not boil. 7. Simmer for 10-12 minutes until cooked through; remove with a slotted spoon and drain on paper towels. 8. Serve warm or cold on lettuce with prepared horseradish.", "tags": "ashkenazi, passover, shabbat, fish, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 155, \"protein\": 18.0, \"carbs\": 8.0, \"fat\": 5.0}"},
  {"name": "Tzimmes", "category": "Jewish", "description": "Sweet glazed carrots, sweet potatoes, and prunes roasted with honey and cinnamon for Rosh Hashanah.", "servings": 8, "prepTime": 15, "cookTime": 90, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"carrots peeled and cut into 1/2-inch slices\"}, {\"qty\": \"2\", \"name\": \"medium sweet potatoes peeled and cut into chunks\"}, {\"qty\": \"1 cup\", \"name\": \"pitted prunes\"}, {\"qty\": \"1/2 cup\", \"name\": \"golden raisins\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 cup\", \"name\": \"orange juice\"}]", "instructions": "1. Preheat oven to 350°F; lightly grease a 9x13 baking dish. 2. Place carrots, sweet potatoes, prunes, and raisins in a large bowl. 3. Drizzle with oil; add brown sugar, cinnamon, salt, and pepper; toss well to coat all pieces. 4. Pour in orange juice and toss again to combine. 5. Transfer to prepared baking dish; cover tightly with foil. 6. Bake for 1 hour, stirring once or twice, until vegetables are very tender. 7. Remove foil and continue baking 20-30 minutes until sauce has thickened into a glaze. 8. Serve warm as a side dish.", "tags": "ashkenazi, rosh-hashanah, passover, pareve, vegan", "source": "https://www.myjewishlearning.com/the-nosher/classic-tzimmes-recipe/", "nutritionData": "{\"calories\": 245, \"protein\": 2.0, \"carbs\": 55.0, \"fat\": 4.0}"},
  {"name": "Potato Kugel", "category": "Jewish", "description": "Crispy-edged baked shredded potato casserole with golden crust, a Passover and Shabbat staple.", "servings": 8, "prepTime": 20, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"russet potatoes peeled\"}, {\"qty\": \"2\", \"name\": \"large onions\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/3 cup\", \"name\": \"olive oil or schmaltz\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"potato starch\"}, {\"qty\": \"\", \"name\": \"Paprika for topping\"}]", "instructions": "1. Preheat oven to 400°F; add 1/4 cup oil to a 9x13 baking dish and place in oven to heat up. 2. Shred potatoes using a food processor or box grater; place in a large bowl of cold water for 5 minutes. 3. Shred onions and set aside. 4. Whisk together eggs, salt, pepper, and garlic powder in a large bowl. 5. Drain potatoes in a colander, pressing firmly to remove excess liquid; add to egg mixture. 6. Add shredded onion and potato starch; mix with hands until well combined. 7. Carefully pour hot oil from dish into potato mixture and stir; quickly transfer mixture to hot dish, spreading evenly with a spoon (it should sizzle); drizzle remaining oil on top and sprinkle with paprika. 8. Bake uncovered 60-70 minutes until top is deeply golden and crispy; cool 5 minutes before cutting.", "tags": "ashkenazi, passover, shabbat, pareve, gluten-free", "source": "https://www.myjewishlearning.com/the-nosher/classic-potato-kugel/", "nutritionData": "{\"calories\": 250, \"protein\": 5.0, \"carbs\": 33.0, \"fat\": 11.0}"},
  {"name": "Sufganiyot", "category": "Jewish", "description": "Deep-fried yeast doughnuts filled with strawberry jam and dusted with powdered sugar for Hanukkah.", "servings": 16, "prepTime": 30, "cookTime": 180, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 1/4 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"18 oz\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"canola oil\"}, {\"qty\": \"3/4 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"vodka or brandy\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"strawberry jam strained\"}, {\"qty\": \"\", \"name\": \"Powdered sugar for dusting\"}, {\"qty\": \"2\", \"name\": \"quarts vegetable oil for frying\"}]", "instructions": "1. Whisk yeast, 1 tbsp sugar, and warm water in a small bowl; let stand 5-10 minutes until foamy. 2. In a stand mixer bowl, combine flour and salt; add yeast mixture, remaining sugar, eggs, canola oil, and vanilla; knead with dough hook on low for 10 minutes until sticky dough forms. 3. Add vodka and knead 2-3 minutes more; dough should be sticky but cohesive. 4. Transfer dough to an oiled bowl, cover with a damp towel, and let rise 2 hours until doubled. 5. Roll dough on a floured surface to 1/2-inch thick; cut into 3-inch circles; place on a floured baking sheet and let rise 45 minutes. 6. Heat oil in a large pot to 325°F using a thermometer; fry sufganiyot in batches of 4, flipping once, about 90 seconds per side until golden brown. 7. Drain on a wire rack; cool slightly. 8. Fill a squeeze bottle with strained jam; insert tip into center of each sufganiyot and squeeze in jam; dust generously with powdered sugar and serve immediately.", "tags": "ashkenazi, israeli, hanukkah, fried", "source": "https://toriavey.com/sufganiyot/", "nutritionData": "{\"calories\": 250, \"protein\": 4.0, \"carbs\": 37.0, \"fat\": 10.0}"},
  {"name": "Honey Apple Cake", "category": "Jewish", "description": "Moist and warmly spiced apple honey bundt cake, a traditional Rosh Hashanah dessert for a sweet New Year.", "servings": 16, "prepTime": 20, "cookTime": 90, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"honey\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1/4 tsp\", \"name\": \"nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"shredded apple with juice\"}, {\"qty\": \"1 cup\", \"name\": \"powdered sugar for glaze\"}]", "instructions": "1. Preheat oven to 325°F; grease and flour a 10-inch bundt pan. 2. Beat eggs until frothy; whisk in honey, both sugars, oil, and vanilla. 3. In a separate bowl, sift together flour, baking powder, baking soda, cinnamon, allspice, nutmeg, and salt. 4. Fold the flour mixture into the wet ingredients, stirring until combined; fold in shredded apples and their juice. 5. Pour batter into prepared bundt pan. 6. Bake 75-90 minutes until a toothpick inserted in the center comes out clean; check at 60 minutes if using a dark pan. 7. Cool cake in pan exactly 10 minutes; invert onto a plate and tap gently to release; cool completely. 8. Mix powdered sugar with 1-2 tsp water to make a thick glaze; drizzle over cake in a zigzag pattern and allow to set before slicing.", "tags": "ashkenazi, rosh-hashanah, dairy-free, pareve, dessert", "source": "https://toriavey.com/honey-apple-cake/", "nutritionData": "{\"calories\": 300, \"protein\": 3.0, \"carbs\": 52.0, \"fat\": 10.0}"},
  {"name": "Cheese Burekas", "category": "Jewish", "description": "Flaky puff pastry triangles stuffed with seasoned feta and ricotta cheese, a beloved Israeli-Sephardic snack.", "servings": 18, "prepTime": 20, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 sheets\", \"name\": \"frozen puff pastry thawed\"}, {\"qty\": \"4 oz\", \"name\": \"feta cheese crumbled\"}, {\"qty\": \"4 oz\", \"name\": \"kashkaval or mozzarella shredded\"}, {\"qty\": \"4 oz\", \"name\": \"ricotta cheese\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"\", \"name\": \"Pinch of kosher salt\"}, {\"qty\": \"\", \"name\": \"Pinch of black pepper\"}, {\"qty\": \"1\", \"name\": \"egg yolk mixed with 2 tsp water for egg wash\"}, {\"qty\": \"\", \"name\": \"Sesame or poppy seeds for topping\"}]", "instructions": "1. Preheat oven to 350°F; line two baking sheets with parchment paper. 2. In a mixing bowl, combine feta, kashkaval or mozzarella, ricotta, egg, salt, and pepper; mix well with a fork until blended. 3. On a lightly floured surface, roll out each puff pastry sheet to a 12x12-inch square; cut each into 9 equal squares (4x4 inches each). 4. Place 1 scant tablespoon of cheese filling in the center of each square. 5. Wet edges with a finger dipped in water; fold dough over diagonally to form triangles; press edges firmly to seal, then crimp with a fork. 6. Arrange on prepared baking sheets spaced evenly apart. 7. Brush tops with egg wash and sprinkle with sesame or poppy seeds. 8. Bake 30 minutes, switching pans halfway through, until puffed and golden brown; serve warm or at room temperature.", "tags": "sephardic, israeli, dairy, snack, shabbat", "source": "https://toriavey.com/cheese-bourekas/", "nutritionData": "{\"calories\": 200, \"protein\": 6.0, \"carbs\": 18.0, \"fat\": 12.0}"},
  {"name": "Moroccan Harira Soup", "category": "Jewish", "description": "Rich Moroccan tomato and lentil soup with chickpeas, warming spices, and fresh herbs.", "servings": 6, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"carrots diced\"}, {\"qty\": \"3\", \"name\": \"stalks celery diced\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"harissa paste\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 can\", \"name\": \"diced tomatoes 14 oz\"}, {\"qty\": \"1 cup\", \"name\": \"dried green lentils\"}, {\"qty\": \"1/2 cup\", \"name\": \"red lentils\"}, {\"qty\": \"1 can\", \"name\": \"chickpeas 15 oz drained\"}, {\"qty\": \"6 cups\", \"name\": \"vegetable stock\"}, {\"qty\": \"2 oz\", \"name\": \"vermicelli noodles\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley and cilantro chopped\"}]", "instructions": "1. Heat olive oil in a large pot over medium heat; add carrots, celery, and onion; sauté 5-6 minutes until softened. 2. Add garlic and sauté 1-2 minutes until fragrant. 3. Stir in harissa, turmeric, ginger, cinnamon, and coriander; cook 1 minute; add tomato paste and cook 2 more minutes. 4. Add green lentils, red lentils, diced tomatoes, and vegetable stock; increase heat to high and bring to a boil. 5. Reduce heat and simmer 60-90 minutes until lentils are very tender and soup begins to thicken; stir occasionally. 6. Add chickpeas and vermicelli noodles; simmer 15 minutes more until noodles are cooked. 7. Taste and season with salt and pepper as needed. 8. Ladle into bowls and finish with generous handfuls of fresh parsley and cilantro.", "tags": "sephardic, moroccan, vegan, shabbat, rosh-hashanah", "source": "https://www.myjewishlearning.com/the-nosher/moroccan-harira-soup-recipe/", "nutritionData": "{\"calories\": 190, \"protein\": 10.0, \"carbs\": 28.0, \"fat\": 5.0}"},
  {"name": "Moroccan Chicken Couscous", "category": "Jewish", "description": "Aromatic braised chicken and seven vegetables over steamed couscous, a Moroccan-Jewish Shabbat centerpiece.", "servings": 6, "prepTime": 20, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chicken pieces bone-in\"}, {\"qty\": \"2\", \"name\": \"onions sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1\", \"name\": \"zucchini cut into wedges\"}, {\"qty\": \"2\", \"name\": \"carrots peeled and chopped\"}, {\"qty\": \"1\", \"name\": \"small butternut squash peeled and cubed\"}, {\"qty\": \"1 can\", \"name\": \"chickpeas 15 oz drained\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 cups\", \"name\": \"couscous\"}, {\"qty\": \"2 cups\", \"name\": \"chicken broth for couscous\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro or parsley for garnish\"}]", "instructions": "1. Heat olive oil in a large Dutch oven over medium-high heat; brown chicken pieces on all sides; remove and set aside. 2. In the same pot, sauté onions over medium heat until caramelized, about 10 minutes; add garlic and cook 1 minute. 3. Pour in 1.5 cups chicken broth; stir in salt, turmeric, cumin, and cayenne; bring to a simmer. 4. Return chicken to pot skin-side up; cover and simmer on low heat for 45 minutes. 5. Add squash, zucchini, and carrots around the chicken; bring back to a boil, then cover and simmer 15 minutes. 6. Stir in chickpeas; simmer covered 5-10 more minutes until largest vegetables are tender. 7. Meanwhile, bring 2 cups broth to a boil; stir in couscous, cover, remove from heat, and steam 5 minutes; fluff with a fork. 8. Mound couscous on a large platter; top with chicken and vegetables; ladle broth on top and garnish with fresh cilantro.", "tags": "sephardic, moroccan, shabbat, meat", "source": "https://toriavey.com/chicken-vegetable-couscous/", "nutritionData": "{\"calories\": 485, \"protein\": 38.0, \"carbs\": 48.0, \"fat\": 13.0}"},
  {"name": "Jachnun", "category": "Jewish", "description": "Flaky Yemenite overnight pastry rolls baked low and slow, served with grated tomato and schug on Shabbat morning.", "servings": 10, "prepTime": 60, "cookTime": 600, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"8 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"5 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"warm water\"}, {\"qty\": \"1/2 cup\", \"name\": \"neutral oil\"}, {\"qty\": \"2 sticks\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"10\", \"name\": \"large eggs in shells for slow cooking\"}, {\"qty\": \"\", \"name\": \"2-3 slices stale bread for pot\"}, {\"qty\": \"2\", \"name\": \"ripe tomatoes grated for serving\"}, {\"qty\": \"1/2 cup\", \"name\": \"schug green chili sauce for serving\"}]", "instructions": "1. Combine flour, brown sugar, and salt in a stand mixer with dough hook; gradually add water on low speed; mix 10-15 minutes until soft and slightly sticky dough forms. 2. Oil the dough, cover, and rest at room temperature 30 minutes; divide into 10 equal balls; place in an oiled dish, cover, and refrigerate at least 2 hours. 3. Preheat oven to 200°F; line the bottom of a heavy ovenproof pot with stale bread and parchment paper. 4. Working with one dough ball at a time, use buttered fingertips to slowly stretch each ball into a very thin, nearly translucent 17x20-inch sheet. 5. Dab with 2 tsp softened butter; fold the sheet into thirds horizontally then roll into a tight log; place in the pot. 6. Repeat with remaining dough balls, layering them in the pot; drizzle 2-3 tbsp hot water over the top; cover tightly. 7. Place eggs in their shells into a small lidded pot; cover with salted water; place both pots in oven for 10-12 hours overnight. 8. Serve jachnun hot from the oven with slow-cooked brown eggs, grated fresh tomato, and schug.", "tags": "yemenite, mizrahi, shabbat, pareve", "source": "https://www.myjewishlearning.com/the-nosher/how-to-make-jachnun-yemenite-overnight-shabbat-rolls/", "nutritionData": "{\"calories\": 520, \"protein\": 9.0, \"carbs\": 62.0, \"fat\": 26.0}"},
  {"name": "Ashkenazi Charoset", "category": "Jewish", "description": "Apple and walnut Passover condiment sweetened with wine and cinnamon, symbolizing the mortar of Egypt.", "servings": 8, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"Gala or Fuji apples (about 4 medium)\"}, {\"qty\": \"1 cup\", \"name\": \"raw walnuts finely chopped\"}, {\"qty\": \"5 tbsp\", \"name\": \"sweet kosher wine\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1/4 tsp\", \"name\": \"allspice\"}, {\"qty\": \"\", \"name\": \"Pinch of kosher salt\"}]", "instructions": "1. Peel and core the apples; chop finely by hand or pulse in a food processor, being careful not to over-process into applesauce. 2. Place chopped apples in a large bowl. 3. Add sweet kosher wine, honey, cinnamon, ginger, allspice, and a pinch of salt; stir to combine. 4. Fold in finely chopped walnuts. 5. Taste and adjust sweetness with more wine or honey if needed; the mixture should be moistened but not soupy. 6. Cover and refrigerate for at least 1 hour or overnight for the best flavor. 7. Stir again before serving; the wine will be partially absorbed. 8. Serve chilled at the Passover seder alongside matzah and the rest of the seder plate.", "tags": "ashkenazi, passover, seder, vegan, gluten-free", "source": "https://toriavey.com/apple-cinnamon-charoset-candied-walnuts/", "nutritionData": "{\"calories\": 85, \"protein\": 2.0, \"carbs\": 13.0, \"fat\": 4.0}"},
  {"name": "Cinnamon Noodle Kugel", "category": "Jewish", "description": "Light and fluffy pareve noodle kugel with cinnamon, nutmeg, and raisins baked until golden and set.", "servings": 12, "prepTime": 15, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"broad egg noodles\"}, {\"qty\": \"1/2 cup\", \"name\": \"margarine or butter melted\"}, {\"qty\": \"1 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"4 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"7\", \"name\": \"large eggs separated\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"raisins\"}]", "instructions": "1. Preheat oven to 350°F; grease a 9x13 baking dish. 2. Cook egg noodles according to package directions; drain well. 3. In a large bowl, toss noodles with melted margarine or butter until coated. 4. In a separate bowl, whisk together sugar, cinnamon, and nutmeg; add to noodle mixture and stir. 5. Separate eggs; beat whites in a clean bowl until stiff peaks form; lightly beat yolks in another bowl. 6. Add beaten yolks and raisins to the noodle mixture; stir to combine. 7. Gently fold stiff egg whites into the noodle mixture until just incorporated. 8. Pour into greased baking dish and bake 40-45 minutes until top is just beginning to turn golden and crispy.", "tags": "ashkenazi, shabbat, dairy-free-option, make-ahead", "source": "https://www.myjewishlearning.com/the-nosher/cinnamon-noodle-kugel-recipe/", "nutritionData": "{\"calories\": 355, \"protein\": 8.0, \"carbs\": 56.0, \"fat\": 12.0}"},
  {"name": "New York Cheesecake", "category": "Jewish", "description": "Towering, ultra-creamy cream cheese cheesecake on a graham cracker crust, the quintessential Shavuot dessert.", "servings": 12, "prepTime": 30, "cookTime": 75, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"graham crackers finely ground\"}, {\"qty\": \"8 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar for crust\"}, {\"qty\": \"5\", \"name\": \"packages cream cheese 8 oz each softened\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"finely grated lemon zest\"}, {\"qty\": \"1 tsp\", \"name\": \"finely grated orange zest\"}, {\"qty\": \"5\", \"name\": \"large eggs\"}, {\"qty\": \"2\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Make crust: combine ground graham crackers, melted butter, and 1/2 cup sugar; press firmly onto bottom and partway up the sides of a buttered 9.5-inch springform pan; chill in freezer while preparing filling. 2. Preheat oven to 550°F; beat cream cheese, 1 3/4 cups sugar, flour, and zests with a mixer until smooth. 3. Add vanilla then eggs and egg yolks one at a time, beating on low after each addition; scrape bowl frequently. 4. Place pan with crust in a shallow baking pan (to catch drips); pour filling into crust (pan will be very full). 5. Bake at 550°F for 12 minutes until puffed; reduce oven to 200°F and continue baking 60-70 minutes until mostly firm with a slight wobble in the center. 6. Run a knife around the top edge to loosen; cool completely on a rack. 7. Refrigerate loosely covered for at least 6 hours or overnight. 8. Carefully remove sides of springform; slice with a warm, clean knife and serve at room temperature.", "tags": "jewish-american, shavuot, dairy, dessert, make-ahead", "source": "https://smittenkitchen.com/2010/04/new-york-cheesecake/", "nutritionData": "{\"calories\": 605, \"protein\": 10.0, \"carbs\": 56.0, \"fat\": 39.0}"},
  {"name": "Mandelbrot", "category": "Jewish", "description": "Twice-baked almond and chocolate chip Jewish biscotti, crisp and perfect for dunking in tea or coffee.", "servings": 30, "prepTime": 15, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"3/4 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"almond extract\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"sliced almonds\"}, {\"qty\": \"1 cup\", \"name\": \"semisweet chocolate chips\"}, {\"qty\": \"2 tsp\", \"name\": \"cinnamon mixed with 2 tbsp sugar for topping\"}]", "instructions": "1. Preheat oven to 350°F; line a baking sheet with parchment paper. 2. Beat eggs and sugar with an electric mixer for 2 minutes; beat in oil, vanilla, and almond extract. 3. In a separate bowl, whisk together flour, baking powder, and salt; stir into egg mixture until combined. 4. Fold in almonds and chocolate chips; dough will be soft and slightly sticky. 5. Divide dough in half; shape each half into a log about 12 inches long and 2.5 inches wide on the prepared baking sheet; logs will spread during baking. 6. Sprinkle tops with cinnamon-sugar mixture. 7. Bake 30-35 minutes until golden and set; cool 15 minutes; slice each log diagonally into 1/2-inch slices. 8. Return slices to baking sheet cut-side up and bake 10-12 minutes more until dry and crisp; cool completely on a rack.", "tags": "ashkenazi, purim, pareve, cookies, dairy-free", "source": "Classic", "nutritionData": "{\"calories\": 165, \"protein\": 3.0, \"carbs\": 19.0, \"fat\": 9.0}"},
  {"name": "Maamoul Date Cookies", "category": "Jewish", "description": "Tender semolina shortbread cookies filled with spiced date paste, a beloved Sephardic and Mizrahi confection.", "servings": 24, "prepTime": 30, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 cup\", \"name\": \"fine semolina\"}, {\"qty\": \"1/3 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"7 oz\", \"name\": \"unsalted butter slightly softened\"}, {\"qty\": \"1/3 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"rose water\"}, {\"qty\": \"10 oz\", \"name\": \"pitted dates\"}, {\"qty\": \"1/2 cup\", \"name\": \"walnuts finely chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"\", \"name\": \"Powdered sugar for dusting\"}]", "instructions": "1. Combine flour, semolina, powdered sugar, and baking powder in a large bowl; add softened butter, oil, rose water, and water; mix by hand until a soft dough forms (do not overmix); refrigerate 20 minutes. 2. Make filling: combine dates, chopped walnuts, and cinnamon; knead together, adding 1 tbsp water if needed, until a uniform paste forms. 3. Preheat oven to 350°F; line baking sheets with parchment. 4. Divide dough into three sections; roll out each portion to 1/4-inch thick on parchment paper. 5. Press a ball of dough into a floured maamoul mold (or shape by hand into a round); press a teaspoon of date filling into the center; close dough over the filling and smooth. 6. Tap mold to release shaped cookie or shape into a smooth round ball and press lightly. 7. Arrange on baking sheets and bake 25-30 minutes until just barely beginning to turn golden on the bottom; do not overbake. 8. Cool completely; dust generously with powdered sugar before serving.", "tags": "sephardic, mizrahi, purim, passover, dairy-free", "source": "Classic", "nutritionData": "{\"calories\": 175, \"protein\": 3.0, \"carbs\": 22.0, \"fat\": 9.0}"},
  {"name": "T'beet Iraqi Shabbat Rice", "category": "Jewish", "description": "Iraqi-Jewish slow-cooked whole chicken stuffed with fragrant spiced rice, simmered overnight for Shabbat.", "servings": 6, "prepTime": 30, "cookTime": 600, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken 3-4 lbs\"}, {\"qty\": \"2 cups\", \"name\": \"long-grain white rice\"}, {\"qty\": \"2\", \"name\": \"onions finely chopped\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 can\", \"name\": \"diced tomatoes 14 oz\"}, {\"qty\": \"3 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"slivered almonds toasted for garnish\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Heat oil in a large heavy pot over medium; sauté onions until golden brown and caramelized, about 15 minutes; add garlic and cook 1 minute. 2. Add turmeric, allspice, cinnamon, cumin, black pepper, and salt; stir 1 minute. 3. Mix half of the spiced onion with 1 cup uncooked rice; stuff this mixture loosely into the chicken cavity; tie legs together with kitchen twine. 4. Add diced tomatoes and chicken broth to the remaining spiced onions in the pot; stir to combine. 5. Place stuffed chicken breast-side down in the pot; add remaining 1 cup of rice around the chicken. 6. Add water if needed so rice is submerged; bring to a boil, then reduce to lowest heat; cover tightly. 7. Cook on lowest heat overnight or bake at 200°F for 10-12 hours until chicken is falling-apart tender and rice has cooked and absorbed the broth. 8. Serve garnished with toasted almonds and fresh parsley.", "tags": "mizrahi, iraqi, shabbat, meat, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 35.0, \"carbs\": 48.0, \"fat\": 16.0}"},
  {"name": "Sabich", "category": "Jewish", "description": "Israeli pita sandwich with fried eggplant, hard-boiled eggs, hummus, and Israeli salad, an Iraqi-Jewish street food.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium Italian eggplants sliced 1/2 inch thick\"}, {\"qty\": \"\", \"name\": \"Vegetable oil for frying\"}, {\"qty\": \"4\", \"name\": \"large pita breads\"}, {\"qty\": \"4\", \"name\": \"hard-boiled eggs sliced\"}, {\"qty\": \"1 cup\", \"name\": \"store-bought or homemade hummus\"}, {\"qty\": \"2\", \"name\": \"large tomatoes diced\"}, {\"qty\": \"2\", \"name\": \"Persian cucumbers diced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"Salt and pepper to taste\"}, {\"qty\": \"1/4 cup\", \"name\": \"tahini thinned with lemon juice\"}, {\"qty\": \"\", \"name\": \"Amba mango pickle sauce for serving\"}, {\"qty\": \"\", \"name\": \"Schug for serving\"}]", "instructions": "1. Salt eggplant slices generously and let drain in a colander for 20 minutes; pat dry with paper towels. 2. Heat 1/2 inch vegetable oil in a large skillet over medium-high heat; fry eggplant slices in batches for 2-3 minutes per side until deeply golden and tender; drain on a rack. 3. Make Israeli salad: combine diced tomatoes, cucumbers, and parsley; dress with olive oil, lemon juice, salt, and pepper; toss well. 4. Warm pitas in a dry skillet or oven; open each pita to form a pocket. 5. Spread a generous layer of hummus inside each pita. 6. Layer in 3-4 slices of fried eggplant and 2-3 slices of hard-boiled egg. 7. Add a scoop of Israeli salad. 8. Drizzle with thin tahini and amba sauce; add schug for heat; serve immediately.", "tags": "israeli, mizrahi, street-food, dairy-free, modern", "source": "Classic", "nutritionData": "{\"calories\": 540, \"protein\": 20.0, \"carbs\": 52.0, \"fat\": 28.0}"},
  {"name": "Schug Green Chili Sauce", "category": "Jewish", "description": "Vibrant Yemenite green chili and herb sauce, an essential condiment for sabich, falafel, and jachnun.", "servings": 12, "prepTime": 10, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"serrano or jalape\\u00f1o peppers stems removed\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1 cup\", \"name\": \"fresh cilantro leaves and stems\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh parsley leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cardamom\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"water or more to thin\"}]", "instructions": "1. Roughly chop the hot peppers, removing seeds if you prefer less heat. 2. Add peppers and garlic to a food processor and pulse until roughly chopped. 3. Add cilantro, parsley, cumin, cardamom, and salt to the processor. 4. Pulse, scraping down the sides, until a slightly chunky paste forms; do not over-process to a smooth paste. 5. Add olive oil and water; pulse a few more times to incorporate. 6. Taste and adjust salt, heat, and lemon juice to your preference. 7. Transfer to a jar; drizzle a thin layer of olive oil on top to preserve color. 8. Refrigerate for up to 2 weeks; serve as a condiment alongside sabich, falafel, jachnun, or eggs.", "tags": "yemenite, israeli, condiment, vegan, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 30, \"protein\": 1.0, \"carbs\": 2.0, \"fat\": 2.0}"},
  {"name": "Matbucha", "category": "Jewish", "description": "Slowly cooked Moroccan-Israeli roasted tomato and pepper salad, a classic mezze for dipping with challah.", "servings": 8, "prepTime": 15, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ripe tomatoes\"}, {\"qty\": \"3\", \"name\": \"large red bell peppers\"}, {\"qty\": \"\", \"name\": \"1-2 hot chili peppers or to taste\"}, {\"qty\": \"8 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"sweet paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}]", "instructions": "1. Roast red bell peppers directly over a gas flame or under the broiler, turning, until completely charred on all sides; place in a covered bowl for 15 minutes to steam. 2. Peel, seed, and roughly chop the charred peppers. 3. Score the base of the tomatoes with an X; blanch in boiling water 30 seconds; peel, seed, and chop coarsely. 4. Heat olive oil in a wide heavy pot over medium heat; add garlic and sauté 1-2 minutes until fragrant but not browned. 5. Add chopped tomatoes, chopped peppers, and whole hot chili peppers; stir to combine. 6. Stir in tomato paste, paprika, sugar, salt, and pepper. 7. Simmer uncovered over medium-low heat, stirring occasionally, for 60 minutes until mixture is very thick and most liquid has evaporated. 8. Cool to room temperature; serve as a mezze with challah, pita, or crackers; refrigerates well for up to 1 week.", "tags": "moroccan, sephardic, israeli, mezze, vegan", "source": "Classic", "nutritionData": "{\"calories\": 100, \"protein\": 2.0, \"carbs\": 11.0, \"fat\": 6.0}"},
  {"name": "Malabi", "category": "Jewish", "description": "Silky Middle Eastern rosewater milk pudding topped with pomegranate syrup and toasted coconut.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"5 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"rose water\"}, {\"qty\": \"1/2 cup\", \"name\": \"pomegranate juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar for syrup\"}, {\"qty\": \"1/4 cup\", \"name\": \"toasted shredded coconut\"}, {\"qty\": \"2 tbsp\", \"name\": \"crushed pistachios for garnish\"}]", "instructions": "1. In a small bowl, whisk cornstarch with 1/2 cup of the milk until smooth (the slurry). 2. Combine remaining milk, heavy cream, and 1/2 cup sugar in a medium saucepan over medium heat; stir until sugar dissolves and milk is hot but not boiling. 3. Whisk the cornstarch slurry into the hot milk mixture; cook over medium heat, stirring constantly, until mixture thickens enough to coat the back of a spoon, about 5-8 minutes. 4. Remove from heat and stir in rose water. 5. Pour pudding into 6 individual dessert cups or ramekins; press plastic wrap directly on the surface to prevent a skin. 6. Refrigerate at least 3 hours or overnight until fully set and firm. 7. Make the syrup: simmer pomegranate juice with 2 tbsp sugar over medium heat for 5-8 minutes until slightly thickened and syrupy; cool. 8. To serve, spoon pomegranate syrup over each pudding and garnish with toasted coconut and crushed pistachios.", "tags": "sephardic, israeli, dessert, gluten-free, dairy", "source": "Classic", "nutritionData": "{\"calories\": 245, \"protein\": 6.0, \"carbs\": 38.0, \"fat\": 8.0}"},
  {"name": "Butter Chicken", "category": "Indian", "description": "Tender broiled chicken simmered in a rich spiced tomato cream sauce with kasoori methi.", "servings": 4, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2 tsp\", \"name\": \"tandoori masala\"}, {\"qty\": \"4 tsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"2\", \"name\": \"green cardamoms\"}, {\"qty\": \"1\", \"name\": \"black cardamom\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"3\", \"name\": \"large tomatoes pureed\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"kasoori methi\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Cut chicken into bite-size pieces and marinate with yogurt, lemon juice, 2 tsp ginger garlic paste, tandoori masala, chili powder, and salt for 2 hours or overnight. 2. Broil chicken on high for 5-7 minutes per side until slightly charred; set aside. 3. Heat butter in a pan over medium heat; add cardamoms, bay leaf, and cinnamon stick; fry 1 minute. 4. Add remaining 2 tsp ginger garlic paste; fry 30 seconds then stir in tomato puree. 5. Add salt, chili powder, and garam masala; simmer 10 minutes until oil separates. 6. Stir in sugar and crushed kasoori methi; cook 2 minutes then add broiled chicken. 7. Pour in heavy cream, stir well, and bring just to a boil; taste and adjust seasoning before serving.", "tags": "north-indian, creamy, chicken", "source": "https://showmethecurry.com/curries/butter-chicken-murgh-makhani.html", "nutritionData": "{\"calories\": 520, \"protein\": 36.0, \"carbs\": 12.0, \"fat\": 37.0}"},
  {"name": "Paneer Tikka Masala", "category": "Indian", "description": "Grilled spiced paneer cubes folded into a velvety onion-tomato-cashew gravy.", "servings": 4, "prepTime": 30, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"400g\", \"name\": \"paneer cut in cubes\"}, {\"qty\": \"1/2 cup\", \"name\": \"thick plain yogurt\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"1 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"2\", \"name\": \"medium onions chopped\"}, {\"qty\": \"3\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"10\", \"name\": \"cashews\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Mix yogurt, chili powder, ginger garlic paste, garam masala, kasuri methi, oil, lemon juice, and salt; coat paneer cubes and marinate 1 hour. 2. Grill paneer on a hot oiled griddle or in oven at 430 F for 10 minutes until lightly charred; set aside. 3. Saute onions in oil until golden; add tomatoes, cashews, sugar, and salt; cook until tomatoes are soft. 4. Cool and blend onion-tomato mixture to a smooth puree. 5. Heat 2 tbsp oil; add cumin seeds and ginger garlic paste; saute 1 minute then pour in the puree. 6. Stir in chili powder, garam masala, and water to get a gravy consistency; simmer covered 10 minutes until oil floats on top. 7. Add grilled paneer; stir in heavy cream and crushed kasuri methi; simmer 3 minutes and serve garnished with coriander.", "tags": "north-indian, vegetarian, paneer", "source": "https://www.indianhealthyrecipes.com/paneer-tikka-masala-recipe-sanjeev-kapoor/", "nutritionData": "{\"calories\": 480, \"protein\": 22.0, \"carbs\": 18.0, \"fat\": 36.0}"},
  {"name": "Chana Masala", "category": "Indian", "description": "Bold Punjabi chickpea curry with tangy amchur and a deeply spiced onion-tomato base.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"dried chickpeas soaked overnight\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1\", \"name\": \"large onion finely chopped\"}, {\"qty\": \"1\", \"name\": \"green chili chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1.5 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"amchur powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"coriander leaves to garnish\"}]", "instructions": "1. Pressure cook soaked chickpeas with 1.5 cups water for 5-6 whistles until soft; drain and reserve cooking liquid. 2. Heat oil in a pot; add cumin seeds then onion and green chili; saute 7-8 minutes until golden. 3. Add ginger garlic paste and saute 2 minutes; stir in tomatoes and cook until mushy for 6-7 minutes. 4. Lower heat and add chili powder, turmeric, coriander powder, cumin powder, and salt; saute 3-4 minutes. 5. Add drained chickpeas and 1 cup reserved cooking liquid; mix well, cover, and simmer 15 minutes. 6. Uncover and mash a few chickpeas with the spoon to thicken the gravy; cook 5 more minutes. 7. Stir in amchur powder and crushed kasuri methi; garnish with coriander leaves and serve with naan or rice.", "tags": "north-indian, vegan, legumes", "source": "https://www.indianhealthyrecipes.com/chana-masala/", "nutritionData": "{\"calories\": 320, \"protein\": 15.0, \"carbs\": 48.0, \"fat\": 8.0}"},
  {"name": "Rajma Masala", "category": "Indian", "description": "Slow-simmered Punjabi kidney bean curry in an aromatic spiced onion-tomato gravy.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"dried kidney beans soaked overnight\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"2\", \"name\": \"medium onions finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"3\", \"name\": \"medium tomatoes finely chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"2 tbsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"2 tbsp\", \"name\": \"light cream\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"coriander leaves to garnish\"}]", "instructions": "1. Pressure cook soaked kidney beans with 3 cups water for 18-20 minutes until very tender; keep aside. 2. Heat ghee in a large pot; add cumin seeds then onions; saute until golden stirring often. 3. Add ginger garlic paste and cook 1 minute; add tomatoes and cook on medium heat until oil separates about 8 minutes. 4. Stir in turmeric, chili powder, coriander powder, and salt; saute the masala until aromatic. 5. Add cooked kidney beans with 2 cups liquid; stir well. 6. Simmer uncovered on low-medium heat 12-15 minutes until gravy thickens; mash a few beans to thicken further. 7. Stir in garam masala, crushed kasuri methi, and cream; simmer 2 more minutes and garnish with coriander.", "tags": "north-indian, vegan-adaptable, legumes", "source": "https://www.vegrecipesofindia.com/rajma-masala-recipe-restaurant-style/", "nutritionData": "{\"calories\": 300, \"protein\": 14.0, \"carbs\": 46.0, \"fat\": 7.0}"},
  {"name": "Rogan Josh", "category": "Indian", "description": "Slow-braised Kashmiri lamb in a fragrant yogurt-spice sauce with fennel and dried ginger.", "servings": 4, "prepTime": 20, "cookTime": 120, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"800g\", \"name\": \"bone-in lamb shoulder cut in pieces\"}, {\"qty\": \"3 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"5\", \"name\": \"green cardamoms\"}, {\"qty\": \"4\", \"name\": \"cloves\"}, {\"qty\": \"1\", \"name\": \"large onion finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger paste\"}, {\"qty\": \"1.5 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"fennel powder\"}, {\"qty\": \"1 tsp\", \"name\": \"dried ginger powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"thick plain yogurt\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"hot water\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"\", \"name\": \"coriander leaves to garnish\"}]", "instructions": "1. Heat ghee in a heavy pot; add cinnamon, cardamoms, and cloves; sizzle 1 minute. 2. Add lamb and sear on high heat 2 minutes; reduce and fry 4-5 minutes more until lightly browned. 3. Whisk together yogurt, chili powder, fennel powder, dried ginger powder, and salt in a bowl. 4. Take pot off stove; stir in yogurt mixture; return to medium heat and cook covered 3-4 minutes. 5. Pour 1 cup hot water; cook covered on low heat about 2 hours until lamb is fork-tender stirring every 10-15 minutes and adding more water as needed. 6. Uncover and reduce sauce slightly until it is of medium-thick consistency. 7. Stir in garam masala, garnish with coriander, and serve with basmati rice or naan.", "tags": "north-indian, lamb, slow-cook", "source": "https://www.indianhealthyrecipes.com/rogan-josh/", "nutritionData": "{\"calories\": 420, \"protein\": 32.0, \"carbs\": 8.0, \"fat\": 28.0}"},
  {"name": "Lamb Vindaloo", "category": "Indian", "description": "Fiery Goan-style lamb curry marinated in a vinegar-based spice paste with dark whole chilies.", "servings": 4, "prepTime": 30, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"800g\", \"name\": \"boneless lamb shoulder cubed\"}, {\"qty\": \"8\", \"name\": \"dried Kashmiri red chilies deseeded\"}, {\"qty\": \"3 tbsp\", \"name\": \"white wine vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"coriander seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"inch cinnamon\"}, {\"qty\": \"4\", \"name\": \"cloves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black mustard seeds\"}, {\"qty\": \"1 tbsp\", \"name\": \"jaggery\"}, {\"qty\": \"1\", \"name\": \"inch ginger\"}, {\"qty\": \"6\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"2\", \"name\": \"medium onions finely chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}]", "instructions": "1. Soak chilies in vinegar and 1/4 cup hot water 20 minutes; grind to a smooth paste with spices, jaggery, ginger, and garlic. 2. Marinate lamb in turmeric, vindaloo paste, and salt; cover and refrigerate overnight or at least 6 hours. 3. Heat oil in a dutch oven; fry onions over medium heat until golden about 8 minutes. 4. Add marinated lamb; saute on medium-high 5 minutes until the paste begins to smell aromatic and leave sides. 5. Cover and cook 3 minutes on medium-low; add curry leaves and saute 2 minutes. 6. Pour 1 cup boiling water and mix well; cook covered on low for 90 minutes stirring every 15 minutes and adding hot water as needed. 7. When lamb is fork-tender uncover and cook off excess moisture; taste and adjust with salt and jaggery.", "tags": "goan, spicy, lamb", "source": "https://www.indianhealthyrecipes.com/lamb-vindaloo/", "nutritionData": "{\"calories\": 450, \"protein\": 34.0, \"carbs\": 10.0, \"fat\": 30.0}"},
  {"name": "Lucknowi Awadhi Biryani", "category": "Indian", "description": "Fragrant dum-cooked Awadhi biryani with saffron and cream layered over gently spiced chicken.", "servings": 5, "prepTime": 45, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"500g\", \"name\": \"chicken pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"thick plain yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"2 cups\", \"name\": \"basmati rice soaked 30 minutes\"}, {\"qty\": \"4 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1/4 cup\", \"name\": \"fried onions\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron dissolved in 2 tbsp warm milk\"}, {\"qty\": \"4 tbsp\", \"name\": \"cream\"}, {\"qty\": \"1 tsp\", \"name\": \"shahi jeera\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kewra water\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"handful of mint leaves\"}]", "instructions": "1. Marinate chicken with yogurt, ginger garlic paste, chili powder, garam masala, turmeric, and salt for 2 hours. 2. Make fried onions: thinly slice 2 onions and fry in ghee until deep golden; set aside. 3. Parboil drained rice with salted boiling water and shahi jeera until 90 percent done; drain and set aside. 4. Saute marinated chicken in remaining ghee with green chilies 3-4 minutes; add half the fried onions and cook on medium-low until chicken is fully cooked with a thick nearly-dry gravy. 5. In a wide heavy pot layer chicken at base; top with parboiled rice; scatter mint leaves and remaining fried onions. 6. Mix cream with saffron-milk and kewra water; drizzle over rice layer. 7. Seal pot tightly with foil then lid; cook on medium heat 10 minutes then on low 5-10 minutes; rest 10 minutes before serving.", "tags": "north-indian, biryani, rice", "source": "https://www.indianhealthyrecipes.com/awadhi-chicken-biryani-lucknowi-biryani/", "nutritionData": "{\"calories\": 580, \"protein\": 30.0, \"carbs\": 60.0, \"fat\": 22.0}"},
  {"name": "Tandoori Chicken", "category": "Indian", "description": "Yogurt-and-spice marinated chicken grilled to smoky perfection in oven or on grill.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 kg\", \"name\": \"chicken pieces skin removed\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"1/2 cup\", \"name\": \"thick plain yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tbsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"1 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chaat masala to finish\"}]", "instructions": "1. Score chicken pieces with deep cuts; rub with lemon juice, chili powder, and salt; rest 20 minutes. 2. Mix yogurt, ginger garlic paste, garam masala, coriander powder, cumin powder, turmeric, kasuri methi, and oil; coat chicken thoroughly. 3. Marinate covered in refrigerator for at least 4 hours or overnight. 4. Preheat oven to 450 F; place chicken on a wire rack over a foil-lined baking sheet. 5. Roast 20-22 minutes turning halfway until charred in spots and cooked through. 6. Optionally finish under broiler for 2 minutes for extra char. 7. Sprinkle chaat masala over chicken and serve with mint chutney and sliced onions.", "tags": "north-indian, grilled, chicken", "source": "https://www.indianhealthyrecipes.com/tandoori-chicken-recipe/", "nutritionData": "{\"calories\": 270, \"protein\": 36.0, \"carbs\": 5.0, \"fat\": 10.0}"},
  {"name": "Aloo Gobi", "category": "Indian", "description": "Homestyle dry-spiced cauliflower and potato curry with cumin, turmeric, and fresh ginger.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"medium potatoes peeled and cubed\"}, {\"qty\": \"1\", \"name\": \"small head cauliflower cut in florets\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1\", \"name\": \"medium onion finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes finely chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"amchur\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"chopped coriander leaves\"}]", "instructions": "1. Heat oil in a wide pan; add cumin seeds and let them sizzle; add onion and saute until translucent. 2. Add ginger garlic paste and cook 1 minute until fragrant. 3. Add tomatoes and cook 2 minutes until slightly soft; stir in turmeric, amchur, chili powder, and coriander powder. 4. Cover the pan and cook masala on medium heat 2-3 minutes. 5. Add potato cubes and cauliflower florets and garam masala; mix to coat with masala. 6. Cover and cook on low-medium heat 18-20 minutes stirring occasionally; add 1-2 tbsp water if masala sticks. 7. When vegetables are fork-tender add salt, garnish with coriander leaves, and serve hot with roti.", "tags": "north-indian, vegetarian, dry-curry", "source": "https://www.indianhealthyrecipes.com/aloo-gobi-recipe/", "nutritionData": "{\"calories\": 180, \"protein\": 5.0, \"carbs\": 26.0, \"fat\": 7.0}"},
  {"name": "Baingan Bharta", "category": "Indian", "description": "Smoky fire-roasted eggplant mashed with spiced onion-tomato for a classic Punjabi side.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large eggplants\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1\", \"name\": \"large onion finely chopped\"}, {\"qty\": \"2\", \"name\": \"green chilies chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger finely chopped\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes finely chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"coriander leaves chopped\"}]", "instructions": "1. Rub eggplants with oil and place directly on a stovetop flame; char on all sides turning with tongs for 15-20 minutes until completely soft inside; cool and peel. 2. Roughly mash the roasted eggplant pulp and set aside. 3. Heat oil in a saucepan; add cumin seeds; when they crackle add onions and green chilies; saute until golden. 4. Add ginger and saute 1 minute; add tomatoes and cook 5 minutes until soft and pulpy. 5. Stir in turmeric, chili powder, coriander powder, and salt; cook 2 minutes. 6. Add mashed eggplant; mix thoroughly and cook 5 minutes more. 7. Add garam masala, garnish with coriander leaves, and serve with roti or naan.", "tags": "north-indian, vegan, smoky", "source": "https://www.vegrecipesofindia.com/baingan-bharta-recipe-punjabi-baingan-bharta-recipe/", "nutritionData": "{\"calories\": 140, \"protein\": 3.0, \"carbs\": 15.0, \"fat\": 8.0}"},
  {"name": "Aloo Paratha", "category": "Indian", "description": "Flaky whole-wheat flatbread stuffed with spiced mashed potato and cooked in butter.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"whole wheat flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"water to knead\"}, {\"qty\": \"3\", \"name\": \"medium potatoes boiled and mashed\"}, {\"qty\": \"1\", \"name\": \"green chili finely chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"amchur\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"2 tbsp\", \"name\": \"coriander leaves finely chopped\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter or ghee for cooking\"}]", "instructions": "1. Mix flour, 1/2 tsp salt, and water; knead into a smooth soft dough; cover and rest 20 minutes. 2. Combine mashed potatoes, green chili, chili powder, garam masala, amchur, cumin, coriander leaves, and salt; divide into 8 equal portions. 3. Divide dough into 8 balls; roll each into a 4-inch circle; place a potato filling ball in the center; gather edges and seal. 4. Gently roll the stuffed dough ball into a 7-8 inch round paratha; press evenly to avoid tearing. 5. Heat a griddle on medium-high; place paratha and cook 1-2 minutes until bubbles appear and underside is lightly golden. 6. Flip; apply butter or ghee; cook 1 minute; flip again; apply butter on the other side; press gently and cook until both sides are golden brown and crisp. 7. Serve hot with plain yogurt, pickle, or butter.", "tags": "north-indian, bread, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 320, \"protein\": 8.0, \"carbs\": 48.0, \"fat\": 11.0}"},
  {"name": "Methi Chicken", "category": "Indian", "description": "Tender chicken cooked with fresh fenugreek leaves in a fragrant North Indian onion-tomato gravy.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"700g\", \"name\": \"chicken pieces bone-in\"}, {\"qty\": \"2 cups\", \"name\": \"fresh fenugreek leaves packed\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2\", \"name\": \"medium onions finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes pureed\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 cup\", \"name\": \"plain yogurt whisked\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"coriander leaves to garnish\"}]", "instructions": "1. Wash fenugreek leaves well; sprinkle with a pinch of salt, rest 5 minutes, then squeeze out excess moisture. 2. Heat oil in a heavy pan; add bay leaf then onions; saute on medium heat until deep golden about 10 minutes. 3. Add ginger garlic paste and cook 2 minutes until fragrant. 4. Add tomato puree and cook on medium heat until oil separates about 6-8 minutes. 5. Stir in chili powder, turmeric, coriander powder, and salt; saute 2 minutes. 6. Add chicken pieces and stir to coat; cook on high heat 3 minutes then reduce to medium; stir in whisked yogurt and fenugreek leaves. 7. Cook covered on low heat 20-25 minutes until chicken is cooked through; stir in garam masala, garnish with coriander, and serve with roti.", "tags": "north-indian, chicken, fenugreek", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 30.0, \"carbs\": 10.0, \"fat\": 19.0}"},
  {"name": "Masala Dosa", "category": "Indian", "description": "Crispy South Indian rice-and-lentil crepe filled with spiced potato masala served with sambar.", "servings": 4, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"parboiled rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"urad dal\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fenugreek seeds\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"3\", \"name\": \"medium potatoes boiled and mashed\"}, {\"qty\": \"1\", \"name\": \"medium onion sliced\"}, {\"qty\": \"2\", \"name\": \"green chilies chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger grated\"}, {\"qty\": \"1/2 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"urad dal for tempering\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"\", \"name\": \"oil or ghee for dosa\"}]", "instructions": "1. Soak rice and fenugreek separately; soak urad dal separately for 5-6 hours; blend each smooth; combine with salt and ferment overnight. 2. For potato masala: heat 1 tbsp oil; crackle mustard and cumin; add curry leaves, green chilies, ginger, onion, and turmeric; saute until onions soften. 3. Add mashed potatoes and a few tbsp water; mix and cook 2 minutes; adjust salt; set aside. 4. Thin fermented batter with water to a spreading consistency; heat a cast iron tawa until very hot; pour a ladle of batter and spread in a spiral to a thin crepe. 5. Drizzle oil around edges; cook on medium-high until underside is crisp and golden. 6. Place a portion of potato masala in the center; fold dosa over filling. 7. Serve immediately with coconut chutney and sambar.", "tags": "south-indian, vegan, fermented", "source": "https://www.indianhealthyrecipes.com/masala-dosa-recipe/", "nutritionData": "{\"calories\": 380, \"protein\": 10.0, \"carbs\": 62.0, \"fat\": 10.0}"},
  {"name": "Idli with Tiffin Sambar", "category": "Indian", "description": "Soft steamed rice-lentil cakes paired with tangy spiced vegetable sambar.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"parboiled rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"urad dal\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fenugreek seeds\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"1/2 cup\", \"name\": \"toor dal\"}, {\"qty\": \"1/2 cup\", \"name\": \"mixed vegetables (carrot, potato, onion, tomato)\"}, {\"qty\": \"1 tbsp\", \"name\": \"tamarind pulp\"}, {\"qty\": \"1 tsp\", \"name\": \"sambar powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"2\", \"name\": \"dried red chilies\"}, {\"qty\": \"1 pinch\", \"name\": \"asafoetida\"}, {\"qty\": \"2 tsp\", \"name\": \"oil\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Soak rice and fenugreek seeds together and urad dal separately for 5-6 hours; grind separately to smooth batters; combine with salt and ferment overnight. 2. Grease idli molds; pour batter to 3/4 full; steam 10-12 minutes until a toothpick comes out clean; rest 2 minutes before unmolding. 3. Pressure cook toor dal with turmeric and 2 cups water for 2 whistles; mash and set aside. 4. In a pot add vegetables, tamarind pulp, sambar powder, salt, and 1.5 cups water; cook until vegetables are tender. 5. Stir in mashed dal; bring to a simmer. 6. For tempering: heat oil in a small pan; crackle mustard and cumin; add dried chilies, curry leaves, and asafoetida; pour over sambar. 7. Serve hot idlis with sambar and coconut chutney.", "tags": "south-indian, vegan, fermented", "source": "https://www.indianhealthyrecipes.com/idli-sambar-recipe-tiffin-sambar/", "nutritionData": "{\"calories\": 220, \"protein\": 9.0, \"carbs\": 40.0, \"fat\": 3.0}"},
  {"name": "Uttapam", "category": "Indian", "description": "Thick South Indian rice pancakes topped with onions, tomatoes, and green chilies.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"parboiled rice\"}, {\"qty\": \"1/2 cup\", \"name\": \"urad dal\"}, {\"qty\": \"1/4 tsp\", \"name\": \"fenugreek seeds\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"1\", \"name\": \"medium onion finely chopped\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes finely chopped\"}, {\"qty\": \"2\", \"name\": \"green chilies finely chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"coriander leaves chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"oil per uttapam\"}]", "instructions": "1. Prepare fermented idli-dosa batter by soaking rice and urad dal separately 5-6 hours; blend; ferment overnight or use ready batter. 2. Mix chopped onions, tomatoes, green chilies, and coriander leaves in a bowl. 3. Heat a non-stick tawa on medium heat; pour a large ladle of batter and gently spread to a thick pancake about 6 inches wide. 4. Immediately scatter a generous portion of the vegetable topping over the wet batter; press lightly with spatula so they adhere. 5. Drizzle oil around edges; cook on medium heat until underside is golden and set about 3-4 minutes. 6. Flip carefully and cook the topping side until onions are lightly caramelized 2-3 minutes more. 7. Serve hot uttapam with sambar and coconut chutney.", "tags": "south-indian, vegan, breakfast", "source": "https://www.vegrecipesofindia.com/uttapam-recipe/", "nutritionData": "{\"calories\": 230, \"protein\": 7.0, \"carbs\": 40.0, \"fat\": 5.0}"},
  {"name": "Chettinad Pepper Chicken", "category": "Indian", "description": "Intensely spiced South Indian dry chicken curry ground with fresh peppercorns and aromatic masala.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"700g\", \"name\": \"chicken pieces bone-in\"}, {\"qty\": \"2 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"3\", \"name\": \"green cardamoms\"}, {\"qty\": \"2\", \"name\": \"cloves\"}, {\"qty\": \"1\", \"name\": \"inch cinnamon\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"2\", \"name\": \"medium onions finely chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"2 tsp\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"coriander leaves to garnish\"}]", "instructions": "1. Heat oil in a heavy kadai; crackle mustard and cumin seeds; add cardamoms, cloves, and cinnamon; saute 30 seconds. 2. Add onions and curry leaves; cook on medium heat until onions are deep golden stirring often. 3. Add ginger garlic paste; fry 1-2 minutes until fragrant. 4. Add tomatoes; cook until soft and oil begins to separate. 5. Stir in chili powder, coriander powder, turmeric, and salt; saute 2 minutes. 6. Add chicken pieces; mix well; cook on high heat 3 minutes then reduce to medium-low; cover and cook 20-25 minutes until chicken is cooked through stirring occasionally. 7. Uncover, increase heat, stir in freshly ground pepper; cook 3-5 minutes until masala coats chicken; garnish with coriander leaves.", "tags": "south-indian, spicy, chicken", "source": "Classic", "nutritionData": "{\"calories\": 350, \"protein\": 30.0, \"carbs\": 8.0, \"fat\": 22.0}"},
  {"name": "Kerala Coconut Fish Curry", "category": "Indian", "description": "Flaky fish simmered in a tangy tamarind-coconut milk curry with warming spices.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"500g\", \"name\": \"firm fish fillets cubed\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"fenugreek seeds\"}, {\"qty\": \"1\", \"name\": \"large onion thinly sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"2\", \"name\": \"green chilies slit\"}, {\"qty\": \"1 tsp\", \"name\": \"Kashmiri red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tbsp\", \"name\": \"tamarind pulp\"}, {\"qty\": \"1 cup\", \"name\": \"coconut milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Heat coconut oil in a clay pot or kadai; crackle mustard and fenugreek seeds. 2. Add onions, curry leaves, and green chilies; saute until onions are lightly golden. 3. Add ginger garlic paste; cook 1 minute; reduce heat and stir in chili powder, coriander powder, and turmeric; saute 3-4 minutes. 4. Stir in tamarind pulp and water; bring to a boil. 5. Add fish pieces; cook partially covered on medium heat 8-10 minutes gently shaking the pan rather than stirring to avoid breaking fish. 6. Pour in coconut milk; simmer on low heat 3-4 minutes until fish is cooked through and curry is creamy. 7. Drizzle extra coconut oil on top and garnish with curry leaves; serve with steamed rice.", "tags": "south-indian, seafood, coconut", "source": "Classic", "nutritionData": "{\"calories\": 310, \"protein\": 22.0, \"carbs\": 10.0, \"fat\": 20.0}"},
  {"name": "Macher Jhol", "category": "Indian", "description": "Light Bengali fish curry with potatoes in mustard oil with nigella seeds and fresh spices.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"600g\", \"name\": \"fresh water fish (rohu or catla) cleaned and cut\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"\", \"name\": \"salt\"}, {\"qty\": \"4 tbsp\", \"name\": \"mustard oil\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"1/2 tsp\", \"name\": \"nigella seeds\"}, {\"qty\": \"2\", \"name\": \"green chilies slit\"}, {\"qty\": \"1\", \"name\": \"medium onion blended to paste\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger paste\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1\", \"name\": \"medium tomato chopped\"}, {\"qty\": \"2\", \"name\": \"medium potatoes quartered\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1.5 cups\", \"name\": \"hot water\"}]", "instructions": "1. Rub fish with turmeric and salt; rest 10 minutes. 2. Heat mustard oil in a heavy wok until slightly smoky; shallow fry fish 2 minutes per side until lightly crisp; remove to a plate. 3. In remaining oil fry potatoes until lightly golden; remove. 4. Crackle bay leaf and nigella seeds in the oil; add green chilies. 5. Add onion paste; brown on medium heat 3 minutes; add ginger and garlic pastes with spice powders and a splash of water; fry 2-3 minutes until oil separates. 6. Add tomato, sugar, and salt; cook 2 minutes; pour in hot water; bring to a boil; add fried potatoes and simmer 5 minutes. 7. Gently add fried fish; simmer 6-8 minutes until cooked through; squeeze lime juice over and rest 15 minutes before serving with rice.", "tags": "east-indian, bengali, seafood", "source": "Classic", "nutritionData": "{\"calories\": 290, \"protein\": 22.0, \"carbs\": 16.0, \"fat\": 15.0}"},
  {"name": "Kosha Mangsho", "category": "Indian", "description": "Slow-cooked Bengali mutton curry with deeply browned onions and warming whole spices.", "servings": 4, "prepTime": 20, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"700g\", \"name\": \"bone-in goat mutton cut in pieces\"}, {\"qty\": \"1/4 cup\", \"name\": \"plain yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"mustard oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"4 tbsp\", \"name\": \"mustard oil for cooking\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"2\", \"name\": \"black cardamoms\"}, {\"qty\": \"4\", \"name\": \"green cardamoms\"}, {\"qty\": \"1\", \"name\": \"inch cinnamon\"}, {\"qty\": \"4\", \"name\": \"cloves\"}, {\"qty\": \"2\", \"name\": \"dried red chilies\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"3\", \"name\": \"large onions thinly sliced\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger paste\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic paste\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"whisked yogurt\"}, {\"qty\": \"1 tbsp\", \"name\": \"garam masala\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Marinate mutton with yogurt, 1 tbsp mustard oil, ginger garlic paste, and salt; refrigerate 3-4 hours. 2. Heat 4 tbsp mustard oil in a large heavy pan; add bay leaves, lightly crushed cardamoms, cinnamon, cloves, dried chilies, and sugar; fry 5 seconds. 3. Add onions; cook on medium heat 15-20 minutes stirring often until very deep golden-brown. 4. Add ginger and garlic pastes; cook 2 minutes; stir in chili powder, turmeric, and coriander powder. 5. Add marinated mutton with its marinade; sear on high heat 5-6 minutes until browned. 6. Reduce heat to low; cover and cook 70-80 minutes stirring every 5-7 minutes and adding splashes of water to prevent sticking until mutton is very tender. 7. Stir in whisked yogurt and garam masala; cook uncovered 5 minutes; adjust salt and serve with rice or luchi.", "tags": "east-indian, bengali, mutton", "source": "https://www.whiskaffair.com/bengali-kosha-mangsho-recipe/", "nutritionData": "{\"calories\": 420, \"protein\": 32.0, \"carbs\": 10.0, \"fat\": 28.0}"},
  {"name": "Pav Bhaji", "category": "Indian", "description": "Buttery Mumbai street food: a thick spiced vegetable mash served with toasted bread rolls.", "servings": 5, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"medium potatoes peeled and cubed\"}, {\"qty\": \"1 cup\", \"name\": \"green peas\"}, {\"qty\": \"1 cup\", \"name\": \"cauliflower florets\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1\", \"name\": \"large onion finely chopped\"}, {\"qty\": \"1\", \"name\": \"green chili chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"1\", \"name\": \"medium red bell pepper finely chopped\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes finely chopped\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"pav bhaji masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"kasuri methi\"}, {\"qty\": \"\", \"name\": \"lemon juice to taste\"}, {\"qty\": \"\", \"name\": \"coriander leaves to garnish\"}, {\"qty\": \"10\", \"name\": \"dinner rolls pav\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter for toasting\"}]", "instructions": "1. Pressure cook potatoes, peas, and cauliflower with 1.5 cups water for 1-2 whistles until soft; mash well. 2. Heat butter and oil in a large pan; crackle cumin; add onions and green chili; saute until translucent. 3. Add ginger garlic paste and fry 30 seconds; add bell pepper and cook 2 minutes. 4. Add tomatoes and salt; cook until mushy 5-6 minutes stirring often. 5. Stir in pav bhaji masala, chili powder, and turmeric; saute 2 minutes. 6. Add mashed vegetables and 1/2 cup water; mash together and simmer on low 10 minutes; stir in kasuri methi and lemon juice; adjust salt. 7. Toast pav buns on a buttered griddle sprinkled with pav bhaji masala until golden; serve alongside bhaji garnished with coriander, butter, and chopped onions.", "tags": "west-indian, mumbai, vegan-adaptable", "source": "https://www.indianhealthyrecipes.com/pav-bhaji-recipe-how-to-make-pav-bhaji-step-by-step-pictures/", "nutritionData": "{\"calories\": 430, \"protein\": 10.0, \"carbs\": 62.0, \"fat\": 15.0}"},
  {"name": "Dhokla", "category": "Indian", "description": "Soft and spongy steamed Gujarati gram-flour snack with a sweet-spicy mustard tempering.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"besan (gram flour)\"}, {\"qty\": \"1 tbsp\", \"name\": \"fine semolina\"}, {\"qty\": \"1 cup\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"citric acid\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1 tsp\", \"name\": \"grated ginger\"}, {\"qty\": \"2\", \"name\": \"green chilies paste\"}, {\"qty\": \"1 tsp\", \"name\": \"fruit salt (Eno)\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tsp\", \"name\": \"oil for tempering\"}, {\"qty\": \"1/2 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"\", \"name\": \"7-8 curry leaves\"}, {\"qty\": \"1\", \"name\": \"green chili sliced\"}, {\"qty\": \"1/3 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"coriander leaves and coconut for garnish\"}]", "instructions": "1. Sift besan and semolina together in a large bowl; set aside. 2. Whisk together 1 cup water, 2 tbsp sugar, salt, ginger-green chili paste, turmeric, 1.5 tbsp oil, and citric acid until sugar dissolves; pour over besan and stir to a thick but flowing batter. 3. Grease a 9-inch steamer pan with oil; heat steamer with boiling water. 4. Just before steaming add Eno to batter; stir briskly until it foams; immediately pour into greased pan. 5. Steam on medium heat 15-17 minutes; test with a toothpick; cool 10 minutes. 6. For tempering: heat oil in a small pan; crackle mustard seeds; add curry leaves and green chili; add 1/3 cup water with 1 tsp sugar and a pinch of salt; remove from heat. 7. Cut dhokla into squares; pour tempering evenly over pieces; garnish with coriander and fresh coconut; serve with green chutney.", "tags": "west-indian, gujarati, vegetarian", "source": "https://www.vegrecipesofindia.com/khaman-dhokla-microwave-recipe/", "nutritionData": "{\"calories\": 170, \"protein\": 8.0, \"carbs\": 28.0, \"fat\": 4.0}"},
  {"name": "Goan Prawn Curry", "category": "Indian", "description": "Succulent prawns in a bright coconut-tamarind curry with Kashmiri chilies and ground spices.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"500g\", \"name\": \"medium prawns deveined\"}, {\"qty\": \"1 cup\", \"name\": \"fresh grated coconut\"}, {\"qty\": \"1 cup\", \"name\": \"coconut milk\"}, {\"qty\": \"5\", \"name\": \"dried Kashmiri red chilies\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"coriander seeds\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"7\", \"name\": \"garlic cloves\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"tamarind pulp\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil\"}, {\"qty\": \"1\", \"name\": \"medium onion finely chopped\"}, {\"qty\": \"1\", \"name\": \"small tomato chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"2\", \"name\": \"green chilies slit\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Dry roast coriander seeds, cumin seeds, and black pepper in a dry pan until aromatic. 2. Blend roasted spices with coconut, Kashmiri chilies, garlic, and tamarind pulp with enough water into a smooth paste; set aside. 3. Heat coconut oil in a pan; saute onion until lightly golden; add tomato and cook 5-7 minutes until broken down. 4. Add turmeric and salt; stir in ground coconut masala paste; saute 3-4 minutes until raw smell goes. 5. Pour in coconut milk; bring to a boil; reduce heat and simmer 10-15 minutes until color deepens slightly. 6. Add prawns and green chilies; cook 5-7 minutes just until prawns curl and turn pink; do not overcook. 7. Scatter curry leaves on top; rest 5 minutes and serve over steamed rice.", "tags": "west-indian, goan, seafood", "source": "Classic", "nutritionData": "{\"calories\": 280, \"protein\": 20.0, \"carbs\": 12.0, \"fat\": 17.0}"},
  {"name": "Lemon Rice", "category": "Indian", "description": "Bright South Indian rice tempered with mustard seeds, curry leaves, peanuts, and fresh lemon juice.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"cooked basmati or sona masoori rice cooled\"}, {\"qty\": \"3 tbsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"mustard seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"urad dal\"}, {\"qty\": \"1 tsp\", \"name\": \"chana dal\"}, {\"qty\": \"1/4 tsp\", \"name\": \"asafoetida\"}, {\"qty\": \"2\", \"name\": \"dried red chilies\"}, {\"qty\": \"2\", \"name\": \"green chilies chopped\"}, {\"qty\": \"1 sprig\", \"name\": \"curry leaves\"}, {\"qty\": \"1/4 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"3 tbsp\", \"name\": \"roasted peanuts\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"coriander leaves chopped\"}]", "instructions": "1. Spread cold cooked rice on a tray; sprinkle turmeric and toss gently so grains are coated; set aside. 2. Heat oil in a wide pan; crackle mustard seeds; add cumin, urad dal, and chana dal; fry until dals turn golden. 3. Add asafoetida, dried red chilies, green chilies, and curry leaves; fry 30 seconds until leaves turn crisp. 4. Add roasted peanuts and toss 30 seconds. 5. Add turmeric-coated rice; gently mix so tempering is evenly distributed; heat through on low-medium heat 2-3 minutes. 6. Remove from heat; pour lemon juice evenly over rice; toss gently; taste and adjust salt and lemon. 7. Garnish with coriander leaves and serve warm with yogurt or pickle.", "tags": "south-indian, vegetarian, quick", "source": "https://www.sailusfood.com/lemon-rice-recipe-nimmakaya-annam", "nutritionData": "{\"calories\": 260, \"protein\": 6.0, \"carbs\": 40.0, \"fat\": 9.0}"},
  {"name": "Samosas", "category": "Indian", "description": "Crispy fried pastry triangles filled with spiced potato and peas — India's most beloved street snack.", "servings": 6, "prepTime": 40, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"carom seeds\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"melted ghee\"}, {\"qty\": \"1/2 cup\", \"name\": \"water approximately\"}, {\"qty\": \"3\", \"name\": \"medium potatoes boiled and mashed\"}, {\"qty\": \"1/2 cup\", \"name\": \"green peas cooked\"}, {\"qty\": \"2 tsp\", \"name\": \"oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"2\", \"name\": \"green chilies finely chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"ginger paste\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1 tsp\", \"name\": \"chaat masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"2 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"\", \"name\": \"oil for deep frying\"}]", "instructions": "1. Rub ghee into flour with carom seeds and salt until mixture resembles coarse sand; add water gradually to form a firm smooth dough; cover and rest 20 minutes. 2. Heat 2 tsp oil in a pan; crackle cumin; add green chilies and ginger paste; fry 1 minute; add peas. 3. Add chili powder, coriander powder, chaat masala, and garam masala; mix; stir in mashed potatoes and lemon juice; taste and adjust salt; cool completely. 4. Divide dough into 12 balls; roll each into a 6-inch oval; cut in half; form each half into a cone by sealing the straight edge. 5. Fill each cone with potato stuffing; seal the open edge with water; press firmly. 6. Heat oil for deep frying to medium-low; fry samosas in batches 10-12 minutes turning occasionally until golden brown and crisp. 7. Drain on paper towels and serve hot with mint chutney and tamarind chutney.", "tags": "street-food, vegetarian, snack", "source": "https://www.indianhealthyrecipes.com/samosa-recipe-make-samosa/", "nutritionData": "{\"calories\": 280, \"protein\": 6.0, \"carbs\": 36.0, \"fat\": 13.0}"},
  {"name": "Papdi Chaat", "category": "Indian", "description": "Crunchy wheat crackers layered with chickpeas, yogurt, chutneys, and savory-sweet spice mix.", "servings": 4, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"20\", \"name\": \"papdi crackers store-bought\"}, {\"qty\": \"1 cup\", \"name\": \"boiled chickpeas\"}, {\"qty\": \"2\", \"name\": \"medium boiled potatoes cubed\"}, {\"qty\": \"1 cup\", \"name\": \"plain yogurt whisked smooth\"}, {\"qty\": \"2 tbsp\", \"name\": \"green chutney (coriander-mint)\"}, {\"qty\": \"2 tbsp\", \"name\": \"tamarind chutney\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chaat masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"roasted cumin powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}, {\"qty\": \"\", \"name\": \"sev (fried chickpea noodles) handful\"}, {\"qty\": \"\", \"name\": \"coriander leaves chopped\"}]", "instructions": "1. Arrange papdi crackers in a single layer on a serving plate. 2. Scatter boiled chickpeas and cubed potatoes evenly over the papdis. 3. Whisk yogurt with a pinch of salt; drizzle generously over the chickpeas and potatoes. 4. Drizzle green chutney and tamarind chutney evenly over the yogurt layer. 5. Sprinkle chaat masala, roasted cumin powder, and red chili powder over the entire plate. 6. Top with a generous handful of sev. 7. Garnish with coriander leaves and a final drizzle of tamarind chutney; serve immediately so papdis stay crisp.", "tags": "street-food, vegetarian, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 310, \"protein\": 10.0, \"carbs\": 50.0, \"fat\": 8.0}"},
  {"name": "Kheer", "category": "Indian", "description": "Slow-cooked Indian rice pudding with saffron, cardamom, and a garnish of toasted nuts.", "servings": 4, "prepTime": 5, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"basmati rice rinsed and soaked 15 minutes\"}, {\"qty\": \"4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"5 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"green cardamom powder\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron strands\"}, {\"qty\": \"1 tbsp\", \"name\": \"warm milk for saffron\"}, {\"qty\": \"1 tbsp\", \"name\": \"slivered almonds\"}, {\"qty\": \"1 tbsp\", \"name\": \"chopped cashews\"}, {\"qty\": \"1 tbsp\", \"name\": \"slivered pistachios\"}, {\"qty\": \"1 tbsp\", \"name\": \"golden raisins\"}, {\"qty\": \"1 tsp\", \"name\": \"rose water (optional)\"}]", "instructions": "1. Pour milk into a heavy-bottom pot; bring to a boil on medium heat stirring often to prevent scorching. 2. Drain soaked rice; add to hot milk; stir well. 3. Simmer on low-medium heat 25-30 minutes stirring every 3 minutes until rice is completely soft and slightly mushy. 4. Add sugar; stir to dissolve; continue simmering 10 minutes until kheer thickens but still flows. 5. Steep saffron in warm milk; stir into kheer along with cardamom powder and nuts. 6. Cook 2-3 more minutes; remove from heat as kheer will thicken further on cooling. 7. Add rose water if using; serve warm or chilled garnished with pistachios and saffron strands.", "tags": "dessert, vegetarian, slow-cook", "source": "https://www.indianhealthyrecipes.com/rice-kheer-recipe-chawal-ki-kheer/", "nutritionData": "{\"calories\": 290, \"protein\": 8.0, \"carbs\": 46.0, \"fat\": 8.0}"},
  {"name": "Gulab Jamun", "category": "Indian", "description": "Soft milk-powder dumplings deep-fried and soaked in a fragrant saffron-cardamom sugar syrup.", "servings": 6, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"milk powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee melted\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk approximately\"}, {\"qty\": \"2 cups\", \"name\": \"sugar\"}, {\"qty\": \"1.5 cups\", \"name\": \"water\"}, {\"qty\": \"5\", \"name\": \"green cardamom pods crushed\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron\"}, {\"qty\": \"1 tsp\", \"name\": \"rose water\"}, {\"qty\": \"\", \"name\": \"oil for deep frying\"}]", "instructions": "1. Make syrup: combine sugar, water, and cardamom in a saucepan; heat until sugar dissolves; simmer 5 minutes; add rose water and saffron; keep warm. 2. Sift milk powder, flour, and baking soda; rub in melted ghee until mixture resembles coarse crumbs. 3. Add milk a tablespoon at a time; knead gently into a soft smooth dough without cracks; do not over-knead; rest 5 minutes. 4. Divide dough into 20-22 equal portions; roll each into a smooth crack-free ball. 5. Heat oil to medium heat and fry gulab jamun in batches on medium-low heat 4-5 minutes gently swirling until deep golden brown. 6. Drain briefly and immediately transfer to warm sugar syrup; coat on all sides; cover and soak 30 minutes until they have absorbed the syrup and plumped up. 7. Serve warm or at room temperature garnished with crushed pistachios.", "tags": "dessert, vegetarian, deep-fried", "source": "https://www.indianhealthyrecipes.com/gulab-jamun-recipe-using-milk-powder/", "nutritionData": "{\"calories\": 340, \"protein\": 7.0, \"carbs\": 52.0, \"fat\": 12.0}"},
  {"name": "Mango Lassi", "category": "Indian", "description": "Creamy blended drink of ripe mango pulp, yogurt, and a hint of cardamom.", "servings": 2, "prepTime": 5, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"ripe mango pulp (fresh or canned Alphonso)\"}, {\"qty\": \"1 cup\", \"name\": \"plain whole-milk yogurt\"}, {\"qty\": \"1/2 cup\", \"name\": \"cold whole milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar or to taste\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cardamom\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron (optional)\"}, {\"qty\": \"\", \"name\": \"ice cubes\"}]", "instructions": "1. If using fresh mango peel, cube, and blend to a smooth pulp. 2. Add mango pulp, yogurt, milk, sugar, and cardamom to a blender. 3. Blend on high for 60 seconds until completely smooth and frothy. 4. Taste and adjust sweetness; if too thick add a splash more milk. 5. Add ice cubes and blend briefly or serve over ice. 6. Pour into tall glasses. 7. Garnish with a pinch of saffron, a slice of mango, or a dusting of cardamom and serve immediately.", "tags": "drink, vegetarian, quick", "source": "Classic", "nutritionData": "{\"calories\": 220, \"protein\": 7.0, \"carbs\": 38.0, \"fat\": 5.0}"},
  {"name": "Palak Paneer Dhaba Style", "category": "Indian", "description": "Rustic roadside-style spinach and paneer curry with a charred onion base and robust spices.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"400g\", \"name\": \"fresh spinach leaves blanched\"}, {\"qty\": \"200g\", \"name\": \"paneer cubed\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1\", \"name\": \"medium onion roughly chopped and charred\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger garlic paste\"}, {\"qty\": \"2\", \"name\": \"green chilies\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"red chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cream\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Blanch spinach in boiling salted water 2 minutes; drain and blend with green chilies to a coarse-smooth puree; set aside. 2. Char onion quarters directly on flame or under broiler until edges are blackened; cool and roughly chop. 3. Heat ghee in a heavy kadai; crackle cumin seeds; add charred onion and ginger garlic paste; fry 2-3 minutes. 4. Add tomatoes; cook on medium heat until very soft and oil separates; stir in turmeric, chili powder, and coriander powder. 5. Pour in spinach puree; mix; simmer 5 minutes; season with salt. 6. Add paneer cubes; fold in gently; simmer 3-4 minutes. 7. Stir in cream and garam masala; serve hot with roti or paratha.", "tags": "north-indian, paneer, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 360, \"protein\": 18.0, \"carbs\": 12.0, \"fat\": 27.0}"},
  {"name": "Masala Chai", "category": "Indian", "description": "Robust spiced Indian tea simmered with ginger, cardamom, and cinnamon and finished with milk.", "servings": 2, "prepTime": 2, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3 tsp\", \"name\": \"loose black tea (Assam)\"}, {\"qty\": \"1\", \"name\": \"inch ginger grated\"}, {\"qty\": \"4\", \"name\": \"green cardamom pods lightly crushed\"}, {\"qty\": \"1\", \"name\": \"small cinnamon stick\"}, {\"qty\": \"2\", \"name\": \"cloves\"}, {\"qty\": \"4 tsp\", \"name\": \"sugar or to taste\"}]", "instructions": "1. Combine water, grated ginger, crushed cardamom, cinnamon stick, and cloves in a small saucepan. 2. Bring to a boil over medium heat; reduce and simmer 3-4 minutes to extract spice flavors. 3. Add black tea leaves; simmer 1-2 minutes. 4. Pour in milk; stir and bring to a full rolling boil watching carefully to avoid overflow. 5. Reduce heat and gently simmer 2-3 minutes until tea is a deep golden-brown color. 6. Add sugar; stir to dissolve; taste and adjust. 7. Strain through a fine-mesh strainer into cups and serve hot.", "tags": "drink, vegetarian, quick", "source": "Classic", "nutritionData": "{\"calories\": 110, \"protein\": 4.0, \"carbs\": 18.0, \"fat\": 3.0}"},
  {"name": "Saltimbocca alla Romana", "category": "Italian Regional", "description": "Tender veal cutlets topped with prosciutto and sage, pan-seared in a buttery white-wine sauce.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"thin veal scallopini (about 1.5 lb)\"}, {\"qty\": \"8 slices\", \"name\": \"prosciutto di Parma\"}, {\"qty\": \"16\", \"name\": \"fresh sage leaves\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Place a slice of prosciutto and two sage leaves on each veal piece; secure with a toothpick. 2. Season lightly with pepper and dredge the veal side only in flour, shaking off excess. 3. Heat olive oil and 2 tbsp butter in a large skillet over medium-high heat. 4. Add veal prosciutto-side down and cook 2 minutes until prosciutto is crisp; flip and cook 1 minute more. Transfer to a platter. 5. Pour wine into the skillet, scraping up any browned bits, and reduce by half. 6. Remove from heat, swirl in remaining butter, and pour sauce over the saltimbocca. Remove toothpicks and serve immediately.", "tags": "lazio, roman, quick, stovetop", "source": "Classic", "nutritionData": "{\"calories\": 363, \"protein\": 13.0, \"carbs\": 12.0, \"fat\": 29.0}"},
  {"name": "Supplì al Telefono", "category": "Italian Regional", "description": "Crispy Roman fried rice balls with a molten mozzarella center, named for the cheese strands that stretch like a telephone wire.", "servings": 6, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"3 cups\", \"name\": \"tomato passata\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"4 oz\", \"name\": \"fresh mozzarella cut into cubes\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"plain breadcrumbs\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Sauté onion in olive oil until soft; add ground beef and brown, breaking it up. 2. Add wine, cook 1 minute, then add passata and simmer 20 minutes until thick. Season with salt and pepper. 3. Stir in dry rice and cook with the sauce, adding water as needed, until rice is just cooked. Stir in Parmigiano. Spread on a tray and cool completely in the fridge for at least 1 hour. 4. With damp hands, form oblong rice balls around a cube of mozzarella. 5. Dredge in flour, dip in beaten egg, then coat in breadcrumbs. 6. Deep-fry in 350°F vegetable oil for 3–4 minutes until golden. Drain on paper towels and serve hot.", "tags": "lazio, roman, fried, appetizer, street food", "source": "https://www.sipandfeast.com/arancini/", "nutritionData": "{\"calories\": 572, \"protein\": 24.0, \"carbs\": 72.0, \"fat\": 19.0}"},
  {"name": "Coda alla Vaccinara", "category": "Italian Regional", "description": "Rich Roman braised oxtail stewed with tomato, celery, pine nuts, and dark chocolate in the traditional butcher-quarter style.", "servings": 6, "prepTime": 30, "cookTime": 180, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"oxtail cut into 2-inch sections\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"4\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"1 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"2 cups\", \"name\": \"tomato passata\"}, {\"qty\": \"1/2 cup\", \"name\": \"pine nuts\"}, {\"qty\": \"2 tbsp\", \"name\": \"raisins\"}, {\"qty\": \"1 oz\", \"name\": \"dark chocolate grated\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Season oxtail with salt and pepper. Brown in olive oil in a large Dutch oven over high heat in batches; set aside. 2. In the same pot, sauté onion, garlic, and half the celery over medium heat until soft. Add tomato paste and cook 3 minutes. 3. Return oxtail to pot, add wine and cook 2 minutes. Add passata, cinnamon, and enough water to nearly submerge meat. 4. Cover and braise on lowest heat for 2.5–3 hours until meat is very tender. 5. Stir in remaining celery, pine nuts, raisins, and grated chocolate; simmer uncovered 20 minutes. 6. Adjust seasoning and finish with parsley. Serve with crusty bread or polenta.", "tags": "lazio, roman, braised, offal, slow-cook", "source": "Classic", "nutritionData": "{\"calories\": 420, \"protein\": 32.0, \"carbs\": 12.0, \"fat\": 28.0}"},
  {"name": "Abbacchio Scottadito", "category": "Italian Regional", "description": "Chargrilled Roman lamb chops marinated with garlic, rosemary, and lemon, cooked hot enough to \"burn the fingers\" at the table.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"small lamb rib chops (about 12 chops)\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary leaves stripped and minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Pound lamb chops gently to flatten to about 1/2-inch thickness. 2. Whisk together garlic, rosemary, olive oil, lemon juice, and red pepper. Coat chops and marinate 15 minutes at room temperature. 3. Heat a grill or cast-iron pan to very high heat. 4. Season chops with salt and pepper; grill 2–3 minutes per side for medium-rare. 5. Serve immediately with lemon wedges.", "tags": "lazio, roman, grilled, lamb, quick", "source": "Classic", "nutritionData": "{\"calories\": 380, \"protein\": 35.0, \"carbs\": 2.0, \"fat\": 26.0}"},
  {"name": "Ribollita", "category": "Italian Regional", "description": "Hearty Tuscan bread-and-bean soup thickened with day-old bread and lacinato kale, slow-simmered for deep flavor.", "servings": 6, "prepTime": 20, "cookTime": 60, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/4 pound\", \"name\": \"pancetta diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"1\", \"name\": \"large carrot chopped\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"bunch Tuscan kale stems removed, chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"5 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 cans\", \"name\": \"cannellini beans drained\"}, {\"qty\": \"6 cups\", \"name\": \"low-sodium chicken stock\"}, {\"qty\": \"1\", \"name\": \"rind Parmigiano Reggiano\"}, {\"qty\": \"1 sprig\", \"name\": \"rosemary\"}, {\"qty\": \"1\", \"name\": \"loaf day-old crusty bread sliced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"extra-virgin olive oil for finishing\"}]", "instructions": "1. Cook pancetta in a large heavy pot over medium heat until the fat renders, about 5 minutes. 2. Add olive oil, onion, celery, and carrot; cook until soft, 10 minutes. Add garlic, cook 2 minutes. Add red pepper flakes and tomato paste; cook 5 minutes. 3. Add stock, kale, cannellini beans, Parmigiano rind, and rosemary. Bring to a boil, then simmer with lid cracked for 30 minutes. 4. Season with salt and pepper. Place thick slices of day-old bread in individual bowls and ladle soup on top. 5. Drizzle with extra-virgin olive oil and finish with grated Parmigiano. Serve with additional bread.", "tags": "tuscany, tuscan, soup, bean, vegetarian-adaptable, make-ahead", "source": "https://www.sipandfeast.com/ribollita-soup/", "nutritionData": "{\"calories\": 632, \"protein\": 22.0, \"carbs\": 70.0, \"fat\": 30.0}"},
  {"name": "Bistecca alla Fiorentina", "category": "Italian Regional", "description": "Thick-cut Florentine T-bone steak from Chianina beef, grilled over hardwood coals and served rare with just olive oil, salt, and lemon.", "servings": 2, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"Florentine T-bone steak 2 to 3 inches thick (about 2.5 lb)\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"\", \"name\": \"coarse sea salt\"}, {\"qty\": \"\", \"name\": \"freshly cracked black pepper\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Remove steak from the fridge 1 hour before cooking; pat very dry. 2. Heat a charcoal grill or cast-iron grill pan to very high heat. 3. Season steak generously on both sides with salt and pepper. 4. Grill 5–7 minutes per side for rare to medium-rare, turning once. Let the bone side also touch the grill for 2 minutes. 5. Rest on a cutting board for 5 minutes. 6. Drizzle with olive oil, garnish with rosemary, and serve with lemon wedges. Carve tableside.", "tags": "tuscany, florence, beef, grilled, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 680, \"protein\": 52.0, \"carbs\": 0.0, \"fat\": 51.0}"},
  {"name": "Panzanella", "category": "Italian Regional", "description": "Tuscan summer bread salad with ripe tomatoes, cucumber, red onion, and basil in a tangy red-wine-vinegar dressing.", "servings": 4, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6 oz\", \"name\": \"stale ciabatta or Tuscan bread torn into chunks\"}, {\"qty\": \"1.5 lb\", \"name\": \"ripe tomatoes cut into chunks\"}, {\"qty\": \"1\", \"name\": \"English cucumber sliced\"}, {\"qty\": \"1\", \"name\": \"small red onion thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh basil leaves torn\"}, {\"qty\": \"1/4 cup\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1/2 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Soak bread chunks in a bowl of cold water for 5 minutes; squeeze out excess water and crumble into large pieces into a salad bowl. 2. Add tomatoes, cucumber, and red onion to the bowl. 3. Whisk together vinegar, olive oil, garlic, sugar, salt, and pepper to make dressing. 4. Pour dressing over the salad and toss well. Let sit 15 minutes for bread to absorb the juices. 5. Add basil, toss gently, and serve at room temperature.", "tags": "tuscany, tuscan, salad, vegetarian, summer, no-cook", "source": "Classic", "nutritionData": "{\"calories\": 429, \"protein\": 6.0, \"carbs\": 31.0, \"fat\": 31.0}"},
  {"name": "Cinghiale al Cinghiale", "category": "Italian Regional", "description": "Ruscan wild-boar ragù slow-braised in Chianti with juniper berries, rosemary, and herbs, served over pappardelle.", "servings": 6, "prepTime": 30, "cookTime": 150, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"wild boar shoulder cut into 1-inch cubes\"}, {\"qty\": \"1\", \"name\": \"bottle Chianti or other robust red wine\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"2\", \"name\": \"carrots diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 sprigs\", \"name\": \"rosemary\"}, {\"qty\": \"6\", \"name\": \"juniper berries crushed\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 lb\", \"name\": \"pappardelle pasta\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"grated Pecorino Romano for serving\"}]", "instructions": "1. Marinate boar in wine with aromatics (onion, carrots, celery, garlic, rosemary, juniper, bay) overnight in the fridge. 2. Drain meat and vegetables, reserving the wine marinade. Pat meat dry. 3. Heat olive oil in a Dutch oven over high heat; brown meat in batches. Remove and set aside. 4. In the same pot, sauté the drained vegetables over medium heat until soft. Add tomato paste and cook 3 minutes. 5. Return meat to pot, add reserved wine, and bring to a boil. Reduce heat to lowest, cover, and braise 2–2.5 hours until meat is very tender. 6. Shred meat, taste and adjust seasoning. Cook pappardelle to al dente; toss with ragù. Serve with Pecorino.", "tags": "tuscany, wild boar, ragù, pasta, slow-cook", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 38.0, \"carbs\": 45.0, \"fat\": 18.0}"},
  {"name": "Tortellini in Brodo", "category": "Italian Regional", "description": "Emilian pork-and-Parmigiano-stuffed tortellini floating in a rich golden capon broth, the quintessential Christmas dish of Bologna.", "servings": 6, "prepTime": 90, "cookTime": 120, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"For the broth: 1 whole capon or chicken (3 lb)\"}, {\"qty\": \"1 lb\", \"name\": \"beef brisket\"}, {\"qty\": \"1\", \"name\": \"onion halved\"}, {\"qty\": \"2\", \"name\": \"carrots\"}, {\"qty\": \"2\", \"name\": \"stalks celery\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"For the filling: 1/4 lb prosciutto di Parma finely minced\"}, {\"qty\": \"1/4 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"1\", \"name\": \"egg\"}, {\"qty\": \"\", \"name\": \"pinch nutmeg\"}, {\"qty\": \"\", \"name\": \"For the pasta: 2 cups all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"\", \"name\": \"salt\"}]", "instructions": "1. For broth: place chicken, brisket, and vegetables in a large pot with cold water, bring to a boil, skim foam, and simmer 2 hours. Strain and season with salt. 2. For filling: brown pork in a dry skillet. Cool, then combine with prosciutto, Parmigiano, egg, and nutmeg. Season well. 3. For pasta: mound flour, make a well, add eggs and a pinch of salt. Knead 10 minutes until smooth and silky. Rest 30 minutes wrapped. 4. Roll dough paper-thin. Cut 1.5-inch squares; place a tiny mound of filling on each. Fold diagonally and wrap around a finger, pressing ends together to form tortellini. 5. Bring broth to a gentle simmer. Cook tortellini 3–4 minutes until they float. 6. Ladle into bowls, ensuring plenty of broth, and serve with extra Parmigiano.", "tags": "emilia-romagna, bologna, pasta, soup, celebration", "source": "https://memoriediangelina.com/index/primi-piatti/", "nutritionData": "{\"calories\": 390, \"protein\": 22.0, \"carbs\": 42.0, \"fat\": 13.0}"},
  {"name": "Lasagne alla Bolognese", "category": "Italian Regional", "description": "Classic Emilian lasagne layered with slow-cooked Bolognese ragù, silky béchamel, and ample Parmigiano Reggiano.", "servings": 8, "prepTime": 60, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh lasagna sheets\"}, {\"qty\": \"\", \"name\": \"For rag\\u00f9: 1/2 lb ground beef\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1\", \"name\": \"onion finely diced\"}, {\"qty\": \"1\", \"name\": \"carrot diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 cups\", \"name\": \"tomato passata\"}, {\"qty\": \"\", \"name\": \"salt and pepper\"}, {\"qty\": \"\", \"name\": \"For b\\u00e9chamel: 4 tbsp butter\"}, {\"qty\": \"4 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 cups\", \"name\": \"whole milk\"}, {\"qty\": \"\", \"name\": \"pinch nutmeg\"}, {\"qty\": \"\", \"name\": \"For assembly: 1 cup grated Parmigiano Reggiano\"}]", "instructions": "1. Ragù: Sauté vegetables in butter until soft. Add beef and pork; brown well. Add wine, reduce. Add milk, reduce. Add passata and simmer very gently, partially covered, 1.5 hours. Season. 2. Béchamel: Melt butter, whisk in flour, cook 1 minute. Gradually whisk in warm milk until smooth. Simmer until thick; season with nutmeg and salt. 3. Blanch lasagna sheets briefly in salted water; lay on damp towels. 4. Preheat oven to 375°F. Spread thin layer of béchamel on pan bottom. Layer pasta, ragù, béchamel, Parmigiano; repeat 4–5 layers, ending with béchamel and Parmigiano. 5. Dot top with butter; bake 40–45 minutes until bubbling and golden. Rest 10 minutes before cutting.", "tags": "emilia-romagna, bologna, pasta, baked, celebration", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 20.0, \"carbs\": 56.0, \"fat\": 16.0}"},
  {"name": "Osso Buco alla Milanese", "category": "Italian Regional", "description": "Milanese braised veal shanks in white wine with a bright gremolata of lemon, garlic, and parsley, traditionally served with risotto milanese.", "servings": 4, "prepTime": 20, "cookTime": 120, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"cross-cut veal shanks about 1.5 inches thick (about 3 lb total)\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"carrot diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1.5 cups\", \"name\": \"chicken stock\"}, {\"qty\": \"1 can\", \"name\": \"whole tomatoes crushed\"}, {\"qty\": \"2 sprigs\", \"name\": \"thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"For gremolata: 1/4 cup flat-leaf parsley minced\"}, {\"qty\": \"\", \"name\": \"zest of 1 lemon\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Pat shanks dry and season with salt and pepper. Dredge in flour. 2. Brown shanks in butter and oil in a wide Dutch oven over high heat, 4 minutes per side. Remove. 3. In same pot, sauté onion, carrot, celery, and garlic over medium heat until soft. Add wine, scrape up browned bits, and reduce by half. 4. Add stock, tomatoes, thyme, and bay leaves. Return shanks. Liquid should reach halfway up the shanks. 5. Cover and braise over very low heat or in a 325°F oven for 1.5–2 hours until meat is very tender. 6. Mix gremolata ingredients. Serve osso buco over risotto milanese, topped with gremolata.", "tags": "lombardy, milan, braised, veal, celebration", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 42.0, \"carbs\": 18.0, \"fat\": 26.0}"},
  {"name": "Risotto alla Milanese", "category": "Italian Regional", "description": "Saffron-gilded Milanese risotto made with beef stock, butter, and abundant Parmigiano Reggiano — the classic partner to osso buco.", "servings": 4, "prepTime": 10, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"8 cups\", \"name\": \"low-sodium beef stock warmed\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter divided\"}, {\"qty\": \"1\", \"name\": \"large shallot finely diced\"}, {\"qty\": \"3/4 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/2 tsp\", \"name\": \"saffron threads\"}, {\"qty\": \"1 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"3 tbsp\", \"name\": \"flat-leaf parsley minced\"}]", "instructions": "1. Bring stock to a low simmer in a saucepan. Dissolve saffron in 1/2 cup warm stock; set aside. 2. Melt 3 tbsp butter in a wide heavy pan over medium heat. Sauté shallot until soft, 3 minutes. 3. Add rice and stir 2 minutes until edges turn translucent. Add wine and cook until absorbed. 4. Add stock one ladle at a time, stirring frequently; each addition should be absorbed before adding the next. Cook 18–20 minutes total until rice is al dente and creamy. 5. Stir in saffron stock, remaining butter, and Parmigiano. Remove from heat, stir vigorously to mantecare. 6. Season with salt and pepper; serve immediately scattered with parsley.", "tags": "lombardy, milan, risotto, saffron, gluten-free", "source": "https://www.sipandfeast.com/risotto-alla-milanese/", "nutritionData": "{\"calories\": 596, \"protein\": 9.0, \"carbs\": 82.0, \"fat\": 25.0}"},
  {"name": "Cotoletta alla Milanese", "category": "Italian Regional", "description": "Bone-in veal chop breaded in fine breadcrumbs and shallow-fried in clarified butter until golden, the original Milanese cutlet.", "servings": 2, "prepTime": 20, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"bone-in veal rib chops about 3/4-inch thick (about 1.5 lb)\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"fine plain breadcrumbs\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"6 tbsp\", \"name\": \"clarified butter or ghee\"}, {\"qty\": \"\", \"name\": \"coarse sea salt\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}, {\"qty\": \"\", \"name\": \"flat-leaf parsley for garnish\"}]", "instructions": "1. Using a meat mallet, pound veal chops on both sides to about 1/4-inch thickness, keeping bone attached. 2. Season with salt. Set up a dredging station: flour, beaten eggs, breadcrumbs. 3. Dredge each chop in flour, dip in egg, then coat evenly in breadcrumbs, pressing firmly. 4. Heat clarified butter in a large skillet over medium-high heat. 5. Fry chops 3–4 minutes per side until deeply golden and cooked through. 6. Drain briefly on a wire rack, season with sea salt, and serve immediately with lemon wedges and parsley.", "tags": "lombardy, milan, veal, fried, breaded", "source": "Classic", "nutritionData": "{\"calories\": 568, \"protein\": 13.0, \"carbs\": 39.0, \"fat\": 40.0}"},
  {"name": "Vitello Tonnato", "category": "Italian Regional", "description": "Elegant Piedmontese cold sliced veal draped in a silky tuna-and-caper sauce, a classic summer centerpiece.", "servings": 6, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"veal loin or tenderloin tied\"}, {\"qty\": \"1\", \"name\": \"medium onion sliced\"}, {\"qty\": \"1\", \"name\": \"carrot\"}, {\"qty\": \"1\", \"name\": \"stalk celery\"}, {\"qty\": \"1 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"4\", \"name\": \"whole cloves\"}, {\"qty\": \"\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"For tonnato sauce: 2 large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 can\", \"name\": \"tuna in olive oil drained\"}, {\"qty\": \"4\", \"name\": \"anchovy fillets\"}, {\"qty\": \"3 tbsp\", \"name\": \"capers rinsed\"}, {\"qty\": \"\", \"name\": \"juice of 1/2 lemon\"}, {\"qty\": \"2 tbsp\", \"name\": \"meat cooking liquid\"}, {\"qty\": \"\", \"name\": \"capers and lemon slices for garnish\"}]", "instructions": "1. Simmer onion, carrot, celery, wine, bay leaf, and cloves in salted water 10 minutes. Add veal and simmer gently 60–75 minutes until just cooked through. Cool in liquid. 2. For sauce: blend eggs, lemon juice, and a pinch of salt. With blender running, stream in olive oil until a thick mayonnaise forms. 3. Add tuna, anchovies, capers, and a splash of cooking liquid; blend until smooth and pourable. Adjust seasoning. 4. Remove veal from liquid, pat dry, and slice paper-thin against the grain. 5. Arrange slices on a platter, overlapping. Spoon sauce generously over all. 6. Garnish with capers and lemon slices. Refrigerate at least 2 hours or overnight before serving.", "tags": "piedmont, veal, cold dish, summer, elegant", "source": "https://memoriediangelina.com/2010/07/11/vitello-tonnato/", "nutritionData": "{\"calories\": 506, \"protein\": 41.0, \"carbs\": 2.0, \"fat\": 36.0}"},
  {"name": "Bagna Cauda", "category": "Italian Regional", "description": "Warm Piedmontese garlic-and-anchovy dipping sauce served hot at the table with raw and lightly cooked seasonal vegetables.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"10 cloves\", \"name\": \"garlic peeled\"}, {\"qty\": \"2 oz\", \"name\": \"anchovy fillets in oil drained\"}, {\"qty\": \"3/4 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"assorted vegetables for dipping: fennel, radicchio, bell pepper, carrot, cauliflower\"}, {\"qty\": \"\", \"name\": \"crusty bread for serving\"}]", "instructions": "1. Mince garlic very finely or crush to a paste. 2. Combine garlic and olive oil in a small heavy saucepan over the lowest possible heat. 3. Cook very gently, stirring often, for 15 minutes until garlic is soft and fragrant but not colored. 4. Add anchovy fillets and mash with a wooden spoon until they dissolve into the oil. Stir 5 minutes more. 5. Remove from heat and swirl in butter until melted. 6. Transfer to a fondue pot or ceramic warmer. Serve surrounded by vegetables and crusty bread for dipping.", "tags": "piedmont, dip, anchovy, garlic, communal, appetizer", "source": "Classic", "nutritionData": "{\"calories\": 260, \"protein\": 8.0, \"carbs\": 6.0, \"fat\": 23.0}"},
  {"name": "Farinata Genovese", "category": "Italian Regional", "description": "Golden Ligurian chickpea-flour pancake baked in a blazing-hot oven until crisp at the edges and custardy in the center.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"chickpea flour\"}, {\"qty\": \"2 cups\", \"name\": \"cold water\"}, {\"qty\": \"1/4 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil for the pan\"}, {\"qty\": \"\", \"name\": \"fresh rosemary leaves (optional)\"}]", "instructions": "1. Whisk chickpea flour into cold water until smooth; whisk in 1/4 cup olive oil and salt. Let batter rest 4 hours or overnight at room temperature. 2. Preheat oven to 500°F (with a 12-inch cast-iron skillet inside) for at least 30 minutes. 3. Skim any foam from batter surface. 4. Carefully add 2 tbsp olive oil to the hot skillet; pour in batter to a depth of about 1/4 inch. 5. Bake 15–20 minutes until golden and set at center with slightly crisp edges. 6. Season generously with black pepper; slice into wedges and serve hot.", "tags": "liguria, genoa, chickpea, vegan, gluten-free, appetizer", "source": "https://memoriediangelina.com/2013/06/23/farinata-genovese-genovese-chickpea-flatbread/", "nutritionData": "{\"calories\": 369, \"protein\": 10.0, \"carbs\": 26.0, \"fat\": 25.0}"},
  {"name": "Risi e Bisi", "category": "Italian Regional", "description": "Venetian spring rice-and-pea dish — wetter than risotto, thicker than soup — made from fresh peas and pancetta in pea-pod broth.", "servings": 4, "prepTime": 20, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"fresh shelled peas (pods reserved)\"}, {\"qty\": \"2 cups\", \"name\": \"Vialone Nano or Arborio rice\"}, {\"qty\": \"1/4 cup\", \"name\": \"pancetta diced\"}, {\"qty\": \"1\", \"name\": \"small onion finely chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"flat-leaf parsley minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"5 cups\", \"name\": \"pea-pod broth (or chicken stock)\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"\", \"name\": \"salt and white pepper to taste\"}]", "instructions": "1. For pea broth: Simmer pea pods in 7 cups salted water with a sliced onion and carrot for 30 minutes; strain. 2. In a wide pot, sauté pancetta and onion in butter and olive oil until onion is translucent. Add parsley and cook 1 minute. 3. Add peas and a ladle of broth; cover and simmer gently 5 minutes until almost tender. 4. Add rice and remaining hot broth all at once; stir and cook at a gentle boil for 18–20 minutes until rice is tender. The consistency should be quite soupy. 5. Remove from heat; stir in remaining butter and Parmigiano. 6. Season with salt and white pepper; serve immediately in warm bowls.", "tags": "veneto, venice, rice, spring, peas", "source": "https://memoriediangelina.com/2010/05/15/risi-e-bisi/", "nutritionData": "{\"calories\": 380, \"protein\": 14.0, \"carbs\": 52.0, \"fat\": 12.0}"},
  {"name": "Sarde in Saor", "category": "Italian Regional", "description": "Venetian sweet-and-sour marinated sardines layered with agrodolce onions, raisins, and pine nuts — best made two days ahead.", "servings": 6, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"fresh sardines cleaned filleted and butterflied\"}, {\"qty\": \"\", \"name\": \"all-purpose flour for dredging\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"2\", \"name\": \"large white onions thinly sliced\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 cup\", \"name\": \"white wine vinegar\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"raisins soaked in warm water\"}, {\"qty\": \"1/2 cup\", \"name\": \"pine nuts toasted\"}, {\"qty\": \"1 tsp\", \"name\": \"whole black peppercorns\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Dust sardine fillets in flour; shallow-fry in hot vegetable oil until golden, about 2 minutes per side. Season with salt and drain on paper towels. 2. Sauté onions in olive oil over low heat for 25–30 minutes until very soft but not colored. 3. Raise heat, add wine vinegar and white wine; cook 5 minutes. Season with salt and pepper. 4. In a glass dish, layer sardines, onions, drained raisins, and pine nuts. Repeat, ending with the onion mixture. 5. Pour any remaining sousing liquid over top. Cover and refrigerate at least 24–48 hours. 6. Serve at room temperature as part of an antipasto.", "tags": "veneto, venice, sardines, agrodolce, make-ahead, antipasto", "source": "https://www.emikodavies.com/sarde-in-saor/", "nutritionData": "{\"calories\": 320, \"protein\": 18.0, \"carbs\": 20.0, \"fat\": 18.0}"},
  {"name": "Tiramisù", "category": "Italian Regional", "description": "The Treviso-born mascarpone-and-espresso layered dessert with savoiardi, egg zabaglione, and a dusting of cocoa.", "servings": 8, "prepTime": 30, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"28\", \"name\": \"savoiardi ladyfingers\"}, {\"qty\": \"1 cup\", \"name\": \"brewed espresso cooled\"}, {\"qty\": \"3 tbsp\", \"name\": \"demerara sugar\"}, {\"qty\": \"5\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/2 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"16 oz\", \"name\": \"mascarpone chilled\"}, {\"qty\": \"1.75 cups\", \"name\": \"heavy cream chilled\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 cup\", \"name\": \"Dutch-process cocoa powder for dusting\"}]", "instructions": "1. Whisk egg yolks and sugar in a heatproof bowl over barely simmering water until pale and ribbon-like, about 8 minutes. Remove from heat and cool slightly. 2. Fold in mascarpone until smooth. 3. Whip heavy cream and vanilla to soft peaks. Fold cream into mascarpone mixture in two additions. 4. Mix espresso with demerara sugar in a shallow bowl. 5. Quickly dip each ladyfinger in espresso (1 second per side) and arrange in a single layer in an 8×11-inch baking dish. 6. Spread half the cream over ladyfingers; dust with cocoa. Repeat with a second layer. Dust top generously with cocoa. Refrigerate at least 6 hours or overnight before serving.", "tags": "veneto, treviso, dessert, make-ahead, no-bake", "source": "Classic", "nutritionData": "{\"calories\": 575, \"protein\": 10.0, \"carbs\": 27.0, \"fat\": 48.0}"},
  {"name": "Arancini", "category": "Italian Regional", "description": "Saffron-scented Sicilian fried rice balls stuffed with a rich ragù, green peas, and melted caciocavallo cheese.", "servings": 6, "prepTime": 90, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"6.25 cups\", \"name\": \"low-sodium beef stock\"}, {\"qty\": \"3 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1/2 tsp\", \"name\": \"saffron threads\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1\", \"name\": \"small onion minced\"}, {\"qty\": \"3 oz\", \"name\": \"pancetta diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1/4 lb\", \"name\": \"caciocavallo or mozzarella cut into small cubes\"}, {\"qty\": \"1.25 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1.25 cups\", \"name\": \"water\"}, {\"qty\": \"2 cups\", \"name\": \"plain breadcrumbs\"}, {\"qty\": \"\", \"name\": \"vegetable oil for deep frying\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Bring stock, butter, and saffron to a boil; add rice, cover, reduce to low, cook until liquid evaporates (~20 min). Off heat, stir in Parmigiano, cool 10 min, then mix in eggs. Spread on baking sheet; refrigerate 1 hour. 2. Brown pancetta; add onion, cook until soft. Add beef and pork; brown. Add tomato paste, cook 3 min. Add wine, reduce. Add peas; season. Cool. 3. With damp hands, cup 1/2 cup rice, indent center, fill with 1–2 tsp ragù and a cube of cheese. Close and roll into a ball. 4. Whisk flour, water, eggs, and salt into batter. Dip balls in batter then coat in breadcrumbs. 5. Deep-fry at 370°F in batches of 3 until golden all over, 4–5 min. Drain on paper towels. Serve immediately.", "tags": "sicily, palermo, fried, rice, street food", "source": "https://www.sipandfeast.com/arancini/", "nutritionData": "{\"calories\": 480, \"protein\": 22.0, \"carbs\": 62.0, \"fat\": 16.0}"},
  {"name": "Caponata", "category": "Italian Regional", "description": "Sicilian sweet-and-sour eggplant relish with celery, olives, capers, and pine nuts in a rich agrodolce tomato sauce.", "servings": 6, "prepTime": 20, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"eggplant cubed into 1.5-inch pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"olive oil\"}, {\"qty\": \"4\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"1\", \"name\": \"large red onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1/2 cup\", \"name\": \"pitted green olives chopped and rinsed\"}, {\"qty\": \"3 tbsp\", \"name\": \"capers rinsed\"}, {\"qty\": \"3 tbsp\", \"name\": \"raisins\"}, {\"qty\": \"3 tbsp\", \"name\": \"pine nuts toasted\"}, {\"qty\": \"3 tbsp\", \"name\": \"red wine vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"1/4 cup\", \"name\": \"flat-leaf parsley chopped\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Toss eggplant with salt; drain in colander 20 minutes. Pat dry. Roast at 425°F with 1/4 cup olive oil on a lined baking sheet for 30–35 minutes until browned. 2. Heat remaining oil in a large skillet over medium heat. Sauté celery, onion, and bell pepper until soft, 8 minutes. 3. Add tomato paste; cook 5 minutes. Add red pepper flakes. 4. Add olives, capers, raisins, vinegar, and sugar; cook 5 minutes for flavors to meld. 5. Fold in roasted eggplant gently. Taste and adjust sweet-sour balance with more vinegar or sugar. 6. Stir in pine nuts and parsley. Serve at room temperature; better the next day.", "tags": "sicily, palermo, agrodolce, vegetarian, antipasto, make-ahead", "source": "https://www.sipandfeast.com/eggplant-caponata/", "nutritionData": "{\"calories\": 320, \"protein\": 3.0, \"carbs\": 20.0, \"fat\": 27.0}"},
  {"name": "Pasta con le Sarde", "category": "Italian Regional", "description": "Sicilian bucatini with fresh sardines, wild fennel, saffron, raisins, and pine nuts in the sweet-savory Palermitan tradition.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"bucatini pasta\"}, {\"qty\": \"1 cup\", \"name\": \"plain breadcrumbs\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil for breadcrumbs\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron threads\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"1/4 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1\", \"name\": \"large fennel bulb halved, fronds reserved\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"5 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"5\", \"name\": \"anchovy fillets in oil\"}, {\"qty\": \"3 cans\", \"name\": \"sardines in oil (about 12 oz)\"}, {\"qty\": \"1/3 cup\", \"name\": \"golden raisins soaked and drained\"}, {\"qty\": \"1/3 cup\", \"name\": \"pine nuts\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Toast breadcrumbs in 3 tbsp olive oil until golden; set aside. 2. Dissolve saffron in white wine; set aside. 3. Boil a large pot of salted water. Cook fennel 10 minutes until tender; remove with a slotted spoon, dice, and reserve water for pasta. 4. Sauté onion in olive oil until translucent; add anchovies and garlic, cook until anchovies dissolve. Add diced fennel; cook 2 minutes. 5. Add saffron wine; reduce by half. Add raisins, pine nuts, and sardines; gently fold together, leaving some texture. Cook pasta in the fennel water to 1 minute shy of al dente. 6. Add pasta and 1 cup pasta water to the pan; toss until al dente. Serve with toasted breadcrumbs and a drizzle of olive oil.", "tags": "sicily, palermo, pasta, sardines, seafood", "source": "https://www.sipandfeast.com/pasta-con-le-sarde/", "nutritionData": "{\"calories\": 520, \"protein\": 28.0, \"carbs\": 72.0, \"fat\": 14.0}"},
  {"name": "Cannoli Siciliani", "category": "Italian Regional", "description": "Crispy Sicilian pastry tubes filled with sweetened sheep's-milk ricotta, chocolate chips, and candied orange peel.", "servings": 12, "prepTime": 60, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"For shells: 2 cups all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter at room temperature\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry Marsala wine\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1\", \"name\": \"egg white for sealing\"}, {\"qty\": \"\", \"name\": \"For filling: 2 lb fresh ricotta well-drained overnight\"}, {\"qty\": \"1 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/2 cup\", \"name\": \"mini chocolate chips\"}, {\"qty\": \"1/4 cup\", \"name\": \"candied orange peel diced\"}, {\"qty\": \"\", \"name\": \"powdered sugar for finishing\"}, {\"qty\": \"\", \"name\": \"chopped pistachios for garnish\"}]", "instructions": "1. Mix flour, sugar, cinnamon, and salt. Work in butter until crumbly. Beat egg with Marsala; add to flour and knead until smooth. Rest 30 minutes wrapped. 2. Roll dough paper-thin. Cut into 4-inch rounds. Wrap around metal cannoli tubes; seal edges with egg white. 3. Deep-fry at 350°F until golden and bubbled, 2–3 minutes. Drain and cool slightly before sliding off tubes. 4. Beat ricotta with powdered sugar until smooth. Fold in chocolate chips and orange peel. Transfer to a piping bag. 5. Fill shells just before serving, piping from both ends. 6. Dust with powdered sugar and garnish ends with pistachios or extra chocolate chips.", "tags": "sicily, dessert, pastry, ricotta, celebration", "source": "Classic", "nutritionData": "{\"calories\": 320, \"protein\": 9.0, \"carbs\": 35.0, \"fat\": 16.0}"},
  {"name": "Pizza Margherita Napoletana", "category": "Italian Regional", "description": "Authentic Neapolitan pizza with a charred, airy cornicione, San Marzano tomato sauce, fresh fior di latte mozzarella, and basil.", "servings": 2, "prepTime": 30, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"For dough: 2 cups all-purpose flour (or 00 flour)\"}, {\"qty\": \"1/2 tsp\", \"name\": \"active dry yeast\"}, {\"qty\": \"3/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm water\"}, {\"qty\": \"\", \"name\": \"For toppings: 1 cup San Marzano tomatoes hand-crushed\"}, {\"qty\": \"6 oz\", \"name\": \"fresh mozzarella or fior di latte sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}]", "instructions": "1. Combine flour, yeast, and salt. Add water; mix until shaggy, then knead 8–10 minutes until smooth and elastic. Rest covered at room temperature 8–24 hours. 2. Divide into 2 balls; rest 1 hour at room temperature. 3. Place a baking steel or heavy sheet pan on top rack; preheat oven to maximum temperature (500–550°F) for 45 minutes. 4. Stretch each dough ball to a 10-inch round on floured surface; do not use a rolling pin. 5. Spread crushed tomatoes lightly, leaving a 3/4-inch border. Top with mozzarella slices. Drizzle olive oil, season with salt. 6. Bake 6–8 minutes until crust is charred in spots and cheese is bubbling. Top with fresh basil.", "tags": "campania, naples, pizza, vegetarian, quick", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 22.0, \"carbs\": 62.0, \"fat\": 16.0}"},
  {"name": "Parmigiana di Melanzane", "category": "Italian Regional", "description": "Campanian layered eggplant Parmesan baked with Neapolitan tomato sauce, mozzarella, hard-boiled eggs, and fried eggplant.", "servings": 6, "prepTime": 30, "cookTime": 75, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large eggplant sliced into 1/4-inch disks\"}, {\"qty\": \"3 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 lb\", \"name\": \"fresh mozzarella shredded\"}, {\"qty\": \"3 cups\", \"name\": \"marinara or Neapolitan tomato sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano Reggiano\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"1 cup\", \"name\": \"olive oil for frying\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Salt eggplant slices generously; stack and weigh down 90 minutes. Rinse and pat very dry. 2. Fry eggplant in olive oil over medium heat until golden, 3–4 min per side; drain on paper towels. 3. Preheat oven to 325°F. Spread a thin layer of tomato sauce in the bottom of a 9×13 baking dish. 4. Layer: eggplant, sauce, torn basil, mozzarella, and Parmigiano. Repeat until all ingredients are used, ending with sauce and cheeses. 5. Bake 50–60 minutes until bubbling and deeply golden. 6. Rest 20 minutes before slicing and serving.", "tags": "campania, naples, eggplant, baked, vegetarian", "source": "https://www.sipandfeast.com/eggplant-parmigiana/", "nutritionData": "{\"calories\": 625, \"protein\": 19.0, \"carbs\": 13.0, \"fat\": 54.0}"},
  {"name": "Orecchiette con Cime di Rapa", "category": "Italian Regional", "description": "Pugliese ear-shaped pasta tossed with bitter broccoli rabe, anchovy-garlic oil, and chili flakes — a staple of Bari's street cooks.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"orecchiette pasta\"}, {\"qty\": \"1\", \"name\": \"bunch broccoli rabe stems trimmed and chopped\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"5\", \"name\": \"anchovy fillets in olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"1/4 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"flat-leaf parsley minced\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"grated Pecorino Romano for serving\"}]", "instructions": "1. Bring a large pot of salted water to a boil. Blanch broccoli rabe 2–3 minutes until bright green; remove with tongs and set aside. Keep water boiling. 2. Add orecchiette to the same water; cook to 1 minute shy of al dente. Reserve 1 cup pasta water. 3. Heat olive oil in a wide skillet over medium heat. Add garlic and anchovies; cook until garlic is golden and anchovies dissolve, 3 minutes. Add red pepper flakes, cook 30 seconds. 4. Add broccoli rabe and toss. Add pasta and half the pasta water; toss vigorously over high heat 1–2 minutes until everything is well-coated. 5. Adjust with more pasta water if needed; season with salt and pepper. 6. Finish with parsley and serve with grated Pecorino.", "tags": "puglia, bari, pasta, broccoli rabe, quick", "source": "Classic", "nutritionData": "{\"calories\": 610, \"protein\": 18.0, \"carbs\": 93.0, \"fat\": 19.0}"},
  {"name": "Malloreddus alla Campidanese", "category": "Italian Regional", "description": "Sardinian saffron-tinged gnocchetti shells in a slow-cooked fennel sausage-and-tomato sauce, finished with aged Pecorino Sardo.", "servings": 4, "prepTime": 20, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"malloreddus pasta (Sardinian gnocchetti)\"}, {\"qty\": \"3/4 lb\", \"name\": \"Sardinian fennel sausage casings removed\"}, {\"qty\": \"1 clove\", \"name\": \"garlic slightly crushed\"}, {\"qty\": \"1 can\", \"name\": \"whole peeled tomatoes crushed by hand\"}, {\"qty\": \"1 pinch\", \"name\": \"saffron dissolved in 2 tbsp warm water\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"fennel seeds\"}, {\"qty\": \"\", \"name\": \"pinch crushed red pepper\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"\", \"name\": \"grated Pecorino Sardo for serving\"}]", "instructions": "1. Brown sausage meat in olive oil in a wide skillet over medium heat, breaking it up; remove and set aside, leaving fat in pan. 2. Sauté garlic in remaining fat until fragrant; discard garlic. Add fennel seeds and red pepper; cook 30 seconds. 3. Add tomatoes, saffron water, salt, and pepper; simmer 20 minutes until sauce thickens. Return sausage to pan. 4. Cook malloreddus in a large pot of salted water according to package instructions until al dente. Reserve 1/2 cup pasta water. 5. Drain pasta and add directly to sauce; toss well, adding a splash of pasta water if needed. 6. Serve with abundant grated Pecorino Sardo.", "tags": "sardinia, cagliari, pasta, sausage, saffron", "source": "https://memoriediangelina.com/2010/10/29/malloreddus-alla-campidanese/", "nutritionData": "{\"calories\": 730, \"protein\": 28.0, \"carbs\": 91.0, \"fat\": 27.0}"},
  {"name": "Canederli in Brodo", "category": "Italian Regional", "description": "Tyrolean bread dumplings made with stale bread, speck, and herbs, simmered in a clear golden meat broth.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3/4 lb\", \"name\": \"stale white bread cubed\"}, {\"qty\": \"3 oz\", \"name\": \"speck or bacon finely minced\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1\", \"name\": \"small onion finely minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"flat-leaf parsley minced\"}, {\"qty\": \"\", \"name\": \"pinch nutmeg\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}, {\"qty\": \"6 cups\", \"name\": \"rich meat or chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter for saut\\u00e9ing\"}]", "instructions": "1. Sauté onion in butter until translucent; cool slightly. 2. Toss together bread cubes, speck, sautéed onion, and parsley in a large bowl. 3. Beat eggs with milk; pour over bread mixture. Mix well and let rest 20 minutes until bread is moist and clumping. 4. Add flour, nutmeg, salt, and pepper; mix until the dough holds together when pressed. If too wet, add more flour a tablespoon at a time. 5. With damp hands, form golf-ball-sized dumplings. Test one in simmering broth — if it falls apart, mix more flour into remaining dough. 6. Simmer canederli in gently simmering broth 15 minutes until cooked through. Serve in deep bowls with broth.", "tags": "trentino, alto adige, tyrol, soup, dumplings", "source": "https://memoriediangelina.com/2010/12/19/canederli/", "nutritionData": "{\"calories\": 457, \"protein\": 19.0, \"carbs\": 52.0, \"fat\": 19.0}"},
  {"name": "Frico Croccante", "category": "Italian Regional", "description": "Crispy Friulian cheese-and-potato wafer made from aged Montasio, pan-fried until molten in the center and lacey at the edges.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"aged Montasio cheese (or a mix of aged and semi-aged) grated\"}, {\"qty\": \"2\", \"name\": \"medium potatoes peeled and grated\"}, {\"qty\": \"1\", \"name\": \"small onion grated\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}]", "instructions": "1. Squeeze excess moisture from grated potatoes and onion in a clean kitchen towel. 2. Mix cheese, potato, and onion together in a bowl; season with salt and pepper. 3. Heat 1 tbsp olive oil in a 10-inch nonstick skillet over medium heat. 4. Add half the cheese-potato mixture, pressing into an even layer. Cook 8–10 minutes until deep golden on the bottom. 5. Flip carefully using a plate; add remaining oil and cook the second side 7–8 minutes until crisp and golden. 6. Slide onto a cutting board; cool 2 minutes (it crisps as it cools) and cut into wedges. Repeat with remaining mixture.", "tags": "friuli, montasio, cheese, crispy, appetizer, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 19.0, \"carbs\": 8.0, \"fat\": 27.0}"},
  {"name": "Arrosticini Abruzzesi", "category": "Italian Regional", "description": "Abruzzese skewers of cubed castrated sheep meat grilled over a narrow charcoal grill and eaten straight off the wooden stick.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"lamb shoulder or mutton cut into 1-inch cubes\"}, {\"qty\": \"1/4 cup\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh rosemary\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic slightly crushed\"}, {\"qty\": \"\", \"name\": \"coarse sea salt\"}, {\"qty\": \"\", \"name\": \"freshly ground black pepper\"}, {\"qty\": \"\", \"name\": \"crusty bread for serving\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Thread 4–5 cubes of lamb tightly onto each wooden skewer, alternating lean and fat pieces. 2. Season skewers generously with salt and pepper. 3. Brush lightly with olive oil infused with rosemary and garlic. 4. Grill over very hot charcoal in a narrow grill (the cylindrical fornacella style) or a very hot cast-iron ridged pan, 3–4 minutes per side, turning so all sides are browned. 5. Serve immediately with crusty bread and lemon wedges.", "tags": "abruzzo, lamb, grilled, street food, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 390, \"protein\": 32.0, \"carbs\": 1.0, \"fat\": 29.0}"},
  {"name": "Texas Smoked Brisket", "category": "BBQ & Grilling", "description": "A whole packer brisket seasoned with just salt and pepper and slow-smoked over oak for authentic Texas bark and a deep smoke ring.", "servings": 12, "prepTime": 30, "cookTime": 840, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"12 lb\", \"name\": \"whole packer beef brisket\"}, {\"qty\": \"1/4 cup\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"coarse black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"2 cups\", \"name\": \"beef tallow or unsalted butter for spritzing\"}]", "instructions": "1. Trim fat cap on brisket to 1/4 inch and remove any hard fat. 2. Mix salt, pepper, garlic powder, and onion powder; coat brisket generously on all sides. 3. Preheat smoker to 225°F using post oak or hickory wood. 4. Place brisket fat-side up on smoker grates; smoke for 8-10 hours until internal temp reaches 165°F. 5. Wrap tightly in butcher paper; return to smoker. 6. Continue smoking until internal temp reaches 200-205°F and probe slides in like butter, about 4-6 more hours. 7. Rest wrapped in a cooler for at least 1 hour before slicing against the grain.", "tags": "texas-bbq, smoking, low-and-slow, beef", "source": "https://amazingribs.com/tested-recipes/beef-and-bison-recipes/smoked-brisket-texas-style/", "nutritionData": "{\"calories\": 710, \"protein\": 72.0, \"carbs\": 2.0, \"fat\": 46.0}"},
  {"name": "Carolina Vinegar Pulled Pork", "category": "BBQ & Grilling", "description": "Smoked pork shoulder mopped with tangy vinegar sauce in the tradition of Eastern North Carolina BBQ.", "servings": 10, "prepTime": 20, "cookTime": 600, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"8 lb\", \"name\": \"bone-in pork shoulder\"}, {\"qty\": \"2 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 cup\", \"name\": \"beer\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 cups\", \"name\": \"apple cider vinegar for sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"ketchup\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"salt\"}]", "instructions": "1. Mix salt, pepper, and paprika; rub all over pork shoulder. 2. Preheat smoker to 250°F with oak or hickory wood. 3. Place pork on smoker and smoke for 8-10 hours, mopping with vinegar-beer mop every hour. 4. Meanwhile combine sauce ingredients in a saucepan; simmer 25 minutes. 5. Smoke until internal temp reaches 200°F. 6. Rest wrapped in foil for 1 hour. 7. Shred pork, discarding bone and excess fat. 8. Toss shredded pork with vinegar sauce and serve.", "tags": "carolina-bbq, smoking, pulled-pork, low-and-slow", "source": "https://heygrillhey.com/carolina-style-pulled-pork/", "nutritionData": "{\"calories\": 360, \"protein\": 47.0, \"carbs\": 6.0, \"fat\": 16.0}"},
  {"name": "Baby Back Ribs 3-2-1 Method", "category": "BBQ & Grilling", "description": "Tender smoked baby back ribs using the classic 3-2-1 method: smoke, braise, then sauce for fall-off-the-bone results.", "servings": 6, "prepTime": 20, "cookTime": 360, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"racks baby back ribs\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"apple cider\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}]", "instructions": "1. Remove membrane from bone side of ribs using paper towel for grip. 2. Mix brown sugar, paprika, garlic powder, onion powder, pepper, salt, and cayenne; coat ribs generously on both sides. 3. Preheat smoker to 225°F with apple or cherry wood. 4. Smoke ribs directly on grates for 3 hours. 5. Wrap each rack in foil with apple cider, butter, and honey; return to smoker for 2 hours at 225°F. 6. Unwrap ribs; brush with BBQ sauce; return to smoker uncovered for 1 hour to set sauce. 7. Rest 10 minutes; slice and serve.", "tags": "smoking, pork-ribs, low-and-slow, BBQ", "source": "https://heygrillhey.com/3-2-1-ribs-perfect-fall-off-the-bone-ribs/", "nutritionData": "{\"calories\": 680, \"protein\": 42.0, \"carbs\": 12.0, \"fat\": 50.0}"},
  {"name": "St. Louis Style Smoked Ribs", "category": "BBQ & Grilling", "description": "Spare ribs trimmed to a rectangular St. Louis cut, smoked low and slow to achieve a beautifully lacquered bark.", "servings": 6, "prepTime": 25, "cookTime": 300, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"racks St. Louis style spare ribs\"}, {\"qty\": \"2 tbsp\", \"name\": \"yellow mustard\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"apple juice for spritzing\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}]", "instructions": "1. Trim ribs to even rectangular shape; remove membrane from bone side. 2. Slather ribs with yellow mustard as binder. 3. Mix dry rub ingredients; coat ribs liberally on both sides. 4. Preheat smoker to 275°F with apple or peach wood. 5. Place ribs bone-side down; smoke for 4.5-5 hours, spritzing with apple juice every 45 minutes after first hour. 6. In last 30 minutes brush with BBQ sauce; cook until ribs bend easily at 195-200°F. 7. Rest 15 minutes; slice and serve.", "tags": "smoking, pork-ribs, BBQ, low-and-slow", "source": "https://heygrillhey.com/smoked-st-louis-ribs/", "nutritionData": "{\"calories\": 790, \"protein\": 41.0, \"carbs\": 13.0, \"fat\": 56.0}"},
  {"name": "Smoked Beef Short Ribs", "category": "BBQ & Grilling", "description": "Massive beef short ribs seasoned with a simple salt-and-pepper rub and smoked until deeply tender with a bold bark.", "servings": 4, "prepTime": 15, "cookTime": 480, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"beef short ribs plate cut 4-5 bones\"}, {\"qty\": \"2 tbsp\", \"name\": \"spicy brown mustard\"}, {\"qty\": \"2 tbsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"beef stock for spritzing\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}]", "instructions": "1. Trim excess fat cap and silver skin from top of ribs. 2. Slather ribs with mustard; season liberally with salt, pepper, and garlic powder. 3. Preheat smoker to 250°F with oak or cherry wood. 4. Place ribs bone-side down; smoke for 3 hours without opening lid. 5. Mix beef stock and vinegar in spray bottle; spritz ribs every hour. 6. Continue smoking until internal temp reaches 203-210°F and probe slides in like butter, about 5-6 more hours total. 7. Wrap in foil; rest 30 minutes before serving.", "tags": "texas-bbq, beef-ribs, smoking, low-and-slow", "source": "https://heygrillhey.com/smoked-beef-short-ribs/", "nutritionData": "{\"calories\": 650, \"protein\": 37.0, \"carbs\": 2.0, \"fat\": 53.0}"},
  {"name": "Memphis Dry Rub Ribs", "category": "BBQ & Grilling", "description": "Baby back ribs smoked low and slow with a bold paprika-and-spice dry rub and no sauce, in the authentic Memphis style.", "servings": 6, "prepTime": 20, "cookTime": 270, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"racks baby back ribs\"}, {\"qty\": \"3 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"dry mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"celery salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 cup\", \"name\": \"apple juice for spritzing\"}]", "instructions": "1. Remove membrane from bone side of ribs. 2. Mix all dry rub ingredients; generously season ribs on both sides, pressing into meat. 3. Preheat smoker to 275°F using hickory wood. 4. Place ribs on smoker; cook for 4.5-5 hours spritzing with apple juice every 30 minutes after first hour. 5. Ribs are done when meat pulls back from bones 1/4 inch and rack bends easily at 200°F. 6. Rest 15 minutes; dust with another round of dry rub before slicing and serving.", "tags": "memphis-bbq, smoking, pork-ribs, dry-rub", "source": "https://heygrillhey.com/memphis-style-dry-rub-ribs/", "nutritionData": "{\"calories\": 590, \"protein\": 39.0, \"carbs\": 3.0, \"fat\": 47.0}"},
  {"name": "Kansas City Sweet and Saucy Ribs", "category": "BBQ & Grilling", "description": "Baby back ribs smoked low and slow and finished with a thick sweet molasses-based Kansas City style BBQ sauce.", "servings": 6, "prepTime": 20, "cookTime": 330, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"racks baby back ribs\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"apple cider for braising\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 cup\", \"name\": \"ketchup-based KC BBQ sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"molasses\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}]", "instructions": "1. Remove membrane from back of ribs; season both sides with mixed dry rub. 2. Preheat smoker to 225°F with apple or cherry wood. 3. Smoke ribs for 3 hours. 4. Wrap ribs in foil with apple cider and butter; cook 2 hours more. 5. Stir molasses and Worcestershire into BBQ sauce. 6. Unwrap ribs; brush generously with KC BBQ sauce; smoke uncovered 45 minutes until sauce is sticky and set. 7. Rest 10 minutes; slice and serve with extra sauce.", "tags": "kansas-city-bbq, smoking, pork-ribs, sweet-sauce", "source": "https://amazingribs.com/best-barbecue-ribs-recipe/", "nutritionData": "{\"calories\": 680, \"protein\": 42.0, \"carbs\": 16.0, \"fat\": 48.0}"},
  {"name": "Brisket Burnt Ends", "category": "BBQ & Grilling", "description": "Smoky cubed brisket point sauced with buttery Kansas City BBQ glaze and returned to the smoker for sticky caramelized bites.", "servings": 8, "prepTime": 30, "cookTime": 540, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"4 lb\", \"name\": \"brisket point\"}, {\"qty\": \"2 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"coarse black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter cut in pats\"}, {\"qty\": \"1/2 cup\", \"name\": \"KC-style BBQ sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}]", "instructions": "1. Season brisket point with salt, pepper, garlic powder, and paprika. 2. Smoke at 250°F with oak or cherry wood for 6-8 hours until internal temp reaches 200°F. 3. Remove from smoker; rest 20 minutes then cut into 1-inch cubes. 4. Place cubed brisket in foil pan; add butter pats, BBQ sauce, brown sugar, vinegar, and honey. 5. Toss to coat; cover pan with foil. 6. Return to smoker at 250°F for 1.5-2 hours, tossing every 30 minutes until sauce caramelizes. 7. Serve immediately.", "tags": "kansas-city-bbq, smoking, beef, burnt-ends", "source": "Classic", "nutritionData": "{\"calories\": 475, \"protein\": 24.0, \"carbs\": 15.0, \"fat\": 35.0}"},
  {"name": "Smoked Turkey", "category": "BBQ & Grilling", "description": "A whole turkey brined in apple cider and slow-smoked over apple wood for a juicy, deeply flavored bird perfect for any occasion.", "servings": 12, "prepTime": 30, "cookTime": 330, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12 lb\", \"name\": \"whole turkey\"}, {\"qty\": \"3 cups\", \"name\": \"apple cider\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1/4 cup\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"onion powder\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"2 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"black pepper\"}]", "instructions": "1. Combine cider, water, vinegar, salt, brown sugar, Worcestershire, garlic powder, and onion powder in large pot; brine turkey 12-24 hours. 2. Remove turkey from brine; pat dry thoroughly. 3. Mix softened butter with paprika and pepper; rub under and over skin. 4. Preheat smoker to 275°F with apple wood. 5. Place turkey breast-side up on smoker; cook 4-5 hours until breast reaches 165°F. 6. Rest tented with foil for 20 minutes before carving.", "tags": "smoking, poultry, holiday, low-and-slow", "source": "https://heygrillhey.com/smoked-turkey/", "nutritionData": "{\"calories\": 370, \"protein\": 48.0, \"carbs\": 2.0, \"fat\": 16.0}"},
  {"name": "Alabama White Sauce Smoked Chicken", "category": "BBQ & Grilling", "description": "Smoky split chicken halves brushed with a tangy mayo-based Alabama white sauce for a classic Southern BBQ experience.", "servings": 4, "prepTime": 20, "cookTime": 180, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"whole chickens halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/4 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"spicy brown mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"horseradish\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}]", "instructions": "1. Rub chicken halves with olive oil; season with salt, pepper, garlic powder, and paprika. 2. Preheat smoker to 275°F with hickory or pecan wood. 3. Place chicken halves skin-side up on smoker grates. 4. Smoke for 2.5-3 hours until breast meat reaches 165°F. 5. Whisk together mayo, vinegar, brown sugar, mustard, horseradish, and cayenne for white sauce. 6. Baste chicken with white sauce in final 15 minutes; cook until set. 7. Serve with additional white sauce on the side.", "tags": "alabama-bbq, smoking, chicken, southern", "source": "Classic", "nutritionData": "{\"calories\": 360, \"protein\": 27.0, \"carbs\": 4.0, \"fat\": 26.0}"},
  {"name": "Smoked Sausage Links", "category": "BBQ & Grilling", "description": "Classic smoked pork sausage links slow-smoked over hickory until deeply flavored with a satisfying snap in the casing.", "servings": 6, "prepTime": 10, "cookTime": 120, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"pork sausage links kielbasa or similar\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 cup\", \"name\": \"beer for spritzing\"}, {\"qty\": \"\", \"name\": \"mustard for serving\"}, {\"qty\": \"2 cups\", \"name\": \"sauerkraut for serving\"}]", "instructions": "1. Mix brown sugar, paprika, garlic powder, onion powder, pepper, and cayenne; lightly dust sausages with rub. 2. Preheat smoker to 225°F with hickory or pecan wood. 3. Place sausages on smoker grates. 4. Smoke for 2 hours spritzing with beer every 30 minutes. 5. Increase temperature to 275°F; smoke 30 more minutes until internal temp reaches 160°F. 6. Rest 5 minutes; serve with mustard and sauerkraut.", "tags": "smoking, sausage, BBQ, pork", "source": "Classic", "nutritionData": "{\"calories\": 660, \"protein\": 36.0, \"carbs\": 5.0, \"fat\": 57.0}"},
  {"name": "Classic Smashburger", "category": "BBQ & Grilling", "description": "Thin crispy-edged beef patties smashed on a screaming-hot griddle for maximum Maillard crust with melted American cheese.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"ground beef 80/20 divided into 8 balls\"}, {\"qty\": \"8 slices\", \"name\": \"American cheese\"}, {\"qty\": \"4\", \"name\": \"brioche buns\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tsp\", \"name\": \"yellow mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"ketchup\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"8 slices\", \"name\": \"dill pickle\"}, {\"qty\": \"1 cup\", \"name\": \"shredded iceberg lettuce\"}, {\"qty\": \"1\", \"name\": \"tomato sliced\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}]", "instructions": "1. Combine mayo, mustard, ketchup, and garlic powder to make burger sauce; set aside. 2. Heat griddle or cast iron over high heat until smoking; butter and toast buns until golden; set aside. 3. Add beef balls to griddle 2-4 at a time; immediately smash flat with a burger press or heavy spatula over parchment; season with salt and pepper. 4. Cook 45-60 seconds until edges are deeply browned; scrape and flip with firm pressure. 5. Place cheese on half the patties; stack a second patty on each cheesed patty; cook 30 seconds more. 6. Assemble on toasted buns with sauce, pickles, lettuce, and tomato.", "tags": "grilling, burgers, fast, American", "source": "https://www.seriouseats.com/ultra-smashed-cheeseburger-recipe-food-lab", "nutritionData": "{\"calories\": 815, \"protein\": 57.0, \"carbs\": 32.0, \"fat\": 42.0}"},
  {"name": "Juicy Lucy Burger", "category": "BBQ & Grilling", "description": "A Minnesota-style stuffed burger with molten cheese sealed inside the patty for an explosive cheesy surprise.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"ground beef 80/20\"}, {\"qty\": \"4 oz\", \"name\": \"American cheese cut in cubes\"}, {\"qty\": \"4 oz\", \"name\": \"cheddar cheese shredded\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4\", \"name\": \"brioche buns\"}, {\"qty\": \"\", \"name\": \"butter for buns\"}, {\"qty\": \"\", \"name\": \"lettuce tomato and pickles for serving\"}]", "instructions": "1. Mix Worcestershire, garlic powder, onion powder, salt, and pepper into ground beef gently. 2. Divide beef into 8 equal thin patties. 3. Place a mound of mixed cheese in center of 4 patties; top with remaining 4 patties; seal edges tightly. 4. Preheat grill to medium-high heat. 5. Grill stuffed patties 4-5 minutes per side until internal temp reaches 165°F; do not press. 6. Toast buttered buns on grill until golden. 7. Rest burgers 3 minutes before serving; warn guests about hot cheese interior.", "tags": "grilling, burgers, American, stuffed", "source": "Classic", "nutritionData": "{\"calories\": 860, \"protein\": 72.0, \"carbs\": 29.0, \"fat\": 48.0}"},
  {"name": "BBQ Bacon Burger", "category": "BBQ & Grilling", "description": "A thick grilled beef burger topped with crispy bacon, cheddar, caramelized onions, and smoky BBQ sauce.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"8\", \"name\": \"strips thick-cut bacon\"}, {\"qty\": \"4 slices\", \"name\": \"cheddar cheese\"}, {\"qty\": \"1\", \"name\": \"large onion thinly sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"4\", \"name\": \"brioche buns\"}, {\"qty\": \"1/2 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"\", \"name\": \"lettuce and tomato for serving\"}]", "instructions": "1. Form beef into 4 patties; season with salt, pepper, and garlic powder; refrigerate until grilling. 2. Cook bacon in skillet until crispy; set aside. 3. Caramelize onions in butter over medium-low heat 20-25 minutes until golden. 4. Preheat grill to medium-high; cook patties 3-4 minutes per side until 160°F internal temp. 5. Top each patty with cheddar in last minute of cooking; cover to melt. 6. Toast buns on grill. 7. Assemble with BBQ sauce on bun, lettuce, patty with cheese, bacon, and caramelized onions.", "tags": "grilling, burgers, American, BBQ", "source": "Classic", "nutritionData": "{\"calories\": 812, \"protein\": 63.0, \"carbs\": 48.0, \"fat\": 36.0}"},
  {"name": "Grilled Hot Dogs with Toppings", "category": "BBQ & Grilling", "description": "Char-grilled beef hot dogs in toasted buns with classic fixings of mustard, relish, onion, and sport peppers.", "servings": 6, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"all-beef hot dogs\"}, {\"qty\": \"6\", \"name\": \"hot dog buns\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"yellow mustard\"}, {\"qty\": \"1/2 cup\", \"name\": \"sweet relish\"}, {\"qty\": \"1\", \"name\": \"medium white onion diced\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes diced\"}, {\"qty\": \"6\", \"name\": \"sport peppers or banana peppers\"}, {\"qty\": \"\", \"name\": \"celery salt to taste\"}, {\"qty\": \"6\", \"name\": \"dill pickle spears\"}]", "instructions": "1. Preheat grill to medium-high heat. 2. Score hot dogs with shallow diagonal cuts on each side for better caramelization. 3. Grill hot dogs 6-8 minutes turning frequently until nicely charred and blistered. 4. Butter buns and toast cut-side down on grill 1-2 minutes until golden. 5. Place hot dog in bun; add mustard in zigzag pattern; top with relish, onion, tomato, and sport peppers. 6. Add pickle spear to side; dust with celery salt; serve immediately.", "tags": "grilling, hot-dogs, American, quick", "source": "Classic", "nutritionData": "{\"calories\": 345, \"protein\": 11.0, \"carbs\": 29.0, \"fat\": 18.0}"},
  {"name": "Bacon-Wrapped Grilled Pork Tenderloin", "category": "BBQ & Grilling", "description": "Juicy pork tenderloin wrapped in bacon and grilled until caramelized outside and perfectly rosy within.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"pork tenderloin\"}, {\"qty\": \"8\", \"name\": \"strips thin-cut bacon\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"\", \"name\": \"toothpicks for securing\"}]", "instructions": "1. Mix mustard, brown sugar, garlic powder, paprika, pepper, salt, and thyme; rub over tenderloin. 2. Wrap tenderloin tightly with overlapping bacon strips securing with toothpicks. 3. Preheat grill to medium heat; set up two-zone cooking. 4. Sear wrapped tenderloin over direct heat 2-3 minutes per side until bacon is browned. 5. Move to indirect heat; close lid and cook until pork reaches 145°F internal temp, about 20-25 minutes. 6. Rest 5 minutes before slicing.", "tags": "grilling, pork, bacon-wrapped, quick", "source": "https://heygrillhey.com/bacon-wrapped-pork-tenderloin/", "nutritionData": "{\"calories\": 352, \"protein\": 50.0, \"carbs\": 7.0, \"fat\": 12.0}"},
  {"name": "Grilled Flank Steak with Garlic Herb Marinade", "category": "BBQ & Grilling", "description": "Marinated flank steak grilled hot and fast over charcoal and sliced thin against the grain for maximum tenderness.", "servings": 4, "prepTime": 20, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"flank steak\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 tsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"\", \"name\": \"pinch red pepper flakes\"}]", "instructions": "1. Whisk together soy sauce, olive oil, Worcestershire, garlic, rosemary, thyme, brown sugar, pepper, lemon juice, and pepper flakes for marinade. 2. Score flank steak lightly in crosshatch pattern; submerge in marinade; refrigerate 4-8 hours. 3. Remove steak from marinade; pat dry; bring to room temperature 30 minutes. 4. Preheat grill to high heat. 5. Grill steak 4-5 minutes per side for medium-rare (130°F internal). 6. Rest 8 minutes then slice very thin against the grain.", "tags": "grilling, beef, quick, weeknight", "source": "Classic", "nutritionData": "{\"calories\": 360, \"protein\": 48.0, \"carbs\": 4.0, \"fat\": 11.0}"},
  {"name": "Grilled Chicken Thighs with Honey Sriracha Glaze", "category": "BBQ & Grilling", "description": "Bone-in chicken thighs grilled over two-zone heat then glazed with a sticky honey sriracha sauce for irresistible caramelization.", "servings": 4, "prepTime": 15, "cookTime": 40, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"sriracha sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}]", "instructions": "1. Season chicken thighs with salt, pepper, garlic powder, and paprika; let sit 30 minutes. 2. Whisk honey, sriracha, soy sauce, vinegar, and garlic together for glaze. 3. Preheat grill to medium with two-zone setup; brush grates with oil. 4. Place thighs skin-side down over indirect heat; cook 25 minutes flipping once. 5. Move to direct heat skin-side down; brush generously with glaze; grill 5-7 minutes per side until internal temp reaches 165°F and glaze is caramelized. 6. Rest 5 minutes before serving.", "tags": "grilling, chicken, sticky-glaze, spicy", "source": "https://heygrillhey.com/grilled-chicken-thighs/", "nutritionData": "{\"calories\": 345, \"protein\": 27.0, \"carbs\": 16.0, \"fat\": 19.0}"},
  {"name": "Grilled Salmon with Brown Butter and Dill", "category": "BBQ & Grilling", "description": "Salmon fillets seasoned simply and grilled over high heat then finished with a nutty brown butter and fresh dill sauce.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"salmon fillets 6 oz each skin-on\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh dill chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers\"}, {\"qty\": \"1\", \"name\": \"lemon juice and zest\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}]", "instructions": "1. Pat salmon dry; brush with olive oil; season with salt, pepper, and garlic powder. 2. Preheat grill to high heat; clean and oil grates well. 3. Place salmon skin-side down on grill; cook 4-5 minutes without moving. 4. Carefully flip; cook 3-4 more minutes until salmon flakes easily at 130-135°F. 5. Meanwhile melt butter in small skillet over medium heat until golden and nutty; remove from heat. 6. Stir in dill, capers, lemon juice, and pepper flakes into brown butter. 7. Plate salmon and spoon brown butter sauce over top.", "tags": "grilling, seafood, quick, brown-butter", "source": "Classic", "nutritionData": "{\"calories\": 460, \"protein\": 34.0, \"carbs\": 2.0, \"fat\": 34.0}"},
  {"name": "Grilled Lamb Chops with Garlic and Rosemary", "category": "BBQ & Grilling", "description": "Rack of lamb chops marinated in garlic and rosemary then grilled hot and fast to medium-rare perfection.", "servings": 4, "prepTime": 15, "cookTime": 10, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"lamb rib chops from a rack of lamb\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh rosemary minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}]", "instructions": "1. Combine garlic, rosemary, olive oil, salt, pepper, lemon juice, mustard, and oregano in small bowl. 2. Coat lamb chops in marinade; let marinate 30 minutes at room temperature. 3. Preheat grill to high heat; clean and oil grates. 4. Shake excess marinade from chops; place on grill over direct heat. 5. Grill 3 minutes per side for medium-rare (135°F internal). 6. Rest 3 minutes; serve immediately.", "tags": "grilling, lamb, Mediterranean-inspired, quick", "source": "https://www.seriouseats.com/perfectly-grilled-lamb-rib-or-loin-chops", "nutritionData": "{\"calories\": 390, \"protein\": 38.0, \"carbs\": 3.0, \"fat\": 25.0}"},
  {"name": "Grilled Shrimp Skewers with Garlic Butter", "category": "BBQ & Grilling", "description": "Jumbo shrimp threaded on skewers and grilled in under 10 minutes with a lemon garlic butter baste.", "servings": 4, "prepTime": 15, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"jumbo shrimp peeled and deveined\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"juice of 1 lemon\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"8\", \"name\": \"metal or soaked wooden skewers\"}]", "instructions": "1. Toss shrimp with olive oil, paprika, salt, pepper, and red pepper flakes. 2. Thread shrimp onto skewers (2-3 per skewer in a C shape). 3. Mix melted butter, garlic, lemon juice, and parsley for basting sauce. 4. Preheat grill to high heat. 5. Grill shrimp 2-3 minutes per side brushing with garlic butter after flipping. 6. Remove immediately when shrimp are pink and curled; serve with remaining garlic butter.", "tags": "grilling, seafood, quick, skewers", "source": "Classic", "nutritionData": "{\"calories\": 300, \"protein\": 41.0, \"carbs\": 2.0, \"fat\": 15.0}"},
  {"name": "Elote Grilled Corn on the Cob", "category": "BBQ & Grilling", "description": "Mexican street corn charred on the grill then slathered with mayo, cotija cheese, chili powder, and lime juice.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"ears fresh corn in husks\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"3 tbsp\", \"name\": \"sour cream\"}, {\"qty\": \"1/2 cup\", \"name\": \"cotija cheese crumbled\"}, {\"qty\": \"1 tsp\", \"name\": \"ancho chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2\", \"name\": \"limes juiced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}, {\"qty\": \"\", \"name\": \"pinch cayenne\"}]", "instructions": "1. Peel back corn husks without removing; strip silk; soak in cold water 30 minutes. 2. Preheat grill to medium-high heat. 3. Pull husks back up around corn; grill for 15 minutes turning occasionally. 4. Peel back husks; grill directly on grates 2-3 minutes per side until kernels are charred. 5. Brush each cob with mayo-sour cream mixture. 6. Roll in cotija cheese; dust with chili powder, paprika, and cayenne. 7. Squeeze lime juice over top; garnish with cilantro.", "tags": "grilling, vegetarian, Mexican-inspired, street-food", "source": "Classic", "nutritionData": "{\"calories\": 280, \"protein\": 6.0, \"carbs\": 29.0, \"fat\": 16.0}"},
  {"name": "Grilled Portobello Mushrooms with Balsamic and Herbs", "category": "BBQ & Grilling", "description": "Meaty portobello caps marinated in balsamic and herbs then grilled until tender for a satisfying vegetarian BBQ main.", "servings": 4, "prepTime": 15, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large portobello mushroom caps stems removed\"}, {\"qty\": \"3 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley for serving\"}, {\"qty\": \"1/4 cup\", \"name\": \"goat cheese crumbled for serving\"}]", "instructions": "1. Whisk balsamic, olive oil, garlic, thyme, rosemary, mustard, salt, and pepper together for marinade. 2. Place mushroom caps gill-side up in shallow dish; pour marinade over; marinate 30 minutes. 3. Preheat grill to medium-high heat. 4. Place mushrooms gill-side down on grill; cook 5-6 minutes until grill marks form. 5. Flip; brush with remaining marinade; grill 5-6 more minutes until tender and cooked through. 6. Top with goat cheese and parsley; serve immediately.", "tags": "grilling, vegetarian, mushroom, balsamic", "source": "Classic", "nutritionData": "{\"calories\": 284, \"protein\": 8.0, \"carbs\": 6.0, \"fat\": 27.0}"},
  {"name": "Korean BBQ Short Ribs (Kalbi)", "category": "BBQ & Grilling", "description": "Flanken-cut beef short ribs marinated in soy, Asian pear, sesame oil, and garlic then grilled fast over high heat.", "servings": 4, "prepTime": 20, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"flanken-cut beef short ribs\"}, {\"qty\": \"1/2 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"mirin\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1\", \"name\": \"Asian pear or kiwi grated\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"2\", \"name\": \"green onions finely chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}, {\"qty\": \"\", \"name\": \"steamed rice and kimchi for serving\"}]", "instructions": "1. Score ribs between bones if not already flanken cut. 2. Blend soy sauce, brown sugar, mirin, garlic, sesame oil, grated pear, ginger, green onions, and pepper into marinade. 3. Marinate ribs in marinade 4-8 hours in refrigerator; bring to room temperature before grilling. 4. Preheat grill to high heat. 5. Grill ribs 2-3 minutes per side until caramelized and cooked through. 6. Garnish with sesame seeds and additional green onion; serve with rice and kimchi.", "tags": "Korean-BBQ, grilling, beef, Asian", "source": "https://blog.thermoworks.com/korean-shortribs-kalbi/", "nutritionData": "{\"calories\": 430, \"protein\": 22.0, \"carbs\": 20.0, \"fat\": 29.0}"},
  {"name": "Japanese Yakitori Chicken Skewers", "category": "BBQ & Grilling", "description": "Classic Japanese grilled chicken thigh and scallion skewers basted repeatedly with homemade tare sauce over charcoal.", "servings": 4, "prepTime": 30, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken thighs cut in 1.5 inch pieces\"}, {\"qty\": \"4\", \"name\": \"green onions cut in 1.5 inch pieces\"}, {\"qty\": \"1/2 cup\", \"name\": \"soy sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"mirin\"}, {\"qty\": \"1/4 cup\", \"name\": \"sake\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"2 tsp\", \"name\": \"brown sugar\"}, {\"qty\": \"\", \"name\": \"bamboo skewers soaked 30 minutes\"}, {\"qty\": \"\", \"name\": \"sesame seeds for garnish\"}, {\"qty\": \"\", \"name\": \"shichimi togarashi optional\"}]", "instructions": "1. Combine soy sauce, mirin, sake, water, and brown sugar in small saucepan; bring to boil then reduce to 1/3 volume over low heat about 30 minutes; cool to make tare. 2. Thread chicken pieces and scallion alternately on skewers (3 chicken and 2 scallion per skewer). 3. Preheat charcoal grill or broiler to high heat. 4. Grill skewers 6 minutes total turning every 90 seconds. 5. Baste with tare on both sides; grill 3-4 more minutes until caramelized. 6. Baste once more; grill 1 minute; serve with extra tare and shichimi.", "tags": "Japanese, grilling, skewers, Asian", "source": "https://www.justonecookbook.com/yakitori/", "nutritionData": "{\"calories\": 298, \"protein\": 30.0, \"carbs\": 14.0, \"fat\": 11.0}"},
  {"name": "Thai Grilled Chicken (Gai Yang)", "category": "BBQ & Grilling", "description": "Thai-style marinated chicken halves grilled until caramelized and served with a sweet chili dipping sauce.", "servings": 4, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken 3.5 lb butterflied and halved\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2\", \"name\": \"stalks lemongrass tender white part\"}, {\"qty\": \"2 tbsp\", \"name\": \"fish sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"oyster sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"white pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"coriander\"}, {\"qty\": \"1/2 cup\", \"name\": \"coconut milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/4 cup\", \"name\": \"sweet chili sauce for serving\"}, {\"qty\": \"\", \"name\": \"lime wedges\"}]", "instructions": "1. Blend garlic, lemongrass, fish sauce, oyster sauce, soy sauce, brown sugar, white pepper, coriander, and coconut milk into marinade. 2. Coat chicken halves in marinade; refrigerate 4-8 hours. 3. Bring chicken to room temperature; preheat grill to medium heat. 4. Grill chicken skin-side down over indirect heat 20 minutes. 5. Flip; continue grilling 20-25 minutes until breast reaches 165°F. 6. Move to direct heat to char skin 3-4 minutes. 7. Rest 10 minutes; serve with sweet chili sauce and lime wedges.", "tags": "Thai, grilling, chicken, Asian", "source": "https://www.recipetineats.com/thai-grilled-chicken-gai-yang/", "nutritionData": "{\"calories\": 283, \"protein\": 28.0, \"carbs\": 9.0, \"fat\": 15.0}"},
  {"name": "Greek Pork Souvlaki Skewers", "category": "BBQ & Grilling", "description": "Marinated pork shoulder cubes threaded on skewers and grilled over charcoal for crispy edges and juicy centers.", "servings": 4, "prepTime": 20, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"pork shoulder cut in 1.5 inch cubes\"}, {\"qty\": \"4 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"\", \"name\": \"juice of 2 lemons\"}, {\"qty\": \"1 tbsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4\", \"name\": \"pita breads\"}, {\"qty\": \"1 cup\", \"name\": \"tzatziki\"}, {\"qty\": \"1\", \"name\": \"tomato diced\"}, {\"qty\": \"1/4\", \"name\": \"red onion thinly sliced\"}, {\"qty\": \"\", \"name\": \"fresh parsley\"}]", "instructions": "1. Whisk olive oil, garlic, lemon juice, oregano, thyme, salt, and pepper together for marinade. 2. Toss pork cubes in marinade; refrigerate 2-4 hours. 3. Thread pork onto metal skewers (5-6 pieces per skewer). 4. Preheat grill to high heat. 5. Grill skewers 12-15 minutes total turning every 3-4 minutes until pork is caramelized and reaches 145°F. 6. Warm pita on grill 30 seconds per side. 7. Serve pork on pita with tzatziki, tomato, onion, and parsley.", "tags": "Greek, grilling, pork, skewers", "source": "Classic", "nutritionData": "{\"calories\": 523, \"protein\": 34.0, \"carbs\": 37.0, \"fat\": 23.0}"},
  {"name": "Lebanese Kafta Kebabs", "category": "BBQ & Grilling", "description": "Spiced ground lamb and beef kofta shaped onto flat skewers and grilled over charcoal until juicy and charred.", "servings": 4, "prepTime": 20, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground lamb\"}, {\"qty\": \"0.5 lb\", \"name\": \"ground beef\"}, {\"qty\": \"1\", \"name\": \"small onion grated\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh mint chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"allspice\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"metal skewers\"}, {\"qty\": \"\", \"name\": \"pita and hummus for serving\"}]", "instructions": "1. Combine ground lamb, ground beef, grated onion, garlic, parsley, mint, and all spices; mix thoroughly. 2. Refrigerate mixture 30 minutes. 3. Divide into 8 portions; shape each portion around a flat metal skewer into a 6-inch cylinder. 4. Preheat grill to high heat. 5. Grill kafta skewers 3-4 minutes per side turning once or twice until browned and cooked through. 6. Serve on pita with hummus, tomato, onion, and fresh herbs.", "tags": "Lebanese, grilling, lamb, Middle-Eastern", "source": "Classic", "nutritionData": "{\"calories\": 508, \"protein\": 38.0, \"carbs\": 20.0, \"fat\": 20.0}"},
  {"name": "Brazilian Picanha Churrasco", "category": "BBQ & Grilling", "description": "Rump cap steaks scored through the fat cap, skewered in a C-shape, seasoned with just rock salt, and grilled over charcoal Brazilian-style.", "servings": 6, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"picanha rump cap with fat cap intact\"}, {\"qty\": \"3 tbsp\", \"name\": \"coarse rock salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"chimichurri sauce for serving\"}, {\"qty\": \"\", \"name\": \"crusty bread and rice for serving\"}]", "instructions": "1. Score fat cap in a crosshatch pattern without cutting into meat. 2. Slice picanha into 1-inch thick steaks keeping fat cap on. 3. Fold each steak into a C-shape and skewer so fat is on outside. 4. Season generously with rock salt and pepper on all sides. 5. Preheat charcoal grill to very high heat with glowing coals. 6. Grill skewered picanha turning every 3-4 minutes; cook with fat side toward heat first to render. 7. Cook 18-20 minutes total for medium (135°F internal). 8. Rest 5 minutes; slice thin at the table; serve with chimichurri.", "tags": "Brazilian, grilling, beef, churrasco", "source": "https://www.seriouseats.com/picanha-brazilian-grilled-beef-sirloin-cap", "nutritionData": "{\"calories\": 450, \"protein\": 38.0, \"carbs\": 1.0, \"fat\": 32.0}"},
  {"name": "Smoked Mac and Cheese", "category": "BBQ & Grilling", "description": "Creamy three-cheese macaroni in a cast iron skillet smoked at low temperature for an hour to develop a signature smoky depth.", "servings": 8, "prepTime": 20, "cookTime": 70, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"elbow macaroni cooked al dente\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"ground mustard powder\"}, {\"qty\": \"2 cups\", \"name\": \"half-and-half\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese\"}, {\"qty\": \"3 cups\", \"name\": \"sharp cheddar cheese shredded\"}, {\"qty\": \"1.5 cups\", \"name\": \"smoked gouda cheese shredded\"}, {\"qty\": \"1 cup\", \"name\": \"panko bread crumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"butter melted for topping\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat smoker to 225°F using apple or cherry wood. 2. Cook macaroni to al dente; drain and set aside. 3. Melt 1/2 cup butter in 12-inch cast iron over medium heat; whisk in flour to form roux; whisk in mustard powder. 4. Add half-and-half; bring to boil whisking; reduce heat; whisk in cream cheese until smooth. 5. Stir in cheddar and gouda until melted; season with salt, pepper. 6. Fold in cooked macaroni; mix melted butter, panko, and paprika; sprinkle over top. 7. Place skillet in smoker; smoke 1 hour until topping is golden and mac is infused with smoke.", "tags": "smoking, side-dish, comfort-food, BBQ-sides", "source": "https://heygrillhey.com/smoked-mac-and-cheese/", "nutritionData": "{\"calories\": 660, \"protein\": 23.0, \"carbs\": 58.0, \"fat\": 37.0}"},
  {"name": "Fluffy Buttermilk Pancake Stack", "category": "Breakfast for Dinner", "description": "Tall, golden buttermilk pancakes stacked high and served with maple syrup and butter for a classic dinner.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"\", \"name\": \"butter and maple syrup for serving\"}]", "instructions": "1. Whisk flour, sugar, baking powder, baking soda, and salt in a large bowl. 2. In a separate bowl whisk buttermilk, eggs, melted butter, and vanilla. 3. Pour wet ingredients into dry and stir until just combined; let batter rest 10 minutes. 4. Heat a griddle or skillet over medium heat and lightly grease with butter. 5. Pour 1/4 cup batter per pancake; cook until bubbles form on surface and edges look set, about 2 minutes. 6. Flip and cook 1-2 minutes more until golden. Repeat with remaining batter. 7. Serve stacked with butter and warm maple syrup.", "tags": "family-friendly, weekend dinner, vegetarian", "source": "https://www.kingarthurbaking.com/recipes/buttermilk-pancakes-recipe", "nutritionData": "{\"calories\": 420, \"protein\": 12.0, \"carbs\": 58.0, \"fat\": 16.0}"},
  {"name": "Banana Pancakes", "category": "Breakfast for Dinner", "description": "Moist, banana-studded pancakes topped with caramelized banana slices and a drizzle of maple syrup.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"3\", \"name\": \"ripe bananas mashed\"}, {\"qty\": \"2\", \"name\": \"large eggs separated\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"\", \"name\": \"vegetable oil for griddle\"}]", "instructions": "1. Whisk flour, baking powder, cinnamon, salt, and sugar in a large bowl. 2. Mash 2 bananas with sugar in a separate bowl until smooth; whisk in egg yolks, milk, melted butter, and vanilla. 3. Pour wet ingredients into dry and stir until just combined. 4. Beat egg whites to soft peaks and fold into batter. 5. Slice remaining banana and set aside; heat a greased griddle over medium heat. 6. Pour 1/4 cup batter per pancake; place 2-3 banana slices on each. Cook until bubbles form, about 2 minutes, then flip and cook 2 minutes more. 7. Serve with maple syrup and extra banana slices.", "tags": "family-friendly, vegetarian, fruit-forward", "source": "https://www.kingarthurbaking.com/recipes/banana-pancakes-recipe", "nutritionData": "{\"calories\": 450, \"protein\": 13.0, \"carbs\": 72.0, \"fat\": 14.0}"},
  {"name": "Blueberry Pancakes", "category": "Breakfast for Dinner", "description": "Fluffy buttermilk pancakes bursting with fresh blueberries, served with warm maple syrup.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tbsp\", \"name\": \"sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"fresh or frozen blueberries\"}, {\"qty\": \"\", \"name\": \"butter for cooking\"}]", "instructions": "1. Whisk flour, sugar, baking powder, baking soda, and salt in a large bowl. 2. Whisk buttermilk, eggs, melted butter, and vanilla in another bowl. 3. Fold wet into dry until just combined; gently fold in blueberries. 4. Let batter rest 5 minutes while heating a greased griddle over medium-low heat. 5. Pour 1/3 cup batter per pancake and cook until bubbles form on top, about 2-3 minutes. 6. Flip and cook 2 minutes until cooked through. 7. Serve with maple syrup and extra blueberries.", "tags": "vegetarian, fruit-forward, family-friendly", "source": "Classic", "nutritionData": "{\"calories\": 440, \"protein\": 13.0, \"carbs\": 63.0, \"fat\": 14.0}"},
  {"name": "Savory Dutch Baby with Mushrooms and Gruyere", "category": "Breakfast for Dinner", "description": "A dramatic oven-puffed German pancake loaded with sauteed mushrooms, Gruyere, and fresh thyme.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"3/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter divided\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded Gruyere cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for finishing\"}]", "instructions": "1. Preheat oven to 450°F and place a 12-inch cast iron skillet inside to heat. 2. Blend eggs, milk, flour, salt, and pepper in a blender until smooth; rest 10 minutes. 3. Meanwhile saute mushrooms in 1 tbsp butter over medium-high heat until browned, about 6 minutes; add garlic and thyme, season, and set aside. 4. Remove skillet from oven; add remaining 2 tbsp butter and swirl to coat. Immediately pour in batter. 5. Sprinkle Gruyere and mushrooms over top. Bake 20-22 minutes until puffed and deep golden. 6. Top with chives and flaky salt; serve immediately directly from the pan.", "tags": "vegetarian, impressive, gluten-adaptable", "source": "https://sallysbakingaddiction.com/dutch-baby-pancake-recipe/", "nutritionData": "{\"calories\": 380, \"protein\": 20.0, \"carbs\": 22.0, \"fat\": 24.0}"},
  {"name": "Lemon Ricotta Pancakes", "category": "Breakfast for Dinner", "description": "Light and creamy ricotta pancakes brightened with lemon zest, topped with blueberry syrup.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"whole-milk ricotta\"}, {\"qty\": \"1 cup\", \"name\": \"buttermilk\"}, {\"qty\": \"3\", \"name\": \"large eggs separated\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon zest\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 cup\", \"name\": \"fresh blueberries\"}, {\"qty\": \"3 tbsp\", \"name\": \"maple syrup\"}]", "instructions": "1. Whisk flour, baking powder, baking soda, salt, and sugar in a large bowl. 2. Whisk ricotta, buttermilk, egg yolks, lemon zest, lemon juice, and melted butter together. 3. Fold wet ingredients into dry until just combined. 4. Beat egg whites to stiff peaks; gently fold into batter in two additions. 5. Heat a lightly buttered griddle over medium-low heat. Cook 1/4-cup portions 2-3 minutes per side. 6. For blueberry syrup: simmer blueberries and maple syrup in a small pot 5 minutes until jammy. 7. Serve pancakes topped with warm blueberry syrup.", "tags": "vegetarian, impressive, brunch-worthy", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 18.0, \"carbs\": 60.0, \"fat\": 19.0}"},
  {"name": "Sheet Pan Pancakes", "category": "Breakfast for Dinner", "description": "Oven-baked buttermilk pancakes on a sheet pan cut into squares for feeding a crowd effortlessly.", "servings": 6, "prepTime": 15, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 1/2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 1/4 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"5 tbsp\", \"name\": \"unsalted butter melted plus more for pan\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"mixed fresh berries\"}, {\"qty\": \"\", \"name\": \"powdered sugar and maple syrup for serving\"}]", "instructions": "1. Preheat oven to 425°F; generously butter a rimmed 13x18-inch sheet pan. 2. Whisk flour, sugar, baking powder, baking soda, and salt in a large bowl. 3. Whisk buttermilk, eggs, melted butter, and vanilla; fold into dry ingredients until just combined. 4. Pour batter onto prepared pan; spread evenly. Scatter berries over top. 5. Bake 15-18 minutes until set in center and edges are golden. 6. Cut into squares and serve with maple syrup.", "tags": "crowd-pleasing, vegetarian, make-ahead", "source": "https://www.nytimes.com/2019/08/23/dining/sheet-pan-pancakes.html", "nutritionData": "{\"calories\": 400, \"protein\": 11.0, \"carbs\": 56.0, \"fat\": 15.0}"},
  {"name": "Classic Belgian Waffles", "category": "Breakfast for Dinner", "description": "Light yeast-risen Belgian waffles with deep pockets for holding pools of butter and maple syrup.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 cups\", \"name\": \"warm whole milk\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"maple syrup\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/2 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"\", \"name\": \"butter and maple syrup for serving\"}, {\"qty\": \"\", \"name\": \"fresh berries and whipped cream optional\"}]", "instructions": "1. Combine warm milk, melted butter, maple syrup, salt, and eggs in a large bowl; whisk to combine. 2. Add flour and yeast; stir until smooth. Cover and rest at room temperature 1 hour until bubbly. (Can refrigerate overnight.) 3. Preheat waffle iron; spray with nonstick cooking spray. 4. Stir down batter; pour 2/3 to 3/4 cup per waffle into the iron. Close and cook 5-6 minutes until deep golden and crisp. 5. Serve immediately with butter, maple syrup, and fresh berries if desired.", "tags": "vegetarian, crispy, crowd-pleasing", "source": "https://www.kingarthurbaking.com/recipes/belgian-style-yeast-waffles-recipe", "nutritionData": "{\"calories\": 510, \"protein\": 13.0, \"carbs\": 62.0, \"fat\": 22.0}"},
  {"name": "Chicken and Waffles", "category": "Breakfast for Dinner", "description": "Crispy buttermilk-fried chicken thighs served on fluffy Belgian waffles with hot sauce and maple syrup.", "servings": 4, "prepTime": 30, "cookTime": 30, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken thighs\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"buttermilk\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"hot sauce\"}, {\"qty\": \"3 cups\", \"name\": \"all-purpose flour divided\"}, {\"qty\": \"2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour for waffles\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"2 cups\", \"name\": \"buttermilk for waffles\"}, {\"qty\": \"2\", \"name\": \"eggs separated\"}, {\"qty\": \"1/2 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"\", \"name\": \"maple syrup and hot sauce for serving\"}]", "instructions": "1. Cut chicken into strips; marinate in buttermilk, 1 egg, and hot sauce at least 1 hour or overnight. 2. Make waffle batter: whisk 2 cups flour, baking powder, cinnamon, and 1 tsp salt; combine buttermilk, oil, and egg yolks; fold together. Beat egg whites to peaks and fold in. 3. Whisk 3 cups flour, garlic powder, paprika, cayenne, and salt for dredge. 4. Dredge chicken in flour, back into buttermilk, then flour again. 5. Fry in 350°F oil 6-7 minutes per batch until golden and 165°F internal. Drain on a rack. 6. Cook waffles in preheated iron until golden and crisp. 7. Serve chicken on waffles with maple syrup and hot sauce.", "tags": "comfort food, crowd-pleasing, sweet-savory", "source": "Classic", "nutritionData": "{\"calories\": 820, \"protein\": 52.0, \"carbs\": 68.0, \"fat\": 35.0}"},
  {"name": "Cornbread Waffles", "category": "Breakfast for Dinner", "description": "Crispy-edged cornbread waffles with a tender crumb, perfect topped with fried eggs or chili.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"yellow cornmeal\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"molasses\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 cup\", \"name\": \"buttermilk\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"4\", \"name\": \"large eggs fried for serving\"}, {\"qty\": \"\", \"name\": \"hot sauce for serving\"}]", "instructions": "1. Whisk cornmeal, flour, baking powder, baking soda, and salt in a bowl. 2. Whisk molasses, melted butter, buttermilk, and 1 egg; pour into dry ingredients and stir until just combined. Let rest 10 minutes. 3. Preheat waffle iron; brush with melted butter or cooking spray. 4. Cook waffles in 1/4-cup ladlefuls until lightly browned and crisp, about 4-5 minutes. 5. Fry eggs in butter until whites are set and yolks are runny. 6. Serve cornbread waffles topped with a fried egg and hot sauce.", "tags": "vegetarian, Southern-inspired, savory", "source": "https://smittenkitchen.com/2017/03/cornbread-waffles/", "nutritionData": "{\"calories\": 480, \"protein\": 17.0, \"carbs\": 53.0, \"fat\": 23.0}"},
  {"name": "Savory Bacon-Cheddar Waffles", "category": "Breakfast for Dinner", "description": "Crispy waffles loaded with crumbled bacon and sharp cheddar, served with sour cream and chives.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6 slices\", \"name\": \"thick-cut bacon\"}, {\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 3/4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 cup\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"2\", \"name\": \"green onions thinly sliced\"}, {\"qty\": \"\", \"name\": \"sour cream and chives for serving\"}]", "instructions": "1. Cook bacon in a skillet until crisp; drain on paper towels and crumble. Reserve 1 tbsp drippings. 2. Whisk flour, baking powder, salt, and pepper in a large bowl. 3. Whisk milk, eggs, and melted butter together; stir into dry ingredients until just combined. 4. Fold in crumbled bacon, cheddar, and green onions. 5. Preheat waffle iron and brush with reserved bacon drippings or cooking spray. 6. Cook waffles until deep golden and crisp, about 5 minutes. 7. Serve topped with sour cream and extra chives.", "tags": "savory, comfort food, high-protein", "source": "Classic", "nutritionData": "{\"calories\": 610, \"protein\": 24.0, \"carbs\": 52.0, \"fat\": 33.0}"},
  {"name": "Classic French Toast", "category": "Breakfast for Dinner", "description": "Thick-cut bread soaked in a vanilla-cinnamon custard and pan-fried to golden perfection.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"thick slices brioche or challah bread\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"\", \"name\": \"pinch of kosher salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"powdered sugar and maple syrup for serving\"}]", "instructions": "1. Whisk eggs, milk, sugar, vanilla, cinnamon, and salt in a shallow dish. 2. Heat 1 tbsp butter in a large skillet over medium heat until foamy. 3. Dip bread slices one at a time into the custard, letting each soak 20-30 seconds per side. 4. Cook in batches, 2-3 slices at a time, 2-3 minutes per side until deep golden. 5. Add more butter between batches. 6. Serve dusted with powdered sugar and warm maple syrup.", "tags": "vegetarian, comfort food, family-friendly", "source": "Classic", "nutritionData": "{\"calories\": 450, \"protein\": 16.0, \"carbs\": 54.0, \"fat\": 18.0}"},
  {"name": "Baked French Toast Casserole", "category": "Breakfast for Dinner", "description": "Overnight cream cheese French toast casserole with a brown sugar crumb topping, baked until golden.", "servings": 8, "prepTime": 20, "cookTime": 55, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"loaf challah bread cubed\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour for topping\"}, {\"qty\": \"1/2 cup\", \"name\": \"brown sugar for topping\"}, {\"qty\": \"4 tbsp\", \"name\": \"cold unsalted butter cubed\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon for topping\"}, {\"qty\": \"\", \"name\": \"maple syrup for serving\"}]", "instructions": "1. Grease a 9x13-inch baking dish. Spread bread cubes in the pan. 2. Whisk cream cheese, eggs, milk, cream, brown sugar, vanilla, cinnamon, and salt until smooth; pour over bread. Cover and refrigerate 3 hours or overnight. 3. Make crumb topping: mix flour, brown sugar, and cinnamon; cut in cold butter until pea-sized crumbles form. Refrigerate. 4. Preheat oven to 350°F. Let casserole sit at room temperature 10 minutes. 5. Scatter crumb topping over casserole; bake uncovered 20 minutes, then tent with foil and bake 30-35 minutes more until center is set. 6. Cool 5 minutes; serve with maple syrup.", "tags": "make-ahead, crowd-pleasing, vegetarian", "source": "https://sallysbakingaddiction.com/baked-cream-cheese-french-toast-casserole/", "nutritionData": "{\"calories\": 510, \"protein\": 14.0, \"carbs\": 58.0, \"fat\": 24.0}"},
  {"name": "Stuffed French Toast", "category": "Breakfast for Dinner", "description": "Challah slices stuffed with whipped cream cheese and strawberry jam, baked until puffed and golden.", "servings": 6, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"loaf challah sliced 1 1/2-inch thick\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"10 oz\", \"name\": \"strawberry jam\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"4 tbsp\", \"name\": \"salted butter melted\"}, {\"qty\": \"1 tbsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"2 tsp\", \"name\": \"honey\"}, {\"qty\": \"\", \"name\": \"pinch of kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"fresh strawberries sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"honey\"}, {\"qty\": \"2 tsp\", \"name\": \"lemon juice\"}, {\"qty\": \"\", \"name\": \"maple syrup for serving\"}]", "instructions": "1. Grease a 9x13-inch baking dish. 2. Whip cream cheese until fluffy. Slice each bread piece almost through horizontally; spread inside with cream cheese and jam. Press closed. 3. Whisk eggs, milk, melted butter, vanilla, honey, and salt in a bowl. 4. Dip each stuffed piece in custard, soaking at least 1 minute; arrange in dish. Pour remaining custard over. Cover and refrigerate 30 minutes to overnight. 5. Preheat oven to 375°F. Cover with foil; bake 25 minutes. Remove foil; bake 20-25 minutes until golden. 6. Toss strawberries with honey and lemon juice. Serve French toast topped with strawberries.", "tags": "vegetarian, impressive, make-ahead", "source": "https://www.halfbakedharvest.com/baked-strawberry-cream-cheese-stuffed-french-toast/", "nutritionData": "{\"calories\": 560, \"protein\": 15.0, \"carbs\": 71.0, \"fat\": 23.0}"},
  {"name": "French Toast Sticks", "category": "Breakfast for Dinner", "description": "Thick-cut bread fingers dipped in vanilla custard and pan-fried, rolled in cinnamon sugar for dipping.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 slices\", \"name\": \"Texas toast or thick white bread\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/3 cup\", \"name\": \"granulated sugar for coating\"}, {\"qty\": \"2 tsp\", \"name\": \"cinnamon for coating\"}, {\"qty\": \"\", \"name\": \"warm maple syrup for dipping\"}]", "instructions": "1. Remove crusts from bread; cut each slice into 3 thick sticks. 2. Whisk eggs, cream, vanilla, sugar, cinnamon, and salt in a shallow dish. 3. Mix coating sugar and cinnamon on a plate; set aside. 4. Melt 2 tbsp butter in a large skillet over medium heat. 5. Quickly dip each stick in egg mixture (do not soak); shake off excess and place in pan. Cook in batches 2-3 minutes per side until golden on all sides. 6. Immediately roll hot sticks in cinnamon sugar. Serve with maple syrup.", "tags": "family-friendly, kid-approved, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 530, \"protein\": 14.0, \"carbs\": 66.0, \"fat\": 23.0}"},
  {"name": "Brioche French Toast", "category": "Breakfast for Dinner", "description": "Ultra-rich brioche slices soaked in orange-scented custard and pan-fried to a lacquered, golden finish.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"thick slices brioche bread\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"orange zest\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cinnamon\"}, {\"qty\": \"\", \"name\": \"pinch of nutmeg\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"\", \"name\": \"powdered sugar and maple syrup for serving\"}, {\"qty\": \"\", \"name\": \"fresh berries optional\"}]", "instructions": "1. Whisk eggs, milk, cream, sugar, vanilla, orange zest, cinnamon, and nutmeg in a shallow bowl. 2. Melt 1 tbsp butter in a large skillet over medium heat until foamy. 3. Soak brioche slices in custard 30 seconds per side. 4. Cook 2-3 slices at a time, 2-3 minutes per side until deep golden brown. 5. Add more butter as needed between batches. 6. Dust with powdered sugar; serve with maple syrup and fresh berries.", "tags": "vegetarian, indulgent, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 15.0, \"carbs\": 53.0, \"fat\": 23.0}"},
  {"name": "Tunisian Shakshuka", "category": "Breakfast for Dinner", "description": "Bold North African eggs poached in a spiced harissa tomato sauce with olives, capers, and feta.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"harissa paste\"}, {\"qty\": \"1 tsp\", \"name\": \"caraway seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 can\", \"name\": \"28 oz crushed tomatoes\"}, {\"qty\": \"1/4 cup\", \"name\": \"pitted green olives halved\"}, {\"qty\": \"2 tbsp\", \"name\": \"capers\"}, {\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"3 oz\", \"name\": \"crumbled feta cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"crusty bread for serving\"}]", "instructions": "1. Heat olive oil in a large oven-safe skillet over medium-high heat. Add onion and peppers; cook 8 minutes until softened and beginning to char at edges. 2. Add garlic, harissa, caraway seeds, and cumin; cook 1 minute until fragrant. 3. Add crushed tomatoes; simmer 15 minutes until thickened. Stir in olives and capers; season with salt. 4. Make 6 wells in the sauce; crack an egg into each. Spoon sauce over egg whites. 5. Cover and cook on lowest heat 5-8 minutes until whites are just set and yolks are still runny. 6. Crumble feta on top; scatter parsley. Serve directly from pan with crusty bread.", "tags": "gluten-free, vegetarian, one-pan", "source": "Classic", "nutritionData": "{\"calories\": 320, \"protein\": 18.0, \"carbs\": 22.0, \"fat\": 19.0}"},
  {"name": "Fancy Huevos Rancheros", "category": "Breakfast for Dinner", "description": "Elevated huevos rancheros with homemade ranchero sauce, crispy tortillas, refried beans, and cotija cheese.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"corn tortillas\"}, {\"qty\": \"1 can\", \"name\": \"15 oz refried beans warmed\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1 can\", \"name\": \"14 oz fire-roasted diced tomatoes\"}, {\"qty\": \"1\", \"name\": \"chipotle pepper in adobo minced\"}, {\"qty\": \"1/2\", \"name\": \"onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"1/4 cup\", \"name\": \"cotija cheese crumbled\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1\", \"name\": \"lime cut into wedges\"}, {\"qty\": \"\", \"name\": \"hot sauce for serving\"}]", "instructions": "1. Make ranchero sauce: sauté onion in 1 tbsp oil 5 minutes; add garlic, cumin, paprika, chipotle, and tomatoes. Simmer 10 minutes; blend until smooth. 2. Warm tortillas one at a time in a brush-oiled skillet 15 seconds per side until puffed and fragrant. 3. Fry eggs in remaining oil to desired doneness; season with salt. 4. Spread refried beans on each tortilla; top with ranchero sauce and a fried egg. 5. Garnish with avocado, cotija, cilantro, and a squeeze of lime. Serve with hot sauce.", "tags": "gluten-free, vegetarian, Tex-Mex", "source": "https://www.loveandlemons.com/huevos-rancheros/", "nutritionData": "{\"calories\": 500, \"protein\": 21.0, \"carbs\": 54.0, \"fat\": 22.0}"},
  {"name": "Eggs Benedict", "category": "Breakfast for Dinner", "description": "Classic poached eggs on English muffins with Canadian bacon and blender hollandaise sauce.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"4\", \"name\": \"English muffins split and toasted\"}, {\"qty\": \"8 slices\", \"name\": \"Canadian bacon\"}, {\"qty\": \"3\", \"name\": \"egg yolks\"}, {\"qty\": \"3/4 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 1/2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"1 1/2 tbsp\", \"name\": \"water\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"white vinegar\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Make hollandaise: blend egg yolks, lemon juice, water, cayenne, and salt. With blender running, slowly stream in hot melted butter until thick and emulsified. Keep warm. 2. Warm Canadian bacon in a skillet 1-2 minutes per side. 3. Toast English muffins; keep warm in a 200°F oven. 4. Fill a large pot with 3 inches of water; add vinegar and bring to a bare simmer. 5. Crack eggs into individual cups; gently slide into water. Poach 2-3 minutes until whites are set and yolks are runny. Remove with slotted spoon. 6. Assemble: muffin half, Canadian bacon, poached egg, hollandaise. Garnish with chives.", "tags": "impressive, high-protein, brunch-worthy", "source": "Classic", "nutritionData": "{\"calories\": 580, \"protein\": 28.0, \"carbs\": 28.0, \"fat\": 40.0}"},
  {"name": "Eggs Florentine", "category": "Breakfast for Dinner", "description": "Poached eggs over wilted garlic spinach on toasted English muffins with silky hollandaise sauce.", "servings": 4, "prepTime": 20, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"4\", \"name\": \"English muffins split and toasted\"}, {\"qty\": \"10 oz\", \"name\": \"fresh baby spinach\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"small shallot minced\"}, {\"qty\": \"2\", \"name\": \"large egg yolks\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter melted for hollandaise\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"dash hot sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"white wine vinegar\"}, {\"qty\": \"\", \"name\": \"fresh chives for garnish\"}]", "instructions": "1. Make hollandaise: blend egg yolks with lemon juice and salt; with blender running slowly pour in hot butter until thick. Season with hot sauce; set aside. 2. Wilt spinach in 1 tbsp butter with shallot over medium heat 2 minutes until just wilted; press out liquid and season. 3. Toast English muffins in remaining butter until golden. 4. Poach eggs: simmer water with vinegar; slide eggs in and cook 3-4 minutes. Remove with slotted spoon. 5. Assemble: muffin half, spinach, poached egg, hollandaise. Garnish with chives.", "tags": "vegetarian, impressive, high-protein", "source": "https://smittenkitchen.com/2025/05/eggs-florentine/", "nutritionData": "{\"calories\": 540, \"protein\": 25.0, \"carbs\": 29.0, \"fat\": 37.0}"},
  {"name": "Chorizo and Potato Hash", "category": "Breakfast for Dinner", "description": "Crispy smashed potatoes tossed with spicy Spanish chorizo and fried eggs in a one-pan dinner.", "servings": 4, "prepTime": 15, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 1/2 lbs\", \"name\": \"baby Yukon gold potatoes\"}, {\"qty\": \"8 oz\", \"name\": \"Spanish or Mexican chorizo sliced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1/2\", \"name\": \"yellow onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"hot sauce for serving\"}]", "instructions": "1. Boil potatoes in salted water 12-15 minutes until fork-tender; drain. 2. Heat a large cast iron skillet over medium-high heat; cook chorizo until browned, 3-4 minutes. Remove to a plate. 3. Add olive oil to pan; add potatoes and smash each with a spatula. Cook undisturbed 4-5 minutes until crisp; flip and crisp the other side. 4. Add bell pepper, onion, and garlic; toss and cook 4 minutes until softened. Add chorizo back and toss with paprika. 5. Make 4 wells; crack eggs in each. Cover and cook 3-4 minutes until whites are set. 6. Scatter parsley; serve with hot sauce.", "tags": "gluten-free, high-protein, one-pan", "source": "Classic", "nutritionData": "{\"calories\": 540, \"protein\": 27.0, \"carbs\": 35.0, \"fat\": 31.0}"},
  {"name": "Sausage Gravy and Biscuits", "category": "Breakfast for Dinner", "description": "Fluffy homemade buttermilk biscuits smothered in rich, creamy pork sausage gravy for the ultimate comfort dinner.", "servings": 6, "prepTime": 20, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"cold unsalted butter cubed\"}, {\"qty\": \"3/4 cup\", \"name\": \"cold buttermilk\"}, {\"qty\": \"1 lb\", \"name\": \"ground breakfast sausage\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour for gravy\"}, {\"qty\": \"2 1/2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"half-and-half\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Make biscuits: whisk flour, baking powder, baking soda, sugar, and salt. Cut in cold butter until pea-sized. Add buttermilk and stir until just combined. 2. Pat dough 3/4-inch thick on floured surface; cut into rounds. Bake at 450°F 12-14 minutes until golden. 3. Brown sausage in a large skillet over medium heat, breaking into crumbles. Blot excess grease but leave 2 tbsp. 4. Sprinkle flour over sausage; stir and cook 2 minutes. Gradually whisk in milk and half-and-half. 5. Simmer 5-7 minutes until thickened; season with black pepper, red pepper flakes, and salt. 6. Split warm biscuits and smother generously with gravy.", "tags": "comfort food, Southern-inspired, high-protein", "source": "Classic", "nutritionData": "{\"calories\": 640, \"protein\": 24.0, \"carbs\": 52.0, \"fat\": 36.0}"},
  {"name": "Breakfast Strata", "category": "Breakfast for Dinner", "description": "Savory make-ahead bread casserole layered with bacon, spinach, and Parmesan baked until puffed and golden.", "servings": 8, "prepTime": 20, "cookTime": 55, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"sourdough bread cubed\"}, {\"qty\": \"8 slices\", \"name\": \"uncooked bacon\"}, {\"qty\": \"1/2 cup\", \"name\": \"chopped onion\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 cups\", \"name\": \"fresh spinach chopped\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"shredded Parmesan cheese\"}, {\"qty\": \"9\", \"name\": \"large eggs\"}, {\"qty\": \"2 cups\", \"name\": \"whole milk\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"ground mustard\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Arrange bread cubes in a greased 9x13-inch casserole dish. 2. Cook bacon until crisp; crumble over bread. Leave 1 tbsp drippings in pan. 3. Sauté onion in drippings 4 minutes; add garlic and spinach; cook until wilted. Spoon over bread and bacon. Sprinkle with Parmesan. 4. Whisk eggs, milk, salt, mustard, and pepper; pour evenly over casserole. 5. Cover and refrigerate 1 hour to overnight. 6. Preheat oven to 375°F; bake uncovered 20 minutes, then tent with foil and bake 30-35 minutes until puffed and set. Rest 5 minutes before serving.", "tags": "make-ahead, crowd-pleasing, high-protein", "source": "https://sallysbakingaddiction.com/spinach-bacon-breakfast-strata/", "nutritionData": "{\"calories\": 390, \"protein\": 24.0, \"carbs\": 28.0, \"fat\": 21.0}"},
  {"name": "Croque Madame", "category": "Breakfast for Dinner", "description": "Classic French bistro sandwich of ham and Gruyere in bechamel sauce topped with a fried egg.", "servings": 4, "prepTime": 15, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8 slices\", \"name\": \"thick-cut sandwich bread\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"\", \"name\": \"pinch of nutmeg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"8 oz\", \"name\": \"thinly sliced ham\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"shredded Gruyere cheese\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"salt and white pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Make bechamel: melt butter over medium heat; whisk in flour and cook 2 minutes. Gradually whisk in milk; cook stirring until thick, 4 minutes. Stir in nutmeg and mustard; season with salt. 2. Preheat broiler. Spread bechamel on all bread slices. Place 4 slices béchamel-side up on a baking sheet; top with ham and half the Gruyere. Cover with remaining bread bechamel-side up; top with more bechamel and remaining Gruyere. 3. Broil 4-5 minutes until cheese is bubbling and golden. 4. Fry eggs in olive oil to desired doneness. 5. Top each sandwich with a fried egg; garnish with parsley.", "tags": "French, comfort food, impressive", "source": "https://www.epicurious.com/recipes/food/views/croque-madame-237589", "nutritionData": "{\"calories\": 620, \"protein\": 38.0, \"carbs\": 38.0, \"fat\": 34.0}"},
  {"name": "Italian Sausage and Pepper Frittata", "category": "Breakfast for Dinner", "description": "Hearty oven-finished frittata packed with Italian sausage, roasted peppers, onions, and provolone.", "servings": 6, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"12 oz\", \"name\": \"Italian sausage casings removed\"}, {\"qty\": \"1\", \"name\": \"red bell pepper thinly sliced\"}, {\"qty\": \"1\", \"name\": \"yellow bell pepper thinly sliced\"}, {\"qty\": \"1\", \"name\": \"small onion thinly sliced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"shredded provolone cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil leaves torn\"}]", "instructions": "1. Preheat oven to 375°F. 2. Whisk eggs, milk, salt, and pepper in a bowl; stir in 3/4 cup provolone. 3. Cook sausage in an oven-safe 12-inch skillet over medium-high heat, breaking into crumbles, until browned, 5-6 minutes. Remove; pour off excess fat, leaving 1 tbsp. 4. Sauté peppers and onion in the same pan 5 minutes; add garlic and cook 1 minute. Return sausage to pan. 5. Pour egg mixture over sausage and vegetables; cook without stirring until edges start to set, 4-5 minutes. Sprinkle remaining provolone. 6. Transfer to oven; bake 18-22 minutes until puffed and set. Rest 5 minutes; slice into wedges.", "tags": "gluten-free, high-protein, one-pan", "source": "Classic", "nutritionData": "{\"calories\": 430, \"protein\": 30.0, \"carbs\": 6.0, \"fat\": 32.0}"},
  {"name": "Corned Beef Hash", "category": "Breakfast for Dinner", "description": "Crispy-edged cast iron hash of corned beef and Yukon gold potatoes topped with jammy eggs.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"cooked corned beef diced\"}, {\"qty\": \"1 1/2 lbs\", \"name\": \"Yukon gold potatoes diced\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh chives chopped\"}]", "instructions": "1. Boil diced potatoes in salted water 6-8 minutes until just tender; drain well. 2. Heat butter and oil in a large cast iron skillet over medium-high heat. Add onion; cook 4 minutes until softened. 3. Add potatoes in a single layer; cook undisturbed 5-6 minutes until a crispy crust forms on the bottom. 4. Add corned beef, garlic, Worcestershire, and paprika; stir and press down. Cook another 8-10 minutes, flipping occasionally, until deeply browned and crispy. Season with salt and pepper. 5. Make 4 wells; crack eggs in each. Cover and cook 3-4 minutes to desired doneness. 6. Top with chives and serve from the skillet.", "tags": "gluten-free, high-protein, one-pan", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 32.0, \"carbs\": 36.0, \"fat\": 27.0}"},
  {"name": "Sweet Potato Hash with Eggs", "category": "Breakfast for Dinner", "description": "Smoky sweet potato and red onion hash with crispy edges, finished with baked eggs and avocado.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large sweet potatoes peeled and diced small\"}, {\"qty\": \"1\", \"name\": \"red onion diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1\", \"name\": \"ripe avocado sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"\", \"name\": \"hot sauce for serving\"}]", "instructions": "1. Preheat oven to 425°F. 2. Toss sweet potatoes, red onion, bell pepper, and garlic with olive oil, paprika, cumin, salt, and pepper. Spread in a single layer on a large cast iron skillet or sheet pan. 3. Roast 20-22 minutes until tender and edges are caramelized, stirring once halfway. 4. Make 4 wells in the hash; crack an egg into each. Return to oven 5-7 minutes until egg whites are set. 5. Top with sliced avocado, fresh cilantro, and hot sauce. Serve immediately.", "tags": "gluten-free, vegetarian, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 380, \"protein\": 14.0, \"carbs\": 38.0, \"fat\": 20.0}"},
  {"name": "Migas", "category": "Breakfast for Dinner", "description": "Scrambled eggs folded with crispy fried tortilla strips, peppers, and Monterey Jack for a Tex-Mex dinner.", "servings": 4, "prepTime": 15, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"corn tortillas cut into strips\"}, {\"qty\": \"3 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1\", \"name\": \"jalapeno seeded and diced\"}, {\"qty\": \"1\", \"name\": \"small red bell pepper diced\"}, {\"qty\": \"1/2\", \"name\": \"small onion diced\"}, {\"qty\": \"1\", \"name\": \"medium Roma tomato diced\"}, {\"qty\": \"6\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3/4 cup\", \"name\": \"shredded Monterey Jack cheese\"}, {\"qty\": \"1\", \"name\": \"avocado sliced\"}, {\"qty\": \"\", \"name\": \"salsa and hot sauce for serving\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro chopped\"}]", "instructions": "1. Heat oil in a large nonstick skillet over medium heat; add tortilla strips and fry 4-5 minutes until crisp, turning occasionally. Remove to paper towels and season with salt. 2. In the same pan over medium heat, cook jalapeno, bell pepper, and onion 4 minutes until softened. Add tomato and cook 1 minute. 3. Season eggs with salt and pepper; reduce heat to medium-low. Add crispy tortillas back to pan; pour eggs over. Cook, gently folding, 2-3 minutes until just set. Remove from heat; fold in cheese. 4. Serve immediately topped with avocado, salsa, cilantro, and hot sauce.", "tags": "vegetarian, Tex-Mex, quick", "source": "https://smittenkitchen.com/2009/03/migas-with-tomato-chipotle-coulis/", "nutritionData": "{\"calories\": 450, \"protein\": 22.0, \"carbs\": 28.0, \"fat\": 28.0}"},
  {"name": "Savory Crepes with Ham and Gruyere", "category": "Breakfast for Dinner", "description": "Delicate French crepes folded around sliced ham and melted Gruyere with a light Dijon bechamel.", "servings": 4, "prepTime": 15, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 1/4 cups\", \"name\": \"whole milk\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted plus more for pan\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"8\", \"name\": \"thin slices ham\"}, {\"qty\": \"1 1/2 cups\", \"name\": \"shredded Gruyere cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter for bechamel\"}, {\"qty\": \"1 tbsp\", \"name\": \"flour for bechamel\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk for bechamel\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"\", \"name\": \"pinch of nutmeg\"}, {\"qty\": \"\", \"name\": \"fresh chives for garnish\"}]", "instructions": "1. Make crepe batter: blend flour, eggs, milk, melted butter, and salt until smooth. Rest 30 minutes. 2. Cook crepes in a lightly buttered 8-inch skillet over medium heat, 1-2 minutes per side until just golden. Stack on a plate. 3. Make bechamel: melt butter, whisk in flour, cook 1 minute; gradually add milk whisking constantly until smooth and thick. Stir in mustard and nutmeg; season. 4. Lay a crepe flat; spread with a thin layer of bechamel, add a slice of ham, and sprinkle Gruyere. Fold into quarters. 5. Arrange filled crepes in a buttered baking dish; top with remaining bechamel and Gruyere. Broil 4-5 minutes until golden. 6. Garnish with chives and serve.", "tags": "French, impressive, comfort food", "source": "Classic", "nutritionData": "{\"calories\": 560, \"protein\": 32.0, \"carbs\": 32.0, \"fat\": 32.0}"},
  {"name": "Cheese Blintzes", "category": "Breakfast for Dinner", "description": "Pan-fried crepe rolls stuffed with sweetened ricotta and cream cheese, served with sour cream and jam.", "servings": 6, "prepTime": 30, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted divided\"}, {\"qty\": \"1 tbsp\", \"name\": \"granulated sugar\"}, {\"qty\": \"\", \"name\": \"pinch of salt\"}, {\"qty\": \"2 cups\", \"name\": \"ricotta cheese\"}, {\"qty\": \"6 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"3 tbsp\", \"name\": \"granulated sugar for filling\"}, {\"qty\": \"1\", \"name\": \"egg yolk\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh lemon zest\"}, {\"qty\": \"\", \"name\": \"sour cream and fruit jam for serving\"}]", "instructions": "1. Blend milk, flour, eggs, 2 tbsp melted butter, sugar, and salt until smooth; rest 30 minutes or refrigerate overnight. 2. Cook thin crepes in a buttered 8-inch pan over medium-high heat, one side only, 1 minute each. Stack cooked-side up. 3. Make filling: beat ricotta, cream cheese, sugar, egg yolk, vanilla, and lemon zest until smooth. 4. Place 3 tbsp filling near bottom edge of each crepe (cooked-side up); fold bottom up, fold sides in, and roll up. 5. Heat remaining butter over medium heat; fry blintzes seam-side down in batches 2-3 minutes per side until golden. 6. Serve hot with sour cream and fruit jam.", "tags": "vegetarian, European, comfort food", "source": "https://smittenkitchen.com/2014/01/cheese-blintz/", "nutritionData": "{\"calories\": 490, \"protein\": 18.0, \"carbs\": 34.0, \"fat\": 31.0}"},
  {"name": "Huevos Divorciados", "category": "Breakfast for Dinner", "description": "Two fried eggs on crispy tortillas each sauced with a different salsa — red chile and green tomatillo.", "servings": 4, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"corn tortillas\"}, {\"qty\": \"8\", \"name\": \"large eggs\"}, {\"qty\": \"3\", \"name\": \"dried guajillo chiles stemmed and seeded\"}, {\"qty\": \"1 can\", \"name\": \"14 oz whole tomatoes\"}, {\"qty\": \"6\", \"name\": \"medium tomatillos husked\"}, {\"qty\": \"2\", \"name\": \"serrano peppers\"}, {\"qty\": \"1\", \"name\": \"small white onion halved\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1\", \"name\": \"lime juiced\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil plus more for tortillas\"}, {\"qty\": \"1 cup\", \"name\": \"refried beans warmed\"}, {\"qty\": \"3/4 cup\", \"name\": \"crumbled cotija cheese\"}, {\"qty\": \"\", \"name\": \"salt to taste\"}]", "instructions": "1. Make red salsa: toast guajillo chiles in dry pan 30 seconds; soak in hot water 15 minutes. Blend with tomatoes, half the onion, and 2 garlic cloves; simmer in 1 tsp oil 8 minutes. Season. 2. Make green salsa: broil tomatillos, serranos, remaining onion, and garlic 8-10 minutes until charred. Blend with cilantro and lime juice; season. 3. Heat 1/4-inch oil in a skillet; fry tortillas 30 seconds per side until crispy. Drain. 4. Fry eggs in oil to desired doneness. 5. Spread each tortilla with refried beans; place one egg on each. Pour red salsa over 4 eggs and green salsa over the other 4. 6. Top with cotija; serve immediately.", "tags": "gluten-free, vegetarian, Mexican", "source": "Classic", "nutritionData": "{\"calories\": 570, \"protein\": 28.0, \"carbs\": 48.0, \"fat\": 29.0}"},
  {"name": "Classic Roast Turkey", "category": "Holiday Feasts", "description": "A perfectly golden whole roasted turkey with herb butter under the skin and pan drippings for gravy.", "servings": 12, "prepTime": 30, "cookTime": 180, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole turkey (14-16 lb)\"}, {\"qty\": \"1/2 cup\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh rosemary chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh sage chopped\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"large onion quartered\"}, {\"qty\": \"1\", \"name\": \"lemon quartered\"}, {\"qty\": \"4 cups\", \"name\": \"chicken stock\"}]", "instructions": "1. Remove turkey from refrigerator 1 hour before roasting and pat dry. 2. Preheat oven to 325°F. Mix butter with garlic, thyme, rosemary, sage, salt and pepper. 3. Loosen skin over breast and thighs; rub herb butter underneath and all over outside. 4. Stuff cavity with onion and lemon. Truss legs with kitchen twine. 5. Place breast-side up on a rack in a roasting pan. Pour stock into pan bottom. 6. Roast 13-15 minutes per pound, basting every 45 minutes, until thigh registers 165°F, about 3 hours. 7. Tent loosely with foil and rest 30 minutes before carving.", "tags": "thanksgiving, holiday-roast, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 420, \"protein\": 52.0, \"carbs\": 2.0, \"fat\": 22.0}"},
  {"name": "Spatchcocked Thanksgiving Turkey", "category": "Holiday Feasts", "description": "Butterflied turkey roasted at high heat for ultra-crispy skin and juicy meat in just 80 minutes.", "servings": 10, "prepTime": 30, "cookTime": 80, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole turkey (12-14 lb) backbone removed\"}, {\"qty\": \"2 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"large onions roughly chopped\"}, {\"qty\": \"3\", \"name\": \"large carrots roughly chopped\"}, {\"qty\": \"4\", \"name\": \"stalks celery roughly chopped\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"6 cups\", \"name\": \"chicken or turkey stock\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}]", "instructions": "1. Using kitchen shears, cut along both sides of backbone and remove. Flip turkey breast-side up and press firmly on breastbone to flatten. 2. Preheat oven to 450°F. Line a rimmed baking sheet with foil; scatter two-thirds of onions, carrots, celery and thyme on bottom. Place a wire rack on top. 3. Rub turkey all over and under skin with oil; season liberally with salt and pepper. Tuck wing tips underneath. Place turkey on rack. 4. Roast until breast registers 150°F and thighs 165°F, about 80 minutes. 5. While turkey roasts, make gravy: simmer backbone with remaining vegetables and stock 45 minutes; strain. Make roux with butter and flour, whisk in strained stock; simmer until thickened. 6. Rest turkey 20 minutes, then carve and serve with gravy.", "tags": "thanksgiving, spatchcock, crispy-skin", "source": "https://www.seriouseats.com/butterfiled-roast-turkey-with-gravy-recipe", "nutritionData": "{\"calories\": 410, \"protein\": 50.0, \"carbs\": 3.0, \"fat\": 21.0}"},
  {"name": "Turkey Gravy from Drippings", "category": "Holiday Feasts", "description": "Rich and silky turkey gravy made from pan drippings and a fortified broth with neck and giblets.", "servings": 8, "prepTime": 10, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"\", \"name\": \"Turkey neck and giblets reserved\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1\", \"name\": \"medium onion roughly chopped\"}, {\"qty\": \"2\", \"name\": \"carrots roughly chopped\"}, {\"qty\": \"2\", \"name\": \"stalks celery roughly chopped\"}, {\"qty\": \"4 cups\", \"name\": \"chicken stock\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}]", "instructions": "1. Chop turkey neck and giblets into 1-inch pieces. Heat oil in a saucepan over medium-high heat and brown turkey parts, 5-7 minutes. 2. Add onion, carrots and celery; cook 5 minutes until softened. Add stock, soy sauce, thyme and bay leaves; bring to a boil then simmer 45 minutes. 3. Strain broth through a fine-mesh strainer; discard solids. Skim off fat. 4. In a separate saucepan, melt butter over medium heat. Add flour and whisk constantly until golden brown, about 3 minutes. 5. Slowly whisk in strained broth in a thin stream until fully incorporated. Bring to a boil then simmer until thickened, about 15 minutes. 6. Stir in any pan drippings from roasted turkey; season with salt and pepper and keep warm until serving.", "tags": "thanksgiving, sauce, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 95, \"protein\": 3.0, \"carbs\": 7.0, \"fat\": 7.0}"},
  {"name": "Classic Herb Stuffing", "category": "Holiday Feasts", "description": "Traditional bread stuffing with celery, onion and fresh sage for the ultimate Thanksgiving side dish.", "servings": 10, "prepTime": 20, "cookTime": 65, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"day-old white bread cut into 1-inch cubes\"}, {\"qty\": \"8 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"4\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh sage chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"2 cups\", \"name\": \"chicken stock\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat oven to 275°F. Spread bread cubes on two rimmed baking sheets; bake until dried, about 50 minutes. Let cool. Increase oven to 350°F. 2. Melt butter in a large Dutch oven over medium-high heat. Add onion, celery and garlic; cook until softened, about 10 minutes. Add sage and thyme; cook 1 minute more. 3. Whisk together stock, eggs and parsley. Combine with bread cubes and sautéed vegetables; toss until evenly mixed. 4. Transfer to a buttered 9x13-inch baking dish. Cover tightly with foil and bake until internal temperature reaches 150°F, about 45 minutes. 5. Remove foil and continue baking until top is golden and crisp, 15-20 minutes. Let cool 5 minutes and serve.", "tags": "thanksgiving, stuffing, make-ahead", "source": "https://www.seriouseats.com/classic-sage-sausage-stuffing-or-dressing", "nutritionData": "{\"calories\": 290, \"protein\": 9.0, \"carbs\": 38.0, \"fat\": 12.0}"},
  {"name": "Cranberry Orange Sauce", "category": "Holiday Feasts", "description": "Bright and tangy homemade cranberry sauce with fresh orange juice and zest.", "servings": 8, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"fresh cranberries rinsed\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar packed\"}, {\"qty\": \"1/2 cup\", \"name\": \"fresh orange juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"orange zest\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"1/4 tsp\", \"name\": \"vanilla extract\"}]", "instructions": "1. Combine sugars, orange juice and water in a medium saucepan over medium heat. Stir until sugar dissolves. 2. Add cranberries and cinnamon stick. Bring to a boil then reduce heat to a simmer. 3. Cook stirring occasionally until berries burst and sauce thickens, about 12-15 minutes. Mash any remaining whole berries against side of pan. 4. Remove cinnamon stick. Stir in orange zest and vanilla extract. 5. Transfer to a bowl and let cool to room temperature. Refrigerate at least 2 hours before serving; sauce thickens as it chills.", "tags": "thanksgiving, make-ahead, vegetarian", "source": "https://sallysbakingaddiction.com/cranberry-sauce/", "nutritionData": "{\"calories\": 115, \"protein\": 0.0, \"carbs\": 29.0, \"fat\": 0.0}"},
  {"name": "Sweet Potato Casserole with Marshmallows", "category": "Holiday Feasts", "description": "Creamy mashed sweet potatoes topped with toasted marshmallows and a buttery pecan streusel.", "servings": 10, "prepTime": 20, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"sweet potatoes peeled and cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"brown sugar packed\"}, {\"qty\": \"1/3 cup\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"mini marshmallows\"}, {\"qty\": \"1 cup\", \"name\": \"pecans chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3 tbsp\", \"name\": \"cold butter cubed\"}]", "instructions": "1. Preheat oven to 375°F. Boil sweet potatoes in salted water until fork-tender, about 20 minutes. Drain. 2. Mash sweet potatoes; stir in brown sugar, melted butter, milk, eggs, vanilla, cinnamon and salt until smooth. Spread into a greased 9x13-inch baking dish. 3. Combine chopped pecans, flour and cold butter; work together with fingers until crumbly. Sprinkle pecan streusel over sweet potatoes. 4. Bake 25 minutes until set and topping is lightly golden. 5. Remove from oven; top with mini marshmallows. Return to oven and bake 5-8 minutes more until marshmallows are puffed and golden. 6. Let cool 5 minutes before serving.", "tags": "thanksgiving, vegetarian, sweet", "source": "https://www.seriouseats.com/sweet-potato-casserole", "nutritionData": "{\"calories\": 340, \"protein\": 4.0, \"carbs\": 55.0, \"fat\": 13.0}"},
  {"name": "Fancy Green Bean Casserole", "category": "Holiday Feasts", "description": "Elevated homemade green bean casserole with fresh mushroom cream sauce and crispy fried shallots.", "servings": 8, "prepTime": 30, "cookTime": 40, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"fresh green beans trimmed\"}, {\"qty\": \"1 lb\", \"name\": \"cremini mushrooms roughly chopped\"}, {\"qty\": \"8 oz\", \"name\": \"shallots thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"chicken stock\"}, {\"qty\": \"1 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}]", "instructions": "1. Fry sliced shallots in oil over medium heat, stirring, until deep golden brown. Remove with slotted spoon to paper towels; season with salt. Reserve 2 tbsp shallot oil. 2. Blanch green beans in boiling salted water 3-4 minutes; transfer immediately to ice water. Drain and set aside. 3. Heat shallot oil and 2 tbsp butter in a large oven-safe skillet over high heat. Add mushrooms; cook until dry and caramelized, about 10 minutes. Reduce heat; add garlic and flour; cook 2 minutes. 4. Whisk in stock, cream, soy sauce and lemon juice. Simmer until thickened, about 5 minutes. Season with salt and pepper. 5. Preheat oven to 375°F. Fold blanched green beans and half the fried shallots into mushroom sauce. Bake 20-25 minutes until bubbling. 6. Top with remaining fried shallots and serve immediately.", "tags": "thanksgiving, vegetarian, elevated", "source": "https://www.seriouseats.com/green-bean-casserole", "nutritionData": "{\"calories\": 210, \"protein\": 5.0, \"carbs\": 14.0, \"fat\": 16.0}"},
  {"name": "Pecan Pie", "category": "Holiday Feasts", "description": "A classic Southern pecan pie with a gooey brown sugar filling and buttery pastry crust.", "servings": 8, "prepTime": 20, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"unbaked 9-inch pie shell\"}, {\"qty\": \"3\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"light corn syrup\"}, {\"qty\": \"3/4 cup\", \"name\": \"brown sugar packed\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 cups\", \"name\": \"pecan halves\"}, {\"qty\": \"1 tbsp\", \"name\": \"rye whiskey optional\"}]", "instructions": "1. Preheat oven to 375°F with rack in lowest position. 2. Whisk together eggs, corn syrup, brown sugar, melted butter, vanilla, salt and rye whiskey if using in a large bowl until smooth. 3. Stir in pecan halves. Pour filling into unbaked pie shell. 4. Bake on lowest rack until filling is set around edges but center barely jiggles, 40-45 minutes; tent with foil if crust browns too quickly. 5. Transfer to a wire rack and cool completely, at least 2 hours, before slicing. Serve at room temperature or slightly warmed with whipped cream.", "tags": "thanksgiving, dessert, southern", "source": "Classic", "nutritionData": "{\"calories\": 510, \"protein\": 6.0, \"carbs\": 63.0, \"fat\": 28.0}"},
  {"name": "Classic Pumpkin Pie", "category": "Holiday Feasts", "description": "Silky spiced pumpkin pie in a flaky crust — the definitive Thanksgiving dessert.", "servings": 8, "prepTime": 20, "cookTime": 65, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"unbaked 9-inch deep-dish pie shell\"}, {\"qty\": \"1 can\", \"name\": \"(15 oz) pumpkin puree\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 can\", \"name\": \"(12 oz) evaporated milk\"}, {\"qty\": \"\", \"name\": \"whipped cream for serving\"}]", "instructions": "1. Preheat oven to 425°F. 2. Beat eggs and pumpkin puree together in a large bowl. Combine sugar, cinnamon, ginger, cloves, nutmeg and salt; stir into pumpkin mixture. 3. Gradually stir in evaporated milk until smooth. Pour into unbaked pie shell; fill only 3/4 full. 4. Bake at 425°F for 15 minutes. Reduce heat to 350°F and bake until center is nearly set and a knife inserted near center comes out mostly clean, 40-50 minutes more. 5. Cool completely on a wire rack at least 2 hours. Refrigerate until serving. Serve with whipped cream.", "tags": "thanksgiving, dessert, fall", "source": "https://sallysbakingaddiction.com/the-great-pumpkin-pie-recipe/", "nutritionData": "{\"calories\": 320, \"protein\": 7.0, \"carbs\": 45.0, \"fat\": 13.0}"},
  {"name": "Prime Rib Roast", "category": "Holiday Feasts", "description": "A majestic slow-roasted standing rib roast with a golden herb crust — the Christmas dinner centerpiece.", "servings": 8, "prepTime": 15, "cookTime": 240, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"bone-in prime rib roast (5-6 lb)\"}, {\"qty\": \"2 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"head garlic halved crosswise\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"\", \"name\": \"horseradish cream for serving\"}]", "instructions": "1. Season roast generously all over with salt; refrigerate uncovered on a rack overnight. 2. Remove from refrigerator 2 hours before cooking. Preheat oven to 250°F. Mix pepper, garlic powder, rosemary, thyme and olive oil; rub all over roast. 3. Place roast bone-side down on a rack in a roasting pan with halved garlic head and thyme. Roast until center registers 120°F for rare to medium-rare, 3-4 hours. 4. Remove from oven; tent loosely with foil. Rest at least 30 minutes (up to 1.5 hours). 5. Increase oven to 500°F. Uncover roast and sear 5-10 minutes until deeply browned and crusted. 6. Carve along ribs and slice; serve immediately with horseradish cream.", "tags": "christmas, prime-rib, holiday-roast", "source": "https://www.seriouseats.com/the-best-prime-rib-roast-recipe", "nutritionData": "{\"calories\": 580, \"protein\": 40.0, \"carbs\": 1.0, \"fat\": 46.0}"},
  {"name": "Beef Wellington", "category": "Holiday Feasts", "description": "Tender beef tenderloin wrapped in mushroom duxelles and prosciutto in golden puff pastry.", "servings": 6, "prepTime": 60, "cookTime": 45, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lb\", \"name\": \"center-cut beef tenderloin\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"6 oz\", \"name\": \"prosciutto di Parma sliced\"}, {\"qty\": \"1 lb\", \"name\": \"cremini mushrooms finely chopped\"}, {\"qty\": \"4\", \"name\": \"shallots finely minced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"dry sherry\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh thyme leaves\"}, {\"qty\": \"2 sheets\", \"name\": \"puff pastry thawed\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}]", "instructions": "1. Season tenderloin with salt and pepper; sear in an oiled hot skillet on all sides until browned, 2 minutes per side. Brush all over with Dijon mustard; chill 20 minutes. 2. Cook mushrooms, shallots and garlic in butter over medium heat adding sherry gradually until completely dry and caramelized, 30-40 minutes. Stir in thyme; cool completely. 3. Lay overlapping slices of prosciutto on plastic wrap; spread mushroom duxelles evenly. Place tenderloin at edge and roll tightly into a log; refrigerate 30 minutes. 4. Roll out puff pastry; unwrap tenderloin roll and place on pastry. Wrap tightly sealing seam with egg wash; refrigerate 20 minutes. 5. Preheat oven to 425°F. Brush pastry with egg wash; score decoratively. Bake until pastry is deep golden and internal temperature is 125°F, 25-30 minutes. 6. Rest 10 minutes before slicing into 1-inch portions and serving immediately.", "tags": "christmas, elegant, special-occasion", "source": "https://www.foodnetwork.com/recipes/tyler-florence/the-ultimate-beef-wellington-recipe2-1952280", "nutritionData": "{\"calories\": 640, \"protein\": 38.0, \"carbs\": 30.0, \"fat\": 40.0}"},
  {"name": "Honey-Glazed Spiral Ham", "category": "Holiday Feasts", "description": "A showstopping holiday ham lacquered with a sticky honey, brown sugar and mustard glaze.", "servings": 12, "prepTime": 15, "cookTime": 100, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"spiral-cut bone-in ham (8-10 lb)\"}, {\"qty\": \"1/2 cup\", \"name\": \"honey\"}, {\"qty\": \"1/2 cup\", \"name\": \"brown sugar packed\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/4 cup\", \"name\": \"pineapple juice\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}]", "instructions": "1. Preheat oven to 325°F. Line a roasting pan with foil; place ham cut-side down in pan. 2. Make glaze: melt butter in a saucepan over medium heat; whisk in honey, brown sugar, mustard, pineapple juice, garlic powder and paprika. Simmer 5-7 minutes until slightly thickened. 3. Brush one-third of glaze over ham. Cover pan tightly with foil and bake for 1.5 hours. 4. Uncover; increase oven to 425°F. Brush with half the remaining glaze; bake 15 minutes. Brush with remaining glaze; bake 10-15 minutes more until caramelized and sticky. 5. Rest 10 minutes before slicing and serving with pan juices.", "tags": "christmas, easter, crowd-pleaser", "source": "https://grandbaby-cakes.com/honey-glazed-ham/", "nutritionData": "{\"calories\": 360, \"protein\": 32.0, \"carbs\": 22.0, \"fat\": 15.0}"},
  {"name": "Yorkshire Pudding", "category": "Holiday Feasts", "description": "Dramatic sky-high popovers made from a rested egg batter cooked in sizzling hot beef drippings.", "servings": 6, "prepTime": 5, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2 tbsp\", \"name\": \"water\"}, {\"qty\": \"6 tbsp\", \"name\": \"beef dripping or lard\"}]", "instructions": "1. Combine eggs, flour, milk, water and salt in a bowl; whisk until completely smooth. Transfer to an airtight container and refrigerate overnight or up to 3 days. 2. Remove batter from refrigerator while preheating oven to 450°F. 3. Divide beef dripping evenly among a 12-cup muffin tin or six individual popover molds. Place in oven until fat is smoking hot, about 10 minutes. 4. Working quickly, divide batter evenly among cups filling each about half full. Immediately return to oven. 5. Bake without opening the oven until puddings have risen, turned deep brown all over and sound hollow when tapped, about 15-18 minutes. 6. Serve immediately alongside prime rib roast.", "tags": "christmas, british, side-dish", "source": "https://www.seriouseats.com/yorkshire-pudding-recipe", "nutritionData": "{\"calories\": 195, \"protein\": 7.0, \"carbs\": 18.0, \"fat\": 11.0}"},
  {"name": "Sugar Cookies with Royal Icing", "category": "Holiday Feasts", "description": "Classic buttery sugar cookies decorated with smooth royal icing in festive holiday designs.", "servings": 36, "prepTime": 30, "cookTime": 12, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"whole milk\"}, {\"qty\": \"3 cups\", \"name\": \"powdered sugar sifted\"}, {\"qty\": \"2\", \"name\": \"large egg whites\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cream of tartar\"}, {\"qty\": \"\", \"name\": \"food coloring as desired\"}]", "instructions": "1. Whisk flour, baking powder and salt. Beat butter and sugar until fluffy; add egg, vanilla and milk. Stir in flour mixture until just combined. 2. Divide dough in half; flatten into discs. Wrap and refrigerate 1-2 hours until firm. 3. Preheat oven to 350°F. Roll dough to 1/4-inch thickness; cut into desired shapes. Chill cut shapes on baking sheets for 15 minutes. 4. Bake until edges are set and bottom is just barely golden, 10-12 minutes. Cool completely on a wire rack. 5. Make royal icing: beat egg whites and cream of tartar to soft peaks; gradually add powdered sugar until thick and glossy. Thin with water 1 tsp at a time for flooding consistency. Divide and color as desired. 6. Pipe outlines, flood with thinned icing and let set 1-2 hours before stacking.", "tags": "christmas, cookies, decorating", "source": "https://www.seriouseats.com/perfect-sugar-cookies", "nutritionData": "{\"calories\": 120, \"protein\": 1.0, \"carbs\": 20.0, \"fat\": 4.0}"},
  {"name": "Mulled Wine", "category": "Holiday Feasts", "description": "A warming pot of red wine mulled with citrus, cinnamon, cloves and star anise for Christmas parties.", "servings": 8, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"bottle (750 ml) dry red wine\"}, {\"qty\": \"1\", \"name\": \"orange sliced into rounds\"}, {\"qty\": \"3\", \"name\": \"cinnamon sticks\"}, {\"qty\": \"6\", \"name\": \"whole cloves\"}, {\"qty\": \"3\", \"name\": \"star anise pods\"}, {\"qty\": \"1/2 cup\", \"name\": \"brandy\"}, {\"qty\": \"1/4 cup\", \"name\": \"honey or to taste\"}, {\"qty\": \"2\", \"name\": \"cardamom pods lightly crushed\"}]", "instructions": "1. Combine wine, orange slices, cinnamon sticks, cloves, star anise, cardamom and brandy in a medium saucepan over medium heat. 2. Bring to a gentle simmer stirring occasionally (do not boil or you will burn off the alcohol). 3. Reduce heat to medium-low; cook 10 minutes until fragrant and flavors have melded. 4. Stir in honey to taste; add more for a sweeter wine. 5. Ladle into mugs through a fine-mesh strainer to catch spices. Garnish with fresh orange slices and a cinnamon stick.", "tags": "christmas, drinks, warm", "source": "https://www.delish.com/cooking/recipe-ideas/a23364385/mulled-wine-recipe/", "nutritionData": "{\"calories\": 170, \"protein\": 0.0, \"carbs\": 18.0, \"fat\": 0.0}"},
  {"name": "Easter Roast Leg of Lamb", "category": "Holiday Feasts", "description": "Garlic and rosemary studded leg of lamb roasted to a blushing pink medium-rare for Easter Sunday.", "servings": 8, "prepTime": 20, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"bone-in leg of lamb (5-6 lb)\"}, {\"qty\": \"6 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh rosemary leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/4 cup\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh thyme\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"coarse kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 lb\", \"name\": \"baby potatoes\"}, {\"qty\": \"1\", \"name\": \"lemon halved\"}]", "instructions": "1. Using a sharp knife, make small incisions all over the lamb. Insert a slice of garlic and a small sprig of rosemary into each slit. 2. Mix mustard, olive oil, thyme, salt and pepper. Rub all over the lamb. Let marinate at room temperature 1 hour or refrigerate overnight. 3. Preheat oven to 350°F. Place baby potatoes in a large roasting pan; drizzle with olive oil and season with salt and pepper. Set lamb on top of potatoes. 4. Squeeze lemon over lamb. Roast until thickest part registers 135°F for medium about 1.5 hours. 5. Rest lamb on a carving board 20 minutes. Carve and serve over potatoes with pan juices.", "tags": "easter, spring, lamb", "source": "https://tatyanaseverydayfood.com/roasted-leg-of-lamb/", "nutritionData": "{\"calories\": 430, \"protein\": 40.0, \"carbs\": 12.0, \"fat\": 24.0}"},
  {"name": "Easter Deviled Eggs", "category": "Holiday Feasts", "description": "Classic deviled eggs with a creamy mustard filling piped high and dusted with smoked paprika.", "servings": 12, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12\", \"name\": \"large eggs\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"1.5 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"white wine vinegar\"}, {\"qty\": \"1/4 tsp\", \"name\": \"hot sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"smoked paprika for garnish\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh chives chopped\"}]", "instructions": "1. Place eggs in a steamer basket over 1 inch of boiling water. Cover and steam 12 minutes. Transfer immediately to an ice bath; cool 15 minutes then peel. 2. Halve eggs lengthwise; pop yolks into a food processor. Set aside 24 of the best-looking white halves. 3. Add mayonnaise, mustard, vinegar and hot sauce to yolks; process until smooth. With machine running, drizzle in olive oil. Season with salt and pepper. 4. Transfer filling to a zip-lock bag; snip corner. Pipe filling generously into egg white halves. 5. Garnish with a dusting of smoked paprika, a crack of black pepper and fresh chives. Refrigerate until serving.", "tags": "easter, appetizer, make-ahead", "source": "https://www.seriouseats.com/deviled-eggs-with-olive-oil-recipe", "nutritionData": "{\"calories\": 105, \"protein\": 7.0, \"carbs\": 1.0, \"fat\": 8.0}"},
  {"name": "Hot Cross Buns", "category": "Holiday Feasts", "description": "Lightly spiced enriched yeast buns studded with raisins and currants and marked with iced crosses.", "servings": 14, "prepTime": 30, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2.25 tsp\", \"name\": \"instant yeast\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground allspice\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"warm whole milk\"}, {\"qty\": \"3\", \"name\": \"large eggs (one separated)\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1/2 cup\", \"name\": \"raisins\"}, {\"qty\": \"1/4 cup\", \"name\": \"currants\"}, {\"qty\": \"1 cup\", \"name\": \"powdered sugar\"}, {\"qty\": \"2 tbsp\", \"name\": \"milk for icing\"}]", "instructions": "1. Mix flour, sugar, yeast, cinnamon, allspice, nutmeg and salt. Add warm milk, 2 whole eggs plus 1 yolk (reserve the white) and butter; knead with a mixer 8-10 minutes until dough is soft and elastic. 2. Mix in raisins and currants. Cover and let rise 1 hour until puffy. 3. Grease a 9x13 pan. Divide dough into 14 equal pieces; roll into balls and arrange in pan touching. Cover and rise 1 hour until puffed together. Preheat oven to 375°F. 4. Whisk reserved egg white with 1 tbsp milk; brush over buns. Bake 20 minutes until golden brown. Cool completely on a rack. 5. Mix powdered sugar with 2 tbsp milk until thick. Pipe or drizzle a cross on each bun.", "tags": "easter, baking, british", "source": "https://www.kingarthurbaking.com/recipes/easy-hot-cross-buns-recipe", "nutritionData": "{\"calories\": 220, \"protein\": 6.0, \"carbs\": 38.0, \"fat\": 5.0}"},
  {"name": "Easter Carrot Cake", "category": "Holiday Feasts", "description": "A moist spiced carrot cake with toasted walnuts and a tangy cream cheese frosting.", "servings": 12, "prepTime": 30, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2.5 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground ginger\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1.5 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"1 cup\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"3 cups\", \"name\": \"grated carrots\"}, {\"qty\": \"1 cup\", \"name\": \"walnuts toasted and chopped\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"3 cups\", \"name\": \"powdered sugar\"}, {\"qty\": \"1 stick\", \"name\": \"unsalted butter softened\"}]", "instructions": "1. Preheat oven to 350°F. Grease and flour two 9-inch round cake pans. Whisk flour, baking powder, baking soda, spices and salt in a bowl. 2. Whisk eggs and sugar vigorously until pale; whisk in oil and vanilla. Fold in flour mixture until just combined. Fold in grated carrots and walnuts. 3. Divide batter evenly between prepared pans. Bake 30-35 minutes until a toothpick inserted in center comes out clean. Cool in pans 10 minutes; turn out and cool completely. 4. Make frosting: beat cream cheese and butter together until smooth. Gradually add powdered sugar; beat until fluffy and smooth. 5. Place one cake layer on a plate; spread with one-third of frosting. Top with second layer; frost top and sides. Refrigerate 30 minutes to set before slicing.", "tags": "easter, dessert, baking", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 6.0, \"carbs\": 66.0, \"fat\": 27.0}"},
  {"name": "Hoppin John Black-Eyed Peas", "category": "Holiday Feasts", "description": "Southern New Year's black-eyed peas braised with a ham hock over white rice for good luck.", "servings": 8, "prepTime": 15, "cookTime": 75, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried black-eyed peas soaked overnight and rinsed\"}, {\"qty\": \"1\", \"name\": \"smoked ham hock\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"5 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper to taste\"}, {\"qty\": \"\", \"name\": \"white or brown rice for serving\"}, {\"qty\": \"4\", \"name\": \"green onions sliced\"}]", "instructions": "1. Heat butter in a large pot or Dutch oven over medium-high heat. Add onion, bell pepper, celery and garlic; cook 4-5 minutes until softened. 2. Add drained black-eyed peas, ham hock, chicken broth, cayenne, salt and pepper. Bring to a boil then reduce heat to a simmer. 3. Cover and cook 45-60 minutes until peas are creamy and tender, adding more broth if too thick. 4. Stir in apple cider vinegar; taste and adjust seasoning. Remove ham hock; pull off any meat and return to pot. 5. Serve over cooked white rice ladling plenty of cooking liquid over the top. Garnish with sliced green onions.", "tags": "new-year, southern, good-luck", "source": "https://www.thepioneerwoman.com/food-cooking/recipes/a10902/hoppin-john/", "nutritionData": "{\"calories\": 380, \"protein\": 22.0, \"carbs\": 55.0, \"fat\": 7.0}"},
  {"name": "Champagne Risotto", "category": "Holiday Feasts", "description": "Elegant creamy risotto made with Champagne and finished with Parmesan for New Year's Eve.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"arborio rice\"}, {\"qty\": \"2 cups\", \"name\": \"Champagne or dry sparkling wine\"}, {\"qty\": \"4 cups\", \"name\": \"warm chicken or vegetable broth\"}, {\"qty\": \"3\", \"name\": \"shallots finely diced\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmigiano-Reggiano\"}, {\"qty\": \"1/4 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"\", \"name\": \"kosher salt and white pepper to taste\"}, {\"qty\": \"\", \"name\": \"fresh chives for garnish\"}]", "instructions": "1. Warm broth in a small saucepan; keep at a bare simmer. Melt 2 tbsp butter in a wide heavy saucepan over medium heat. Sauté shallots until softened, 2-3 minutes; do not brown. 2. Add rice; stir to coat and toast for 2 minutes until edges turn translucent. 3. Add 1 cup Champagne; let bubble and evaporate stirring constantly. Add remaining Champagne; let evaporate again. 4. Add broth one ladleful at a time stirring and allowing each addition to absorb before adding more, about 18-20 minutes total until rice is al dente. 5. Remove from heat; stir in remaining 2 tbsp butter, heavy cream and Parmesan vigorously until creamy and saucy. Season with salt and white pepper. 6. Serve immediately in warm bowls; garnish with chives.", "tags": "new-year, elegant, vegetarian", "source": "https://memoriediangelina.com/2017/12/29/champagne-risotto/", "nutritionData": "{\"calories\": 450, \"protein\": 12.0, \"carbs\": 58.0, \"fat\": 17.0}"},
  {"name": "4th of July Baby Back Ribs", "category": "Holiday Feasts", "description": "Slow-cooked picnic-style baby back ribs with a smoky dry rub and sticky BBQ glaze.", "servings": 6, "prepTime": 20, "cookTime": 300, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"racks baby back ribs (about 4 lb total)\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}]", "instructions": "1. Mix brown sugar, paprika, salt, garlic powder, onion powder, black pepper and cayenne. Remove membrane from back of ribs by peeling with paper towel. Rub generously all over ribs; let sit 1 hour at room temperature or refrigerate overnight. 2. Preheat oven to 275°F. Wrap each rack tightly in foil; place on baking sheets. Bake low and slow for 3-3.5 hours until meat begins to pull away from bones. 3. Remove from oven; unwrap carefully. Transfer ribs to a foil-lined baking sheet. 4. Mix BBQ sauce with apple cider vinegar. Brush ribs generously with sauce. 5. Increase oven to 400°F or fire up a grill; cook ribs uncovered 20-30 minutes basting every 10 minutes until sauce is sticky and caramelized. 6. Rest 10 minutes; cut between bones to serve.", "tags": "4th-of-july, BBQ, summer", "source": "Classic", "nutritionData": "{\"calories\": 520, \"protein\": 38.0, \"carbs\": 18.0, \"fat\": 34.0}"},
  {"name": "Watermelon Feta Salad", "category": "Holiday Feasts", "description": "Refreshing summer salad of sweet watermelon, salty feta, cucumber and fresh mint with a honey-lime dressing.", "servings": 6, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/2\", \"name\": \"seedless watermelon (about 6 cups) cubed\"}, {\"qty\": \"1\", \"name\": \"English cucumber cubed\"}, {\"qty\": \"1/2 cup\", \"name\": \"crumbled feta cheese\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh mint leaves\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh basil leaves\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lime juice\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"pinch of kosher salt\"}]", "instructions": "1. Cut watermelon into 1-inch cubes and place in a large shallow serving bowl or platter. Add cucumber cubes and scatter mint and basil leaves over. 2. Whisk together honey, lime juice, olive oil and a pinch of salt in a small bowl. 3. Drizzle dressing over salad; toss gently to combine. 4. Scatter crumbled feta all over the top. Serve immediately or refrigerate up to 1 hour.", "tags": "4th-of-july, summer, no-cook", "source": "https://www.themediterraneandish.com/watermelon-salad-with-cucumber-feta/", "nutritionData": "{\"calories\": 120, \"protein\": 3.0, \"carbs\": 18.0, \"fat\": 5.0}"},
  {"name": "Classic American Potato Salad", "category": "Holiday Feasts", "description": "Creamy old-fashioned potato salad with hard-boiled eggs, dill pickles and a tangy mayo dressing.", "servings": 8, "prepTime": 20, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"Yukon Gold potatoes cut into 1-inch chunks\"}, {\"qty\": \"4\", \"name\": \"large hard-boiled eggs\"}, {\"qty\": \"1 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"yellow mustard\"}, {\"qty\": \"2\", \"name\": \"dill pickles finely diced\"}, {\"qty\": \"1 tbsp\", \"name\": \"pickle juice\"}, {\"qty\": \"2\", \"name\": \"stalks celery chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"red onion finely chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh dill and parsley chopped\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"smoked paprika for garnish\"}]", "instructions": "1. Boil potato chunks in well-salted water until just fork-tender, 12-15 minutes. Drain; return to pot and let steam dry 2 minutes. Transfer to a large bowl. 2. Separate egg yolks from whites. In a bowl, mash yolks with mayonnaise, sour cream, mustard, pickle juice, salt and pepper until smooth. 3. Chop egg whites and add to bowl with potatoes along with celery, red onion, pickles and half the herbs. 4. Pour dressing over and gently fold to combine keeping some potato chunks intact. Taste and adjust seasoning. 5. Sprinkle with remaining fresh herbs and a dusting of smoked paprika. Refrigerate at least 2 hours before serving.", "tags": "4th-of-july, summer, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 290, \"protein\": 7.0, \"carbs\": 30.0, \"fat\": 17.0}"},
  {"name": "Classic Peach Cobbler", "category": "Holiday Feasts", "description": "Golden crispy-topped peach cobbler with a sweet biscuit batter baked right over the fruit.", "servings": 8, "prepTime": 20, "cookTime": 70, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4.5 lb\", \"name\": \"fresh ripe peaches pitted and cut into chunks\"}, {\"qty\": \"\", \"name\": \"zest and juice of 1 lemon\"}, {\"qty\": \"4 oz\", \"name\": \"unsalted butter softened\"}, {\"qty\": \"1.5 cups\", \"name\": \"granulated sugar divided\"}, {\"qty\": \"1.5 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"3/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"hot water\"}, {\"qty\": \"\", \"name\": \"heavy cream for drizzling\"}]", "instructions": "1. Preheat oven to 350°F. Line a rimmed baking sheet with foil. Place peaches in a 9x13-inch baking dish; toss with lemon zest and juice. 2. Beat butter and 1 cup sugar until sandy. Add flour, baking powder and salt; beat until combined. Mix in milk on low for 2 minutes until light. 3. Drop batter in large blobs over peaches; spread evenly to about 1/2-inch thick. Sprinkle remaining 1/2 cup sugar evenly over batter. 4. Drizzle hot water evenly over the sugared batter (this creates the crackly crust). 5. Place dish on foil-lined baking sheet to catch drips. Bake 60-70 minutes until top is cracked and golden and a toothpick comes out clean. 6. Let cool at least 30 minutes before serving. Drizzle cream over each serving.", "tags": "4th-of-july, dessert, summer", "source": "https://smittenkitchen.com/2015/08/crispy-peach-cobbler/", "nutritionData": "{\"calories\": 395, \"protein\": 4.0, \"carbs\": 64.0, \"fat\": 15.0}"},
  {"name": "Mardi Gras Jambalaya", "category": "Holiday Feasts", "description": "A festive one-pot Cajun jambalaya with andouille sausage, chicken and shrimp for a crowd.", "servings": 8, "prepTime": 20, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"andouille sausage sliced\"}, {\"qty\": \"1.5 lb\", \"name\": \"boneless chicken thighs cut into 1-inch pieces\"}, {\"qty\": \"1 lb\", \"name\": \"large shrimp peeled and deveined\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1.5 cups\", \"name\": \"long-grain rice\"}, {\"qty\": \"3 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 can\", \"name\": \"(14 oz) diced tomatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1 cup\", \"name\": \"green onions sliced\"}]", "instructions": "1. Preheat oven to 350°F. Heat oil in a large Dutch oven over medium-high heat. Sear sausage slices until browned, 3 minutes; remove. Brown chicken until golden; remove. Sear shrimp 1.5 minutes per side; set aside separately. 2. Add butter, onion, bell pepper, celery and garlic; cook 3-4 minutes until softened. 3. Add rice; stir to coat grains in oil, 1-2 minutes. Add broth, tomatoes, tomato paste, paprika, thyme, cayenne and sausage and chicken. Stir well; bring to a boil. 4. Cover and transfer to oven; bake 25-30 minutes until rice is just cooked. 5. Add shrimp and green onions; quickly stir through; cover and return to oven 3 minutes until shrimp are just pink. 6. Fluff gently; taste and adjust seasoning. Serve immediately.", "tags": "mardi-gras, cajun, one-pot", "source": "https://www.recipetineats.com/jambalaya-recipe/", "nutritionData": "{\"calories\": 440, \"protein\": 32.0, \"carbs\": 42.0, \"fat\": 15.0}"},
  {"name": "St. Patrick's Day Corned Beef and Cabbage", "category": "Holiday Feasts", "description": "Classic Irish-American boiled corned beef with cabbage, potatoes and carrots in a savory broth.", "servings": 8, "prepTime": 15, "cookTime": 195, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lb\", \"name\": \"flat-cut corned beef brisket with spice packet\"}, {\"qty\": \"1\", \"name\": \"small head green cabbage cut into wedges\"}, {\"qty\": \"6\", \"name\": \"medium carrots peeled and cut into chunks\"}, {\"qty\": \"1.5 lb\", \"name\": \"small red potatoes halved\"}, {\"qty\": \"1\", \"name\": \"large onion quartered\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"\", \"name\": \"Dijon mustard or horseradish for serving\"}]", "instructions": "1. Place corned beef fat-side up in a large Dutch oven. Sprinkle over spice packet contents and add bay leaf. Add onion. Cover with water until just submerged. Bring to a boil, skim any foam, reduce heat and cover. Simmer gently for 3 hours until fork-tender. 2. Transfer beef to a cutting board; tent with foil. Bring braising liquid to a boil. 3. Add potatoes and carrots to the boiling liquid; cook covered 10 minutes. Add cabbage wedges; cover and cook 10 more minutes until vegetables are fork-tender. 4. Drain vegetables; toss potatoes and carrots with butter, salt, pepper and parsley. 5. Slice corned beef against the grain into thin slices. Serve with vegetables, some braising liquid ladled over top and Dijon mustard.", "tags": "st-patricks-day, irish, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 410, \"protein\": 33.0, \"carbs\": 22.0, \"fat\": 19.0}"},
  {"name": "St. Patrick's Day Shepherd's Pie", "category": "Holiday Feasts", "description": "Hearty Irish shepherd's pie with a savory ground lamb filling and creamy mashed potato topping.", "servings": 6, "prepTime": 20, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lb\", \"name\": \"ground lamb or beef\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"2\", \"name\": \"carrots diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 cup\", \"name\": \"beef broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"3 lb\", \"name\": \"Yukon Gold potatoes peeled and quartered\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/2 cup\", \"name\": \"warm milk\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F. Cook potatoes in boiling salted water until tender, 15 minutes. Drain; mash with butter, warm milk, salt and pepper until smooth. Set aside. 2. Brown lamb in a large oven-safe skillet over medium-high heat, breaking up with a spoon, 8 minutes. Drain excess fat. Add onion, carrots and celery; cook 5 minutes. Add garlic; cook 1 minute. 3. Stir in tomato paste; cook until darkened, 2 minutes. Add Worcestershire, broth, thyme and rosemary. Simmer 5 minutes until slightly thickened. Stir in peas. Season with salt and pepper. 4. Dollop mashed potatoes evenly over filling; spread into a uniform layer. Run a fork over the surface to create ridges. 5. Bake 25-30 minutes until filling is bubbling. Broil 2 minutes until top begins to brown. Rest 10 minutes before serving.", "tags": "st-patricks-day, irish, comfort-food", "source": "Classic", "nutritionData": "{\"calories\": 480, \"protein\": 28.0, \"carbs\": 45.0, \"fat\": 19.0}"},
  {"name": "Mother's Day Brunch Quiche", "category": "Holiday Feasts", "description": "A classic quiche Lorraine with caramelized leeks, ham and Swiss cheese in a buttery pastry shell.", "servings": 6, "prepTime": 45, "cookTime": 35, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"unbaked 9-inch pie shell\"}, {\"qty\": \"3/4 cup\", \"name\": \"diced leeks white and light green parts\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1.5 cups\", \"name\": \"diced ham\"}, {\"qty\": \"3/4 cup\", \"name\": \"grated Swiss cheese\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"1/2 cup\", \"name\": \"heavy cream\"}, {\"qty\": \"1 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"kosher salt to taste\"}]", "instructions": "1. Preheat oven to 375°F. Sauté leeks in olive oil over low heat 25-30 minutes until caramelized; let cool. 2. Refrigerate pie shell 30 minutes. Spread leeks over the base; scatter ham and Swiss cheese on top. 3. Whisk eggs, heavy cream and sour cream until smooth; season with nutmeg, salt and pepper. Pour into pie shell. 4. Place on a baking sheet. Bake until puffed and golden, 25-35 minutes. A knife inserted near center should come out mostly clean. 5. Cool on a rack 10 minutes. Slice and serve warm or at room temperature.", "tags": "mothers-day, brunch, make-ahead", "source": "https://smittenkitchen.com/2009/10/quiche-lorraine/", "nutritionData": "{\"calories\": 430, \"protein\": 20.0, \"carbs\": 22.0, \"fat\": 31.0}"},
  {"name": "Cinco de Mayo Carnitas Tacos", "category": "Holiday Feasts", "description": "Slow-braised crispy pork carnitas in corn tortillas with roasted jalapeño avocado for a crowd.", "servings": 8, "prepTime": 20, "cookTime": 180, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lb\", \"name\": \"boneless pork shoulder cut into 3-inch pieces\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"orange juice\"}, {\"qty\": \"1/4 cup\", \"name\": \"lime juice\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"16\", \"name\": \"corn tortillas\"}, {\"qty\": \"2\", \"name\": \"avocados mashed\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1os roasted and chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"\", \"name\": \"lime wedges for serving\"}]", "instructions": "1. Preheat oven to 325°F. Arrange pork in a large Dutch oven. Add garlic powder, onion powder, paprika, cumin, oregano and salt; rub all over pork. Pour over orange juice, lime juice and water. 2. Cover and roast for 2.5-3 hours until very tender and falling apart. 3. Increase oven to 425°F. Uncover and roast 10 more minutes until pork is deeply caramelized on top. Remove pork and shred with two forks. 4. Char or roast jalapeños over open flame or under broiler until blackened. Remove some charred skin; finely chop. Mash with avocado, cilantro and a pinch of salt. 5. Warm corn tortillas in a dry skillet or microwave. Fill each with carnitas and top with jalapeño avocado and cilantro. Serve with lime wedges.", "tags": "cinco-de-mayo, mexican, crowd-pleaser", "source": "https://www.halfbakedharvest.com/crispy-carnitas-tacos/", "nutritionData": "{\"calories\": 420, \"protein\": 30.0, \"carbs\": 28.0, \"fat\": 20.0}"},
  {"name": "Classic Buffalo Wings", "category": "Game Day", "description": "Crispy baked chicken wings tossed in buttery Frank's RedHot sauce with blue cheese dip on the side.", "servings": 6, "prepTime": 15, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"chicken wings drumettes and flats\"}, {\"qty\": \"2.5 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"4 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/2 cup\", \"name\": \"Frank's RedHot Original sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"blue cheese crumbled\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 clove\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}]", "instructions": "1. Pat wings dry and toss with baking powder and salt in a zip-top bag. 2. Spread on a wire rack over a foil-lined baking sheet and refrigerate uncovered 8 hours or overnight. 3. Preheat oven to 250°F. Bake wings on lower rack 30 minutes. 4. Increase oven to 425°F and move wings to upper rack. Bake 40-50 minutes, rotating halfway, until skin is very crispy and deep golden. 5. Whisk together melted butter, hot sauce, and brown sugar. Toss hot wings in sauce. 6. Make blue cheese dip by mashing blue cheese with sour cream, mayo, garlic, and lemon juice. Serve alongside.", "tags": "wings, super-bowl, crowd-pleaser", "source": "https://www.seriouseats.com/the-best-buffalo-wings-recipe", "nutritionData": "{\"calories\": 820, \"protein\": 62.0, \"carbs\": 5.0, \"fat\": 57.0}"},
  {"name": "Korean Fried Chicken Wings", "category": "Game Day", "description": "Double-fried chicken wings in a crispy batter coated with sticky gochujang honey glaze and sesame seeds.", "servings": 4, "prepTime": 20, "cookTime": 40, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"chicken wings\"}, {\"qty\": \"1/2 cup\", \"name\": \"potato starch\"}, {\"qty\": \"1/2 cup\", \"name\": \"cornstarch\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"cold water\"}, {\"qty\": \"8 cups\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"ginger minced\"}, {\"qty\": \"3 tbsp\", \"name\": \"gochujang\"}, {\"qty\": \"3 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"3 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"6 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"sliced scallions\"}, {\"qty\": \"1 tbsp\", \"name\": \"toasted sesame seeds\"}]", "instructions": "1. Whisk potato starch, cornstarch, baking powder, salt, and cold water into a thin batter. 2. Heat oil to 325°F. Dip wings in batter and fry in batches 4-5 minutes until lightly golden. Drain and cool to room temperature, then freeze 2 hours. 3. Make sauce: sauté garlic and ginger in sesame oil 2 minutes, add gochujang, soy sauce, rice vinegar, and honey. Simmer 10-12 minutes until syrupy. 4. Heat oil to 375-400°F. Fry frozen wings 4-5 minutes until deep golden and crispy. 5. Drain wings and toss in sauce. 6. Transfer to platter and garnish with scallions and sesame seeds.", "tags": "wings, korean, super-bowl", "source": "https://www.seriouseats.com/korean-fried-chicken-wings", "nutritionData": "{\"calories\": 850, \"protein\": 58.0, \"carbs\": 28.0, \"fat\": 48.0}"},
  {"name": "Lemon Pepper Wings", "category": "Game Day", "description": "Crispy baked wings tossed in a buttery lemon pepper glaze with honey and fresh lemon juice.", "servings": 4, "prepTime": 10, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"chicken wings\"}, {\"qty\": \"2 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"6 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon pepper seasoning\"}, {\"qty\": \"4 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Preheat oven to 425°F. Line a baking sheet with parchment paper. 2. Toss wings with baking powder and salt until evenly coated. Arrange in a single layer on the baking sheet. 3. Bake 40-45 minutes until wings are golden and crispy. 4. Whisk together melted butter, lemon pepper seasoning, honey, and lemon juice. 5. Remove wings from oven and brush with lemon pepper glaze, tossing to coat. 6. Garnish with lemon wedges and parsley and serve immediately.", "tags": "wings, lemon-pepper, party", "source": "https://damndelicious.net/lemon-pepper-wings", "nutritionData": "{\"calories\": 1050, \"protein\": 98.0, \"carbs\": 15.0, \"fat\": 65.0}"},
  {"name": "Garlic Parmesan Wings", "category": "Game Day", "description": "Baked chicken wings tossed in herb-garlic olive oil and showered with freshly grated Parmesan cheese.", "servings": 4, "prepTime": 15, "cookTime": 50, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chicken wings drumettes and flats\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"2 tsp\", \"name\": \"kosher salt divided\"}, {\"qty\": \"3 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh basil finely minced\"}, {\"qty\": \"2 tsp\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh thyme minced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"red pepper flakes\"}, {\"qty\": \"1/3 cup\", \"name\": \"Parmesan grated\"}]", "instructions": "1. Pat wings dry. Toss with baking powder and 1 tsp salt. Arrange on wire rack over baking sheet. Refrigerate uncovered 8 hours. 2. In a large bowl whisk together olive oil, basil, garlic, thyme, black pepper, red pepper flakes, and remaining salt. Set aside. 3. Preheat grill to high indirect heat or preheat oven to 425°F. Cook wings over cool side of grill 30-40 minutes until skin is golden and blistered. 4. Transfer hot wings to bowl with herb oil and toss well. 5. Add Parmesan cheese and toss again until wings are evenly coated. 6. Transfer to serving platter and serve immediately.", "tags": "wings, parmesan, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 880, \"protein\": 73.0, \"carbs\": 3.0, \"fat\": 59.0}"},
  {"name": "BBQ Smoked Wings", "category": "Game Day", "description": "Low-and-slow smoked chicken wings glazed with sweet BBQ sauce and finished over high heat for crispy skin.", "servings": 4, "prepTime": 10, "cookTime": 150, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"chicken wings\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"2 tbsp\", \"name\": \"BBQ dry rub seasoning\"}, {\"qty\": \"2 tbsp\", \"name\": \"sweet BBQ glaze or sauce\"}, {\"qty\": \"\", \"name\": \"apple or cherry wood chips\"}]", "instructions": "1. Pat wings dry. Place in a zip-top bag with avocado oil and toss to coat. Add BBQ rub and shake until evenly coated. 2. Preheat smoker to 275°F using apple or cherry wood. Place wings directly on grates, close lid, and smoke 2 hours until internal temperature reaches 160-165°F. 3. Remove wings to a baking sheet. Increase smoker temperature to 400-450°F. 4. Brush wings with BBQ glaze and return to the smoker. Cook 3-4 minutes per side until wings reach 175°F internal temperature. 5. Remove from smoker. Drizzle with additional sauce if desired. 6. Serve immediately with ranch or blue cheese dressing.", "tags": "wings, smoked, super-bowl", "source": "https://heygrillhey.com/crispy-smoked-chicken-wings/", "nutritionData": "{\"calories\": 520, \"protein\": 49.0, \"carbs\": 8.0, \"fat\": 32.0}"},
  {"name": "Sticky Honey-Soy Wings", "category": "Game Day", "description": "Oven-baked wings marinated in honey, soy, and garlic, basted repeatedly until lacquered and sticky.", "servings": 4, "prepTime": 35, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"chicken wings\"}, {\"qty\": \"4 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"balsamic vinegar\"}, {\"qty\": \"3 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"Sriracha\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ginger powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"cornstarch\"}, {\"qty\": \"2 tbsp\", \"name\": \"sliced scallions\"}, {\"qty\": \"1 tsp\", \"name\": \"toasted sesame seeds\"}]", "instructions": "1. Whisk soy sauce, balsamic, brown sugar, honey, garlic, Sriracha, ginger, pepper, and onion powder in a bowl. 2. Place wings in a zip-top bag, pour in marinade, and toss. Marinate 30 minutes at room temperature. 3. Preheat oven to 400°F. Line a baking sheet with foil. Arrange wings skin side up and reserve marinade. Bake 30 minutes. 4. Drain juices off the pan. Pour reserved marinade over wings and toss to coat. Turn oven to 350°F. Bake 30 more minutes, basting with pan juices every 10 minutes. 5. Broil 2-3 minutes for extra caramelization. 6. Garnish with sesame seeds and scallions and serve.", "tags": "wings, honey-soy, party", "source": "https://damndelicious.net/2014/10/01/slow-cooker-sticky-chicken-wings/", "nutritionData": "{\"calories\": 580, \"protein\": 50.0, \"carbs\": 25.0, \"fat\": 32.0}"},
  {"name": "Grilled BBQ Wings", "category": "Game Day", "description": "Grilled chicken wings with a honey BBQ glaze, charred and smoky with caramelized sauce.", "servings": 4, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chicken wings\"}, {\"qty\": \"1 tbsp\", \"name\": \"avocado oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"honey BBQ sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}]", "instructions": "1. Preheat grill to 425°F. Pat wings dry and toss with avocado oil, salt, pepper, and garlic powder. 2. Whisk BBQ sauce, honey, Worcestershire, and smoked paprika in a saucepan over medium heat. Bring to a simmer 5 minutes. Keep warm. 3. Place wings on grill grates. Close lid and grill 15-20 minutes, flipping every 3-5 minutes, until skin is crispy and internal temperature reaches 170-175°F. 4. Brush wings generously with BBQ glaze and grill 2-3 more minutes per side for caramelized crust. 5. Remove from grill and toss in remaining glaze. 6. Serve immediately.", "tags": "wings, BBQ, grilled", "source": "https://heygrillhey.com/grilled-chicken-wings/", "nutritionData": "{\"calories\": 760, \"protein\": 74.0, \"carbs\": 18.0, \"fat\": 47.0}"},
  {"name": "Baked Crispy Wings", "category": "Game Day", "description": "Ultra-crispy oven-baked wings using the baking powder method — no frying required, served with any sauce.", "servings": 4, "prepTime": 480, "cookTime": 70, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chicken wings drumettes and flats\"}, {\"qty\": \"1 tbsp\", \"name\": \"baking powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"hot sauce or BBQ sauce for serving\"}]", "instructions": "1. Pat wings completely dry with paper towels. Toss with baking powder, salt, garlic powder, paprika, and pepper in a zip-top bag. 2. Spread wings in a single layer on a wire rack over a foil-lined baking sheet. Refrigerate uncovered at least 8 hours or overnight. 3. Preheat oven to 250°F. Place baking sheet on lower oven rack and bake 30 minutes. 4. Increase oven temperature to 425°F and move sheet to upper rack. Bake 40-50 minutes, rotating pan halfway, until skin is very dark golden and crispy. 5. Let rest 5 minutes. Serve with your choice of dipping sauce. 6. Toss in any sauce or serve plain for maximum crispiness.", "tags": "wings, crispy, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 720, \"protein\": 81.0, \"carbs\": 2.0, \"fat\": 43.0}"},
  {"name": "7-Layer Dip", "category": "Game Day", "description": "Classic party dip with layered refried beans, guacamole, sour cream, cheese, tomatoes, olives, and scallions.", "servings": 12, "prepTime": 20, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 can\", \"name\": \"16 oz refried beans\"}, {\"qty\": \"1\", \"name\": \"packet taco seasoning\"}, {\"qty\": \"2 cups\", \"name\": \"guacamole\"}, {\"qty\": \"1.5 cups\", \"name\": \"sour cream\"}, {\"qty\": \"1.5 cups\", \"name\": \"shredded Mexican blend cheese\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes diced\"}, {\"qty\": \"1 can\", \"name\": \"3.8 oz sliced black olives drained\"}, {\"qty\": \"4\", \"name\": \"scallions chopped\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o sliced optional\"}, {\"qty\": \"\", \"name\": \"tortilla chips for serving\"}]", "instructions": "1. Spread refried beans evenly in the bottom of a 9x13 dish. Mix half the taco seasoning into the beans for extra flavor. 2. Spread guacamole in an even layer over the beans. 3. Mix remaining taco seasoning into sour cream, then spread over the guacamole layer. 4. Sprinkle shredded cheese evenly over the sour cream. 5. Top with diced tomatoes, sliced black olives, and scallions. 6. Add jalapeño slices if desired. Serve immediately or refrigerate up to 4 hours before serving. Serve with tortilla chips.", "tags": "dip, party, make-ahead", "source": "https://www.thekitchn.com/7-layer-dip-265851", "nutritionData": "{\"calories\": 230, \"protein\": 7.0, \"carbs\": 16.0, \"fat\": 16.0}"},
  {"name": "Buffalo Chicken Dip", "category": "Game Day", "description": "Creamy, spicy baked dip loaded with shredded chicken, cream cheese, Frank's hot sauce, and cheddar cheese.", "servings": 10, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"shredded cooked chicken\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"3/4 cup\", \"name\": \"Frank's RedHot Buffalo sauce\"}, {\"qty\": \"1 cup\", \"name\": \"ranch dressing\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese divided\"}, {\"qty\": \"\", \"name\": \"kosher salt and black pepper\"}, {\"qty\": \"\", \"name\": \"tortilla chips or celery sticks for serving\"}]", "instructions": "1. Preheat oven to 375°F. Lightly grease an 8x8 baking dish. 2. Cook and shred chicken breast if starting from raw, then mix with hot sauce. 3. Stir together cream cheese, ranch dressing, hot sauce-chicken mixture, and 1 cup of cheddar until well combined. 4. Transfer to prepared baking dish and spread evenly. Top with remaining cup of cheddar cheese. 5. Bake uncovered 18-20 minutes until bubbly and edges are lightly browned. 6. Serve hot with tortilla chips or celery sticks.", "tags": "dip, buffalo, super-bowl", "source": "https://damndelicious.net/2014/09/03/buffalo-chicken-dip/", "nutritionData": "{\"calories\": 330, \"protein\": 18.0, \"carbs\": 5.0, \"fat\": 28.0}"},
  {"name": "Roasted Spinach Artichoke Dip", "category": "Game Day", "description": "Warm baked dip with roasted lemon, jalapeño, cream cheese, fontina, spinach, and marinated artichokes.", "servings": 8, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"small Meyer lemon\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o halved\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1 cup\", \"name\": \"fontina cheese cubed\"}, {\"qty\": \"1 cup\", \"name\": \"mozzarella cheese cubed divided\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"10 oz\", \"name\": \"frozen chopped spinach thawed and squeezed dry\"}, {\"qty\": \"12 oz\", \"name\": \"marinated artichoke hearts roughly chopped\"}, {\"qty\": \"2 tbsp\", \"name\": \"pine nuts\"}, {\"qty\": \"\", \"name\": \"kosher salt and pepper\"}, {\"qty\": \"\", \"name\": \"crackers or bread for dipping\"}]", "instructions": "1. Preheat oven to 375°F. Place lemon quarters, jalapeño, and garlic in a small baking dish with olive oil. Season with salt and pepper. Roast 15-20 minutes until golden. 2. Let cool, then finely chop roasted lemon, jalapeño, and garlic into a rough paste. 3. In a medium bowl, combine cream cheese, fontina, half the mozzarella, smoked paprika, spinach, artichokes, and the roasted lemon paste. Season with salt and pepper. 4. Transfer to a greased 8-inch baking dish. Top with remaining mozzarella. 5. Bake 15-20 minutes until cheese is melted and bubbling. 6. Top with pine nuts and serve warm with crackers or bread.", "tags": "dip, spinach-artichoke, vegetarian", "source": "https://www.halfbakedharvest.com/roasted-lemon-spinach-and-artichoke-dip/", "nutritionData": "{\"calories\": 270, \"protein\": 10.0, \"carbs\": 8.0, \"fat\": 21.0}"},
  {"name": "Jalapeño Queso Dip", "category": "Game Day", "description": "Silky stovetop queso with fresh jalapeños, chipotle peppers, cream cheese, and melted cheddar for dipping.", "servings": 8, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"1\", \"name\": \"small onion diced\"}, {\"qty\": \"2\", \"name\": \"jalape\\u00f1os seeded and diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"kosher salt\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2 cups\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"1-2 chipotle peppers in adobo minced\"}, {\"qty\": \"\", \"name\": \"salsa for topping\"}, {\"qty\": \"\", \"name\": \"avocado slices for topping\"}, {\"qty\": \"\", \"name\": \"tortilla chips for serving\"}]", "instructions": "1. Melt butter in a large skillet over medium heat. Add onion, jalapeños, garlic, cumin, and a pinch of salt. Cook 5-10 minutes until onion is fragrant. 2. Add cream cheese and milk. Cook over medium heat, stirring, until cream cheese is melted and sauce is smooth. 3. In a bowl, toss shredded cheddar with flour. 4. Little by little add the cheese to the warm milk mixture, whisking until the sauce is smooth. 5. Stir in chipotle peppers. Taste and season with salt. 6. Serve warm topped with salsa and avocado slices with tortilla chips.", "tags": "dip, queso, party", "source": "https://www.halfbakedharvest.com/the-best-jalapeno-queso/", "nutritionData": "{\"calories\": 280, \"protein\": 12.0, \"carbs\": 8.0, \"fat\": 23.0}"},
  {"name": "Pimento Cheese Dip", "category": "Game Day", "description": "Southern-style pimento cheese made with sharp cheddar, cream cheese, and pimentos — bold and spreadable.", "servings": 8, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"sharp cheddar cheese freshly shredded\"}, {\"qty\": \"4 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"4 oz\", \"name\": \"diced pimentos drained\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o seeded and minced optional\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}, {\"qty\": \"\", \"name\": \"crackers or crudit\\u00e9s for serving\"}]", "instructions": "1. Shred cheddar cheese fresh for best results. Set aside 2 oz for folding in later. 2. Combine cream cheese, drained pimentos, remaining cheddar, mayo, garlic powder, onion powder, cayenne, and black pepper in a food processor. 3. Pulse until combined and somewhat whipped — about 1 minute on and off. Do not overprocess; you want some texture. 4. Remove from food processor and transfer to a bowl. Fold in reserved shredded cheddar and jalapeño if using. 5. Taste and adjust seasoning with salt and more cayenne if desired. 6. Serve immediately or refrigerate up to 1 week; let sit at room temperature 30 minutes before serving with crackers or veggies.", "tags": "dip, southern, make-ahead", "source": "https://www.thekitchn.com/pimento-cheese-recipe-23649988", "nutritionData": "{\"calories\": 220, \"protein\": 9.0, \"carbs\": 3.0, \"fat\": 20.0}"},
  {"name": "Beer Cheese Dip", "category": "Game Day", "description": "Pub-style warm beer cheese dip with sharp cheddar, Gruyère, and a splash of beer — perfect for pretzels.", "servings": 8, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1/4 cup\", \"name\": \"unsalted butter\"}, {\"qty\": \"1/4 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cayenne pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 cup\", \"name\": \"whole milk\"}, {\"qty\": \"2/3 cup\", \"name\": \"beer lager or ale\"}, {\"qty\": \"1 tsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 cups\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Gruy\\u00e8re or Swiss cheese\"}, {\"qty\": \"\", \"name\": \"soft pretzels or vegetables for dipping\"}]", "instructions": "1. In a medium saucepan over medium heat, melt butter. Whisk in flour, onion powder, garlic powder, cayenne, and salt. Cook 1 minute. 2. Gradually whisk in milk and beer a little at a time until smooth after each addition. 3. Continue cooking over medium heat, stirring constantly. Add mustard and Worcestershire sauce. Cook until sauce is thick and bubbly, about 5 minutes. 4. Turn off heat. Add cheddar and Gruyère and stir until completely melted and smooth. 5. Taste and adjust seasoning with salt and cayenne. 6. Transfer to a serving bowl and serve warm with pretzels, vegetables, or tortilla chips.", "tags": "dip, beer-cheese, party", "source": "https://www.spendwithpennies.com/beer-cheese-dip/", "nutritionData": "{\"calories\": 270, \"protein\": 13.0, \"carbs\": 7.0, \"fat\": 22.0}"},
  {"name": "Hot Crab Dip", "category": "Game Day", "description": "Bubbly baked crab dip with lump crabmeat, Old Bay cream cheese, mozzarella, Parmesan, and a golden crust.", "servings": 8, "prepTime": 15, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1/2\", \"name\": \"lemon zested and juiced\"}, {\"qty\": \"1.5 tsp\", \"name\": \"Old Bay seasoning\"}, {\"qty\": \"8 oz\", \"name\": \"lump crab meat drained\"}, {\"qty\": \"2 cups\", \"name\": \"shredded mozzarella cheese divided\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"2\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"crostini or crackers for serving\"}]", "instructions": "1. Preheat oven to 375°F. Spray an 8-inch oven-safe skillet or baking dish with cooking spray. 2. Blend cream cheese, mayonnaise, sour cream, lemon zest, lemon juice, and Old Bay seasoning with a hand mixer until smooth. 3. Fold in lump crab meat, 1.5 cups mozzarella, Parmesan, and most of the scallions. 4. Spread evenly in the prepared dish. Sprinkle reserved mozzarella and scallions on top. 5. Bake uncovered 25 minutes until top is browned and dip is bubbly. 6. Let rest 5 minutes then serve with crostini or crackers.", "tags": "dip, crab, seafood", "source": "https://www.thekitchn.com/crab-dip-recipe-23612449", "nutritionData": "{\"calories\": 295, \"protein\": 16.0, \"carbs\": 4.0, \"fat\": 24.0}"},
  {"name": "Queso Fundido", "category": "Game Day", "description": "Baked Mexican chorizo-and-cheese skillet dip with melted Oaxacan cheese and served with warm tortillas.", "servings": 6, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"8 oz\", \"name\": \"Mexican chorizo casings removed\"}, {\"qty\": \"1/2\", \"name\": \"small onion finely diced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2\", \"name\": \"jalape\\u00f1o seeded and minced\"}, {\"qty\": \"1 cup\", \"name\": \"Oaxacan cheese shredded\"}, {\"qty\": \"1 cup\", \"name\": \"Monterey Jack cheese shredded\"}, {\"qty\": \"1/2 cup\", \"name\": \"mozzarella shredded\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}, {\"qty\": \"\", \"name\": \"salsa for topping\"}, {\"qty\": \"\", \"name\": \"flour tortillas for dipping\"}]", "instructions": "1. Preheat oven to 400°F. Heat a 10-inch oven-safe skillet over medium-high heat. 2. Add chorizo to skillet and brown, breaking it up, about 5 minutes. Slide cooked chorizo out onto a plate. Drain excess fat if needed. 3. In the same skillet, sauté onion, garlic, and jalapeño until softened, about 3 minutes. 4. Return chorizo to pan and spread evenly. Top with all the shredded cheeses. 5. Transfer skillet to oven and bake 10-15 minutes until cheese is melted and beginning to bubble. 6. Serve immediately topped with fresh cilantro and salsa with warm flour tortillas.", "tags": "dip, queso-fundido, mexican", "source": "https://www.halfbakedharvest.com/queso-fundido-alla-tequila/", "nutritionData": "{\"calories\": 360, \"protein\": 20.0, \"carbs\": 8.0, \"fat\": 27.0}"},
  {"name": "Crowd Guacamole", "category": "Game Day", "description": "Restaurant-style chunky guacamole made with a spiced paste base of jalapeño, onion, and cilantro.", "servings": 6, "prepTime": 15, "cookTime": 0, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large ripe avocados\"}, {\"qty\": \"2 tbsp\", \"name\": \"finely chopped white onion\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o seeded and diced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt plus more to taste\"}, {\"qty\": \"1/4 cup\", \"name\": \"chopped cilantro\"}, {\"qty\": \"\", \"name\": \"juice of 1 lime\"}, {\"qty\": \"1\", \"name\": \"Roma tomato peeled seeded and diced\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"\", \"name\": \"pinch of garlic powder\"}, {\"qty\": \"\", \"name\": \"tortilla chips for serving\"}]", "instructions": "1. Combine onion, jalapeño, salt, cumin, and half the cilantro on a cutting board. Use a fork to mash into a coarse paste. 2. Alternatively, grind into a paste using a mortar and pestle. This is the flavor base. 3. Scrape paste into a large bowl. Halve and pit avocados; scoop fruit into the bowl. 4. Mash avocado to desired consistency — chunky or smooth. 5. Stir in lime juice, remaining cilantro, and diced tomato. Taste and adjust salt, lime, and jalapeño as needed. 6. Serve immediately with tortilla chips. To store, press plastic wrap directly onto surface to prevent browning.", "tags": "dip, guacamole, party", "source": "Classic", "nutritionData": "{\"calories\": 190, \"protein\": 3.0, \"carbs\": 12.0, \"fat\": 17.0}"},
  {"name": "Pulled Pork Sliders", "category": "Game Day", "description": "Slow-cooker pulled pork with tangy homemade BBQ sauce piled onto sweet Hawaiian rolls with zesty coleslaw.", "servings": 12, "prepTime": 20, "cookTime": 480, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4 lbs\", \"name\": \"boneless pork shoulder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"medium onion chopped\"}, {\"qty\": \"3/4 cup\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1/2 cup\", \"name\": \"ketchup\"}, {\"qty\": \"1/4 cup\", \"name\": \"brown sugar\"}, {\"qty\": \"1/4 cup\", \"name\": \"molasses\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"dry mustard\"}, {\"qty\": \"5 cups\", \"name\": \"coleslaw mix\"}, {\"qty\": \"1/3 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"white vinegar\"}, {\"qty\": \"2 tsp\", \"name\": \"sugar\"}, {\"qty\": \"12\", \"name\": \"Hawaiian sweet rolls\"}]", "instructions": "1. Season pork with salt and pepper. Sear in a skillet over medium-high heat on all sides until browned. 2. In a medium bowl, combine onion, apple cider vinegar, ketchup, brown sugar, molasses, Worcestershire, and dry mustard. 3. Place pork in slow cooker, pour sauce over top. Cook on low 8-10 hours until fork-tender. 4. Remove pork, shred with two forks, discard large fat pieces. Return to slow cooker with enough sauce for desired consistency. 5. Prepare coleslaw by whisking mayo, vinegar, and sugar together, then toss with coleslaw mix. 6. Slice Hawaiian rolls, pile high with pulled pork and coleslaw. Serve.", "tags": "sliders, pulled-pork, crowd-pleaser", "source": "https://www.spendwithpennies.com/slow-cooker-pulled-pork-sandwiches-zesty-slaw/", "nutritionData": "{\"calories\": 560, \"protein\": 40.0, \"carbs\": 32.0, \"fat\": 34.0}"},
  {"name": "Cheeseburger Sliders", "category": "Game Day", "description": "Hawaiian roll cheeseburger sliders with seasoned ground beef, special sauce, pickles, and melted cheddar.", "servings": 12, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"85/15 ground beef\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"12\", \"name\": \"Hawaiian sweet rolls\"}, {\"qty\": \"8 slices\", \"name\": \"sharp cheddar cheese\"}, {\"qty\": \"\", \"name\": \"dill pickle slices\"}, {\"qty\": \"2 tbsp\", \"name\": \"sesame seeds\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"1/4 cup\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tbsp\", \"name\": \"ketchup\"}, {\"qty\": \"1 tbsp\", \"name\": \"sweet pickle relish\"}]", "instructions": "1. Preheat oven to 350°F. Grease a small sheet pan. 2. Mix ground beef with salt, pepper, onion powder, garlic powder, and Worcestershire. Pat into a rectangle on the pan. Bake 15 minutes until browned. Drain grease. 3. Slice Hawaiian rolls in half horizontally. Place bottom half on the sheet pan. 4. Whisk together mayo, ketchup, and relish for special sauce. 5. Place cheese on roll bottoms, add beef patty, drizzle with special sauce, add pickles. Place top buns on. Brush with melted butter, sprinkle sesame seeds. 6. Wrap in foil and bake 15 minutes. Uncover and bake 5-6 minutes until tops are golden. Slice and serve.", "tags": "sliders, cheeseburger, super-bowl", "source": "https://www.thekitchn.com/cheeseburger-sliders-recipe-23626544", "nutritionData": "{\"calories\": 390, \"protein\": 22.0, \"carbs\": 22.0, \"fat\": 25.0}"},
  {"name": "BBQ Chicken Sliders", "category": "Game Day", "description": "Tender shredded BBQ chicken piled onto toasted Hawaiian rolls with pickled jalapeños and creamy slaw.", "servings": 12, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter\"}, {\"qty\": \"12\", \"name\": \"Hawaiian sweet rolls\"}, {\"qty\": \"2 cups\", \"name\": \"coleslaw mix\"}, {\"qty\": \"3 tbsp\", \"name\": \"mayonnaise\"}, {\"qty\": \"1 tbsp\", \"name\": \"apple cider vinegar\"}, {\"qty\": \"1 tsp\", \"name\": \"sugar\"}, {\"qty\": \"\", \"name\": \"pickled jalape\\u00f1os optional\"}, {\"qty\": \"4 oz\", \"name\": \"provolone cheese sliced\"}]", "instructions": "1. Season chicken with garlic powder and smoked paprika. Place in a skillet with broth and half the BBQ sauce. 2. Simmer covered over medium heat 20-25 minutes until chicken is cooked through and tender. 3. Shred chicken using two forks. Add remaining BBQ sauce and toss to coat. 4. Toss coleslaw mix with mayo, apple cider vinegar, and sugar. 5. Melt butter and brush cut sides of rolls. Toast in a skillet or under the broiler until golden. 6. Add a slice of cheese to each roll bottom, pile on shredded chicken, top with coleslaw and jalapeños. Serve.", "tags": "sliders, chicken, BBQ", "source": "Classic", "nutritionData": "{\"calories\": 340, \"protein\": 28.0, \"carbs\": 26.0, \"fat\": 14.0}"},
  {"name": "Meatball Subs", "category": "Game Day", "description": "Italian-style meatball sub sandwiches loaded with marinara, melted provolone, and fresh basil.", "servings": 6, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"85/15 ground beef\"}, {\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"1/2 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1\", \"name\": \"large egg\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"25 oz\", \"name\": \"jar marinara sauce\"}, {\"qty\": \"6\", \"name\": \"hoagie rolls\"}, {\"qty\": \"6 slices\", \"name\": \"provolone cheese\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter softened\"}, {\"qty\": \"\", \"name\": \"fresh basil for garnish\"}]", "instructions": "1. Preheat oven to 400°F. Combine beef, pork, breadcrumbs soaked in milk, Parmesan, egg, garlic, Italian seasoning, and salt in a bowl. Mix gently. 2. Roll into 1.5-inch balls and arrange on a parchment-lined baking sheet. Bake 18-20 minutes until cooked through. 3. Transfer cooked meatballs to a saucepan with marinara. Simmer covered 10 minutes. 4. Mix butter with minced garlic and spread on cut sides of rolls. Broil rolls 2-3 minutes until golden. 5. Place 4-5 meatballs in each toasted roll and top with sauce and a slice of provolone. 6. Broil 2-3 minutes until cheese is melted. Garnish with basil and serve.", "tags": "sliders, meatball, italian", "source": "https://www.spendwithpennies.com/meatball-sub/", "nutritionData": "{\"calories\": 760, \"protein\": 54.0, \"carbs\": 44.0, \"fat\": 40.0}"},
  {"name": "Bacon-Wrapped Jalapeño Poppers", "category": "Game Day", "description": "Cream cheese and cheddar-stuffed jalapeño halves wrapped in bacon and grilled until crispy and caramelized.", "servings": 6, "prepTime": 20, "cookTime": 25, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large jalape\\u00f1os halved and seeded\"}, {\"qty\": \"8 oz\", \"name\": \"cream cheese softened\"}, {\"qty\": \"8 oz\", \"name\": \"sharp cheddar cheese shredded\"}, {\"qty\": \"1 tbsp\", \"name\": \"BBQ dry rub or seasoning\"}, {\"qty\": \"12 slices\", \"name\": \"bacon halved\"}]", "instructions": "1. Preheat grill to 375-400°F using two-zone heat (one direct, one indirect). 2. In a bowl, combine cream cheese and cheddar cheese. Mix until well blended. 3. Slice jalapeños in half lengthwise. Scrape out seeds and ribs with a spoon. 4. Fill each jalapeño half with about 1 tablespoon of the cheese filling. 5. Wrap each stuffed jalapeño in half a slice of bacon. Tuck ends under or secure with a toothpick. Sprinkle with BBQ rub. 6. Grill over indirect heat 20-25 minutes. Move to direct heat 2-3 minutes to crisp the bacon. Serve hot.", "tags": "finger-food, jalapeño-poppers, party", "source": "https://heygrillhey.com/grilled-jalapeno-poppers/", "nutritionData": "{\"calories\": 380, \"protein\": 19.0, \"carbs\": 3.0, \"fat\": 33.0}"},
  {"name": "Bacon-Wrapped Dates with Goat Cheese", "category": "Game Day", "description": "Sweet Medjool dates stuffed with creamy goat cheese, wrapped in bacon and baked until caramelized and crispy.", "servings": 10, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"20\", \"name\": \"Medjool dates pitted\"}, {\"qty\": \"4 oz\", \"name\": \"goat cheese\"}, {\"qty\": \"10 slices\", \"name\": \"regular bacon halved crosswise\"}, {\"qty\": \"\", \"name\": \"black pepper to taste\"}]", "instructions": "1. Preheat oven to 400°F. Line a rimmed baking sheet with parchment paper. 2. Slice dates along one long side and remove pits. Open each date like a book. 3. Fill each date with about 1/2 teaspoon of goat cheese and press the sides closed. 4. Wrap each stuffed date with a half-slice of bacon, overlapping the ends. Secure with a toothpick. 5. Place wrapped dates in a single layer on the prepared baking sheet. 6. Bake 20 minutes until bacon is crispy, flipping halfway. Transfer to a platter, sprinkle with pepper, and serve immediately.", "tags": "finger-food, bacon, party", "source": "https://www.thekitchn.com/how-to-make-bacon-wrapped-dates-226082", "nutritionData": "{\"calories\": 270, \"protein\": 6.0, \"carbs\": 47.0, \"fat\": 6.0}"},
  {"name": "Loaded Potato Skins", "category": "Game Day", "description": "Crispy baked potato skins loaded with cheddar cheese, crispy bacon, sour cream, and green onions.", "servings": 8, "prepTime": 15, "cookTime": 90, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"large russet potatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"8 slices\", \"name\": \"bacon cooked and crumbled\"}, {\"qty\": \"2 cups\", \"name\": \"shredded sharp cheddar cheese\"}, {\"qty\": \"1/2 cup\", \"name\": \"sour cream\"}, {\"qty\": \"4\", \"name\": \"scallions thinly sliced\"}, {\"qty\": \"\", \"name\": \"hot sauce optional\"}]", "instructions": "1. Preheat oven to 400°F. Prick potatoes all over with a fork. Place directly on oven rack and bake 1 hour until soft when squeezed. Let cool slightly. 2. Halve potatoes lengthwise and scoop out flesh leaving a 1/4-inch border. Save flesh for another use. 3. Slice each half in half again to make 4 pieces per potato. Brush insides and outsides with olive oil. Season with salt and pepper. 4. Place on a baking sheet and bake at 450°F 20-25 minutes until edges are crispy and golden. 5. Remove and top each skin with cheddar cheese and crumbled bacon. Return to oven 3-5 minutes until cheese is bubbly. 6. Top with sour cream, scallions, and hot sauce. Serve immediately.", "tags": "finger-food, potato-skins, crowd-pleaser", "source": "https://www.thekitchn.com/loaded-potato-skins-recipe-23076582", "nutritionData": "{\"calories\": 290, \"protein\": 13.0, \"carbs\": 19.0, \"fat\": 17.0}"},
  {"name": "Fried Mozzarella Sticks", "category": "Game Day", "description": "Golden-fried mozzarella sticks with a crispy panko crust and gooey cheese interior — served with marinara.", "servings": 6, "prepTime": 30, "cookTime": 5, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"whole milk mozzarella block cut into 15 sticks\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1.5 cups\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"\", \"name\": \"vegetable oil for frying\"}, {\"qty\": \"1.5 cups\", \"name\": \"marinara sauce warmed for serving\"}]", "instructions": "1. Set up a dredging station: flour in one shallow bowl, beaten eggs in another, and panko mixed with Italian seasoning, garlic powder, parsley, pepper, and salt in a third. 2. Working one at a time, dredge each mozzarella stick in flour (shake off excess), dip in egg, then coat in panko. Repeat egg and panko steps for a second coat. 3. Place coated sticks on a baking sheet and freeze at least 1 hour. 4. Heat 3 inches of vegetable oil in a heavy pot to 350°F. 5. Fry in batches of 3-4 for about 1 minute until golden brown. Do not let cheese bubble and leak. 6. Drain on paper towels. Serve immediately with warm marinara sauce.", "tags": "finger-food, mozzarella-sticks, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 440, \"protein\": 19.0, \"carbs\": 26.0, \"fat\": 27.0}"},
  {"name": "Nachos Supreme", "category": "Game Day", "description": "Sheet-pan nachos layered with seasoned ground beef, refried beans, melted cheese, and all the toppings.", "servings": 8, "prepTime": 15, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"85/15 ground beef\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1 oz\", \"name\": \"taco seasoning packet\"}, {\"qty\": \"3/4 cup\", \"name\": \"water\"}, {\"qty\": \"12 oz\", \"name\": \"tortilla chips\"}, {\"qty\": \"1 can\", \"name\": \"15 oz refried beans\"}, {\"qty\": \"2 cups\", \"name\": \"shredded Mexican blend cheese\"}, {\"qty\": \"2\", \"name\": \"Roma tomatoes diced\"}, {\"qty\": \"4\", \"name\": \"scallions sliced\"}, {\"qty\": \"1 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1 cup\", \"name\": \"guacamole\"}, {\"qty\": \"1\", \"name\": \"jalape\\u00f1o sliced\"}, {\"qty\": \"1 can\", \"name\": \"sliced black olives drained\"}]", "instructions": "1. Preheat oven to 400°F. Line two baking sheets with parchment paper. 2. Brown ground beef and onion in a skillet over medium-high heat until cooked through, about 8 minutes. Drain. Stir in taco seasoning and water; simmer until thickened. 3. Spread tortilla chips in a single layer across the prepared baking sheets. 4. Spoon dollops of refried beans and seasoned ground beef over the chips. Sprinkle cheese over everything. 5. Bake 15 minutes until cheese is melted and chips begin to crisp. 6. Remove from oven and top with diced tomatoes, scallions, olives, jalapeños, sour cream, and guacamole. Serve immediately.", "tags": "nachos, party, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 650, \"protein\": 29.0, \"carbs\": 42.0, \"fat\": 40.0}"},
  {"name": "Shrimp Cocktail Platter", "category": "Game Day", "description": "Classic poached jumbo shrimp chilled over ice and served with homemade zesty cocktail sauce.", "servings": 8, "prepTime": 15, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"jumbo shrimp peeled deveined tails on\"}, {\"qty\": \"2\", \"name\": \"stalks celery\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"4 sprigs\", \"name\": \"parsley\"}, {\"qty\": \"1 tbsp\", \"name\": \"whole black peppercorns\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1\", \"name\": \"lemon halved\"}, {\"qty\": \"1 cup\", \"name\": \"ketchup\"}, {\"qty\": \"2 tbsp\", \"name\": \"prepared horseradish\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. Fill a medium saucepan 2/3 full with water. Add celery, salt, thyme, parsley, peppercorns, and bay leaves. Bring to a boil and simmer 10 minutes. 2. Prepare shrimp: peel and devein, leaving tails on. 3. Add shrimp and half the lemon to simmering water. Remove from heat immediately, cover, and let rest 3-4 minutes until pink and firm. 4. Fill a bowl with ice water. Transfer shrimp to ice bath until completely cooled, about 5 minutes. Drain. 5. Make cocktail sauce: whisk together ketchup, horseradish, Worcestershire, and lemon juice. Refrigerate 30 minutes. 6. Arrange shrimp around a bowl of cocktail sauce over crushed ice. Serve with lemon wedges.", "tags": "seafood, shrimp, crowd-pleaser", "source": "https://www.spendwithpennies.com/shrimp-cocktail/", "nutritionData": "{\"calories\": 140, \"protein\": 27.0, \"carbs\": 8.0, \"fat\": 1.0}"},
  {"name": "5-Alarm Competition Chili", "category": "Game Day", "description": "Rich Texas-style no-bean chili with three chiles, chunks of beef chuck, and layers of deep smoky heat.", "servings": 8, "prepTime": 30, "cookTime": 180, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"beef chuck coarsely ground or cubed\"}, {\"qty\": \"2\", \"name\": \"qts beef stock\"}, {\"qty\": \"18 oz\", \"name\": \"tomato paste\"}, {\"qty\": \"2\", \"name\": \"dried ancho chiles stemmed and torn\"}, {\"qty\": \"1\", \"name\": \"chipotle chile in adobo chopped\"}, {\"qty\": \"1\", \"name\": \"large onion diced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"chili powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tbsp\", \"name\": \"Mexican oregano\"}, {\"qty\": \"\", \"name\": \"1-3 tsp cayenne pepper to taste\"}, {\"qty\": \"2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"\", \"name\": \"shredded cheddar and sour cream for serving\"}]", "instructions": "1. Combine beef stock and tomato paste in a large Dutch oven. Whisk to combine. 2. Add chili powder, ancho chiles, chipotle, onion, garlic, cumin, oregano, cayenne, salt, and smoked paprika. Stir to combine. Add raw beef. 3. Cover and bring to medium heat, stirring occasionally. After about 1 hour the chili should reach a light simmer. 4. Turn off heat and allow to cool completely. Refrigerate overnight for best flavor development. 5. The next day, skim congealed fat off the top. Cover and warm over low heat 30 minutes. Raise heat to medium and simmer uncovered 1.5 hours until chili is reduced and thickened. 6. Taste and season with additional salt. Serve with shredded cheddar, sour cream, and cornbread.", "tags": "chili, competition-style, heartier", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 48.0, \"carbs\": 13.0, \"fat\": 30.0}"},
  {"name": "Frito Pie", "category": "Game Day", "description": "Texas-style Frito pie with zesty ground beef chili baked over corn chips with cheddar and all the fixings.", "servings": 8, "prepTime": 15, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"85/15 ground beef\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper diced\"}, {\"qty\": \"1 can\", \"name\": \"10 oz Rotel diced tomatoes with green chiles\"}, {\"qty\": \"1 can\", \"name\": \"15 oz enchilada sauce\"}, {\"qty\": \"2 cans\", \"name\": \"15 oz chili beans\"}, {\"qty\": \"1 cup\", \"name\": \"corn kernels\"}, {\"qty\": \"1 oz\", \"name\": \"packet taco seasoning\"}, {\"qty\": \"8 oz\", \"name\": \"Fritos corn chips\"}, {\"qty\": \"2 cups\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"\", \"name\": \"sour cream diced tomatoes and sliced jalape\\u00f1os for serving\"}]", "instructions": "1. Preheat oven to 400°F. Coat a 9x13-inch baking dish with cooking spray. 2. In a large skillet over medium-high heat, brown ground beef with onion and bell pepper until cooked through, about 8 minutes. Drain grease. 3. Stir in taco seasoning. Add Rotel tomatoes, enchilada sauce, chili beans, and corn. Bring to a simmer and cook 5 minutes. 4. Sprinkle half the Fritos in the bottom of the baking dish. Top with 1 cup cheddar, then pour meat mixture over everything. Top with remaining Fritos and cheddar. 5. Bake uncovered 10-15 minutes until cheese is melted and bubbly. 6. Serve topped with sour cream, diced tomatoes, and jalapeños.", "tags": "heartier, tex-mex, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 620, \"protein\": 35.0, \"carbs\": 52.0, \"fat\": 28.0}"},
  {"name": "Party-Sized Fudge Brownies", "category": "Game Day", "description": "Dense, fudgy 9x13 pan of scratch-made brownies loaded with chocolate chips — rich, shareable, and perfect for a crowd.", "servings": 24, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 sticks\", \"name\": \"1 cup unsalted butter\"}, {\"qty\": \"2 cups\", \"name\": \"granulated sugar\"}, {\"qty\": \"4\", \"name\": \"large eggs\"}, {\"qty\": \"2 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"3/4 cup\", \"name\": \"Dutch-process cocoa powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1.5 cups\", \"name\": \"semi-sweet chocolate chips divided\"}, {\"qty\": \"\", \"name\": \"flaky sea salt for topping\"}]", "instructions": "1. Preheat oven to 350°F. Grease a 9x13-inch baking pan and line with parchment paper, leaving an overhang for easy removal. 2. Melt butter in a medium saucepan over low heat. Remove from heat and stir in sugar until combined. 3. Beat in eggs one at a time, then stir in vanilla. 4. In a separate bowl, whisk together flour, cocoa powder, salt, and baking powder. Fold into wet ingredients until just combined. 5. Stir in 1 cup chocolate chips. Pour batter into prepared pan and spread evenly. Scatter remaining 1/2 cup chips on top. 6. Bake 28-32 minutes until a toothpick inserted in the center comes out with moist crumbs. Sprinkle with flaky salt. Cool completely before cutting into 24 squares.", "tags": "dessert, brownies, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 220, \"protein\": 3.0, \"carbs\": 30.0, \"fat\": 11.0}"},
  {"name": "Air Fryer Chicken Breast", "category": "Air Fryer", "description": "Juicy, perfectly seasoned boneless chicken breasts cooked to golden perfection in the air fryer.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"small boneless skinless chicken breasts about 6 oz each\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"3/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/8 tsp\", \"name\": \"cayenne pepper\"}]", "instructions": "1. Pound the thicker end of each chicken breast so they are an even thickness. 2. Rub chicken with olive oil on all sides. 3. Mix garlic powder, onion powder, paprika, parsley, salt, and cayenne; rub spice blend all over chicken. 4. Preheat air fryer to 380°F. 5. Place chicken in basket in a single layer and air fry 5 to 6 minutes per side, 10 to 12 minutes total, until internal temp reaches 165°F. 6. Rest 5 minutes before slicing and serving.", "tags": "high-protein, gluten-free, quick", "source": "https://www.skinnytaste.com/air-fryer-chicken-breast/", "nutritionData": "{\"calories\": 311, \"protein\": 53.0, \"carbs\": 0.0, \"fat\": 10.0}"},
  {"name": "Air Fryer Chicken Thighs", "category": "Air Fryer", "description": "Crispy-skinned bone-in chicken thighs seasoned with lemon and herbs, cooked in the air fryer.", "servings": 4, "prepTime": 10, "cookTime": 24, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"bone-in skin-on chicken thighs\"}, {\"qty\": \"1/2\", \"name\": \"lemon juiced\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sweet paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}]", "instructions": "1. Pat chicken thighs dry with paper towels. 2. Squeeze lemon juice over chicken and season with all spices; rub well on all sides. 3. Place chicken thighs skin-side down in air fryer basket. 4. Air fry at 400°F for 12 minutes. 5. Flip skin-side up and cook an additional 12 minutes until skin is crispy and internal temp reaches 165°F. 6. Rest 5 minutes before serving.", "tags": "high-protein, gluten-free, family-friendly", "source": "https://www.skinnytaste.com/air-fryer-chicken-thighs/", "nutritionData": "{\"calories\": 251, \"protein\": 31.0, \"carbs\": 0.0, \"fat\": 13.0}"},
  {"name": "Air Fryer Buffalo Chicken Wings", "category": "Air Fryer", "description": "Crispy air-fried chicken wings tossed in classic Frank's hot sauce and butter for the ultimate buffalo flavor.", "servings": 4, "prepTime": 10, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"chicken wingettes and drumettes\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"sweet paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"2 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"1/2 cup\", \"name\": \"Frank's RedHot sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"unsalted butter melted\"}]", "instructions": "1. Pat wings dry thoroughly with paper towels. 2. In a large bowl, combine salt, garlic powder, onion powder, paprika, oregano, and baking powder; toss wings to coat evenly. 3. Spray air fryer basket with oil and arrange wings in a single layer in batches. 4. Air fry at 400°F for 16 to 22 minutes, shaking basket halfway through, until golden and crispy. 5. While wings cook, warm hot sauce and stir in melted butter. 6. Toss cooked wings in buffalo sauce and serve immediately.", "tags": "high-protein, game-day, spicy", "source": "https://www.skinnytaste.com/air-fryer-chicken-wings/", "nutritionData": "{\"calories\": 541, \"protein\": 61.0, \"carbs\": 6.0, \"fat\": 33.0}"},
  {"name": "Air Fryer Garlic Parmesan Wings", "category": "Air Fryer", "description": "Crispy air-fried chicken wings coated in a savory garlic butter and Parmesan sauce.", "servings": 4, "prepTime": 10, "cookTime": 22, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"chicken wingettes and drumettes\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"baking powder\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley chopped\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}]", "instructions": "1. Pat wings completely dry with paper towels. 2. Toss wings with salt, pepper, garlic powder, and baking powder in a large bowl. 3. Arrange in a single layer in the air fryer basket; air fry at 400°F for 20 to 22 minutes, shaking basket halfway, until deeply golden. 4. Meanwhile, melt butter in a small saucepan over low heat; add minced garlic and cook 1 to 2 minutes until fragrant. 5. Remove from heat and stir in Parmesan and parsley. 6. Toss hot wings in garlic Parmesan sauce and serve immediately.", "tags": "high-protein, game-day, crowd-pleaser", "source": "Classic", "nutritionData": "{\"calories\": 563, \"protein\": 64.0, \"carbs\": 0.0, \"fat\": 38.0}"},
  {"name": "Air Fryer Buffalo Chicken Nuggets", "category": "Air Fryer", "description": "Bite-sized chicken chunks dipped in hot sauce and coated in panko, air fried to crispy perfection.", "servings": 4, "prepTime": 10, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"boneless skinless chicken breast cut into bite-size chunks\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/8 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"Frank's Hot Sauce\"}, {\"qty\": \"3/4 cup\", \"name\": \"seasoned panko breadcrumbs\"}, {\"qty\": \"\", \"name\": \"olive oil spray\"}]", "instructions": "1. Cut chicken into small bite-sized chunks; season with garlic powder, paprika, chili powder, and pepper. 2. Place panko in one shallow bowl and hot sauce in another. 3. Dip each chicken piece in hot sauce, then roll in panko to coat. 4. Place coated nuggets in air fryer basket in a single layer. 5. Spray generously with olive oil and air fry at 400°F for 4 minutes. 6. Flip, spray the other side, and cook 4 more minutes until golden and cooked through. 7. Serve with celery sticks and blue cheese dressing.", "tags": "high-protein, quick, spicy", "source": "https://www.skinnytaste.com/air-fryer-buffalo-chicken-nuggets/", "nutritionData": "{\"calories\": 279, \"protein\": 38.0, \"carbs\": 17.0, \"fat\": 5.0}"},
  {"name": "Air Fryer Breaded Pork Chops", "category": "Air Fryer", "description": "Thick pork chops dredged in seasoned panko breadcrumbs and air fried until golden and juicy.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless pork chops 3/4 inch thick\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"\", \"name\": \"cooking spray\"}]", "instructions": "1. Pat pork chops dry; season both sides with salt and pepper. 2. Set up a dredging station: flour in one dish, beaten eggs in another, and panko mixed with Parmesan, Italian seasoning, and paprika in a third. 3. Dredge each chop in flour, dip in egg, then firmly press into panko mixture. 4. Preheat air fryer to 400°F. 5. Spray both sides of breaded chops with cooking spray; place in basket in a single layer. 6. Cook 5 minutes, flip, spray again, and cook 4 to 5 more minutes until breading is golden and internal temp reaches 145°F. 7. Rest 5 minutes before serving.", "tags": "high-protein, crispy, family-friendly", "source": "https://www.spendwithpennies.com/crispy-air-fryer-pork-chops/", "nutritionData": "{\"calories\": 485, \"protein\": 46.0, \"carbs\": 28.0, \"fat\": 20.0}"},
  {"name": "Air Fryer Pork Tenderloin", "category": "Air Fryer", "description": "Herb-rubbed pork tenderloin cooked quickly in the air fryer until juicy and perfectly tender.", "servings": 4, "prepTime": 10, "cookTime": 17, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"pork tenderloin about 1.25 to 1.5 lbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}]", "instructions": "1. Remove silver skin from pork tenderloin using a sharp knife. 2. Brush pork with olive oil on all sides. 3. Combine salt, pepper, garlic powder, onion powder, paprika, and thyme; rub evenly over the tenderloin. 4. Preheat air fryer to 400°F. 5. Place tenderloin in the basket (cut in half if needed to fit) and cook 16 to 17 minutes until internal temp reaches 145°F. 6. Transfer to a plate and rest at least 5 minutes before slicing.", "tags": "high-protein, gluten-free, meal-prep", "source": "https://www.spendwithpennies.com/air-fryer-pork-tenderloin/", "nutritionData": "{\"calories\": 228, \"protein\": 36.0, \"carbs\": 0.0, \"fat\": 8.0}"},
  {"name": "Air Fryer Salmon with Honey Dijon Glaze", "category": "Air Fryer", "description": "Flaky salmon fillets brushed with a honey-Dijon glaze and air fried to golden perfection in minutes.", "servings": 2, "prepTime": 5, "cookTime": 9, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"salmon fillets about 6 oz each\"}, {\"qty\": \"1 pinch\", \"name\": \"kosher salt\"}, {\"qty\": \"1 pinch\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"honey\"}, {\"qty\": \"1 tbsp\", \"name\": \"Dijon mustard\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tbsp\", \"name\": \"low-sodium soy sauce\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}]", "instructions": "1. Pat salmon dry with paper towels; season lightly with salt and pepper. 2. In a small bowl, whisk together honey, Dijon, olive oil, soy sauce, and garlic powder. 3. Line air fryer basket with aluminum foil; preheat air fryer to 400°F for 3 minutes. 4. Spoon glaze generously over the top of each salmon fillet. 5. Place fillets in basket not touching; air fry 8 to 9 minutes for 1-inch thick fillets until salmon reaches 145°F and glaze is caramelized. 6. Serve immediately.", "tags": "high-protein, gluten-free, quick", "source": "https://www.wellplated.com/air-fryer-salmon/", "nutritionData": "{\"calories\": 420, \"protein\": 34.0, \"carbs\": 9.0, \"fat\": 26.0}"},
  {"name": "Air Fryer Seasoned Shrimp", "category": "Air Fryer", "description": "Plump jumbo shrimp seasoned with garlic and paprika, air fried in minutes for bowls, salads, or tacos.", "servings": 4, "prepTime": 5, "cookTime": 6, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.25 lbs\", \"name\": \"jumbo shrimp peeled and deveined\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"3/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"3/4 tsp\", \"name\": \"sweet paprika\"}, {\"qty\": \"3/4 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"lemon wedges for serving\"}]", "instructions": "1. In a bowl, whisk olive oil with garlic powder, paprika, parsley, and salt. 2. Add shrimp and toss to coat on all sides. 3. Arrange shrimp in a single layer in the air fryer basket without overlapping; work in batches if needed. 4. Air fry at 400°F for 5 to 6 minutes, shaking basket halfway through, until shrimp are pink and curled. 5. Serve immediately with lemon wedges.", "tags": "high-protein, gluten-free, quick", "source": "https://www.skinnytaste.com/perfect-air-fryer-shrimp/", "nutritionData": "{\"calories\": 202, \"protein\": 34.0, \"carbs\": 0.0, \"fat\": 7.0}"},
  {"name": "Air Fryer Garlic Butter Steak Bites", "category": "Air Fryer", "description": "Tender sirloin cubes seared in the air fryer and finished with garlic butter for a quick steakhouse treat.", "servings": 4, "prepTime": 10, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"sirloin steak cut into 1.5-inch cubes\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Pat steak cubes very dry; toss with olive oil, garlic powder, onion powder, paprika, salt, and pepper. 2. Preheat air fryer to 400°F for 3 minutes. 3. Arrange steak bites in a single layer in basket; do not crowd. 4. Air fry 6 to 8 minutes for medium, shaking halfway, until browned on the outside. 5. Meanwhile, melt butter in a small skillet over medium heat; add minced garlic and cook 1 minute until fragrant. 6. Toss hot steak bites with garlic butter and parsley; serve immediately.", "tags": "high-protein, gluten-free, keto", "source": "Classic", "nutritionData": "{\"calories\": 481, \"protein\": 43.0, \"carbs\": 0.0, \"fat\": 34.0}"},
  {"name": "Air Fryer Parmesan Brussels Sprouts", "category": "Air Fryer", "description": "Halved Brussels sprouts roasted until crispy in the air fryer, finished with Parmesan and breadcrumbs.", "servings": 4, "prepTime": 5, "cookTime": 16, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"Brussels sprouts trimmed and halved\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"extra-virgin olive oil\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"small garlic cloves minced\"}, {\"qty\": \"4 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1 tbsp\", \"name\": \"seasoned breadcrumbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1/8 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Toss Brussels sprouts with 1 tablespoon olive oil and salt in a large bowl. 2. Add sprouts to air fryer basket and air fry at 350°F for 14 minutes, shaking basket halfway through. 3. Meanwhile, combine Parmesan, breadcrumbs, garlic, parsley, pepper, and remaining 1/2 tablespoon oil in a small bowl. 4. Open basket and spread Parmesan mixture evenly over sprouts; spritz with olive oil spray. 5. Air fry at 350°F for 2 more minutes until topping is golden. 6. Serve immediately.", "tags": "vegetarian, gluten-free optional, low-calorie", "source": "https://www.skinnytaste.com/air-fryer-brussel-sprouts/", "nutritionData": "{\"calories\": 109, \"protein\": 5.0, \"carbs\": 8.0, \"fat\": 7.0}"},
  {"name": "Air Fryer Parmesan Green Beans", "category": "Air Fryer", "description": "Crisp-tender green beans air fried with olive oil and topped with golden Parmesan breadcrumbs.", "servings": 4, "prepTime": 5, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"fresh green beans rinsed and trimmed\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil divided\"}, {\"qty\": \"1/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"small garlic cloves minced\"}, {\"qty\": \"2.5 tbsp\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"seasoned breadcrumbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"sweet paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1/8 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Toss green beans with 2 teaspoons olive oil and salt until coated. 2. Add to air fryer basket and air fry at 375°F for 6 to 7 minutes, shaking halfway, until crisp-tender. 3. Combine Parmesan, breadcrumbs, garlic, paprika, parsley, and pepper with remaining oil in a small bowl. 4. Spread crumb mixture over green beans in basket; spritz with oil spray. 5. Air fry at 375°F for 2 more minutes until golden. 6. Transfer to a platter and serve hot.", "tags": "vegetarian, low-calorie, quick", "source": "https://www.skinnytaste.com/air-fryer-green-beans/", "nutritionData": "{\"calories\": 89, \"protein\": 4.0, \"carbs\": 9.0, \"fat\": 5.0}"},
  {"name": "Air Fryer Sweet Potato Fries", "category": "Air Fryer", "description": "Lightly seasoned sweet potato fries that come out crispy on the outside and tender inside from the air fryer.", "servings": 4, "prepTime": 10, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large sweet potatoes peeled and cut into 1/4-inch fries\"}, {\"qty\": \"1.5 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"pinch of cayenne\"}]", "instructions": "1. Peel and cut sweet potatoes into even 1/4-inch thick fries; dry thoroughly with paper towels. 2. Toss fries with olive oil, salt, garlic powder, paprika, pepper, and cayenne until evenly coated. 3. Preheat air fryer to 380°F. 4. Arrange fries in a single layer in basket; do not overcrowd (cook in batches). 5. Air fry 10 minutes, then shake basket and cook 7 to 8 more minutes until edges are crispy. 6. Serve immediately with dipping sauce of choice.", "tags": "vegan, gluten-free, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 132, \"protein\": 2.0, \"carbs\": 20.0, \"fat\": 5.0}"},
  {"name": "Air Fryer French Fries", "category": "Air Fryer", "description": "Classic golden french fries made from fresh russet potatoes, soaked and air fried to crispy perfection.", "servings": 4, "prepTime": 15, "cookTime": 18, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"large russet potatoes peeled and cut into 1/4-inch fries\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"seasoned salt\"}]", "instructions": "1. Cut potatoes into 1/4-inch fries; place in a large bowl of cold water and soak 30 minutes. 2. Drain well and pat very dry with a clean kitchen towel. 3. Toss fries with olive oil, garlic powder, and seasoned salt. 4. Preheat air fryer to 390°F. 5. Place fries in basket in a single layer and cook 10 minutes; shake basket and cook another 6 to 8 minutes until golden and crispy. 6. Add additional salt to taste and serve immediately.", "tags": "vegan, gluten-free, vegetarian", "source": "https://www.spendwithpennies.com/crispy-air-fryer-french-fries/", "nutritionData": "{\"calories\": 146, \"protein\": 3.0, \"carbs\": 26.0, \"fat\": 4.0}"},
  {"name": "Air Fryer Breakfast Home Fries", "category": "Air Fryer", "description": "Seasoned diced russet potatoes cooked in the air fryer until golden brown and crispy for the perfect breakfast side.", "servings": 4, "prepTime": 10, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3\", \"name\": \"medium russet potatoes cut into 1/2-inch cubes\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat air fryer to 400°F. 2. Toss diced potatoes with olive oil, paprika, salt, garlic powder, onion powder, thyme, and pepper in a large bowl. 3. Lightly spray air fryer basket with nonstick cooking spray. 4. Add seasoned potatoes in a single layer; do not overcrowd. 5. Cook 15 minutes, shaking basket every 5 minutes for even browning. 6. Remove when golden brown and crispy; serve immediately.", "tags": "vegan, gluten-free, vegetarian", "source": "https://www.thecountrycook.net/air-fryer-home-fries/", "nutritionData": "{\"calories\": 146, \"protein\": 3.0, \"carbs\": 26.0, \"fat\": 4.0}"},
  {"name": "Air Fryer Bacon", "category": "Air Fryer", "description": "Perfectly crispy twisted bacon strips cooked in the air fryer with no grease splatter and easy cleanup.", "servings": 4, "prepTime": 2, "cookTime": 8, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"center-cut bacon\"}, {\"qty\": \"\", \"name\": \"salt and pepper to taste\"}]", "instructions": "1. Preheat air fryer to 350°F. 2. Take each bacon strip and twist into a tight rope shape. 3. Lay twisted bacon in the air fryer basket without strips touching; work in batches as needed. 4. Season lightly with salt and pepper if desired. 5. Air fry 6 to 10 minutes depending on thickness and desired crispness. 6. Use tongs to transfer to a paper towel-lined plate to drain; serve immediately.", "tags": "gluten-free, keto, breakfast", "source": "https://www.thecountrycook.net/air-fryer-twisted-bacon/", "nutritionData": "{\"calories\": 126, \"protein\": 9.0, \"carbs\": 0.0, \"fat\": 10.0}"},
  {"name": "Air Fryer Egg Cups", "category": "Air Fryer", "description": "Individual egg cups loaded with vegetables and cheese, air fried in silicone molds for an easy protein-packed breakfast.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/2 cup\", \"name\": \"baby spinach chopped\"}, {\"qty\": \"1/4 cup\", \"name\": \"red bell pepper diced\"}, {\"qty\": \"1/4 cup\", \"name\": \"cherry tomatoes halved\"}, {\"qty\": \"1/4 cup\", \"name\": \"shredded cheddar cheese\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Preheat air fryer to 300°F. 2. Whisk eggs and milk together in a large bowl; season with garlic powder, salt, and pepper. 3. Stir in spinach, bell pepper, tomatoes, and half the cheddar. 4. Spray 4 silicone egg molds or ramekins with cooking spray; fill each about 3/4 full with egg mixture. 5. Top each with remaining cheese; place molds in air fryer basket. 6. Air fry 10 to 12 minutes until eggs are fully set and tops are lightly golden. 7. Cool briefly in molds before unmolding and serving.", "tags": "vegetarian, high-protein, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 152, \"protein\": 12.0, \"carbs\": 3.0, \"fat\": 10.0}"},
  {"name": "Air Fryer Crispy Garlic Rosemary Chickpeas", "category": "Air Fryer", "description": "Canned chickpeas tossed with olive oil and herbs then air fried until irresistibly crunchy as a healthy snack.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cans\", \"name\": \"15 oz each chickpeas drained and rinsed\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1/8 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}]", "instructions": "1. Drain and rinse chickpeas; pat very dry with paper towels. 2. In a bowl, toss chickpeas with olive oil, salt, garlic powder, and rosemary until evenly coated. 3. Preheat air fryer to 400°F. 4. Spread chickpeas in air fryer basket in a single layer. 5. Cook 15 minutes, stirring halfway through, until chickpeas are golden and crispy. 6. Allow to cool completely before serving or storing in an airtight container.", "tags": "vegan, gluten-free, high-fiber", "source": "https://airfryereats.com/air-fryer-chickpeas-garlic-rosemary/", "nutritionData": "{\"calories\": 228, \"protein\": 10.0, \"carbs\": 33.0, \"fat\": 7.0}"},
  {"name": "Air Fryer Mozzarella Sticks", "category": "Air Fryer", "description": "Classic mozzarella sticks double-coated in panko and frozen before air frying to prevent cheese from leaking.", "servings": 4, "prepTime": 40, "cookTime": 6, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"8\", \"name\": \"mozzarella string cheese sticks\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 tbsp\", \"name\": \"water\"}, {\"qty\": \"1/3 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"nonstick cooking spray\"}]", "instructions": "1. Beat eggs and water in a shallow bowl; place flour in a second bowl; mix panko, garlic powder, Italian seasoning, salt, and pepper in a third. 2. Halve mozzarella sticks lengthwise; coat in flour, dip in egg, roll in panko pressing to adhere. 3. Dip again in egg and roll again in panko for a double coat; arrange on parchment-lined baking sheet. 4. Freeze for at least 30 minutes (do not skip this step). 5. Preheat air fryer to 390°F; spray basket and all sides of frozen sticks with cooking spray. 6. Air fry 4 to 7 minutes in batches until crispy and golden; serve immediately with marinara sauce.", "tags": "vegetarian, appetizer, crowd-pleaser", "source": "https://www.thecountrycook.net/air-fryer-mozzarella-sticks/", "nutritionData": "{\"calories\": 341, \"protein\": 19.0, \"carbs\": 30.0, \"fat\": 14.0}"},
  {"name": "Air Fryer Jalapeño Poppers", "category": "Air Fryer", "description": "Cream cheese-stuffed jalapeño halves topped with shredded cheese and crispy bacon, air fried until bubbly.", "servings": 4, "prepTime": 15, "cookTime": 9, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large jalape\\u00f1os\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"8 oz\", \"name\": \"block cream cheese softened\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 cup\", \"name\": \"shredded Colby Jack cheese divided\"}, {\"qty\": \"4\", \"name\": \"strips bacon cooked and crumbled\"}, {\"qty\": \"3 tbsp\", \"name\": \"sliced green onions\"}]", "instructions": "1. Slice jalapeños lengthwise and remove seeds and veins; brush with olive oil. 2. Air fry jalapeño halves at 400°F for 4 minutes; let cool 5 minutes and drain upside down on paper towels. 3. Beat cream cheese with garlic powder, salt, and pepper until smooth. 4. Stir in 1/2 cup Colby Jack, most of the bacon, and green onions. 5. Fill each jalapeño half with cream cheese mixture; top with remaining cheese and reserved bacon. 6. Air fry at 400°F for 5 minutes until cheese is melted and bubbly; serve hot.", "tags": "keto, gluten-free, appetizer", "source": "https://www.thecountrycook.net/air-fryer-jalapeno-poppers/", "nutritionData": "{\"calories\": 336, \"protein\": 10.0, \"carbs\": 3.0, \"fat\": 32.0}"},
  {"name": "Air Fryer Onion Rings", "category": "Air Fryer", "description": "Thick-cut onion rings dredged in seasoned panko and air fried until shatteringly crispy without deep frying.", "servings": 4, "prepTime": 15, "cookTime": 12, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large yellow onions cut into 1/2-inch rings\"}, {\"qty\": \"1/2 cup\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"2/3 cup\", \"name\": \"buttermilk\"}, {\"qty\": \"2 cups\", \"name\": \"panko breadcrumbs\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"\", \"name\": \"cooking spray\"}]", "instructions": "1. Separate onion rings and set aside. 2. In a bowl, whisk flour, paprika, garlic powder, and salt. 3. In another bowl, whisk eggs and buttermilk together. 4. In a third bowl, combine panko with olive oil. 5. Dredge each ring in flour, dip in egg-buttermilk mixture, then press into panko to coat; place on a baking sheet. 6. Spray air fryer basket; arrange rings in a single layer. 7. Air fry at 350°F for 6 minutes, flip, spray again, and cook 5 to 6 more minutes until golden brown. 8. Serve immediately with dipping sauce.", "tags": "vegetarian, appetizer, crispy", "source": "https://www.spendwithpennies.com/air-fryer-onion-rings/", "nutritionData": "{\"calories\": 428, \"protein\": 13.0, \"carbs\": 62.0, \"fat\": 14.0}"},
  {"name": "Air Fryer Pork Egg Rolls", "category": "Air Fryer", "description": "Crispy egg rolls stuffed with seasoned ground pork and coleslaw mix, air fried instead of deep fried.", "servings": 4, "prepTime": 15, "cookTime": 11, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1/2 lb\", \"name\": \"ground pork\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"3 cups\", \"name\": \"coleslaw mix\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"3\", \"name\": \"green onions sliced\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"8\", \"name\": \"egg roll wrappers\"}, {\"qty\": \"\", \"name\": \"vegetable oil or cooking spray\"}]", "instructions": "1. Cook ground pork in a skillet over medium heat until no pink remains; drain fat. 2. Add garlic and ginger; cook 1 minute. Add coleslaw mix and cook 5 to 6 minutes until tender. 3. Stir in soy sauce and green onions; cool slightly. 4. Mix flour with just enough water to make a paste. 5. Lay out egg roll wrappers; place 1/3 cup filling in center of each. 6. Fold diagonally, tuck sides in, roll up and seal tip with flour paste. 7. Brush outside of each egg roll with oil; place in air fryer basket 3 to 4 at a time. 8. Air fry at 390°F for 8 minutes, flip, cook 3 more minutes until golden and crispy.", "tags": "appetizer, asian-inspired, family-friendly", "source": "https://www.spendwithpennies.com/air-fryer-egg-rolls/", "nutritionData": "{\"calories\": 374, \"protein\": 22.0, \"carbs\": 47.0, \"fat\": 12.0}"},
  {"name": "Air Fryer Falafel", "category": "Air Fryer", "description": "Classic herb-packed chickpea falafel balls air fried until golden and crispy without deep frying.", "servings": 4, "prepTime": 30, "cookTime": 18, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"12 oz\", \"name\": \"dried chickpeas soaked overnight\"}, {\"qty\": \"2\", \"name\": \"shallots diced\"}, {\"qty\": \"1 cup\", \"name\": \"fresh parsley tightly packed\"}, {\"qty\": \"1 cup\", \"name\": \"fresh cilantro tightly packed\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 tsp\", \"name\": \"cumin\"}, {\"qty\": \"2 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"lemon juice\"}, {\"qty\": \"3 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"\", \"name\": \"cooking spray\"}]", "instructions": "1. Soak dried chickpeas in water overnight; drain well (do not use canned). 2. Combine soaked chickpeas, shallots, parsley, cilantro, garlic, spices, lemon juice, and flour in food processor. 3. Pulse until coarse and well combined but not completely smooth; refrigerate 30 minutes. 4. Shape mixture into 1-inch balls; spray air fryer basket with cooking spray. 5. Place falafel in basket in a single layer with space between each; spray tops with oil. 6. Air fry at 350°F for 15 to 18 minutes, turning halfway through, until golden and crispy. 7. Serve immediately in pita with tahini sauce.", "tags": "vegan, high-fiber, middle-eastern", "source": "https://airfryereats.com/air-fryer-falafel/", "nutritionData": "{\"calories\": 328, \"protein\": 17.0, \"carbs\": 56.0, \"fat\": 5.0}"},
  {"name": "Air Fryer Samosas", "category": "Air Fryer", "description": "Flaky dough parcels stuffed with spiced potato and pea filling, air fried until golden and crispy.", "servings": 4, "prepTime": 40, "cookTime": 22, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"all-purpose flour\"}, {\"qty\": \"4 tbsp\", \"name\": \"vegetable oil divided\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt divided\"}, {\"qty\": \"1/2 cup\", \"name\": \"warm water\"}, {\"qty\": \"2\", \"name\": \"medium potatoes boiled and mashed\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas thawed\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"fresh ginger grated\"}, {\"qty\": \"1\", \"name\": \"green chile minced\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}]", "instructions": "1. Make dough: combine flour, 2 tbsp oil, and 1/4 tsp salt; gradually add warm water and knead until smooth. Rest covered 20 minutes. 2. Heat 2 tbsp oil in skillet; add cumin seeds. Once sizzling add ginger, chile, garam masala, coriander, and remaining salt; cook 30 seconds. 3. Add mashed potatoes and peas; cook 2 minutes. Stir in cilantro; cool. 4. Divide dough into 8 balls; roll each into a 6-inch disc and cut in half. 5. Fold each semicircle into a cone; fill with 2 tbsp potato filling; seal edges tightly. 6. Brush samosas with oil; place in air fryer basket. 7. Air fry at 375°F for 12 minutes; flip, brush again with oil, and cook 8 to 10 more minutes until golden. 8. Serve with chutney.", "tags": "vegan, indian-inspired, appetizer", "source": "https://spicecravings.com/air-fryer-samosa", "nutritionData": "{\"calories\": 428, \"protein\": 8.0, \"carbs\": 64.0, \"fat\": 15.0}"},
  {"name": "Air Fryer Korean Chicken Bites", "category": "Air Fryer", "description": "Crispy cornstarch-coated chicken thigh pieces air fried and tossed in a sticky gochujang glaze.", "servings": 4, "prepTime": 25, "cookTime": 15, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs cut into bite-size pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"rice vinegar\"}, {\"qty\": \"1 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"2 tsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"3/4 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs beaten\"}, {\"qty\": \"1 cup\", \"name\": \"cornstarch\"}, {\"qty\": \"\", \"name\": \"cooking oil spray\"}, {\"qty\": \"3 tbsp\", \"name\": \"ketchup\"}, {\"qty\": \"3 tbsp\", \"name\": \"gochujang\"}, {\"qty\": \"3 tbsp\", \"name\": \"honey\"}, {\"qty\": \"2 tbsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1 tbsp\", \"name\": \"sesame oil\"}, {\"qty\": \"2\", \"name\": \"garlic cloves minced\"}, {\"qty\": \"4\", \"name\": \"scallions sliced\"}, {\"qty\": \"\", \"name\": \"toasted sesame seeds\"}]", "instructions": "1. Toss chicken with vinegar, 1 tbsp soy sauce, ginger, and salt; marinate 15 to 20 minutes. 2. Set up two bowls: beaten eggs and cornstarch; dip each piece in egg then cornstarch. 3. Line air fryer basket with parchment; arrange coated chicken in single layer; spray with oil. 4. Air fry at 400°F for 8 minutes; flip, spray with more oil, cook 7 more minutes until crispy. 5. Make sauce: stir together ketchup, gochujang, honey, 2 tbsp soy sauce, sesame oil, and garlic. 6. Toss hot chicken in sauce; garnish with scallions and sesame seeds; serve immediately.", "tags": "high-protein, asian-inspired, spicy", "source": "https://allwaysdelicious.com/air-fryer-korean-fried-chicken/", "nutritionData": "{\"calories\": 626, \"protein\": 47.0, \"carbs\": 49.0, \"fat\": 25.0}"},
  {"name": "Air Fryer Beef Burgers", "category": "Air Fryer", "description": "Juicy seasoned 80/20 ground beef patties cooked in the air fryer in under 15 minutes.", "servings": 4, "prepTime": 10, "cookTime": 10, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"lean ground beef 80/20\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"4\", \"name\": \"hamburger buns\"}, {\"qty\": \"\", \"name\": \"lettuce tomato onion for serving\"}, {\"qty\": \"4 slices\", \"name\": \"cheddar cheese optional\"}]", "instructions": "1. Combine ground beef, salt, pepper, onion powder, and garlic powder in a bowl; mix gently. 2. Form into 4 patties about 1/2-inch thick; make a small indent in the center of each. 3. Preheat air fryer to 370°F. 4. Add patties in a single layer to the basket; cook 6 minutes. 5. Flip and cook 3 to 5 more minutes until beef reaches 160°F. 6. Add cheese if using; cook 1 more minute until melted. 7. Serve on buns with desired toppings.", "tags": "high-protein, family-friendly, quick", "source": "https://www.spendwithpennies.com/air-fryer-hamburgers/", "nutritionData": "{\"calories\": 517, \"protein\": 41.0, \"carbs\": 22.0, \"fat\": 31.0}"},
  {"name": "Air Fryer Turkey Burgers", "category": "Air Fryer", "description": "Moist and flavorful turkey burgers with soy sauce and breadcrumbs, air fried until juicy and brown.", "servings": 4, "prepTime": 40, "cookTime": 14, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"ground turkey not extra lean\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1\", \"name\": \"egg yolk\"}, {\"qty\": \"2 tbsp\", \"name\": \"seasoned breadcrumbs\"}, {\"qty\": \"1 tsp\", \"name\": \"soy sauce\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"\", \"name\": \"salt and black pepper to taste\"}, {\"qty\": \"4\", \"name\": \"hamburger buns\"}, {\"qty\": \"\", \"name\": \"lettuce and tomato for serving\"}]", "instructions": "1. Gently mix all ingredients in a bowl until just combined. 2. Form into 4 patties 1/2-inch thick; make a small indent in center of each. 3. Refrigerate patties 30 minutes to help them hold together. 4. Preheat air fryer to 350°F. 5. Place patties in a single layer in the basket; cook 6 minutes. 6. Flip and cook 6 to 8 more minutes until internal temp reaches 165°F. 7. Serve on buns with desired toppings.", "tags": "high-protein, family-friendly, leaner", "source": "https://www.spendwithpennies.com/air-fryer-turkey-burgers/", "nutritionData": "{\"calories\": 358, \"protein\": 29.0, \"carbs\": 25.0, \"fat\": 17.0}"},
  {"name": "Air Fryer Crispy Hash Browns", "category": "Air Fryer", "description": "Frozen shredded hash browns tossed with oil and air fried until deeply golden and crispy on the outside.", "servings": 4, "prepTime": 2, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"frozen shredded hash browns do not thaw\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Add frozen hash browns to a large bowl; break up any large clumps. 2. Drizzle oil over hash browns; toss to coat evenly; season with salt and pepper. 3. Spread hash browns into air fryer basket in an even layer. 4. Air fry at 380°F for 15 minutes; flip with a spatula and cook an additional 3 to 5 minutes until golden and crispy. 5. Serve immediately.", "tags": "vegetarian, gluten-free, breakfast", "source": "https://airfryereats.com/air-fryer-hash-browns/", "nutritionData": "{\"calories\": 132, \"protein\": 2.0, \"carbs\": 20.0, \"fat\": 7.0}"},
  {"name": "Air Fryer Brown Sugar Rubbed Pork Chops", "category": "Air Fryer", "description": "Boneless pork chops coated in a sweet and savory brown sugar spice rub and air fried to juicy perfection.", "servings": 4, "prepTime": 10, "cookTime": 12, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"4\", \"name\": \"boneless pork chops 3/4 inch thick\"}, {\"qty\": \"2 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}]", "instructions": "1. Preheat air fryer to 400°F. 2. In a small bowl, combine brown sugar, chili powder, garlic powder, black pepper, and salt. 3. Using a sharp knife, cut a few slits in the fat cap on the sides of each chop to prevent curling. 4. Massage rub into both sides of the pork chops. 5. Place chops in a single layer in the basket; cook 12 minutes, flipping after 6 minutes, until internal temp reaches 145°F. 6. Transfer to a plate; rest 5 minutes before serving.", "tags": "high-protein, gluten-free, quick", "source": "https://www.spendwithpennies.com/air-fryer-pork-chops/", "nutritionData": "{\"calories\": 316, \"protein\": 38.0, \"carbs\": 6.0, \"fat\": 15.0}"},
  {"name": "Air Fryer Roasted Cauliflower", "category": "Air Fryer", "description": "Cauliflower florets seasoned with smoked paprika and garlic, air fried until caramelized and tender.", "servings": 4, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"medium head cauliflower cut into florets\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"salt\"}, {\"qty\": \"1/4 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"grated Parmesan cheese optional\"}, {\"qty\": \"\", \"name\": \"fresh parsley for garnish\"}]", "instructions": "1. Cut cauliflower into even florets; pat dry with paper towels. 2. Toss florets with olive oil, smoked paprika, garlic powder, onion powder, salt, and pepper in a large bowl. 3. Preheat air fryer to 390°F. 4. Add florets in a single layer to the basket; cook 8 minutes. 5. Shake basket and cook 6 to 7 more minutes until edges are caramelized and tender. 6. Sprinkle with Parmesan if using and garnish with parsley; serve immediately.", "tags": "vegan, gluten-free, vegetarian", "source": "Classic", "nutritionData": "{\"calories\": 84, \"protein\": 2.0, \"carbs\": 2.0, \"fat\": 8.0}"},
  {"name": "Instant Pot Chicken Noodle Soup", "category": "Instant Pot", "description": "Classic chicken noodle soup made fast in the pressure cooker with tender chicken and egg noodles.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken breast\"}, {\"qty\": \"3\", \"name\": \"medium carrots sliced\"}, {\"qty\": \"3\", \"name\": \"stalks celery sliced\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 cups\", \"name\": \"egg noodles\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"dried parsley\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Set Instant Pot to Saute (High). Heat olive oil and saute onion and celery for 3 minutes until softened. Add garlic and cook 1 minute more. 2. Add carrots, chicken broth, thyme, bay leaf, salt, and pepper. Nestle chicken breasts into the broth. 3. Seal lid and cook on High Pressure for 10 minutes. Allow natural pressure release for 5 minutes, then quick release remaining pressure. 4. Remove chicken breasts and shred with two forks. Discard bay leaf. 5. Set pot to Saute. Add egg noodles and cook 6-8 minutes until tender. Return shredded chicken to pot. 6. Taste and adjust seasoning. Ladle into bowls and garnish with fresh parsley.", "tags": "soup, comfort-food, make-ahead, pressure-cooker", "source": "https://www.pressurecookingtoday.com/pressure-cooker-chicken-noodle-soup/", "nutritionData": "{\"calories\": 370, \"protein\": 40.0, \"carbs\": 28.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Beef Stew", "category": "Instant Pot", "description": "Hearty pressure-cooked beef stew with tender chuck roast, potatoes, and carrots in rich broth.", "servings": 6, "prepTime": 15, "cookTime": 55, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"2.5 lbs\", \"name\": \"boneless chuck roast cut into 1.5-inch cubes\"}, {\"qty\": \"1.5 cups\", \"name\": \"Yukon gold potatoes cubed\"}, {\"qty\": \"1.5 cups\", \"name\": \"carrots sliced\"}, {\"qty\": \"1 cup\", \"name\": \"celery chopped\"}, {\"qty\": \"1\", \"name\": \"medium yellow onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2 cups\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"3 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}]", "instructions": "1. Season beef cubes with salt and pepper. Set Instant Pot to Saute (High). Heat 1 tbsp oil and sear beef in batches until browned on all sides, about 4 minutes per batch. Remove beef and set aside. 2. Add remaining oil and saute onion until softened, about 3 minutes. Add garlic and cook 30 seconds. Stir in broth and scrape up browned bits from bottom of pot to deglaze. 3. Add tomato paste, Worcestershire sauce, thyme, and bay leaf. Return browned beef to pot. Add carrots, potatoes, and celery on top. Do not stir. 4. Seal lid and cook on High Pressure for 35 minutes. Natural pressure release for 10 minutes, then quick release remaining. 5. Remove thyme and bay leaf. Whisk cornstarch with 2 tbsp cold water to make a slurry. Set pot to Saute. Stir slurry into stew and simmer 2 minutes until thickened. Add peas and stir. 6. Serve hot.", "tags": "stew, comfort-food, meal-prep, pressure-cooker", "source": "https://www.wellplated.com/instant-pot-beef-stew/", "nutritionData": "{\"calories\": 610, \"protein\": 51.0, \"carbs\": 12.0, \"fat\": 34.0}"},
  {"name": "Instant Pot Chili", "category": "Instant Pot", "description": "Award-winning ground beef chili pressure-cooked in 15 minutes with kidney beans and crushed tomatoes.", "servings": 8, "prepTime": 10, "cookTime": 35, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"ground beef 85/15\"}, {\"qty\": \"1\", \"name\": \"small yellow onion minced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"2\", \"name\": \"(15 oz) cans kidney beans drained and rinsed\"}, {\"qty\": \"28 oz\", \"name\": \"crushed tomatoes\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"light lager beer or additional broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"chili seasoning blend\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Set Instant Pot to Saute (High). Add ground beef and onion; brown meat breaking it up, about 5 minutes. Add garlic and cook 1 minute. Drain excess grease. 2. Pour in beer (or broth) and scrape up any browned bits from bottom of pot. Cook 2 minutes. Hit Cancel to stop Saute. 3. Add beef broth, chili seasoning, kidney beans, and Worcestershire sauce. Stir well. Place crushed tomatoes on top without stirring. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 15 minutes. 5. Allow natural pressure release for at least 15 minutes, then release any remaining pressure. 6. Stir chili and serve with desired toppings such as shredded cheddar, sour cream, and scallions.", "tags": "chili, ground-beef, meal-prep, pressure-cooker", "source": "https://amindfullmom.com/instant-pot-chili/", "nutritionData": "{\"calories\": 380, \"protein\": 36.0, \"carbs\": 18.0, \"fat\": 20.0}"},
  {"name": "Instant Pot Lentil Soup", "category": "Instant Pot", "description": "Nourishing red lentil soup with cumin, carrots, and a squeeze of lemon, cooked in under 30 minutes.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"red lentils rinsed\"}, {\"qty\": \"2\", \"name\": \"medium carrots diced\"}, {\"qty\": \"2\", \"name\": \"stalks celery diced\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"6 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1\", \"name\": \"(14 oz) can diced tomatoes\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1.5 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh parsley chopped\"}]", "instructions": "1. Set Instant Pot to Saute (Medium). Heat olive oil and cook onion, carrots, and celery for 3 minutes. Add garlic, cumin, turmeric, and paprika; cook 1 minute until fragrant. 2. Add rinsed lentils, vegetable broth, diced tomatoes, salt, and pepper. Stir well. Hit Cancel. 3. Seal lid and set vent to Sealing. Cook on High Pressure for 10 minutes. Quick release the pressure. 4. Stir the soup; lentils will have broken down and thickened the broth naturally. 5. Stir in fresh lemon juice and taste for seasoning. 6. Ladle into bowls and garnish with fresh parsley. Serve with crusty bread.", "tags": "vegan, lentil, soup, high-protein, pressure-cooker", "source": "https://www.pressurecookingtoday.com/lentil-orzo-soup/", "nutritionData": "{\"calories\": 260, \"protein\": 13.0, \"carbs\": 35.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Split Pea Soup", "category": "Instant Pot", "description": "Thick and smoky split pea soup with ham, cooked under high pressure for a silky bowl of comfort.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"green split peas rinsed\"}, {\"qty\": \"8 oz\", \"name\": \"diced ham\"}, {\"qty\": \"1 cup\", \"name\": \"carrots diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"celery diced\"}, {\"qty\": \"1/2 cup\", \"name\": \"yellow onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"6 cups\", \"name\": \"chicken broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tbsp\", \"name\": \"Worcestershire sauce\"}, {\"qty\": \"6 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}]", "instructions": "1. Set Instant Pot to Saute. Heat olive oil and cook onion, celery, and carrots for 5 minutes until softened. Add garlic and cook 1 minute. 2. Add split peas, chicken broth, ham, Worcestershire sauce, thyme, bay leaf, salt, and pepper. Stir well. 3. Seal lid and set vent to Sealing. Cook on High Pressure for 15 minutes. Quick release the pressure when done. 4. Remove bay leaf and thyme sprigs. Stir soup vigorously — the split peas will dissolve into a thick creamy texture. 5. Taste and adjust salt and pepper as needed. 6. Serve hot. Soup will thicken further as it cools; add broth to thin if desired.", "tags": "soup, comfort-food, make-ahead, pressure-cooker", "source": "Classic", "nutritionData": "{\"calories\": 250, \"protein\": 18.0, \"carbs\": 32.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Pulled Pork", "category": "Instant Pot", "description": "Fall-apart tender pulled pork with a smoky spice rub, pressure-cooked in 60 minutes.", "servings": 8, "prepTime": 10, "cookTime": 75, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"boneless pork shoulder cut into large chunks\"}, {\"qty\": \"1 tbsp\", \"name\": \"brown sugar\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ancho chile powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/4 cup\", \"name\": \"water\"}, {\"qty\": \"1 cup\", \"name\": \"BBQ sauce for serving\"}]", "instructions": "1. In a large bowl, mix together brown sugar, garlic powder, onion powder, smoked paprika, cumin, salt, chile powder, and black pepper. 2. Add pork shoulder pieces and massage the spice rub all over the meat. Allow to marinate 15 minutes. 3. Place rubbed pork into the Instant Pot inner liner. Add 1/4 cup water. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 60 minutes. 5. Allow natural pressure release for 15 minutes, then quick release any remaining pressure. 6. Remove pork to a cutting board and shred with two forks. Return shredded pork to the cooking liquid. Serve with BBQ sauce on rolls or in tacos.", "tags": "pork, pressure-cooker, meal-prep, crowd-pleaser", "source": "https://twosleevers.com/mexican-pulled-pork/", "nutritionData": "{\"calories\": 405, \"protein\": 35.0, \"carbs\": 12.0, \"fat\": 24.0}"},
  {"name": "Instant Pot Pot Roast", "category": "Instant Pot", "description": "Classic pot roast with fork-tender chuck roast, potatoes, carrots, and rich pan gravy.", "servings": 6, "prepTime": 15, "cookTime": 80, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"chuck roast\"}, {\"qty\": \"2\", \"name\": \"medium yellow onions sliced into wedges\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1.5 lbs\", \"name\": \"baby potatoes halved\"}, {\"qty\": \"3\", \"name\": \"large carrots cut into 2-inch pieces\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"seasoned salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"dried thyme\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"2 tbsp\", \"name\": \"cornstarch\"}, {\"qty\": \"1 tsp\", \"name\": \"Worcestershire sauce\"}]", "instructions": "1. Combine salt, seasoned salt, pepper, rosemary, thyme, onion powder, and garlic powder. Rub all over the roast. 2. Set Instant Pot to Saute (High). Heat olive oil and sear roast 2 minutes per side. Remove and set aside. 3. Add butter and onions; stir constantly to deglaze the pot for 2 minutes. Add garlic, Worcestershire sauce, wine, and broth and scrape up any browned bits. 4. Place trivet in pot over onions with handles up. Set roast on trivet fat-side up. Wrap potatoes and carrots in separate foil pouches and place on top of roast. 5. Seal lid and cook on High Pressure for 60 minutes. Natural release 15 minutes, then quick release remaining. 6. Remove foil pouches and roast. Set Instant Pot to Saute. Whisk cornstarch with 2 tbsp water; stir into pot and simmer 1 minute until thickened. Slice roast and serve with gravy and vegetables.", "tags": "pot-roast, comfort-food, pressure-cooker, weekend-dinner", "source": "https://pressureluckcooking.com/instant-pot-roast/", "nutritionData": "{\"calories\": 680, \"protein\": 62.0, \"carbs\": 22.0, \"fat\": 40.0}"},
  {"name": "Instant Pot Pulled Chicken", "category": "Instant Pot", "description": "Juicy shredded chicken breast made in the Instant Pot in under 25 minutes, perfect for meal prep.", "servings": 4, "prepTime": 5, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"boneless skinless chicken breasts\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"2\", \"name\": \"stalks celery\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}]", "instructions": "1. Place chicken breasts in the Instant Pot. Add chicken broth, celery stalks, and bay leaves. 2. Sprinkle salt, pepper, garlic powder, onion powder, paprika, and oregano over the chicken. 3. Seal lid and set vent to Sealing. Cook on High Pressure for 10 minutes. Natural release for 8 minutes, then quick release remaining pressure. 4. Remove chicken to a cutting board. Discard celery and bay leaves. Reserve broth for soup or other uses. 5. Shred chicken with two forks or use a hand mixer for quick fine shredding. 6. Add a splash of reserved broth back to the chicken to keep it moist. Use in tacos, salads, sandwiches, or bowls.", "tags": "high-protein, meal-prep, low-carb, pressure-cooker", "source": "https://www.skinnytaste.com/instant-pot-shredded-chicken/", "nutritionData": "{\"calories\": 200, \"protein\": 38.0, \"carbs\": 2.0, \"fat\": 4.0}"},
  {"name": "Instant Pot Chicken Tikka Masala", "category": "Instant Pot", "description": "Tender chicken in a rich, spiced tomato-coconut sauce made fast in the pressure cooker.", "servings": 4, "prepTime": 10, "cookTime": 30, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 lbs\", \"name\": \"boneless skinless chicken thighs cut into bite-size pieces\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"1\", \"name\": \"(15 oz) can tomato sauce\"}, {\"qty\": \"1/2 cup\", \"name\": \"coconut milk full fat\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1.5 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"cardamom\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 cup\", \"name\": \"frozen peas\"}, {\"qty\": \"1/4 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for serving\"}]", "instructions": "1. Set Instant Pot to Saute. Melt butter, then add onion, garlic, ginger, and all spices (garam masala through cardamom). Cook 3 minutes until onion is softened and spices are fragrant. 2. Add tomato sauce and stir. Season chicken with 1 tsp salt and add to pot. Stir to combine. Sprinkle remaining salt. 3. Seal lid and set vent to Sealing. Cook on High Pressure for 15 minutes. Quick release the pressure. 4. Stir in coconut milk and frozen peas. Set pot to Saute and simmer 5 minutes to thicken sauce. 5. Turn pot off. Let cool 3 minutes, then stir in Greek yogurt. 6. Serve over basmati rice or with naan, garnished with fresh cilantro.", "tags": "Indian, chicken, pressure-cooker, gluten-free", "source": "https://www.skinnytaste.com/instant-pot-chicken-tikka-masala-with-cauliflower-and-peas/", "nutritionData": "{\"calories\": 460, \"protein\": 47.0, \"carbs\": 15.0, \"fat\": 26.0}"},
  {"name": "Instant Pot Dal Makhani", "category": "Instant Pot", "description": "Buttery, creamy black lentil dal cooked low and slow under high pressure, Instant Pot style.", "servings": 6, "prepTime": 10, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"whole black urad dal rinsed and drained\"}, {\"qty\": \"1/4 cup\", \"name\": \"rajma red kidney beans\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"3 cups\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/4 cup\", \"name\": \"plain Greek yogurt\"}, {\"qty\": \"1/4 cup\", \"name\": \"half and half or heavy cream\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh cilantro chopped\"}]", "instructions": "1. Wash the urad dal and rajma well. Add to Instant Pot along with bay leaves, garlic, ginger, and 3 cups water. 2. Seal lid and cook on High Pressure for 30 minutes. Allow natural pressure release for 10 minutes, then quick release remaining. 3. Using the back of a spoon, mash some of the dal to make it creamy while leaving most intact. 4. In a small saucepan, heat ghee. Add cumin seeds and let them sputter 30 seconds. Add tomato paste and cook until it absorbs the ghee, about 2 minutes. 5. Pour tomato-ghee mixture into the dal and mix well. Set pot to Saute and add a little water if needed for consistency. 6. Stir in yogurt and cream. Simmer 5 minutes on Saute. Garnish with cilantro and serve with naan or rice.", "tags": "Indian, vegan-adaptable, pressure-cooker, high-protein", "source": "https://twosleevers.com/pressure-cooker-dal-makhani-buttery-lentils/", "nutritionData": "{\"calories\": 220, \"protein\": 9.0, \"carbs\": 24.0, \"fat\": 9.0}"},
  {"name": "Instant Pot Chana Masala", "category": "Instant Pot", "description": "Spiced chickpea curry with tomatoes and aromatic spices, pressure-cooked for deep flavor.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"(15 oz) cans chickpeas drained\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"1\", \"name\": \"(14 oz) can diced tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"2 tbsp\", \"name\": \"coconut oil\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"1 tsp\", \"name\": \"fennel seeds\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1.5 tsp\", \"name\": \"ground coriander\"}, {\"qty\": \"1 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1\", \"name\": \"red chili minced\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}]", "instructions": "1. Set Instant Pot to Saute. Heat coconut oil, then add fennel seeds and cumin seeds. Cook 1-2 minutes until sizzling. 2. Add bay leaves and onion; cook 3 minutes until softened. Add garlic, ginger, and red chili; cook 1 minute until fragrant. 3. Stir in coriander, chili powder, and turmeric. Cook 1 minute. Add diced tomatoes, chickpeas, and water. Stir to combine. Hit Cancel. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 5 minutes. Quick release the pressure. 5. Remove lid and stir in fresh cilantro. Season to taste with salt. 6. Serve over basmati rice or with naan. Squeeze fresh lemon juice over top if desired.", "tags": "Indian, vegan, gluten-free, pressure-cooker", "source": "Classic", "nutritionData": "{\"calories\": 260, \"protein\": 10.0, \"carbs\": 33.0, \"fat\": 8.0}"},
  {"name": "Instant Pot Mac and Cheese", "category": "Instant Pot", "description": "Ultra-creamy homemade mac and cheese with three cheeses, cooked in the pressure cooker in minutes.", "servings": 6, "prepTime": 5, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"elbow macaroni\"}, {\"qty\": \"4 cups\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"paprika\"}, {\"qty\": \"2 cups\", \"name\": \"sharp cheddar cheese freshly grated\"}, {\"qty\": \"1 cup\", \"name\": \"Swiss cheese freshly grated\"}, {\"qty\": \"1/4 cup\", \"name\": \"Parmesan cheese grated\"}, {\"qty\": \"1/4 cup\", \"name\": \"whole milk\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}]", "instructions": "1. Add chicken broth, salt, garlic powder, onion powder, and paprika to Instant Pot. Stir to combine. Add elbow noodles and gently push down so they are submerged in the broth in an even layer. 2. Seal lid and set vent to Sealing. Cook on High Pressure for 3 minutes. 3. Allow natural pressure release for exactly 5 minutes, then quick release remaining pressure. 4. Open lid and stir to break up any clumped noodles. Stir in milk. 5. Add cheese in handfuls, stirring to melt after each addition. Fold in sour cream. 6. Stir until creamy and smooth. Adjust thickness with additional milk if needed. Serve immediately.", "tags": "pasta, comfort-food, kid-friendly, pressure-cooker", "source": "https://amindfullmom.com/instant-pot-mac-and-cheese/", "nutritionData": "{\"calories\": 540, \"protein\": 25.0, \"carbs\": 60.0, \"fat\": 18.0}"},
  {"name": "Instant Pot Spaghetti and Meatballs", "category": "Instant Pot", "description": "One-pot spaghetti and meatballs with marinara sauce, cooked under pressure in just 8 minutes.", "servings": 6, "prepTime": 10, "cookTime": 25, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"spaghetti broken in half\"}, {\"qty\": \"24 oz\", \"name\": \"marinara sauce divided\"}, {\"qty\": \"1.5 cups\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"1 lb\", \"name\": \"frozen or raw meatballs (about 20)\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1/2 cup\", \"name\": \"cherry tomatoes\"}, {\"qty\": \"1/2 cup\", \"name\": \"grated Parmesan cheese\"}, {\"qty\": \"2 oz\", \"name\": \"cream cheese or herb cheese\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}]", "instructions": "1. Set Instant Pot to Saute (High). Add olive oil and butter. Once melted, add shallots and garlic; saute 3 minutes. 2. Add meatballs, broth, 1.5 cups of the marinara sauce, and oregano. Stir well. 3. Break spaghetti in half and place in the pot in batches, smoothing with a spoon to submerge under the broth. DO NOT stir the spaghetti. Top with cherry tomatoes. 4. Seal lid and cook on High Pressure for 8 minutes. Quick release the pressure when done. 5. Stir the spaghetti to detach any clumped noodles. Add remaining 1.5 cups marinara, Parmesan, and cream cheese; stir until combined. 6. Allow to rest 5 minutes before serving so sauce thickens. Serve with additional Parmesan.", "tags": "pasta, Italian, comfort-food, pressure-cooker", "source": "https://pressureluckcooking.com/instant-pot-spaghetti-meatballs/", "nutritionData": "{\"calories\": 660, \"protein\": 29.0, \"carbs\": 79.0, \"fat\": 20.0}"},
  {"name": "Instant Pot Mushroom Risotto", "category": "Instant Pot", "description": "Creamy Arborio rice risotto with sauteed mushrooms and Parmesan, cooked under pressure in 6 minutes.", "servings": 4, "prepTime": 10, "cookTime": 20, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"8 oz\", \"name\": \"cremini mushrooms sliced\"}, {\"qty\": \"2\", \"name\": \"shallots minced\"}, {\"qty\": \"3 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"3.5 cups\", \"name\": \"vegetable broth\"}, {\"qty\": \"1/2 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"4 tbsp\", \"name\": \"butter divided\"}, {\"qty\": \"1 tbsp\", \"name\": \"vegetable oil\"}, {\"qty\": \"1/2 cup\", \"name\": \"Parmesan cheese grated\"}, {\"qty\": \"1 tsp\", \"name\": \"Italian seasoning\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1/2 tsp\", \"name\": \"seasoned salt\"}, {\"qty\": \"1 tsp\", \"name\": \"truffle oil optional\"}, {\"qty\": \"2 tbsp\", \"name\": \"dried parsley\"}]", "instructions": "1. Set Instant Pot to Saute (High). Add oil and 2 tbsp butter. Once melted, add shallots and cook 2 minutes. Add garlic and cook 1 minute. Add mushrooms and remaining butter; saute 3 minutes until browned. 2. Pour in white wine; let bubble 1 minute while scraping up any browned bits from bottom of pot. 3. Add Arborio rice and stir to coat for 1 minute. Add broth, seasoned salt, pepper, Italian seasoning, and parsley. Stir well, again deglazing the bottom. 4. Seal lid and cook on High Pressure for 6 minutes. Quick release the pressure. 5. Immediately stir everything together; the risotto will come to the right creamy consistency upon stirring. 6. Stir in Parmesan and truffle oil if using. Transfer to a serving dish and enjoy immediately.", "tags": "vegetarian, Italian, risotto, pressure-cooker", "source": "https://pressureluckcooking.com/instant-pot-mushroom-risotto/", "nutritionData": "{\"calories\": 480, \"protein\": 12.0, \"carbs\": 65.0, \"fat\": 15.0}"},
  {"name": "Instant Pot Chicken Biryani", "category": "Instant Pot", "description": "Fragrant layered chicken and basmati rice biryani cooked under pressure with whole spices.", "servings": 6, "prepTime": 30, "cookTime": 20, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"2 lbs\", \"name\": \"bone-in chicken thighs\"}, {\"qty\": \"2 cups\", \"name\": \"basmati rice rinsed and soaked 20 minutes\"}, {\"qty\": \"2\", \"name\": \"large onions thinly sliced\"}, {\"qty\": \"1 cup\", \"name\": \"plain whole-milk yogurt\"}, {\"qty\": \"2 tbsp\", \"name\": \"fresh ginger minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"garlic minced\"}, {\"qty\": \"2\", \"name\": \"jalapenos minced\"}, {\"qty\": \"2 tbsp\", \"name\": \"ghee\"}, {\"qty\": \"2 tsp\", \"name\": \"garam masala\"}, {\"qty\": \"1 tsp\", \"name\": \"turmeric\"}, {\"qty\": \"1 tsp\", \"name\": \"cumin seeds\"}, {\"qty\": \"4\", \"name\": \"green cardamom pods\"}, {\"qty\": \"2\", \"name\": \"cloves\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 cup\", \"name\": \"water\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh cilantro\"}, {\"qty\": \"1/4 cup\", \"name\": \"fresh mint leaves\"}]", "instructions": "1. Marinate chicken in yogurt, ginger, garlic, jalapenos, garam masala, turmeric, and salt for 20 minutes (or overnight for deeper flavor). 2. Set Instant Pot to Saute (High). Heat ghee; add cumin seeds, cardamom, cloves, and cinnamon stick until sizzling. Add sliced onions and cook, stirring, until well-browned and crisp at the edges, about 12 minutes. 3. Add garlic and jalapenos; cook 2 minutes. Add marinated chicken and yogurt marinade to the pot. Stir to combine. 4. Drain soaked basmati rice and carefully spread over the chicken in an even layer. Pour in 1 cup water and gently push rice to submerge. Sprinkle cilantro and mint on top. 5. Seal lid and cook on High Pressure for 5 minutes. Allow full natural pressure release (about 15 minutes). 6. Open pot and gently fluff rice from bottom. Garnish with additional cilantro. Serve with raita.", "tags": "Indian, rice, pressure-cooker, weekend-dinner", "source": "https://twosleevers.com/pressure-cooker-chicken-biryani/", "nutritionData": "{\"calories\": 510, \"protein\": 43.0, \"carbs\": 23.0, \"fat\": 27.0}"},
  {"name": "Instant Pot Hard Boiled Eggs 5-5-5", "category": "Instant Pot", "description": "Perfectly cooked hard boiled eggs using the foolproof 5-5-5 pressure cooker method for easy peeling.", "servings": 6, "prepTime": 1, "cookTime": 15, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"6\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"cold water\"}]", "instructions": "1. Pour 1 cup of water into the Instant Pot inner pot. Place the trivet (rack) in the bottom. 2. Set eggs on the trivet in a single layer. 3. Seal lid and set vent to Sealing. Cook on High Pressure for 5 minutes. 4. When cook time is done, allow natural pressure release for 5 minutes. Do not touch the pot. Then quick release any remaining pressure. 5. Immediately transfer eggs to an ice bath or run under cold water for at least 5 minutes until fully cooled. 6. Peel right away — eggs release cleanly from the shell. Store unpeeled eggs in refrigerator up to 1 week.", "tags": "eggs, quick, meal-prep, pressure-cooker", "source": "https://www.skinnytaste.com/how-to-make-perfect-eggs-in-the-instant-pot/", "nutritionData": "{\"calories\": 72, \"protein\": 6.0, \"carbs\": 0.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Black Beans From Dry", "category": "Instant Pot", "description": "Perfectly cooked black beans from dry in the Instant Pot with no soaking required.", "servings": 8, "prepTime": 5, "cookTime": 50, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 lb\", \"name\": \"dried black beans rinsed\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"1\", \"name\": \"green bell pepper diced\"}, {\"qty\": \"1\", \"name\": \"jalapeno minced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"5 cups\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"\", \"name\": \"fresh cilantro for serving\"}]", "instructions": "1. Rinse dried black beans and pick out any debris. Set Instant Pot to Saute. Heat olive oil and cook onion, bell pepper, and jalapeno 2 minutes. Add garlic; cook 1 minute. 2. Add cumin, oregano, and tomato paste; stir 1 minute to toast spices. Add bay leaves. Hit Cancel. 3. Add rinsed beans and water. Stir well. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 35 minutes. 5. Allow natural pressure release for 15 minutes. Slowly release any remaining pressure (beans may foam — release slowly). 6. Remove bay leaves. Add salt and stir. Roughly mash a portion of beans against the side for creamier texture. Garnish with cilantro and serve.", "tags": "vegan, beans, gluten-free, meal-prep, pressure-cooker", "source": "https://twosleevers.com/instant-pot-black-beans-and-rice/", "nutritionData": "{\"calories\": 230, \"protein\": 15.0, \"carbs\": 41.0, \"fat\": 2.0}"},
  {"name": "Instant Pot Cheesecake", "category": "Instant Pot", "description": "Silky New York-style cheesecake cooked in the Instant Pot water bath method for a perfect creamy texture.", "servings": 8, "prepTime": 20, "cookTime": 90, "difficulty": "Hard", "ingredientsJson": "[{\"qty\": \"16 oz\", \"name\": \"cream cheese at room temperature\"}, {\"qty\": \"2/3 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1/4 cup\", \"name\": \"sour cream\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"all-purpose flour\"}, {\"qty\": \"1 cup\", \"name\": \"graham cracker crumbs\"}, {\"qty\": \"3 tbsp\", \"name\": \"unsalted butter melted\"}, {\"qty\": \"2 cups\", \"name\": \"water for the pot\"}]", "instructions": "1. Grease a 6-inch springform pan and line the bottom with parchment paper. Mix graham cracker crumbs with melted butter; press firmly into bottom of pan. Freeze 10 minutes. 2. Using a hand or stand mixer, beat cream cheese and sugar until smooth and creamy. Add eggs one at a time, mixing well after each. Mix in sour cream, vanilla, and flour until no lumps remain. 3. Pour batter over frozen crust. Cover pan tightly with aluminum foil. 4. Add 2 cups water to Instant Pot. Place trivet with handles inside. Carefully lower springform pan onto trivet. 5. Seal lid and cook on High Pressure for 35 minutes. Allow full natural pressure release (about 15-20 minutes). 6. Remove foil and let cheesecake cool on counter for 1 hour. Refrigerate uncovered at least 4 hours or overnight before serving. Run knife along edges before releasing springform.", "tags": "dessert, cheesecake, pressure-cooker, make-ahead", "source": "https://www.pressurecookingtoday.com/making-perfect-pressure-cooker-cheesecake/", "nutritionData": "{\"calories\": 395, \"protein\": 5.0, \"carbs\": 30.0, \"fat\": 26.0}"},
  {"name": "Instant Pot Rice Pudding", "category": "Instant Pot", "description": "Creamy Arborio rice pudding with vanilla and cinnamon, cooked under pressure for a silky dessert.", "servings": 6, "prepTime": 5, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1.5 cups\", \"name\": \"Arborio rice\"}, {\"qty\": \"5 cups\", \"name\": \"whole milk\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"2\", \"name\": \"large eggs\"}, {\"qty\": \"1 cup\", \"name\": \"half and half\"}, {\"qty\": \"1.5 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1\", \"name\": \"cinnamon stick\"}, {\"qty\": \"1 cup\", \"name\": \"raisins optional\"}, {\"qty\": \"\", \"name\": \"ground cinnamon for serving\"}]", "instructions": "1. Combine Arborio rice, whole milk, sugar, and salt in the Instant Pot. Set pot to Saute and bring to a boil, stirring constantly to dissolve sugar. 2. Once mixture begins to boil, immediately seal lid. Cook on Low Pressure for 16 minutes. 3. While rice cooks, whisk eggs with half and half and vanilla extract in a bowl. 4. When cook time ends, turn pot off and wait 10 minutes before doing a quick pressure release. Carefully remove lid. Stir the rice. 5. Stir the egg mixture into the hot pudding. Set pot to Saute and cook, stirring, until pudding just begins to bubble, about 2 minutes. Turn off pot. Stir in raisins if using. 6. Serve warm or pour into dishes, cool to room temperature, then refrigerate. Dust with ground cinnamon before serving.", "tags": "dessert, rice-pudding, comfort-food, pressure-cooker", "source": "https://www.pressurecookingtoday.com/the-best-pressure-cooker-rice-pudding/", "nutritionData": "{\"calories\": 490, \"protein\": 13.0, \"carbs\": 77.0, \"fat\": 14.0}"},
  {"name": "Instant Pot Chicken Bone Broth", "category": "Instant Pot", "description": "Rich, collagen-packed chicken bone broth made hands-off in the Instant Pot in under 2 hours.", "servings": 8, "prepTime": 10, "cookTime": 120, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken carcass or 2 lbs chicken bones\"}, {\"qty\": \"1\", \"name\": \"carrot cut into quarters\"}, {\"qty\": \"2\", \"name\": \"large onions peeled and halved\"}, {\"qty\": \"2\", \"name\": \"stalks celery with leaves cut into quarters\"}, {\"qty\": \"\", \"name\": \"2-3 sprigs fresh thyme\"}, {\"qty\": \"1 tbsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"whole peppercorns\"}, {\"qty\": \"\", \"name\": \"2-3 bay leaves\"}, {\"qty\": \"10 cups\", \"name\": \"cold water\"}, {\"qty\": \"2 tbsp\", \"name\": \"apple cider vinegar\"}]", "instructions": "1. Place chicken bones, carrot, onion, celery, thyme, peppercorns, and bay leaves into the Instant Pot. 2. Pour apple cider vinegar over bones and let sit 10 minutes (helps draw minerals from bones). Pour in cold water up to two-thirds max fill line. 3. Seal lid and set vent to Sealing. For bone broth: Cook on High Pressure for 120 minutes. For lighter chicken stock: cook 45 minutes. 4. Allow natural pressure release for at least 30 minutes before quick releasing any remaining pressure. 5. Remove lid and carefully strain broth through a fine mesh strainer into a large bowl or pot, discarding all solids. 6. Cool broth and refrigerate overnight. Skim fat from surface before using. Store refrigerated up to 5 days or freeze up to 3 months.", "tags": "bone-broth, make-ahead, gluten-free, pressure-cooker", "source": "https://amindfullmom.com/instant-pot-chicken-stock/", "nutritionData": "{\"calories\": 40, \"protein\": 6.0, \"carbs\": 0.0, \"fat\": 1.0}"},
  {"name": "Instant Pot White Bean and Kale Soup", "category": "Instant Pot", "description": "Hearty Italian white bean and kale soup with garlic and herbs, cooked under pressure in minutes.", "servings": 6, "prepTime": 10, "cookTime": 20, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"(15 oz) cans great northern beans drained and rinsed\"}, {\"qty\": \"3 cups\", \"name\": \"packed lacinato kale chopped\"}, {\"qty\": \"2\", \"name\": \"medium Yukon gold potatoes cubed\"}, {\"qty\": \"2\", \"name\": \"medium carrots sliced\"}, {\"qty\": \"2\", \"name\": \"stalks celery minced\"}, {\"qty\": \"1\", \"name\": \"small yellow onion minced\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"6 cups\", \"name\": \"low-sodium vegetable broth\"}, {\"qty\": \"1/4 cup\", \"name\": \"dry white wine\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1/2 tsp\", \"name\": \"crushed red pepper flakes\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1\", \"name\": \"bay leaf\"}, {\"qty\": \"\", \"name\": \"Parmesan cheese for serving\"}]", "instructions": "1. Set Instant Pot to Saute. Heat olive oil and cook onion, celery, carrots, red pepper flakes, pepper, salt, and oregano for 3 minutes until onions begin to soften. Add garlic and cook 30-60 seconds. 2. Pour in white wine and scrape up any browned bits from the bottom of the pot. Cook 1-2 minutes then hit Cancel. 3. Add vegetable broth, cubed potatoes, drained beans, and bay leaf. Stir to combine. Push kale into liquid. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 5 minutes. Natural pressure release for 10 minutes, then quick release remaining. 5. Remove bay leaf. Stir everything together and taste for seasoning. 6. Ladle into bowls and top with grated Parmesan cheese if desired.", "tags": "vegan, soup, beans, pressure-cooker, make-ahead", "source": "https://amindfullmom.com/instant-pot-white-bean-and-kale-soup/", "nutritionData": "{\"calories\": 215, \"protein\": 10.0, \"carbs\": 32.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Beef Short Ribs", "category": "Instant Pot", "description": "Fall-off-the-bone beef short ribs braised in red wine and herbs under high pressure.", "servings": 4, "prepTime": 15, "cookTime": 70, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"bone-in beef short ribs\"}, {\"qty\": \"1\", \"name\": \"large onion sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"1 cup\", \"name\": \"dry red wine\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"2 tbsp\", \"name\": \"tomato paste\"}, {\"qty\": \"2 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"2 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2\", \"name\": \"medium carrots cut into chunks\"}, {\"qty\": \"2 tbsp\", \"name\": \"all-purpose flour for searing\"}, {\"qty\": \"1 tbsp\", \"name\": \"cornstarch for gravy\"}]", "instructions": "1. Pat short ribs dry, season generously with salt and pepper, and dust lightly with flour. 2. Set Instant Pot to Saute (High). Heat olive oil and sear ribs in batches on all sides until browned, about 3 minutes per side. Remove and set aside. 3. Add onion and stir constantly for 3 minutes to deglaze pot. Add garlic; cook 1 minute. Add wine and scrape up all browned bits from bottom. Stir in tomato paste and broth. 4. Return short ribs to pot. Add thyme, bay leaves, and carrots. 5. Seal lid and cook on High Pressure for 45 minutes. Natural pressure release for 15 minutes, then quick release remaining. 6. Remove ribs. Discard thyme and bay leaves. Set pot to Saute; whisk in cornstarch slurry and simmer sauce 2 minutes to thicken. Pour over ribs and serve over mashed potatoes.", "tags": "beef, braised, pressure-cooker, weekend-dinner", "source": "Classic", "nutritionData": "{\"calories\": 570, \"protein\": 32.0, \"carbs\": 12.0, \"fat\": 38.0}"},
  {"name": "Instant Pot Corned Beef and Cabbage", "category": "Instant Pot", "description": "Classic St. Patrick's Day corned beef with cabbage, potatoes, and carrots cooked under pressure.", "servings": 6, "prepTime": 10, "cookTime": 90, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"flat-cut corned beef brisket with spice packet\"}, {\"qty\": \"1 lb\", \"name\": \"baby potatoes halved\"}, {\"qty\": \"1\", \"name\": \"small head green cabbage cut into wedges\"}, {\"qty\": \"3\", \"name\": \"large carrots cut into chunks\"}, {\"qty\": \"1\", \"name\": \"medium onion quartered\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"2 cups\", \"name\": \"low-sodium beef broth\"}, {\"qty\": \"2 cups\", \"name\": \"water\"}, {\"qty\": \"1 tbsp\", \"name\": \"whole grain mustard for serving\"}, {\"qty\": \"1 tsp\", \"name\": \"black peppercorns\"}]", "instructions": "1. Rinse corned beef brisket under cold water. Place fat-side up in the Instant Pot. 2. Add onion, garlic, peppercorns, and spice packet from the brisket. Pour in beef broth and water. 3. Seal lid and cook on High Pressure for 75 minutes. Natural pressure release for 15 minutes, then quick release remaining pressure. 4. Remove brisket to a cutting board and tent with foil. Add potatoes and carrots to the hot broth in the pot. 5. Seal lid and cook on High Pressure for 3 minutes. Quick release. Remove potatoes and carrots. Add cabbage wedges and cook on Saute for 5 minutes until tender. 6. Slice corned beef against the grain. Arrange on platter with vegetables. Serve with whole grain mustard.", "tags": "beef, one-pot, pressure-cooker, st-patricks-day", "source": "Classic", "nutritionData": "{\"calories\": 670, \"protein\": 42.0, \"carbs\": 18.0, \"fat\": 44.0}"},
  {"name": "Instant Pot Refried Beans", "category": "Instant Pot", "description": "Creamy homemade refried beans from dry pinto beans, pressure-cooked to perfection.", "servings": 8, "prepTime": 5, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2 cups\", \"name\": \"dried pinto beans rinsed\"}, {\"qty\": \"1\", \"name\": \"medium onion diced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic minced\"}, {\"qty\": \"5 cups\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1 tsp\", \"name\": \"chili powder\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"2 tbsp\", \"name\": \"lard or bacon fat or butter\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}]", "instructions": "1. Rinse dried pinto beans and add to Instant Pot. Add onion, garlic, cumin, chili powder, and water. Do not add salt yet (salt toughens beans). 2. Seal lid and set vent to Sealing. Cook on High Pressure for 45 minutes. Natural pressure release for 15 minutes, then slowly release any remaining pressure. 3. Drain beans, reserving 1 cup of cooking liquid. 4. Set pot to Saute. Add lard or butter. Add drained beans in batches and mash with a potato masher or immersion blender to desired consistency. 5. Add reserved cooking liquid as needed to reach desired texture (creamy but thick). Season with salt and pepper. 6. Serve as a side dish, in burritos, tacos, or as a dip with chips.", "tags": "vegan-adaptable, Mexican, beans, pressure-cooker, meal-prep", "source": "Classic", "nutritionData": "{\"calories\": 215, \"protein\": 10.0, \"carbs\": 33.0, \"fat\": 5.0}"},
  {"name": "Instant Pot Dulce de Leche", "category": "Instant Pot", "description": "Luscious caramel dulce de leche made effortlessly in the Instant Pot from sweetened condensed milk.", "servings": 16, "prepTime": 5, "cookTime": 60, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"(14 oz) cans sweetened condensed milk\"}, {\"qty\": \"2 cups\", \"name\": \"water for the pot\"}]", "instructions": "1. Remove labels from sweetened condensed milk cans. Do not open the cans. 2. Pour 2 cups water into the Instant Pot. Place trivet inside. Set unopened cans on their sides on the trivet. Make sure cans are completely covered by water — add more water if needed. 3. Seal lid and cook on High Pressure for 40 minutes. Allow full natural pressure release (about 20 minutes). 4. Carefully remove cans using tongs — they will be very hot. Allow cans to cool completely at room temperature before opening, at least 1 hour. 5. Once completely cool, open cans to reveal golden-brown dulce de leche. 6. Stir until smooth. Use as a dip, spread, ice cream topping, or filling for cakes and cookies. Store in refrigerator up to 2 weeks.", "tags": "dessert, caramel, pressure-cooker, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 159, \"protein\": 4.0, \"carbs\": 27.0, \"fat\": 4.0}"},
  {"name": "Instant Pot Whole Chicken", "category": "Instant Pot", "description": "Juicy and tender whole roasted chicken cooked in the pressure cooker in just 25 minutes.", "servings": 5, "prepTime": 10, "cookTime": 45, "difficulty": "Medium", "ingredientsJson": "[{\"qty\": \"1\", \"name\": \"whole chicken 4-5 lbs\"}, {\"qty\": \"1 cup\", \"name\": \"low-sodium chicken broth\"}, {\"qty\": \"1\", \"name\": \"lemon quartered\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic smashed\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2 tbsp\", \"name\": \"butter softened\"}, {\"qty\": \"1 tsp\", \"name\": \"garlic powder\"}, {\"qty\": \"1 tsp\", \"name\": \"onion powder\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"dried rosemary\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1/2 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}]", "instructions": "1. Pat whole chicken dry inside and out. Mix softened butter with garlic powder, onion powder, paprika, rosemary, salt, and pepper. Rub seasoned butter all over the outside of the chicken and under the breast skin. 2. Stuff the cavity with lemon quarters, garlic, and thyme sprigs. 3. Set Instant Pot to Saute (High). Heat olive oil and sear chicken breast-side down for 3 minutes until golden. Flip and sear 2 minutes more. Remove chicken. 4. Add chicken broth and deglaze bottom of pot. Place trivet inside and set chicken breast-side up on trivet. 5. Seal lid and cook on High Pressure for 25 minutes (for a 4-lb chicken; add 5 minutes for 5-lb). Natural release for 15 minutes, then quick release remaining. 6. Verify internal temperature reaches 165°F in the thickest part of the thigh. For crispy skin, broil in oven for 3-5 minutes. Rest 10 minutes before carving.", "tags": "chicken, pressure-cooker, meal-prep, gluten-free", "source": "Classic", "nutritionData": "{\"calories\": 490, \"protein\": 52.0, \"carbs\": 2.0, \"fat\": 29.0}"},
  {"name": "Instant Pot Vegetable Broth", "category": "Instant Pot", "description": "Rich, golden vegetable broth made from kitchen scraps and aromatics in just 30 minutes.", "servings": 8, "prepTime": 10, "cookTime": 45, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"2\", \"name\": \"large onions quartered\"}, {\"qty\": \"3\", \"name\": \"carrots rough chopped\"}, {\"qty\": \"3\", \"name\": \"stalks celery with leaves rough chopped\"}, {\"qty\": \"1\", \"name\": \"whole head garlic halved crosswise\"}, {\"qty\": \"2\", \"name\": \"medium tomatoes quartered\"}, {\"qty\": \"1 cup\", \"name\": \"mushroom stems or sliced mushrooms\"}, {\"qty\": \"1\", \"name\": \"bunch parsley stems included\"}, {\"qty\": \"4 sprigs\", \"name\": \"fresh thyme\"}, {\"qty\": \"2\", \"name\": \"bay leaves\"}, {\"qty\": \"1 tbsp\", \"name\": \"olive oil\"}, {\"qty\": \"1 tsp\", \"name\": \"whole peppercorns\"}, {\"qty\": \"1 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"10 cups\", \"name\": \"cold water\"}]", "instructions": "1. Set Instant Pot to Saute. Heat olive oil and add onions, carrots, and celery. Cook 5 minutes until lightly browned to develop flavor. 2. Add garlic (cut-side down), tomatoes, and mushrooms; cook 2 minutes more. Hit Cancel. 3. Add parsley, thyme, bay leaves, peppercorns, salt, and water. Do not fill above the two-thirds max fill line. 4. Seal lid and set vent to Sealing. Cook on High Pressure for 30 minutes. Allow natural pressure release for 15 minutes, then quick release any remaining. 5. Strain broth through a fine mesh strainer into a large bowl, pressing solids to extract all liquid. Discard solids. 6. Taste and adjust salt. Cool and store in the refrigerator up to 5 days or freeze up to 3 months.", "tags": "vegan, broth, make-ahead, gluten-free, pressure-cooker", "source": "Classic", "nutritionData": "{\"calories\": 15, \"protein\": 0.0, \"carbs\": 3.0, \"fat\": 0.0}"},
  {"name": "Instant Pot Apple Butter", "category": "Instant Pot", "description": "Smooth, spiced apple butter made in the pressure cooker in a fraction of traditional stovetop time.", "servings": 32, "prepTime": 15, "cookTime": 30, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"5 lbs\", \"name\": \"apples peeled cored and quartered (such as Fuji or Gala)\"}, {\"qty\": \"3/4 cup\", \"name\": \"granulated sugar\"}, {\"qty\": \"1/2 cup\", \"name\": \"brown sugar packed\"}, {\"qty\": \"1/4 cup\", \"name\": \"apple cider\"}, {\"qty\": \"2 tsp\", \"name\": \"ground cinnamon\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground nutmeg\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground cloves\"}, {\"qty\": \"1/4 tsp\", \"name\": \"ground allspice\"}, {\"qty\": \"1 tsp\", \"name\": \"vanilla extract\"}, {\"qty\": \"1 tbsp\", \"name\": \"fresh lemon juice\"}]", "instructions": "1. Add quartered apples, granulated sugar, brown sugar, apple cider, cinnamon, nutmeg, cloves, and allspice to the Instant Pot. Stir to combine. 2. Seal lid and cook on High Pressure for 8 minutes. Quick release the pressure. 3. Use an immersion blender to puree the apple mixture directly in the pot until completely smooth. 4. Set pot to Saute and cook uncovered, stirring frequently, until apple butter thickens to desired consistency, about 20 minutes. 5. Stir in vanilla extract and lemon juice. Taste and adjust sweetness with additional sugar if needed. 6. Pour into sterilized jars and refrigerate up to 3 weeks, or process in a hot water bath for shelf-stable storage.", "tags": "condiment, apple, pressure-cooker, make-ahead", "source": "Classic", "nutritionData": "{\"calories\": 45, \"protein\": 0.0, \"carbs\": 11.0, \"fat\": 0.0}"},
  {"name": "Instant Pot Carnitas", "category": "Instant Pot", "description": "Crispy Instant Pot pork carnitas with citrus and spices, pressure-cooked then broiled for the perfect crunch.", "servings": 8, "prepTime": 10, "cookTime": 50, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"3 lbs\", \"name\": \"boneless pork butt cut into 2-inch cubes\"}, {\"qty\": \"1\", \"name\": \"large onion sliced\"}, {\"qty\": \"4 cloves\", \"name\": \"garlic sliced\"}, {\"qty\": \"1\", \"name\": \"lemon juiced\"}, {\"qty\": \"1\", \"name\": \"orange juiced\"}, {\"qty\": \"1/2 cup\", \"name\": \"water\"}, {\"qty\": \"1 tsp\", \"name\": \"smoked paprika\"}, {\"qty\": \"1 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ancho chile powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"chipotle chile powder\"}, {\"qty\": \"1/2 tsp\", \"name\": \"dried oregano\"}, {\"qty\": \"1.5 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"1 tsp\", \"name\": \"black pepper\"}, {\"qty\": \"\", \"name\": \"1-2 tbsp coconut oil for crisping\"}]", "instructions": "1. Place sliced onions and garlic in the bottom of the Instant Pot. Mix pork cubes with lemon juice, spices, salt, and pepper in a bowl. 2. Place seasoned pork on top of onions. Pour orange juice and water around the pork. 3. Seal lid and cook on High Pressure for 35 minutes. Allow natural pressure release for 10 minutes, then quick release remaining. 4. Remove pork to a cutting board and shred with two forks. Set pot to Saute and reduce remaining liquid to concentrate flavor. 5. Heat coconut oil in a large cast iron skillet over high heat. Spread shredded pork in a single layer and cook undisturbed until crispy and browned, about 3-4 minutes. Drizzle some concentrated broth over the crispy meat. 6. Serve in corn tortillas with salsa, cilantro, and diced onion.", "tags": "Mexican, pork, gluten-free, pressure-cooker", "source": "https://twosleevers.com/pulled-pork-carnitas/", "nutritionData": "{\"calories\": 400, \"protein\": 38.0, \"carbs\": 3.0, \"fat\": 27.0}"},
  {"name": "Instant Pot Hummus From Scratch", "category": "Instant Pot", "description": "Ultra-creamy homemade hummus made from dried chickpeas cooked in the pressure cooker, smoother than any can.", "servings": 8, "prepTime": 10, "cookTime": 50, "difficulty": "Easy", "ingredientsJson": "[{\"qty\": \"1 cup\", \"name\": \"dried chickpeas\"}, {\"qty\": \"4 cups\", \"name\": \"water for cooking\"}, {\"qty\": \"1/2 tsp\", \"name\": \"baking soda\"}, {\"qty\": \"3 tbsp\", \"name\": \"tahini\"}, {\"qty\": \"3 tbsp\", \"name\": \"fresh lemon juice\"}, {\"qty\": \"2 cloves\", \"name\": \"garlic\"}, {\"qty\": \"1/2 tsp\", \"name\": \"ground cumin\"}, {\"qty\": \"1/2 tsp\", \"name\": \"kosher salt\"}, {\"qty\": \"\", \"name\": \"2-4 tbsp ice cold water to blend\"}, {\"qty\": \"2 tbsp\", \"name\": \"extra virgin olive oil for serving\"}, {\"qty\": \"\", \"name\": \"paprika and parsley for garnish\"}]", "instructions": "1. Add dried chickpeas, 4 cups water, and baking soda to the Instant Pot (baking soda helps chickpeas get ultra-creamy). 2. Seal lid and cook on High Pressure for 40 minutes. Allow natural pressure release for 10 minutes, then quick release remaining. 3. Drain chickpeas but reserve 1/2 cup cooking liquid. While still warm, add chickpeas to a food processor or blender. 4. Add tahini, lemon juice, garlic, cumin, and salt. Process 1 minute. 5. With motor running, drizzle in ice cold water 1 tbsp at a time until hummus reaches a smooth, fluffy consistency. Taste and adjust lemon and salt. 6. Transfer to a serving bowl. Drizzle with olive oil and sprinkle paprika and fresh parsley.", "tags": "vegan, gluten-free, high-protein, pressure-cooker", "source": "Classic", "nutritionData": "{\"calories\": 145, \"protein\": 6.0, \"carbs\": 14.0, \"fat\": 8.0}"},
] as const;
